// 프로그래밍기능사 통합 정리서 마인드맵 (원본 PDF의 가지 2,581개와 메모 2,008개를 그대로 옮김)
// n: 요점에 붙은 메모 [종류, 내용]
window.MM = [{"n":0,"t":"11월 8일 기준 시험 안내","c":[{"t":"제1절 2026년 프로그래밍기능사 개편 총정리","c":[{"t":"Ⅰ 무엇이 바뀌었나","c":[{"t":"1. 명칭과 시행 시기","c":[{"t":"(1) 정보처리기능사에서 프로그래밍기능사로","c":[{"t":"① 2026.1.1 명칭 변경","n":[["설명","2026년 1월 1일(2026년 기능사 제1회)부터 자격 종목 명칭이 정보처리기능사에서 프로그래밍기능사로 바뀌었다."]]},{"t":"② 필기·실기 출제기준 개편","n":[["설명","필기·실기 출제기준이 함께 개편되었다. 이 책은 개편된 기준(2026.1.1~)에 맞춘 책이다."],["시험 포인트","기존 정보처리기능사 취득자는 프로그래밍기능사를 취득한 것으로 인정된다는 안내가 있으나, 비공식 자료(나무위키) 기반이므로 큐넷 공지로 최종 확인한다."],["쉬운 예","가게 이름과 메뉴가 함께 바뀐 것과 같다. 간판(명칭)만 바뀐 것이 아니라 파는 물건(시험 과목)도 코딩 중심으로 바뀌었다."]]}]},{"t":"(2) 왜 바뀌었나","c":[{"t":"① 계산·정의 위주 한계","n":[["설명","기존 시험은 계산·정의 위주여서 실제 코드 작성 능력을 검증하기에 부족하다는 지적이 있었다."]]},{"t":"② 코딩·SQL 실무 중심 재편","n":[["설명","그래서 코딩과 SQL 등 프로그래밍 실무 중심으로 과목이 재편되었다."]]}]}]},{"t":"2. 필기 과목의 변화","c":[{"t":"(1) 폐지된 과목","c":[{"t":"① 전자계산기일반 등 4과목 폐지","n":[["설명","전자계산기일반, 패키지활용, PC운영체제, 정보통신일반 4과목이 폐지되었다."]]},{"t":"② 옛 교재·기출 활용 곤란","n":[["설명","따라서 이 과목들 중심의 옛 교재·기출은 현재 시험 준비에 그대로 쓰기 어렵다."]]}]},{"t":"(2) 새 과목","c":[{"t":"① 프로그래밍 언어 등 신규 4과목","n":[["설명","프로그래밍 언어, 응용SW기초기술, SQL 활용, 정보시스템 기초기술 4과목이다."]]},{"t":"② 필기 편 4과목 순서 구성","n":[["설명","이 책의 필기 편은 위 4과목 순서대로 구성되어 있다."],["실제 사례","개편 안내 자료들은 2026년부터 직접 코딩 능력이 실기의 핵심이라고 설명한다. 그래서 이 책의 실기 편은 C·Java·Python 코드 읽기, 빈칸 채우기, 디버깅, SQL 작성에 큰 비중을 둔다."]]}]}]}]},{"t":"Ⅱ 시험 구성과 합격 기준","c":[{"t":"1. 필기시험","c":[{"t":"(1) 시험 형태","c":[{"t":"① 4지택일 60문항·60분","n":[["설명","객관식 4지택일형 60문항, 시험시간 60분이다."]]},{"t":"② 모의고사 과목당 15문항","n":[["설명","이 책의 필기 모의고사는 4과목을 15문항씩 균등하게 배분해 구성했다."]]}]},{"t":"(2) 합격 기준","c":[{"t":"① 60점 이상(36문항) 합격","n":[["설명","100점 만점에 60점 이상(60문항 중 36문항 이상)이면 합격이다."]]},{"t":"② 과락 없이 총점 판정","n":[["설명","과목별 과락 없이 총점으로 판정하는 것으로 구성했다. 세부 기준은 큐넷 공고로 확인한다."],["시험 포인트","필기 문항 수·과목별 배분은 자료마다 표기가 다르다. 이 책은 60문항·60분·4과목 균등 배분을 기준으로 삼았다."]]}]}]},{"t":"2. 실기시험","c":[{"t":"(1) 시험 형태","c":[{"t":"① 기초프로그래밍 실무·1시간 30분","n":[["설명","과목명은 기초프로그래밍 실무이며, 시험시간은 1시간 30분이다."]]},{"t":"② 작업형·필답형 병행 대비","n":[["설명","명목상 작업형(코딩 실기)이나, 실제로는 필답형에 가깝게 진행된다는 설명도 있다. 두 경우 모두 대비할 수있도록 코드 작성과 서술형을 함께 연습한다."]]}]},{"t":"(2) 합격 기준","c":[{"t":"① 실기 60점 이상 합격","n":[["설명","100점 만점에 60점 이상이면 합격이다."]]},{"t":"② 모의고사 12문항·90분","n":[["설명","이 책의 실기 모의고사는 12문항, 100점 만점, 90분 기준으로 구성했다."],["쉬운 예","필기는 \"개념을 알고 있는지\" 보는 필기시험이고, 실기는 \"직접 해 보는지\" 보는 운전면허 기능시험과 같다."]]}]}]}]}]},{"t":"제2절 2026년 11월 8일 현재 시험 일정과 막판 학습 전략","c":[{"t":"Ⅰ 2026년 제4회 시험 일정","c":[{"t":"1. 필기에서 실기까지","c":[{"t":"(1) 이미 지나간 일정","c":[{"t":"① 필기 접수 8/24~27·시험 9/16~21","n":[["설명","필기 원서접수 8월 24일~27일, 필기시험 9월 16일~21일이었다."]]},{"t":"② 필기 합격 발표 10/7","n":[["설명","필기 합격자 발표는 10월 7일이었다."]]}]},{"t":"(2) 앞으로 남은 일정","c":[{"t":"① 실기시험 11/14~12/2","n":[["설명","실기시험은 11월 14일~12월 2일에 시행된다."]]},{"t":"② 최종 발표 12/11(또는 12/18)","n":[["설명","최종 합격자 발표는 12월 11일(일부 자료는 12월 18일로 안내)이다."]]}]}]},{"t":"2. 접수 현황","c":[{"t":"(1) 접수 기간","c":[{"t":"① 실기 접수 10/12~15·빈자리 11/8~9","n":[["설명","큐넷 일정표 기준 실기 원서접수는 10월 12일~15일, 실기 빈자리 접수는 11월 8일~9일이다."]]},{"t":"② 11/9 마감 표기 차이","n":[["설명","일부 자료는 실기 접수가 11월 9일까지라고 표기하므로 차이가 있다."]]}]},{"t":"(2) 오늘(11월 8일) 해야 할 일","c":[{"t":"① 큐넷 빈자리 접수 확인","n":[["설명","아직 접수하지 못했다면 큐넷에서 빈자리 접수 가능 여부를 즉시 확인한다."]]},{"t":"② 시험장·수험표·신분증 확인","n":[["설명","접수를 마쳤다면 시험장·시간·준비물(수험표, 신분증)을 확인한다."],["시험 포인트","일정은 지역·종목별로 다를 수 있다. 위 날짜는 공개 자료 기준이므로 큐넷에서 최종 확인한다."],["시험 포인트","실기는 11월 14일~12월 2일 중 본인에게 배정된 날짜에 치른다. D-6은 가장 이른 날짜를 기준으로 한 계산이므로 수험표의 일자를 확인한다."]]}]}]}]},{"t":"Ⅱ 실기 D-6 학습 전략","c":[{"t":"1. 우선순위","c":[{"t":"(1) 반드시 잡을 것","c":[{"t":"① 모의고사 5회 90분 실전 풀이","n":[["설명","실기 모의고사 5회분을 시간(90분)을 재고 풀어 본다."]]},{"t":"② 디버깅 오답 유형 반복","n":[["설명","실전 디버깅 연습문제집에서 틀린 유형(조건식·인덱스·형변환·초기화)을 반복한다."]]}]},{"t":"(2) 마지막 점검","c":[{"t":"① SQL DDL·DML·GROUP BY 손코딩","n":[["설명","SQL의 DDL·DML·GROUP BY/HAVING·서브쿼리를 직접 손으로 써 본다."]]},{"t":"② 테스트 용어 한 줄 암기","n":[["설명","테스트 용어(블랙박스·화이트박스·통합 방식·형상 관리)를 한 줄씩 암기한다."]]}]}]},{"t":"2. 시험 당일 요령","c":[{"t":"(1) 시간 배분","c":[{"t":"① 출력 예측 우선·서술형 키워드","n":[["설명","쉬운 출력 예측 문제부터 풀고 서술형은 키워드 위주로 쓴다."]]},{"t":"② 마지막 10분 오탈자 점검","n":[["설명","마지막 10분은 오탈자·세미콜론·자료형 점검에 쓴다."]]}]},{"t":"(2) 답안 작성 요령","c":[{"t":"① SQL 대문자·세미콜론 정확히","n":[["설명","SQL은 키워드를 대문자로, 세미콜론까지 정확히 쓴다."]]},{"t":"② 들여쓰기·빈칸 없이 부분점수","n":[["설명","코드는 들여쓰기를 지켜 쓰고, 모르는 문제도 부분 점수를 노려 빈칸 없이 채운다."],["쉬운 예","실기는 운동경기의 마지막 주 훈련과 같다. 새 기술을 배우기보다 이미 가진 기술을 실수 없이 쓰는 연습이 점수를 만든다."]]}]}]}]}]}],"k":"시작하기"},{"n":1,"t":"프로그래밍 언어","c":[{"t":"제1절 프로그래밍 언어의 기초와 구조적 프로그래밍","c":[{"t":"Ⅰ 프로그래밍 언어의 개념과 분류","c":[{"t":"1. 프로그래밍 언어의 정의와 언어 번역 방식","c":[{"t":"(1) 프로그래밍 언어의 정의","c":[{"t":"① 사람-컴퓨터 명령용 인공언어","n":[["설명","프로그래밍 언어란 프로그래밍 언어란 사람이 컴퓨터에게 특정한 작업을 수행하도록 명령을 내리기 위하여 사용하는 인공적으로 만들어진 언어를 말한다. 사람은 자연어(한국어, 영어 등)로 사고하지만 컴퓨터는 0과 1로 구성된 기계어만을 직접 이해할 수 있기 때문에, 사람의 의도를 컴퓨터가 처리할 수 있는 형태로 옮겨주는 매개체로서 프로그래밍 언어가 존재한다. 프로그래밍 언어는 문법(Syntax)과 의미(Semantics)로 구성되며, 정해진 문법 규칙에 따라 작성된 코드를 언어 번역 프로그램이 해석하거나 번역하여 컴퓨터가 실행할 수 있는 형태로 변환한다."],["쉬운 예","시험에서는 특정 프로그래밍 언어의 개발자, 개발 연도, 개발 목적을 짝짓는 문제가 자주 출제된다. 예를 들어 C언어는 1972년 미국 벨(Bell) 연구소의 데니스 리치(Dennis Ritchie)가 유닉스(UNIX) 운영체제를 개발할 목적으로 만든 시스템 기술용 언어이며, 하드웨어를 직접 제어할 수 있는 저수준 제어 능력과 이식성이 높은 고수준 문법을 동시에 갖추고 있어 시스템 프로그래밍과 응용 프로그래밍에 모두 활용된다는 점을 반드시 기억해야 한다."],["쉬운 예","예시: 동일한 덧셈 연산이라도 기계어는 이진수 명령 코드로, 어셈블리어는 ADD와 같은 니모닉 (mnemonic) 기호로, C나 Python과 같은 고급언어는 a = b + c 와 같이 사람이 읽기 쉬운 수식으로 표현된다. 시험에서는 저급언어와 고급언어의 예시를 구분하는 문제, 그리고 이식성·개발 생산성·실행 속도의 상대적 비교를 묻는 문제가 출제된다."]]},{"t":"② 컴파일러 전체 번역·목적프로그램","n":[["설명","컴파일러(Compiler) 컴파일러는 고급언어로 작성된 원시 프로그램(Source Program) 전체를 한꺼번에 읽어들여 기계어로 이루어진 목적 프로그램(Object Program)을 생성하는 번역 프로그램이다. 번역 과정에서 어휘 분석, 구문 분석, 의미 분석, 코드 최적화, 코드 생성의 단계를 거치며, 번역이 완료된 후에는 실행 파일을 독립적으로 실행할수 있다. 대표적인 컴파일러 언어로는 C, C++, Java(바이트코드로 컴파일) 등이 있다. 컴파일러 방식은 전체를 한 번에 번역하기 때문에 실행 속도가 빠르지만, 번역에 시간이 걸리고 오류가 발생하면 전체 번역이 중단된다는 특징이 있다."],["시험 포인트","인터프리터는 원시 프로그램을 한 줄(문장) 단위로 읽어 즉시 해석하고 실행하는 방식의 번역 프로그램이다. 컴파일 과정 없이 바로 실행되므로 프로그램 개발과 디버깅이 편리하지만, 실행할 때마다 매번 해석 과정을 거치기 때문에 컴파일러 방식보다 실행 속도가 느리다. 대표적인 인터프리터 언어로는 Python, JavaScript, 기본 BASIC 등이 있다. 시험에서는 컴파일러와 인터프리터의 차이를 비교하는 문제(번역 단위, 목적 프로그램 생성 여부, 실행 속도)가 자주 출제되므로 표로 정리하여 암기해 두어야 한다."]]}]},{"t":"(2) 절차적(구조적) 프로그래밍 언어","c":[{"t":"① 절차적 언어 C·COBOL·FOR TRAN","n":[["설명","개념 절차적 프로그래밍 언어는 프로그램이 수행해야 할 절차(순서)를 함수와 문장의 나열로 기술하는 방식의 언어이다. 프로그램은 위에서 아래로 순차적으로 실행되는 것을 기본으로 하며, 필요한 경우 함수(부프로그램) 호출을 통해 특정 처리 단위를 반복적으로 사용한다. 대표적인 절차적 언어로는 C, COBOL, FORTRAN, BASIC, Pascal 등이 있다. 절차적 언어는 실행 순서를 명확하게 기술할 수 있어 알고리즘 구현에 적합하지만, 프로그램의 규모가 커질수록 데이터와 함수가 분리되어 있어 유지보수가 어려워지는 단점이 있다."]]},{"t":"② 객체지향 언어 속성+메서드 객체","n":[["설명","개념 객체지향 프로그래밍 언어는 현실 세계의 개체(대상)를 속성(데이터)과 메서드(동작)를 하나로 묶은 객체(Object) 단위로 모델링하여 프로그램을 구성하는 언어이다. 객체지향 언어의 세부 개념(캡슐화, 상속성, 다형성, 추상화)은 본 정리서 제3절에서 Java 언어와 함께 상세히 다룬다."],["시험 포인트","대표적인 객체지향 언어로는 Java, C++, Python, Smalltalk 등이 있다. 특히 Smalltalk는 1세대 순수 객체지향 언어로서 최초로 GUI 개념을 도입한 언어로 시험에 종종 출제된다. 객체지향 언어는 코드의 재사용성과 유지보수성이 높다는 장점이 있으나, 설계 단계에서의 학습 곡선이 높고 실행 시 처리 시간이 다소 지연될 수 있다는 단점이 있다."]]},{"t":"③ 스크립트 언어 인터프리터 즉시실행","n":[["설명","개념 스크립트 언어는 별도의 컴파일 과정 없이 인터프리터에 의해 해석되어 즉시 실행되는 경량 프로그래밍 언어를 말한다. 주로 웹 브라우저, 운영체제 셸, 응용 프로그램 내부의 자동화 작업에 사용된다."],["시험 포인트","대표적인 스크립트 언어로는 JavaScript, Python, PHP, Perl, 셸 스크립트(Shell Script) 등이 있다. 스크립트 언어는 코드 수정과 실행이 간편하여 생산성이 높지만, 컴파일 언어에 비해 실행 속도가 느린 편이다. 참고로 Python은 스크립트 언어이면서 동시에 객체지향 언어의 특성도 함께 가지고 있어 여러 관점에서 출제될 수 있음에 유의한다."]]}]}]}]},{"t":"Ⅱ 구조적 프로그래밍과 제어구조","c":[{"t":"1. 구조적 프로그래밍의 개념","c":[{"t":"(1) 정의와 등장 배경","c":[{"t":"① 순차·선택·반복 3구조, GOTO 배제","n":[["설명","구조적 프로그래밍의 정의 구조적 프로그래밍(Structured Programming)이란 순차, 선택, 반복의 세 가지 기본 제어구조만을 사용하여 프로그램을 작성하는 기법을 말한다. 프로그램의 흐름을 위에서 아래로 읽어 내려갈 수 있도록 논리적으로 구성함으로써, 프로그램의 가독성과 이해도를 높이고 유지보수를 쉽게 하는 것을 목표로 한다. 구조적 프로그래밍이 등장하기 이전의 프로그램은 GOTO문을 이용하여 프로그램의 실행 흐름을 임의의 위치로 자유롭게 이동시키는 방식이 널리 사용되었다. 그러나 GOTO문을 남용하면 프로그램의 흐름이 마치 실타래처럼 얽혀 이해하기 어려워지는데, 이를 스파게티 코드(Spaghetti Code)라고 부른다. 1968년 에츠허르 다익스트라(Edsger Dijkstra)가 발표한 논문 \"GOTO문은 해롭다(Go To Statement Considered Harmful)\"를 계기로 GOTO문의 사용을 최소화하고 순차·선택·반복의 세 가지 제어구조만으로 프로그램을 작성하자는 구조적 프로그래밍 방법론이 확립되었다."]]},{"t":"② 가독성·디버깅·협업 유리","n":[["설명","장점 구조적 프로그래밍은 프로그램의 흐름이 명확하여 코드의 가독성이 높고, 논리적인 오류를 찾기 쉬워 디버깅과 유지보수가 용이하다. 또한 하나의 입구와 하나의 출구를 갖는 모듈 단위로 프로그램을 나눌 수 있어 여러 사람이 동시에 개발하는 협업 개발에도 유리하다."],["시험 포인트","다만 복잡한 예외 처리나 다중 종료 조건을 표현할 때 GOTO문을 전혀 사용하지 않으면 오히려 코드가 길어지고 중복될 수 있다는 한계도 존재한다. 그러나 시험에서는 구조적 프로그래밍의 장점(가독성, 유지보수성 향상)을 묻는 문제가 압도적으로 많이 출제되므로 장점 위주로 암기하는 것이 효율적이다."]]}]},{"t":"(2) 순차 구조(Sequence Structure)","c":[{"t":"① 순차 구조 위→아래 실행","n":[["설명","개념 순차 구조는 프로그램에 작성된 명령문을 위에서 아래로, 작성된 순서 그대로 하나씩 실행하는 가장 기본적인 제어구조이다. 별도의 조건 판단이나 반복 없이 순서대로 실행되는 구조로서 모든 프로그램의 기본 골격이된다."],["쉬운 예","예를 들어 변수를 선언하고, 값을 입력받고, 계산을 수행한 뒤 결과를 출력하는 네 개의 문장이 순서대로 한 번씩 실행되는 프로그램은 전형적인 순차 구조에 해당한다."]]},{"t":"② 선택 구조 if·switch","n":[["설명","개념 선택 구조는 주어진 조건식의 참(True)과 거짓(False) 여부를 판단하여 서로 다른 실행 경로 중 하나를 선택하여 실행하는 구조이다. C언어의 if문, if~else문, switch문, Java의 if문과 switch문, Python의 if~elif~else문이 대표적인 선택 구조에 해당한다."],["쉬운 예","예를 들어 시험 점수가 60점 이상이면 \"합격\"을, 60점 미만이면 \"불합격\"을 출력하는 프로그램은 조건에 따라 서로 다른 문장을 실행하는 선택 구조의 대표적인 예시이다."]]},{"t":"③ 반복 구조 for·while","n":[["설명","개념 반복 구조는 주어진 조건이 만족하는 동안 또는 정해진 횟수만큼 특정 문장을 되풀이하여 실행하는 구조이다. C언어와 Java의 for문·while문·do~while문, Python의 for문·while문이 대표적인 반복 구조에 해당한다."],["쉬운 예","예를 들어 1부터 10까지의 합계를 구하는 프로그램에서 변수를 1부터 10까지 1씩 증가시키면서 누적 합을 계산하는 과정은 반복 구조의 전형적인 예이다. 순차·선택·반복의 세 구조는 서로 중첩되어 사용될 수 있으 며(예: 반복문 안에 선택문이 포함되는 경우), 시험에서는 짧은 코드를 보고 어떤 제어구조가 사용되었는지, 또는 그 실행 결과가 무엇인지를 묻는 문제가 출제된다."]]}]}]}]},{"t":"Ⅲ 변수와 자료형의 기본 개념","c":[{"t":"1. 변수와 상수","c":[{"t":"(1) 변수의 개념과 선언","c":[{"t":"① 변수 값 저장 메모리 공간","n":[["설명","변수의 정의"],["쉬운 예","변수(Variable)란 프로그램이 실행되는 동안 값을 저장하기 위하여 이름을 붙인 메모리 공간을 말한다. 변수를 사용하기 위해서는 먼저 어떤 종류의 값을 저장할 것인지(자료형)와 그 변수를 무엇이라고 부를 것인지(변수명)를 정하여 선언(Declaration)하는 과정이 필요하다. 예를 들어 C언어에서 int a; 라고 작성하면, 정수형 값을 저장할 수 있는 4바이트 크기의 메모리 공간을 확보하고 그 공간에 a라는 이름을 붙이는 것이다."],["시험 포인트","변수명은 영문자, 숫자, 밑줄(_)로 구성하되 숫자로 시작할 수 없으며, 언어에서 이미 예약하여 사용하고 있는 예약어(keyword)는 변수명으로 사용할 수 없다. 대소문자를 구분하는 언어(C, Java, Python 등) 에서는 num과 Num을 서로 다른 변수로 인식한다는 점도 시험에서 자주 다루어진다."]]},{"t":"② 상수 #define·const·f inal","n":[["설명","상수(Constant) 상수는 프로그램 실행 중에 값이 변하지 않는 데이터를 말한다. C언어에서는 #define 전처리기 지시자나 const 키워드를 이용하여 상수를 선언하며, Java에서는 final 키워드를 사용한다."],["쉬운 예","리터럴은 소스 코드 안에 직접 표기된 값 자체를 의미한다. 예를 들어 int a = 10; 이라는 문장에서 10이 바로 리터럴이다. 리터럴은 정수 리터럴(10), 실수 리터럴(3.14), 문자 리터럴('A'), 문자열 리터럴(\"Hello\") 등으로 구분된다."]]}]},{"t":"(2) 정수형과 실수형","c":[{"t":"① 정수형 int·short·long","n":[["설명","정수형(Integer Type)"],["쉬운 예","정수형은 소수점이 없는 숫자를 저장하는 자료형이다. C언어에서는 short(2바이트), int(4바이트), long(4 또는 8바이트) 등으로 세분화되며, 각 자료형은 저장 가능한 값의 범위가 다르다. 예를 들어 4바이트 int형은 부호를 포함하여 약 -21억 ~ +21억(-2^31 ~ 2^31-1) 범위의 값을 표현할 수 있다."]]},{"t":"② 문자형 char","n":[["설명","문자형(Character Type)"],["쉬운 예","문자형은 하나의 문자를 저장하는 자료형으로, C언어에서는 char(1바이트)로 선언한다. 문자는 내부적으로 아스키(ASCII) 코드값, 즉 정수로 저장되기 때문에 문자형 변수는 정수처럼 연산에 사용될 수도 있다. 예를 들어 문자 'A'의 아스키 코드값은 65이며, 'A' + 1은 'B'의 아스키 코드값인 66이 된다."],["시험 포인트","논리형은 참(True)과 거짓(False) 두 가지 값만을 가지는 자료형이다. Java에서는 boolean 키워드로, Python에서는 bool 자료형(True/False)으로 지원한다. C언어(C99 이전)에는 별도의 논리형이 없어 0을 거짓, 0이 아닌 값을 모두 참으로 취급한다는 점이 시험에 자주 출제되는 포인트이다."]]},{"t":"③ char 1·int 4·double 8바이트","n":[["설명","C언어 기본 자료형의 크기 일반적인 32비트/64비트 환경(운영체제 및 컴파일러에 따라 달라질 수 있음)을 기준으로 char는 1바이트, short는 2바이트, int는 4바이트, long은 4바이트 또는 8바이트, float는 4바이트, double은 8바이트의 메모리를 차지한다. sizeof() 연산자를 사용하면 특정 자료형이나 변수가 차지하는 바이트 수를 직접 확인할 수있다."],["시험 포인트","자료형이 차지하는 바이트 수가 클수록 표현할 수 있는 값의 범위가 넓어진다. n바이트로 표현할수 있는 부호 있는 정수의 범위는 -2^(8n-1) ~ 2^(8n-1)-1 이며, 이 공식을 이용하여 1바이트(-128~127), 2 바이트(-32768~32767), 4바이트의 표현 범위를 유도하는 문제가 출제될 수 있으므로 계산 원리를 이해해 두어야 한다."]]}]}]}]},{"t":"Ⅳ 수 체계와 진법 변환","c":[{"t":"1. 진법의 개념과 표현","c":[{"t":"(1) 다양한 진법","c":[{"t":"① 2·8·16진법, 2진 3자리=8진 1자리","n":[["설명","2진법, 8진법, 16진법 컴퓨터 내부는 전기 신호의 On/Off 두 가지 상태만을 구분할 수 있기 때문에 모든 데이터를 2진수(Binary, 0과 1)로 표현하고 처리한다. 다만 2진수는 자릿수가 길어져 사람이 읽기 불편하므로, 이를 간략히 표기하기 위한 보조 수단으로 8진법(0~7의 8개 숫자를 사용)과 16진법(0~9와 A~F를 사용하는 16개의 기호를 사용) 이 함께 사용된다. 2진수 3자리는 8진수 1자리와 정확히 대응되고(2^3=8), 2진수 4자리는 16진수 1자리와 정확히 대응된다 (2^4=16). 이 성질을 이용하면 2진수를 3자리씩 묶어 8진수로, 4자리씩 묶어 16진수로 간편하게 변환할 수있다."]]},{"t":"② 10진수 나눗셈 나머지 변환","n":[["설명","10진수를 다른 진법으로 변환"],["쉬운 예","10진수를 2진수(또는 8진수, 16진수)로 변환할 때는 변환하고자 하는 진법의 기수로 몫이 0이 될 때까지 나누고, 그 나머지를 아래에서 위로(즉 마지막에 구한 나머지부터 거꾸로) 나열하면 된다. 예를 들어 10진수 13을 2진수로 변환하면, 13÷2=6...1, 6÷2=3...0, 3÷2=1...1, 1÷2=0...1이 되어 나머지를 거꾸로 나열한 1101이 정답이 된다."],["쉬운 예","2진수, 8진수, 16진수를 10진수로 변환할 때는 각 자릿수에 해당 진법의 자릿값(기수의 거듭제곱)을 곱하여 모두 더하면 된다. 예를 들어 2진수 1101은 1×2³ + 1×2² + 0×2¹ + 1×2⁰ = 8+4+0+1 = 13(10진수) 이 된다. 시험에서는 이러한 상호 변환 계산 문제가 매우 자주 출제되므로 나눗셈과 자릿값 계산 원리를 정확히 숙지해야 한다."]]}]},{"t":"(2) 보수(Complement)의 개념","c":[{"t":"① 1의 보수 반전, 2의 보수 +1","n":[["설명","1의 보수와 2의 보수 컴퓨터에서 음수를 표현하기 위하여 보수 개념을 사용한다. 2진수에서 1의 보수는 각 비트를 0은 1로, 1은 0으로 뒤집어(반전시켜) 구하며, 2의 보수는 1의 보수를 구한 후 그 결과에 1을 더하여 구한다."],["쉬운 예","현대 컴퓨터는 음수를 표현할 때 2의 보수 방식을 표준으로 사용하는데, 이는 덧셈 회로만으로 뺄셈 연산까지 수행할 수 있어 하드웨어 구조를 단순화할 수 있기 때문이다. 예를 들어 5-3의 연산을 5+(-3)으로 바꾸어 -3을 2의 보수로 표현한 뒤 덧셈 연산만으로 처리할 수 있다."]]},{"t":"② 보수 변환 절차","n":[["설명","변환 절차"],["쉬운 예","예를 들어 8비트 환경에서 +5는 00000101로 표현된다. 이 값을 2의 보수로 변환하면 -5를 표현할수 있는데, 먼저 1의 보수를 구하면 11111010이 되고, 여기에 1을 더하면 11111011이 되어 이것이 -5를 나타내는 2진수가 된다."],["시험 포인트","시험에서는 특정 2진수의 1의 보수와 2의 보수를 구하는 간단한 계산 문제, 또는 보수를 사용하는 목적(뺄셈의 덧셈화)을 묻는 개념 문제가 출제된다."]]}]}]}]},{"t":"Ⅴ 문자 인코딩 체계","c":[{"t":"1. 문자 코드의 개념과 종류","c":[{"t":"(1) 아스키(ASCII) 코드","c":[{"t":"① ASCII 7비트 128자, 'A'=65","n":[["설명","아스키 코드의 개념 아스키(ASCII, American Standard Code for Information Interchange) 코드는 영문 알파벳, 숫자, 특수문자, 제어문자를 7비트(128가지)로 표현하는 가장 기본적인 문자 코드 체계이다. 컴퓨터는 문자를 그대로 저장하는 것이 아니라 각 문자에 대응하는 아스키 코드값(정수)으로 변환하여 저장한다. 대문자 'A'의 아스키 코드값은 65이며, 알파벳 순서대로 1씩 증가하여 'B'는 66, 'Z'는 90이 된다. 소문자 'a' 의 아스키 코드값은 97이다. 대문자와 소문자 사이에는 정확히 32의 차이가 있다는 규칙도 함께 기억해 두면 문자 연산 문제를 빠르게 풀 수 있다."]]},{"t":"② 유니코드 전 세계 문자 통일","n":[["설명","유니코드의 필요성 아스키 코드는 128가지 문자만 표현할 수 있어 영어 이외의 언어(한글, 한자, 일본어 등)를 표현하는 데 한계가 있다. 이를 해결하기 위하여 전 세계 모든 문자를 하나의 통일된 코드 체계로 표현하고자 만들어진 것이 유니코드이다."],["실제 사례","유니코드는 보통 2바이트(16비트) 이상을 사용하여 문자를 표현하며, 한글의 모든 글자를 포함하여전 세계 대부분의 문자를 하나의 코드 체계 안에서 표현할 수 있다는 장점이 있다. UTF-8, UTF-16 등은 유니코드를 실제로 저장할 때 사용하는 대표적인 인코딩 방식이다."]]}]},{"t":"(2) C언어에서의 문자 처리","c":[{"t":"① C char형 = 아스키 정수값","n":[["설명","char형과 아스키 코드"],["실제 사례","C언어의 char형 변수는 실제로는 1바이트 정수를 저장하는 것과 같아서, 문자 리터럴 'A'를 char형 변수에 저장하면 내부적으로는 65라는 정수값이 저장된다. 이 때문에 char형 변수는 정수형 변수처럼 산술연 산에 사용될 수 있다."],["쉬운 예","예를 들어 소문자를 대문자로 변환하고 싶을 때 문자에서 32를 빼는 연산('a'-32 = 'A')을 이용할 수있으며, 이는 아스키 코드값의 규칙적인 배열 구조를 활용한 전형적인 예이다."]]},{"t":"② Java char 유니코드 2바이트","n":[["설명","Java의 char형 Java의 char형도 유니코드 문자 하나를 저장하며 내부적으로 정수 코드값을 갖는다는 점은 C언어와 유사하다. 다만 Java는 유니코드를 기본으로 채택하여 2바이트로 문자를 표현한다는 차이가 있다."],["쉬운 예","Python에서는 ord() 함수로 문자를 아스키(유니코드) 코드값으로 변환할 수 있고, chr() 함수로 코드값을 다시 문자로 변환할 수 있다. 예를 들어 ord('A')는 65를 반환하고, chr(65)는 'A'를 반환한다."]]}]}]}]},{"t":"Ⅵ 알고리즘과 순서도","c":[{"t":"1. 알고리즘의 개념과 조건","c":[{"t":"(1) 알고리즘의 정의","c":[{"t":"① 알고리즘 문제해결 절차","n":[["설명","알고리즘이란"],["쉬운 예","알고리즘(Algorithm)이란 주어진 문제를 해결하기 위한 처리 절차나 방법을 순서대로 명확하게 정의한 것을 말한다. 프로그래밍 언어로 프로그램을 작성하기에 앞서, 문제를 해결하는 논리적인 절차를 먼저 알고리즘으로 설계하는 것이 일반적인 소프트웨어 개발 순서이다. 예를 들어 \"1부터 100까지의 합을 구하라\"는 문제가 주어졌을 때, 이를 어떤 순서로 계산할 것인지를 글이나 그림으로 미리 표현한 것이 알고리즘이다."],["시험 포인트","좋은 알고리즘이 갖추어야 할 다섯 가지 조건으로 입력(0개 이상의 입력이 존재), 출력(1개 이상의 결과가 반드시 존재), 명확성(각 단계의 명령이 모호하지 않고 명확해야 함), 유한성(정해진 단계 후에는 반드시 종료되어야 함), 유효성(각 단계가 실행 가능해야 함)이 있다. 이 다섯 가지 조건 중 하나라도 만족하지 못하면 올바른 알고리즘이라 할 수 없다는 점이 시험에서 자주 다루어진다."]]},{"t":"② 자연어·의사코드 표현","n":[["설명","자연어와 의사코드(Pseudocode)"],["실제 사례","알고리즘은 자연어(일상 언어)로 서술할 수도 있으나, 문장이 길어지고 모호해질 수 있다는 단점이 있다. 이를 보완하기 위하여 프로그래밍 언어와 유사한 형식이지만 특정 언어의 문법에 얽매이지 않는 의사코드 (Pseudocode)로 알고리즘을 표현하는 방법이 널리 사용된다. 의사코드는 실제 컴파일이 되지는 않지만, 알고리즘의 논리적 흐름을 프로그래밍 언어로 옮기기 직전 단계의 설계 도구로 매우 유용하다."]]}]},{"t":"(2) 순서도의 기본 기호","c":[{"t":"① 타원 단말·사각 처리·마름모 판단","n":[["설명","단말, 처리, 판단 기호 순서도에서 타원(또는 둥근 사각형)은 프로그램의 시작과 끝(단말, Terminal)을 나타내고, 직사각형은 데이터의 처리(연산, 대입 등)를 나타내며, 마름모는 조건을 판단하여 흐름을 분기하는 판단(Decision) 기호를 나타낸다. 평행사변형은 데이터의 입력이나 출력을 나타내는 기호이며, 화살표로 표시되는 흐름선은 각 기호들 사이의 처리 순서(실행 흐름)를 나타낸다. 순서도는 반드시 하나의 시작점과 하나 이상의 종료점을 가져야 하며, 흐름선은 위에서 아래로, 또는 왼쪽에서 오른쪽으로 자연스럽게 읽히도록 작성하는 것이 원칙이다."]]},{"t":"② 순차 처리 순서도 예","n":[["설명","단순 순차 처리 예"],["쉬운 예","예를 들어 두 수를 입력받아 합을 구하고 출력하는 알고리즘은 시작(단말) → 두 수 입력(입출력) → 합계 계산(처리) → 결과 출력(입출력) → 종료(단말)의 순서로 순서도를 작성할 수 있다."]]}]}]}]},{"t":"Ⅶ 스택과 큐의 기본 개념","c":[{"t":"1. 스택(Stack)","c":[{"t":"(1) 스택의 개념과 동작 원리","c":[{"t":"① 스택 LIFO, push·pop·top","n":[["설명","스택의 정의 스택은 데이터를 한쪽 끝에서만 넣고 빼는 제한적인 선형 자료구조로, 가장 나중에 저장한 데이터를 가장 먼저 꺼내는 후입선출(LIFO, Last In First Out) 구조를 갖는다. 마치 접시를 쌓아 올린 뒤 맨 위에서부터 하나씩 꺼내 쓰는 모습에 비유할 수 있다. 스택에 데이터를 저장하는 연산을 push(삽입)라 하고, 스택에서 데이터를 꺼내는 연산을 pop(삭제)이라 한다. 데이터가 저장되고 삭제되는 위치를 top(스택의 맨 위)이라고 하며, top 위치의 값만 접근할 수 있다는 점이 스택의 가장 중요한 제약이다."]]},{"t":"② 함수 호출 복귀주소 저장","n":[["설명","함수 호출과 되돌아가기 프로그램에서 함수가 다른 함수를 호출할 때, 호출한 위치(복귀 주소)를 스택에 저장해 두었다가 함수 실행이 끝나면 스택에서 꺼내어 원래의 호출 위치로 되돌아간다. 이처럼 스택은 프로그램 실행 중 함수 호출 정보를 관리하는 데 핵심적으로 사용된다."],["쉬운 예","수식에서 괄호의 짝이 올바른지 검사하거나, 중위 표기법 수식을 후위 표기법으로 변환하여 계산하는 과정에서도 스택이 활용된다. 예를 들어 여는 괄호를 만나면 push하고 닫는 괄호를 만나면 pop하여 짝을 맞추는 방식으로 괄호의 균형을 검사할 수 있다."]]}]},{"t":"(2) 큐의 개념과 동작 원리","c":[{"t":"① 큐 FIFO, enqueue·de queue","n":[["설명","큐의 정의 큐는 데이터를 한쪽 끝(rear, 후단)에서 삽입하고 반대쪽 끝(front, 전단)에서 삭제하는 선형 자료구조로, 가장 먼저 저장한 데이터를 가장 먼저 꺼내는 선입선출(FIFO, First In First Out) 구조를 갖는다. 은행 창구나 매표소에서 먼저 줄을 선 사람이 먼저 서비스를 받는 것에 비유할 수 있다. 큐에 데이터를 저장하는 연산을 enqueue(삽입)라 하고, 큐에서 데이터를 꺼내는 연산을 dequeue(삭제)라한다. 스택과 달리 삽입과 삭제가 서로 다른 끝에서 이루어진다는 점이 큐의 가장 중요한 특징이다."]]},{"t":"② 큐 활용 인쇄·프로세스 대기열","n":[["설명","작업 대기열(버퍼) 큐는 프린터 인쇄 작업이나 운영체제의 프로세스 스케줄링과 같이, 여러 작업이 들어온 순서대로 처리되어야하는 대기열(버퍼)을 구현하는 데 활용된다. 먼저 요청한 작업이 먼저 처리되어야 하는 공정성을 보장할 수 있기 때문이다."],["시험 포인트","스택은 후입선출(LIFO), 큐는 선입선출(FIFO) 구조를 갖는다는 점이 두 자료구조의 근본적인 차이이며, 시험에서는 데이터를 순서대로 삽입한 뒤 삭제 연산을 수행했을 때 어떤 순서로 값이 출력되는지를 묻는 문제가 스택과 큐 각각에 대하여 자주 출제된다."]]}]}]}]},{"t":"Ⅷ 정렬과 탐색 알고리즘의 기초","c":[{"t":"1. 정렬 알고리즘","c":[{"t":"(1) 버블 정렬(Bubble Sort)","c":[{"t":"① 버블 정렬 인접 비교·교환","n":[["설명","동작 원리 버블 정렬은 인접한 두 원소를 반복적으로 비교하여, 앞의 값이 뒤의 값보다 크면 두 값의 위치를 서로 교환해 나가는 정렬 알고리즘이다. 한 번의 순회(pass)가 끝날 때마다 가장 큰 값이 마치 거품이 위로 떠오르듯 배열의 맨 뒤로 이동하게 되어 버블(거품) 정렬이라는 이름이 붙었다."],["시험 포인트","버블 정렬은 구현이 매우 단순하지만, 원소를 비교하고 교환하는 횟수가 많아 데이터의 개수가 늘어날수록 처리 속도가 크게 느려지는 비효율적인 정렬 방법으로 분류된다. 그럼에도 알고리즘의 기본 원리를 이해하기 위한 교육용 예제로 시험에 자주 등장한다."]]},{"t":"② 선택 정렬 최솟값 맨 앞 교환","n":[["설명","동작 원리 선택 정렬은 전체 데이터 중 가장 작은(또는 가장 큰) 값을 찾아 맨 앞의 위치와 교환하고, 그 다음으로 남은 데이터 중 가장 작은 값을 찾아 두 번째 위치와 교환하는 과정을 반복하는 정렬 알고리즘이다. 선택 정렬은 매 회전마다 교환이 최대 한 번만 일어나므로 교환 횟수 측면에서는 버블 정렬보다 유리할 수 있으나, 매번 남은 데이터 전체에서 최솟값을 찾아야 하므로 비교 횟수 자체는 여전히 많다는 한계가 있다."]]}]},{"t":"(2) 순차 탐색(Linear Search)","c":[{"t":"① 순차 탐색 정렬 불필요","n":[["설명","개념 순차 탐색은 배열의 맨 앞(또는 어느 한쪽 끝)에서부터 순서대로 하나씩 값을 비교하며 원하는 값을 찾는 가장 기본적인 탐색 방법이다. 데이터가 정렬되어 있지 않아도 사용할 수 있다는 장점이 있으나, 최악의 경우 배열의 모든 원소를 다 검사해야 할 수도 있다. 순차 탐색은 구현이 간단하여 데이터의 양이 적을 때 주로 사용되며, 데이터의 정렬 여부와 관계없이 항상 적용할 수 있는 범용적인 탐색 방법이라는 것이 가장 큰 장점이다."]]},{"t":"② 이진 탐색 정렬 필수·절반 축소","n":[["설명","동작 원리 이진 탐색은 반드시 정렬되어 있는 배열을 대상으로, 배열의 중앙에 위치한 값과 찾고자 하는 값을 비교하여 탐색 범위를 절반씩 줄여나가는 방법이다. 찾는 값이 중앙값보다 작으면 왼쪽 절반을, 크면 오른쪽 절반을 대상으로 같은 과정을 반복한다."],["시험 포인트","이진 탐색은 탐색 범위가 매 단계마다 절반으로 줄어들기 때문에 순차 탐색에 비하여 매우 빠른 속도로 원하는 값을 찾을 수 있다. 다만 탐색을 수행하기 전에 데이터가 반드시 정렬되어 있어야 한다는 전제 조건이 필요하며, 시험에서는 정렬된 배열에서 이진 탐색을 몇 번 수행해야 특정 값을 찾을 수 있는지를 손으로 직접 따라가며 계산하는 문제가 자주 출제된다."]]}]}]}]}]},{"t":"제2절 C 언어의 이해와 활용","c":[{"t":"Ⅰ C 언어 개요와 기본 구조","c":[{"t":"1. C 언어의 역사와 특징","c":[{"t":"(1) C 언어의 역사와 개발 목적","c":[{"t":"① 1972 벨연구소 데니스 리치","n":[["설명","개발 배경 C언어는 1972년 미국 벨(Bell) 연구소의 데니스 리치(Dennis Ritchie)에 의하여 개발된 시스템 기술용 (system description) 언어이다. 당초 유닉스(UNIX) 운영체제를 개발할 목적으로 만들어졌으며, 하드웨어를 세밀하게 제어할 수 있으면서도 사람이 이해하기 쉬운 고급언어의 문법을 함께 갖추고 있어 이후 대부분의 운영체제와 시스템 소프트웨어 개발의 기초가 되었다."],["시험 포인트","시험에서는 \"유닉스 운영체제 개발에 사용된 언어는 무엇인가\", \"C언어를 개발한 사람은 누구인 가\"와 같이 역사적 사실을 그대로 묻는 문제가 출제되므로 1972년, 벨 연구소, 데니스 리치, 유닉스라는 네 가지 키워드는 반드시 암기해 두어야 한다."]]},{"t":"② 시스템 프로그래밍·포인터·이식성","n":[["설명","논리적·구조적 시스템 프로그래밍 언어 C언어는 논리적이고 구조적인 시스템 프로그래밍 언어이다. 여기서 시스템 프로그램이란 운영체제(OS)와 같이 하드웨어를 직접 다루는 프로그램을 의미하며, C언어는 포인터를 통해 메모리 주소를 직접 다룰 수 있어 하드웨어 제어가 가능하다. 이 때문에 전자·전기공학 전공자들도 임베디드 시스템 개발을 위하여 C언어를 기본적으로 학습한다. 이식성이란 하나의 운영체제 환경에서 작성한 프로그램(소스 코드)을 다른 운영체제 환경으로 옮겨도 비교적 손쉽게 재사용할 수 있는 성질을 말한다. C언어로 작성된 코드는 표준 문법을 따르는 한 다양한 컴파일러와 운영체제 환경에서 다시 컴파일하여 사용할 수 있어 이식성이 높은 언어로 평가된다."]]}]},{"t":"(2) 기본 구조 (헤더파일과 main 함수)","c":[{"t":"① #include <stdio.h> 전처리","n":[["설명","헤더파일(Header File) C 프로그램은 일반적으로 #include <stdio.h>와 같은 전처리기 지시문으로 시작한다. stdio.h는 표준 입출 력(Standard Input/Output) 함수인 printf, scanf 등을 사용하기 위하여 반드시 포함해야 하는 헤더파일이다. #으로 시작하는 문장은 컴파일 이전에 전처리기(Preprocessor)가 먼저 처리한다."],["실제 사례","C 프로그램은 반드시 main() 함수를 포함해야 하며, 프로그램은 항상 main 함수의 첫 문장부터 실행을 시작한다. main 함수의 중괄호 { } 사이에 프로그램이 실제로 수행할 명령문들을 작성하며, 각 문장의 끝에는 세미콜론(;)을 붙여야 한다.\n#include <stdio.h>\nint main() {"]]},{"t":"② printf 서식 %d·%f·%c·%s","n":[["설명","printf 함수와 서식 지정자\n    printf 함수는 화면에 값을 출력하는 표준 출력 함수이다. 문자열 안에 서식 지정자(format specifier)를 사\n    용하여 변수의 값을 원하는 자료형으로 출력할 수 있다. %d는 정수(int), %f는 실수(float, double), %c는\n    문자(char), %s는 문자열(string), %x는 16진수를 출력할 때 사용하며, \\n은 줄바꿈을 의미하는 이스케이\n    프 문자이다.\n    scanf 함수는 키보드로부터 값을 입력받는 표준 입력 함수이다. scanf(\"%d\", &a);와 같이 변수 이름 앞에\n    반드시 주소 연산자 &를 붙여야 하는데, 이는 scanf 함수가 입력받은 값을 저장하기 위하여 해당 변수의 메모\n    리 주소를 알아야 하기 때문이다. 이 & 기호는 뒤에서 학습할 포인터 개념과 직접 연결되므로 반드시 함께 기\n    억해 두어야 한다.\n#include <stdio.h>\nint main() {\n      int a;\n      scanf(\"%d\", &a);   // & 는 주소 연산자\n      printf(\"입력값: %d\\n\", a);\n      return 0;\n}"]]}]}]}]},{"t":"Ⅱ 연산자","c":[{"t":"1. 산술연산자와 대입연산자","c":[{"t":"(1) 산술연산자(Arithmetic Operator)","c":[{"t":"① 산술연산자 + - * / %","n":[["설명","종류와 특징"],["쉬운 예","산술연산자에는 덧셈(+), 뺄셈(-), 곱셈(*), 나눗셈(/), 나머지(%)가 있다. 정수형끼리 나눗셈(/) 연산을 수행하면 소수점 이하는 버려지고 몫만 정수로 반환되며, 나머지 연산자(%)는 정수 나눗셈의 나머지 값을 반환한다. 예를 들어 7 / 2의 결과는 3이고, 7 % 2의 결과는 1이다."],["쉬운 예","정수형과 실수형이 함께 연산되면 정수형이 실수형으로 자동 형변환(묵시적 형변환)되어 계산 결과가 실수형으로 반환된다. 예를 들어 7 / 2.0의 결과는 3.5이다. 이처럼 서로 다른 자료형이 혼합 연산될 때 더 큰범위를 표현할 수 있는 자료형으로 자동 변환되는 규칙을 잘 이해해야 한다."]]},{"t":"② 대입연산자(=) 우→좌 대입","n":[["설명","대입연산자(=)"],["시험 포인트","대입연산자(=)는 오른쪽 값을 왼쪽 변수에 저장하는 연산자이다. 수학에서의 등호(같다)와는 의미가 다르므로 주의해야 하며, a = b는 \"a는 b와 같다\"가 아니라 \"b의 값을 a에 저장한다\"로 해석해야 한다."],["시험 포인트","복합대입연산자는 산술연산과 대입연산을 결합한 축약형 연산자로 +=, -=, *=, /=, %= 등이 있다. a += 5는 a = a + 5와 동일한 의미이며, 시험에서는 복합대입연산자의 결과값을 계산하는 문제가 자주 출제된다."]]}]},{"t":"(2) 증감연산자(전위형과 후위형)","c":[{"t":"① 전위 ++a 증가 후 사용","n":[["설명","전위 증감연산자(++a, --a)"],["쉬운 예","전위형은 변수 앞에 ++ 또는 --를 붙이는 형태로, 먼저 변수의 값을 1 증가(또는 감소)시킨 후 그 결과값을 해당 수식에 사용한다. 예를 들어 b = ++a;는 a의 값을 먼저 1 증가시킨 다음 그 값을 b에 대입한다."],["쉬운 예","후위형은 변수 뒤에 ++ 또는 --를 붙이는 형태로, 먼저 현재 변수의 값을 수식에 사용한 뒤 그 다음에 변수의 값을 1 증가(또는 감소)시킨다. 예를 들어 a가 5일 때 b = a++;를 수행하면 b에는 5가 대입되고 그 이후 a는 6이 된다. 전위형과 후위형의 실행 순서 차이를 코드로 분석하는 문제가 시험에 매우 자주 출제되므로 반드시 직접 손으로 여러 예제를 풀어보며 익혀야 한다."]]},{"t":"② 관계 참1·거짓0, 논리 && || !","n":[["설명","관계연산자(비교연산자) 관계연산자는 두 값의 크기를 비교하여 그 결과를 참(1)과 거짓(0)으로 반환하는 연산자로, ==(같다), !=(다르다), >(크다), <(작다), >=(크거나 같다), <=(작거나 같다)가 있다. C언어에서는 참을 1(또는 0이 아닌 값) , 거짓을 0으로 표현한다는 점에 유의해야 한다. 논리연산자는 여러 개의 조건식을 결합할 때 사용하며, &&(논리곱, AND), ||(논리합, OR), !(논리부정, NOT)이 있다. &&는 두 조건이 모두 참일 때만 참이 되고, ||는 두 조건 중 하나라도 참이면 참이 되며, !는 참과 거짓을 서로 반대로 바꾼다."]]}]},{"t":"(3) 비트연산자(Bitwise Operator)","c":[{"t":"① 비트연산자 & | ^ ~ << >>","n":[["설명","종류 비트연산자는 데이터를 비트(bit) 단위로 연산하는 연산자로, &(비트 AND), |(비트 OR), ^(비트 XOR, 배타적 논리합), ~(비트 NOT, 1의 보수), <<(왼쪽 시프트), >>(오른쪽 시프트)가 있다."],["쉬운 예","왼쪽 시프트(<<) 연산은 비트를 왼쪽으로 이동시키며 이는 2를 곱하는 것과 같은 효과를 가지고, 오른쪽 시프트(>>) 연산은 비트를 오른쪽으로 이동시키며 2로 나누는 것과 같은 효과를 가진다. 예를 들어 정수 3(이진수 011)을 왼쪽으로 1비트 이동(3 << 1)시키면 110, 즉 십진수 6이 된다."]]},{"t":"② 우선순위 단항>산술>관계>논리>대 입","n":[["설명","우선순위의 기본 원칙 하나의 수식에 여러 연산자가 함께 사용될 때는 정해진 우선순위에 따라 먼저 계산할 연산과 나중에 계산할 연산이 결정된다. 일반적으로 괄호 연산이 가장 먼저 수행되며, 그 다음으로 단항연산자(++, --, !) > 산술연 산자(*, /, % > +, -) > 관계연산자 > 논리연산자(&& > ||) > 대입연산자 순으로 우선순위가 낮아진다."],["시험 포인트","대부분의 이항연산자는 왼쪽에서 오른쪽으로 결합하여 계산되지만, 대입연산자와 단항연산자는 오른쪽에서 왼쪽으로 결합한다는 예외가 있다. 우선순위가 헷갈리는 복잡한 수식은 괄호를 사용하여 계산 순서를 명확히 지정하는 것이 안전하며, 시험에서는 우선순위를 몰라도 괄호의 중첩 구조만 정확히 따라가면 풀 수있는 문제가 많이 출제된다."]]}]}]}]},{"t":"Ⅲ 제어문 - 선택문과 반복문","c":[{"t":"1. 선택문","c":[{"t":"(1) if문과 if~else문","c":[{"t":"① if 조건 0 아니면 참","n":[["설명","if문의 구조 if문은 조건식이 참일 때만 중괄호 안의 문장을 실행하는 선택문이다. 조건식의 결과가 0이 아니면 참으로 간주되어 실행문을 수행하고, 0이면 거짓으로 간주되어 실행문을 건너뛴다. if~else문은 조건이 참일 때와 거짓일 때 서로 다른 문장을 실행하도록 구성한다. 조건이 세 가지 이상으로 나뉘는 경우에는 if~else if~else 형태로 조건을 연속하여 검사할 수 있다. 이때 조건은 위에서부터 순서대로 검사되며, 참인 조건을 처음 만나는 순간 해당 블록만 실행하고 나머지 조건은 검사하지 않는다는 점이 중요하다.\nint score = 85;\nif (score >= 90) {\n      printf(\"A학점\\n\");\n} else if (score >= 80) {\n      printf(\"B학점\\n\");   // 이 문장이 실행됨\n} else {\n      printf(\"C학점\\n\");\n}"]]},{"t":"② switch case·defaul t 다중선택","n":[["설명","switch문의 구조 switch문은 하나의 변수(또는 식)의 값에 따라 여러 case 중 하나를 선택하여 실행하는 다중 선택문이다. 변수의 값과 일치하는 case 레이블로 이동하여 그 이후의 문장들을 실행하며, 어떤 case와도 일치하지 않을 때는 default 레이블의 문장을 실행한다."],["시험 포인트","각 case 블록의 끝에 break문을 작성하지 않으면 해당 case 이후에 오는 다른 case의 문장까지 연속하여 실행되는 폴스루(fall-through) 현상이 발생한다. 따라서 특정 case만 실행하고 switch문을 빠져나오려면 각 case 블록 끝에 break문을 반드시 작성해야 한다. 시험에서는 break문을 의도적으로 누락시킨 코드를 제시하고 출력 결과를 묻는 함정 문제가 자주 출제된다.\nint x = 2;\nswitch (x) {"]]}]},{"t":"(2) while문과 do~while문","c":[{"t":"① while 선검사, do~while 최소 1회","n":[["설명","while문\n    while문은 조건식을 먼저 검사한 후, 조건이 참인 동안 반복하여 실행문을 수행하는 반복문이다. 조건을 먼저\n    검사하기 때문에 최초 조건이 거짓이면 반복문 내부의 문장이 단 한 번도 실행되지 않을 수 있다.\n    do~while문은 실행문을 먼저 한 번 수행한 뒤 조건식을 검사하는 반복문이다. 조건이 거짓이더라도 최초 한\n    번은 반드시 실행된다는 점이 while문과의 가장 큰 차이이며, 문장의 끝에 세미콜론(;)을 반드시 붙여야 한다.\nint i = 0;\nwhile (i < 5) {           // 조건을 먼저 검사\n      printf(\"%d \", i);\n      i++;\n}\nint j = 10;\ndo {                        // 조건이 거짓이어도 1회 실행\n      printf(\"%d \", j);\n      j++;\n} while (j < 5);"]]},{"t":"② for(초기식; 조건식; 증감식)","n":[["설명","for문의 구조 for문은 초기식, 조건식, 증감식을 한 줄에 함께 작성하여 반복 횟수가 정해진 반복 작업을 처리할 때 주로 사용하는 반복문이다. for(초기식; 조건식; 증감식) 형태로 작성하며, 초기식은 반복문 진입 전 한 번만 실행되고, 조건식은 매 반복마다 검사되며, 증감식은 각 반복이 끝날 때마다 실행된다."],["시험 포인트","for문 안에 또 다른 for문을 포함시키는 것을 중첩 반복문이라 하며, 구구단이나 별 찍기와 같이 행과 열로 구성된 2차원 형태의 데이터를 처리할 때 널리 사용된다. 시험에서는 중첩 반복문의 실행 횟수를 계산하는 문제나 별 찍기 패턴의 출력 결과를 묻는 문제가 자주 출제된다.\nfor (int i = 1; i <= 3; i++) {"]]},{"t":"③ break 가장 안쪽 반복만 탈출","n":[["설명","break문 break문은 현재 실행 중인 반복문(for, while, do~while)이나 switch문을 즉시 빠져나가는 명령이다. 중첩 반복문에서 break문은 자신이 속한 가장 안쪽의 반복문 하나만을 종료시킨다는 점에 유의해야 한다."],["시험 포인트","continue문은 반복문을 종료시키지 않고, 현재 반복 회차의 나머지 문장 실행을 건너뛴 뒤 조건 식(또는 증감식) 검사로 즉시 이동하여 다음 반복을 계속 진행하는 명령이다. break문과 continue문의 차이( 반복문 종료 여부)를 코드로 구분하는 문제가 시험에 자주 출제된다.\nfor (int i = 1; i <= 5; i++) {"]]}]}]}]},{"t":"Ⅳ 배열과 문자열","c":[{"t":"1. 배열(Array)","c":[{"t":"(1) 1차원 배열","c":[{"t":"① 배열 인덱스 0부터 arr[0]","n":[["설명","배열의 개념과 선언 배열은 같은 자료형의 여러 데이터를 하나의 이름으로 묶어 연속된 메모리 공간에 저장하는 자료구조이다.\nint arr[5];와 같이 선언하면 정수형 값을 5개 저장할 수 있는 연속된 메모리 공간이 확보되며, 각 원소는 배열\n명[인덱스] 형태로 접근한다. 배열의 인덱스(첨자)는 0부터 시작하므로 arr[0]이 첫 번째 원소, arr[4]가 마지\n막(다섯 번째) 원소가 된다는 점을 반드시 기억해야 한다.\n배열은 int arr[3] = {10, 20, 30}; 과 같이 선언과 동시에 초기화할 수 있다. 초기값의 개수가 배열 크기보다\n적으면 나머지 원소는 자동으로 0으로 초기화되며, 크기를 생략하고 int arr[] = {10, 20, 30};으로 선언하면\n초기값의 개수에 맞추어 배열 크기가 자동으로 결정된다."]]},{"t":"② 2차원 배열 arr[2][3] 6개","n":[["설명","2차원 배열의 개념 2차원 배열은 행(row)과 열(column)로 구성된 표 형태의 자료구조이다. int arr[2][3];과 같이 선언하면 2 행 3열, 즉 총 6개의 원소를 저장할 수 있으며, arr[행 인덱스][열 인덱스] 형태로 각 원소에 접근한다."],["쉬운 예","2차원 배열은 중첩 for문과 함께 사용하여 행과 열을 순서대로 순회하며 값을 입력하거나 출력하는 형태로 자주 활용된다. 예를 들어 성적표, 행렬 연산, 게임판 등을 표현할 때 2차원 배열이 사용된다.\nint arr[2][3] = {{1, 2, 3}, {4, 5, 6}};\nfor (int i = 0; i < 2; i++) {"]]}]},{"t":"(2) 문자 배열과 문자열의 표현","c":[{"t":"① 문자열 끝 널문자 '\\0'","n":[["설명","문자열의 저장 방식"],["쉬운 예","C언어에는 별도의 문자열 자료형이 없으며, 문자열은 문자(char)형 배열로 표현한다. 문자열의 끝에는 널문자(\\0, NULL 문자)가 자동으로 저장되어 문자열의 끝을 표시하는데, 이 널문자를 포함할 공간까지 고려하여 배열의 크기를 선언해야 한다. 예를 들어 \"Hello\"라는 5글자 문자열을 저장하려면 널문자를 포함하여 최소 6바이트 크기의 char 배열이 필요하다."]]},{"t":"② strlen·strcpy·strc at·strcmp","n":[["설명","string.h 헤더의 주요 함수 C언어는 string.h 헤더파일을 통하여 문자열을 처리하는 표준 함수를 제공한다. strlen()은 문자열의 길이( 널문자 제외)를 반환하고, strcpy()는 문자열을 다른 배열로 복사하며, strcat()은 두 문자열을 이어 붙이고, strcmp()는 두 문자열을 사전 순으로 비교한다."],["시험 포인트","strcmp(a, b) 함수는 두 문자열이 같으면 0을, a가 b보다 사전순으로 앞서면 음수를, a가 b보다 뒤에 있으면 양수를 반환한다. 문자열의 대소 비교는 == 연산자가 아니라 strcmp 함수를 사용해야 한다는 점이 자주 출제된다."]]}]}]}]},{"t":"Ⅴ 포인터","c":[{"t":"1. 포인터의 개념과 사용법","c":[{"t":"(1) 포인터 변수의 선언과 사용","c":[{"t":"① 포인터 = 메모리 주소 저장 변수","n":[["설명","포인터의 개념"],["쉬운 예","포인터(Pointer)란 메모리의 주소값을 저장하는 변수를 말한다. 일반 변수가 데이터 값 자체를 저장하는 것과 달리, 포인터 변수는 그 데이터가 저장되어 있는 메모리의 위치(주소)를 저장한다. 흔히 집 주소에 비유 하는데, 우편배달부가 주소를 보고 실제 집을 찾아가듯이 포인터는 저장된 주소를 통해 실제 데이터가 있는 메모리 공간을 찾아간다."],["쉬운 예","포인터 변수는 자료형 뒤에 별표(*)를 붙여서 선언한다. 예를 들어 int *p;는 정수형 변수의 주소를 저장할 수 있는 포인터 변수 p를 선언하는 것이며, 별표의 위치는 int* p;, int * p; 등으로 자유롭게 띄어 써도 문법상 문제가 없다.\nint a = 20;"]]},{"t":"② & 주소 연산자, * 간접참조","n":[["설명","& 연산자(주소 연산자)"],["쉬운 예","변수 앞에 &를 붙이면 그 변수가 저장되어 있는 메모리의 주소값을 의미한다. 예를 들어 &a는 변수 a가 저장된 메모리 주소를 말하며, 이 값을 포인터 변수에 대입하여 사용한다."],["실제 사례","포인터 변수 앞에 *를 붙이면 그 포인터가 가리키고 있는 주소에 저장된 실제 값을 의미하며, 이를 역참조(Dereference)라고 한다. 즉 포인터를 선언할 때의 *는 \"포인터 변수임\"을 나타내는 기호이고, 실행문에서 사용하는 *는 \"그 주소를 찾아가서 값을 읽거나 쓰라\"는 의미로 서로 다르게 해석되므로 문맥에 따라 구분해야 한다."]]}]},{"t":"(2) 포인터와 배열의 관계","c":[{"t":"① 배열명 = 배열 시작 주소","n":[["설명","배열명은 배열의 시작 주소 배열의 이름 자체는 그 배열이 저장된 메모리의 시작 주소를 의미한다. 따라서 int arr[3] = {10,20,30}; int *p = arr;와 같이 배열명을 포인터 변수에 대입하면, p는 arr[0]의 주소를 가리키게 된다. 다만 배열 이름 자체에 새로운 값을 대입하는 것은 원칙적으로 허용되지 않는다는 점에 유의해야 한다."],["쉬운 예","포인터에 정수를 더하면 자료형의 크기만큼 주소가 이동한다. 예를 들어 p가 int형 배열의 시작 주소를 가리키고 있을 때 *(p+1)은 arr[1]과 같은 값을 의미하며, *(p+2)는 arr[2]와 같은 값을 의미한다. 이처럼 포인터 연산으로 배열 원소에 접근하는 방식을 코드에서 분석할 수 있어야 한다.\nint arr[3] = {10, 20, 30};"]]},{"t":"② 미초기화 포인터 쓰레기값, NULL","n":[["설명","포인터 변수의 초기화 포인터 변수를 선언만 하고 초기화하지 않으면, 그 안에는 이전에 사용되던 임의의 값(쓰레기값, garbage value)이 들어있어 어떤 메모리 주소를 가리키고 있는지 알 수 없다. 이러한 초기화되지 않은 포인터에 값을 대입하면 예측할 수 없는 메모리 영역을 훼손하여 프로그램이 오작동하거나 심각한 오류가 발생할 수 있다. 안전한 포인터 사용을 위해서는 사용하기 전에 반드시 유효한 변수의 주소로 초기화하거나, 아직 가리킬 대상이 없다면 NULL로 초기화해 두어야 한다. NULL은 \"아무것도 가리키지 않음\"을 명시적으로 나타내며, 프로그램에서 포인터가 NULL인지 여부를 검사하여 잘못된 메모리 접근을 방지할 수 있다."]]}]}]}]},{"t":"Ⅵ 함수","c":[{"t":"1. 함수의 정의와 호출","c":[{"t":"(1) 함수의 구조","c":[{"t":"① 반환형·함수명·매개변수·본체","n":[["설명","함수의 구성 요소"],["쉬운 예","함수는 반환형(return type), 함수명, 매개변수(parameter) 목록, 그리고 함수 몸체(body)로 구성된다. 예를 들어 int add(int a, int b) { return a + b; }에서 int는 반환형, add는 함수명, (int a, int b)는 매개변수 목록이다. 함수는 특정 작업을 독립적인 단위로 분리하여 필요할 때마다 호출하여 재사용할 수 있도록 해준다."]]},{"t":"② Call by Value 복사, 주소 호출","n":[["설명","값에 의한 호출(Call by Value) 값에 의한 호출은 함수를 호출할 때 인자의 값을 복사하여 매개변수에 전달하는 방식이다. 함수 내부에서 매개변수의 값을 변경하더라도 원래 호출자의 변수에는 아무런 영향을 주지 않는다. C언어의 기본적인 매개변수 전달 방식이 값에 의한 호출이다. 주소에 의한 호출은 변수의 값이 아니라 그 변수가 저장된 메모리의 주소를 매개변수로 전달하는 방식이다. C언어에서는 포인터를 매개변수로 사용하여 이를 구현하며, 함수 내부에서 포인터를 역참조하여 값을 변경하면 호출자의 원본 변수 값도 함께 변경된다는 점이 값에 의한 호출과의 가장 큰 차이이다.\nvoid swap(int *x, int *y) {     // 주소를 전달받음\n     int temp = *x;\n     *x = *y;\n     *y = temp;\n}\nint main() {\n     int a = 1, b = 2;\n     swap(&a, &b);       // a와 b의 주소를 전달\n     printf(\"%d %d\\n\", a, b);   // 2 1 (값이 바뀜)\n}"]]}]},{"t":"(2) 지역변수와 전역변수","c":[{"t":"① 지역변수 블록 내, 전역변수 전체","n":[["설명","지역변수(Local Variable) 지역변수는 함수 또는 블록 내부에서 선언된 변수로, 그 함수(블록)가 실행되는 동안에만 존재하며 함수 실행이 끝나면 메모리에서 소멸된다. 지역변수는 선언된 함수(블록) 내부에서만 접근할 수 있다. 전역변수는 함수 바깥, 즉 모든 함수의 밖에서 선언된 변수로, 프로그램이 실행되는 동안 계속 유지되며 프로그램 내의 모든 함수에서 접근하여 사용할 수 있다. 지역변수와 전역변수의 이름이 같을 경우, 함수 내부에서는 지역변수가 우선적으로 사용되며 이를 변수의 은폐(shadowing)라고 한다."]]},{"t":"② static 정적변수 값 유지","n":[["설명","정적 변수의 개념 정적 변수는 static 키워드를 사용하여 선언하는 변수로, 지역변수처럼 함수 내부에서 선언되지만 전역변수처럼 프로그램이 종료될 때까지 메모리에 값이 유지된다는 특징을 가진다. 정적 변수는 함수가 호출될 때마다 초기화되지 않고, 이전 호출에서 저장된 값을 그대로 유지한 채 사용된다. 이 때문에 함수가 몇 번 호출되었는지 횟수를 세는 카운터 등을 구현할 때 정적 변수가 활용된다."]]}]}]}]},{"t":"Ⅶ 구조체와 공용체","c":[{"t":"1. 구조체(Structure)","c":[{"t":"(1) 구조체의 개념과 선언","c":[{"t":"① 구조체 서로 다른 자료형 묶음","n":[["설명","구조체의 필요성"],["쉬운 예","구조체는 서로 다른 자료형의 변수들을 하나의 묶음으로 관리하기 위한 사용자 정의 자료형이다. 배열이 동일한 자료형의 데이터만 묶을 수 있는 것과 달리, 구조체는 정수형, 문자형, 실수형 등 서로 다른 자료형을 하나의 이름으로 묶어 관리할 수 있다. 예를 들어 한 학생의 정보(이름-문자열, 학번-정수, 평균점수-실수)를 하나의 단위로 묶을 때 구조체가 사용된다."]]},{"t":"② 멤버 접근 . 과 -> 연산자","n":[["설명","멤버 접근 연산자"],["시험 포인트","구조체 변수의 각 멤버에 접근할 때는 마침표(.) 연산자를 사용한다. 만약 구조체를 가리키는 포인터 변수를 통해 멤버에 접근할 때는 화살표(->) 연산자를 사용하며, (*p).멤버명 과 p->멤버명 은 완전히 동일한 의미를 갖는다는 점이 시험에서 자주 다루어진다."]]}]},{"t":"(2) 공용체의 개념","c":[{"t":"① 공용체 union 메모리 공유","n":[["설명","공용체의 정의 공용체는 구조체와 문법이 유사하지만(union 키워드 사용), 모든 멤버가 동일한 메모리 공간을 공유하여 사용한다는 근본적인 차이가 있다. 즉 공용체는 그 안에서 가장 큰 자료형의 크기만큼만 메모리를 할당받으며, 한 순간에는 하나의 멤버 값만 유효하게 사용할 수 있다. 구조체는 선언된 모든 멤버 각각을 위한 별도의 메모리 공간을 확보하므로 전체 크기가 각 멤버 크기의 합(정 렬에 따른 추가 패딩 포함)이 되지만, 공용체는 모든 멤버가 같은 메모리를 나누어 쓰기 때문에 전체 크기가 가장 큰 멤버 하나의 크기와 같다는 점이 결정적인 차이이다."]]},{"t":"② 공용체 최대 멤버 크기만 할당","n":[["설명","메모리 절약 목적"],["쉬운 예","공용체는 여러 자료형 중 한 번에 하나만 사용하면 되는 상황에서 메모리를 절약하기 위한 목적으로 활용된다. 예를 들어 동일한 메모리 위치를 정수형으로도, 문자 배열로도 번갈아 해석해야 하는 저수준 프로그 래밍(임베디드 시스템 등)에서 자주 사용된다."],["시험 포인트","시험에서는 구조체와 공용체의 sizeof() 결과를 비교하는 문제, 그리고 \"여러 멤버가 메모리를 공유하는 자료형은 무엇인가\"와 같이 정의를 직접 묻는 문제가 출제된다."]]}]}]}]},{"t":"Ⅷ 전처리기와 매크로","c":[{"t":"1. 전처리기(Preprocessor )","c":[{"t":"(1) 전처리기의 개념","c":[{"t":"① # 지시문 컴파일 전 처리","n":[["설명","전처리기의 역할"],["실제 사례","전처리기는 실제 컴파일이 시작되기 전에 소스 코드를 먼저 가공하는 역할을 담당한다. 전처리기 지시문은 #으로 시작하며, #include, #define, #ifdef 등이 대표적이다."]]},{"t":"② #define PI 3.14 문자열 치환","n":[["설명","단순 매크로 상수\n#define PI 3.14와 같이 작성하면 소스 코드 안의 모든 PI라는 문자열이 컴파일 전에 3.14로 그대로 치환된\n다. 이는 값이 변하지 않는 상수를 정의하는 전통적인 방법이며, const 키워드와 달리 자료형을 갖지 않고 단순 문자열 치환이라는 점이 특징이다."],["실제 사례","#define SQUARE(x) ((x)*(x))와 같이 매개변수를 갖는 매크로 함수도 정의할 수 있다. 매크로 함수는 실제 함수 호출이 아니라 코드 자체가 그대로 치환되는 것이므로 실행 속도가 빠르지만, 괄호를 제대로 사용하지 않으면 의도하지 않은 계산 결과가 나올 수 있어 주의가 필요하다."]]}]},{"t":"(2) 조건부 컴파일 지시문","c":[{"t":"① #ifdef·#ifndef·#en dif","n":[["설명","#ifdef, #ifndef, #endif 조건부 컴파일은 특정 조건에 따라 소스 코드의 일부분만 선택적으로 컴파일하도록 지정하는 기능이다. #ifdef는 특정 매크로가 정의되어 있을 때, #ifndef는 정의되어 있지 않을 때 그 사이의 코드를 컴파일에 포함시키며, #endif로 조건부 블록을 끝맺는다. 조건부 컴파일은 서로 다른 운영체제나 개발 환경에 따라 다른 코드를 적용해야 할 때, 혹은 디버깅용 코드를 최종 배포판에서는 제외하고자 할 때 주로 활용된다."]]},{"t":"② 헤더 중복 #include 오류","n":[["설명","중복 포함 문제 여러 소스 파일에서 동일한 헤더파일을 중복으로 #include 하면 구조체나 함수가 중복 선언되어 컴파일 오류가 발생할 수 있다."],["실제 사례","헤더파일의 맨 앞부분에 #ifndef 헤더가드명 / #define 헤더가드명 을 작성하고 파일의 맨 끝에 #endif를 작성하면, 동일한 헤더파일이 여러 번 포함되더라도 실제로는 최초 한 번만 내용이 반영되도록 하여 중복 선언 오류를 방지할 수 있다."]]}]}]}]},{"t":"Ⅸ 다차원 배열과 포인터 배열","c":[{"t":"1. 포인터 배열과 배열 포인터","c":[{"t":"(1) 포인터 배열(Array of Pointers)","c":[{"t":"① 포인터 배열 int *p[3]","n":[["설명","개념"],["쉬운 예","포인터 배열이란 배열의 각 원소가 포인터 변수로 이루어진 배열을 말한다. 예를 들어 int *arr[3];이 라고 선언하면, 정수형 변수의 주소를 저장할 수 있는 포인터 3개로 이루어진 배열이 만들어진다. 각 배열 원소 arr[0], arr[1], arr[2]는 각각 서로 다른 정수형 변수의 주소를 가리킬 수 있다."]]},{"t":"② 배열 포인터 int (*p)[3]","n":[["설명","개념 배열 포인터는 배열 전체를 가리키는 포인터로, int (*p)[3];과 같이 괄호를 사용하여 선언한다. 포인터 배열이 여러 개의 포인터를 모아 놓은 배열인 것과 달리, 배열 포인터는 하나의 포인터가 배열 전체(예: 2차원 배열의 한 행)를 가리킨다는 차이가 있다."],["시험 포인트","int *p[3];은 포인터 배열(포인터 3개로 이루어진 배열)이고, int (*p)[3];은 배열 포인터(원소 3 개짜리 배열을 가리키는 포인터 1개)이다. 괄호의 위치에 따라 완전히 다른 의미가 된다는 점이 시험에서 혼동을 유발하는 대표적인 포인트이므로 괄호의 유무를 정확히 구분하여 암기해야 한다."]]}]},{"t":"(2) 2차원 배열 이름의 의미","c":[{"t":"① arr+1 = 다음 행 arr[1] 주소","n":[["설명","행 단위의 주소 2차원 배열 int arr[2][3];에서 배열의 이름 arr는 그 자체로 배열 포인터와 같은 성질을 가지며, arr가 가리키는 하나의 단위는 정수 하나가 아니라 정수 3개로 이루어진 하나의 행(row) 전체이다. 따라서 arr+1은 arr[0]의 다음 정수가 아니라, 다음 행인 arr[1]의 시작 주소를 가리키게 된다."],["실제 사례","2차원 배열은 문법상 이중 포인터(int **p)와 유사해 보이지만, 실제 메모리 구조와 연산 방식이 서로 다르므로 2차원 배열의 이름을 이중 포인터 변수에 직접 대입할 수 없다는 점에 유의해야 한다."]]},{"t":"② 매개변수 int arr[][3] 열 필수","n":[["설명","매개변수로 전달할 때의 표기 2차원 배열을 함수의 매개변수로 전달할 때는 void func(int arr[][3])과 같이 열의 크기를 반드시 명시해야한다. 행의 크기는 생략할 수 있지만 열의 크기를 생략하면 컴파일러가 각 행의 크기(간격)를 알 수 없어 올바르게 배열에 접근할 수 없기 때문이다."],["시험 포인트","시험에서는 포인터 배열과 배열 포인터의 선언 문법을 구분하는 문제, 그리고 2차원 배열의 이름이 가리키는 의미(행 단위 주소)를 이해하고 있는지를 묻는 문제가 출제될 수 있다."]]}]}]}]},{"t":"Ⅹ 동적 메모리 할당","c":[{"t":"1. malloc과 free","c":[{"t":"(1) 동적 메모리 할당의 개념","c":[{"t":"① 정적 할당 vs 실행 중 동적 할당","n":[["설명","정적 할당과 동적 할당의 차이 배열처럼 프로그램 작성 시 크기를 미리 정해 놓고 메모리를 확보하는 방식을 정적 할당이라 하며, 프로그램이 실행되는 도중에 필요한 만큼의 메모리 크기를 그때그때 결정하여 확보하는 방식을 동적 할당이라 한다. 동적 할당을 사용하면 실행 중에 입력되는 데이터의 개수에 맞추어 유연하게 메모리 크기를 조절할 수 있다는 장점이 있다. C언어에서는 stdlib.h 헤더파일에 선언된 malloc() 함수를 사용하여 힙(heap) 영역에 동적으로 메모리를 할당받는다. malloc(할당할 바이트 수)의 형태로 호출하며, 반환값은 할당된 메모리의 시작 주소를 가리키는 포인터(void형 포인터)이므로 사용하고자 하는 자료형의 포인터로 형변환하여 사용하는 것이 일반적이다."]]},{"t":"② free() 미호출 시 메모리 누수","n":[["설명","free() 함수의 필요성 malloc()으로 할당받은 메모리는 사용이 끝난 후 반드시 free() 함수를 호출하여 운영체제에 반환해 주어야한다. 이를 해제하지 않으면 프로그램이 종료될 때까지 해당 메모리를 계속 점유하게 되어, 불필요한 메모리 낭비인 메모리 누수(Memory Leak)가 발생한다. 특히 반복문 안에서 malloc()을 반복 호출하면서 free()를 누락하면, 프로그램이 실행되는 동안 메모리 사용량이 계속 증가하여 결국 시스템 자원이 고갈되고 프로그램이나 시스템 전체가 느려지거나 다운될 수 있다. 따라서 malloc()과 free()는 반드시 쌍으로 사용해야 한다는 원칙을 기억해야 한다.\n#include <stdlib.h>\nint *p = (int*)malloc(sizeof(int) * 5);    // 정수 5개 크기의 메모리 할당\nif (p != NULL) {\n      for (int i = 0; i < 5; i++) {\n          p[i] = i * 10;\n      }\n      free(p);   // 사용이 끝난 메모리 반드시 해제\n}"]]}]},{"t":"(2) 할당 실패에 대한 처리","c":[{"t":"① malloc 실패 시 NULL 반환","n":[["설명","NULL 반환 확인 malloc() 함수는 요청한 크기의 메모리를 확보할 수 없을 때 NULL을 반환한다. 따라서 malloc() 호출 직후에는 반환된 포인터가 NULL인지 여부를 반드시 확인한 뒤, NULL이 아닐 때만 그 메모리를 사용하도록 코드를 작성하는 것이 안전한 프로그래밍 습관이다. free()로 메모리를 해제한 뒤에도 그 포인터 변수 자체는 이전 주소값을 그대로 가지고 있는데, 이렇게 이미 해제된 메모리를 가리키고 있는 포인터를 댕글링 포인터라고 한다. 댕글링 포인터를 실수로 다시 참조(역참조)하면 예측할 수 없는 오류가 발생할 수 있으므로, free() 이후에는 포인터 값을 NULL로 다시 초기화해 두는 것이 안전하다."]]},{"t":"② calloc 0 초기화, realloc 크기변경","n":[["설명","calloc() 함수 calloc() 함수는 malloc()과 유사하게 동적으로 메모리를 할당하지만, 할당받은 메모리 공간을 자동으로 0으로 초기화해 준다는 차이가 있다. calloc(개수, 각 원소의 크기)의 두 개의 인자를 받는다는 점도 malloc()과 다른 부분이다. realloc() 함수는 이미 할당되어 있는 메모리의 크기를 늘리거나 줄이고자 할 때 사용한다. realloc(기존 포인터, 새로운 크기)의 형태로 호출하며, 기존 데이터는 가능한 범위 내에서 그대로 유지된 채 메모리 공간의 크기만 재조정된다는 특징이 있다. Ⅺ. 표준 라이브러리 함수의 활용"],["쉬운 예","math.h 헤더파일은 다양한 수학 연산 함수를 제공한다. sqrt(x)는 x의 제곱근을 실수형으로 반환하며, pow(x, y)는 x의 y제곱을 계산하여 반환한다. 예를 들어 pow(2, 3)은 8.0을 반환한다."],["쉬운 예","stdlib.h에는 문자열을 숫자로 변환하는 함수들이 포함되어 있다. atoi()는 문자열을 정수(int)로, atof()는 문자열을 실수(double)로 변환한다. 예를 들어 atoi(\"123\")은 정수 123을 반환한다."]]}]}]}]}]},{"t":"제3절 Java 언어와 객체지향 프로그래밍","c":[{"t":"Ⅰ 객체지향 프로그래밍의 개념","c":[{"t":"1. 객체지향 프로그래밍의 정의와 구성요소","c":[{"t":"(1) 객체지향 프로그래밍의 정의","c":[{"t":"① 객체 단위 모델링 프로그래밍","n":[["설명","객체지향의 기본 개념"],["쉬운 예","객체지향 프로그래밍(Object-Oriented Programming, OOP)이란 현실 세계에 존재하는 대상(개 체)을 하나의 객체(Object)로 모델링하고, 객체들 사이의 상호작용을 통해 프로그램을 구성하는 기법을 말한다. 예를 들어 자동차라는 개체는 색상, 속도, 연료량과 같은 명사적 속성과, 달리다·멈추다·시동을 걸다와 같은 동사적 행위를 함께 가지고 있는데, 이러한 명사(속성)와 동사(기능)를 하나의 단위로 묶어 프로그래밍하는 방식이 객체지향 프로그래밍이다."]]},{"t":"② 객체 속성+메서드, 클래스 설계도","n":[["설명","객체(Object) 객체는 데이터(속성, Attribute)와 이를 처리하는 동작(메서드, Method)으로 구성된 소프트웨어 모듈이다. 객체는 각각을 구분하기 위한 고유한 이름(식별성)을 가지며, 속성은 객체가 가지는 데이터 값을, 메서드는 객체가 메시지를 받아 수행하는 구체적인 연산을 의미한다. 클래스는 객체를 만들어내기 위한 설계도(틀)로서, 공통된 속성과 메서드를 갖는 객체들을 하나의 집합으로 묶어 정의한 것이다. 자동차를 예로 들면, 엔진·차체·바퀴 등 여러 부품(객체)을 조립하기 위한 전체 설계도가 클래스에 해당한다. 메시지는 객체와 객체 사이에 상호작용을 위하여 주고받는 전달 수단으로, 메시지를 받은 객체는 대응하는 메서드를 수행하여 그 결과를 반환한다."]]}]},{"t":"(2) 캡슐화와 정보은닉","c":[{"t":"① 캡슐화 데이터+메서드 묶음·은닉","n":[["설명","캡슐화(Encapsulation) 캡슐화란 데이터(속성)와 그 데이터를 처리하는 함수(메서드)를 하나로 묶는 것을 말한다. 마치 여러 성분의 약을 하나의 캡슐 안에 넣어 겉에서는 내부 성분을 볼 수 없게 하는 것처럼, 캡슐화를 통해 객체의 세부 구현 내용을 외부로부터 감춘다. 캡슐화된 객체는 변경이 발생하더라도 그 파급 효과가 적고, 다른 프로그램에서도 재사용하기 쉽다는 장점이 있다. 정보은닉은 캡슐화에서 가장 핵심이 되는 개념으로, 객체가 자신의 내부 정보(데이터)를 외부에 감추고, 자신이 제공하는 연산(메서드)을 통해서만 접근을 허용하는 것을 말한다. 이를 통해 외부의 잘못된 접근으로부터 데이터를 보호하고, 객체 내부 구현이 변경되더라도 외부에 미치는 영향을 최소화할 수 있다."]]},{"t":"② 추상화 핵심 특징만 추출","n":[["설명","추상화의 개념"],["쉬운 예","추상화란 객체의 세부적인 내용은 생략하고 공통적이고 중요한 속성만을 추출하여 표현하는 것을 말한다. 예를 들어 자동차를 운전할 때 엔진 내부의 연소 과정을 몰라도 \"시동을 걸고 액셀을 밟으면 차가 움직인 다\"는 사실만 알면 충분한 것처럼, 복잡한 내용을 단순화하여 표현하는 것이 추상화이다."]]},{"t":"③ 상속성 부모 속성·메서드 물려받음","n":[["설명","상속성의 개념"],["쉬운 예","상속성이란 이미 정의된 상위 클래스(부모 클래스)의 모든 속성과 연산(메서드)을 하위 클래스(자식 클래스)가 물려받아 사용하는 것을 말한다. 예를 들어 \"동물\"이라는 상위 클래스의 공통된 속성을 \"개\"와 \"고양 이\"라는 하위 클래스가 물려받고, 각자의 고유한 특징(개는 짖는다, 고양이는 야옹거린다)만 추가로 정의하면된다."]]},{"t":"④ 다형성 같은 메시지 다른 동작","n":[["설명","다형성의 개념"],["쉬운 예","다형성이란 동일한 이름의 메시지(메서드 호출)를 전달받더라도, 객체의 종류에 따라 서로 다르게 동작하는 성질을 말한다. 예를 들어 \"움직여라\"라는 동일한 명령을 자동차와 비행기에 내리면 자동차는 달리고 비행기는 날아가는 것처럼, 같은 이름의 기능이 객체에 따라 다른 결과를 만들어낸다."]]}]},{"t":"(3) 대표적인 객체지향 언어","c":[{"t":"① C++ C 확장 객체지향 언어","n":[["설명","C++ C++는 C언어에 객체지향 개념을 적용하여 확장한 언어로, 모든 문제를 객체로 모델링하여 표현한다. C언어 와의 호환성을 유지하면서도 클래스, 상속, 다형성과 같은 객체지향 기능을 함께 제공한다."],["시험 포인트","Smalltalk는 1세대 객체지향 프로그래밍 언어 중 하나로, 순수한 객체지향 언어이며 최초로 GUI( 그래픽 사용자 인터페이스)를 제공한 언어로 시험에 자주 출제된다. Java는 분산 네트워크 환경에 적용이 가능하고, 멀티스레드를 지원하여 여러 작업을 동시에 처리할 수 있으며, 운영체제 및 하드웨어에 독립적이어서 이식성이 매우 높은 대표적인 객체지향 언어이다."]]},{"t":"② OOP 장점 재사용, 단점 방법론 부족","n":[["설명","장점 상속을 통한 코드의 재사용과 시스템 확장이 용이하며, 자연적인 모델링을 통해 분석과 설계를 효율적으로 수행할 수 있다. 또한 사용자와 개발자 사이의 이해를 돕고, 객체 단위로 개발과 유지보수가 이루어지기 때문에 대형 프로그램의 작성과 관리가 상대적으로 쉬워진다. 객체지향 프로그래밍 구현을 지원하는 표준화된 분석 및 설계 방법론이 부족하며, 객체 간의 메시지 전달 등처리 과정이 복잡하여 실행 시간이 다소 지연될 수 있다. 특히 소규모 프로그램에서는 객체지향 방식이 오히려 개발 시간을 늘릴 수 있으며, 상속 관계를 잘못 설계하면 코드가 길어지고 성능이 저하될 수 있다."]]}]}]}]},{"t":"Ⅱ Java 언어의 기본","c":[{"t":"1. Java의 특징과 실행환경","c":[{"t":"(1) Java의 특징","c":[{"t":"① Write Once Run Anywhere 바이트코드","n":[["설명","플랫폼 독립성 Java는 \"Write Once, Run Anywhere\"라는 표어로 대표되는 플랫폼 독립적인 언어이다. 소스 코드를 컴파 일하면 특정 운영체제의 기계어가 아닌 바이트코드(Bytecode)로 변환되며, 이 바이트코드는 자바 가상 머신(JVM)이 설치된 어떠한 운영체제에서도 실행될 수 있다. Java는 처음부터 순수 객체지향 언어로 설계되어 캡슐화, 상속, 다형성을 완전히 지원하며, 하나의 프로그램 안에서 여러 작업을 동시에 처리할 수 있는 멀티스레드(Multi-thread) 기능도 기본적으로 제공한다."]]},{"t":"② JVM 바이트코드 해석 실행","n":[["설명","JVM(Java Virtual Machine) JVM은 자바 바이트코드를 해당 운영체제가 이해할 수 있는 기계어로 다시 해석하여 실행해 주는 가상 머신이다. JVM이 운영체제와 Java 프로그램 사이의 중개자 역할을 하기 때문에, 동일한 자바 프로그램(바이트 코드)이 Windows, Linux, macOS 등 서로 다른 운영체제에서도 수정 없이 실행될 수 있는 것이다. Java 소스 파일(.java)은 먼저 javac 컴파일러에 의해 바이트코드 파일(.class)로 컴파일되며, 이후 java 명령을 통해 JVM 위에서 바이트코드가 실행된다. 이 과정에서 컴파일과 인터프리터 실행 방식이 혼합되어 사용된다는 점이 Java의 실행 구조상 특징이다."]]}]},{"t":"(2) 클래스와 main 메서드","c":[{"t":"① public class·main 메서드","n":[["설명","클래스 선언"],["쉬운 예","Java의 모든 코드는 반드시 클래스 내부에 작성되어야 하며, 소스 파일의 이름은 public으로 선언된 클래스의 이름과 반드시 동일해야 한다. 예를 들어 public class Hello가 선언된 파일은 Hello.java라는 이름으로 저장되어야 한다."]]},{"t":"② println 줄바꿈, print 줄바꿈 없음","n":[["설명","System.out.println과 print\nSystem.out.println()은 값을 출력한 뒤 자동으로 줄바꿈을 하는 출력 명령이며, System.out.print()는 줄\n바꿈 없이 값을 출력한다. Java에서 문자열과 숫자를 + 연산자로 연결하면 자동으로 문자열이 결합되어 출\n력된다.\nJava의 기본 자료형에는 정수형(byte, short, int, long), 실수형(float, double), 문자형(char), 논리형 (boolean)이 있다. C언어와 달리 boolean 자료형이 명확히 존재하여 true와 false 값만을 가진다는 점이 특징이다."]]}]}]}]},{"t":"Ⅲ 클래스와 객체","c":[{"t":"1. 클래스 선언과 객체 생성","c":[{"t":"(1) 클래스의 정의","c":[{"t":"① class 필드+메서드 정의","n":[["설명","클래스 문법"],["실제 사례","클래스는 class 키워드를 사용하여 정의하며, 내부에 객체가 가질 속성(필드, field)과 동작(메서드, method)을 함께 작성한다. 클래스 자체는 설계도일 뿐이며, 실제로 메모리에 생성되어 사용되는 것은 그 클래스로부터 만들어진 객체(인스턴스, instance)이다."],["쉬운 예","필드는 객체가 가지는 데이터(속성)를 저장하는 변수이고, 메서드는 그 데이터를 처리하는 함수이다. 예를 들어 Car라는 클래스에 color(색상), speed(속도)라는 필드와 drive()(주행하다), stop()(멈추다)라는 메서드를 함께 정의할 수 있다."]]},{"t":"② new 연산자 객체 생성","n":[["설명","new 연산자를 이용한 객체 생성"],["쉬운 예","Java에서 클래스로부터 실제 객체(인스턴스)를 만들 때는 new 연산자를 사용한다. 예를 들어 Car myCar = new Car();라고 작성하면 Car 클래스의 설계도에 따라 새로운 객체가 메모리(힙 영역)에 생성되고, myCar라는 참조변수가 그 객체를 가리키게 된다."]]}]},{"t":"(2) 생성자(Constructor)","c":[{"t":"① 생성자 클래스명 동일·반환형 없음","n":[["설명","생성자의 개념 생성자는 객체가 new 연산자로 생성될 때 자동으로 호출되어 객체의 초기값을 설정하는 특수한 메서드이다. 생성자의 이름은 클래스의 이름과 반드시 동일해야 하며, 반환형을 별도로 작성하지 않는다. 클래스에 생성자를 별도로 작성하지 않으면 컴파일러가 매개변수 없는 기본 생성자를 자동으로 제공한다. 개발자가 필요에 따라 매개변수를 갖는 생성자를 여러 개 작성할 수도 있으며, 이는 이후 학습할 오버로딩의 대표적인 예시가 된다."]]},{"t":"② 접근제어자 public~priva te 4종","n":[["설명","접근제어자의 종류와 특징"],["시험 포인트","접근제어자는 클래스, 필드, 메서드에 대한 접근 범위를 지정하는 키워드이다. 접근 범위가 넓은 순서대로 public(모든 클래스, 모든 패키지에서 접근 가능) > protected(같은 패키지 및 상속 관계의 클래스에서 접근 가능) > default(아무런 제어자도 지정하지 않은 경우로, 같은 패키지 내에서만 접근 가능) > private(선언된 자신의 클래스 내부에서만 접근 가능) 순서로 정리된다. 이 접근 범위의 순서(public > protected > default > private)는 반드시 암기해 두어야 한다."],["실제 사례","접근제어자는 객체지향의 특징인 캡슐화와 정보은닉을 실제 코드로 구현하는 수단이다. 일반적으로 필드는 private으로 선언하여 외부에서 직접 접근하지 못하도록 감추고, 이를 조회하거나 변경하는 별도의\npublic 메서드(getter, setter)를 통해서만 접근을 허용하는 방식이 널리 사용된다."]]}]}]}]},{"t":"Ⅳ 상속과 다형성","c":[{"t":"1. 상속(Inheritance)","c":[{"t":"(1) 상속의 개념과 문법","c":[{"t":"① extends 키워드 상속","n":[["설명","extends 키워드 Java에서 클래스 간의 상속은 extends 키워드로 구현한다. class Child extends Parent { }와 같이 작성하면 Child(자식, 하위 클래스)는 Parent(부모, 상위 클래스)가 가진 public 및 protected 필드와 메서드를 물려받아 자신의 것처럼 사용할 수 있다."],["시험 포인트","부모 클래스의 private 멤버는 상속 자체가 되지 않으며, 자식 클래스에서 직접 접근할 수 없다. 또한 상위 클래스가 인터페이스(interface)로 선언된 경우에는 extends가 아니라 implements 키워드를 사용해야 한다는 점이 시험에서 함정 문제로 자주 등장한다."]]},{"t":"② 상속 장점 재사용, 깊으면 복잡","n":[["설명","장점 상속을 이용하면 공통된 속성과 기능을 여러 번 작성할 필요 없이 한 번만 정의하고 재사용할 수 있어 코드의 중복을 줄이고 유지보수성을 높인다. 부모 클래스의 코드가 변경되면 이를 상속받는 모든 자식 클래스에 영향을 미치므로, 상속 관계가 지나치게 깊거나 복잡해지면 오히려 코드 분석과 유지보수가 어려워질 수 있다."]]}]},{"t":"(2) 오버로딩(Overloading )","c":[{"t":"① 오버로딩 같은 이름·다른 매개변수","n":[["설명","오버로딩의 개념 오버로딩이란 같은 클래스 안에서 동일한 이름의 메서드를 매개변수의 개수, 자료형, 순서를 다르게 하여 여러 개 정의하는 것을 말한다. 메서드가 호출될 때 전달되는 인자의 개수와 자료형을 비교하여 그에 일치하는 메서드가 자동으로 선택되어 실행된다. 오버로딩이 성립하려면 메서드의 이름은 반드시 동일해야 하며, 매개변수의 개수·자료형·순서 중 하나 이상이 달라야 한다. 매개변수는 동일한데 반환형(리턴 타입)만 다른 경우는 오버로딩으로 인정되지 않으므로 반드시 유의해야 한다. 오버로딩은 컴파일 시점에 어떤 메서드를 호출할지가 결정되므로 정적 바인딩(Static Binding)이라고 한다.\nclass Calculator {\n      int add(int a, int b) { return a + b; }          // 정수 2개\n      double add(double a, double b) { return a+b; }   // 실수 2개\n      int add(int a, int b, int c) { return a+b+c; }   // 정수 3개\n}\n// add(5, 10)          -> 첫 번째 메서드 호출, 15\n// add(2.5, 4.5)       -> 두 번째 메서드 호출, 7.0"]]},{"t":"② 오버라이딩 상속 시 재정의","n":[["설명","오버라이딩의 개념 오버라이딩이란 상속 관계에 있는 자식 클래스가 부모 클래스로부터 물려받은 메서드를 자신의 클래스에 맞게 다시 정의(재정의)하여 덮어쓰는 것을 말한다. 오버라이딩은 반드시 상속 관계에서만 가능하다는 점이 오버로딩과의 근본적인 차이이다. 오버라이딩이 성립하려면 메서드의 이름, 매개변수, 반환형이 부모 클래스의 메서드와 완전히 동일해야 한다. 또한 자식 클래스에서 재정의할 때 접근 범위를 부모보다 더 좁게 설정할 수는 없다(같거나 더 넓게는 가능). 소스 코드에 @Override 애노테이션을 붙이면 컴파일러가 오버라이딩 조건을 만족하는지 검사해 주므로 오타나 실수를 예방할 수 있다. 오버라이딩은 실행(런타임) 시점에 어떤 메서드를 호출할지가 결정되므로 동적 바인딩(Dynamic Binding)이라고 한다.\nclass Parent {\n      void greet() { System.out.println(\"Hello from Parent\"); }\n}\nclass Child extends Parent {\n      @Override\n      void greet() { System.out.println(\"Hello from Child\"); }    // 재정의\n}\npublic class Main {\n      public static void main(String[] args) {\n          Parent p = new Child();   // 부모 타입 참조변수 = 자식 객체\n          p.greet();                 // \"Hello from Child\" 출력(동적 바인딩)\n      }\n}"]]},{"t":"③ 오버로딩 정적, 오버라이딩 동적","n":[["설명","공통점과 차이점 정리 오버로딩과 오버라이딩은 모두 다형성을 구현하는 방법이라는 공통점이 있으나, 오버로딩은 같은 클래스 내에서 메서드 이름은 같고 매개변수가 다르며 바인딩이 컴파일 시점에 정적으로 결정되는 반면, 오버라이딩은 상속 관계에서만 가능하고 메서드 이름·매개변수·반환형이 모두 동일하며 바인딩이 실행 시점에 동적으로 결정된다는 차이가 있다."],["시험 포인트","시험에서는 두 개념의 차이를 묻는 이론 문제뿐 아니라, 오버로딩·오버라이딩이 사용된 짧은 Java 코드를 제시하고 출력 결과를 추론하는 문제가 자주 출제된다. 특히 부모 타입 참조변수가 자식 객체를 가리키는 경우(다형성의 전형적인 형태) 어떤 메서드가 실행되는지를 정확히 분석하는 연습이 중요하다."]]}]},{"t":"(3) 인터페이스(Interface)","c":[{"t":"① 인터페이스 implements 규약","n":[["설명","인터페이스의 개념 인터페이스는 클래스가 반드시 구현해야 할 메서드의 목록만을 정의해 놓은 일종의 규약(약속)이다. 인터페이스 자체는 객체를 생성할 수 없으며, 이를 구현하는 클래스가 인터페이스에 선언된 모든 메서드의 내용을 반드시 작성해야 한다. 클래스가 인터페이스를 구현할 때는 extends가 아니라 implements 키워드를 사용한다. class Dog implements Animal { }과 같이 작성하며, 하나의 클래스가 여러 개의 인터페이스를 동시에 구현(다중 구현)할 수 있어 Java에서 다중 상속의 한계를 보완하는 역할을 한다."]]},{"t":"② abstract 추상클래스, 단일 상속","n":[["설명","추상클래스의 개념 추상클래스는 abstract 키워드로 선언되며, 하나 이상의 추상 메서드(구현부가 없는 메서드)를 포함할 수 있는 클래스이다. 추상클래스 역시 인터페이스와 마찬가지로 직접 객체를 생성할 수 없으며, 이를 상속받는 자식 클래스가 추상 메서드를 반드시 구현(오버라이딩)해야 한다. 인터페이스는 원칙적으로 메서드의 선언만을 포함하며 다중 구현이 가능한 반면, 추상클래스는 일반 메서드(구현부가 있는 메서드)와 추상 메서드를 함께 가질 수 있고 단일 상속만 가능하다는 차이가 있다. 두 개념 모두 공통 기능의 규격을 정의하고 하위 클래스에서 구체적으로 구현하도록 강제한다는 점에서 다형성 구현의 중요한 도구로 사용된다."]]}]}]}]},{"t":"Ⅴ Java의 예외 처리","c":[{"t":"1. 예외(Exception)의 개념","c":[{"t":"(1) 예외와 오류","c":[{"t":"① 예외 0 나눗셈·배열범위 초과","n":[["설명","예외의 정의 예외(Exception)란 프로그램 실행 중에 발생하는 비정상적인 상황으로, 배열의 범위를 벗어난 접근, 0으로 나누는 연산, 잘못된 형변환 등이 대표적이다. Java는 이러한 예외 상황을 프로그램이 강제 종료되지 않고 적절히 처리할 수 있도록 예외 처리 메커니즘을 제공한다. ArithmeticException(산술 연산 오류, 예: 정수를 0으로 나눔), ArrayIndexOutOfBoundsException(배 열의 범위를 벗어난 인덱스 접근), NullPointerException(참조되지 않은 객체에 접근) 등이 Java에서 자주 사용되는 대표적인 예외 클래스이다."]]},{"t":"② try~catch~finally 구조","n":[["설명","기본 구조 Java의 예외 처리는 try { 예외가 발생할 수 있는 코드 } catch(예외타입 e) { 예외 발생 시 처리할 코드 } 의구조로 작성한다. try 블록 안에서 예외가 발생하면 즉시 실행이 중단되고 해당 예외 타입과 일치하는 catch 블록으로 이동하여 예외를 처리한다. finally 블록은 예외의 발생 여부와 관계없이 항상 마지막에 실행되는 블록으로, 파일 닫기·자원 반납과 같이 반드시 수행되어야 하는 마무리 작업을 작성할 때 사용한다. Python의 try~except~else~finally와 개념적으로 유사하지만, Java에는 else 블록이 없다는 차이가 있다.\npublic class Main {\n      public static void main(String[] args) {\n          try {\n              int result = 10 / 0;   // ArithmeticException 발생\n          } catch (ArithmeticException e) {\n              System.out.println(\"0으로 나눌 수 없습니다\");\n          } finally {\n              System.out.println(\"처리 종료\");\n          }\n      }\n}"]]}]},{"t":"(2) 다중 catch와 예외 계층","c":[{"t":"① 다중 catch 하위 예외 먼저","n":[["설명","다중 catch 블록 하나의 try 블록에 대하여 여러 개의 catch 블록을 연속하여 작성함으로써, 서로 다른 종류의 예외를 각각 다른 방식으로 처리할 수 있다. 이때 여러 catch 블록은 더 구체적인(하위) 예외 클래스를 먼저 작성하고, 더 포괄적인(상위) 예외 클래스를 나중에 작성해야 한다. 모든 예외 클래스의 최상위 클래스는 Exception이며, catch(Exception e)로 작성하면 어떤 종류의 예외든 모두 처리할 수 있다. 다만 이는 세밀한 예외 구분이 어려워지므로 일반적으로 구체적인 예외 클래스를 먼저 처리한 뒤 마지막에 포괄적으로 처리하는 방식이 권장된다."]]},{"t":"② throw 예외 강제 발생","n":[["설명","throw 키워드 throw 키워드는 프로그래머가 의도적으로 예외를 발생시키고자 할 때 사용한다. 특정 조건을 만족하지 않을때 throw new IllegalArgumentException(\"메시지\");와 같이 작성하여 예외를 강제로 발생시킬 수 있다."],["실제 사례","throws는 메서드 선언부에 작성하여, 이 메서드가 특정 예외를 발생시킬 가능성이 있음을 호출하는 쪽에 알려주는 역할을 한다. throw(예외를 실제로 발생시키는 문장)와 throws(메서드가 예외를 던질 수 있음을 선언하는 키워드)의 철자와 용법을 구분하는 문제가 시험에 출제될 수 있다."]]}]}]}]},{"t":"Ⅵ 배열과 컬렉션","c":[{"t":"1. Java의 배열","c":[{"t":"(1) 배열의 선언과 생성","c":[{"t":"① int[] arr = new int[5]","n":[["설명","배열 선언 문법"],["쉬운 예","Java에서 배열은 자료형[] 배열명 = new 자료형[크기]; 형태로 선언과 동시에 메모리를 할당한다. 예를 들어 int[] arr = new int[5];는 정수 5개를 저장할 수 있는 배열을 생성하며, C언어와 마찬가지로 인덱스는 0부터 시작한다."]]},{"t":"② 향상된 for문 for(타입 변수 : 배열)","n":[["설명","향상된 for문의 문법 Java는 배열이나 컬렉션의 모든 원소를 순서대로 꺼내어 처리할 때 for(자료형 변수명 : 배열명) 형태의 향상된 for문(for-each문)을 제공한다. 인덱스를 직접 다루지 않아도 되어 코드가 간결해진다는 장점이 있다."],["쉬운 예","예를 들어 int[] arr = {1,2,3}; for(int x : arr) { System.out.println(x); }와 같이 작성하면 배열의 모든 원소를 순서대로 출력할 수 있다."]]}]},{"t":"(2) ArrayList의 개념","c":[{"t":"① ArrayList 가변 크기·제네릭","n":[["설명","배열과의 차이 ArrayList는 java.util 패키지에서 제공하는 대표적인 컬렉션 클래스로, 일반 배열과 달리 크기가 고정되어 있지 않고 원소를 추가·삭제함에 따라 자동으로 크기가 조절되는 가변 크기의 목록이다. ArrayList<Integer> list = new ArrayList<>();와 같이 제네릭(Generic) 표기법을 사용하여 저장할 자료형을 지정한다. 이때 기본 자료형(int)이 아닌 래퍼 클래스(Integer)를 사용해야 한다는 점에 유의해야 한다."]]},{"t":"② add·remove·get·siz e","n":[["설명","추가, 삭제, 조회 add() 메서드로 원소를 추가하고, remove()로 특정 원소(또는 인덱스)를 삭제하며, get(인덱스)로 특정 위치의 값을 조회한다. size() 메서드는 현재 저장된 원소의 개수를 반환한다."],["시험 포인트","시험에서는 ArrayList에 값을 추가·삭제하는 짧은 코드를 제시하고 최종적으로 리스트에 남은 값이나 size()의 결과를 묻는 문제가 출제될 수 있다."]]}]}]}]},{"t":"Ⅶ 자바의 표준 입력과 문자열 처리","c":[{"t":"1. Scanner를 이용한 입력","c":[{"t":"(1) Scanner 클래스","c":[{"t":"① Scanner(System.in) nextInt","n":[["설명","Scanner의 선언과 사용 Java에서 키보드로부터 값을 입력받기 위해서는 java.util.Scanner 클래스를 사용한다. Scanner sc = new Scanner(System.in); 으로 객체를 생성한 뒤, sc.nextInt()(정수 입력), sc.nextDouble()(실수 입력) , sc.next()(공백 전까지의 문자열 입력), sc.nextLine()(한 줄 전체 입력) 등의 메서드로 값을 입력받는다. Scanner 클래스를 사용하려면 소스 코드의 맨 앞부분에 import java.util.Scanner; 문장을 작성하여 해당 클래스를 불러와야 한다. import문은 C언어의 #include, Python의 import와 유사한 역할을 한다."]]},{"t":"② nextInt 후 nextLine 개행 잔류","n":[["설명","nextInt()와 nextLine()의 혼용 문제"],["실제 사례","nextInt()는 숫자만 읽어 들이고 그 뒤에 있는 줄바꿈 문자는 입력 스트림에 그대로 남겨두기 때문에, 바로 이어서 nextLine()을 호출하면 빈 문자열을 읽어버리는 문제가 발생할 수 있다. 이는 실무와 시험 모두에서 자주 언급되는 대표적인 함정이다."]]}]},{"t":"(2) String 클래스의 특징","c":[{"t":"① String 불변 객체","n":[["설명","문자열의 불변성"],["실제 사례","Java의 문자열(String)은 한 번 생성되면 그 내용을 변경할 수 없는 불변(immutable) 객체이다. 문자열을 변경하는 것처럼 보이는 연산(+ 연결 등)은 실제로는 기존 문자열을 수정하는 것이 아니라 새로운 String 객체를 생성하는 것이다."]]},{"t":"② == 주소 비교, equals() 내용 비교","n":[["설명","== 연산자의 함정 Java에서 == 연산자는 기본 자료형(int 등)의 값 자체를 비교할 때는 값의 일치 여부를 정확히 비교하지만, String과 같은 객체(참조형)에 사용될 경우에는 두 참조변수가 완전히 동일한 객체(메모리 주소)를 가리키는 지를 비교한다. 두 문자열이 저장하고 있는 내용(문자의 나열) 자체가 같은지를 비교하려면 반드시 equals() 메서드를 사용해야 한다. 이는 C언어의 strcmp() 함수, Python의 == 연산자(Python은 문자열 내용 비교에 == 를 그대로 사용할 수 있음)와 비교되는 Java만의 중요한 특징이므로 세 언어의 문자열 비교 방식 차이를 명확히 구분해 두어야 한다."]]}]}]}]},{"t":"Ⅷ static 키워드와 클래스 변수","c":[{"t":"1. 인스턴스 변수와 클래스 변수","c":[{"t":"(1) 인스턴스 변수(Instance Variable)","c":[{"t":"① 인스턴스 변수 객체마다 독립","n":[["설명","개념 인스턴스 변수는 각 객체(인스턴스)마다 독립적으로 별도의 메모리 공간을 가지는 필드를 말한다. 동일한 클래스로부터 여러 객체를 생성하면, 각 객체는 서로 다른 값을 가지는 자신만의 인스턴스 변수를 가지게 되어한 객체의 값을 변경해도 다른 객체에는 영향을 주지 않는다."],["쉬운 예","예를 들어 Student 클래스에 이름(name)이라는 인스턴스 변수가 있다면, 학생 객체 s1과 s2는 각각 다른 이름 값을 독립적으로 저장할 수 있다."]]},{"t":"② static 클래스 변수 전 객체 공유","n":[["설명","static 키워드의 의미 클래스 변수는 필드 선언 앞에 static 키워드를 붙여 선언하며, 특정 객체에 속하는 것이 아니라 클래스 자체에 하나만 존재하여 그 클래스로부터 생성된 모든 객체가 공유하는 변수이다. 한 객체에서 static 변수의 값을 변경하면, 그 값은 같은 클래스의 다른 모든 객체에서도 변경된 것으로 확인된다. static 변수는 그 클래스로부터 생성된 객체의 총 개수를 세는 용도로 자주 활용된다. 생성자가 호출될 때마다 static 변수의 값을 1씩 증가시키면, 프로그램 전체에서 지금까지 몇 개의 객체가 생성되었는지를 공통으로 파악할 수 있다.\nclass Counter {\n      static int count = 0;   // 클래스 변수(모든 객체가 공유)\n      int id;                  // 인스턴스 변수(객체마다 독립)\n      Counter() {\n          count++;\n          id = count;\n      }\n}\n// Counter c1 = new Counter(); c1.id = 1, count = 1\n// Counter c2 = new Counter(); c2.id = 2, count = 2"]]}]},{"t":"(2) static 메서드","c":[{"t":"① static 메서드 객체 없이 호출","n":[["설명","static 메서드의 특징 static 메서드는 객체를 생성하지 않고도 클래스명.메서드명() 형태로 바로 호출할 수 있는 메서드이다. main() 메서드가 대표적인 static 메서드이며, 프로그램 실행을 위하여 객체 생성 없이도 JVM이 곧바로 호출할 수 있어야 하기 때문에 static으로 선언되어 있다. static 메서드 내부에서는 인스턴스 변수나 인스턴스 메서드에 직접 접근할 수 없다. 인스턴스 변수는 객체가 생성되어야 비로소 존재하는 반면, static 메서드는 객체 생성 여부와 관계없이 호출될 수 있으므로 아직 존재하지 않을 수도 있는 인스턴스 변수를 참조할 수 없기 때문이다."]]},{"t":"② final 변수 상수·상속·재정의 금지","n":[["설명","final 키워드의 의미 final 키워드는 변수에 사용되면 그 값을 한 번 초기화한 이후 다시는 변경할 수 없는 상수로 만들며, 클래스에 사용되면 그 클래스를 상속할 수 없도록 제한하고, 메서드에 사용되면 자식 클래스에서 그 메서드를 오버라 이딩할 수 없도록 제한한다."],["시험 포인트","static과 final을 함께 사용하면(예: static final int MAX = 100;) 클래스 전체가 공유하면서도 값이 변하지 않는 진정한 의미의 상수를 정의할 수 있다. 이는 Java에서 상수를 선언하는 가장 대표적이고 관용적인 방법으로 시험에 자주 언급된다."]]}]}]}]},{"t":"Ⅸ 제네릭과 컬렉션 심화","c":[{"t":"1. 제네릭(Generic)","c":[{"t":"(1) 제네릭의 개념","c":[{"t":"① 제네릭 자료형 안전성·형변환 제거","n":[["설명","제네릭이 필요한 이유"],["실제 사례","제네릭은 클래스나 메서드를 정의할 때 사용할 자료형을 미리 고정하지 않고, 실제로 사용하는 시점에 자료형을 지정할 수 있도록 하는 문법이다. 제네릭을 사용하면 여러 자료형에 대하여 동일한 코드를 재사용할 수 있으면서도, 컴파일 시점에 자료형을 검사하여 실행 중 발생할 수 있는 형변환 오류를 미리 방지할 수 있다."],["쉬운 예","제네릭은 꺾쇠괄호(<>) 안에 사용할 자료형을 지정하는 방식으로 표현한다. 예를 들어 ArrayList<String> list = new ArrayList<>();라고 선언하면, 이 리스트에는 오직 String 자료형의 값만 저장할 수 있음을 컴파일러에게 알려주는 것이다."]]},{"t":"② 컬렉션 제네릭 형변환 불필요","n":[["설명","컬렉션에서의 제네릭 사용 ArrayList, HashMap과 같은 컬렉션 클래스는 어떠한 자료형의 객체든 저장할 수 있도록 만들어져 있으나, 제네릭을 지정하지 않으면 꺼낸 값의 자료형을 알 수 없어 매번 형변환을 해 주어야 하는 불편함이 있다. 제네릭을 사용하면 이러한 불필요한 형변환 과정 없이 지정한 자료형 그대로 값을 꺼내어 사용할 수 있다. 제네릭에는 int, double과 같은 기본 자료형을 직접 지정할 수 없으며, 반드시 Integer, Double과 같이 이에 대응하는 래퍼(Wrapper) 클래스를 사용해야 한다는 제약이 있다."]]}]},{"t":"(2) HashMap의 개념","c":[{"t":"① HashMap 키-값 쌍 저장","n":[["설명","HashMap의 정의 HashMap은 java.util 패키지에서 제공하는 컬렉션 클래스로, 키(key)와 값(value)을 한 쌍으로 저장하는 자료구조이다. Python의 딕셔너리(dict)와 개념적으로 매우 유사하며, 특정 키를 이용하여 그에 대응하는 값을 빠르게 찾아올 수 있다는 장점이 있다. HashMap<String, Integer> map = new HashMap<>();와 같이 제네릭을 사용하여 키와 값의 자료형을 각각 지정하여 선언한다. 첫 번째 자료형은 키의 자료형을, 두 번째 자료형은 값의 자료형을 의미한다."]]},{"t":"② put 저장·갱신, get 조회","n":[["설명","put과 get put(키, 값) 메서드는 HashMap에 새로운 키-값 쌍을 저장하며, 이미 존재하는 키에 대하여 put()을 다시 호출하면 기존 값이 새로운 값으로 갱신(덮어쓰기)된다. get(키) 메서드는 특정 키에 대응하는 값을 조회하여 반환한다. containsKey(키) 메서드는 특정 키가 HashMap 안에 존재하는지 여부를 참(true)과 거짓(false)으로 반환하며, remove(키) 메서드는 특정 키-값 쌍을 삭제한다. HashMap은 저장된 순서를 보장하지 않는다는 점도 함께 기억해 두어야 한다."]]}]}]}]},{"t":"Ⅹ Wrapper 클래스와 컬렉션의 확장","c":[{"t":"1. Wrapper 클래스와 오토박싱","c":[{"t":"(1) Wrapper 클래스의 개념","c":[{"t":"① Wrapper Integer·Do uble·Boolean","n":[["설명","Wrapper 클래스란 Wrapper(래퍼) 클래스는 int, double, boolean과 같은 기본 자료형의 값을 객체로 다룰 수 있도록 감싸주는 클래스이다. int에 대응하는 Integer, double에 대응하는 Double, boolean에 대응하는 Boolean 등이 대표적이며, 컬렉션과 같이 객체만을 다룰 수 있는 자료구조에 기본 자료형의 값을 저장하고자 할 때 반드시 필요하다."],["쉬운 예","오토박싱(Autoboxing)은 기본 자료형의 값을 Wrapper 클래스 객체로 자동 변환해 주는 기능이며, 언박싱(Unboxing)은 반대로 Wrapper 클래스 객체를 다시 기본 자료형의 값으로 자동 변환해 주는 기능이다. 예를 들어 Integer num = 10;이라고 작성하면 컴파일러가 자동으로 오토박싱을 수행하여 int값 10을 Integer 객체로 감싸 준다."]]},{"t":"② Integer.parseInt, 오토박싱","n":[["설명","문자열과 기본 자료형 간의 변환 Wrapper 클래스는 문자열을 기본 자료형으로 변환하는 정적 메서드도 함께 제공한다. Integer.parseInt( 문자열)는 문자열을 int형으로, Double.parseDouble(문자열)은 문자열을 double형으로 변환하여 반환한다. ArrayList<Integer>와 같이 제네릭을 사용하는 컬렉션에는 기본 자료형이 아닌 Wrapper 클래스만 담을수 있으므로, 오토박싱 덕분에 개발자가 별도의 변환 코드를 작성하지 않고도 마치 기본 자료형처럼 자연스럽게 컬렉션에 값을 추가하고 꺼낼 수 있다."]]}]},{"t":"(2) LinkedList","c":[{"t":"① LinkedList 연결 구조 삽입·삭제","n":[["설명","개념 LinkedList는 ArrayList와 마찬가지로 java.util 패키지에서 제공하는 리스트 계열의 컬렉션 클래스이다. ArrayList가 배열 기반으로 구현되어 인덱스를 이용한 조회가 빠른 반면, LinkedList는 각 원소가 다음 원소를 가리키는 연결 구조로 구현되어 있어 리스트 중간에 데이터를 추가하거나 삭제하는 연산이 상대적으로 효율적이다."],["시험 포인트","ArrayList는 조회(get)가 빠르지만 중간 삽입·삭제 시 뒤 원소들을 옮겨야 하여 상대적으로 느리고, LinkedList는 중간 삽입·삭제가 빠르지만 특정 인덱스를 조회하려면 처음부터 순서대로 따라가야 하므로 조회 속도가 상대적으로 느리다는 트레이드오프가 있다. 시험에서는 두 컬렉션의 이러한 성능 특성의 차이를 비교하는 문제가 출제될 수 있다."]]},{"t":"② Iterator hasNext·next 순회","n":[["설명","Iterator의 개념"],["실제 사례","Iterator는 컬렉션에 저장된 원소들을 순서대로 하나씩 꺼내어 순회할 수 있도록 해 주는 표준화된 도구(인터페이스)이다. hasNext() 메서드로 다음 원소가 존재하는지 확인하고, next() 메서드로 다음 원소를 실제로 꺼내어 사용한다."]]}]}]}]}]},{"t":"제4절 Python 언어의 이해와 활용","c":[{"t":"Ⅰ Python 언어 개요","c":[{"t":"1. Python의 특징과 실행 방식","c":[{"t":"(1) Python의 특징","c":[{"t":"① 귀도 반 로섬, 간결·인터프리터","n":[["설명","간결한 문법과 높은 생산성 Python은 네덜란드의 귀도 반 로섬(Guido van Rossum)이 개발한 언어로, 문법이 간결하고 사람이 읽기 쉬워 초보자도 빠르게 학습할 수 있는 고급언어이다. C나 Java에 비하여 코드의 줄 수가 적고 세미콜론이나 중괄호 없이도 프로그램을 작성할 수 있어 생산성이 매우 높다. Python은 인터프리터 방식으로 실행되는 언어로서 별도의 컴파일 과정 없이 한 줄씩 즉시 해석되어 실행된다. 또한 동적 타이핑(Dynamic Typing)을 지원하여 변수를 선언할 때 자료형을 미리 지정하지 않아도 되며, 대입되는 값에 따라 자료형이 실행 중에 자동으로 결정된다."]]},{"t":"② 들여쓰기 블록, IndentationError","n":[["설명","들여쓰기(Indentation)의 의미 Python은 C나 Java의 중괄호({}) 대신 들여쓰기로 코드 블록의 범위를 구분하는 독특한 문법을 가지고 있다. if문, for문, 함수 정의 등에서 동일한 블록에 속하는 문장들은 반드시 동일한 개수의 공백(또는 탭)으로 들여쓰기가 되어야 하며, 들여쓰기 규칙을 지키지 않으면 오류(IndentationError)가 발생한다. if, for, while, def, class 등으로 시작하는 문장의 끝에는 반드시 콜론(:)을 붙이며, 그 다음 줄부터 들여쓰기된 문장들이 해당 블록에 속하게 된다. 세미콜론은 필수가 아니며 한 줄에 하나의 문장을 작성하는 것이 일반적이다. a = 10 if a > 5:\n   print(\"5보다 큽니다\")      # 들여쓰기로 블록 구분\n   print(\"두 번째 문장\")\nprint(\"블록 밖의 문장\")"]]}]}]}]},{"t":"Ⅱ 자료형과 연산자","c":[{"t":"1. 기본 자료형","c":[{"t":"(1) 숫자형과 문자열형","c":[{"t":"① / 실수, // 몫, % 나머지, ** 거듭제곱","n":[["설명","숫자형(정수형, 실수형) Python의 숫자형에는 정수형(int)과 실수형(float)이 있으며, C나 Java와 달리 정수형의 크기 제한이 사실상 없어 매우 큰 숫자도 오버플로우 걱정 없이 표현할 수 있다. 나눗셈 연산자에는 일반 나눗셈(/, 항상 실수 반환)과 몫만 구하는 정수 나눗셈(//), 나머지를 구하는 연산자(%), 거듭제곱 연산자(**)가 있다."],["쉬운 예","문자열은 작은따옴표나 큰따옴표로 감싸서 표현하며, 두 문자열을 + 연산자로 연결(결합)할 수 있고 * 연산자로 문자열을 반복시킬 수 있다. 예를 들어 \"abc\" * 3은 \"abcabcabc\"가 된다."]]},{"t":"② True·False, 0·빈값 False","n":[["설명","불리언형 불리언형은 True와 False 두 가지 값만을 가지는 자료형이다. Python에서는 0, 0.0, 빈 문자열과 같이 비어 있거나 값이 없는 데이터는 조건문에서 False로 취급되고, 그 외의 값은 True로 취급된다."],["시험 포인트","서로 다른 자료형 간의 값을 변환할 때는 int(), float(), str() 등의 형변환 함수를 사용한다. 특히 문자열과 숫자를 + 연산자로 결합하려고 하면 오류가 발생하므로, str(n)과 같이 숫자를 문자열로 명시적으로 변환한 뒤 결합해야 한다는 점이 시험에서 자주 다루어진다. n = 10\nprint(\"숫자는 \" + str(n) + \"입니다\")   # 강제 형변환 필요"]]}]},{"t":"(2) 리스트(list)와 튜플(tuple)","c":[{"t":"① 리스트 [] 가변, 튜플 () 불변","n":[["설명","리스트 리스트는 대괄호로 표현하며 여러 개의 값을 순서대로 저장하는 자료형이다. 리스트에 저장된 값은 이후에 추가(append), 삭제(remove, del), 수정이 자유롭게 가능한 가변(mutable) 자료형이다. 튜플은 소괄호로 표현하며 리스트와 유사하게 여러 값을 순서대로 저장하지만, 한 번 생성된 이후에는 값을 변경할 수 없는 불변(immutable) 자료형이라는 점이 리스트와의 근본적인 차이이다."]]},{"t":"② 딕셔너리 키-값, 집합 중복 불허","n":[["설명","딕셔너리 딕셔너리는 중괄호로 표현하며 키(key)와 값(value)을 한 쌍으로 저장하는 자료형이다. 딕셔너리명[키]의 형태로 특정 키에 대응하는 값에 접근한다. 집합도 중괄호로 표현하지만 딕셔너리와 달리 키-값 쌍이 아닌 값만을 저장하며, 중복된 값을 허용하지 않고 저장된 값들의 순서가 유지되지 않는다는 특징이 있다. 교집합(&), 합집합(|), 차집합(-) 연산을 지원하여 수학의 집합 연산을 그대로 프로그램에서 활용할 수 있다."]]}]}]}]},{"t":"Ⅲ 문자열 처리","c":[{"t":"1. 문자열 인덱싱과 슬라이싱","c":[{"t":"(1) 인덱싱(Indexing)","c":[{"t":"① 인덱스 0부터, 음수 -1 끝","n":[["설명","인덱스 번호 규칙"],["쉬운 예","문자열의 각 문자는 순서대로 인덱스 번호가 매겨지며, 맨 앞 문자의 인덱스는 0부터 시작한다. 예를 들어 s가 \"Python\"일 때 s[0]은 P, s[5]는 n이다."],["쉬운 예","Python은 문자열의 뒤에서부터 접근할 수 있는 음수 인덱스도 지원한다. s[-1]은 문자열의 마지막 문자를, s[-2]는 뒤에서 두 번째 문자를 가리킨다. 예를 들어 s가 \"Python\"일 때 s[-1]은 n이다."]]},{"t":"② 슬라이싱 [시작:끝] 끝 미포함","n":[["설명","슬라이싱의 기본 문법"],["쉬운 예","슬라이싱은 문자열의 일부를 잘라내는 기능으로 시작 인덱스와 끝 인덱스를 콜론으로 구분하여 지정한다. 시작 인덱스는 포함되지만 끝 인덱스는 포함되지 않는다는 점이 매우 중요한 시험 포인트이다. 예를 들어 s가 \"Python\"일 때 s[0:3]은 Pyt이며, 끝을 생략하면 해당 인덱스부터 문자열 끝까지를 의미하고, 시작을 생략하면 처음부터 해당 인덱스 전까지를 의미한다."],["시험 포인트","슬라이싱은 시작, 끝에 이어 증가값을 추가로 지정하여 몇 칸씩 건너뛰며 문자를 추출할지 정할수 있다. 증가값을 2로 지정하면 짝수 번째 인덱스의 문자만 추출하며, 증가값을 -1로 지정하면 문자열 전체를 거꾸로 뒤집는 결과를 만든다. 이 뒤집기 표현은 문자열 뒤집기 문제로 시험에 매우 자주 출제된다. s = \"Python\""]]}]},{"t":"(2) 주요 문자열 메서드","c":[{"t":"① upper·lower·strip· split·join","n":[["설명","대소문자 변환과 공백 제거 upper()는 문자열을 모두 대문자로, lower()는 모두 소문자로 변환한다. strip()은 문자열 양쪽 끝의 공백을 제거하며, lstrip()과 rstrip()은 각각 왼쪽과 오른쪽의 공백만 제거한다. split()은 구분자를 기준으로 문자열을 나누어 리스트로 반환하며, join()은 리스트의 문자열 원소들을 구분자를 사이에 넣어 하나의 문자열로 결합한다. replace()는 문자열 안의 특정 부분을 다른 문자열로 치환하고, find()는 특정 문자열이 처음 나타나는 위치(인덱스)를 반환한다."]]},{"t":"② format()·f-string, len()","n":[["설명","format() 메서드와 f-string format() 메서드를 사용하면 문자열 중괄호 위치에 변수의 값을 대입하여 문자열을 완성할 수 있다. 최근에는 문자열 앞에 f를 붙이고 중괄호 안에 변수를 직접 작성하는 f-string 방식이 더 간결하여 널리 사용된다. len() 함수는 문자열의 길이(문자 개수)를 반환하는 내장 함수로, 리스트, 튜플 등 다른 군집 자료형의 원소 개수를 셀 때도 동일하게 사용된다."]]}]}]}]},{"t":"Ⅳ 제어문과 반복문","c":[{"t":"1. 조건문","c":[{"t":"(1) if~elif~else문","c":[{"t":"① if~elif~else 콜론·들여쓰기","n":[["설명","기본 구조 Python의 조건문은 if 조건식: 으로 시작하며, 추가 조건은 else if가 아닌 elif 조건식: 으로 작성하고, 마지막에 else: 로 나머지 모든 경우를 처리한다. C나 Java와 달리 조건식을 소괄호로 감싸지 않아도 되며, 블록은 들여쓰기로 구분한다. 점수에 따라 등급을 판정하는 프로그램에서 조건을 순서대로 검사하며, 처음으로 참이 되는 조건의 블록만 실행하고 이후 조건은 검사하지 않는다."]]},{"t":"② 논리 and·or·not, in 연산자","n":[["설명","비교연산자와 논리연산자 Python의 비교연산자는 다른 언어와 동일하지만, 논리연산자는 기호(&&, ||, !) 대신 and, or, not이라는 영단어를 그대로 사용한다는 점이 C, Java와 구별되는 매우 중요한 차이점이다. in 연산자는 특정 값이 리스트, 문자열, 튜플 등에 포함되어 있는지를 검사하는 연산자이다. 조건문의 조건식에서 자주 활용된다."]]}]},{"t":"(2) for문과 range() 함수","c":[{"t":"① range(a, b, step) 끝값 미포함","n":[["설명","range() 함수의 규칙 range(n)은 0부터 n-1까지의 정수를 생성하고, range(a, b)는 a부터 b-1까지, range(a, b, step)은 a부터 b-1까지 step만큼 건너뛰며 정수를 생성한다. 파이썬의 range() 역시 슬라이싱과 마찬가지로 끝값은 결과에 포함되지 않는다는 점을 반드시 기억해야 한다. for문은 range() 뿐만 아니라 리스트, 문자열, 튜플과 같이 순서가 있는 자료형의 원소를 하나씩 꺼내어 반복하는 용도로도 널리 사용된다. s = 0 for i in range(1, 11):   # 1부터 10까지 s = s + i\nprint(s)   # 55"]]},{"t":"② while True 무한루프·break","n":[["설명","while문의 구조\nwhile문은 조건식이 참인 동안 들여쓰기 된 블록을 반복하여 실행한다. C, Java의 while문과 동작 원리는\n동일하며, 조건이 처음부터 거짓이면 블록이 한 번도 실행되지 않는다. 조건식에 True를 지정하면 무한히 반복되는 루프가 되며, 이 경우 반복문 내부에 break문을 이용한 별도의 종료 조건을 반드시 마련해야 한다."]]},{"t":"③ break 종료, continue 건너뜀","n":[["설명","break문 break문은 반복문(for, while)을 즉시 종료시키는 명령으로, C, Java의 break문과 동일한 역할을 한다. continue문은 현재 반복 회차의 남은 문장을 건너뛰고 곧바로 다음 반복으로 넘어가는 명령이다. for문이나\nwhile문 안에서 특정 조건일 때만 처리를 생략하고 싶은 경우에 사용한다."]]}]}]}]},{"t":"Ⅴ 함수와 예외처리","c":[{"t":"1. 사용자 정의 함수","c":[{"t":"(1) 함수의 정의(def)와 반환","c":[{"t":"① def 함수명(매개변수): return","n":[["설명","def 키워드 Python에서 사용자 정의 함수는 def 함수명(매개변수): 의 형태로 정의한다. 매개변수는 필요에 따라 있을 수도, 없을 수도 있으며, 함수의 실행 결과를 호출한 곳으로 돌려주고 싶을 때는 return문을 사용한다.\nreturn문이 없는 함수는 호출 후 결과값을 돌려받을 수 없으며, 파이썬 인터프리터(셸) 환경에서 결과값 없이\n함수만 단독으로 호출하면 아무 값도 출력되지 않는다. 반면 return문이 있는 함수는 그 반환값을 변수에 저장하거나 다른 연산에 곧바로 활용할 수 있다. 또한 프로그램은 파일의 위에서 아래로 실행되며, 함수가 정의된 코드 자체는 호출되기 전까지 실행되지 않고, 함수 호출문을 만났을 때 비로소 함수 내부로 실행 흐름이 이동한다는 점을 기억해야 한다.\ndef some_func(n):    # 사용자 정의 함수\n   s = 0\n   for x in range(1, n+1):\n        s = s + x\n   return s"]]},{"t":"② 전역변수, global 키워드","n":[["설명","전역변수 전역변수는 함수 바깥(호출 이전, 함수 밖)에서 선언된 변수로, 프로그램 전체에서 참조하여 사용할 수 있다."],["시험 포인트","지역변수는 함수 안에서 선언되어 그 함수 내부에서만 사용되는 변수이다. 함수 내부에서 전역변 수와 같은 이름의 변수에 새로 값을 대입하면, 이는 전역변수를 변경하는 것이 아니라 같은 이름을 가진 새로운 지역변수가 별도로 만들어지는 것이며, 함수가 끝나고 나면 바깥의 전역변수 값은 변경되지 않은 채 그대로 유지된다. 즉 이름이 같아도 서로 독립된 별개의 변수라는 점이 시험에서 함정 문제로 자주 등장한다."]]}]},{"t":"(2) math 모듈","c":[{"t":"① math sqrt·pow·ceil ·floor","n":[["설명","math 모듈의 주요 함수"],["쉬운 예","math 모듈에 있는 함수를 사용하려면 모듈을 불러온 뒤 함수 이름 앞에 math를 붙여 호출한다. math의 ceil은 소수점을 올림하여 정수로, floor는 소수점을 버림(내림)하여 정수로 반환한다. 예를 들어 2.1 을 올림하면 3, 2.8을 내림하면 2가 된다."]]},{"t":"② random randint·cho ice","n":[["설명","random 모듈의 주요 함수"],["시험 포인트","random 모듈을 사용하려면 모듈을 불러와야 한다. random 함수는 0 이상 1 미만의 임의의 실수를 반환하고, randint(a, b)는 a 이상 b 이하의 임의의 정수를 반환한다. 결과값이 실행할 때마다 달라지므로 특정 실행 결과를 묻는 문제는 출제될 수 없으며, 각 함수의 용도와 기능을 구분하는 문제가 출제된다."]]}]},{"t":"(3) try~except~else~ finally 구조","c":[{"t":"① try·except·else·fi nally 역할","n":[["설명","각 블록의 역할 try 블록은 오류가 발생할 가능성이 있는 문장을 실행해 보는 블록이다. try 블록 실행 중 오류(예외)가 발생하면 except 블록이 실행되고, 오류가 발생하지 않으면 else 블록이 실행된다. finally 블록은 오류 발생 여부와 관계없이 항상 마지막에 실행되는 블록이다. except문이 생략된 상태에서 오류가 발생하지 않으면 else 블록이 실행되지만, except문 자체가 없는 상태에서는 애초에 오류 발생 시 처리할 블록이 없다는 점에 유의해야 한다. else와 finally는 각각 상황에 따라 생략할 수 있다."]]},{"t":"② 정상 시 try→else→fina lly","n":[["설명","오류가 발생하지 않는 경우 try 블록의 문장이 오류 없이 정상적으로 실행되면, try 블록 실행 다음 except 블록은 건너뛰고 else 블록을 실행한 뒤 마지막으로 finally 블록을 실행하는 순서로 진행된다."],["쉬운 예","try 블록에서 오류가 발생하면, 오류가 발생한 지점까지만 실행한 뒤 except 블록을 실행하고 else 블록은 건너뛴 채 마지막으로 finally 블록을 실행하는 순서로 진행된다. 예를 들어 0으로 나누는 연산을 try 블록에 포함시킨 코드를 제시하고, 최종적으로 어떤 순서로 어떤 값이 출력되는지를 분석하는 문제가 자주 출제된다. try:"]]}]},{"t":"(4) match문의 개념과 문법","c":[{"t":"① match문 Python 3.10 다중분기","n":[["설명","match문의 등장 배경 match문은 Python 3.10 버전부터 새롭게 도입된 문법으로, C나 Java의 switch문과 유사하게 하나의 변수 값에 따라 여러 경우 중 하나를 선택하여 실행하는 다중 분기 구조이다. match 뒤에 검사할 대상을 적고 콜론으로 시작하고, 각 경우는 case 값으로 작성하며, 어떤 case와도 일치하지 않는 경우를 처리하는 언더바 case를 마지막에 둘 수 있다. Java의 switch문과 달리 Python의 match문은 각 case 블록에 break문을 작성할 필요가 없다. 일치하는 case 하나만 실행한 뒤 자동으로 match문을 빠져나가므로, switch문에서 발생할 수 있는 폴스루(fall-through) 현상이 애초에 발생하지 않는다."]]},{"t":"② match~case _ 기본 사용 예","n":[["설명","기본 사용 예시"],["쉬운 예","예를 들어 요일을 나타내는 숫자를 입력받아 그에 해당하는 요일명을 출력하는 프로그램을 match문으로 간결하게 구현할 수 있다. 파이프 기호를 사용하면 여러 값을 하나의 case에서 함께 처리할 수도 있다."],["시험 포인트","match문은 비교적 최근에 추가된 문법이므로, 시험에서는 기본적인 문법 구조(콜론 사용, 기본 case의 의미, break문이 필요 없다는 점)를 이해하고 있는지를 확인하는 수준의 문제가 출제될 가능성이 높다. day = 3 match day:"]]}]}]}]},{"t":"Ⅵ Python의 클래스와 객체지향 프로그래밍","c":[{"t":"1. 클래스 정의와 객체 생성","c":[{"t":"(1) class 키워드와 클래스 선언","c":[{"t":"① class 정의, __init__ 초기화","n":[["설명","클래스 정의 문법 Python에서도 class 키워드를 이용하여 클래스를 정의할 수 있다. 클래스 내부에 속성과 메서드를 정의하며, Python의 클래스 역시 Java와 마찬가지로 객체를 생성하기 위한 설계도 역할을 한다. 클래스 안에 정의하는 특수한 초기화 메서드는 객체가 생성될 때 자동으로 호출되는 메서드로, Java의 생성 자와 동일한 역할을 한다. 객체가 만들어질 때 필요한 초기값을 설정하는 데 사용되며, 메서드 이름 앞뒤에 밑줄이 두 개씩 붙어 있다는 점이 특징이다.\nclass Dog:\n   def __init__(self, name):   # 생성자"]]},{"t":"② self 객체 자신 명시","n":[["설명","self의 의미 Python의 클래스 메서드는 첫 번째 매개변수로 반드시 self를 작성해야 하며, self는 그 메서드를 호출한 객체 자기 자신을 가리킨다. Java나 C++에서는 this 키워드가 암묵적으로 처리되지만, Python은 self를 각메서드마다 명시적으로 작성해야 한다는 차이가 있다. self에 점을 찍고 속성명을 붙여 값을 대입한 변수를 인스턴스 변수라고 하며, 이는 객체마다 독립적으로 유지되는 값이다. 즉 같은 클래스로부터 여러 객체를 생성하더라도 각 객체의 인스턴스 변수는 서로 영향을 주지 않는다."]]}]},{"t":"(2) 상속의 문법","c":[{"t":"① class 자식(부모) 상속 선언","n":[["설명","클래스 상속 선언 Python에서 상속은 자식 클래스명 뒤 소괄호 안에 부모 클래스명을 적는 형태로 선언한다. Java의 extends와 달리 소괄호 안에 부모 클래스의 이름을 직접 작성한다는 문법적 차이가 있다. 자식 클래스에서 부모 클래스와 동일한 이름의 메서드를 다시 정의하면, Java와 마찬가지로 오버라이딩이되어 자식 클래스의 메서드가 우선적으로 실행된다."]]},{"t":"② Python 다중 상속 직접 지원","n":[["설명","Python의 다중 상속 지원 Java는 클래스의 다중 상속을 허용하지 않고 인터페이스를 통해서만 유사하게 구현할 수 있는 반면, Python은 소괄호 안에 여러 개의 클래스 이름을 나열하여 동시에 상속받는 다중 상속을 직접 지원한다는 점이 중요한 차이이다."],["시험 포인트","시험에서는 C, Java, Python 세 언어의 상속 관련 키워드(단순히 소괄호 사용 여부, extends 사용 여부)와 다중 상속 지원 여부를 서로 비교하는 문제가 출제될 수 있다."]]}]}]}]},{"t":"Ⅶ 파일 입출력","c":[{"t":"1. 파일 열기와 닫기","c":[{"t":"(1) open() 함수","c":[{"t":"① open 모드 r·w·a, close()","n":[["설명","파일 열기 모드 Python에서 파일을 다루려면 open 함수에 파일명과 모드를 지정하여 파일 객체를 얻어야 한다. 대표적인 모드로 읽기 모드, 쓰기 모드(기존 내용 삭제 후 새로 씀), 추가 모드(기존 내용 뒤에 이어 씀)가 있다. 파일 작업이 끝난 후에는 close() 메서드를 호출하여 파일을 닫아 주어야 한다. 파일을 닫지 않으면 다른 프로그램에서 해당 파일에 접근하지 못하거나 데이터가 완전히 저장되지 않을 수 있다."]]},{"t":"② with문 파일 자동 닫기","n":[["설명","with문의 필요성 with문을 사용하여 파일을 열면, 블록 안의 코드가 모두 실행된 후 파일을 자동으로 닫아 주기 때문에 close()를 깜빡하는 실수를 방지할 수 있다. with문은 파일 처리 도중 예외가 발생하더라도 자동으로 파일을 안전하게 닫아 주므로, 예외 처리 관점에서도 try~finally를 직접 작성하는 것보다 안전하고 간결한 방법으로 널리 권장된다. with open(\"data.txt\", \"w\") as f: f.write(\"Hello Python\\n\") with open(\"data.txt\", \"r\") as f: content = f.read()\nprint(content)"]]}]},{"t":"(2) 파일 쓰기 메서드","c":[{"t":"① write·writelines 개행 미추가","n":[["설명","write() write 메서드는 파일에 문자열 하나를 그대로 기록한다. print 함수와 달리 자동으로 줄바꿈이 되지 않으므로, 줄바꿈이 필요하면 문자열 끝에 직접 개행 문자를 포함시켜야 한다. writelines 메서드는 문자열로 이루어진 리스트의 각 원소를 순서대로 파일에 기록한다. 이 역시 각 줄 끝에 개행 문자가 자동으로 추가되지 않는다는 점에 유의해야 한다."]]},{"t":"② read 전체, readline 한 줄","n":[["설명","read()와 readline() read 메서드는 파일의 전체 내용을 하나의 문자열로 읽어 오며, readline 메서드는 파일에서 한 줄만 읽어 온다. 파일을 한 줄씩 반복하여 읽어야 할 때는 readline을 반복 호출하거나 파일 객체를 직접 반복문에 사용할수 있다."],["시험 포인트","readlines 메서드는 파일의 모든 줄을 각각의 문자열 원소로 갖는 리스트 형태로 한 번에 읽어 온다. 시험에서는 read, readline, readlines가 반환하는 자료형(문자열 vs 리스트)의 차이를 구분하는 문제가 출제될 수 있다."]]}]}]}]},{"t":"Ⅷ 리스트 컴프리헨션과 람다식","c":[{"t":"1. 리스트 컴프리헨션(List Comprehension)","c":[{"t":"(1) 리스트 컴프리헨션의 개념","c":[{"t":"① [표현식 for 변수 in 반복대상]","n":[["설명","기본 문법 리스트 컴프리헨션은 대괄호 안에 반복문과 조건문을 함께 사용하여 새로운 리스트를 간결한 한 줄의 코드로 생성하는 Python만의 독특한 문법이다. [표현식 for 변수 in 반복대상] 의 형태로 작성하며, 일반적인 for문과 append()를 여러 줄에 걸쳐 작성하는 것과 동일한 결과를 훨씬 간결하게 얻을 수 있다. [표현식 for 변수 in 반복대상 if 조건식] 과 같이 if 조건을 추가하면, 반복 대상 중 조건을 만족하는 원소에 대해서만 표현식을 적용하여 새로운 리스트를 생성할 수 있다. squares = [x*x for x in range(1, 6)]\nprint(squares)     # [1, 4, 9, 16, 25]\nevens = [x for x in range(1, 11) if x % 2 == 0]\nprint(evens)        # [2, 4, 6, 8, 10]"]]},{"t":"② 컴프리헨션 간결성·과중첩 주의","n":[["설명","코드의 간결성 리스트 컴프리헨션을 사용하면 여러 줄의 for문과 append() 호출을 단 한 줄로 표현할 수 있어 코드가 짧고 명확해진다. 다만 조건과 반복이 지나치게 복잡하게 중첩되면 오히려 가독성이 떨어질 수 있으므로 적절한 상황에서 사용하는 것이 바람직하다."],["시험 포인트","시험에서는 짧은 리스트 컴프리헨션 코드를 제시하고 그 결과로 생성되는 리스트의 내용을 추론하는 문제가 출제될 수 있으며, 이는 for문과 조건문에 대한 이해를 함께 확인하는 문제이기도 하다."]]}]},{"t":"(2) 람다식의 개념","c":[{"t":"① lambda 매개변수: 표현식 익명함수","n":[["설명","람다식이란 람다식은 이름이 없는 익명 함수를 한 줄로 간단히 정의하는 문법으로, lambda 매개변수: 표현식 의 형태로 작성한다. def 키워드로 함수를 별도로 정의하지 않고도, 짧고 간단한 함수가 필요한 곳에서 즉석으로 만들어 사용할 수 있다는 장점이 있다. 람다식은 하나의 표현식만을 포함할 수 있으며, return문이나 여러 개의 문장으로 이루어진 복잡한 로직은 람다식으로 표현할 수 없다. 복잡한 처리가 필요한 경우에는 일반적인 def 함수로 정의해야 한다. add = lambda a, b: a + b\nprint(add(3, 5))     # 8\nnums = [1, 2, 3, 4, 5] squared = list(map(lambda x: x*x, nums))\nprint(squared)     # [1, 4, 9, 16, 25]"]]},{"t":"② map(함수, 리스트) 일괄 적용","n":[["설명","map() 함수 map(함수, 리스트)는 리스트의 각 원소에 지정된 함수를 적용한 결과를 새로운 map 객체로 반환한다. 람다 식과 함께 사용하면 별도의 함수 정의 없이 리스트의 모든 원소를 일괄 변환할 수 있다."],["쉬운 예","filter(함수, 리스트)는 리스트의 각 원소 중 함수의 결과가 참(True)인 원소만을 걸러내어 반환한다. 예를 들어 filter(lambda x: x % 2 == 0, nums)는 nums 리스트에서 짝수만을 걸러낸다."]]}]}]}]},{"t":"Ⅸ 모듈과 패키지","c":[{"t":"1. 모듈(Module)","c":[{"t":"(1) 모듈의 개념","c":[{"t":"① 모듈 .py 파일, import 모듈명","n":[["설명","모듈이란 모듈은 함수, 변수, 클래스 등을 모아 놓은 하나의 파이썬 파일(.py)을 의미한다. 프로그램의 코드를 기능별로 여러 모듈로 나누어 작성하면, 코드의 재사용성이 높아지고 프로그램의 구조를 체계적으로 관리할 수 있다. 다른 모듈에 정의된 함수나 변수를 사용하려면 import 모듈명 문장으로 해당 모듈을 불러와야 한다. 불러온 모듈의 함수를 사용할 때는 모듈명.함수명() 형태로 접근한다."]]},{"t":"② from 모듈 import 함수","n":[["설명","from ~ import 구문 from 모듈명 import 함수명 형태로 작성하면, 모듈 전체가 아니라 특정 함수나 변수만을 선택적으로 불러올수 있다. 이 경우에는 모듈명을 붙이지 않고 함수명만으로 바로 호출할 수 있다는 차이가 있다."],["쉬운 예","import 모듈명 as 별칭 형태로 작성하면, 모듈의 이름을 원하는 별칭으로 줄여서 사용할 수 있다. 예를 들어 import math as m이라고 작성하면 이후 코드에서 math 대신 m으로 짧게 모듈에 접근할 수 있다."]]}]},{"t":"(2) 패키지의 개념","c":[{"t":"① 패키지 모듈 묶은 디렉터리","n":[["설명","패키지란 패키지는 관련 있는 여러 모듈들을 하나의 디렉터리(폴더) 아래에 모아 계층적으로 구성한 것을 말한다. 프로그램의 규모가 커질수록 모듈의 개수도 늘어나므로, 이를 폴더 구조로 체계적으로 묶어 관리하기 위하여 패키지 개념이 사용된다. 패키지 안에 있는 특정 모듈을 사용하려면 import 패키지명.모듈명 과 같이 점(.)으로 구분하여 접근 경로를 표시한다."]]},{"t":"② 표준 라이브러리·pip install","n":[["설명","표준 라이브러리 Python은 별도의 설치 없이 기본적으로 제공되는 표준 라이브러리(math, random, os, sys 등)를 풍부하게 갖추고 있어, 다양한 기능을 별도의 구현 없이 바로 활용할 수 있다. 표준 라이브러리에 포함되지 않은 기능은 pip이라는 패키지 관리 도구를 이용하여 외부 패키지를 설치한 뒤사용할 수 있다. pip install 패키지명 명령으로 필요한 외부 패키지를 내려받아 설치할 수 있으며, 이는 Python 생태계가 방대한 기능을 손쉽게 확장할 수 있는 기반이 된다."]]}]}]}]},{"t":"Ⅹ 정규표현식과 예외 처리 심화","c":[{"t":"1. 정규표현식(re 모듈)","c":[{"t":"(1) 정규표현식의 개념","c":[{"t":"① 정규표현식 문자열 패턴, re 모듈","n":[["설명","정규표현식이란 정규표현식(Regular Expression)이란 특정한 규칙을 가진 문자열의 패턴을 표현하기 위한 형식 언어이다. 전화번호, 이메일 주소, 우편번호와 같이 일정한 형식을 갖는 문자열이 올바른 형식인지 검사하거나, 긴 텍스 트에서 원하는 패턴의 문자열만 찾아낼 때 널리 사용된다. Python에서는 표준 라이브러리인 re 모듈을 불러와 정규표현식을 사용할 수 있다. re.match()는 문자열의맨 앞부분이 패턴과 일치하는지 검사하고, re.search()는 문자열 전체에서 패턴과 일치하는 부분을 찾으며, re.findall()은 패턴과 일치하는 모든 부분을 리스트로 반환한다."]]},{"t":"② 메타문자 . * + ? []","n":[["설명","기본 메타문자 정규표현식에는 특별한 의미를 가지는 메타문자가 있다. 마침표(.)는 임의의 한 문자를, 별표(*)는 바로 앞 문자가 0개 이상 반복됨을, 더하기(+)는 바로 앞 문자가 1개 이상 반복됨을, 물음표(?)는 바로 앞 문자가 0개 또는 1개 있음을 의미한다. 대괄호([ ])는 그 안에 포함된 문자 중 하나와 일치함을 의미하며(예: [0-9]는 숫자 하나), \\d는 숫자를, \\s는 공백 문자를 의미하는 축약 표현이다. 캐럿(^)은 문자열의 시작을, 달러($)는 문자열의 끝을 나타내는 앵커 (anchor) 기호로 사용된다.\nimport re\ntext = \"제 전화번호는 010-1234-5678 입니다\" result = re.search(r\"\\d{3}-\\d{4}-\\d{4}\", text) if result:\nprint(result.group())    # 010-1234-5678"]]}]},{"t":"(2) 다중 except와 예외 튜플","c":[{"t":"① 다중 except·예외 튜플","n":[["설명","여러 개의 except 블록 Python도 Java와 마찬가지로 하나의 try 블록에 대하여 여러 개의 except 블록을 연속하여 작성하여, 서로 다른 종류의 예외를 각각 다른 방식으로 처리할 수 있다. 이때도 더 구체적인 예외를 먼저 검사하고, 포괄적인 Exception은 가장 마지막에 작성하는 것이 일반적인 관례이다. except (ValueError, TypeError):와 같이 괄호로 여러 예외 클래스를 튜플로 묶어 작성하면, 이 중 어느 하나라도 발생했을 때 동일한 except 블록에서 한꺼번에 처리할 수 있다."]]},{"t":"② 사용자 정의 예외, raise","n":[["설명","Exception 클래스 상속 Python에서는 내장된 Exception 클래스를 상속받는 새로운 클래스를 정의하여 프로그래머가 직접 사용자정의 예외를 만들 수 있다. 이를 통해 프로그램의 특정 상황에 맞는 의미 있는 이름의 예외를 설계하여 사용할수 있다. raise 키워드는 Java의 throw 키워드와 동일한 역할을 하며, 프로그래머가 의도적으로 예외를 발생시키고자 할 때 사용한다. raise 사용자정의예외(\"에러 메시지\")와 같은 형태로 작성하여 특정 조건을 만족하지 않을 때 강제로 예외를 발생시킬 수 있다.\nclass NegativeNumberError(Exception):   # 사용자 정의 예외\n   pass\ndef check_positive(n):\n   if n < 0:\n          raise NegativeNumberError(\"음수는 허용되지 않습니다\")\n   return n\ntry: check_positive(-5) except NegativeNumberError as e:\nprint(e)     # 음수는 허용되지 않습니다"]]}]}]}]}]}],"k":"필기 1과목"},{"n":2,"t":"응용SW기초기술","c":[{"t":"제1절 운영체제의 이해와 활용","c":[{"t":"Ⅰ 운영체제의 개념과 목적","c":[{"t":"1. 운영체제의 정의와 역할","c":[{"t":"(1) 운영체제의 정의","c":[{"t":"① OS: HW 사용 인터페이스 SW","n":[["설명","운영체제란 운영체제(Operating System, OS)란 사용자로 하여금 컴퓨터의 하드웨어를 보다 쉽게 사용할 수 있도록 인터페이스를 제공해 주는 소프트웨어를 말한다. 컴퓨터의 하드웨어는 데이터를 처리하는 중앙처리장치(CPU), 데이터를 저장하는 기억장치, 외부와 통신을 담당하는 통신장치, 데이터의 입출력을 담당하는 입출력장치 등으로 구분되는데, 운영체제는 이러한 여러 장치를 사용자가 직접 제어하지 않고도 편리하게 이용할 수있도록 중간에서 다리 역할을 한다. 운영체제는 단순히 사용자 편의를 위한 인터페이스에 그치지 않고, 중앙처리장치·메모리·디스크·주변기기 등컴퓨터가 가진 다양한 자원을 효율적으로 배분하고 관리하는 자원 관리자(Resource Manager)의 역할도 함께 수행한다. 즉 운영체제의 제어 범위는 CPU, 메모리, 디스크는 물론 마우스·키보드·프린터·모니터·스피 커와 같은 외부 장치의 컨트롤러까지 포괄한다."]]},{"t":"② 처리능력↑·반환시간↓ 성능 평가","n":[["설명","처리 능력과 반환 시간 운영체제의 목적은 곧 운영체제의 성능을 평가하는 항목과도 같다. 처리 능력(Throughput)은 일정한 단위 시간 내에 처리할 수 있는 일의 양을 의미하며, 반환 시간(Turn Around Time)은 하나의 작업을 시작한 시점부터 그 결과를 얻을 때까지 걸리는 시간을 의미한다. 처리 능력은 높을수록, 반환 시간은 짧을수록 우수한 운영체제로 평가된다."],["시험 포인트","사용 가능도(Availability)는 시스템을 이용하고자 할 때 얼마나 신속하게 사용할 수 있는지를 나타내는 정도이며, 신뢰도(Reliability)는 시스템이 주어진 문제를 얼마나 정확하게 해결할 수 있는지를 나타내는 정도이다. 시험에서는 처리 능력·반환 시간·사용 가능도·신뢰도 네 가지 항목의 정의를 서로 구분하여 묻는 문제가 자주 출제되므로 각 용어의 영문 명칭과 의미를 정확히 암기해 두어야 한다."]]}]},{"t":"(2) 1950~1960년대의 운영체제","c":[{"t":"① 일괄처리·버퍼링·스풀링 등장","n":[["설명","일괄 처리, 버퍼링, 스풀링 1950년대에는 일괄 처리 시스템(Batch Processing System), 버퍼링(Buffering), 스풀링(Spooling)이 등장하였다. 일괄 처리 시스템은 데이터를 모아 두었다가 한꺼번에 묶어서 처리하는 방식이며, 버퍼링은 입출력장치와 프로세서의 속도 차이를 보완하기 위하여 다음에 처리할 레코드를 주기억장치의 버퍼에 미리 보관해 둠으로써 CPU가 기다림 없이 데이터를 전달받을 수 있도록 하는 기법이다. 스풀링은 버퍼링과 달리 주기억장치 대신 디스크를 매우 큰 버퍼처럼 사용하는 기법으로, 여러 작업의 입출력과 계산을 동시에 진행할 수있다는 장점이 있다. 1960년대에는 다중 프로그래밍(Multiprogramming), 시분할 시스템(Time Sharing System), 다중 처리 시스템(Multiprocessing System), 실시간 시스템(Real-Time System)이 발전하였다. 다중 프로그래밍은 여러 프로그램을 메모리에 나누어 적재한 뒤 CPU를 번갈아 할당하여 여러 프로그램을 동시에 실행하는 것처럼 보이게 하는 방식이며, 시분할 시스템은 다중 프로그래밍을 확장하여 프로세서 스케줄링 개념을 더한 시스템으로, 여러 사용자에게 짧은 간격으로 프로세서를 번갈아 할당함으로써 사용자 각자가 마치 컴퓨터를 독점하는 것처럼 느끼게 한다. 다중 처리 시스템은 하나의 시스템 안에서 여러 개의 프로세서를 사용하는 시스템이며, 실시간 시스템은 데이터가 발생하는 즉시 응답하는 시스템이다."]]},{"t":"② 다중 모드·범용 시스템 등장","n":[["설명","다중 모드와 범용 시스템 1970년대 초반에는 일괄·시분할·실시간·다중 처리 방식을 모두 제공하는 다중 모드(Multi Mode) 시스템과, 특별히 정해진 용도로만 사용되는 것이 아니라 메모리에 적재되어 실행되는 프로그램에 따라 여러 용도로 활용할 수 있는 범용 시스템(General Purpose System)이 등장하였다. 다중 모드 시스템은 고가이며 계획한 시간과 예산을 초과하여 완성되는 경우가 많았고 사용에 고도의 훈련이 필요하였다. 1970년대 중반 이후에는 독립적인 처리 능력을 가진 컴퓨터들을 통신망으로 연결하여 네트워크 상에서 서로 통신하며 협력하여 처리하는 분산 처리 시스템(Distributed Processing System)과, 하나 이상의 연산을 동시에 수행하여 연산 속도를 증가시키는 병렬 처리 시스템(Parallel Processing System)이 발전하였다. 2000년대 이후에는 특정 기능을 수행하도록 장치 내에 내장되는 임베디드(Embedded) 시스템, 물리적 하드웨어를 사용자로부터 은폐하여 논리적인 자원으로 제공하는 가상화(Virtualization) 기술, 그리고 인터넷을 기반으로 컴퓨팅 자원을 제공하는 클라우드 컴퓨팅(Cloud Computing)이 크게 발전하였다."]]}]}]}]},{"t":"Ⅱ 운영체제의 계열별 특징","c":[{"t":"1. Windows 계열","c":[{"t":"(1) Windows의 역사와 특징","c":[{"t":"① Windows 95 이후 GUI 발전","n":[["설명","Windows의 발전 과정 마이크로소프트(Microsoft)사는 1995년 윈도우 95(Windows 95)를 발표한 이후 지속적으로 98, ME, XP, 7, 8, 10 등의 버전을 출시하며 발전시켜 왔다. Windows는 사용자가 마우스로 아이콘을 클릭하여 소프트웨어를 실행하는 편리한 그래픽 인터페이스가 특징이며, 마이크로소프트사만이 소스코드를 수정하고 배포할 수 있어 고객 지원이 체계적이라는 장점을 가진다. Windows는 문제점(버그 등)이 발견되었을 때 이를 수정하는 데 다소 시간이 걸린다는 단점이 있으며, 문제 발생과 해결 사이의 시간차를 악용하는 해커들로 인하여 유닉스 계열에 비하여 보안에 상대적으로 취약하다는 지적을 받는다. 그럼에도 불구하고 직관적인 사용자 인터페이스 덕분에 일반 개인 사용자들에게 가장 널리 보급된 운영체제로 자리잡고 있다."]]},{"t":"② 선점형 멀티태스킹·PnP","n":[["설명","선점형 멀티태스킹과 PnP 선점형 멀티태스킹(Preemptive Multitasking)이란 운영체제가 수행 중인 각 프로그램의 실행 시간을 할당하고, 실행 도중 문제가 발생하면 해당 프로그램을 강제로 종료시킨 후 모든 시스템 자원을 회수하는 멀티태스킹 운영 방식이다. PnP(Plug and Play)는 장치와 장치를 연결할 때 별도의 사용자 조작 없이도 운영체제가 자동으로 장치를 인식하여 사용할 수 있게 해 주는 기능이다. 시스템 전원이 켜진 상태에서 장치를 추가하는 것은 가능하나 제거하는 것은 불가능한 것을 핫플러그(Hot Plug)라 하고, 전원이 켜진 상태에서도 장치를 자유롭게 교체할 수 있는 것을 핫스왑(Hot Swap)이라 하여 서로 구분한다. FAT(File Allocation Table) 파일 시스템은 파일 할당 테이블을 이용하여 운영체제를 운용하는 데 필요한 디스크 공간을 할당하는 전통적인 파일 시스템이며, NTFS(New Technology File System)는 Windows 가 현재 주로 사용 중인 압축 파일 시스템으로 FAT에 비하여 신뢰성과 성능이 개선되어 디스크 공간을 효율적으로 사용할 수 있다. ReFS(Resilient File System)는 마이크로소프트가 NTFS를 대체하기 위해 개발한 차세대 파일 시스템이다."]]}]},{"t":"(2) UNIX 계열","c":[{"t":"① UNIX: Multics 기원·커널/쉘","n":[["설명","UNIX의 역사와 구성 UNIX는 1960년대 AT&T의 벨(Bell) 연구소, MIT, General Electric의 공동 연구로 개발이 착수되어 멀티 태스크 기능에 초점을 맞춘 초기 운영체제 Multics로부터 출발하였다. 이후 C언어로 재이식되어 대중화의 기반을 마련하였고, 1970년대에 AT&T가 본격적으로 유닉스 시스템을 판매하였다. UNIX는 커널(Kernel, 프로세스 수행에 필요한 하드웨어 성능을 조정하는 핵심 요소), 쉘(Shell, 실행할 프로세스를 커널에 전달할수 있도록 번역해 주는 명령 해석기), 유틸리티(Utility, 운영체제가 기본 제공하는 것 이외의 실행 가능한 프로그램)로 구성된다. UNIX는 사용자에게 컴퓨터 자원을 시간에 따라 분할하여 제공하는 시분할 시스템의 대표적인 예이며, 디스크 기반의 UFS(UNIX File System) 파일 시스템과 자료 구조 시스템인 아이노드(i-node)를 사용한다. 원본을 유지시킨 채 연결하는 소프트 링크(심볼릭 링크)와, 원본과 완전히 동기화되어 원본 삭제 시 함께 삭제되는 하드 링크로 파일을 연결할 수 있다. 대표적인 UNIX 제품으로는 IBM의 AIX, 오라클의 솔라리스(Solaris), HP의 HP-UX 등이 있으며, System V 계열과 BSD(Berkeley Software Distribution) 계열로 발전해 오다가 현재는 두 계열의 장점을 통합한 버전이 배포되고 있다."]]},{"t":"② Linux: 1991 토발즈 자유SW","n":[["설명","Linux의 특징 리눅스(Linux)는 UNIX의 호환 커널로서, 1991년 리누스 토발즈(Linus Torvalds)가 자유 소프트웨어(Free Software) 정책 아래 완전히 자유롭게 배포할 수 있는 운영체제로 개발하였다. 수천 명 이상의 개발자가 코드를 검토하고 업데이트하고 있어 버그 발생 시 빠른 수정이 가능하지만, Windows와 같은 체계적인 지원이 상대적으로 부족하여 일반 사용자보다는 전문가들이 주로 사용한다. 데비안, 레드햇, Fedora, Ubuntu, CentOS 등 다양한 회사에서 각기 다른 배포 정책으로 출시하고 있으며, 서버 시장과 슈퍼컴퓨터 시장에서 매우 높은 점유율을 보유하고 있다. 매킨토시 운영체제(OS X)는 UNIX를 기반으로 만들어져 애플(Apple)사 제품군에서만 사용할 수 있는 그래픽 기반 운영체제이다. 애플사는 자사의 운영체제를 오랜 기간 유지해 오다가 1999년 OS X로 업데이트하였 으며, 이후 클라이언트 버전과 서버 제품 등으로 제품군을 확대하였다. 매킨토시 OS는 프로그램을 폴더에 복사하거나 삭제함으로써 설치(Install)와 제거(Uninstall) 과정을 단순화하였다는 특징이 있다."]]}]}]}]},{"t":"Ⅲ 운영체제 제어 방식과 명령어","c":[{"t":"1. CLI와 GUI","c":[{"t":"(1) 운영체제 제어 방법의 개념","c":[{"t":"① CLI: 키보드 명령어 입력 방식","n":[["설명","CLI(Command Line Interface) CLI는 사용자가 키보드로 직접 명령어를 입력하여 컴퓨터에게 작업을 지시하는 방식이다. 초기의 운영체제들은 대부분 CLI 기반으로 사용자와 상호작용하였으나, 이후 마우스를 이용한 제어 방식인 GUI가 개발되면서 CLI의 사용 빈도가 한동안 하락하였다. 다만 최근에는 오픈소스 기반의 개발 환경이 급격히 확산되고 GitHub와 같은 도구의 사용이 늘어나면서, CLI의 기본 개념과 명령어의 중요성이 다시 부각되고 있다. GUI는 마우스로 화면의 아이콘이나 메뉴를 클릭하여 컴퓨터를 제어하는 방식이다. Windows 환경에서는 파일 이동이나 프로그램 실행 등 대부분의 작업이 GUI 명령에 해당하며, 메모리나 디스크 제어와 같은 세부 설정이 필요한 경우에는 제어판에서 원하는 기능을 선택하여 명령을 내린다. 리눅스의 GUI는 Windows처럼 항상 기본으로 설정되어 있지는 않아, 배포판이나 버전에 따라 별도의 설치 절차를 거쳐야 하는 경우가 많다."]]},{"t":"② 리눅스 경로 / 구분·주요 디렉터리","n":[["설명","디렉터리 표기 방식 리눅스의 디렉터리는 Windows의 폴더와 같은 개념이다. Windows에서는 경로 구분에 원화(₩) 기호나 역슬래시(\\)를 사용하지만, 리눅스에서는 슬래시(/)를 사용한다는 문법적 차이가 있다. 최상위 디렉터리는 슬래시(/) 하나로 표기하며, root는 최상위 디렉터리 아래에 위치한 슈퍼유저(root) 계정의 홈 디렉터리를 의미한다. etc 디렉터리는 시스템 환경 및 주요 설정 파일을 보관하고, tmp는 임시 파일을 보관하며, lib는 프로그램 모듈을 보관한다. usr는 사용자가 활용하는 파일을 보관하고, dev는 물리적 장치 제어를 위한 파일을 보관하며, home은 각 사용자의 작업 디렉터리이다. boot는 커널을 위한 프로그램 파일을 보관하고, root는 슈퍼유저의 홈 디렉터리이며, sbin은 슈퍼유저가 사용하는 명령어를 저장하는 디렉터리이고, var는 시스템 동작 중 변화하는 파일을 저장한다."]]}]},{"t":"(2) CLI 대표 명령어","c":[{"t":"① cd·dir/ls·copy/cp· mkdir 대응","n":[["설명","경로·목록·파일 관련 명령어 경로를 변경할 때는 Windows와 리눅스 모두 cd 명령어를 사용하며, 목록을 출력할 때는 Windows에서는 dir을, 리눅스에서는 ls를 사용한다. 파일을 복사할 때는 Windows의 copy에 대응하여 리눅스는 cp를 사용하고, 구조 전체를 복사할 때는 Windows의 xcopy에 대응하여 리눅스는 마찬가지로 cp를 사용한다. 디렉터리를 생성할 때는 두 운영체제 모두 mkdir을 사용하며, 하위 파일을 삭제할 때는 Windows의 del에 대응하여 리눅스는 rm을 사용한다. 권한을 설정할 때는 Windows의 attrib에 대응하여 리눅스는 chmod를 사용하고, 화면에 파일 내용을 표시할 때는 Windows의 type에 대응하여 리눅스는 cat을 사용한다. 목적지까지의 경로를 추적할 때는 Windows의 tracert에 대응하여 리눅스는 traceroute를 사용한다. 리눅스에는 이 외에도 프로세스를 종료하는 kill, 실행 중인 프로세스를 표시하는 ps, 디렉터리 경로를 표시하는 pwd, 네트워크 상태를 점검하는 ping, 접속해 있는 사용자를 표시하는 who 등의 명령어가 있다."]]},{"t":"② Ctrl·Alt·윈도우키 단축키","n":[["설명","편집 관련 단축키 Windows에서 Ctrl+C는 복사, Ctrl+X는 잘라내기(오려두기), Ctrl+V는 붙여넣기, Ctrl+Z는 작업 취소(실행 취소), Ctrl+A는 모두 선택, Ctrl+W는 활성화된 창 닫기 기능을 수행한다. Alt+F4는 실행 중인 프로그램을 종료하며, Alt+Tab은 실행 중인 여러 창을 서로 전환할 때 사용한다. Windows 키와 조합하는 단축키로는 화면 캡처(영역 캡처)를 실행하는 윈도우+Shift+S, 윈도우 탐색기를 실행하는 윈도우+E, 실행 창을 여는 윈도우+R, 바탕화면을 표시하는 윈도우+D, 사용자를 전환하거나 화면을 잠그는 윈도우+L, 열려 있는 창을 모두 최소화하는 윈도우+M, 윈도우 검색창을 실행하는 윈도우+S, 가상 데스크톱을 추가하는 윈도우+Ctrl+D 등이 있다."]]}]}]}]},{"t":"Ⅳ 프로세스 관리","c":[{"t":"1. 프로세스의 개념과 상태","c":[{"t":"(1) 프로세스의 개념","c":[{"t":"① 프로세스: 실행 중인 프로그램","n":[["설명","프로세스의 정의 프로그램은 파일 형태로 저장되어 관리되다가 이를 실행시키면 비로소 동작하게 된다. 이처럼 실행 중인 프로그램을 프로세스(Process), 작업(Job) 또는 태스크(Task)라고 한다. 프로세스 관리 기법에는 프로세스의 일시 중지 및 재실행, 동기화, 통신, 교착상태 처리, 프로세스의 생성과 삭제 등이 포함된다. Windows에서는 작업 관리자의 프로세스 탭에서 다양한 프로세스를 조회할 수 있으며, 프로그램이 정상적으로 동작하지 않을때 프로그램 끝내기를 통해 해당 프로세스를 강제로 중단시킬 수 있다."],["실제 사례","프로세스는 생성(Create, 사용자에 의해 프로세스가 만들어진 상태), 준비(Ready, 준비 큐에서 실행을 기다리고 있는 상태), 실행(Running, 준비 큐에 있던 프로세스가 CPU를 할당받아 실제로 실행되는 상태) , 대기(Waiting, 프로세스 수행 중 입출력을 위해 대기 상태로 전이한 상태), 종료(Terminated, 프로세스가 CPU를 할당받아 수행을 마친 상태)의 다섯 단계를 거친다."]]},{"t":"② 디스패치·보류·깨움 상태전이","n":[["설명","디스패치와 보류 디스패치(Dispatch)는 준비(ready) 상태의 프로세스가 실행(running) 상태로 바뀌는 것을 말하며, 보류 (Block)는 프로세스가 실행되는 도중 시간이 다 되기도 전에 입출력 동작을 수행해야 할 경우, 프로세스가 CPU를 반납하고 실행 상태에서 대기(blocked) 상태로 전이하는 것을 말한다. 깨움(Wakeup)은 대기(blocked) 상태에 있던 프로세스가 입출력이 완료된 후 다시 준비(ready) 상태로 넘어가는 것을 말하며, 시간 제한(Timeout)은 클록 인터럽트를 통하여 실행(running) 상태의 프로세스가 일정 시간만 CPU를 점유할 수 있도록 강제로 준비(ready) 상태로 되돌리는 것을 말한다."]]}]},{"t":"(2) 선점형 스케줄링","c":[{"t":"① 선점형: RR·SRT","n":[["설명","RR과 SRT 선점형(Preemptive) 스케줄링은 이미 할당되어 실행 중인 프로세스라도 강제로 빼앗아 다른 프로세스에 자원을 재할당할 수 있는 방식이다. RR(Round Robin, 라운드 로빈)은 순서대로 일정한 시간 단위로 CPU를 할당하는 방식으로, 할당된 시간이 지나면 자원을 반납해야 한다. SRT(Shortest Remaining Time)는 SJF 기법의 장점을 최대화하여 실행 시간이 가장 짧게 남은 프로세스를 우선적으로 처리하는 방식이다. 다단계 큐(Multi-level Queue)는 프로세스를 그룹으로 분류할 수 있을 경우, 그룹에 따라 각기 다른 준비 상태의 큐를 사용하는 기법이다. 다단계 피드백 큐(Multi-level Feedback Queue)는 다단계 큐의 단점을 보완하여, 프로세스가 큐들 사이를 이동할 수 있도록 개선한 기법이다."]]},{"t":"② 비선점형: FIFO(FCFS)·S JF","n":[["설명","FIFO(FCFS)와 SJF 비선점형(Non-preemptive) 스케줄링은 이미 실행 중인 프로세스를 강제로 빼앗아 사용할 수 없는 방식이다. FIFO(First In First Out, FCFS라고도 함)는 선입선출 방식으로, 우선순위와 상관없이 준비 큐에 먼저 도착한 프로세스부터 순서대로 처리한다. SJF(Shortest Job First)는 CPU 점유 시간이 가장 짧은 프로세스를 먼저 할당하는 처리 기법이다. HRN(Highest Response-ratio Next)은 SJF 기법을 보완하여 대기시간과 실행시간을 함께 고려한 처리 기법으로, (대기시간 + 실행시간) ÷ 실행시간의 공식으로 우선순위 점수를 계산한다. 우선순위(Priority) 기법은 준비 상태의 프로세스마다 우선순위를 부여하여 가장 높은 우선순위를 가진 프로세스부터 할당하는 기법이다."]]}]}]}]},{"t":"Ⅴ 메모리 관리와 가상화·클라우드","c":[{"t":"1. 메모리 관리","c":[{"t":"(1) 메모리 관리의 개념","c":[{"t":"① 실행 종료까지 메모리 가용 유지","n":[["설명","메모리 관리의 필요성 메모리 안에는 다수의 프로그램이 동시에 실행되는데, 프로그램이 실행되는 동안 메모리가 가득 차게 되면 시스템의 속도가 느려지거나 때로는 시스템이 멈추는 현상이 발생할 수 있다. 따라서 프로그램의 실행이 종료될 때까지 메모리를 가용한 상태로 유지하고 관리하는 것을 메모리 관리라고 한다."],["실제 사례","메모리에 적재되어 있는 프로그램은 중앙처리장치인 CPU로 이동하여 실제 처리가 이루어진다. 초기에는 메모리 용량에 제한이 많아 소프트웨어를 개발할 때 메모리 관리가 매우 중요한 과제였으나, 최근에는 운영체제가 대부분의 메모리 관리를 자동으로 수행해 주므로 사용자의 편의성이 크게 증대되었다. 또한 개발 및시스템 환경이 클라우드화되면서 자원 관리에 필요한 노력도 함께 줄어드는 추세이다."]]}]},{"t":"(2) 가상화","c":[{"t":"① 가상화: 서버 가동률 20%→60~70%","n":[["설명","가상화의 개념 가상화(Virtualization)란 물리적인 리소스를 사용자에게 하나로 보이게 하거나, 반대로 하나의 물리적인 리소스를 여러 개로 보이게 하는 기술을 의미한다. 대부분의 서버는 전체 용량의 약 20% 정도만을 사용하는 경우가 많은데, 가상화를 활용하면 서버의 가동률을 60~70% 이상으로 끌어올릴 수 있다는 실질적인 이점이 있다."],["실제 사례","플랫폼 가상화는 하드웨어 플랫폼 위에서 실행되는 호스트 프로그램이 게스트 프로그램을 만들어 마치 독립된 실행 환경인 것처럼 보이게 하는 방식이다. 리소스 가상화는 메모리, 저장 장치, 네트워크 등을 결합하거나 나누는 것으로, 사용자는 자신이 사용하는 자원이 실제로 어느 물리적 장치에 위치하는지 알지 못하는 경우가 많다. 앞서 다룬 가상화 방식 중 호스트 OS형은 기존 운영체제 위에 가상화 소프트웨어와 가상머신을 설치하는 방식이며, 하이퍼바이저형은 호스트 OS 없이 물리 하드웨어를 직접 제어하여 독립적인 호스트처럼 동작하는 방식이고, 컨테이너형은 미리 구축된 가상화 소프트웨어(컨테이너)를 이용하는 방식이다."]]},{"t":"② 클라우드 컴퓨팅·IaaS 관리범위 최대","n":[["설명","클라우드 컴퓨팅의 개념 클라우드 컴퓨팅은 인터넷을 기반으로 구동되는 컴퓨팅 기술로, 응용 프로그램을 필요에 따라 자유롭게 불러와 사용하고 데이터를 손쉽게 저장하고 추출할 수 있게 해 준다. 태블릿과 휴대폰 등 사용 기기가 다양해지면서 클라우드 컴퓨팅의 중요도는 계속하여 높아지고 있다. IaaS(Infrastructure as a Service, 인프라형)는 사용자가 관리할 수 있는 범위가 가장 넓은 클라우드 서비스로, 웹상에서 구글·마이크로소프트·아마존 등이 제공하는 네트워크, 보안, 데이터 저장소 등 다양한 인프라를 임대하여 사용할 수 있다. PaaS(Platform as a Service, 플랫폼형)는 운영체제가 이미 구성되어 있는 상태에서 사용자가 데이터와 애플리케이션만 직접 관리할 수 있는 서비스로, 관리상의 자유도는 낮지만 개발 자체에 더 집중할 수 있다는 장점이 있다. SaaS(Software as a Service, 서비스형)는 인프라와 운영체제뿐 아니라 사용할 소프트웨어까지 모두 갖추어져 있어, 사용자는 웹상에서 로그인만으로 다양한 소프트웨어를 사용한 만큼 비용을 지불하며 이용할 수 있다."]]}]}]}]},{"t":"Ⅵ 교착상태(Deadlock)","c":[{"t":"1. 교착상태의 개념과 발생 조건","c":[{"t":"(1) 교착상태의 정의","c":[{"t":"① 교착상태: 자원 무한 대기","n":[["설명","교착상태란"],["쉬운 예","교착상태(Deadlock)란 둘 이상의 프로세스가 서로 상대방이 점유하고 있는 자원을 요구하며 무한정 대기하는 상태를 말한다. 예를 들어 프로세스 A가 자원 1을 점유한 채 프로세스 B가 점유한 자원 2를 요청하고, 동시에 프로세스 B는 자원 2를 점유한 채 프로세스 A가 점유한 자원 1을 요청한다면, 두 프로세스는 서로 상대방이 자원을 반납하기만을 영원히 기다리게 되어 더 이상 진행되지 못한다."]]},{"t":"② 4조건: 상호배제·점유대기·비선점 ·환형대기","n":[["설명","상호배제와 점유대기 교착상태는 네 가지 조건이 동시에 성립할 때 발생한다. 상호배제(Mutual Exclusion)는 한 번에 하나의 프로세스만 자원을 사용할 수 있는 조건이며, 점유대기(Hold and Wait)는 프로세스가 이미 자원을 점유한 상태에서 다른 자원을 추가로 요청하며 대기하는 조건이다. 비선점(Non-preemption)은 프로세스가 점유한 자원을 다른 프로세스나 운영체제가 강제로 빼앗을 수 없는 조건이며, 순환대기(Circular Wait)는 프로세스들이 마치 원을 그리듯 서로가 서로에게 필요한 자원을 요청하며 대기하는 조건이다. 이 네 가지 조건 중 하나라도 성립하지 않도록 만들면 교착상태를 예방할 수 있다."]]}]},{"t":"(2) 예방과 회피","c":[{"t":"① 예방: 4조건 중 하나 제거","n":[["설명","교착상태 예방(Prevention)"],["쉬운 예","교착상태 예방은 앞서 설명한 네 가지 발생 조건 중 하나를 원천적으로 성립하지 못하도록 제한하는 방법이다. 예를 들어 프로세스가 필요한 자원을 처음부터 모두 한꺼번에 할당받도록 하면 점유대기 조건을 제거할 수 있으나, 이 경우 자원의 활용률이 낮아질 수 있다는 단점이 있다."]]},{"t":"② 탐지: 자원할당 그래프 순환","n":[["설명","교착상태 탐지(Detection) 교착상태 탐지는 예방이나 회피 없이 자원을 자유롭게 할당하다가, 주기적으로 시스템의 자원 할당 상태를 검사하여 교착상태의 발생 여부를 확인하는 방법이다. 자원 할당 그래프(Resource Allocation Graph)에서 순환(Cycle)이 발견되면 교착상태가 발생했다고 판단할 수 있다. 교착상태가 탐지된 이후에는 교착상태에 관련된 프로세스 중 일부를 강제로 종료시키거나, 프로세스가 점유하고 있는 자원의 일부를 강제로 회수하는 방식으로 복구를 수행한다. 어떤 프로세스를 종료할지 선택할 때는 프로세스의 우선순위, 지금까지 실행된 시간, 사용 중인 자원의 양 등을 종합적으로 고려한다."]]}]}]}]},{"t":"Ⅶ 가상기억장치와 페이징","c":[{"t":"1. 가상기억장치의 개념","c":[{"t":"(1) 가상기억장치란","c":[{"t":"① 가상기억장치: 보조기억 활용 확장","n":[["설명","가상기억장치의 정의"],["실제 사례","가상기억장치(Virtual Memory)는 실제 물리적인 주기억장치의 용량보다 더 큰 프로그램을 실행할수 있도록, 보조기억장치(디스크)의 일부를 마치 주기억장치처럼 사용하는 기법을 말한다. 사용자와 프로그램 입장에서는 실제 물리적 메모리의 크기와 관계없이 훨씬 큰 논리적인 주소 공간을 사용하는 것처럼 보이게 된다."]]},{"t":"② 페이징: 페이지·프레임·페이지 부재","n":[["설명","페이징의 개념 페이징(Paging)은 가상기억장치를 구현하는 대표적인 기법으로, 프로세스의 논리적 주소 공간을 페이지 (Page)라는 일정한 크기의 단위로 나누고, 물리적 메모리도 프레임(Frame)이라는 동일한 크기의 단위로 나누어 관리하는 방식이다. 프로세스가 실행될 때 필요한 페이지만 물리적 메모리의 프레임에 적재되며, 당장 필요하지 않은 페이지는 디스크에 남아 있게 된다. 프로세스가 현재 메모리에 적재되어 있지 않은 페이지에 접근하려고 하면 페이지 부재(Page Fault)가 발생하며, 이 경우 운영체제는 해당 페이지를 디스크에서 메모리로 적재해야 한다. 이때 메모리에 빈 공간이 없다면 기존에 적재되어 있던 페이지 중 하나를 내보내야 하는데, 어떤 페이지를 내보낼지 결정하는 방법을 페이지 교체 알고리즘이라 하며 FIFO, LRU(Least Recently Used, 가장 오랫동안 사용되지 않은 페이지를 교체) 등의 알고리즘이 대표적이다."]]}]},{"t":"(2) 디스크 스케줄링의 개념","c":[{"t":"① 헤드 이동거리 최소화·FCFS","n":[["설명","디스크 스케줄링의 필요성 디스크 스케줄링이란 여러 개의 디스크 입출력 요청이 동시에 발생했을 때, 디스크의 헤드가 이동하는 거리를 최소화하여 처리 효율을 높이기 위한 순서를 결정하는 기법을 말한다. 디스크는 물리적으로 헤드가 원하는 트랙까지 이동해야 데이터를 읽거나 쓸 수 있으므로, 헤드의 이동 거리를 줄이는 것이 곧 처리 속도의 향상으로 이어진다. FCFS(First Come First Served) 디스크 스케줄링은 요청이 들어온 순서대로 처리하는 가장 단순한 방식이며, SSTF(Shortest Seek Time First)는 현재 헤드의 위치에서 가장 가까운 요청을 우선적으로 처리하는 방식으로 평균 탐색 거리를 줄일 수 있지만 특정 요청이 계속 뒤로 밀리는 기아 현상이 발생할 수 있다."]]},{"t":"② SCAN(엘리베이터)·C-SCAN","n":[["설명","SCAN 기법 SCAN 기법은 디스크의 헤드가 한쪽 방향으로 이동하면서 그 경로에 있는 모든 요청을 처리하고, 끝에 도달하면 방향을 바꾸어 반대쪽으로 이동하며 요청을 처리하는 방식으로, 마치 엘리베이터가 위아래로 움직이는 것과 유사하여 엘리베이터 기법이라고도 불린다. C-SCAN(Circular SCAN)은 SCAN과 달리 헤드가 한쪽 끝에 도달하면 반대 방향으로 요청을 처리하며 이동하는 것이 아니라, 처리 없이 곧바로 시작 위치로 되돌아간 후 다시 같은 방향으로 요청을 처리하는 기법이다. 이를 통해 SCAN 기법보다 응답 시간의 편차를 더욱 균등하게 유지할 수 있다."]]}]}]}]},{"t":"Ⅷ 장치 관리와 인터럽트","c":[{"t":"1. 입출력 장치 관리","c":[{"t":"(1) 입출력 제어 방식","c":[{"t":"① Programmed I/O 폴링·인터럽트 I/O","n":[["설명","프로그램 제어 입출력 프로그램 제어 입출력(Programmed I/O) 방식은 CPU가 직접 입출력 장치의 상태를 계속 확인(폴링)하면서 데이터를 주고받는 방식이다. 구현이 단순하지만 CPU가 입출력 작업이 끝날 때까지 다른 작업을 하지 못하고 대기해야 하므로 CPU 자원을 크게 낭비하게 된다는 단점이 있다. 인터럽트 기반 입출력 방식에서는 CPU가 입출력 장치에 작업을 지시한 뒤 곧바로 다른 작업을 수행하다가, 입출력 작업이 완료되면 장치가 CPU에 인터럽트 신호를 보내 완료 사실을 알린다. 이를 통해 CPU가 입출력 완료를 기다리며 낭비하는 시간을 줄일 수 있다."]]},{"t":"② DMA: CPU 개입 없는 직접 전송","n":[["설명","DMA의 개념"],["실제 사례","DMA는 CPU를 거치지 않고 입출력 장치가 주기억장치에 직접 데이터를 전송할 수 있도록 하는 방식이다. CPU는 DMA 컨트롤러에게 전송할 데이터의 위치와 양만 지시해 주면, 이후의 실제 데이터 전송은 DMA 컨트롤러가 처리하고, 전송이 끝나면 CPU에 인터럽트로 완료를 알린다."]]}]},{"t":"(2) 인터럽트란","c":[{"t":"① 인터럽트: 하드웨어·소프트웨어","n":[["설명","인터럽트의 정의 인터럽트(Interrupt)란 CPU가 현재 수행 중인 작업을 일시적으로 중단하고, 발생한 이벤트를 먼저 처리하도록 하는 신호를 말한다. 인터럽트가 발생하면 CPU는 현재까지의 작업 상태(레지스터 값 등)를 저장한 뒤, 인터럽트를 처리하는 루틴으로 제어를 넘긴다. 인터럽트는 하드웨어 인터럽트와 소프트웨어 인터럽트로 구분할 수 있다. 하드웨어 인터럽트는 입출력 장치, 타이머 등 외부 장치에서 발생하며, 소프트웨어 인터럽트는 프로그램 실행 중 0으로 나누기와 같은 오류가 발생하거나, 프로그램이 운영체제의 서비스를 요청(시스템 콜)할 때 발생한다."]]},{"t":"② 인터럽트 벡터 테이블·ISR·우선 순위","n":[["설명","인터럽트 벡터와 처리 루틴각 인터럽트에는 고유한 번호가 부여되며, 이 번호에 대응하는 인터럽트 처리 루틴(Interrupt Service Routine)의 주소가 인터럽트 벡터 테이블에 저장되어 있다. 인터럽트가 발생하면 CPU는 이 테이블을 참조하여 해당하는 처리 루틴으로 이동해 인터럽트를 처리한다. 여러 인터럽트가 동시에 발생하는 경우를 대비하여, 각 인터럽트에는 우선순위가 부여되어 있다. 우선순위가 높은 인터럽트가 먼저 처리되며, 특히 중요한 인터럽트를 처리하는 중에는 우선순위가 낮은 다른 인터럽트가 끼어들지 못하도록 일시적으로 인터럽트를 금지하는 기법도 사용된다."]]}]}]}]},{"t":"Ⅸ 운영체제의 보안과 사용자 관리","c":[{"t":"1. 사용자 계정과 권한 관리","c":[{"t":"(1) 사용자 인증","c":[{"t":"① 인증: 사용자 신원 확인","n":[["설명","인증의 개념"],["실제 사례","사용자 인증(Authentication)이란 시스템에 접근하려는 사용자가 실제로 본인이 맞는지를 확인하는 절차를 말한다. 가장 일반적인 인증 방식은 아이디와 비밀번호를 이용하는 것이지만, 최근에는 지문이나 얼굴 인식과 같은 생체 인증, 또는 별도의 인증 앱을 이용하는 다중 인증(MFA, Multi-Factor Authentication) 방식도 널리 사용된다."],["쉬운 예","권한 부여는 인증된 사용자가 시스템 내에서 어떤 자원에 접근할 수 있고 어떤 작업을 수행할 수 있는지를 결정하는 절차이다. 예를 들어 일반 사용자 계정은 시스템 설정 파일을 수정할 수 없지만, 관리자 (Administrator, root) 계정은 시스템의 모든 자원에 접근하고 수정할 수 있는 권한을 갖는다."]]},{"t":"② DAC 소유자 권한 부여·MAC","n":[["설명","임의적 접근 제어(DAC) DAC(Discretionary Access Control)는 자원의 소유자가 그 자원에 대한 접근 권한을 직접 다른 사용자에게 부여하거나 제한할 수 있는 접근 제어 방식이다. 유닉스나 리눅스의 파일 소유자가 다른 사용자에게 읽기, 쓰기, 실행 권한을 부여하는 방식이 대표적인 DAC의 예이다. MAC(Mandatory Access Control)는 시스템 관리자가 미리 정해 놓은 보안 정책에 따라 접근 권한이 강제로 결정되며, 일반 사용자나 자원 소유자가 임의로 권한을 변경할 수 없는 방식이다. 군사, 정부 기관과 같이 매우 엄격한 보안이 요구되는 환경에서 주로 사용된다."]]}]},{"t":"(2) 주요 보안 위협","c":[{"t":"① 악성코드·권한 상승 공격","n":[["설명","악성코드 악성코드(Malware)는 사용자의 동의 없이 시스템에 침투하여 피해를 입히는 프로그램을 통칭하는 용어로, 스스로를 복제하여 확산하는 바이러스, 사용자 몰래 자료를 유출하는 스파이웨어, 파일을 암호화하고 금전을 요구하는 랜섬웨어 등이 대표적이다. 권한 상승(Privilege Escalation) 공격은 일반 사용자 권한으로 시스템에 침투한 공격자가, 운영체제나 응용 프로그램의 취약점을 악용하여 관리자 권한과 같은 더 높은 권한을 획득하려는 공격을 말한다. 이를 막기 위해서는 운영체제와 소프트웨어를 최신 상태로 업데이트하여 알려진 취약점을 제거하는 것이 중요하다."]]},{"t":"② 최소 권한 원칙·보안 패치","n":[["설명","최소 권한의 원칙 최소 권한의 원칙(Principle of Least Privilege)은 각 사용자나 프로세스에게 작업 수행에 꼭 필요한 최소한의 권한만 부여해야 한다는 보안 원칙이다. 이를 통해 특정 계정이나 프로세스가 공격당하더라도 피해 범위를 최소화할 수 있다. 운영체제 제조사는 새롭게 발견된 취약점에 대응하기 위해 지속적으로 보안 패치를 배포하며, 시스템 관리자는 이러한 패치를 신속하게 적용하고, 정기적으로 시스템의 보안 설정과 로그를 점검하여 잠재적인 위협을 조기에 발견해야 한다."]]}]}]}]},{"t":"Ⅹ 스레드와 병렬 처리","c":[{"t":"1. 스레드(Thread)의 개념","c":[{"t":"(1) 프로세스와 스레드의 차이","c":[{"t":"① 스레드: 프로세스 내 실행 단위","n":[["설명","스레드란"],["실제 사례","스레드는 프로세스 내에서 실제로 실행되는 흐름의 단위로, 하나의 프로세스는 하나 이상의 스레드를 가질 수 있다. 프로세스가 자신만의 독립된 메모리 공간을 갖는 것과 달리, 같은 프로세스에 속한 여러 스레드는 코드, 데이터, 힙 영역과 같은 메모리 자원을 공유하면서도 각자 독립적인 스택과 레지스터 값을 갖는다."]]},{"t":"② 경쟁 상태: 공유자원 동시접근","n":[["설명","경쟁 상태(Race Condition)"],["쉬운 예","여러 스레드가 공유 자원에 동시에 접근하여 값을 읽고 쓰는 과정에서, 실행 순서에 따라 결과가 달라지는 문제를 경쟁 상태라고 한다. 예를 들어 두 스레드가 동시에 같은 은행 계좌 잔액을 읽어 각자 차감 연산을 수행한 뒤 저장하면, 하나의 차감 내역이 반영되지 않고 사라지는 오류가 발생할 수 있다."]]}]},{"t":"(2) 멀티코어와 병렬 처리","c":[{"t":"① 멀티코어·암달의 법칙","n":[["설명","멀티코어 프로세서 멀티코어 프로세서는 하나의 CPU 칩 안에 독립적으로 연산을 수행할 수 있는 여러 개의 코어를 탑재한 프로세서를 말한다. 운영체제는 여러 코어에 프로세스나 스레드를 적절히 분배하여 동시에 실행함으로써 전체적인 처리 성능을 향상시킬 수 있다. 모든 작업이 병렬로 처리될 수 있는 것은 아니며, 작업 간에 순차적으로 처리되어야 하는 의존 관계가 있는 부분은 아무리 코어 수를 늘려도 성능 향상에 한계가 있다. 이를 설명하는 대표적인 이론으로 암달의 법칙 (Amdahl 법칙)이 있으며, 이는 프로그램에서 병렬화할 수 없는 부분의 비율이 전체 성능 향상의 한계를 결정한다는 내용을 담고 있다."]]},{"t":"② 병렬(1대) vs 분산(다수) 처리","n":[["설명","병렬 처리와 분산 처리의 차이 병렬 처리는 하나의 컴퓨터 내에서 여러 개의 처리 장치가 동시에 작업을 수행하는 것을 의미하며, 분산 처리는 물리적으로 분리된 여러 대의 컴퓨터가 네트워크로 연결되어 하나의 작업을 나누어 처리하는 것을 의미한다는 점에서 개념적으로 구분된다. 대용량 데이터를 처리하는 빅데이터 환경에서는 하나의 컴퓨터만으로 처리하기 어려운 경우가 많아, 여러 대의 서버에 데이터와 연산을 분산시켜 병렬로 처리하는 분산 처리 프레임워크(예: 하둡, 스파크)가 널리 활용되고 있다."]]}]}]}]}]},{"t":"제2절 네트워크의 이해와 활용","c":[{"t":"Ⅰ 네트워크의 개념과 계층 구조","c":[{"t":"1. 네트워크의 기본 개념","c":[{"t":"(1) 네트워크와 프로토콜","c":[{"t":"① 네트워크·프로토콜·LAN/WAN","n":[["설명","네트워크의 정의 네트워크(Network)란 원하는 정보를 원하는 수신자 또는 기기에 정확하게 전송하기 위한 기반 인프라를 말한다. 네트워크를 통하여 정보를 주고받을 때는 미리 약속된 규칙을 따라야 하는데, 이러한 통신 규칙의 체계를 프로토콜(Protocol)이라고 한다. LAN(Local Area Network, 근거리 네트워크)은 한 건물 또는 작은 지역을 커버하는 네트워크이며, WAN(Wide Area Network, 광대역 네트워크)은 국가나 대륙과 같이 광범위한 지역을 연결하는 네트워크이다. WAN은 LAN에 비하여 전송 거리가 넓고 라우팅 알고리즘이 필요하며, 거리에는 제약이 없지만 다양한 경로를 거쳐 정보가 전달되므로 LAN보다 속도가 느리고 오류율이 높다는 특징이 있다."]]},{"t":"② 회선 교환(고정 대역폭) vs 패킷 교환","n":[["설명","회선 교환 방식 회선 교환 방식은 물리적인 전용선을 활용하여 데이터가 전달될 경로를 미리 정한 후, 통신이 이루어지는 동안 동일한 경로로만 데이터를 전달하는 방식이다. 대역폭(데이터를 동시에 전송할 수 있는 양)이 고정되어 있어 안정적인 전송을 확보할 수 있다는 장점이 있다. 패킷 교환 방식은 패킷(Packet)이라는 작은 단위를 사용하여 데이터를 송수신하는 방식으로, 현재 대부분의 컴퓨터 네트워크에서 주로 사용하는 방식이다. 정보를 일정한 크기로 분할한 뒤 각각의 패킷에 수신 주소 및부가 정보를 입력하여 전송하며, 통신이 이루어지는 동안만 네트워크 자원을 사용한다는 특징이 있다."]]}]},{"t":"(2) OSI 참조 모델의 개념","c":[{"t":"① OSI 7계층: ISO 표준 모델","n":[["설명","OSI 7계층의 정의 OSI(Open System Interconnection) 7계층은 국제 표준화 기구인 ISO(International Standardization Organization)에서 개발한 네트워크 계층 표현 모델이다. 각 계층은 서로 독립적으로 구성되면서도, 하위 계층의 기능을 이용하여 상위 계층에 필요한 기능을 제공한다는 원리로 설계되었다."],["실제 사례","1계층인 물리 계층(Physical Layer)은 실제 장비들을 연결하기 위한 연결 장치를 다루며 허브·리피터가 대표적인 장비이다. 2계층인 데이터링크 계층(DataLink Layer)은 오류와 흐름을 제어하여 신뢰성 있는 데이터 전송을 담당하며 브리지·스위치가 대표적인 장비이다. 3계층인 네트워크 계층(Network Layer)은 다수의 중개 시스템 중 올바른 경로를 선택하도록 지원하며 라우터가 대표적인 장비이다. 4계층인 전송 계층(Transport Layer)은 송신·수신 프로세스 간의 연결을 담당하며 TCP·UDP가 대표적인 프로토콜이다."],["시험 포인트","5계층인 세션 계층(Session Layer)은 송신과 수신 간의 논리적 연결을 담당하고, 6계층인 표현 계층(Presentation Layer)은 코드와 문자 등을 번역하여 일관되게 전송하고 압축·해제·보안 기능을 담당한다. 7계층인 응용 계층(Application Layer)은 이메일·웹과 같이 사용자에게 친화적인 환경을 제공하는 계층이다. 시험에서는 각 계층의 순서와 명칭, 그리고 각 계층에서 사용되는 대표 장비 및 프로토콜을 서로 짝짓는 문제가 매우 자주 출제되므로 1계층부터 7계층까지의 순서를 반드시 암기해 두어야 한다."]]}]}]}]},{"t":"Ⅱ 네트워크 주요 장비","c":[{"t":"1. 허브와 리피터","c":[{"t":"(1) 허브(Hub)","c":[{"t":"① 허브: 수신 포트 제외 전송","n":[["설명","허브의 개념 허브는 여러 대의 컴퓨터를 연결하여 네트워크로 데이터를 보내거나, 하나의 네트워크로부터 수신된 정보를 여러 대의 컴퓨터로 송신하기 위한 장비이다. 허브는 수신한 프레임을 수신한 포트를 제외한 모든 포트로 전송하는 방식으로 동작한다. 더미 허브(Dummy Hub)는 데이터를 단순히 연결한 성형 구조로 구성되어 있는 기본적인 허브이며, 스위치 허브(Switch Hub)는 스위치 기능을 함께 가진 허브로서 데이터의 유무와 흐름을 지능적으로 제어할 수 있어 오늘날 사용되는 대부분의 허브가 이 방식에 해당한다."]]},{"t":"② 리피터: 감쇠 신호 재생 중계","n":[["설명","리피터의 개념 리피터는 감쇠된 전송 신호를 새롭게 재생하여 다시 전달하는 재생 중계 장치이다. 허브 등을 통해 통신할 때신호가 먼 거리를 지나며 약해질 수 있는데, 리피터가 이 감쇠된 디지털 신호를 증폭시켜 목적지 컴퓨터에 온전한 신호가 도달할 수 있도록 돕는다. 리피터는 주로 신호가 약해지기 쉬운 장거리 케이블 구간의 중간에 설치되어 네트워크의 전송 거리를 실질적으로 확장하는 역할을 한다."]]}]},{"t":"(2) 브리지(Bridge)","c":[{"t":"① 브리지: SW·저속·1:1 저장후전달","n":[["설명","브리지의 개념 브리지는 두 개의 시스템을 연결하는 네트워킹 장치로, 두 개의 LAN을 연결하여 하나의 더 큰 LAN을 만들어 주는 역할을 한다. 브리지는 소프트웨어 방식으로 동작하며 저속이고, 포트들이 모두 동일한 속도로 데이터를 전송하며 2~3개 정도의 적은 포트를 가진다. 브리지는 목적지 주소를 기준으로 1:1 연결을 수행하며, 데이터를 전부 수신한 후에 처리하는 저장 후 전달 (Store and Forwarding) 방식만을 사용한다."]]},{"t":"② 스위치: HW·고속·1:N 연결","n":[["설명","스위치의 개념 스위치는 하드웨어 방식으로 동작하는 고속 네트워킹 장치로, 포트마다 서로 다른 속도로 데이터를 전송할 수있으며 수백 개 이상의 많은 포트를 가질 수 있다. 목적지 주소를 기준으로 1:N 연결을 지원한다."],["시험 포인트","스위치는 목적지 주소만 확인한 후 바로 데이터를 전송하는 컷 스루(Cut Through) 방식과, 브리지의 저장 후 전달 방식의 장점을 결합한 프래그먼트 프리(Fragment Free) 방식을 함께 사용한다. 브리지와 스위치는 모두 두 개의 LAN을 연결하여 더 큰 네트워크를 구성한다는 공통점이 있으나, 처리 속도와 포트 수, 데이터 처리 방식에서 뚜렷한 차이를 보이므로 시험에서 이러한 비교 문제가 자주 출제된다."]]}]}]}]},{"t":"Ⅲ 네트워크 프로토콜","c":[{"t":"1. 네트워크 프로토콜의 개념과 종류","c":[{"t":"(1) 프로토콜의 개념","c":[{"t":"① 프로토콜: 통신 규약·HTTP·FTP","n":[["설명","네트워크 프로토콜의 정의 네트워크 프로토콜은 컴퓨터나 원거리 통신 장비 사이에서 메시지를 주고받는 양식과 규칙의 체계를 의미한다. 통신 규약에는 전달 방식, 통신 방식, 자료의 형식, 오류 검증 방식, 코드 변환 규칙, 전송 속도 등이 포함된다. 서로 다른 기종의 장비는 각기 다른 통신 규약을 사용할 수 있는데, 프로토콜을 사용하면 서로 다른 기기 간의 정보 전달을 표준화할 수 있다. HTTP는 웹(인터넷) 상에서 데이터를 주고받을 수 있는 프로토콜이며, FTP는 네트워크를 통해 컴퓨터들 간의 파일을 교환하기 위한 프로토콜로 Anonymous FTP는 익명성을 보장한다. Telnet은 원격 통신에 이용되는 프로토콜로 데이터 전송 시 암호화 작업이 없어 보안성이 낮으며 포트 번호는 23번을 사용한다. SSH는 원격 통신에 이용되는 프로토콜로 데이터 전송 시 암호화 작업이 존재하여 보안성이 높으며 포트 번호는 22번을 사용한다. rlogin은 UNIX와 같은 시스템의 같은 네트워크 상에서 사용되는 원격 통신 프로토콜로 포트 번호는 513번이다."]]},{"t":"② TCP 신뢰·UDP 고속·DHCP·ARP","n":[["설명","TCP, UDP와 주소 관련 프로토콜 TCP는 데이터를 주고받는 과정에서 검수 작업을 거쳐 정상적으로 데이터가 전달되었는지 확인하는 신뢰성 있는 데이터 전송 프로토콜이며, UDP는 이러한 확인 과정을 거치지 않아 신뢰성은 떨어지지만 TCP보다 데이터 전송 속도가 빠른 프로토콜이다. DHCP는 각종 TCP/IP 프로토콜 및 IP 주소를 클라이언트에게 자동으로 제공하는 유동 IP 설정 프로토콜이다. ARP(Address Resolution Protocol)는 IP(논리적 주소)에 대응되는 이더넷 카드의 MAC(물리적 주소)을 검색하여 변환해 주는 프로토콜이며, RARP는 ARP와 반대로 MAC 주소를 IP 주소로 변환해 주는 프로토콜이다. SMTP는 전자우편 송신 프로토콜이며, POP3는 전자우편 수신 프로토콜이다. 네트워크 프로토콜이 갖는 공통적인 특징으로는 전송이 가능한 작은 블록으로 나누는 단편화, 단편화된 조각을 원래 데이터로 복원하는 재조립, 상위 계층의 데이터에 정보를 추가하여 하위 계층으로 보내는 캡슐화, 데이터의 전송량과 속도를 제어하는 연결 제어, 오류를 검증하는 오류 제어, 송수신 시점을 맞추는 동기화, 하나의 회선에 여러 기기가 접속할 수 있게 하는 다중화, 송수신지의 주소를 부여하는 주소 지정 등이 있다."]]}]},{"t":"(2) IPv4와 IPv6","c":[{"t":"① IPv4: 8비트×4·약 43억 개","n":[["설명","IP 주소의 개념과 IPv4 IP(Internet Protocol) 주소는 전 세계 컴퓨터에 부여되는 유일한 식별자이며, 각 나라의 공인 기관에서 관리하는데 우리나라는 한국인터넷진흥원(KRNIC)에서 관리한다. IPv4는 인터넷 초기부터 현재까지 널리 사용되고 있는 주소 체계로, 000.000.000.000과 같이 8비트씩 4부분(10진수)으로 표시하며 약 43억 개의 주소를 부여할 수 있다. 최근 인터넷에 연결되는 디바이스가 급격히 증가하면서 IPv4가 제공할 수 있는 주소의 양이 부족해질 것에 대비하여 IPv6가 공표되었다. IPv6는 128비트를 16비트씩 8부분(16진수)으로 표시하며 IPv4에 비해 압도적으로 많은 주소를 제공하고, 효율적인 패킷 처리와 강화된 보안이라는 특징을 가진다. 두 주소 체계는 현재 공존하고 있으며, 이를 서로 변환해 주는 기술을 NAT(Network Address Translator)라고 한다."]]},{"t":"② 클래스 A 0~·B 128~·C 192~223","n":[["설명","클래스 A, B, C 네트워크 단말의 수가 증가하면서 가용한 IPv4 주소가 부족해졌고, 이에 사용 목적에 따라 IP 대역대를 나누어 규모별로 관리하기 쉽게 표현한 것이 네트워크 클래스이다. 클래스 A는 IP 주소 첫 번째 바이트가 0~127 로 대형 기관(대륙 간) 연결에 사용되고, 클래스 B는 128~191로 중형 기관(국가 간) 연결에, 클래스 C는 192~223으로 소형 기관(기업 간) 연결에 사용된다."],["시험 포인트","클래스 D는 IP 주소 첫 번째 바이트가 224~239로 그룹 통신 및 멀티캐스트 용도로 사용되며, 클래스 E는 240~254로 연구 및 실험용으로 예약되어 있다. 시험에서는 특정 IP 주소를 보고 어느 클래스에 속하는지 판별하는 문제가 자주 출제되므로 각 클래스의 첫 번째 바이트 범위를 정확히 암기해야 한다."]]}]}]}]},{"t":"Ⅳ TCP/IP 프로토콜","c":[{"t":"1. TCP/IP의 구조","c":[{"t":"(1) TCP/IP 4계층","c":[{"t":"① TCP/IP: 관련 프로토콜 통칭·4계층","n":[["설명","TCP/IP의 개념 TCP/IP란 TCP와 IP 두 프로토콜만을 지칭하는 것이 아니라, UDP(User Datagram Protocol), ICMP(Internet Control Message Protocol), ARP(Address Resolution Protocol), RARP(Reverse ARP) 등 관련된 여러 프로토콜을 통칭하는 개념이다. TCP/IP는 네트워크 액세스(Network Access), 인터넷(Internet), 전송(Transport), 응용(Application)의 4계층으로 구성된다. OSI 7계층의 물리·데이터링크 계층은 TCP/IP의 네트워크 액세스 계층에, OSI의 네트워크 계층은 TCP/IP의 인터넷 계층에, OSI의 전송 계층은 TCP/IP의 전송 계층에, OSI의 세션·표현·응용 계층은 TCP/IP의 응용 계층에 각각 대응된다. TCP와 UDP로 구분되는 프로토콜은 전송 계층에서 응용 계층과 인터넷 계층 사이의 통신을 담당한다."]]},{"t":"② 계층별 프로토콜: HTTP·TCP·IP","n":[["설명","응용 계층과 전송·인터넷 계층 TCP/IP의 응용 계층에서는 HTTP, FTP, DNS, SMTP, SNMP, SSL, telnet, POP3, SSH 등의 프로토콜이 사용되며, 전송 계층에서는 TCP와 UDP가 사용된다. 인터넷 계층에서는 ICMP, IGMP, IP, ARP가 사용된다."],["실제 사례","네트워크 액세스 계층에서는 Ethernet, Token Ring, Frame Relay, ATM 등의 기술이 사용되어 실제 물리적인 데이터 전송을 담당한다."]]}]},{"t":"(2) TCP(Transmission Control Protocol)","c":[{"t":"① TCP: CRC·재전송·흐름 제어","n":[["설명","TCP의 특징 TCP는 수신 측의 수신 가능 상태와 수신 여부 등을 단계별로 확인해 가며 데이터를 전송하는 프로토콜로, CRC 체크와 재전송 기능을 통해 신뢰성 있는 전송을 확보한다. Flow Control(흐름 제어) 기능을 수행하여 단계별 데이터 전송 상황을 체크하며, 논리적인 1:1 가상 회선을 지원하여 정해진 경로로만 데이터를 전달한다. TCP를 사용하는 대표적인 서비스로는 FTP, Telnet, HTTP, SMTP, POP, IMAP 등이 있으며, 이들은 모두 데이터의 정확한 전달이 중요한 서비스라는 공통점을 가진다."]]},{"t":"② UDP: 흐름·오류 제어 없음·고속","n":[["설명","UDP의 특징 UDP는 연결되어 있으면 데이터를 송신할 수는 있으나 수신 여부를 확인하기 어려운 프로토콜이다. Flow Control이나 Error Control을 수행하지 않아 신뢰성 있는 데이터 전송에는 부적합하지만, 확인 과정을 거치지 않기 때문에 TCP보다 전송 속도가 빠르다는 장점이 있다."],["시험 포인트","UDP는 하나의 송신 정보를 다수의 인원이 동시에 수신해야 하는 경우에 주로 사용되며, 대표 서비스로는 SNMP, DNS, TFTP, NFS, NETBIOS, 인터넷 게임·방송·증권 시세 서비스 등이 있다. TCP와 UDP는 모두 전송 계층 프로토콜이라는 공통점이 있으나, 신뢰성과 속도라는 상반된 특성을 각각 가진다는 점에서 시험에 자주 비교 출제된다."]]}]}]}]},{"t":"Ⅴ 네트워크 핵심 알고리즘","c":[{"t":"1. 패킷 스위칭과 서킷 스위칭","c":[{"t":"(1) 패킷 스위칭(패킷 교환)","c":[{"t":"① 패킷 스위칭·X.25","n":[["설명","패킷 스위칭의 개념 패킷 스위칭은 작은 블록의 패킷으로 데이터를 전송하며, 데이터를 전송하는 동안만 네트워크 자원을 사용하도록 하는 통신 방식으로 현재 가장 많은 사람들이 사용하는 방식이다. 정보 전달의 단위인 패킷은 여러 통신 지점(Node)을 연결하는 데이터 연결 상의 모든 노드들 사이에서 개별적으로 경로가 제어된다. X.25는 패킷이라는 데이터 블록을 사용하여 대용량 데이터를 다수의 패킷으로 분리하여 송신하며 수신 측에서 다시 결합하는 방식으로, OSI 계층 중 1~3계층까지를 담당한다. 프레임 릴레이는 ISDN을 사용하기 위한 프로토콜로 X.25와 달리 사용자의 요청에 따라 유연한 대역폭을 할당하며 OSI 계층 중 1~2계층만을 담당한다. ATM(Asynchronous Transfer Mode)은 비동기 전송 모드라고 하는 광대역 전송용 스위칭 기법으로, 동기화를 맞추지 않아 데이터가 없는 사용자의 슬롯을 다른 사용자가 활용할 수 있게 하여 네트워크의 효율성을 높인다."]]},{"t":"② 서킷 스위칭: 자원 독점·전송 보장","n":[["설명","서킷 스위칭의 개념 서킷 스위칭은 패킷 스위칭과 달리 네트워크 리소스를 특정 사용자가 독점하도록 하는 방식을 의미한다. 네트워크를 독점적으로 사용하기 때문에 전송이 보장(Guaranteed)된다는 장점이 있다."],["실제 사례","서킷 스위칭은 서킷을 확보하기 위한 작업을 진행하고, 실제 데이터를 전송하며, 통신이 끝나면 서킷을 닫는 순서로 진행된다. 이러한 작업이 진행되는 동안에는 다른 기기들이 해당 경로를 사용할 수 없다는 특징이 있다."]]}]},{"t":"(2) 라우팅 알고리즘","c":[{"t":"① 거리 벡터: 이웃에 전체 테이블","n":[["설명","거리 벡터 알고리즘 라우팅 알고리즘은 데이터가 송신 측으로부터 수신 측까지 전달되는 과정에서 목적지까지의 최적 경로를 산출하기 위한 법칙이다. 거리 벡터 알고리즘(Distance Vector Algorithm)은 라우터와 라우터 간의 최단 경로 스패닝 트리를 찾고, 그 최적 경로를 이용할 수 없을 경우 다른 경로를 찾는 방식이다. 각 라우터가 업데이트될 때마다 전체 라우팅 테이블 정보를 이웃 라우터에게만 보내며, 링크 상태 알고리즘보다 계산이 단순하다는 특징이 있다. 링크 상태 알고리즘(Link State Algorithm)은 라우터와 라우터 간의 모든 경로를 파악한 뒤 대체 경로를 사전에 마련해 두는 방식이다. 이 알고리즘을 사용하면 네트워크 상태를 일관성 있게 파악할 수 있으나, 거리 벡터 알고리즘에 비하여 계산이 더 복잡하고 트래픽을 광범위한 범위까지 전달해야 한다는 단점이 있다."]]},{"t":"② RIP 30초 갱신·IGRP(Ci sco)","n":[["설명","RIP와 IGRP RIP(Routing Information Protocol)는 최초의 라우팅 프로토콜로 거리 벡터 알고리즘을 활용하며, 30초 주기로 전체 라우팅 정보를 갱신하지만 변화가 발생했을 때 이를 업데이트하는 데 많은 시간이 소요되고 라우팅 루프가 발생할 가능성이 있다. IGRP는 RIP의 이러한 문제점을 개선하기 위하여 시스코(Cisco)에서 개발한 프로토콜로, 대역폭과 속도 등 네트워크 상태를 함께 고려하여 라우팅한다. OSPF(Open Shortest Path First)는 링크 상태 알고리즘을 사용하는 프로토콜로, 변경 정보에 대하여 RIP보다 빠르게 업데이트되며 네트워크 토폴로지에 대한 정보가 전체 라우터에 동일하게 유지된다는 장점이 있다. BGP(Border Gateway Protocol)는 규모가 큰 네트워크를 상호 연결할 때 사용되며, 대형 인터넷 서비스 제공자(ISP) 간의 상호 라우팅에 주로 활용된다."]]}]}]}]},{"t":"Ⅵ 무선랜과 이동통신 기술","c":[{"t":"1. 무선랜(Wireless LAN)","c":[{"t":"(1) 무선랜의 개념과 표준","c":[{"t":"① 무선랜 IEEE 802.11 표준","n":[["설명","무선랜의 개념 무선랜(Wireless LAN, WLAN)은 유선 케이블 없이 전파를 이용하여 근거리 통신망을 구성하는 기술이다. 무선랜을 사용하면 사용자가 케이블에 물리적으로 얽매이지 않고 자유롭게 이동하면서도 네트워크에 접속할수 있다는 장점이 있다. 무선랜의 국제 표준은 IEEE 802.11로 정의되며, 802.11b, 802.11g, 802.11n, 802.11ac, 802.11ax(Wi-Fi 6)와 같이 버전이 올라갈수록 더 빠른 전송 속도와 넓은 대역폭을 지원한다. 무선랜의 각 기기가 서로 통신하기 위해서는 AP(Access Point)라는 중계 장치가 필요한 경우가 일반적이다."]]},{"t":"② WEP→WPA·WPA2·WPA3· SSID","n":[["설명","보안 방식의 발전 무선랜은 유선랜과 달리 전파가 공간으로 퍼져 나가기 때문에 도청이나 무단 접속의 위험이 상대적으로 크며, 이를 방지하기 위한 보안 방식이 지속적으로 발전해 왔다. 초기의 WEP(Wired Equivalent Privacy) 방식은 암호화 방식이 취약하여 현재는 거의 사용되지 않으며, 이후 WPA와 WPA2, WPA3와 같이 점차 강화된 보안 방식으로 발전하였다. SSID(Service Set Identifier)는 무선랜을 식별하기 위한 이름으로, 사용자는 접속하고자 하는 무선랜의 SSID를 선택하고 비밀번호를 입력하여 인증 절차를 거친 후 네트워크에 접속하게 된다."]]}]},{"t":"(2) 이동통신 세대별 특징","c":[{"t":"① 이동통신 1G~4G(LTE)·5G","n":[["설명","1세대부터 4세대까지 이동통신 기술은 아날로그 음성 통화만 지원하던 1세대(1G)로부터 시작하여, 디지털 방식으로 전환되어 문자 메시지를 지원한 2세대(2G), 데이터 통신 속도가 크게 향상되어 영상 통화와 인터넷 사용이 가능해진 3세대 (3G), 그리고 고속 데이터 전송을 통해 스트리밍과 대용량 파일 전송이 원활해진 4세대(4G, LTE)로 발전해 왔다. 5세대(5G) 이동통신은 4G보다 훨씬 빠른 전송 속도, 매우 낮은 지연시간, 그리고 대규모 기기의 동시 접속을 지원하는 것이 특징이다. 이러한 특성 덕분에 자율주행차, 사물인터넷(IoT), 증강현실(AR)·가상현실(VR)과 같은 차세대 서비스의 기반 기술로 주목받고 있다."]]},{"t":"② IoT: 사물 인터넷 연결","n":[["설명","IoT의 개념"],["실제 사례","사물인터넷(Internet of Things, IoT)은 다양한 사물에 센서와 통신 기능을 내장하여, 사물들이 인터넷을 통해 서로 데이터를 주고받고 상호작용할 수 있도록 하는 기술을 말한다. 가정의 스마트 기기, 웨어러블 기기, 산업 현장의 센서 등이 대표적인 IoT 기기의 예이다."]]}]}]}]},{"t":"Ⅶ 네트워크 보안 기초","c":[{"t":"1. 방화벽과 침입 탐지·차단 시스템","c":[{"t":"(1) 방화벽(Firewall)","c":[{"t":"① 방화벽: 보안 규칙 허용·차단","n":[["설명","방화벽의 개념 방화벽은 내부 네트워크와 외부 네트워크(인터넷) 사이에 위치하여, 미리 정의된 보안 규칙에 따라 네트워크 트래픽을 허용하거나 차단하는 보안 장비 또는 소프트웨어이다. 마치 건물의 방화벽이 화재의 확산을 막는 것처럼, 네트워크 방화벽은 외부로부터의 부정한 접근이 내부 네트워크로 확산되는 것을 막는 역할을 한다. 패킷 필터링 방화벽은 패킷의 출발지·목적지 IP 주소와 포트 번호 등을 기준으로 트래픽을 허용하거나 차단하며, 애플리케이션 게이트웨이 방화벽은 응용 계층 수준에서 트래픽의 내용까지 검사하여 더 정교한 제어가 가능하지만 처리 속도는 상대적으로 느리다."]]},{"t":"② IDS: 탐지·경고만, 차단 없음","n":[["설명","IDS(Intrusion Detection System) IDS는 침입 탐지 시스템으로, 네트워크나 시스템에 대한 비정상적인 접근이나 공격 시도를 실시간으로 탐지하여 관리자에게 경고하는 시스템이다. 다만 IDS는 탐지만 수행할 뿐 직접적인 차단 기능은 수행하지 않는다는 특징이 있다."],["시험 포인트","IPS는 침입 방지 시스템으로, IDS의 탐지 기능에 더하여 탐지된 공격을 실시간으로 자동 차단하는 기능까지 수행한다. 시험에서는 IDS(탐지만 수행)와 IPS(탐지와 차단을 모두 수행)의 차이를 구분하는 문제가 출제될 수 있다."]]}]},{"t":"(2) VPN(Virtual Private Network)","c":[{"t":"① VPN: 공중망 위 암호화 사설망","n":[["설명","VPN의 개념 VPN은 공중 인터넷망을 이용하면서도, 마치 전용선을 사용하는 것과 같은 안전한 통신 환경을 제공하는 가상 사설망 기술이다. 데이터를 암호화하여 전송함으로써, 외부에서 통신 내용을 가로채더라도 그 내용을 알아볼 수 없게 한다. VPN은 재택근무자가 회사 내부망에 안전하게 접속하거나, 서로 다른 지역에 있는 지사들을 하나의 사설망처럼 연결할 때 널리 활용된다."]]},{"t":"② SSL/TLS 암호화·HTTPS","n":[["설명","SSL/TLS의 개념 SSL(Secure Sockets Layer)과 이를 계승한 TLS(Transport Layer Security)는 인터넷 상에서 주고받는 데이터를 암호화하여 안전하게 전송하기 위한 프로토콜이다. 웹 브라우저 주소창에 표시되는 HTTPS는 HTTP에 이러한 SSL/TLS 암호화를 적용한 프로토콜이다."],["실제 사례","SSL/TLS는 공개키 암호화 방식을 이용하여 통신을 시작하기 전에 서버와 클라이언트가 안전하게 암호화 키를 교환하고, 이후에는 이 키를 바탕으로 한 대칭키 암호화 방식으로 실제 데이터를 빠르게 암호화하여 주고받는다."]]}]}]}]},{"t":"Ⅷ 응용 계층 서비스와 주요 프로토콜","c":[{"t":"1. 웹과 이메일 서비스","c":[{"t":"(1) HTTP와 웹 서비스","c":[{"t":"① HTTP: 요청-응답·Statel ess","n":[["설명","HTTP의 개념 HTTP(HyperText Transfer Protocol)는 웹 브라우저와 웹 서버 간에 웹 페이지와 같은 자원을 주고받기 위한 응용 계층 프로토콜이다. 클라이언트가 요청(Request)을 보내면 서버가 이에 대한 응답(Response)을 돌려주는 요청-응답 구조로 동작하며, 기본적으로 상태를 유지하지 않는(Stateless) 특성을 갖는다."],["쉬운 예","HTTP는 GET(자원 조회), POST(자원 생성), PUT(자원 전체 수정), PATCH(자원 일부 수정), DELETE(자원 삭제)와 같은 메소드를 통해 서버의 자원에 대한 다양한 작업을 요청할 수 있다. 예를 들어 게시 판에 새 글을 작성할 때는 POST 메소드가, 게시글 목록을 조회할 때는 GET 메소드가 사용된다."]]},{"t":"② SMTP 송신·POP3/IMAP 수신","n":[["설명","SMTP SMTP(Simple Mail Transfer Protocol)는 이메일을 송신하고 서버 간에 전달하는 데 사용되는 프로토콜이다. 사용자가 이메일을 작성하여 보내면, SMTP를 통해 발신자의 메일 서버에서 수신자의 메일 서버로 이메일이 전달된다. POP3(Post Office Protocol 3)와 IMAP(Internet Message Access Protocol)은 사용자가 메일 서버에 도착한 이메일을 자신의 기기로 가져오기 위해 사용하는 프로토콜이다. POP3는 메일을 다운로드한 뒤 서버에서 삭제하는 방식이 기본이며, IMAP은 메일을 서버에 남겨둔 채 여러 기기에서 동기화하여 확인할 수 있다는 차이가 있다."]]}]},{"t":"(2) FTP","c":[{"t":"① FTP: 파일 전송 프로토콜","n":[["설명","FTP의 개념"],["실제 사례","FTP(File Transfer Protocol)는 클라이언트와 서버 간에 파일을 업로드하거나 다운로드하기 위한 프로토콜이다. FTP는 명령을 주고받는 제어 연결과 실제 파일 데이터를 전송하는 데이터 연결을 별도로 사용한다는 특징이 있다."]]},{"t":"② Telnet 평문 → SSH 암호화","n":[["설명","Telnet Telnet은 원격지의 컴퓨터에 접속하여 명령어를 입력하고 실행 결과를 확인할 수 있도록 하는 초기의 원격 접속 프로토콜이다. 그러나 데이터를 암호화하지 않고 그대로 전송하기 때문에 아이디와 비밀번호가 노출될 위험이 있어 현재는 보안이 중요한 환경에서는 거의 사용되지 않는다. SSH(Secure Shell)는 Telnet의 보안 취약점을 개선한 프로토콜로, 원격 접속 시 주고받는 모든 데이터를 암호화하여 전송한다. 현재 서버 관리자들이 원격으로 서버에 접속하여 작업할 때 SSH가 사실상의 표준으로 사용되고 있다."]]}]}]}]},{"t":"Ⅸ 최신 네트워크 기술 동향","c":[{"t":"1. 네트워크 가상화 기술","c":[{"t":"(1) SDN(Software Defined Networking)","c":[{"t":"① SDN: 제어·데이터 평면 분리","n":[["설명","SDN의 개념"],["실제 사례","SDN은 네트워크 장비의 제어 기능(제어 평면)과 실제 데이터 전달 기능(데이터 평면)을 분리하여, 네트워크 전체를 소프트웨어로 중앙에서 제어할 수 있도록 하는 기술이다. 기존에는 각 네트워크 장비를 개별적으로 설정해야 했지만, SDN 환경에서는 중앙의 컨트롤러에서 정책을 정의하면 이를 전체 네트워크 장비에 일괄적으로 적용할 수 있다."]]},{"t":"② NFV: 네트워크 기능 SW 가상화","n":[["설명","NFV의 개념 NFV는 방화벽, 로드밸런서, 라우터와 같이 기존에는 전용 하드웨어 장비로 구현되던 네트워크 기능을, 범용 서버에서 실행되는 소프트웨어 형태로 가상화하는 기술이다. 이를 통해 특정 네트워크 기능이 필요할 때 전용 장비를 새로 구매하지 않고도 소프트웨어를 배포하는 것만으로 신속하게 기능을 추가할 수 있다. SDN과 NFV는 함께 사용되는 경우가 많은데, SDN이 네트워크의 제어와 트래픽 흐름을 유연하게 관리하는데 초점을 둔다면, NFV는 네트워크 기능 자체를 하드웨어에서 소프트웨어로 분리하는 데 초점을 둔다는 차이가 있다."]]}]},{"t":"(2) IPv6","c":[{"t":"① IPv6: 128비트 주소 공간","n":[["설명","IPv6의 등장 배경 기존 IPv4는 약 43억 개의 주소만을 표현할 수 있어, 인터넷에 연결되는 기기 수가 폭발적으로 증가함에 따라 주소 고갈 문제가 발생하였다. 이를 해결하기 위해 128비트의 훨씬 넓은 주소 공간을 갖는 IPv6가 개발되 었다. IPv6는 거의 무한에 가까운 주소 공간을 제공할 뿐만 아니라, 헤더 구조를 단순화하여 처리 효율을 높이고, 보안 기능을 프로토콜 자체에 기본적으로 내장하고 있다는 장점이 있다. 다만 기존 IPv4 기반 장비와의 호환성 문제로 인해 전환이 점진적으로 이루어지고 있다."]]},{"t":"② QUIC: UDP 기반·HTTP/3","n":[["설명","QUIC 프로토콜 QUIC는 기존에 TCP 위에서 동작하던 HTTP 통신의 지연 문제를 개선하기 위해, UDP를 기반으로 새롭게 설계된 전송 프로토콜이다. 연결 설정에 필요한 시간을 단축하고, 하나의 연결에서 여러 데이터 스트림을 독립적으로 처리하여 특정 스트림의 손실이 다른 스트림에 영향을 주지 않도록 설계되었다. HTTP/3는 QUIC 프로토콜을 기반으로 하는 최신 버전의 HTTP로, 기존 HTTP/2보다 더 빠르고 안정적인웹 통신 속도를 제공하는 것을 목표로 한다. 주요 웹 브라우저와 콘텐츠 전송 네트워크(CDN) 사업자들이 점진적으로 HTTP/3를 지원하고 있다."]]}]}]}]},{"t":"Ⅹ 네트워크 주소 변환과 서비스 품질","c":[{"t":"1. NAT(Network Address Translation)","c":[{"t":"(1) NAT의 개념","c":[{"t":"① NAT: 사설IP→공인IP 변환","n":[["설명","NAT란 NAT는 사설 IP 주소를 사용하는 내부 네트워크가 공인 IP 주소를 사용하는 외부 인터넷과 통신할 수 있도록, 내부의 사설 IP 주소를 공인 IP 주소로 변환해 주는 기술이다. 가정에서 사용하는 공유기가 대표적인 NAT 장비로, 집안의 여러 기기가 사설 IP를 사용하면서도 하나의 공인 IP를 통해 인터넷에 접속할 수 있도록 해 준다. IPv4 주소는 그 수가 한정되어 있어 모든 기기에 공인 IP를 할당하기 어렵기 때문에, NAT를 이용하면 하나의 공인 IP만으로 여러 대의 내부 기기가 인터넷을 사용할 수 있게 되어 공인 IP 주소의 부족 문제를 완화하는 효과가 있다."]]},{"t":"② NAT 보안성·포트 포워딩","n":[["설명","보안성 향상 NAT를 사용하면 내부 네트워크의 사설 IP 주소 체계가 외부에 직접 노출되지 않기 때문에, 외부에서 내부 기기로 직접 접근하기가 어려워져 부수적으로 보안성이 향상되는 효과도 얻을 수 있다. 다만 외부에서 내부의 특정 서버에 접속해야 하는 경우도 있는데, 이때는 포트 포워딩(Port Forwarding) 설정을 통해 특정 포트로 들어오는 외부 요청을 내부의 지정된 기기로 전달하도록 구성할 수 있다."]]}]},{"t":"(2) QoS의 개념","c":[{"t":"① QoS: 트래픽 서비스 품질 보장","n":[["설명","QoS란"],["쉬운 예","QoS(Quality of Service)는 네트워크 상에서 특정 트래픽에 우선순위를 부여하여, 한정된 네트워크 대역폭을 효율적으로 배분하는 기술을 말한다. 예를 들어 화상 회의나 인터넷 전화와 같이 지연에 민감한 트래픽에 높은 우선순위를 부여하여, 대용량 파일 다운로드와 같은 트래픽보다 먼저 처리되도록 할 수 있다."]]},{"t":"② 트래픽 분류·마킹·큐잉","n":[["설명","트래픽 분류와 우선순위 지정 QoS를 구현하기 위해서는 먼저 네트워크를 통과하는 트래픽을 그 유형(음성, 영상, 일반 데이터 등)에 따라 분류하고, 각 유형에 맞는 우선순위 표시(마킹)를 부여하는 작업이 선행되어야 한다. 분류된 트래픽에 대해서는 큐잉(Queueing) 기법을 이용해 우선순위가 높은 트래픽을 먼저 처리하거나, 특정 트래픽 유형에 대해 최소 보장 대역폭이나 최대 허용 대역폭을 설정하는 방식으로 네트워크 자원을 관리한다."]]}]}]}]}]},{"t":"제3절 시스템 인프라 관리(백업과 형상관리)","c":[{"t":"Ⅰ 백업의 개념과 용량 산정","c":[{"t":"1. 백업의 필요성과 산정 요소","c":[{"t":"(1) 백업의 개념","c":[{"t":"① 백업: 별도 시스템에 보관","n":[["설명","백업이 필요한 이유 백업(Backup)이란 원본 자료를 원본이 저장된 시스템과는 별도의 다른 시스템에 한 번 더 보관해 두는 작업을 말한다. 만약 어떤 중요한 자료가 로컬 디스크가 있는 하나의 시스템에만 저장되어 있다면, 그 시스템이 고장 났을 때 자료를 완전히 잃어버리게 된다. 따라서 다른 시스템에도 동일한 내용을 보관해 두면, 원본 시스템에 고장이 발생하더라도 백업본을 통해 자료를 복원할 수 있다. 단순히 오래된 백업본만 있다면 그 시점 이후의 작업 내용은 여전히 손실될 수 있으므로, 고장이 발생했을 때가장 최신의 자료를 빠르게 복원할 수 있는 백업 방법과 주기를 정하는 것이 중요하다. 기업이나 개인이 데이터를 안정적으로 보관하고 복구할 수 있도록, 현재 보유한 데이터량과 증가율, 보존 기간, 중복 제거 비율, 백업 방식 등을 종합적으로 고려하여 필요한 스토리지 용량을 계산하는 작업을 백업 용량 산정이라고 한다."]]},{"t":"② 원본·변경 데이터 백업 용량","n":[["설명","원본 데이터와 변경 데이터"],["쉬운 예","원본 데이터 크기는 현재 보관 중인 전체 데이터의 용량을 말하며, 변경 데이터는 하루에 새로 추가되거나 수정되는 데이터의 비율(또는 크기)을 말한다. 예를 들어 전체 데이터가 100GB이고 하루 변경률이 2%라면 하루에 2GB씩 데이터가 변경되는 것으로 계산한다."]]}]},{"t":"(2) 풀 백업과 증분 백업","c":[{"t":"① 풀 백업: 전체 데이터 백업","n":[["설명","풀 백업(Full Backup)"],["쉬운 예","풀 백업은 전체 데이터를 통째로 백업하는 방식이다. 예를 들어 1TB짜리 원본 데이터를 매주 풀 백업 한다고 가정하면, 1주 차에 1TB, 2주 차에도 다시 1TB, 3주 차에도 1TB, 4주 차에도 1TB를 각각 저장하게 되어 4주 동안 총 4TB(1TB × 4)의 저장 공간이 필요하다. 풀 백업은 매번 전체를 백업하므로 시간이 오래 걸리고 저장 공간을 많이 차지한다는 단점이 있다."],["쉬운 예","증분 백업은 최초 한 번 풀 백업을 수행한 후, 그 이후로는 매번 새로 증가한 데이터(증분)만을 추가로 백업하는 방식이다. 예를 들어 전체 데이터 크기가 100GB이고 하루 변경량이 10GB이며 주 1회 풀 백업 후 평일에 증분 백업을 한다고 가정하면, 월요일에 10GB, 화요일에 10GB와 같이 매일 증가분만큼만 백업하므로 평일 엿새 동안 60GB가 추가로 필요하다. 이를 풀 백업 100GB에 더하면 첫 주 차에 총 160GB가 소요된다. 증분 백업은 속도가 빠르고 저장 공간을 적게 차지하지만, 중간에 어느 한 증분 백업본에 오류가 발생하면 그 이후의 복구에 실패할 수 있다는 단점이 있다."]]},{"t":"② 차등 백업: 풀 이후 누적 변경분","n":[["설명","차등 백업(Differential Backup)"],["쉬운 예","차등 백업은 누적 방식으로 이해하면 쉬운데, 최초 풀 백업 이후 매일 발생한 변경분을 이전 변경분과 계속 누적하여 백업하는 방식이다. 예를 들어 하루 변경량이 10GB일 때, 월요일에는 10GB, 화요일에는 월요일 을 포함하여 20GB, 수요일에는 30GB와 같이 날마다 변경량이 누적되어 커진다. 이는 매일 10GB씩만 백업하는 증분 백업과 근본적으로 다른 방식이다."]]}]}]}]},{"t":"Ⅱ 백업 시스템의 종류","c":[{"t":"1. 저장 위치에 따른 백업 시스템","c":[{"t":"(1) 로컬 백업과 원격 백업","c":[{"t":"① 로컬 백업 고속·원격 백업 IDC","n":[["설명","로컬 백업 로컬 백업은 하드디스크, NAS, SAN과 같이 저장 장치에 직접 연결된 스토리지에 백업하는 방식이다. 속도가 빠르고 구축 비용이 저렴하다는 장점이 있으나, 화재나 도난, 재해가 발생했을 때 원본과 함께 백업본까지 손실될 위험이 있다는 단점이 있다. 원격 백업(Remote Backup)은 본사가 아닌 다른 지사나 데이터 센터(IDC)에 데이터를 백업해 두는 방식이다. 원본이 위치한 장소가 재해를 입더라도 원격지에 있는 자료는 안전하게 보존되므로 재해복구에 매우 유리하다는 장점이 있다."]]},{"t":"② 클라우드 백업: 확장성·네트워크 의존","n":[["설명","클라우드 백업의 개념 클라우드 백업은 AWS S3, 네이버 클라우드, 구글 클라우드와 같은 퍼블릭 클라우드에 데이터를 저장하는 방식이다. 확장성이 좋고 관리 및 재해 대응에 매우 유리하다는 장점이 있다. 클라우드 백업은 네트워크에 대한 의존도가 높아 인터넷 연결이 원활하지 않으면 백업이나 복원이 제한될 수있으며, 장기간 사용할 경우 누적되는 이용 비용이 증가할 수 있다는 단점이 있다."]]}]},{"t":"(2) 풀·증분·차등 복원 방식","c":[{"t":"① 풀+증분 복원: 전체 증분 필요","n":[["설명","풀 백업과 증분 백업의 복원"],["쉬운 예","풀 백업 복원 방식은 전체 데이터를 한 번에 복원하는 방식으로 가장 간단하지만 시간이 오래 걸린다. 증분 백업으로 특정 요일에 복구하려면, 마지막 풀 백업본에서부터 그 요일까지의 모든 증분 백업본을 순서대로 차례차례 적용해야 한다. 예를 들어 수요일에 복구해야 한다면 풀 백업본에 월요일 증분분, 화요일 증분분, 수요일 증분분을 순차적으로 모두 반영해야 하므로 다소 불편할 수 있으나, 저장 공간은 효율적으로 사용할 수 있다."],["쉬운 예","차등 백업은 누적 방식이므로 복원할 때 풀 백업본과 복구하려는 시점의 최신 차등 백업본 하나만 있으면 된다. 예를 들어 수요일에 복구하는 경우, 일요일의 풀 백업본과 수요일의 차등 백업본(월·화·수요일 변경 분이 이미 누적되어 있음)만 있으면 복원이 가능하므로 증분 백업보다 복구 속도가 빠르고 안정성도 높다."]]},{"t":"② 스냅샷: 특정 시점 저장·롤백","n":[["설명","스냅샷(Snapshot) 스냅샷은 어떤 특정 시점의 데이터 상태를 사진 찍듯이 그대로 저장하는 방식으로, 가상 머신(VM)이나 데이터베이스 등에서 많이 활용된다. 전체를 새로 복사하는 것이 아니라 변경된 부분만 기록하기 때문에 복구 속도가 매우 빠르며, 특정 시점을 선택하여 그 시점으로 시스템을 되돌리는 롤백(Rollback)이 가능하고 전체 시스템뿐 아니라 특정 파일이나 폴더만 부분 복원하는 것도 가능하다. 다만 스냅샷을 찍은 이후에 변경된 데이터는 복원 시 사라질 수 있다는 단점이 있다. CDP는 지속적 데이터 보호를 의미하며, 데이터가 변경될 때마다 즉시 기록하는 실시간 또는 준실시간 백업 방식으로 데이터 손실 지점을 최소화할 수 있다. 분 단위, 초 단위까지 복원이 가능하다는 것이 CDP의 가장큰 특징이며, 데이터베이스나 금융권 서비스와 같이 데이터 손실이 치명적인 환경에서 자주 사용된다. 다만 계속하여 데이터를 기록해야 하므로 저장 공간이 많이 필요하고 시스템 부하가 커질 수 있다는 단점이 있다."]]}]}]}]},{"t":"Ⅲ 운영 목적에 따른 백업 시스템","c":[{"t":"1. 온프레미스와 하이브리드","c":[{"t":"(1) 온프레미스(On-premise ) 백업 시스템","c":[{"t":"① 온프레미스: 자체 구축·통제 용이","n":[["설명","온프레미스의 개념 온프레미스란 기업 내부에 서버와 스토리지를 자체적으로 구축하여 데이터를 저장하고 관리하는 방식을 말한다. 외부 인터넷이 없어도 회사 내부의 네트워크만으로 접근이 가능하고, 데이터 보안이나 통제가 용이하며 다양한 백업 전략을 자유롭게 적용할 수 있다는 장점이 있다. 온프레미스 방식은 구축 비용이 많이 발생하고 별도의 유지보수 인력이 필요하며, 화재나 재해가 발생했을 때물리적인 손실 위험이 있고 관리가 복잡해질 수 있다는 단점이 있다."]]},{"t":"② 하이브리드: 온프레미스+클라우드","n":[["설명","하이브리드 방식의 개념"],["쉬운 예","하이브리드 백업은 온프레미스와 클라우드 백업을 함께 사용하는 방식으로, 내부 백업을 통한 빠른 복구와 클라우드 백업의 안정성을 동시에 얻을 수 있다. 자주 복구해야 하는 데이터는 로컬에 저장하고, 장기적으로 보관해야 할 데이터는 클라우드에 저장하는 방식으로 활용된다. 예를 들어 회사 서버에 매일 증분 백업으로 저장하는 동시에, 클라우드에도 주 단위로 전체 백업을 수행하는 방식이 대표적이다."]]}]},{"t":"(2) DR(Disaster Recovery) 시스템의 개념","c":[{"t":"① DR: 재해 시 신속 복구 체계","n":[["설명","DR 시스템의 정의와 목적 DR 시스템은 재난 복구(Disaster Recovery) 시스템으로, 지진이나 화재, 시스템 장애와 같은 재해가 발생했을 때 IT 서비스와 데이터를 신속히 복구하는 비상 복구 체계를 말한다. DR 시스템의 목적은 서비스 중단을 최소화하고, 데이터 손실을 방지하며, 업무의 연속성을 확보하는 데 있다."],["실제 사례","DR 시스템은 실제 서비스를 운영하는 주 센터와, 재난이 발생했을 때 비상시 서비스를 대신 운영하는 재해복구 센터로 구성된다. 평상시에는 주 센터가 서비스를 운영하다가, 재난이 발생하면 재해복구 센터가그 역할을 대신 수행하게 된다."]]},{"t":"② RTO·RPO·콜드/웜/핫 사이트","n":[["설명","RTO와 RPO RTO(Recovery Time Objective)는 서비스를 복구하는 데 걸리는 목표 시간을 의미하며, RPO(Recovery Point Objective)는 복구가 가능한 시점, 즉 데이터 손실을 허용할 수 있는 범위를 의미한다. DR 시스템의 구축 방식은 콜드 사이트(Cold Site), 웜 사이트(Warm Site), 핫 사이트(Hot Site)로 구분된다. 콜드 사이트는 장비만을 미리 확보해 두는 방식이고, 웜 사이트는 일부 장비와 데이터 동기화를 미리 갖추어 놓는 중간 단계의 방식이며, 핫 사이트는 완벽하게 실시간으로 동기화되어 재해 발생 즉시 서비스를 대신할 수 있는 방식이다. 세 방식은 각각 저비용, 중간 비용, 고비용 순으로 구축 비용이 증가한다."]]}]}]}]},{"t":"Ⅳ 소스코드 형상관리","c":[{"t":"1. 형상관리의 개념과 종류","c":[{"t":"(1) 형상관리의 개념","c":[{"t":"① SCM: 소스 변경 이력 관리","n":[["설명","형상관리(SCM)란 형상관리(Software Configuration Management, SCM)란 소스 코드의 형태(변경 이력)를 체계적으로 관리하는 것을 말한다. 개발자들은 컴파일과 오류 수정을 반복하며 소스 코드를 계속하여 변경하는데, 이러한 변경 이력을 기록하고 관리하여 협업을 원활하게 하고 오류 발생 시 복원을 쉽게 할 수 있도록 하는 시스템을 형상관리 시스템이라고 한다. 형상관리는 코드의 변경 이력을 추적하고 필요할 때 이전 상태로 되돌릴 수 있게 해 주며, 여러 개발자가 동시에 협업할 수 있도록 지원한다. 또한 오류가 발생했을 때 과거의 안정적인 버전으로 회귀할 수 있게 해 주어, 결과적으로 코드의 품질과 유지보수성을 향상시키는 데 기여한다."]]},{"t":"② 로컬 RCS·중앙 CVS/SVN·분산형","n":[["설명","로컬 방식과 중앙 집중식 로컬(Local) 방식은 개인 PC에서만 형상관리를 수행하는 방식으로 RCS가 대표적인 도구이다. 중앙 집중식 (Centralized) 방식은 중앙 서버에서 코드를 관리하는 방식으로, 구조가 단순하고 관리가 용이하지만 서버에 장애가 발생하면 전체 개발이 중단될 수 있다는 단점이 있으며, 대표적인 도구로 CVS와 SVN(Subversion) 이 있다. 분산형 방식은 개발자 각자의 PC에 전체 이력을 보관할 수 있는 방식으로, 서버가 다운되어도 로컬에서 계속 작업할 수 있다는 장점이 있으며 협업이나 백업에 유리하지만, 구조가 다소 복잡해지고 초기 학습이 필요하다는 단점이 있다. 대표적인 도구로 Git과 Mercurial(머큐리얼)이 있다."]]}]},{"t":"(2) Git과 SVN","c":[{"t":"① Git: 분산 VCS·브랜치/머지","n":[["설명","Git의 특징 Git은 분산 버전 관리 시스템의 대표적인 도구로, 모든 개발자가 전체 이력을 자신의 PC에 저장하기 때문에 인터넷이나 서버가 연결되지 않아도 대부분의 작업이 가능하다. 브랜치(Branch)와 머지(Merge) 기능이 강력하여 병렬 개발과 협업에 매우 유리하며, GitHub·GitLab·Bitbucket과 같은 원격 저장소 서비스와 함께 사용된다. Git은 빠르고 안정적이며 협업에 강하고 오픈소스로 제공된다는 장점이 있으나, 초보자에게는 다소 어려울 수 있다는 단점이 있다. SVN(Subversion)은 중앙 집중식 버전 관리 시스템으로, 중앙 서버가 코드와 이력을 관리하고 개발자는 필요한 파일만 내려받아 작업한다. 구조가 단순하고 배우기 쉽다는 장점이 있으나, 서버 의존도가 높아 안정성이 낮고 협업에 대한 확장성이 부족하다는 한계가 있다. 과거에는 많은 기업에서 SVN을 사용하였으나, 현재는 Git이 대세로 자리잡았다."]]},{"t":"② 저장소·커밋·브랜치·머지·푸시","n":[["설명","저장소, 커밋, 브랜치 저장소(Repository)는 코드와 변경 이력을 저장하는 공간을 말하며, 커밋(Commit)은 변경 내용을 기록하는 작업 단위를 말한다. 브랜치(Branch)는 독립된 작업 공간으로, 하나의 프로젝트를 여러 갈래로 나누어 각자 따로 개발하다가 나중에 다시 합칠 수 있게 하는 기능을 말한다. 머지(Merge)는 여러 브랜치의 작업을 하나로 합치는 병합 작업을 말한다. 푸시(Push)는 로컬에서 완성한 작업 내용을 원격 저장소로 밀어 올리는(업로드하는) 것을 의미하며, 풀(Pull)은 반대로 원격 저장소에 저장된 내용을 로컬로 끌어와 가져오는(다운로드하는) 것을 의미한다. 저장소를 새로 만드는 명령은 초기화(init)라고 한다."]]}]}]}]},{"t":"Ⅴ 개발환경 설정","c":[{"t":"1. 개발환경과 개발도구","c":[{"t":"(1) 개발환경 설정의 개념","c":[{"t":"① 팀 개발 동일 환경 구성","n":[["설명","개발환경 설정의 필요성 개발환경 설정이란 프로그램을 개발하기 위하여 필요한 운영체제, 프로그래밍 언어의 실행 환경, 편집기, 컴파일러 등을 준비하고 구성하는 작업을 말한다. 동일한 소스 코드라도 개발환경이 서로 다르면 실행 결과가 달라지거나 오류가 발생할 수 있으므로, 팀 단위 개발에서는 모든 개발자가 동일한 환경에서 작업할 수 있도록 구성하는 것이 중요하다. 여러 명의 개발자나 여러 대의 서버가 동일한 프로그램과 환경 설정을 유지하도록 관리하는 것을 구성 관리(Configuration Management)라고 하며, 이는 개발환경 설정을 일관되게 유지하기 위한 활동과 밀접하게 연관된다."]]},{"t":"② IDE: 편집·컴파일·디버깅 통합","n":[["설명","통합개발환경(IDE) 통합개발환경(Integrated Development Environment, IDE)은 코드 편집, 컴파일, 디버깅, 실행을 하나의 프로그램 안에서 수행할 수 있도록 통합해 놓은 개발 도구이다. 개발하고자 하는 언어와 프로젝트의 성격에 맞는 IDE를 선택하고, 필요한 라이브러리와 플러그인을 설치하는 과정이 개발환경 설정의 핵심이다."],["실제 사례","개발도구를 설치할 때는 운영체제와의 호환성, 팀 내 다른 개발자와의 버전 일치 여부, 프로젝트가 요구하는 언어 버전과 라이브러리 의존성 등을 종합적으로 고려해야 한다. 개발환경이 표준화되어 있지 않으면 \" 내 컴퓨터에서는 되는데 서버에서는 안 되는\" 문제가 발생할 수 있으므로, 이후 학습할 컨테이너 기술 등을 활용하여 환경을 일관되게 유지하는 것이 실무에서 중요하게 다루어진다."]]}]}]}]},{"t":"Ⅵ 클라우드 인프라의 운영과 모니터링","c":[{"t":"1. 클라우드 컴퓨팅의 서비스 모델","c":[{"t":"(1) IaaS, PaaS, SaaS","c":[{"t":"① IaaS: 인프라 가상화·AWS EC2","n":[["설명","IaaS(Infrastructure as a Service) IaaS는 서버, 스토리지, 네트워크와 같은 하드웨어 인프라 자원을 가상화하여 서비스 형태로 제공하는 클라우드 모델이다. 사용자는 운영체제 설치부터 애플리케이션 설치, 운영까지 직접 관리해야 하지만, 물리적인 하드웨어를 직접 구매하고 관리할 필요가 없다는 장점이 있다. 대표적으로 AWS EC2, 마이크로소프트 Azure Virtual Machines 등이 있다."],["쉬운 예","PaaS(Platform as a Service)는 애플리케이션 개발과 실행에 필요한 운영체제, 미들웨어, 개발 도구 등의 플랫폼 환경까지 제공하여 사용자가 애플리케이션 개발에만 집중할 수 있도록 하며, SaaS(Softwareas a Service)는 완성된 소프트웨어 자체를 인터넷을 통해 서비스 형태로 제공하여 사용자가 별도의 설치 없이 웹 브라우저 등을 통해 바로 이용할 수 있도록 한다. 예를 들어 웹메일 서비스나 온라인 문서 작성 도구는 SaaS의 대표적인 예이다."]]},{"t":"② 클라우드 모니터링: CPU·메모리 지표","n":[["설명","모니터링의 필요성 클라우드 환경에서는 다수의 가상 서버와 서비스가 동적으로 생성되고 소멸되기 때문에, 각 자원의 상태와 성능을 지속적으로 관찰하는 모니터링 체계가 필수적이다. CPU 사용률, 메모리 사용량, 네트워크 트래픽, 디스크 입출력 등의 지표를 실시간으로 수집하고 분석함으로써 장애를 사전에 예방하거나 신속하게 대응할 수 있다."],["쉬운 예","모니터링 시스템은 각 지표에 대해 정상 범위를 벗어나는 임계치(Threshold)를 설정해 두고, 이를 초과하는 경우 관리자에게 자동으로 알림을 보내도록 구성하는 것이 일반적이다. 예를 들어 CPU 사용률이 90% 를 넘는 상태가 5분 이상 지속되면 담당자에게 경고 메일이나 메신저 알림을 자동 발송하도록 설정할 수 있다."]]}]},{"t":"(2) 오토스케일링(Auto Scaling)","c":[{"t":"① 오토스케일링: 부하 따라 서버 증감","n":[["설명","오토스케일링의 개념"],["쉬운 예","오토스케일링은 서비스에 대한 트래픽이나 부하량에 따라 서버 자원을 자동으로 늘리거나 줄이는 클라우드 인프라 관리 기법이다. 예를 들어 쇼핑몰의 특정 할인 행사 기간에 접속자가 급증하면 자동으로 서버 인스턴스를 추가로 생성하여 부하를 분산시키고, 트래픽이 줄어들면 다시 인스턴스 수를 줄여 비용을 절감할 수있다."],["실제 사례","오토스케일링을 사용하면 사전에 최대 트래픽을 예측하여 필요 이상으로 많은 서버를 미리 구축해둘 필요가 없으며, 실제 수요에 맞추어 자원을 탄력적으로 운영할 수 있어 비용 효율성과 서비스 안정성을 동시에 확보할 수 있다."]]},{"t":"② 로드밸런싱: 라운드로빈·최소연결","n":[["설명","로드밸런싱의 개념 로드밸런싱은 여러 대의 서버에 요청을 고르게 분산시켜, 특정 서버에 부하가 집중되지 않도록 하는 기술이다. 로드밸런서는 클라이언트의 요청을 받아 미리 정해진 분배 알고리즘에 따라 여러 서버 중 하나로 요청을 전달하는 역할을 한다. 라운드로빈(Round Robin) 방식은 순서대로 돌아가며 각 서버에 균등하게 요청을 배분하는 가장 단순한 방식이며, 최소 연결 방식(Least Connection)은 현재 처리 중인 연결 수가 가장 적은 서버에 우선적으로 요청을 배분하여 서버 간 부하를 더욱 정교하게 조절한다."]]}]}]}]},{"t":"Ⅶ 로그 관리와 장애 대응","c":[{"t":"1. 로그의 개념과 관리","c":[{"t":"(1) 로그(Log)란","c":[{"t":"① 로그: 이벤트 시간순 기록","n":[["설명","로그의 개념 로그란 시스템, 애플리케이션, 네트워크 장비 등에서 발생하는 이벤트와 동작 내역을 시간 순서대로 기록한 데이터를 말한다. 로그에는 사용자의 로그인 기록, 오류 발생 내역, 시스템 자원 사용 현황 등 다양한 정보가 포함되며, 시스템의 상태를 파악하고 문제를 진단하는 데 핵심적인 자료로 활용된다. 로그는 기록 대상에 따라 시스템 로그(운영체제 수준의 이벤트 기록), 애플리케이션 로그(응용 프로그램에서 발생하는 이벤트 기록), 보안 로그(접근 시도, 인증 실패 등 보안 관련 이벤트 기록), 네트워크 로그(트래픽 및장비 동작 기록) 등으로 구분할 수 있다."]]},{"t":"② 통합 로그 관리: ELK 스택","n":[["설명","로그 통합 관리의 필요성 하나의 서비스는 여러 대의 서버와 다양한 애플리케이션으로 구성되는 경우가 많아, 각 시스템에 흩어진 로그를 개별적으로 확인하는 것은 매우 비효율적이다. 이에 따라 여러 시스템의 로그를 한곳에 모아 통합적으로 수집·저장·분석하는 로그 관리 시스템이 널리 사용된다. 대표적인 통합 로그 관리 도구로 ELK 스택(Elasticsearch, Logstash, Kibana)이 있다. Logstash는 여러 시스템으로부터 로그 데이터를 수집하고 가공하며, Elasticsearch는 가공된 로그 데이터를 저장하고 빠르게 검색할 수 있도록 색인하며, Kibana는 저장된 로그 데이터를 그래프나 대시보드 형태로 시각화하여 보여주는 역할을 담당한다."]]}]},{"t":"(2) 장애 대응 절차","c":[{"t":"① 장애 탐지·보고·심각도 등급","n":[["설명","장애 탐지와 보고 장애 대응의 첫 단계는 모니터링 시스템이나 사용자의 신고를 통해 장애를 신속하게 탐지하고, 이를 관련 담당자에게 즉시 보고하는 것이다. 장애의 심각도에 따라 등급을 분류하여, 서비스 전체가 중단되는 심각한 장애는 최우선으로 대응하도록 체계를 갖추는 것이 일반적이다. 장애가 탐지되면 로그와 모니터링 데이터를 분석하여 원인을 파악하고, 서비스 영향을 최소화하기 위한 임시 조치(예: 장애가 발생한 서버를 서비스에서 제외하고 정상 서버로 트래픽을 우회)를 먼저 취한 뒤, 근본적인 원인을 해결하는 순서로 진행한다."]]},{"t":"② 사후 분석(Post-mortem) 보고서","n":[["설명","사후 분석(Post-mortem) 장애가 복구된 이후에는 장애의 발생 원인, 대응 과정, 소요 시간 등을 정리한 사후 분석 보고서를 작성하는 것이 중요하다. 이를 통해 동일하거나 유사한 장애가 재발하지 않도록 근본적인 개선 방안을 도출할 수 있다."],["실제 사례","사후 분석 결과를 바탕으로 모니터링 항목을 추가하거나, 자동 복구 스크립트를 마련하거나, 이중화 구성을 강화하는 등의 재발 방지 대책을 수립하고 실제로 적용하는 것까지 장애 대응 프로세스의 중요한 일부로 간주된다."]]}]}]}]},{"t":"Ⅷ 시스템 성능 관리와 용량 계획","c":[{"t":"1. 시스템 성능 지표","c":[{"t":"(1) 주요 성능 측정 지표","c":[{"t":"① 응답 시간·처리량(Throughp ut)","n":[["설명","응답 시간과 처리량 응답 시간(Response Time)은 사용자가 요청을 보낸 시점부터 결과를 받기까지 걸리는 시간을 의미하며, 처리량(Throughput)은 단위 시간당 시스템이 처리할 수 있는 작업의 양을 의미한다. 일반적으로 시스템에 가해지는 부하가 증가할수록 응답 시간은 늘어나고, 처리량은 일정 수준까지 증가하다가 시스템 한계에 도달하면 오히려 감소하는 경향을 보인다."],["실제 사례","자원 사용률(Utilization)은 CPU, 메모리, 디스크, 네트워크와 같은 시스템 자원이 실제로 얼마나 사용되고 있는지를 나타내는 지표이다. 특정 자원의 사용률이 지속적으로 매우 높게 유지된다면, 해당 자원이 시스템 전체 성능을 제한하는 병목(Bottleneck)일 가능성이 크다."]]},{"t":"② 부하 테스트: 한계 성능 측정","n":[["설명","부하 테스트(Load Test)"],["쉬운 예","부하 테스트는 시스템이 예상되는 최대 수준의 사용자 요청이나 트랜잭션을 처리할 때 정상적으로 동작하는지를 확인하는 테스트이다. 예를 들어 쇼핑몰이 대규모 할인 행사를 앞두고 예상 접속자 수만큼의 가상 트래픽을 발생시켜 시스템이 버틸 수 있는지 사전에 점검하는 것이 부하 테스트의 대표적인 예이다."]]}]},{"t":"(2) 용량 계획의 개념","c":[{"t":"① 용량 계획: 수요 기반 자원 산정","n":[["설명","용량 계획이란 용량 계획은 현재와 향후 예상되는 서비스 수요를 바탕으로, 필요한 서버, 스토리지, 네트워크 대역폭 등의 인프라 자원을 미리 산정하고 준비하는 활동을 말한다. 용량 계획이 부족하면 서비스 성장에 따라 갑자기 자원이 부족해져 장애로 이어질 수 있고, 반대로 지나치게 넉넉한 자원을 준비하면 불필요한 비용이 낭비된다. 용량을 산정할 때는 현재의 트래픽 추이, 서비스의 성장률 예측, 특정 이벤트(할인 행사, 신규 서비스 출시 등)에 따른 일시적 트래픽 급증 가능성, 그리고 장애에 대비한 여유 자원까지 종합적으로 고려해야 한다."]]},{"t":"② 과거 추이로 미래 수요 예측","n":[["설명","추세 분석을 통한 예측"],["쉬운 예","과거 일정 기간 동안의 자원 사용률 추이를 분석하여, 향후 자원 사용량이 어떻게 변화할지를 예측하는 것이 용량 계획의 기본적인 접근 방법이다. 예를 들어 최근 6개월간 저장 공간 사용량이 매달 5%씩 증가해 왔다면, 이러한 추세를 바탕으로 향후 저장 공간이 한계에 도달하는 시점을 예측하고 사전에 증설 계획을 수립할 수 있다."]]}]}]}]},{"t":"Ⅸ 가상화 기술의 심화","c":[{"t":"1. 서버 가상화","c":[{"t":"(1) 하이퍼바이저(Hyperviso r)","c":[{"t":"① 하이퍼바이저 Type 1·Type 2","n":[["설명","하이퍼바이저의 개념 하이퍼바이저는 하나의 물리적인 서버 위에서 여러 개의 가상 머신(Virtual Machine)을 생성하고 운영할 수있도록 하는 소프트웨어 계층이다. 각 가상 머신은 마치 독립된 컴퓨터처럼 자신만의 운영체제와 애플리케이션을 실행할 수 있다. 1형(Type 1) 하이퍼바이저는 물리적 하드웨어 위에 직접 설치되어 동작하는 방식으로 성능이 우수하여 서버 환경에서 주로 사용되며, 2형(Type 2) 하이퍼바이저는 호스트 운영체제 위에 설치되는 애플리케이션 형태로 동작하여 개인용 PC에서 테스트 목적으로 주로 사용된다."]]},{"t":"② 컨테이너: 커널 공유 경량화·Docker","n":[["설명","컨테이너의 개념 컨테이너는 가상 머신과 달리 운영체제 커널을 여러 컨테이너가 공유하면서, 애플리케이션 실행에 필요한 라이브러리와 설정만을 격리하여 실행하는 경량화된 가상화 기술이다. 가상 머신에 비해 훨씬 가볍고 실행 속도가 빠르다는 장점이 있다. Docker는 컨테이너를 생성하고 관리하는 대표적인 플랫폼으로, 애플리케이션과 그 실행 환경을 하나의 이미지로 패키징하여 어떤 환경에서도 동일하게 실행할 수 있도록 한다. 다수의 컨테이너를 자동으로 배포, 확장, 관리해주는 도구로는 쿠버네티스(Kubernetes)가 널리 사용되고 있다."]]}]},{"t":"(2) 가상화의 장점","c":[{"t":"① 가상화 장점: 자원 효율·비용 절감","n":[["설명","자원 활용의 효율성 가상화를 사용하면 하나의 물리적 서버 위에서 여러 개의 가상 서버를 동시에 운영할 수 있어, 물리적 하드웨어의 자원을 훨씬 효율적으로 활용할 수 있다. 이는 별도의 물리 서버를 각 서비스마다 구매하는 것보다 초기 투자 비용과 운영 비용을 크게 절감할 수 있게 해 준다. 가상 서버는 물리 서버와 달리 필요에 따라 손쉽게 생성하거나 삭제할 수 있어, 새로운 서비스 환경을 신속하게 구축하거나 테스트 환경을 빠르게 마련하는 데 매우 유리하다."]]},{"t":"② 가상화 단점: 오버헤드·보안 전파","n":[["설명","성능 오버헤드 가상화 계층을 거치는 과정에서 물리 하드웨어를 직접 사용하는 것에 비해 어느 정도의 성능 저하(오버헤드) 가 발생할 수 있다. 다만 최근의 하드웨어 지원 가상화 기술의 발전으로 이러한 오버헤드는 상당히 줄어든 상태이다. 하나의 물리 서버에서 여러 가상 서버가 함께 운영되므로, 하이퍼바이저 자체에 보안 취약점이 존재할 경우 하나의 가상 서버에 대한 공격이 같은 물리 서버 위의 다른 가상 서버에까지 영향을 미칠 수 있는 위험이 존재한다. 따라서 하이퍼바이저의 보안 패치를 신속하게 적용하고, 중요한 서비스는 격리 수준이 높은 환경에서 운영하는 것이 바람직하다."]]}]}]}]},{"t":"Ⅹ 개발 환경 구성과 형상 관리 도구","c":[{"t":"1. 개발환경과 배포 환경","c":[{"t":"(1) 개발·테스트·운영 환경의 분리","c":[{"t":"① 개발·테스트·운영 환경 분리","n":[["설명","환경 분리의 필요성"],["실제 사례","소프트웨어 개발에서는 일반적으로 개발(Development), 테스트(Test/Staging), 운영 (Production) 환경을 분리하여 운영한다. 개발 환경에서 자유롭게 코드를 수정하고, 테스트 환경에서 실제 운영과 유사한 조건으로 검증한 뒤, 검증이 완료된 코드만 운영 환경에 배포함으로써 실제 서비스에 미치는 위험을 최소화할 수 있다."]]},{"t":"② 컨테이너 환경 일관성·Docker Compose","n":[["설명","컨테이너를 통한 환경 일관성 확보 개발자마다 서로 다른 개발 컴퓨터를 사용하다 보면 \"내 컴퓨터에서는 잘 되는데\" 라는 문제가 흔히 발생한다. 컨테이너 기술을 활용하면 운영체제, 라이브러리 버전 등 실행 환경 자체를 하나의 이미지로 패키징할 수 있어, 어떤 개발자의 컴퓨터에서 실행하든 동일한 환경을 보장할 수 있다. Vagrant나 Docker Compose와 같은 도구를 사용하면 필요한 소프트웨어 스택(데이터베이스, 웹 서버 등)을 코드로 정의해 두고, 명령어 한 번으로 동일한 개발 환경을 여러 컴퓨터에 신속하게 구축할 수 있다."]]}]},{"t":"(2) 브랜치 전략","c":[{"t":"① 브랜치·Git Flow 전략","n":[["설명","브랜치의 개념 Git에서 브랜치(Branch)는 기존 코드 흐름에서 벗어나 독립적으로 개발을 진행할 수 있는 작업 공간을 말한다. 새로운 기능을 개발하거나 버그를 수정할 때 별도의 브랜치를 생성하여 작업하면, 메인 브랜치의 안정성을 해치지 않으면서 여러 작업을 동시에 병행할 수 있다. Git Flow는 대표적인 브랜치 관리 전략으로, 운영 배포 코드를 관리하는 master(main) 브랜치, 다음 배포를 준비하는 develop 브랜치, 새로운 기능을 개발하는 feature 브랜치, 긴급한 오류를 수정하는 hotfix 브랜치 등으로 역할을 나누어 체계적으로 협업하는 방식이다."]]},{"t":"② Merge vs Rebase·충돌 해결","n":[["설명","병합(Merge)과 리베이스(Rebase) 병합(Merge)은 서로 다른 브랜치의 변경 내역을 하나로 합치는 작업이며, 리베이스(Rebase)는 한 브랜치의 커밋들을 다른 브랜치의 최신 내역 위로 옮겨 붙여 커밋 이력을 더 깔끔하게 정리하는 방식이다. 두 브랜치에서 같은 파일의 같은 부분을 서로 다르게 수정한 경우, 병합 과정에서 충돌이 발생하며, 이 경우 개발자가 직접 어떤 내용을 최종적으로 반영할지 수동으로 확인하고 해결해야 한다."]]}]}]}]}]},{"t":"제4절 소프트웨어 생명주기(SDLC) 와 개발방법론","c":[{"t":"Ⅰ SDLC의 개념과 단계","c":[{"t":"1. 소프트웨어 생명주기의 정의","c":[{"t":"(1) SDLC의 개념","c":[{"t":"① SDLC: 분석→설계→구현→테스트","n":[["설명","SDLC란 소프트웨어 생명주기(Software Development Life Cycle, SDLC)란 하나의 소프트웨어가 기획되어 개발 되고, 사용되다가, 그 수명을 다할 때까지 거치는 일련의 과정을 체계적으로 정리한 것을 말한다. SDLC는 요구사항 분석 → 설계 → 구현(코딩) → 테스트 → 배포 → 유지보수의 순서로 진행되는 것이 일반적이며, 프로젝트의 특성과 채택한 개발 방법론에 따라 각 단계가 반복적으로 수행되기도 한다. SDLC를 체계적으로 정립하는 목적은 정해진 일정과 예산 안에서 사용자가 요구하는 품질의 소프트웨어를 안정적으로 개발하기 위함이다. 각 단계별로 산출물과 검토 기준을 명확히 함으로써, 개발 도중 발생할 수 있는 시행착오를 줄이고 프로젝트의 진행 상황을 예측 가능하게 관리할 수 있다."]]},{"t":"② 요구사항 분석·설계 단계","n":[["설명","요구사항 분석과 설계 요구사항 분석(Requirements) 단계에서는 사용자와 발주자가 원하는 기능과 성능을 파악하여 문서로 정리한다. 설계(Design) 단계에서는 요구사항을 바탕으로 시스템의 전체 구조, 데이터베이스, 화면 구성 등을 구체적으로 설계한다. 이 두 단계는 이후 구현될 소프트웨어의 품질을 좌우하는 가장 중요한 초기 단계로 평가된다."],["실제 사례","구현(Coding) 단계에서는 설계 내용을 바탕으로 실제 프로그래밍 언어를 사용하여 코드를 작성한다. 테스트(Testing) 단계에서는 개발된 소프트웨어가 요구사항을 충족하는지, 결함은 없는지를 검증한다. 유지보수(Maintenance) 단계는 소프트웨어가 실제로 사용자에게 배포된 이후, 발견되는 오류를 수정하거나 새로운 요구사항을 반영하여 지속적으로 개선하는 단계로, 전체 생명주기 중 가장 오랜 기간 지속되는 단계이다."]]}]}]}]},{"t":"Ⅱ 폭포수 모델과 프로토타입 모델","c":[{"t":"1. 폭포수 모델(Waterfall Model)","c":[{"t":"(1) 폭포수 모델의 개념","c":[{"t":"① 폭포수: 순차 진행·역행 불가","n":[["설명","폭포수 모델의 정의 폭포수 모델은 SDLC의 각 단계를 마치 폭포수가 위에서 아래로 흐르듯이 순차적으로 진행하는 가장 고전적이고 전통적인 개발 방법론이다. 요구사항 분석이 끝나야 설계로 넘어가고, 설계가 끝나야 구현으로 넘어가는 방식으로, 원칙적으로 이전 단계로 되돌아가지 않는 것을 전제로 한다."],["실제 사례","폭포수 모델은 각 단계별로 산출물이 명확하게 정의되어 있어 프로젝트의 진행 상황을 관리하기 쉽고, 단계별 문서화가 잘 이루어진다는 장점이 있다. 그러나 초기 요구사항 분석 단계에서 요구사항이 잘못 정의 되면 이를 후반 단계에서 발견했을 때 앞 단계로 되돌아가 수정하기가 매우 어렵고 비용이 많이 든다는 단점이 있다. 또한 실제 동작하는 소프트웨어를 개발 후반부에나 확인할 수 있어, 사용자가 초기에 결과물을 미리 볼 수없다는 한계도 있다."]]},{"t":"② 프로토타입: 시제품 피드백 반영","n":[["설명","프로토타입 모델의 개념 프로토타입 모델은 폭포수 모델의 한계를 보완하기 위하여, 개발 초기에 사용자의 요구사항을 바탕으로 시제 품(프로토타입)을 간단히 만들어 사용자에게 미리 보여 주고 피드백을 받은 뒤, 이를 반영하여 점진적으로 완성해 나가는 개발 방법론이다."],["실제 사례","프로토타입 모델은 사용자가 개발 초기 단계부터 결과물을 직접 확인하고 의견을 제시할 수 있어 요구사항을 명확히 하는 데 크게 도움이 되며, 사용자와 개발자 간의 의사소통 오류를 줄일 수 있다는 장점이 있다. 다만 프로토타입을 계속 수정하는 과정에서 전체 일정이 늘어질 수 있고, 프로토타입 자체가 실제 시스템의 품질 기준을 충족하지 못할 경우 추가적인 재작업이 필요할 수 있다는 단점이 있다."]]}]}]}]},{"t":"Ⅲ 나선형 모델과 애자일 방법론","c":[{"t":"1. 나선형 모델(Spiral Model)","c":[{"t":"(1) 나선형 모델의 개념","c":[{"t":"① 나선형: 위험 분석 반복","n":[["설명","나선형 모델의 정의 나선형 모델은 폭포수 모델과 프로토타입 모델의 장점을 결합하면서, 특히 위험 분석(Risk Analysis) 과정을 반복적으로 수행하는 것을 강조하는 개발 방법론이다. 계획 수립, 위험 분석, 개발 및 검증, 고객 평가의 네 가지 활동을 나선을 그리듯이 반복하면서 점진적으로 완성도를 높여 나간다. 나선형 모델은 매 반복 주기마다 위험 요소를 미리 식별하고 대응함으로써, 대규모이고 복잡하며 위험도가 높은 프로젝트에 특히 적합하다는 평가를 받는다. 다만 위험 분석을 전문적으로 수행할 수 있는 인력이 필요하며, 관리가 복잡하고 프로젝트 기간과 비용을 예측하기 어렵다는 단점이 있다."]]},{"t":"② 애자일 등장: 변화 대응 필요","n":[["설명","애자일 방법론의 등장 배경"],["실제 사례","애자일(Agile) 방법론은 폭포수 모델과 같이 계획과 문서를 중시하는 무거운 방법론에서 벗어나, 변화하는 요구사항에 빠르고 유연하게 대응하는 것을 최우선 가치로 삼는 개발 방법론이다. 짧은 주기(Iteration, Sprint라고도 함)로 실제 동작하는 소프트웨어를 반복적으로 만들어 내며, 고객과의 지속적인 협력과 피드백을 강조한다."],["실제 사례","애자일 방법론은 공정과 도구보다 개인과 상호작용을, 포괄적인 문서보다 실제 동작하는 소프트웨어를, 계약 협상보다 고객과의 협력을, 계획을 따르기보다 변화에 대응하는 것을 더 중요한 가치로 여긴다. 이러한 가치는 애자일 소프트웨어 개발 선언문에 명시되어 있으며, 이후 학습할 DevOps 문화와도 자연스럽게 연결된다."]]}]},{"t":"(2) 스크럼(Scrum)","c":[{"t":"① 스크럼: 스프린트 반복 개발","n":[["설명","스크럼의 개념"],["실제 사례","스크럼은 애자일 방법론 중 가장 널리 사용되는 프레임워크로, 스프린트(Sprint)라고 부르는 짧은 개발 주기(보통 1~4주)를 반복하면서 우선순위가 높은 요구사항부터 순차적으로 개발해 나간다. 제품 책임자(Product Owner)는 요구사항의 우선순위를 정한 제품 백로그(Product Backlog)를 관리하고, 스크럼 마스터(Scrum Master)는 팀이 스크럼 프로세스를 원활히 수행하도록 지원하며, 개발팀은 실제로 기능을 구현하는 역할을 담당한다."]]},{"t":"② XP: 짝 프로그래밍·짧은 릴리스","n":[["설명","XP의 개념 XP(익스트림 프로그래밍)는 소프트웨어의 품질과 고객 만족을 극대화하기 위하여 우수한 개발 사례들을 극단적으로 적용하는 애자일 방법론이다. 짧은 주기의 릴리스를 반복하며, 고객이 개발 과정에 지속적으로 참여하여 피드백을 제공한다는 특징이 있다. XP의 대표적인 실천 방법으로는 두 명의 개발자가 한 대의 컴퓨터로 함께 코드를 작성하는 짝 프로그래밍(Pair Programming), 코드를 작성하기 전에 테스트 코드를 먼저 작성하는 테스트 주도 개발(Test-Driven Development, TDD), 기능의 변경 없이 코드의 구조를 지속적으로 개선하는 리팩토링(Refactoring), 그리고 개발자들이 하루에도 여러 번 코드를 통합하는 지속적 통합(Continuous Integration) 등이 있다. 이 중지속적 통합은 이후 학습할 DevOps 및 CI/CD와 개념적으로 직접 연결된다."]]}]}]}]},{"t":"Ⅳ DevOps의 개념과 핵심 원칙","c":[{"t":"1. DevOps란 무엇인가","c":[{"t":"(1) DevOps의 정의","c":[{"t":"① DevOps: 개발+운영 협업 문화","n":[["설명","DevOps의 개념 DevOps는 개발(Development)과 운영(Operations)이 결합된 용어로, 전통적으로 분리되어 있던 개발팀과 운영팀이 협업하여 자동화와 지속적인 배포 등을 통해 빠르고 안정적으로 소프트웨어를 제공하는 것을 목표로 하는 문화이자 프로세스이며 도구의 집합을 의미한다. 과거에는 개발팀이 개발을 마친 소프트웨어를 운영팀에 넘겨 결재를 받는 방식으로 진행되었다면, DevOps 환경에서는 개발과 운영이 하나의 팀처럼 협업하여 곧바로 사용자에게 전달한다. DevOps의 목표는 새로운 기능을 사용자에게 빠르게 전달하는 것, 자동화된 테스트와 검증으로 오류를 최소화하여 품질을 보장하는 것, 장애를 신속하게 탐지하고 대응하여 안정적인 서비스를 운영하는 것, 그리고 모니터링과 피드백을 기반으로 서비스를 지속적으로 개선하는 것이다."]]},{"t":"② DevOps 원칙: 자동화·CI·CD·협업","n":[["설명","자동화, 통합, 배포 DevOps의 핵심 원칙 중 하나인 자동화(Automation)는 빌드, 테스트, 배포, 모니터링 등의 반복 작업을 자동화하는 것을 말한다. 지속적인 통합은 코드 변경 사항을 자주 통합하고 자동으로 테스트를 실행하는 것이며, 지속적인 배포는 운영 환경에 안정적으로 배포할 수 있도록 이 과정을 자동화하는 것이다. 협업(Collaboration)은 개발자와 운영자 간의 질의응답을 통해 팀 간의 장벽을 제거하고 공동의 목표를 추구하는 것을 말한다. 모니터링과 피드백은 운영 상태를 실시간으로 관찰하고 그 결과를 다시 개발 과정에 반영하는 것을 의미하며, 이러한 다섯 가지 원칙이 DevOps 파이프라인 전반에서 유기적으로 작동한다."]]}]},{"t":"(2) DevOps 파이프라인의 흐름","c":[{"t":"① 파이프라인: 계획·코드·빌드·테스 트","n":[["설명","계획, 코드, 빌드, 테스트"],["실제 사례","DevOps 파이프라인은 CI/CD를 중심으로 개발·배포·운영이 이어지는 흐름을 말한다. 먼저 계획 (Plan) 단계에서 요구사항을 수집하고 기획하며, 코드(Code) 단계에서 개발자가 실제 코드를 작성한다. 빌드 (Build) 단계에서는 설치 가능한 형태(아티팩트)로 컴파일하고, 테스트(Test) 단계에서 자동화된 테스트를 실행하여 검증한다."],["실제 사례","릴리즈(Release) 단계에서는 배포를 준비하고, 배포(Deploy) 단계에서 실제 운영 환경에 반영하며, 운영(Operate) 단계에서 서비스가 실행되고, 모니터링(Monitor) 단계에서 운영팀이 서비스 상태를 지속적으로 관찰하고 피드백한다. 이러한 순서가 반드시 고정된 것은 아니지만, DevOps가 무엇을 목표로 하는 흐름인지 이해하는 데 중요한 참고가 된다."]]},{"t":"② 사일로 문화 → 공동 책임 문화","n":[["설명","사일로 문화에서 공동 책임 문화로 과거의 사일로(Silo) 문화는 개발자·운영자·보안 담당자가 각자 맡은 업무만 수행하고 서로 협업하지 않는 분리된 문화를 말한다. DevOps는 이러한 사일로 문화에서 벗어나 개발자와 운영팀, 보안팀 등이 하나의 원팀으로 협력하는 공동 책임 문화로의 전환을 추구한다. DevOps 문화는 실패를 두려워하지 않고 작은 단위의 실험과 개선을 장려하는 특징을 가지며, 자동화 도구와 프로세스, 협업 방식을 모두 지속적으로 점검하고 개선해 나간다. 이러한 문화는 애자일 방법론과 자연스럽게 연결되어, 변화에 유연하게 대응하는 개발 문화를 확립하는 데 기여한다."]]}]}]}]},{"t":"Ⅴ DevOps 주요 도구","c":[{"t":"1. 형상관리와 구성관리 도구","c":[{"t":"(1) 소스 코드 관리(SCM)","c":[{"t":"① SCM 도구: Git(리누스 토발즈)","n":[["설명","SCM의 역할 소스 코드 관리(Source Code Management, SCM)는 프로그램 소스가 계속하여 변경되고 수정되는 이력을 체계적으로 관리하는 것을 말하며, 앞서 다룬 형상관리와 본질적으로 같은 개념이다. 대표적인 도구로는 분산형 소스 코드 관리 도구인 Git이 있으며, 리누스 토발즈가 만든 이 도구는 협업이 필수적인 현대 개발 환경에서 가장 널리 사용되고 있다. Git은 중앙 집중형과 달리 분산된 구조로 되어 있어, 개발자마다 전체 이력의 복사본을 로컬에 가지고 있으므로 중앙 서버가 다운되더라도 로컬에서 바로 작업을 계속할 수 있다. GitHub, GitLab, Bitbucket과 같은 원격 저장소 서비스는 Git을 이용한 협업을 지원하는 대표적인 플랫폼이다."]]},{"t":"② 구성관리: 설정 동일 유지·Ansible","n":[["설명","구성관리의 개념 구성관리(Configuration Management)란 서버나 애플리케이션의 환경 설정을 동일한 상태로 유지해 주는 것을 말한다. 여러 대의 서버에 설치된 프로그램이나 운영 체제, 환경 설정이 서로 다르면 예상하지 못한 오류가 발생할 수 있으므로, 이를 동일하게 유지·관리하기 위한 도구가 필요하다. 대표적인 구성관리 도구로는 에이전트가 필요 없는 간단한 구성 관리 도구인 Ansible(앤서블), 그리고 서버 설정이나 자동화 관리를 지원하는 Puppet(퍼펫), Chef(셰프) 등이 있다. 이러한 도구들은 사람이 수작업으로 서버를 설정할 때 발생할 수 있는 실수와 서버 간 불일치를 방지하는 역할을 한다."]]}]},{"t":"(2) IaC(Infrastructu re as Code)","c":[{"t":"① IaC: 인프라를 코드로 자동 관리","n":[["설명","IaC의 개념 IaC(Infrastructure as Code)는 서버, 네트워크, 보안 설정 등의 인프라를 코드로 작성하여 자동으로 관리할 수 있게 해 주는 방법론이자 도구이다. IaC가 없으면 서버를 생성하거나 보안·네트워크 환경을 구성할 때마다 사람이 매번 수작업으로 처리해야 하므로 실수가 발생하기 쉽고 서버마다 환경이 달라질 위험이 있는데, IaC는 이러한 작업을 미리 작성해 둔 코드를 실행하는 것만으로 자동화할 수 있게 해 준다. 테라폼(Terraform)은 인프라를 선언적으로 관리하며 여러 클라우드 플랫폼을 함께 지원하는 대표적인 IaC 도구이며, AWS CloudFormation은 아마존 웹서비스 환경에 특화된 IaC 도구이다."]]},{"t":"② 컨테이너: 실행환경 패키징 배포","n":[["설명","컨테이너(Container)"],["실제 사례","컨테이너는 화물 운송에 사용하는 규격화된 컨테이너 박스에 비유할 수 있는 개념으로, 프로그램과그 실행에 필요한 환경을 하나의 표준화된 묶음으로 만들어 주는 가상화 기술이다. 컨테이너를 사용하면 개발자의 컴퓨터에서는 실행되는데 실제 서버에서는 실행되지 않는 환경 불일치 문제를 근본적으로 방지할 수 있다. 대표적인 도구로 도커(Docker)가 있다."]]}]}]}]},{"t":"Ⅵ CI(지속적 통합)의 개념","c":[{"t":"1. CI의 정의와 핵심 원칙","c":[{"t":"(1) CI(Continuous Integration)란","c":[{"t":"① CI: 자주 통합·자동 빌드/테스트","n":[["설명","CI의 개념 CI(지속적 통합)는 여러 개발자가 작성한 코드를 중앙 저장소에 자주 통합하고, 자동 빌드 및 테스트를 통해 문제를 조기에 발견하는 프로세스를 말한다. 코드를 변경할 때마다 빠르게 오류를 발견하고 품질을 보장하기 위하여 사용된다. CI가 원활히 작동하려면 모든 개발자가 동일한 저장소를 사용하여 코드가 공유되어야 하며, Git과 같은 분산 버전 관리 도구를 통해 특정 서버가 다운되더라도 작업을 계속할 수 있어야 한다. 또한 빌드와 테스트, 코드 검사 등을 자동화해야 하며, 개발자들이 하루에도 여러 번 커밋과 푸시를 반복하는 짧은 주기로 통합이 이루어져야 한다."]]},{"t":"② CI 일관 환경: Docker·조기 버그 발견","n":[["설명","일관된 환경 유지 CI는 동일한 빌드와 테스트 환경을 유지해야 하는데, 이를 위하여 도커(Docker)나 가상 환경을 활용한다. 개발자의 로컬 환경에서는 실행되지만 서버 환경에서는 실행되지 않는 오류를 방지하기 위해서는, 컨테이너 기술을 통해 어디서나 동일한 환경으로 빌드하고 테스트하는 것이 중요하다. CI를 도입하면 작은 단위에서 바로 버그를 발견할 수 있어 빠른 오류 발견이 가능하고, 자동화된 테스트로 코드 품질을 유지할 수 있으며, 반복적인 수작업을 줄여 생산성이 향상된다. 또한 작은 변경 단위로 통합을 하기 때문에 여러 사람의 작업이 충돌하는 통합 문제를 최소화할 수 있고, 실패 시 즉시 수정할 수 있는 지속적인 피드백을 얻을 수 있다."]]}]},{"t":"(2) CI 과정의 순서","c":[{"t":"① CI 순서: 푸시→감지→빌드→테스 트","n":[["설명","코드 작성부터 빌드까지 CI 과정은 개발자가 코드를 작성한 후 이를 저장소에 푸시(업로드)하는 것으로 시작된다. 이후 CI 서버가 저장소의 변경 사항을 자동으로 감지하고, 감지된 변경 사항에 대하여 빌드가 자동으로 실행되어 컴파일과 설치 과정을 거친다. 빌드가 완료되면 단위 테스트와 정적 분석 도구가 자동으로 실행되며, 그 결과가 성공했는지 실패했는지가 개발자에게 즉시 통보된다. 이러한 일련의 자동화된 과정을 통해 개발자는 자신이 작성한 코드에 문제가 있는지를 신속하게 확인할 수 있다."]]}]}]}]},{"t":"Ⅶ CD(지속적 제공·배포)와 CI/CD 파이프라인","c":[{"t":"1. 지속적 전달과 지속적 배포(CD)","c":[{"t":"(1) CD의 두 가지 의미","c":[{"t":"① 지속적 제공: 수동 승인 후 배포","n":[["설명","지속적 제공(Continuous Delivery)"],["실제 사례","CD는 CI 이후의 단계로서 자동 배포를 의미하며, 크게 지속적 제공(Continuous Delivery)과 지속적 배포(Continuous Deployment)의 두 가지로 구분된다. 지속적 제공은 빌드와 테스트까지는 자동화하 지만 실제 운영 환경으로의 최종 배포는 사람이 승인하는 방식이다. 즉 배포 직전 단계까지만 자동화되어 있으며, 완전히 자동화된 것은 아니다."]]},{"t":"② 제공(승인 필요) vs 배포(자동 반영)","n":[["설명","승인 절차와 안전성 지속적 제공은 사람의 승인 절차가 있어 상대적으로 더 안전하지만, 지속적 배포는 승인 절차가 불필요하여 자동화 수준이 매우 높다는 차이가 있다. 지속적 제공에서는 담당자가 운영 서버 배포 버튼을 직접 클릭해야 하지만, 지속적 배포에서는 코드가 병합되는 즉시 자동으로 반영된다."],["시험 포인트","두 용어는 영문 철자에 유의하여 구분해야 하는데, Delivery(제공)는 사람이 최종 배포를 수행하는 방식이고, Deployment(배포)는 시스템이 완전히 자동으로 배포까지 수행하는 방식이다. 시험에서는 이 두용어의 차이를 묻는 문제가 출제될 수 있으므로 정확히 구분하여 암기해 두어야 한다."]]}]},{"t":"(2) CI/CD 파이프라인의 흐름","c":[{"t":"① CI/CD 순서: CI 후 CD","n":[["설명","전체 파이프라인 순서 CI/CD 파이프라인은 코드를 작성하고, 지속적으로 통합하고, 지속적으로 제공하고, 지속적으로 배포하는 순서로 진행된다. 개발자가 기능을 추가하거나 수정하면, 자동 빌드와 테스트가 성공했을 때 운영 배포가 가능한 상태의 패키지가 자동으로 생성되고, 이후 배포 단계로 이어진다. 즉 CI가 먼저 수행된 이후에 CD가 나중에 이어지는 구조이다. CI/CD를 도입하면 버그를 조기에 발견할 수 있어 코드의 품질이 향상되고, 개발에서 운영까지의 과정을 자동화할 수 있어 배포 속도가 증가한다. 또한 버전(릴리즈) 실패 위험이 감소하여 서비스의 안전성이 향상되며, 개발팀과 운영팀 사이의 협업이 한층 더 강화될 수 있다."]]},{"t":"② 젠킨스·GitHub Actions","n":[["설명","젠킨스와 GitHub Actions 젠킨스(Jenkins)는 오픈소스 기반의 자동화 서버로 CI/CD 도구 중 가장 오랫동안 널리 사용되어 온 도구이다. GitHub Actions는 GitHub 저장소를 기반으로 CI/CD 파이프라인을 구성할 수 있는 도구이며, GitLab CI/CD는 GitLab에 내장되어 있는 파이프라인 기능이다."],["시험 포인트","이 외에도 TeamCity(팀시티), Travis CI(트래비스 CI), ArgoCD(아르고 CD) 등 다양한 CI/CD 도구가 존재한다. 시험에서는 이러한 도구들을 전부 암기하기보다는, CI와 CD가 각각 무엇을 의미하며왜 필요한지, 그리고 지속적 제공과 지속적 배포가 어떻게 다른지에 초점을 맞추어 학습하는 것이 효율적이다."]]}]}]}]},{"t":"Ⅷ 요구공학과 요구사항 명세","c":[{"t":"1. 요구공학의 개념","c":[{"t":"(1) 요구공학이란","c":[{"t":"① 요구공학: 요구사항 체계적 관리","n":[["설명","요구공학의 정의"],["실제 사례","요구공학(Requirements Engineering)은 소프트웨어 개발에 앞서 이해관계자들이 원하는 요구사항을 체계적으로 수집, 분석, 명세, 검증, 관리하는 일련의 활동을 말한다. 요구사항을 정확하고 명확하게 파악하지 못하면 이후 설계와 구현 단계에서 아무리 훌륭하게 작업하더라도 실제 사용자가 원하지 않는 결과물이 만들어질 수 있으므로, 요구공학은 소프트웨어 개발의 성패를 좌우하는 매우 중요한 단계이다."]]},{"t":"② 도출: 인터뷰·설문·브레인스토밍","n":[["설명","요구사항 도출(Elicitation) 요구사항 도출은 인터뷰, 설문조사, 브레인스토밍, 워크숍, 기존 문서 분석 등 다양한 기법을 통해 이해관계자 들로부터 요구사항을 수집하는 활동이다. 이 단계에서는 사용자가 명시적으로 말하지 않은 잠재적인 요구사 항까지 파악하려는 노력이 중요하다. 도출된 요구사항은 서로 상충되거나 모호한 부분이 없는지 분석 과정을 거쳐 정리되며, 이후 요구사항 명세서 (Requirements Specification)라는 문서로 구체화된다. 명세서에는 각 요구사항이 무엇을 의미하는지 명확하고 검증 가능한 형태로 기술되어야 하며, 이는 이후 설계 및 테스트 단계의 기준 문서로 활용된다."]]}]},{"t":"(2) 요구사항 검증(Validati on)","c":[{"t":"① 검증: 요구 반영 여부 확인","n":[["설명","검증의 목적"],["실제 사례","요구사항 검증은 작성된 요구사항 명세서가 이해관계자들이 실제로 원하는 내용을 정확하게 반영하고 있는지, 그리고 명세서 자체에 모순이나 누락이 없는지를 확인하는 활동이다. 이 단계를 소홀히 하면 개발이 상당히 진행된 이후에야 요구사항의 오류를 발견하게 되어 큰 비용 손실로 이어질 수 있다."]]},{"t":"② 추적성: 요구사항 추적표","n":[["설명","요구사항 추적성(Traceability) 요구사항 추적성이란 하나의 요구사항이 설계, 구현, 테스트의 각 단계에서 어떻게 반영되고 있는지를 추적할수 있는 능력을 말한다. 이를 위해 요구사항 추적표(Traceability Matrix)를 작성하여, 각 요구사항이 어떤 설계 문서, 소스 코드, 테스트 케이스와 연결되어 있는지 명시적으로 관리한다. 개발이 진행되는 중에도 요구사항은 비즈니스 환경이나 사용자의 필요에 따라 변경될 수 있으며, 이러한 변경 요청은 임의로 반영하지 않고 정해진 절차(변경 영향 분석, 승인 절차 등)를 거쳐 체계적으로 관리되어야 한다."]]}]}]}]},{"t":"Ⅸ 소프트웨어 품질과 품질 모델","c":[{"t":"1. 소프트웨어 품질의 개념","c":[{"t":"(1) 소프트웨어 품질이란","c":[{"t":"① 품질: 요구사항 만족 정도","n":[["설명","품질의 정의 소프트웨어 품질이란 소프트웨어가 사용자의 요구사항을 얼마나 충실하게 만족시키는지, 그리고 정해진 기준과 명세에 얼마나 부합하는지를 나타내는 정도를 말한다. 품질이 높은 소프트웨어는 기능이 정확하게 동작할 뿐만 아니라, 사용하기 편리하고, 오류가 적으며, 유지보수가 용이하다는 특징을 갖는다. 소프트웨어는 한번 배포된 이후에도 지속적으로 사용되고 수정되는 경우가 많기 때문에, 개발 초기 단계부터 품질을 체계적으로 관리하지 않으면 이후 유지보수 비용이 기하급수적으로 증가할 수 있다. 따라서 품질 관리는 개발이 끝난 뒤에 검사하는 활동이 아니라, 개발 전 과정에 걸쳐 지속적으로 수행되어야 하는 활동으로 인식되고 있다."]]},{"t":"② ISO/IEC 25010: 8가지 품질 특성","n":[["설명","ISO/IEC 25010 ISO/IEC 25010은 소프트웨어 품질을 평가하기 위한 국제 표준으로, 기능 적합성, 성능 효율성, 호환성, 사용성, 신뢰성, 보안성, 유지보수성, 이식성의 8가지 품질 특성으로 소프트웨어 품질을 구분하여 정의한다."],["쉬운 예","예를 들어 신뢰성(Reliability)은 소프트웨어가 정해진 조건에서 오류 없이 일관되게 동작하는 정도를 의미하며, 사용성(Usability)은 사용자가 소프트웨어를 얼마나 쉽고 효율적으로 사용할 수 있는지를 의미한다. 유지보수성(Maintainability)은 소프트웨어를 수정하거나 개선하기가 얼마나 용이한지를 나타내는 특성이다."]]}]},{"t":"(2) 품질 보증(QA)과 품질 관리(QC)","c":[{"t":"① QA: 프로세스 준수 예방 활동","n":[["설명","품질 보증(Quality Assurance) 품질 보증은 소프트웨어 개발 프로세스 자체가 정해진 절차와 표준을 준수하도록 관리함으로써, 결과물의 품질을 사전에 확보하려는 예방적 활동이다. 개발 표준, 코딩 규칙, 검토 절차 등을 수립하고 이를 준수하는지 점검하는 것이 대표적인 QA 활동이다."],["실제 사례","품질 관리는 실제로 만들어진 결과물(소스 코드, 문서 등)을 검사하여 결함을 찾아내고 수정하는 활동으로, 테스트나 코드 리뷰가 대표적인 QC 활동에 해당한다. QA가 프로세스에 초점을 둔다면, QC는 산출물 자체에 초점을 둔다는 차이가 있다."]]},{"t":"② CMMI: 5단계 성숙도 평가","n":[["설명","CMMI CMMI(Capability Maturity Model Integration)는 조직의 소프트웨어 개발 프로세스가 얼마나 체계적이고 성숙한지를 평가하는 모델로, 초기 단계부터 최적화 단계까지 5단계의 성숙도 수준으로 조직의 개발 역량을 평가한다. 공공기관 소프트웨어 사업 입찰 등에서는 개발 조직의 프로세스 성숙도나 품질 인증 수준을 평가 기준으로 활용하는 경우가 많아, CMMI와 같은 인증은 조직의 대외 신뢰도를 높이는 수단으로도 활용된다."]]}]}]}]},{"t":"Ⅹ 프로젝트 관리와 일정 산정","c":[{"t":"1. 소프트웨어 프로젝트 관리","c":[{"t":"(1) 프로젝트 관리의 개념","c":[{"t":"① 프로젝트 관리: 일정·비용·품질 통제","n":[["설명","프로젝트 관리란 소프트웨어 프로젝트 관리는 정해진 기간과 예산, 인력 안에서 소프트웨어를 성공적으로 개발하기 위해 일정, 비용, 품질, 인력, 위험 등을 계획하고 통제하는 활동을 말한다. 아무리 뛰어난 기술력을 가지고 있더라도 프로젝트 관리가 제대로 이루어지지 않으면 일정 지연이나 예산 초과, 품질 저하로 이어질 수 있다. 프로젝트 관리는 일반적으로 범위 관리, 일정 관리, 비용 관리, 품질 관리, 인력 관리, 위험 관리, 의사소통 관리 등의 영역으로 나누어 살펴볼 수 있으며, 이러한 각 영역이 균형있게 관리되어야 프로젝트가 성공적으로 완료될 수 있다."]]},{"t":"② 위험 식별·분석·회피·전가","n":[["설명","위험 식별과 분석 프로젝트를 진행하는 과정에서는 일정 지연, 핵심 인력의 이탈, 기술적 난제, 요구사항 변경 등 다양한 위험 요소가 발생할 수 있다. 위험 관리는 이러한 잠재적 위험 요소를 사전에 식별하고, 각 위험이 발생할 가능성과 발생했을 때의 영향력을 분석하는 활동에서 시작된다. 식별된 위험에 대해서는 위험을 회피하거나, 다른 주체에게 전가하거나(예: 보험, 외주), 발생 가능성이나 영향력을 줄이도록 완화하거나, 위험을 감수하고 받아들이는 등의 대응 전략을 수립하여 관리한다."]]}]},{"t":"(2) 소프트웨어 규모 산정","c":[{"t":"① LOC 기법·기능점수 기법","n":[["설명","LOC(Line of Code) 기법 LOC 기법은 개발할 소프트웨어의 예상 소스 코드 라인 수를 기준으로 개발 규모를 산정하는 가장 단순한 기법이다. 예상 LOC를 개발자 1인이 하루에 작성할 수 있는 평균 라인 수로 나누어 필요한 개발 기간이나 인력을 추정할 수 있으나, 프로그래밍 언어나 개발자의 숙련도에 따라 편차가 크다는 단점이 있다. 기능점수 기법은 소스 코드의 양이 아니라, 소프트웨어가 제공하는 기능의 수와 복잡도를 기준으로 규모를 산정하는 기법이다. 외부 입력, 외부 출력, 외부 조회, 내부 논리 파일, 외부 인터페이스 파일과 같은 기능 유형별로 개수를 세고 복잡도에 따른 가중치를 곱하여 전체 기능점수를 산출하며, 이는 프로그래밍 언어에 관계없이 비교적 객관적인 규모 산정이 가능하다는 장점이 있다."]]},{"t":"② 간트 차트: 일정 막대 도표","n":[["설명","간트 차트(Gantt Chart)"],["실제 사례","간트 차트는 프로젝트를 구성하는 각 작업(Task)의 시작일과 종료일을 가로 막대 형태로 표시하여, 전체 일정과 각 작업 간의 시간적 관계를 한눈에 파악할 수 있도록 시각화한 도구이다. 작성과 이해가 쉬워 실무에서 널리 사용되지만, 작업 간의 선후 관계나 의존 관계를 세밀하게 표현하는 데에는 한계가 있다."],["쉬운 예","소프트웨어 개발 방법론은 프로젝트의 규모, 복잡도, 요구사항의 명확성 등을 종합적으로 고려하여 선정해야 한다. 예를 들어 요구사항이 처음부터 명확하고 변경 가능성이 낮은 소규모 프로젝트에는 폭포수 모델이 적합할 수 있지만, 요구사항이 자주 바뀌고 신속한 시장 대응이 필요한 프로젝트에는 애자일 방법론이 더 적합하다."],["쉬운 예","실제 현업에서는 하나의 방법론만을 순수하게 적용하기보다, 프로젝트의 특성에 맞추어 여러 방법론의 장점을 결합한 하이브리드 접근을 취하는 경우가 많다. 예를 들어 초기 요구사항 분석과 전체 아키텍처 설계는 폭포수 모델의 체계적인 절차를 따르되, 실제 기능 구현은 짧은 반복 주기로 애자일하게 진행하는 방식이 활용될 수 있다."],["실제 사례","스크럼 팀은 제품의 우선순위와 요구사항을 관리하는 제품 책임자(Product Owner), 팀이 스크럼 프로세스를 원활히 따르도록 돕는 스크럼 마스터(Scrum Master), 그리고 실제 개발을 수행하는 개발팀으로 구성된다."],["실제 사례","XP는 짝 프로그래밍(Pair Programming, 두 명의 개발자가 하나의 컴퓨터로 함께 코드를 작성)과 테스트 주도 개발(TDD, Test Driven Development, 실제 코드를 작성하기에 앞서 테스트 코드를 먼저 작성)과 같은 구체적인 실천 기법을 통해 소프트웨어의 품질을 높이고자 하는 애자일 방법론이다."],["쉬운 예","예를 들어 요구사항 분석이 완료된 시점에 요구사항 명세서를 베이스라인으로 설정해 두면, 이후 설계 단계에서 발생하는 변경 사항들이 최초의 요구사항과 어떻게 다른지를 명확하게 추적하고 관리할 수 있다."],["실제 사례","웹 애플리케이션의 화면 동작까지 자동으로 검증하기 위해서는 Selenium이나 Cypress와 같은 UI 자동화 테스트 도구가 활용되며, 이러한 도구는 실제 사용자의 클릭이나 입력 동작을 스크립트로 재현하여 화면과 기능이 올바르게 동작하는지 확인한다."]]}]}]}]}]}],"k":"필기 2과목"},{"n":3,"t":"SQL 활용","c":[{"t":"제1절 데이터베이스 기초와 관계형 모델","c":[{"t":"Ⅰ 데이터베이스와 DBMS의 개념","c":[{"t":"1. 자료, 정보, 데이터베이스","c":[{"t":"(1) 자료와 정보의 구분","c":[{"t":"① 자료(Data) 정의","n":[["설명","자료(Data)란"],["쉬운 예","자료는 현실 세계에 존재하는 사실이나 값을 가공하지 않은 그대로의 상태를 의미한다. 예를 들어 학생들의 이름이 단순히 나열되어 있는 목록은 그 자체로는 특별한 의미를 갖지 못하는 자료에 해당한다."],["쉬운 예","정보는 자료를 관찰이나 측정을 통해 수집한 뒤, 특정한 목적에 맞게 가공하여 유용한 가치를 갖도록 만든 것을 말한다. 예를 들어 학생들의 이름과 성적을 결합하여 \"3학년 1반의 평균 성적\"과 같은 형태로 가공하면, 이는 의사 결정에 직접적으로 활용할 수 있는 정보가 된다. 이처럼 자료를 가공하여 유용한 정보를 만들어내는 과정을 정보 처리라고 한다."]]},{"t":"② DB=공유·통합·운영 데이터 집합","n":[["설명","데이터베이스란 데이터베이스는 여러 사용자와 응용 시스템이 공유하여 사용할 목적으로 통합, 조직되어 저장되고 관리되는 운영 데이터의 집합을 말한다. 특정 조직의 업무를 수행하는 데 필요한 상호 관련된 데이터들의 모임으로, 스스로를 기술하는 통합된 레코드들의 집합체라고도 표현한다."],["쉬운 예","예를 들어 학교에서 학생의 이름, 학번, 전화번호, 주소와 같은 자료들이 하나의 레코드로 묶여 있으면, 이 레코드들이 모여 하나의 데이터베이스를 구성하게 된다. 이러한 데이터베이스를 통해 담임 교사, 교과 담당 교사, 행정 담당자 등 여러 사용자가 동일한 자료를 공유하며 각자의 업무에 필요한 정보를 실시간으로 확인할수 있게 된다."]]}]},{"t":"(2) 실시간성과 동시 공유성","c":[{"t":"① 실시간 접근·계속적 변화","n":[["설명","실시간 접근과 계속적인 변화"],["쉬운 예","데이터베이스는 사용자의 요구에 대해 실시간으로 처리하고 응답할 수 있어야 한다(실시간 접근성). 또한 데이터베이스의 내용은 삽입, 삭제, 갱신을 통해 항상 최신 상태를 유지해야 하며, 이를 계속적인 변화라고한다. 예를 들어 학생의 연락처가 바뀌면 데이터베이스에도 즉시 반영되어야 최신 정보를 유지할 수 있다."],["쉬운 예","데이터베이스는 여러 명의 사용자가 동시에 자신이 원하는 데이터에 접근하여 이용할 수 있어야 한다( 동시 공유성). 또한 데이터의 물리적인 저장 위치나 주소가 아니라, 사용자가 필요로 하는 데이터의 내용 자체를 기준으로 검색이 이루어져야 하는데 이를 내용에 의한 참조라고 한다. 예를 들어 \"3학년 기식이라는 학생\"과 같이 내용을 기준으로 검색이 가능해야 한다."]]},{"t":"② DB 시스템 구성요소","n":[["설명","데이터베이스 시스템의 개념 데이터베이스 시스템은 데이터베이스를 이용하여 자료를 저장하고 관리함으로써 필요한 정보를 얻어내기 위한 컴퓨터 중심의 시스템을 말한다. 데이터베이스, 데이터베이스 언어(SQL), 사용자, 데이터베이스 관리 시스템(DBMS), 스키마, 컴퓨터 하드웨어 등의 요소로 구성된다. 데이터베이스는 논리적 구조에 따라 계층형(트리 구조, 부모-자식 관계), 망형(네트워크형, 그물망 구조, 상하 종속 관계 문제를 일부 해결하였으나 구조가 복잡함), 관계형(표 형태로 가장 널리 사용되며 이해가 쉬움), 분산형(물리적으로는 떨어져 있으나 논리적으로는 하나의 시스템처럼 동작) 등으로 구분할 수 있다."]]}]}]}]},{"t":"Ⅱ DBMS의 기능과 데이터베이스 설계","c":[{"t":"1. DBMS(Database Management System)","c":[{"t":"(1) DBMS의 개념과 필요성","c":[{"t":"① DBMS: 종속성·중복성 해결","n":[["설명","DBMS란 DBMS는 파일 시스템에서 발생하는 데이터의 종속성과 중복성 문제를 해결하기 위해 고안된 소프트웨어 시스템으로, 모든 응용 프로그램이 데이터베이스를 공유하여 이용할 수 있도록 운영하고 관리해 주는 소프트웨어이다. 사용자와 데이터베이스 사이에서 사용자의 요구에 따라 정보를 생성하고 데이터베이스를 관리해 주는 역할을 담당한다. DBMS는 정의 기능(데이터베이스에 저장될 데이터의 자료형, 구조, 이용 방식, 제약 조건을 명시하는 기능), 조작 기능(검색, 갱신, 삽입, 삭제 등을 체계적으로 처리하기 위해 데이터 접근 수단을 정하는 기능), 제어 기능(데이터의 정확성과 안전성을 유지하기 위해 무결성, 보안 및 권한 검사, 병행 수행 제어 등을 담당하는 기능)의 세 가지 필수 기능을 갖추어야 한다."]]},{"t":"② DBMS 장점: 중복 최소·무결성","n":[["설명","DBMS의 장점 DBMS를 사용하면 데이터의 중복을 최소화하고, 데이터와 프로그램 간의 종속성을 최소화하여 유지보수를 용이하게 하며, 여러 사용자가 동시에 데이터에 접근하더라도 일관성을 유지할 수 있도록 동시성을 제어하고, 데이터의 정확성과 일관성을 보장하는 무결성을 유지하며, 접근 권한을 설정하여 보안성을 확보하고, 장애 발생 시 데이터를 복구할 수 있는 기능을 제공한다. 다만 DBMS를 도입하고 운영하기 위해서는 데이터베이스 전문 인력이 필요하며, 전산화 비용과 운영 비용이 증가할 수 있고, 데이터 양이 방대해질 경우 백업과 회복이 어려워지며 시스템이 복잡해질 수 있다는 단점도 함께 존재한다."]]}]},{"t":"(2) 데이터베이스 설계 단계","c":[{"t":"① 설계 순서: 개념→논리→물리","n":[["설명","개념적 설계와 논리적 설계 데이터베이스 설계는 개념적 설계, 논리적 설계, 물리적 설계의 순서로 진행된다. 개념적 설계 단계에서는 구현할 데이터베이스의 구성 요소를 결정하고, E-R 모델과 같은 도구를 이용해 현실 세계를 인간이 이해하기 쉬운 정보 구조로 표현한다. 논리적 설계 단계에서는 개념적 설계에서 얻은 구조를 컴퓨터가 처리할 수 있는 논리적 데이터 모델(관계형, 계층형, 네트워크형 등)로 변환하며, 이 과정에서 스키마를 정의한다."],["실제 사례","물리적 설계 단계에서는 논리적으로 설계된 데이터베이스 구조를 실제 컴퓨터가 효율적으로 처리할수 있도록 내부 저장 장치의 구조와 접근 경로 등을 설계한다. 이 세 단계는 흔히 \"개념 - 논리 - 물리\"의 순서로 암기하며, 순서를 묻는 문제가 자주 출제된다."]]},{"t":"② 스키마 3단계: 외부·개념·내부","n":[["설명","스키마의 정의 스키마는 데이터베이스의 전체적인 구조와 제약 조건에 관한 전반적인 명세를 기술한 것으로, 데이터베이스를 구성하는 개체, 속성, 관계 및 데이터가 갖는 제약 조건에 대한 정의의 총칭이다. 스키마는 외부 스키마, 개념 스키마, 내부 스키마의 3단계로 구분되며, 이를 3단계 스키마 구조라고 한다."],["실제 사례","외부 스키마는 사용자나 응용 프로그래머 개개인의 입장에서 필요로 하는 데이터베이스의 논리적 구조를 정의한 것으로, 서브 스키마 또는 사용자 뷰라고도 한다. 개념 스키마는 조직 전체의 관점에서 하나만 존재하는 데이터베이스의 전체적인 논리적 구조로, 개체 간의 관계와 제약 조건, 보안 및 무결성 규칙을 정의한다. 내부 스키마는 물리적 저장 장치의 관점에서 실제 데이터가 저장되는 방법을 기술한 것으로, 물리적 스키마라 고도 한다."]]}]}]}]},{"t":"Ⅲ E-R 모델과 데이터베이스 구성 요소","c":[{"t":"1. E-R(Entity-Relati onship) 모델","c":[{"t":"(1) E-R 모델의 개념","c":[{"t":"① E-R 모델: 피터 첸 제안","n":[["설명","E-R 모델이란 E-R 모델은 피터 첸(Peter Chen) 박사에 의해 최초로 제안된 개념적 설계 기법으로, 데이터베이스를 구성하는 개체(Entity) 타입과 관계(Relationship) 타입 간의 구조, 그리고 개체를 구성하는 속성(Attribute) 등을 약속된 기호를 사용하여 표현함으로써 데이터베이스의 전반적인 구조를 쉽게 이해할 수 있도록 돕는다. E-R 다이어그램에서는 사각형이 개체 타입을, 마름모가 관계 타입을, 타원이 속성을 나타낸다. 개체를 구성하는 속성 중 기본 키에 해당하는 속성은 타원 안의 글자에 밑줄을 그어 표시한다. 개체 타입과 속성, 개체 타입 간의 연결은 선으로 표현하며, 이 선 위에 1:1, 1:N, N:M과 같은 대응 관계의 종류를 함께 표시한다."]]},{"t":"② 1:1·1:N 관계","n":[["설명","1:1 관계와 1:N 관계"],["쉬운 예","1:1(일대일) 관계는 한 개체 타입의 하나의 인스턴스가 다른 개체 타입의 하나의 인스턴스와만 대응되는 관계이다. 1:N(일대다) 관계는 한 개체 타입의 하나의 인스턴스가 다른 개체 타입의 여러 인스턴스와 대응되는 관계로, 예를 들어 한 명의 교수가 여러 명의 학생을 지도하는 경우가 이에 해당한다."],["쉬운 예","N:M(다대다) 관계는 양쪽 개체 타입의 여러 인스턴스가 서로 여러 인스턴스와 대응될 수 있는 관계로, 예를 들어 여러 학생이 여러 과목을 수강하는 경우가 이에 해당한다. 관계형 데이터베이스로 구현할 때는 N:M 관계를 그대로 표현할 수 없으므로, 별도의 교차 테이블(연결 테이블)을 두어 두 개의 1:N 관계로 분해하여 구현하는 것이 일반적이다."]]}]},{"t":"(2) 개체와 속성","c":[{"t":"① 개체(Entity) 정의","n":[["설명","개체(Entity)"],["쉬운 예","개체는 데이터베이스에 표현하려는 대상으로, 사람이 생각하는 개념이나 정보 단위와 같이 현실 세계에 존재하는 유형 또는 무형의 대상체를 의미한다. 파일 시스템에서의 레코드에 대응되며, 서로 연관된 몇 개의 속성으로 구성되어 독립적으로 존재하거나 그 자체로도 구별이 가능하다. 예를 들어 \"학생\"이나 \"교수\"는 하나의 개체가 될 수 있다."],["쉬운 예","속성은 데이터베이스를 구성하는 가장 작은 논리적 단위로, 파일 구조상의 데이터 항목이나 필드에 해당한다. 개체의 성질이나 상태를 기술하는 역할을 하지만, 그 자체만으로는 중요한 의미를 갖기 어려우며 다른 속성들과 결합하여 하나의 개체를 완전하게 설명하게 된다. 예를 들어 학생 개체의 속성으로는 학번, 이름, 학과, 지도교수번호 등이 있을 수 있다."]]},{"t":"② 관계(Relationship) 정의","n":[["설명","관계(Relationship)"],["쉬운 예","관계는 두 개 이상의 개체 간의 연관성을 결정짓는 의미 있는 연결을 말한다. 데이터 테이블에 존재하는 인스턴스의 상태에 따라 1:1, 1:N, N:M의 대응 관계로 표현되며, 예를 들어 교수와 학생 사이의 \"지도\" 관계나 학생과 과목 사이의 \"수강\" 관계가 대표적인 예이다."],["쉬운 예","릴레이션(표)에서 속성의 개수를 차수 또는 디그리라고 하며, 튜플(행)의 개수를 카디널리티 또는 기수라고 한다. 예를 들어 학번, 이름, 성별, 성적, 학과의 다섯 개 속성으로 구성된 학생 릴레이션이 있고 그 안에네 명의 학생 정보가 저장되어 있다면, 이 릴레이션의 차수는 5, 카디널리티는 4가 된다."]]}]}]}]},{"t":"Ⅳ 관계형 데이터베이스와 키(Key)","c":[{"t":"1. 관계형 데이터베이스의 구조","c":[{"t":"(1) 릴레이션(Relation)의 구성 요소","c":[{"t":"① 릴레이션과 튜플","n":[["설명","릴레이션과 튜플"],["실제 사례","관계형 데이터베이스에서 개체나 관계는 릴레이션이라는 표로 표현된다. 릴레이션을 구성하는 각각의 행을 튜플(Tuple) 또는 레코드라고 하며, 각각의 열을 속성(Attribute) 또는 필드라고 한다. 릴레이션은 릴레이션 스키마(릴레이션의 이름과 속성 이름들의 집합)와 릴레이션 인스턴스(어느 시점까지 실제로 입력된 튜플들의 집합)로 구성된다."],["쉬운 예","도메인은 하나의 속성이 취할 수 있는 같은 타입의 원자값들의 집합을 의미하며, 속성의 값이 가질 수있는 범위라고 이해할 수 있다. 예를 들어 성별 속성의 도메인은 \"남\", \"여\"로 한정되며, 성적 속성의 도메인은 0에서 100 사이의 숫자로 한정될 수 있다."]]},{"t":"② 관계형 DB: 2차원 표 구조","n":[["설명","표 형태의 구조 관계형 데이터베이스는 데이터를 2차원 표 형태로 표현하며, 구조가 단순하고 사용이 편리하여 계층형이나 네트워크형에 비해 가장 널리 사용되고 있다. 기본 키와 이를 참조하는 외래 키를 통해 릴레이션 간의 관계를 표현한다는 특징이 있다."],["시험 포인트","관계형 데이터 모델을 조작하기 위한 대표적인 언어가 바로 SQL(Structured Query Language)이다. SQL을 이용하면 1:1, 1:N, N:M의 다양한 관계를 자유롭게 표현하고 조작할 수 있다. 이처럼 SQL은 필기시험뿐 아니라 실기시험에서도 매우 중요하게 다루어지는 핵심 내용이다."]]}]},{"t":"(2) 후보키와 기본키","c":[{"t":"① 후보키(Candidate Key)","n":[["설명","후보키(Candidate Key)"],["쉬운 예","후보키는 튜플을 유일하게 구분할 수 있는 속성 또는 속성들의 집합으로, 기본 키로 사용될 수 있는 자격을 갖춘 키를 의미한다. 후보키는 유일성(하나의 릴레이션 내에서 중복된 값이 존재하지 않아야 함)과 최소성 (꼭 필요한 최소한의 속성으로만 구성되어야 함)을 모두 만족해야 한다. 예를 들어 학생 릴레이션에서는 학번과 주민번호가 모두 후보키가 될 수 있다."],["쉬운 예","기본키는 여러 후보키 중에서 하나를 선정하여 대표로 사용하는 키를 말한다. 한 릴레이션에서 특정 튜플을 유일하게 구별할 수 있는 속성으로, 중복값이나 널(NULL) 값을 가질 수 없다. 예를 들어 학생 릴레이션에서 학번과 주민번호 중 학번을 기본키로 선정할 수 있다."]]},{"t":"② 대체키와 슈퍼키","n":[["설명","대체키(Alternate Key)와 슈퍼키(Super Key)"],["쉬운 예","대체키는 후보키 중에서 기본키로 선정되지 않은 나머지 키들을 말한다. 예를 들어 학번을 기본키로 선정했다면 주민번호는 대체키가 된다. 슈퍼키는 하나의 릴레이션 내에서 튜플을 유일하게 식별할 수 있는 속성들의 집합으로, 유일성은 만족하지만 최소성은 만족하지 못할 수 있다는 점에서 후보키와 차이가 있다."],["쉬운 예","외래키는 어떤 릴레이션의 기본키를 다른 릴레이션에서 참조하고 있는 속성을 말한다. 예를 들어 교수 릴레이션의 기본키인 교수번호를 학생 릴레이션에서 지도교수번호라는 속성으로 사용하고 있다면, 이 지도교 수번호가 바로 외래키가 된다. 외래키로 지정된 속성에는 참조하는 릴레이션의 기본키에 존재하지 않는 값을 입력할 수 없다."]]}]}]}]},{"t":"Ⅴ 무결성 제약조건과 정규화","c":[{"t":"1. 데이터 무결성(Integrity )","c":[{"t":"(1) 개체 무결성과 참조 무결성","c":[{"t":"① 개체 무결성: 기본키 NOT NULL","n":[["설명","개체 무결성(Entity Integrity)"],["시험 포인트","개체 무결성은 기본키를 구성하는 어떠한 속성값도 널(NULL) 값이나 중복값을 가질 수 없다는 제약조건이다. 기본키가 비어 있다면 해당 튜플을 유일하게 식별할 수 없게 되므로, 이러한 상황을 방지하기 위한 규칙이다. \"기본키가 나오면 개체 무결성\"이라고 연결지어 암기하면 문제 풀이에 도움이 된다."],["시험 포인트","참조 무결성은 외래키와 관련된 무결성으로, 릴레이션은 참조할 수 없는 외래키 값을 가질 수 없다는 제약조건이다. 즉 한 릴레이션의 외래키 값은 반드시 참조 대상이 되는 다른 릴레이션의 기본키 값 중 하나와 일치하거나 널 값이어야 한다. \"외래키가 나오면 참조 무결성\"이라고 연결지어 암기하면 된다."]]},{"t":"② 도메인 무결성","n":[["설명","도메인 무결성(Domain Integrity)"],["쉬운 예","도메인 무결성은 속성값이 정의된 도메인(범위) 이내의 값으로만 구성되어야 한다는 제약조건이다. 예를 들어 성적 속성의 도메인이 0에서 100까지로 정의되어 있다면, 105와 같은 값은 도메인 무결성을 위반하는 값이 된다."]]}]},{"t":"(2) 정규화의 개념과 이상 현상","c":[{"t":"① 정규화 목적: 이상 현상 최소화","n":[["설명","정규화란 정규화는 함수적 종속성 등의 종속성 이론을 이용하여, 잘못 설계된 관계 스키마를 더 작은 속성의 집합으로 분해함으로써 바람직한 스키마로 만들어가는 과정을 말한다. 정규화의 목적은 데이터 저장 공간의 최소화 및데이터 구조의 안정성 극대화, 데이터베이스 내부 자료의 무결성 극대화, 그리고 삽입·삭제·갱신 시 발생할 수있는 이상 현상의 최소화에 있다."],["시험 포인트","이상 현상은 데이터가 부적절하게 구조화되어 있을 때 발생하는 문제로, 삽입 이상(새로운 데이터를 추가할 때 불필요한 정보까지 함께 입력해야 하거나 정보가 부족해 삽입이 불가능한 문제), 삭제 이상(하나의 튜플을 삭제할 때 함께 삭제되어서는 안 될 유용한 정보까지 삭제되는 문제), 갱신 이상(데이터의 일부만 수정되어 데이터 간 불일치가 발생하는 문제)의 세 가지 유형으로 구분된다. 흔히 \"삽살갱\"이라는 축약어로 암기한다."]]},{"t":"② 1NF 원자값·2NF·3NF","n":[["설명","제1정규형에서 제3정규형까지 제1정규형(1NF)은 모든 속성이 하나의 원자값만을 가지도록 하는 정규형이며, 하나의 컬럼에 여러 값이 들어가 있는 경우 이를 분해해야 한다. 제2정규형(2NF)은 1NF를 만족하면서 기본키를 구성하는 일부 속성에만 종속되는 부분적 함수 종속을 제거한 정규형이다. 제3정규형(3NF)은 2NF를 만족하면서 기본키가 아닌 속성 간에 A가 B에, B가 C에 종속되어 결과적으로 A가 C에 종속되는 이행 함수 종속을 제거한 정규형이다."],["실제 사례","보이스-코드 정규형(BCNF)은 3NF를 만족하면서 모든 결정자가 후보키 집합에 속하도록 강화한 정규형이다. 이후 다치 종속을 제거하는 제4정규형, 조인 종속을 제거하는 제5정규형까지 존재하지만, 실무에서는 3NF나 BCNF 수준까지 정규화하는 경우가 대부분이며 4NF와 5NF는 개념 정도만 이해하고 있으면 충분하다. 정규화 단계는 \"도메인(1NF) - 부분종속 제거(2NF) - 이행종속 제거(3NF) - 결정자·후보키(BCNF)\" 의 순서로 진행된다는 점을 기억해 두어야 한다."]]}]}]}]},{"t":"Ⅵ 파일 시스템과 데이터베이스 사용자","c":[{"t":"1. 파일 시스템의 한계","c":[{"t":"(1) 파일 시스템 기반 데이터 관리","c":[{"t":"① 파일 시스템 정의","n":[["설명","파일 시스템이란"],["쉬운 예","데이터베이스가 보편화되기 이전에는 각 응용 프로그램이 자신만의 독립적인 파일에 데이터를 저장하고 관리하는 파일 시스템 방식이 사용되었다. 예를 들어 회계 프로그램은 회계용 파일을, 인사 프로그램은 인사용 파일을 별도로 관리하는 방식이다."],["쉬운 예","파일 시스템 방식에서는 여러 프로그램이 동일한 성격의 데이터를 각자의 파일에 중복하여 저장하는 데이터 종속성과 중복성 문제가 발생한다. 예를 들어 직원의 이름과 주소 정보가 회계용 파일과 인사용 파일에 각각 따로 저장되어 있다면, 주소가 변경되었을 때 두 파일을 모두 찾아 수정해야 하며 하나라도 누락되면 데이터 간 불일치가 발생하게 된다."]]},{"t":"② DBMS 효과: 데이터 독립성","n":[["설명","중복성과 종속성의 해결 DBMS는 이러한 파일 시스템의 데이터 종속성과 중복성 문제를 해결하기 위해 고안되었다. 여러 응용 프로그램이 하나로 통합된 데이터베이스를 공유함으로써, 동일한 데이터를 여러 곳에 중복 저장할 필요가 없어지고, 프로그램과 데이터 간의 종속 관계도 크게 완화된다. DBMS를 통해 얻을 수 있는 핵심적인 효과 중 하나가 데이터 독립성이다. 이는 데이터의 논리적 구조나 물리적 저장 방식이 변경되더라도, 이를 사용하는 응용 프로그램은 영향을 받지 않도록 하는 성질을 말하며, 논리적 독립성과 물리적 독립성으로 구분할 수 있다."]]}]},{"t":"(2) 데이터베이스 관리자(DBA)","c":[{"t":"① DBA: 스키마·저장구조 정의","n":[["설명","DBA의 역할 데이터베이스 관리자(DataBase Administrator, DBA)는 데이터 정의어를 사용하여 데이터베이스를 DBMS에 정의하고, 데이터베이스 시스템의 관리와 운영에 대한 책임을 지는 사람이나 집단을 말한다. 데이터베이스의 구성 요소를 결정하고, 개념 스키마와 내부 스키마를 정의하며, 저장 구조와 접근 방법을 정의하는 역할을 수행한다. DBA는 이 밖에도 보안 및 데이터베이스 접근 권한 부여 정책의 수립, 백업과 복구에 대한 전략 수립, 무결성 유지를 위한 제약 조건 지정 등의 업무를 담당한다. 데이터베이스 전체를 총괄하는 최고 책임자로서의 역할을 수행한다고 이해할 수 있다."]]},{"t":"② 응용 프로그래머: 호스트 언어","n":[["설명","응용 프로그래머 응용 프로그래머는 일반 호스트 언어(C, Java 등)로 프로그램을 작성할 때 데이터 조작 명령어를 삽입하여, 일반 사용자가 응용 프로그램을 통해 데이터베이스에 접근할 수 있도록 인터페이스를 개발하는 사람을 말한다."],["쉬운 예","일반 사용자는 터미널(단말기)을 이용해 질의어나 응용 프로그램을 통해 데이터베이스에 있는 자원을 실질적으로 활용하는 사람을 말한다. 예를 들어 온라인 쇼핑몰에서 상품을 검색하고 주문하는 소비자가 일반 사용자에 해당하며, 이들은 데이터베이스의 내부 구조를 알 필요 없이 응용 프로그램이 제공하는 화면을 통해서만 데이터베이스와 상호작용한다."]]}]}]}]},{"t":"Ⅶ 분산 데이터베이스와 최신 데이터베이스 기술","c":[{"t":"1. 분산 데이터베이스(Distrib uted Database)","c":[{"t":"(1) 분산 데이터베이스의 개념","c":[{"t":"① 분산 데이터베이스 정의","n":[["설명","분산 데이터베이스란"],["쉬운 예","분산 데이터베이스는 물리적으로는 여러 컴퓨터에 나뉘어 저장되어 있지만, 논리적으로는 하나의 데이터베이스처럼 사용자에게 보이도록 하는 데이터베이스 시스템이다. 예를 들어 전국 여러 지사의 데이터를 각지역 서버에 분산 저장하면서도, 본사에서는 이를 하나로 통합된 데이터베이스처럼 조회할 수 있도록 구성하는 방식이다."],["실제 사례","분산 데이터베이스는 위치 투명성(사용자가 데이터의 실제 저장 위치를 알 필요가 없음), 중복 투명 성(데이터가 여러 곳에 중복 저장되어 있어도 사용자는 이를 의식하지 않음), 장애 투명성(일부 서버에 장애가 발생해도 전체 서비스에 영향이 없음)과 같은 다양한 투명성을 제공하는 것을 목표로 한다."]]},{"t":"② 분산 DB 장점: 응답속도·안정성","n":[["설명","분산 데이터베이스의 장점 분산 데이터베이스를 사용하면 지역별로 자주 사용하는 데이터를 가까운 서버에 배치하여 응답 속도를 향상시킬 수 있으며, 한 지역의 서버에 장애가 발생하더라도 다른 지역의 서버는 정상적으로 서비스를 지속할 수있어 안정성이 향상된다. 다만 여러 서버에 걸친 트랜잭션을 처리할 때 데이터의 일관성을 유지하기가 매우 복잡해지며, 네트워크를 통한 통신이 필요하므로 단일 데이터베이스에 비해 관리가 어렵고 설계 및 구축 비용이 크게 증가한다는 단점이 있다."]]}]},{"t":"(2) NoSQL 데이터베이스","c":[{"t":"① NoSQL: 비정형 데이터 대응","n":[["설명","NoSQL의 등장 배경 전통적인 관계형 데이터베이스(RDBMS)는 정형화된 테이블 구조와 엄격한 스키마를 요구하는데, 최근에는 소셜미디어의 게시물이나 로그 데이터처럼 형식이 유동적인 비정형·반정형 데이터가 폭발적으로 증가하면서, 이러한 데이터를 유연하게 저장하고 대규모로 확장할 수 있는 NoSQL(Not Only SQL) 데이터베이스가 함께 활용되고 있다. NoSQL 데이터베이스는 저장 방식에 따라 키와 값의 쌍으로 데이터를 저장하는 키-값(Key-Value) 저장소, 문서 형태로 데이터를 저장하는 문서(Document) 지향 데이터베이스, 컬럼 단위로 데이터를 저장하는 컬럼 지향 데이터베이스, 노드와 관계로 데이터를 표현하는 그래프(Graph) 데이터베이스 등으로 구분할 수 있다."]]},{"t":"② RDBMS 적합: ACID 중요 업무","n":[["설명","RDBMS가 적합한 경우 데이터 간의 관계가 명확하고 정형화되어 있으며, 트랜잭션의 일관성(ACID 특성)이 매우 중요한 은행 거래나 재고 관리와 같은 업무에서는 관계형 데이터베이스가 여전히 널리 사용된다."],["실제 사례","실시간으로 대량의 데이터가 생성되고, 스키마가 자주 변경되며, 수평적 확장(여러 서버로 부하를 분산)이 중요한 경우에는 NoSQL 데이터베이스가 더 적합할 수 있다. 실무에서는 하나의 시스템 안에서도 업무 특성에 따라 관계형 데이터베이스와 NoSQL 데이터베이스를 함께 사용하는 경우가 늘어나고 있다."]]}]}]}]},{"t":"Ⅷ 관계 대수와 관계 해석","c":[{"t":"1. 관계 대수(Relational Algebra)","c":[{"t":"(1) 관계 대수의 개념","c":[{"t":"① 관계 대수: 절차적 언어","n":[["설명","관계 대수란"],["실제 사례","관계 대수는 관계형 데이터베이스에서 원하는 결과를 어떻게(How) 유도해 내는지를 절차적으로 기술하는 언어로, 릴레이션을 입력받아 연산을 수행한 뒤 새로운 릴레이션을 결과로 반환하는 방식으로 동작한다. SQL이 사용자가 실제로 작성하는 언어라면, 관계 대수는 SQL문이 내부적으로 어떻게 처리되는지를 이론적으로 설명하는 도구라고 이해할 수 있다."]]},{"t":"② 일반 집합 연산자 4종","n":[["설명","일반 집합 연산자 관계 대수의 일반 집합 연산자에는 합집합(UNION), 교집합(INTERSECTION), 차집합(DIFFERENCE), 카티션 곱(Cartesian Product)이 있다. 이들은 SQL의 UNION, INTERSECT, MINUS, 교차 조인과 각각 대응되는 이론적 배경이 된다. 관계 대수에서만 사용되는 순수 관계 연산자로는 릴레이션에서 조건을 만족하는 행(튜플)만을 선택하는 셀렉 트(Select, σ), 릴레이션에서 원하는 열(속성)만을 추출하는 프로젝트(Project, π), 두 릴레이션을 공통된 속성을 기준으로 결합하는 조인(Join, ⋈), 하나의 릴레이션을 다른 릴레이션의 속성으로 나누는 디비전 (Division, ÷)이 있다. 셀렉트는 SQL의 WHERE 절, 프로젝트는 SELECT 절의 컬럼 선택과 각각 대응된다."]]}]},{"t":"(2) 관계 해석의 개념","c":[{"t":"① 관계 해석: 비절차적 언어","n":[["설명","관계 해석이란 관계 해석은 관계 대수와 달리 원하는 결과가 \"무엇(What)\"인지를 서술적으로 기술하는 비절차적 언어이다. 연산의 순서를 일일이 명시하지 않고, 원하는 데이터의 조건만을 명시하면 시스템이 알아서 그 결과를 찾아준 다는 점에서 SQL과 유사한 선언적 특성을 갖는다. 관계 대수와 관계 해석은 서로 표현 방식은 다르지만 이론적으로 동일한 표현력을 가지고 있다는 것이 증명되어 있으며, 이를 관계적으로 완전(Relationally Complete)하다고 표현한다. 즉 관계 대수로 표현할 수 있는 모든 질의는 관계 해석으로도 표현할 수 있고, 그 반대도 성립한다."]]},{"t":"② 관계 해석과 SQL 관계","n":[["설명","SQL과의 관계"],["실제 사례","실제로 사용자가 작성하는 SQL은 선언적 언어로서 관계 해석에 가까운 형태를 띠고 있지만, DBMS의 옵티마이저는 내부적으로 이 SQL문을 관계 대수의 연산 순서로 변환하여 실행 계획을 수립하고 처리한다. 즉 사용자는 \"무엇을\" 원하는지만 SQL로 작성하면, DBMS가 내부적으로 \"어떻게\" 처리할지를 관계 대수 연산으로 변환하여 최적화된 순서로 실행한다."]]}]}]}]},{"t":"Ⅸ 함수적 종속성의 이해","c":[{"t":"1. 함수적 종속(Functional Dependency)","c":[{"t":"(1) 함수적 종속의 개념","c":[{"t":"① 함수적 종속 X→Y","n":[["설명","함수적 종속이란"],["쉬운 예","함수적 종속은 릴레이션에서 어떤 속성 X의 값이 정해지면 다른 속성 Y의 값이 유일하게 하나로 결정되는 관계를 의미하며, 이를 \"X가 Y를 함수적으로 결정한다\" 또는 \"Y가 X에 함수적으로 종속되어 있다\"라고 표현하고 X→Y로 표기한다. 예를 들어 학번이 정해지면 그 학생의 이름이 유일하게 하나로 정해지므로 \"학번→이 름\"의 함수적 종속이 성립한다."]]},{"t":"② 완전·부분 함수 종속","n":[["설명","완전 함수 종속과 부분 함수 종속"],["쉬운 예","완전 함수 종속은 기본키를 구성하는 모든 속성에 종속자가 종속되어 있는 경우를 말하며, 부분 함수 종속은 기본키를 구성하는 속성 중 일부에만 종속되어 있는 경우를 말한다. 예를 들어 기본키가 (학번, 과목)으로 구성된 릴레이션에서, 성적은 (학번, 과목) 전체에 종속되어야 완전 함수 종속이지만, 지도교수가 과목만으로 결정된다면 이는 부분 함수 종속에 해당하여 제2정규형을 위반하게 된다."],["쉬운 예","이행 함수 종속은 A→B이고 B→C인 관계가 성립할 때, 결과적으로 A→C가 성립하는 관계를 말한다. 예를 들어 \"회원등급→할인율\"과 \"회원ID→회원등급\"의 관계가 있다면, \"회원ID→할인율\"이라는 이행 함수 종속이 성립하며, 이는 제3정규형을 위반하는 원인이 된다."]]}]},{"t":"(2) 비정규화된 테이블의 분해 과정","c":[{"t":"① 수강 테이블 단계별 분해","n":[["설명","단계별 분해 예시 수강 정보를 담은 하나의 테이블에 학번, 이름, 과목, 담당교수, 교수실번호, 성적이 모두 섞여 있다고 가정하면, 담당교수와 교수실번호는 과목에만 종속되어 학번에는 부분적으로만 관련되는 문제가 발생한다. 이 경우 과목, 담당교수, 교수실번호를 별도의 \"과목\" 테이블로 분리하고, 원래 테이블에는 학번, 과목, 성적만 남겨 정규화를 진행한다. 테이블을 분해한 이후에는 원래의 정보가 조인을 통해 손실 없이 복원될 수 있는지(무손실 분해, Lossless Decomposition), 그리고 원래 존재하던 함수적 종속 관계가 분해된 테이블에서도 그대로 유지되는지(종속성 보존)를 함께 검증해야 한다. 이 두 가지 조건을 만족하지 못하는 분해는 올바른 정규화로 볼 수 없다."]]},{"t":"② 과도한 정규화: 조인 증가","n":[["설명","과도한 정규화의 문제"],["실제 사례","이론적으로는 최대한 높은 정규형까지 분해하는 것이 데이터 무결성 측면에서 바람직하지만, 지나치게 세분화된 테이블 구조는 조회할 때마다 여러 테이블을 조인해야 하므로 실무에서는 오히려 복잡도와 성능 부담이 커질 수 있다."],["실제 사례","실무에서는 일반적으로 제3정규형(3NF) 수준까지 정규화를 진행한 뒤, 조회 성능이 특히 중요한 일부 테이블에 대해서는 의도적으로 반정규화를 적용하는 절충적인 접근 방식을 취하는 경우가 많다. 이는 데이터 무결성과 조회 성능이라는 두 가지 목표 사이의 현실적인 균형점을 찾는 과정이라 할 수 있다."]]}]}]}]}]},{"t":"제2절 DDL과 데이터 정의","c":[{"t":"Ⅰ DDL(데이터 정의어)의 개념","c":[{"t":"1. DDL의 정의와 대상","c":[{"t":"(1) DDL이란","c":[{"t":"① DDL: 데이터 그릇(오브젝트) 정의","n":[["설명","DDL의 정의 DDL은 데이터 정의어(Data Definition Language)로서, 데이터를 정의하는 언어이자 조금 더 엄밀하게 말하면 \"데이터를 담는 그릇\"을 정의하는 언어이다. DBMS에서는 이러한 그릇을 오브젝트(Object)라고 부른다."],["실제 사례","DDL을 통해 정의할 수 있는 대상에는 스키마(Schema, DBMS의 특성과 구현 환경을 감안한 데이터 구조), 도메인(Domain, 속성이 가질 수 있는 값의 범위), 테이블(Table, 실제 데이터가 저장되는 공간), 뷰(View, 하나 이상의 물리 테이블에서 유도되는 가상의 논리 테이블), 인덱스(Index, 검색을 빠르게 하기 위한 데이터 구조) 등이 있다."]]},{"t":"② CREATE 생성·ALTER 변경","n":[["설명","생성과 변경 DDL 명령어는 크게 생성, 변경, 삭제로 구분된다. CREATE는 데이터베이스 오브젝트를 생성하는 명령어이며, ALTER는 이미 생성된 데이터베이스 오브젝트의 구조를 변경하는 명령어이다."],["시험 포인트","DROP은 데이터베이스 오브젝트 자체를 완전히 삭제하는 명령어이며, TRUNCATE는 오브젝트 (테이블)의 구조는 그대로 유지하면서 그 안에 저장된 데이터(내용)만을 삭제하는 명령어이다. DROP과 TRUNCATE의 차이, 즉 테이블 구조까지 삭제되는지 여부를 구분하는 문제가 자주 출제된다."]]}]},{"t":"(2) 데이터 사전의 개념","c":[{"t":"① 데이터 사전 정의","n":[["설명","데이터 사전이란"],["실제 사례","데이터 사전에는 데이터베이스에 저장된 실제 데이터를 제외한 모든 정보, 즉 데이터를 구성하는 데이터(데이터에 대한 데이터)가 담겨 있다. 이러한 이유로 데이터 사전은 메타데이터(Meta Data)로 구성되어 있다고 할 수 있다."]]},{"t":"② 시스템 카탈로그: 시스템 테이블","n":[["설명","시스템 카탈로그의 개념 시스템 카탈로그는 시스템 자체에 관련된 다양한 객체에 대한 정보를 유지, 관리하기 위한 시스템 테이블로서, 좁은 의미로는 자료 사전(데이터 사전)과 같은 의미로 사용되기도 한다. 데이터베이스에 어떤 테이블이 있는지, 각 테이블에는 어떤 컬럼이 있고 그 컬럼은 어떤 자료형을 가지는지 등에 대한 정보를 담고 있는 일종의 \" 설명서\"라고 이해할 수 있다. 시스템 카탈로그는 DDL의 실행 결과로 구성되며, 카탈로그에 저장된 정보 자체를 메타데이터라고 한다. 일반 사용자는 SQL을 이용해 시스템 카탈로그의 내용을 검색할 수는 있지만, 이를 직접 삽입, 삭제, 갱신할 수는 없다. 사용자가 SQL문을 실행하여 테이블, 뷰, 인덱스 등에 변화를 주면 DBMS가 이를 감지하여 시스템 카탈로그를 자동으로 갱신한다."]]}]}]}]},{"t":"Ⅱ 테이블의 생성과 데이터 타입","c":[{"t":"1. CREATE TABLE 문","c":[{"t":"(1) 테이블 생성 구문","c":[{"t":"① CREATE TABLE 기본 구문","n":[["설명","기본 생성 구문\nCREATE TABLE 테이블이름 (\n      열이름 데이터타입 [DEFAULT 값] [NOT NULL]\n      [PRIMARY KEY (열 리스트)]\n      [FOREIGN KEY (열 리스트) REFERENCES 테이블이름(열이름)\n         [ON DELETE 옵션] [ON UPDATE 옵션]]\n      [CHECK (조건식)] [UNIQUE (열이름)]\n);\n CREATE TABLE 문은 새로운 테이블을 생성하는 가장 기본적인 DDL 명령문이다. 각 열의 이름과 데이터\n타입을 지정하고, 필요에 따라 기본값(DEFAULT), NOT NULL, 기본키(PRIMARY KEY), 외래키 (FOREIGN KEY), 체크 조건(CHECK), 유일값 조건(UNIQUE) 등의 제약조건을 함께 정의할 수 있다.\nCREATE TABLE 새테이블이름 AS SELECT문;"],["쉬운 예","이미 존재하는 다른 테이블의 정보를 이용하여 새로운 테이블을 생성할 수도 있다. 예를 들어 \"\nCREATE TABLE 신입생 AS SELECT * FROM 학생 WHERE 학년 = 1;\"과 같이 작성하면, 학생 테이블에서\n학년이 1인 데이터만을 조회한 결과로 신입생이라는 새로운 테이블을 생성할 수 있다. 이때 새로 생성된 테이블에는 원본 테이블의 제약조건(기본키, 외래키 등)은 함께 복사되지 않는다는 점에 유의해야 한다."]]},{"t":"② 문자형·숫자형 데이터 타입","n":[["설명","문자형과 숫자형"],["실제 사례","CHAR는 고정 길이 문자열 데이터 타입으로, 지정한 길이보다 짧은 값이 입력되어도 나머지 공간을 공백으로 채운다. VARCHAR는 가변 길이 문자열 데이터 타입으로, 실제 입력된 문자열의 길이만큼만 저장 공간을 차지하여 공간을 효율적으로 사용한다. INT는 정수형 숫자에 사용되는 데이터 타입이며, FLOAT는 소수점을 포함하는 실수형 데이터 타입이다."],["실제 사례","DATE는 날짜 값(연, 월, 일)을 저장하는 데 사용되는 데이터 타입으로, 제품에 따라 시간까지 함께 저장할 수 있는 DATETIME이나 TIMESTAMP 타입이 별도로 제공되기도 한다. 실무에서 테이블을 설계할 때는 각 컬럼에 저장될 데이터의 성격(고정 길이인지 가변 길이인지, 정수인지 실수인지, 날짜인지)을 명확히 분석하여 적절한 데이터 타입을 선택하는 것이 중요하다."]]}]},{"t":"(2) 뷰(View)의 생성과 특징","c":[{"t":"① CREATE VIEW 구문","n":[["설명","뷰의 개념과 생성\nCREATE VIEW 뷰이름(컬럼목록) AS 뷰를 통해 보여줄 데이터 조회용 쿼리문;"],["쉬운 예","뷰는 하나 이상의 물리 테이블로부터 유도되는 가상의 논리 테이블로서, 사용자의 사용 관점에서는 실제 테이블과 동일하게 취급된다. 예를 들어 \"CREATE VIEW 신입생뷰 AS SELECT 학번, 이름, 학과 FROM 학생 WHERE 학년 = 1;\"과 같이 작성하면, 이후 \"SELECT * FROM 신입생뷰;\"라는 단순한 질의만으로 원하는 결과를 얻을 수 있다."]]},{"t":"② CREATE INDEX: 조회 속도 향상","n":[["설명","인덱스의 개념과 생성\nCREATE [UNIQUE] INDEX 인덱스이름 ON 테이블이름 (컬럼목록);\n인덱스는 테이블에 대한 조회 속도를 높여주기 위해 사용하는 자료구조로, 책의 찾아보기(색인)와 유사한 역할을 한다. 테이블에서 특정 레코드의 위치를 빠르게 찾을 수 있도록 도와주며, 테이블에 기본키를 지정하면 해당 컬럼에는 자동으로 인덱스가 생성된다. UNIQUE 옵션을 지정하면 인덱스가 걸린 컬럼에 중복값이 허용되지 않는다.\nALTER TABLE 테이블이름 DROP INDEX 인덱스이름;\n한 번 생성된 인덱스는 변경이 필요한 경우가 드물며, 일부 제품에서는 인덱스에 대한 변경 SQL문이 아예 제공되지 않아 기존 인덱스를 삭제하고 새로운 인덱스를 생성하는 방식이 권장된다. 인덱스는 테이블에 종속된 구조로 취급되므로, 인덱스를 삭제할 때는 위와 같이 ALTER TABLE 명령문에 DROP INDEX를 추가하는 형태로 사용하는 것이 일반적이다."]]}]}]}]},{"t":"Ⅲ 제약조건(Constraint)의 활용","c":[{"t":"1. 제약조건의 유형","c":[{"t":"(1) PRIMARY KEY와 FOREIGN KEY","c":[{"t":"① PK=NOT NULL+UNIQUE","n":[["설명","PRIMARY KEY 제약조건 PRIMARY KEY는 테이블의 기본키를 정의하는 제약조건으로, 기본적으로 NOT NULL과 UNIQUE 제약이 함께 포함되어 있다. 즉 기본키로 지정된 컬럼은 널 값을 가질 수 없고, 동시에 중복된 값도 가질 수 없다."],["쉬운 예","FOREIGN KEY는 외래키를 정의하는 제약조건으로, 참조하는 대상을 \"테이블이름(열이름)\"의 형태로 명시해야 한다. 참조 무결성이 위배되는 상황(예: 참조되는 값이 삭제되는 경우)이 발생했을 때의 처리 방법을 NO ACTION, SET DEFAULT, SET NULL, CASCADE, RESTRICT와 같은 옵션으로 지정할 수 있다. 예를 들어 CASCADE 옵션은 참조되는 원본 데이터가 삭제되면 이를 참조하는 데이터도 함께 삭제되도록 하는 옵션이다."]]},{"t":"② UNIQUE·NOT NULL 제약","n":[["설명","UNIQUE와 NOT NULL UNIQUE 제약조건은 테이블 내에서 해당 컬럼이 유일한 값을 가져야 함을 의미하며, 동일한 값이 중복되어 서는 안 되는 항목(예: 이메일 주소, 주민번호)에 지정한다. NOT NULL 제약조건은 해당 컬럼에 반드시 값이 존재해야 하며 널 값을 허용하지 않는다는 것을 의미한다."],["쉬운 예","CHECK 제약조건은 개발자가 임의로 정의하는 제약조건으로, 상황에 따라 다양한 조건을 자유롭게 설정할 수 있다. 예를 들어 \"CHECK (나이 >= 0 AND 나이 <= 150)\"과 같이 특정 컬럼의 값이 합리적인 범위 내에 있도록 강제할 수 있다."]]}]},{"t":"(2) 제약조건의 추가와 삭제","c":[{"t":"① ALTER TABLE ADD CONSTRAINT","n":[["설명","제약조건 추가\nALTER TABLE 테이블이름\nADD [CONSTRAINT 제약조건이름] 제약조건(열이름);\n이미 생성되어 있는 테이블에 새로운 제약조건을 추가하고자 할 때는 ALTER TABLE 문에 ADD 절을 사용한다. 제약조건에 이름을 부여해 두면, 이후 해당 제약조건을 삭제하거나 관리할 때 이름으로 명확하게 지정할 수 있어 편리하다.\nALTER TABLE 테이블이름 DROP FOREIGN KEY [제약조건이름];\n제약조건을 삭제할 때도 ALTER TABLE 문을 사용하며, DROP 뒤에 제약조건의 종류와 이름을 지정한다. 특히 외래키 제약조건은 참조 관계를 형성하고 있으므로, 삭제하기 전에 해당 제약조건이 다른 테이블과의 관계에 미치는 영향을 충분히 고려해야 한다."]]},{"t":"② ENABLE/DISABLE CONSTRAINT","n":[["설명","제약조건 활성화\nALTER TABLE 테이블이름 ENABLE CONSTRAINT 제약조건이름;\n대량의 데이터를 일괄로 입력(적재)해야 하는 경우, 제약조건 검사로 인해 처리 속도가 느려지거나 일부 데이터가 조건을 만족하지 못해 삽입에 실패하는 상황이 발생할 수 있다. 이런 경우 제약조건을 일시적으로 비활성화한 뒤 데이터를 적재하고, 적재가 끝난 후 다시 활성화하는 방식을 활용할 수 있다.\nALTER TABLE 테이블이름 DISABLE CONSTRAINT 제약조건이름;"],["시험 포인트","제약조건을 비활성화하면 해당 제약조건의 검사가 일시적으로 수행되지 않으므로, 대량 데이터 적재나 특수한 데이터 정비 작업을 더 빠르게 수행할 수 있다. 다만 비활성화된 상태에서 입력된 데이터가 제약조건을 위반하는 경우, 이후 다시 활성화할 때 오류가 발생할 수 있으므로 주의가 필요하다."]]}]}]}]},{"t":"Ⅳ 테이블의 변경과 삭제","c":[{"t":"1. ALTER TABLE을 이용한 테이블 변경","c":[{"t":"(1) 열의 추가와 삭제","c":[{"t":"① ALTER TABLE ADD 열 추가","n":[["설명","열 추가\nALTER TABLE 테이블이름 ADD 열이름 데이터타입 [DEFAULT 값];"],["쉬운 예","이미 존재하는 테이블에 새로운 열(컬럼)을 추가할 때는 ALTER TABLE 문에 ADD 절을 사용한다. 예를 들어 학생 테이블에 이메일이라는 새로운 컬럼을 추가하고자 한다면 \"ALTER TABLE 학생 ADD 이메일 VARCHAR(50);\"과 같이 작성할 수 있다.\nALTER TABLE 테이블이름 DROP 열이름;"],["실제 사례","더 이상 필요하지 않은 열을 삭제할 때는 DROP 절을 사용한다. 열을 삭제하면 해당 열에 저장되어 있던 모든 데이터가 함께 사라지므로, 실무에서는 열을 삭제하기 전에 반드시 데이터 백업 여부를 확인하는 것이 안전하다."]]},{"t":"② ALTER TABLE MODIFY 열 변경","n":[["설명","MODIFY를 이용한 변경\nALTER TABLE 테이블이름 MODIFY 열이름 데이터타입 [DEFAULT 값];"],["쉬운 예","이미 존재하는 열의 데이터 타입이나 기본값을 변경하고자 할 때는 MODIFY 절을 사용한다. 예를 들어 문자열의 최대 길이를 늘리거나, 숫자 타입의 정밀도를 조정할 때 활용한다."],["쉬운 예","열의 데이터 타입을 변경할 때는 기존에 저장되어 있는 데이터와 새로운 데이터 타입 간의 호환성을 반드시 고려해야 한다. 예를 들어 문자열이 저장되어 있는 열을 숫자형으로 변경하려 하면 오류가 발생할 수 있으며, 문자열의 길이를 기존 데이터보다 짧게 줄이면 데이터가 잘려나가는 문제가 발생할 수 있다."]]}]},{"t":"(2) DROP과 TRUNCATE","c":[{"t":"① DROP TABLE 테이블 삭제","n":[["설명","DROP TABLE\nDROP TABLE 테이블이름;"],["시험 포인트","DROP TABLE 문은 테이블 자체를 완전히 삭제하는 명령문으로, 테이블의 구조와 데이터가 모두 사라지며 이와 관련된 인덱스, 제약조건 등도 함께 삭제된다. 한번 실행하면 되돌리기 어려운 명령이므로 각별한 주의가 필요하다.\nTRUNCATE TABLE 테이블이름;"]]},{"t":"② RENAME TABLE 이름 변경","n":[["설명","RENAME TABLE 구문\nRENAME TABLE 이전테이블이름 TO 새로운테이블이름;\nRENAME TABLE 문은 이미 존재하는 테이블의 이름을 변경할 때 사용하는 명령문이다.\nALTER TABLE 이전테이블이름 RENAME 새로운테이블이름;\n제품에 따라 RENAME TABLE 문 대신 ALTER TABLE 문에 RENAME 절을 결합하여 테이블 이름을 변경하는 방식을 지원하기도 한다. 두 방식 모두 최종적으로는 동일하게 테이블의 이름만 변경될 뿐, 테이블 내부의 데이터나 제약조건에는 영향을 주지 않는다."]]}]}]}]},{"t":"Ⅴ 다양한 데이터 타입의 활용","c":[{"t":"1. 대용량 데이터 타입","c":[{"t":"(1) 텍스트와 이진 데이터","c":[{"t":"① TEXT·CLOB 대용량 문자","n":[["설명","TEXT와 CLOB 게시글 본문이나 상세 설명과 같이 매우 긴 문자열을 저장해야 할 때는 VARCHAR의 최대 길이 제한을 넘어서는 경우가 많아, TEXT나 CLOB(Character Large OBject)과 같은 대용량 문자 데이터 타입을 사용한다. 이러한 타입은 일반 문자열보다 훨씬 큰 용량의 텍스트를 저장할 수 있다."],["실제 사례","이미지, 동영상, 첨부 파일과 같은 이진(Binary) 데이터를 데이터베이스에 직접 저장해야 하는 경우에는 BLOB(Binary Large OBject) 타입을 사용한다. 다만 대용량 이진 파일을 데이터베이스에 직접 저장하면 데이터베이스의 크기가 급격히 커지고 성능이 저하될 수 있어, 실무에서는 파일 자체는 별도의 파일 서버나 스토리지에 저장하고 데이터베이스에는 해당 파일의 경로만 저장하는 방식이 흔히 사용된다."]]},{"t":"② BOOLEAN·자동 증가 컬럼","n":[["설명","BOOLEAN 데이터 타입 참(True) 또는 거짓(False)의 두 가지 값만을 가지는 논리형 데이터를 저장할 때는 BOOLEAN 타입을 사용한다. 다만 일부 DBMS 제품에서는 BOOLEAN 타입을 별도로 제공하지 않고, 0과 1의 숫자값으로 대체하여 표현하기도 한다. 기본키로 사용되는 일련번호 컬럼은 데이터가 삽입될 때마다 자동으로 1씩 증가하는 값을 갖도록 설정할 수있으며, 이를 자동 증가(AUTO_INCREMENT) 속성이라고 한다. 이를 활용하면 사용자가 매번 고유한 값을 직접 지정하지 않아도, 데이터베이스가 자동으로 중복되지 않는 기본키 값을 생성해 준다."]]}]},{"t":"(2) 명명 규칙과 설계 원칙","c":[{"t":"① 테이블·컬럼 명명 규칙","n":[["설명","테이블과 컬럼의 명명 규칙"],["쉬운 예","테이블과 컬럼의 이름을 지을 때는 그 의미를 명확하게 알 수 있도록 일관된 명명 규칙을 적용하는 것이 바람직하다. 예를 들어 테이블명은 복수형 명사(orders, students)로, 컬럼명은 소문자와 언더스코어를 조합한 형태(student_id, created_at)로 통일하는 방식이 실무에서 널리 사용된다."],["쉬운 예","각 컬럼에 적절한 데이터 타입을 선택하는 것은 저장 공간의 효율성뿐 아니라 데이터의 무결성 유지에도 큰 영향을 미친다. 예를 들어 전화번호를 숫자형(INT)으로 저장하면 앞자리의 0이 생략되거나 하이픈을 포함할 수 없는 문제가 발생하므로, 전화번호와 같이 숫자로 보이지만 실제로는 식별자의 성격을 갖는 데이터는 문자형(VARCHAR)으로 저장하는 것이 바람직하다."]]},{"t":"② 정규화 장단점·반정규화","n":[["설명","정규화된 설계의 장단점 앞서 학습한 정규화 이론에 따라 테이블을 여러 개로 분해하여 설계하면 데이터 중복이 최소화되고 무결성이 향상되지만, 데이터를 조회할 때마다 여러 테이블을 조인해야 하므로 조회 성능이 저하될 수 있다는 단점도 함께 존재한다. 반정규화는 조회 성능을 향상시키기 위해 의도적으로 정규화 원칙을 일부 완화하여, 중복 데이터를 허용하거나 여러 테이블의 데이터를 하나의 테이블로 통합하는 설계 기법이다. 다만 반정규화는 데이터 중복으로 인한 갱신 이상의 위험을 감수해야 하므로, 조회 성능과 데이터 무결성 사이의 트레이드오프를 신중하게 고려하여 적용해야 한다."]]}]}]}]},{"t":"Ⅵ 스키마 객체의 관리와 시퀀스","c":[{"t":"1. 시퀀스(Sequence)","c":[{"t":"(1) 시퀀스의 개념","c":[{"t":"① CREATE SEQUENCE 순차 번호","n":[["설명","시퀀스란\nCREATE SEQUENCE 시퀀스이름\nSTART WITH 1\nINCREMENT BY 1;\n시퀀스는 기본키와 같이 자동으로 순차적인 숫자값을 생성해 주는 데이터베이스 오브젝트이다. 여러 사용자가 동시에 데이터를 입력하더라도 서로 중복되지 않는 고유한 번호를 순서대로 발급받을 수 있도록 해 준다. 위 예시는 1부터 시작하여 1씩 증가하는 시퀀스를 생성하는 구문이다. 시퀀스를 생성한 후에는 \"시퀀스이름.NEXTVAL\"과 같은 형태로 다음 순번 값을 가져와 INSERT 문에 활용할 수 있다. 이는 앞서 학습한 자동 증가(AUTO_INCREMENT) 컬럼과 유사한 목적을 갖지만, 시퀀스는 특정 테이블에 종속되지 않는 독립적인 오브젝트로서 여러 테이블에서 공통으로 사용할 수 있다는 차이가 있다."]]},{"t":"② ALTER·DROP SEQUENCE","n":[["설명","ALTER SEQUENCE\nALTER SEQUENCE 시퀀스이름 INCREMENT BY 2;\n이미 생성된 시퀀스의 증가값이나 최댓값 등의 속성은 ALTER SEQUENCE 문을 통해 변경할 수 있다. 다만 이미 발급된 값 자체를 소급하여 변경할 수는 없으며, 이후 발급되는 값부터 새로운 설정이 적용된다.\nDROP SEQUENCE 시퀀스이름;\n더 이상 필요하지 않은 시퀀스는 DROP SEQUENCE 문으로 삭제할 수 있다. 시퀀스를 삭제하면 해당 시퀀스를 참조하고 있던 애플리케이션에서 더 이상 새로운 순번 값을 발급받을 수 없게 되므로, 삭제 전 다른 오브 젝트에서의 참조 여부를 반드시 확인해야 한다."]]}]},{"t":"(2) 동의어(Synonym)","c":[{"t":"① CREATE SYNONYM 별칭","n":[["설명","동의어의 개념\nCREATE SYNONYM 별칭 FOR 원본테이블이름;\n동의어는 테이블, 뷰 등의 데이터베이스 오브젝트에 대해 별도의 다른 이름(별칭)을 부여하는 기능이다. 이를 활용하면 복잡하거나 긴 오브젝트 이름 대신 간단한 이름으로 접근할 수 있으며, 여러 스키마에 걸쳐 있는 오브젝트에 대해 마치 하나의 스키마에 있는 것처럼 접근할 수 있도록 해 준다."],["실제 사례","동의어는 실제 테이블의 이름이나 위치가 변경되더라도, 응용 프로그램에서는 동의어만을 사용하도록 하여 실제 변경 사항이 응용 프로그램 코드에 영향을 주지 않도록 하는 용도로도 활용된다. 이는 앞서 학습한 뷰가 제공하는 논리적 독립성과 유사한 효과를 제공한다."]]},{"t":"② 테이블 구조 확인 DESC","n":[["설명","테이블 구조 확인"],["실제 사례","대부분의 DBMS는 DESC(DESCRIBE)나 이와 유사한 명령어를 통해 특정 테이블의 컬럼 구성, 데이터 타입, 제약조건 등의 구조 정보를 간편하게 확인할 수 있는 기능을 제공한다. 이는 실제 데이터를 조회하는 것이 아니라, 테이블 자체의 메타데이터(스키마 정보)를 확인하는 용도로 사용된다."]]}]}]}]},{"t":"Ⅶ 파티션과 테이블 스페이스","c":[{"t":"1. 테이블 파티셔닝(Partitio ning)","c":[{"t":"(1) 파티셔닝의 개념","c":[{"t":"① 파티셔닝: 대용량 테이블 분할","n":[["설명","파티셔닝이란 파티셔닝은 하나의 대용량 테이블을 물리적으로 여러 개의 작은 단위(파티션)로 나누어 저장하는 기법이다. 사용자나 응용 프로그램에서는 여전히 하나의 논리적인 테이블처럼 취급하여 질의할 수 있지만, 내부적으로는 데이터가 분할된 여러 저장 공간에 나뉘어 저장된다."],["쉬운 예","대용량 로그 테이블이나 거래 내역 테이블처럼 데이터가 매우 빠르게 누적되는 경우, 파티셔닝을 적용 하지 않으면 테이블 전체를 검색해야 하므로 조회 성능이 크게 저하될 수 있다. 예를 들어 월별로 파티션을 나누어 두면, 특정 월의 데이터만 조회하는 질의는 해당 월의 파티션만 검색하면 되므로 성능이 크게 향상된다."]]},{"t":"② 범위·해시 파티셔닝","n":[["설명","범위 파티셔닝과 해시 파티셔닝 범위 파티셔닝(Range Partitioning)은 특정 컬럼의 값 범위(예: 날짜, 숫자 구간)를 기준으로 데이터를 나누는 방식으로, 날짜 기반의 로그 데이터에 흔히 사용된다. 해시 파티셔닝(Hash Partitioning)은 특정 컬럼의 값을 해시 함수에 통과시킨 결과를 기준으로 데이터를 고르게 분산시키는 방식으로, 데이터가 특정 파티션에 치우치지 않고 균등하게 분배되도록 하는 데 유리하다."],["쉬운 예","목록 파티셔닝(List Partitioning)은 특정 컬럼이 가질 수 있는 값의 목록을 미리 정의하여, 그 값에 따라 데이터를 나누는 방식이다. 예를 들어 지역 컬럼의 값이 \"서울\", \"경기\", \"기타\"인 경우에 따라 각각 다른 파티션에 저장하도록 구성할 수 있다."]]}]},{"t":"(2) 테이블 스페이스(Tablesp ace)","c":[{"t":"① 테이블 스페이스 개념","n":[["설명","테이블 스페이스의 개념"],["실제 사례","테이블 스페이스는 데이터베이스의 데이터가 실제로 저장되는 논리적인 저장 공간의 단위로, 하나 이상의 물리적 데이터 파일과 연결되어 있다. 테이블이나 인덱스와 같은 오브젝트를 생성할 때, 이를 어느 테이블 스페이스에 저장할 것인지 지정할 수 있다."]]},{"t":"② 저장 공간 부족 시 파일 추가","n":[["설명","저장 공간 부족에 대한 대응 데이터가 계속 누적되어 테이블 스페이스의 저장 공간이 부족해지면, 새로운 데이터 파일을 추가하거나 기존 데이터 파일의 크기를 확장하는 방식으로 대응할 수 있다. 데이터베이스 관리자는 이러한 저장 공간의 사용 추이를 지속적으로 모니터링하여, 공간 부족으로 인한 서비스 장애가 발생하지 않도록 사전에 대비해야 한다. 파티셔닝이 적용된 테이블에서는 보관 기한이 지난 오래된 파티션을 통째로 삭제하거나 별도의 저장소로 이전(아카이빙)하는 방식으로 저장 공간을 효율적으로 관리할 수 있다. 이는 개별 행을 하나씩 DELETE하는 것보다 훨씬 빠르고 효율적인 데이터 정리 방법이다."]]}]}]}]},{"t":"Ⅷ DDL 실전 종합 예제","c":[{"t":"1. 업무 시나리오 기반 테이블 설계","c":[{"t":"(1) 주문 관리 시스템 설계 예시","c":[{"t":"① 고객·주문 테이블 CREATE 예시","n":[["설명","테이블 구조 설계\nCREATE TABLE 고객 (\n      고객번호 INT PRIMARY KEY,\n      이름 VARCHAR(20) NOT NULL,\n      전화번호 VARCHAR(20),\n      가입일 DATE DEFAULT SYSDATE\n);\nCREATE TABLE 주문 (\n      주문번호 INT PRIMARY KEY,\n      고객번호 INT,\n      주문일자 DATE NOT NULL,\n      총금액 INT CHECK (총금액 >= 0),\n      FOREIGN KEY (고객번호) REFERENCES 고객(고객번호)\n         ON DELETE CASCADE\n);\n위 예시는 고객과 주문이라는 두 개의 테이블을 설계하는 과정을 보여준다. 고객 테이블의 고객번호를 기본키로 지정하고, 주문 테이블에서는 이를 외래키로 참조하도록 구성하였다. ON DELETE CASCADE 옵션을 지정하였으므로, 만약 고객 정보가 삭제되면 그 고객과 관련된 주문 내역도 함께 삭제된다. 총금액 컬럼에는 CHECK 제약조건을 적용하여 음수 값이 입력되지 않도록 하였으며, 이름 컬럼에는 NOT NULL 제약조건을 적용하여 반드시 값이 입력되도록 하였다. 이처럼 테이블을 설계할 때는 단순히 컬럼과 데이터 타입만 정의하는 것이 아니라, 데이터의 논리적 제약까지 함께 고려하여 무결성을 확보하는 것이 중요하다."]]},{"t":"② 이메일 컬럼·CHECK 추가 예시","n":[["설명","요구사항 변경에 따른 ALTER TABLE\nALTER TABLE 고객 ADD 이메일 VARCHAR(50);\nALTER TABLE 주문 ADD CONSTRAINT ck_금액 CHECK (총금액 <= 10000000);\n서비스 운영 중 이메일 수집이 추가로 필요해졌다면, 위와 같이 ALTER TABLE 문으로 이메일 컬럼을 고객 테이블에 추가할 수 있다. 또한 비정상적으로 큰 금액이 입력되는 것을 방지하기 위해, 이름을 지정한 CHECK 제약조건을 나중에 추가로 적용할 수도 있다. 위 예시처럼 제약조건에 \"ck_금액\"과 같이 명시적인 이름을 부여해 두면, 이후 이 제약조건을 삭제하거나 비활성화해야 할 때 이름으로 명확하게 지정할 수 있어 관리가 편리해진다. 이름을 지정하지 않으면 시스템이 자동으로 생성한 이름을 사용해야 하므로 관리가 번거로워질 수 있다."]]}]},{"t":"(2) 문제 유형별 접근","c":[{"t":"① 빈칸 채우기형 문제 접근","n":[["설명","빈칸 채우기형 문제"],["시험 포인트","실기 시험에서는 CREATE TABLE 문의 일부 키워드나 옵션이 빈칸으로 제시되고 이를 채우는 형태의 문제가 자주 출제된다. 이러한 문제를 풀 때는 먼저 전체 구문의 큰 흐름(CREATE TABLE - 컬럼 정의 - 제약조건)을 파악한 뒤, 빈칸 앞뒤의 문맥을 통해 어떤 키워드나 데이터 타입이 들어가야 할지 유추하는 순서로 접근하는 것이 효과적이다."],["시험 포인트","주어진 DDL 문장에서 문법 오류를 찾아 수정하는 유형의 문제도 자주 출제되며, 흔한 오류 유형 으로는 데이터 타입과 값의 불일치, 세미콜론 누락, 괄호의 짝이 맞지 않는 경우, PRIMARY KEY와 FOREIGN KEY의 순서나 참조 대상 오기재 등이 있다. 이러한 유형은 평소 정확한 문법을 반복적으로 연습해 두어야 실수 없이 풀어낼 수 있다."]]},{"t":"② 자동 증가 컬럼 문법 차이","n":[["설명","자동 증가 컬럼의 문법 차이"],["시험 포인트","자동으로 증가하는 일련번호 컬럼을 정의하는 문법은 DBMS 제품마다 차이가 있어, 어떤 제품은 AUTO_INCREMENT 키워드를, 어떤 제품은 별도의 시퀀스 오브젝트를, 또 어떤 제품은 IDENTITY라는 키워드를 사용한다. 시험 문제에서 특정 DBMS를 명시하고 있다면 그 제품의 문법을 정확히 따라야 한다."],["시험 포인트","DDL의 기본적인 골격(CREATE, ALTER, DROP)은 대부분의 DBMS 제품에서 공통적이지만, 세부적인 옵션이나 데이터 타입의 명칭은 제품별로 차이가 있을 수 있다. 시험에서는 특정 제품에 종속되지 않는 표준적인 SQL 문법을 중심으로 출제되는 경향이 있으므로, 기본기를 충실히 다져 두는 것이 가장 안전한 대비 방법이다."]]}]}]}]}]},{"t":"제3절 DML과 데이터 조작","c":[{"t":"Ⅰ DML의 개념과 SELECT문 기본","c":[{"t":"1. DML의 개념과 유형","c":[{"t":"(1) DML이란","c":[{"t":"① DML: 조회·추가·변경·삭제","n":[["설명","DML의 정의 DML은 데이터 조작어(Data Manipulation Language)로서, 데이터를 조작하는 명령어를 의미한다. 여기서 조작이란 데이터의 관점에서 데이터의 생명 주기(조회, 추가, 변경, 삭제)를 제어하는 것을 말한다."],["실제 사례","DML은 데이터 조회를 담당하는 SELECT, 데이터 추가를 담당하는 INSERT, 데이터 변경을 담당하는 UPDATE, 데이터 삭제를 담당하는 DELETE의 네 가지 명령어로 구성된다. 이 중 SELECT는 가장 많이 사용되는 SQL 명령어로서, 다른 DML 명령어와 함께 사용되며 실무와 시험 모두에서 매우 중요한 비중을 차지한다."]]},{"t":"② SELECT 기본 형식","n":[["설명","기본 형식\nSELECT [옵션] 컬럼목록 FROM 테이블 [WHERE 조건];"],["쉬운 예","SELECT 문은 위와 같은 기본 형식을 가지며, 옵션(ALL 또는 DISTINCT), 조회할 컬럼 목록, 조회 대상 테이블, 그리고 조건을 지정하는 WHERE 절로 구성된다. 예를 들어 \"SELECT 이름, 학과 FROM 학생\nWHERE 학년 = 3;\"은 학생 테이블에서 학년이 3인 행들의 이름과 학과 컬럼만을 조회하는 질의문이다."],["쉬운 예","ALL 옵션은 중복을 포함한 조회 결과를 그대로 출력하며, 별도로 옵션을 지정하지 않으면 기본값으로 ALL이 적용된다. DISTINCT 옵션은 중복된 행을 제외하고 유일한 값만을 출력한다. 예를 들어 \"SELECT DISTINCT 학과 FROM 학생;\"이라고 작성하면 학생 테이블에 존재하는 학과의 종류만을 중복 없이 조회할 수있다."]]}]},{"t":"(2) 비교 연산자와 논리 연산자","c":[{"t":"① 비교 연산자","n":[["설명","비교 연산자"],["쉬운 예","WHERE 절에서는 =(같음), <>또는 !=(같지 않음), >(초과), <(미만), >=(이상), <=(이하)와 같은 비교 연산자를 사용하여 조건을 지정할 수 있다. 예를 들어 \"SELECT * FROM 학생 WHERE 성적 >= 90;\"은 성적이 90점 이상인 학생만을 조회한다."],["쉬운 예","여러 조건을 결합할 때는 AND(모든 조건을 만족), OR(조건 중 하나라도 만족), NOT(조건의 부정)과 같은 논리 연산자를 사용한다. 예를 들어 \"SELECT * FROM 학생 WHERE 학년 = 3 AND 학과 = '컴퓨터공학과';\"는 3학년이면서 동시에 컴퓨터공학과에 속한 학생만을 조회한다."]]},{"t":"② BETWEEN·IN·LIKE","n":[["설명","BETWEEN, IN, LIKE"],["쉬운 예","BETWEEN A AND B는 A와 B 사이의 범위(A, B 포함)에 속하는 값을 조건으로 지정할 때 사용한다. IN(값1, 값2, ...)은 여러 값 중 하나와 일치하는 경우를 조건으로 지정할 때 사용한다. LIKE 연산자는 문자열의 부분 일치를 검색할 때 사용하며, %(임의의 여러 문자)와 _(임의의 한 문자)를 와일드카드로 활용한다. 예를 들어 \"SELECT * FROM 학생 WHERE 이름 LIKE '김%';\"는 이름이 \"김\"으로 시작하는 모든 학생을 조회한다."],["쉬운 예","널(NULL) 값은 \"=\" 연산자로 비교할 수 없으며, 반드시 IS NULL 또는 IS NOT NULL을 사용해야한다. 예를 들어 \"SELECT * FROM 학생 WHERE 전화번호 IS NULL;\"은 전화번호가 입력되지 않은 학생을 조회하는 질의문이다. 각 연산자 앞에 NOT을 붙이면 조건을 부정할 수 있으며(NOT BETWEEN, NOT IN, NOT LIKE), 반환되는 결과가 정반대로 뒤바뀐다는 점에 유의해야 한다."]]}]}]}]},{"t":"Ⅱ 정렬과 그룹화","c":[{"t":"1. ORDER BY를 이용한 정렬","c":[{"t":"(1) ORDER BY의 기본 사용법","c":[{"t":"① ORDER BY ASC/DESC","n":[["설명","오름차순과 내림차순 정렬\nSELECT 컬럼목록 FROM 테이블 ORDER BY 정렬기준컬럼 [ASC|DESC];"],["쉬운 예","ORDER BY 절은 조회 결과를 특정 컬럼을 기준으로 정렬할 때 사용한다. ASC(Ascending)는 오름차순 정렬을 의미하며 생략 시 기본값으로 적용되고, DESC(Descending)는 내림차순 정렬을 의미한다. 예를 들어 \"SELECT * FROM 학생 ORDER BY 성적 DESC;\"는 성적이 높은 순서대로 학생을 조회한다."],["쉬운 예","ORDER BY 절에는 여러 개의 컬럼을 콤마로 구분하여 지정할 수 있으며, 이 경우 앞에 명시된 컬럼을 우선 기준으로 정렬하고, 그 값이 같은 행들에 대해서는 그다음에 명시된 컬럼을 기준으로 다시 정렬한다. 예를 들어 \"ORDER BY 학과 ASC, 성적 DESC;\"는 학과별로 오름차순 정렬한 뒤, 같은 학과 내에서는 성적이 높은 순으로 다시 정렬한다."]]},{"t":"② 널 정렬 순서·별칭 정렬","n":[["설명","널 값의 정렬 순서 정렬 기준 컬럼에 널 값이 포함되어 있는 경우, DBMS 제품에 따라 널 값을 가장 먼저 배치하거나 가장 나중에 배치하는 등 처리 방식이 상이할 수 있다. 정확한 정렬 순서가 중요한 경우에는 이러한 제품별 차이를 확인해야 한다.\nSELECT 절에서 AS를 이용해 컬럼에 별칭(Alias)을 부여한 경우, ORDER BY 절에서는 원래의 컬럼명 대신\n이 별칭을 사용하여 정렬 기준을 지정할 수 있다. 또한 SELECT 절에 나열된 컬럼의 순서 번호(1, 2, 3, ...)를이용해 정렬 기준을 지정하는 것도 가능하다."]]}]},{"t":"(2) GROUP BY를 이용한 그룹화","c":[{"t":"① GROUP BY 학과별 COUNT","n":[["설명","GROUP BY의 개념\nSELECT 학과, COUNT(*) FROM 학생 GROUP BY 학과;\nGROUP BY 절은 특정 컬럼의 값이 같은 행들을 하나의 그룹으로 묶어 집계 함수를 적용할 때 사용한다. 위예시는 학생 테이블을 학과별로 그룹화하여, 각 학과에 속한 학생의 수를 집계하는 질의문이다. GROUP BY 절을 사용하는 SELECT 문에서는, SELECT 절에 집계 함수가 아닌 일반 컬럼을 나열하려면 그컬럼이 반드시 GROUP BY 절에도 포함되어 있어야 한다. 그렇지 않으면 하나의 그룹 안에 여러 값이 존재 하게 되어 어떤 값을 출력해야 할지 알 수 없는 모순이 발생하기 때문이다."]]},{"t":"② HAVING AVG(성적)>=80","n":[["설명","HAVING의 개념\nSELECT 학과, AVG(성적) FROM 학생 GROUP BY 학과 HAVING AVG(성적) >= 80;\nHAVING 절은 GROUP BY로 묶인 그룹에 대해 조건을 지정할 때 사용한다. 위 예시는 학과별 평균 성적을 구한 뒤, 그중 평균 성적이 80점 이상인 학과만을 결과로 출력하는 질의문이다."],["시험 포인트","WHERE 절은 그룹화가 이루어지기 전, 개별 행(튜플) 단위로 조건을 적용하여 필터링하는 반면, HAVING 절은 그룹화가 이루어진 이후 그룹 단위로 조건을 적용한다는 근본적인 차이가 있다. 따라서 HAVING 절에서는 집계 함수(SUM, AVG 등)를 조건식에 사용할 수 있지만, WHERE 절에서는 집계 함수를 직접 사용할 수 없다. 이는 매우 중요한 차이점으로 시험에 자주 출제된다."]]}]}]}]},{"t":"Ⅲ 집계 함수와 주요 내장 함수","c":[{"t":"1. 집계 함수(Aggregate Function)","c":[{"t":"(1) 개수와 합계","c":[{"t":"① COUNT 함수","n":[["설명","COUNT 함수"],["쉬운 예","COUNT 함수는 조회된 행의 개수를 세는 함수이다. \"COUNT(*)\"는 널 값을 포함한 모든 행의 개수를 세며, \"COUNT(컬럼명)\"은 해당 컬럼의 값이 널이 아닌 행의 개수만을 센다. 예를 들어 \"SELECT COUNT(*) FROM 학생;\"은 학생 테이블 전체의 행 수를 반환한다."],["쉬운 예","SUM 함수는 숫자형 컬럼 값들의 합계를 계산하는 함수이다. 예를 들어 \"SELECT SUM(성적)\nFROM 학생 WHERE 학과 = '컴퓨터공학과';\"는 컴퓨터공학과 학생들의 성적 총합을 계산한다. 문자형이나 날\n짜형 컬럼에는 SUM 함수를 적용할 수 없다."]]},{"t":"② AVG 함수","n":[["설명","AVG 함수"],["쉬운 예","AVG 함수는 숫자형 컬럼 값들의 평균을 계산하는 함수이다. 예를 들어 \"SELECT AVG(성적)\nFROM 학생;\"은 학생 테이블 전체의 평균 성적을 계산한다. AVG 함수는 기본적으로 널 값을 계산에서 제외하\n고 평균을 구한다는 점에 유의해야 한다."],["쉬운 예","MAX 함수는 컬럼의 값 중 가장 큰 값을, MIN 함수는 가장 작은 값을 반환하는 함수이다. 숫자형뿐 아니라 문자형(사전 순서 기준)이나 날짜형(시간 순서 기준) 컬럼에도 적용할 수 있다. 예를 들어 \"SELECT MAX(성적), MIN(성적) FROM 학생;\"은 전체 학생 중 최고 성적과 최저 성적을 함께 조회한다."]]}]},{"t":"(2) 문자열 함수","c":[{"t":"① 문자열 결합·길이 함수","n":[["설명","문자열 결합과 길이"],["쉬운 예","CONCAT 함수 또는 \" 결과 \" 연산자는 두 개 이상의 문자열을 하나로 결합할 때 사용한다. 예를 들어 \"SELECT 이름 || '님' FROM 학생;\"은 각 학생의 이름 뒤에 \"님\"이라는 문자열을 결합하여 출력한다. LENGTH 함수는 문자열의 길이(글자 수)를 반환한다."]]},{"t":"② ROUND·TRUNC·ABS·MO D","n":[["설명","숫자 함수 ROUND 함수는 숫자를 지정된 자릿수에서 반올림하며, TRUNC 함수는 지정된 자릿수 이하를 버림(절사)한다. ABS 함수는 숫자의 절댓값을 반환하며, MOD 함수는 두 숫자를 나눈 나머지 값을 반환한다."],["실제 사례","SYSDATE 또는 NOW 함수는 현재 시스템의 날짜와 시간을 반환하며, 대부분의 DBMS 제품에서 널리 사용된다. 두 날짜 사이의 간격을 계산하거나, 날짜에 특정 기간(일, 월, 년)을 더하고 빼는 연산도 가능하며, 이는 회원 가입일로부터 특정 기간이 지났는지를 판별하는 등의 실무 질의에서 자주 활용된다."]]}]}]}]},{"t":"Ⅳ INSERT, UPDATE, DELETE","c":[{"t":"1. INSERT를 이용한 데이터 추가","c":[{"t":"(1) INSERT 문의 기본 형식","c":[{"t":"① INSERT 컬럼 명시 방식","n":[["설명","컬럼을 명시하는 방식\nINSERT INTO 테이블이름 (컬럼1, 컬럼2, ...) VALUES (값1, 값2, ...);\n INSERT 문은 테이블에 새로운 데이터를 삽입하는 명령문으로, 삽입 결과로 하나의 레코드(튜플)가 추가된다.\n컬럼 목록을 명시적으로 지정하는 방식에서는, VALUES 절에 나열되는 값의 순서와 개수가 앞서 지정한 컬럼의 순서 및 개수와 정확히 일치해야 한다. 명시하지 않은 컬럼에는 기본값(DEFAULT)이나 널(NULL)이 자동으로 채워진다.\nINSERT INTO 테이블이름 VALUES (값1, 값2, ...);"],["실제 사례","컬럼 목록을 생략하는 방식에서는, VALUES 절에 나열되는 값이 테이블에 정의된 모든 컬럼의 순서와 정확히 일치해야 한다. 이 방식은 코드가 간결하지만, 테이블의 구조(컬럼 순서)가 변경될 경우 오류가 발생할 위험이 크므로 실무에서는 컬럼을 명시하는 첫 번째 방식이 더 안전하게 권장된다."]]},{"t":"② 여러 행 한 번에 INSERT","n":[["설명","여러 행을 한 번에 삽입"],["쉬운 예","일부 DBMS 제품에서는 하나의 INSERT 문으로 여러 개의 행을 한꺼번에 삽입하는 것을 지원한다. 예를 들어 \"INSERT INTO 학생 VALUES (1, '김철수'), (2, '이영희');\"와 같이 VALUES 절 뒤에 콤마로 구분된 여러 개의 값 집합을 나열할 수 있다."],["쉬운 예","INSERT INTO 문 뒤에 VALUES 절 대신 SELECT문을 사용하면, 다른 테이블을 조회한 결과를 그대로 삽입할 수 있다. 예를 들어 \"INSERT INTO 우수학생 SELECT * FROM 학생 WHERE 성적 >= 90;\"은 학생 테이블에서 성적이 90점 이상인 데이터를 조회하여 우수학생 테이블에 그대로 삽입하는 질의문이다."]]}]},{"t":"(2) UPDATE를 이용한 데이터 변경","c":[{"t":"① UPDATE SET 기본 형식","n":[["설명","UPDATE 문의 기본 형식\nUPDATE 테이블 SET 컬럼1 = 값1, 컬럼2 = 값2, ... [WHERE 조건];"],["쉬운 예","UPDATE 문은 테이블에 이미 저장된 데이터를 변경, 수정할 때 사용한다. 보통 WHERE 절을 통해 특정 조건을 만족하는 행에 대해서만 지정된 컬럼의 값을 수정하는 용도로 많이 사용된다. 예를 들어 \"UPDATE 학생 SET 학년 = 4 WHERE 학번 = '20240001';\"은 학번이 20240001인 학생의 학년을 4로 변경한다."],["실제 사례","UPDATE 문에서 WHERE 절을 생략하면 테이블에 존재하는 모든 행의 지정된 컬럼 값이 한꺼번에 변경되므로, 실무에서는 이러한 실수를 방지하기 위해 UPDATE 문을 실행하기 전 반드시 동일한 조건으로\nSELECT 문을 먼저 실행하여 변경 대상 행을 확인하는 습관을 들이는 것이 중요하다."]]},{"t":"② DELETE FROM 기본 형식","n":[["설명","DELETE 문의 기본 형식\nDELETE FROM 테이블 [WHERE 조건];"],["쉬운 예","DELETE 문은 테이블에 저장된 레코드를 삭제할 때 사용한다. 조건절 없이 DELETE 문을 사용하는 경우, 해당 테이블의 모든 행이 한 번에 삭제되므로 각별한 주의가 필요하다. 예를 들어 \"DELETE FROM 학생\nWHERE 학과 = '중퇴';\"는 학과가 \"중퇴\"로 표시된 학생 데이터만을 삭제한다."],["시험 포인트","DELETE는 DML 명령어로서 WHERE 절을 사용해 원하는 행만 선택적으로 삭제할 수 있고, 삭제 결과를 트랜잭션 관점에서 롤백(ROLLBACK)할 수 있다는 특징이 있다. 반면 앞서 학습한 TRUNCATE는 DDL 명령어로서 테이블 전체 내용을 한 번에 삭제하며, 대체로 롤백이 불가능하고 처리 속도가 더 빠르다는 차이가 있다. 이 둘의 차이는 시험에서 매우 자주 다루어지는 핵심 포인트이다."]]}]}]}]},{"t":"Ⅴ JOIN을 이용한 다중 테이블 조회","c":[{"t":"1. 논리적 조인의 개념과 종류","c":[{"t":"(1) 조인(JOIN)의 개념","c":[{"t":"① 조인: 2개 이상 테이블 결합","n":[["설명","조인이란 조인은 결합을 의미하며, 관계형 데이터베이스에서의 조인은 두 개 이상의 테이블을 결합하여 데이터를 추출하는 기법을 말한다. 관계형 데이터베이스는 데이터의 중복을 최소화하기 위해 정규화를 통해 데이터를 여러 테이블로 분해하여 저장하며, 이렇게 분해된 데이터를 다시 통합하여 사용할 때 조인 기법이 사용된다. 조인은 관계형 데이터베이스의 가장 큰 장점이자 대표적인 핵심 기능이다. 조인은 크게 논리적 조인과 물리적 조인으로 구분된다. 논리적 조인은 사용자가 작성하는 SQL문에 명시적으로 표현되는 테이블 결합 방식으로, 내부 조인(Inner Join)과 외부 조인(Outer Join)으로 나뉜다. 물리적 조인은 데이터베이스의 옵티마이저에 의해 내부적으로 발생하는 테이블 결합 방식으로, 중첩 반복 조인, 정렬 병합 조인, 해시 조인 등이 있다."]]},{"t":"② 동등 조인·자연 조인","n":[["설명","동등 조인과 자연 조인\nSELECT 학생.이름, 교수.교수명\nFROM 학생, 교수\nWHERE 학생.지도교수번호 = 교수.교수번호;\n동등 조인(Equi Join)은 두 테이블에 공통으로 존재하는 컬럼의 값이 일치하는 행만을 추출하는 조인 방식으로, 가장 일반적으로 사용되는 조인 형태이다. 위 예시는 학생 테이블과 교수 테이블을 지도교수번호와 교수 번호가 일치하는 조건으로 결합하여 조회하는 질의문이다. 자연 조인(Natural Join)은 두 테이블의 모든 컬럼을 비교하여 이름이 같은 모든 컬럼의 값이 일치하는 경우를 추출하는 조인이다."],["쉬운 예","교차 조인은 조인 조건 없이 두 테이블의 모든 데이터 조합(카티션 곱)을 추출하는 조인 방식이다. 예를 들어 5행을 가진 테이블과 3행을 가진 테이블을 교차 조인하면 15행의 결과가 생성된다. 실무에서는 의도치 않게 조인 조건을 누락하여 교차 조인이 발생하는 경우가 많은 오류의 원인이 되므로 주의해야 한다."]]}]},{"t":"(2) 외부 조인의 종류","c":[{"t":"① LEFT/RIGHT OUTER JOIN","n":[["설명","왼쪽 외부 조인과 오른쪽 외부 조인\nSELECT 학생.이름, 교수.교수명\nFROM 학생 LEFT OUTER JOIN 교수\nON 학생.지도교수번호 = 교수.교수번호;\n왼쪽 외부 조인(Left Outer Join)은 왼쪽 테이블의 모든 데이터와 오른쪽 테이블의 일치하는 데이터를 추출하며, 오른쪽 테이블에 대응하는 값이 없는 경우 해당 컬럼은 널 값으로 표시된다. 위 예시는 지도교수가 아직 배정되지 않은 학생까지도 결과에 포함시켜 조회하는 질의문이다. 오른쪽 외부 조인(Right Outer Join)은 이와 반대로 오른쪽 테이블의 모든 데이터를 기준으로 조회한다. 완전 외부 조인은 왼쪽 테이블과 오른쪽 테이블 양쪽의 모든 데이터를 추출하는 조인으로, 어느 한쪽에만 존재하고 다른 쪽에는 대응하는 값이 없는 데이터까지 모두 결과에 포함시킨다. 일부 DBMS 제품에서는 FULL OUTER JOIN 구문을 직접 지원하지 않아, UNION을 이용해 왼쪽 외부 조인과 오른쪽 외부 조인의 결과를 합쳐 구현하기도 한다."]]},{"t":"② Nested Loop·Sort-M erge 조인","n":[["설명","중첩 반복 조인과 정렬 병합 조인 중첩 반복 조인(Nested Loop Join)은 두 개 이상의 테이블에서 하나의 집합을 기준으로 바깥 테이블의 처리 범위를 하나씩 접근하면서, 그렇게 추출된 값으로 안쪽 테이블을 조인하는 방식이다. 정렬 병합 조인(Sort-Merge Join)은 적당한 인덱스가 없을 때 사용되며, 양쪽 테이블의 처리 범위를 각각 정렬한 후 그 결과를 순서대로 스캔하며 연결 고리 조건으로 병합하는 방식이다. 해시 조인은 조인할 테이블에 대해 해시 함수를 생성하고, 해시 함수의 결과 순서대로 결과를 출력하는 방식이다. 이러한 물리적 조인 기법은 사용자가 SQL문에 직접 명시하는 것이 아니라, 데이터베이스의 옵티마이저가 테이블의 크기, 인덱스 존재 여부 등을 고려하여 자동으로 가장 효율적인 방식을 선택하여 처리하게 된다."]]}]}]}]},{"t":"Ⅵ 서브쿼리와 집합 연산자","c":[{"t":"1. 서브쿼리(Sub Query)","c":[{"t":"(1) 서브쿼리의 개념과 유형","c":[{"t":"① 서브쿼리: SQL 안의 SQL","n":[["설명","서브쿼리란\nSELECT 이름 FROM 학생\nWHERE 학과 = (SELECT 학과 FROM 학생 WHERE 학번 = '20240001');\n서브쿼리는 하나의 SQL문 안에 포함된 또 다른 SQL문을 의미하며, 미리 알려지지 않은 조건을 검색하기 위해 사용된다. 메인 쿼리와 서브쿼리의 관계는 주종 관계이기 때문에, 서브쿼리는 메인 쿼리의 컬럼 정보를 사용할 수 있으나 그 반대는 성립하지 않는다. 위 예시는 특정 학번의 학생과 같은 학과에 속한 다른 학생들의 이름을 조회하는 질의문이다. 비연관(Un-Correlated) 서브쿼리는 서브쿼리가 메인 쿼리의 컬럼을 사용하지 않는 형태로, 메인 쿼리에 서브쿼리에서 실행된 결과값을 제공하는 용도로 사용된다. 연관(Correlated) 서브쿼리는 서브쿼리가 메인 쿼리의 컬럼을 사용하는 형태로, 메인 쿼리에서 먼저 얻은 데이터가 서브쿼리의 조건에 맞는지 확인하고자 할때 사용된다."]]},{"t":"② 단일 행·다중 행 서브쿼리","n":[["설명","단일 행과 다중 행 서브쿼리 단일 행(Single Row) 서브쿼리는 서브쿼리의 실행 결과가 오직 하나의 값으로 반환되는 서브쿼리로, =, >, < 등의 일반적인 비교 연산자와 함께 사용된다. 다중 행(Multiple Row) 서브쿼리는 서브쿼리의 실행 결과가 여러 건으로 반환되는 서브쿼리로, IN, ALL, ANY(SOME), EXISTS와 같은 다중 행 비교 연산자와 함께 사용해야 한다. IN은 서브쿼리 결과 중 하나와 일치하는 경우, ALL은 서브쿼리 결과 모두를 만족하는 경우(예: > ALL은 모든 값보다 큰 경우), ANY(또는 SOME)는 서브쿼리 결과 중 하나라도 만족하는 경우, EXISTS는 서브쿼리의 실행 결과가 존재하는지 여부(참/거짓)만을 확인할 때 사용한다. 다중 컬럼(Multiple Column) 서브쿼리는 서브쿼리의 결과가 여러 컬럼으로 반환되는 경우로, 메인 쿼리의 조건절과 비교하는 컬럼의 개수와 위치가 반드시 동일해야 한다."]]}]},{"t":"(2) 집합 연산의 개념","c":[{"t":"① 집합 연산: 질의 결과 결합","n":[["설명","집합 연산이란 집합 연산은 테이블을 하나의 집합으로 보고, 두 개 이상의 질의 결과를 하나의 결과로 합쳐 주는 연산 방식이다. 일반적으로 서로 다른 테이블에서 유사한 형태의 결과를 반환하는 질의를 하나로 합치고자 할 때, 또는 동일한 테이블에서 서로 다른 조건으로 조회한 질의 결과를 합치고자 할 때 사용한다. 집합 연산자로 결합되는 여러 SELECT 문은 조회하는 컬럼의 개수와 데이터 타입이 서로 일치해야 한다는 제약이 있다. 컬럼의 이름이 다르더라도 개수와 자료형의 순서만 일치하면 결합이 가능하며, 최종 결과에는 첫번째 SELECT 문에서 지정한 컬럼명이 표시된다."]]},{"t":"② UNION 중복 제거·UNION ALL","n":[["설명","UNION과 UNION ALL\nSELECT 이름 FROM 재학생\nUNION\nSELECT 이름 FROM 휴학생;\nUNION은 여러 SELECT문의 결과에 대한 합집합을 구하며, 이 과정에서 중복된 행은 제거된다. UNION ALL은 UNION과 마찬가지로 합집합을 구하지만 중복된 행을 제거하지 않고 그대로 모두 포함시킨다는 차이가 있다. 중복 제거 연산은 추가적인 처리 비용이 발생하므로, 중복 데이터가 없음을 알고 있거나 중복을 신경 쓰지 않아도 되는 상황이라면 UNION ALL이 더 빠르게 처리된다. INTERSECT(또는 INTERSECTION)는 여러 SELECT문의 결과에 대한 교집합을 구하며 중복된 행을 제거한다. MINUS는 앞의 SELECT문 결과와 뒤의 SELECT문 결과 사이의 차집합을 구하며 역시 중복된 행을 제거하는데, 일부 제품(예: 일부 오픈소스 DBMS)에서는 MINUS 대신 EXCEPT라는 키워드를 사용한다는 점에 유의해야 한다."]]}]}]}]},{"t":"Ⅶ 윈도우 함수(Window Function)","c":[{"t":"1. 윈도우 함수의 개념","c":[{"t":"(1) 윈도우 함수란","c":[{"t":"① RANK() OVER PARTITION BY","n":[["설명","윈도우 함수의 정의\nSELECT 이름, 학과, 성적,\n      RANK() OVER (PARTITION BY 학과 ORDER BY 성적 DESC) AS 학과내순위\nFROM 학생;\n윈도우 함수는 GROUP BY처럼 여러 행을 하나로 합치지 않으면서도, 관련된 행들의 집합(윈도우)을 기준으로 순위, 누적합, 이동평균과 같은 집계 성격의 계산을 수행할 수 있게 해주는 함수이다. 위 예시는 학과별로 성적 순위를 매기되, 그룹화 없이 개별 학생 행을 그대로 유지하면서 순위 컬럼만 추가하는 질의문이다."],["실제 사례","윈도우 함수에서 PARTITION BY 절은 GROUP BY와 유사하게 데이터를 특정 기준으로 나누는 역할을 하지만, 실제로 행을 합치지는 않는다는 차이가 있다. ORDER BY 절은 각 파티션 내에서 행의 순서를 정하는 기준을 지정하며, 순위나 누적 계산에 필수적으로 사용된다."]]},{"t":"② RANK·DENSE_RANK·RO W_NUMBER","n":[["설명","순위 함수 RANK 함수는 순위를 매기되 동점이 있을 경우 다음 순위를 건너뛰며(예: 공동 1위가 두 명이면 다음은 3위) , DENSE_RANK 함수는 동점이 있어도 순위를 건너뛰지 않는다(공동 1위가 두 명이어도 다음은 2위). ROW_NUMBER 함수는 동점 여부와 관계없이 매 행마다 고유하게 증가하는 순번을 부여한다."],["쉬운 예","SUM, AVG, COUNT와 같은 일반 집계 함수도 OVER 절과 함께 사용하면 윈도우 함수로 활용할 수있다. 예를 들어 \"SUM(급여) OVER (PARTITION BY 부서 ORDER BY 입사일)\"과 같이 작성하면, 각 부서 내에서 입사일 순서대로 급여의 누적 합계를 계산할 수 있다."]]}]},{"t":"(2) 실무 활용 예시","c":[{"t":"① TOP-N 조회","n":[["설명","TOP-N 조회"],["쉬운 예","윈도우 함수는 각 그룹별 상위 N개의 데이터를 조회하는 TOP-N 질의에서 매우 유용하게 활용된다. 예를 들어 각 학과별로 성적이 가장 높은 학생 3명씩을 조회하고자 할 때, RANK 함수로 학과 내 순위를 계산한뒤 이 순위가 3 이하인 행만 다시 필터링하는 방식으로 구현할 수 있다."]]},{"t":"② WHERE절 윈도우 함수 사용 불가","n":[["설명","WHERE 절과의 관계 윈도우 함수는 WHERE 절이 실행된 이후, SELECT 절이 처리되는 단계에서 계산되기 때문에 WHERE 절에 윈도우 함수의 결과를 직접 조건으로 사용할 수 없다는 제약이 있다. 특정 순위 이하의 데이터만 걸러내고 싶다면, 윈도우 함수를 포함한 질의를 서브쿼리로 감싼 뒤 바깥쪽 질의의 WHERE 절에서 필터링해야 한다."],["실제 사례","윈도우 함수는 매우 강력한 기능이지만, 대량의 데이터에 대해 정렬과 파티션 작업을 수행하므로 인덱스가 적절히 구성되어 있지 않으면 성능 저하의 원인이 될 수 있다. 실무에서는 파티션 및 정렬 기준이 되는 컬럼에 인덱스를 구성해 두는 것이 성능 최적화에 도움이 된다."]]}]}]}]},{"t":"Ⅷ 계층형 질의와 조건 표현식","c":[{"t":"1. 계층형 질의(Hierarchic al Query)","c":[{"t":"(1) 계층형 데이터의 조회","c":[{"t":"① 계층형 데이터 정의","n":[["설명","계층형 데이터란"],["쉬운 예","조직도나 게시판의 답글 구조처럼, 하나의 테이블 안에서 특정 행이 다른 행을 부모로 참조하는 형태의 데이터를 계층형(Hierarchical) 데이터라고 한다. 예를 들어 사원 테이블에서 각 사원이 자신의 상급자 사번을 참조하는 컬럼(관리자번호)을 갖는 구조가 대표적인 예이다."]]},{"t":"② START WITH·CONNECT BY PRIOR","n":[["설명","CONNECT BY 구문 일부 DBMS 제품에서는 START WITH와 CONNECT BY PRIOR 구문을 이용해 계층형 질의를 직접 지원한다. START WITH 절에서는 계층 구조의 출발점(최상위 노드)을 지정하며, CONNECT BY PRIOR 절에서는 부모와 자식 행 사이의 연결 관계를 지정한다. 표준 SQL에서는 WITH RECURSIVE(재귀적 공통 테이블 표현식)를 이용해 계층형 질의를 구현할 수 있다. 이는 기준이 되는 초기 결과(앵커 멤버)와, 이전 단계의 결과를 참조하여 반복적으로 다음 단계를 찾아나가는 재귀 멤버로 구성되며, 더 이상 새로운 행이 조회되지 않을 때까지 반복 실행된다."]]}]},{"t":"(2) CASE 표현식의 활용","c":[{"t":"① CASE WHEN 학점 변환","n":[["설명","단순 CASE와 검색 CASE\nSELECT 이름,\nCASE WHEN 성적 >= 90 THEN 'A' WHEN 성적 >= 80 THEN 'B' ELSE 'C' END AS 학점\nFROM 학생;\nCASE 표현식은 조건에 따라 서로 다른 값을 반환할 수 있도록 하는 조건부 표현식으로, 프로그래밍 언어의 if-else 구문과 유사한 역할을 SQL 안에서 수행한다. 위 예시는 학생의 성적 구간에 따라 A, B, C의 학점을 부여하는 질의문이다."],["쉬운 예","CASE 표현식은 SELECT 절뿐만 아니라 WHERE 절, ORDER BY 절, GROUP BY 절 등 값이 필요한 대부분의 위치에서 자유롭게 사용할 수 있다. 예를 들어 GROUP BY 절에 CASE 표현식을 사용하면, 원래의 컬럼값을 임의의 구간이나 범주로 재분류하여 집계할 수 있다."]]},{"t":"② COALESCE·NVL 널 대체","n":[["설명","COALESCE와 NVL"],["쉬운 예","COALESCE 함수는 여러 개의 인자 중 널이 아닌 첫 번째 값을 반환하는 함수로, 표준 SQL에서 지원된다. 일부 DBMS 제품에서는 이와 유사한 기능을 하는 NVL이나 ISNULL과 같은 함수를 자체적으로 제공하기도 한다. 예를 들어 \"COALESCE(전화번호, '미등록')\"과 같이 사용하면, 전화번호가 널인 경우 \"미등록\"이라는 문자열을 대신 출력할 수 있다."]]}]}]}]},{"t":"Ⅸ 다중 테이블 조작 실전 예제","c":[{"t":"1. 복합 조건을 활용한 SELECT 실습","c":[{"t":"(1) 여러 조건을 결합한 실전 질의","c":[{"t":"① 복합 WHERE+ORDER BY 실습","n":[["설명","상황 설정과 질의 작성 -- 학생(학번, 이름, 학과, 학년, 성적) 테이블에서 -- 컴퓨터공학과 3학년 이상 학생 중 성적이 85점 이상인 -- 학생을 성적 내림차순으로 조회\nSELECT 학번, 이름, 성적\nFROM 학생\nWHERE 학과 = '컴퓨터공학과'\nAND 학년 >= 3 AND 성적 >= 85\nORDER BY 성적 DESC;"],["시험 포인트","실기 시험이나 실무에서는 위와 같이 여러 조건을 AND로 결합하고, 그 결과를 특정 기준으로 정렬하는 형태의 질의문이 매우 빈번하게 출제되고 사용된다. 조건절을 작성할 때는 문자열 값을 작은따옴표로 감싸야 하며, 숫자 값은 따옴표 없이 그대로 작성한다는 기본 규칙을 반드시 지켜야 한다.\nSELECT s.이름 AS 학생이름, p.교수명 AS 지도교수\nFROM 학생 s, 교수 p\nWHERE s.지도교수번호 = p.교수번호;"],["실제 사례","테이블 이름이 길거나 동일한 컬럼명이 여러 테이블에 존재하는 경우, 테이블과 컬럼에 별칭(Alias)을 부여하면 질의문을 훨씬 간결하고 명확하게 작성할 수 있다. 위 예시처럼 테이블에 s, p와 같은 짧은 별칭을 부여하고, 컬럼에는 AS를 이용해 사용자가 이해하기 쉬운 이름을 부여하는 방식이 실무에서 널리 사용된다."]]},{"t":"② 조인+GROUP BY+HAVING 통계","n":[["설명","학과별 통계와 조인의 결합\nSELECT d.학과명, COUNT(s.학번) AS 학생수, AVG(s.성적) AS 평균성적\nFROM 학생 s, 학과 d\nWHERE s.학과코드 = d.학과코드\nGROUP BY d.학과명 HAVING COUNT(s.학번) >= 10\nORDER BY 평균성적 DESC;"],["실제 사례","위 질의문은 학생 테이블과 학과 테이블을 조인한 뒤, 학과별로 그룹화하여 학생 수와 평균 성적을 계산하고, 학생 수가 10명 이상인 학과만 필터링하여 평균 성적이 높은 순으로 정렬하는 복합적인 질의문이다. 이처럼 조인, GROUP BY, HAVING, ORDER BY를 함께 사용하는 형태는 실무 리포트 작성에서 매우 자주 활용되는 패턴이다.\nSELECT 이름, 성적\nFROM 학생\nWHERE 성적 > (SELECT AVG(성적) FROM 학생)\nORDER BY 성적 DESC;"]]}]},{"t":"(2) 조건부 UPDATE와 서브쿼리를 이용한 갱신","c":[{"t":"① 서브쿼리 UPDATE 장학여부","n":[["설명","서브쿼리를 이용한 UPDATE\nUPDATE 학생\nSET 장학여부 = 'Y'\nWHERE 성적 >= (SELECT AVG(성적) FROM 학생 WHERE 학과 = '컴퓨터공학과')\n AND 학과 = '컴퓨터공학과';\n위 질의문은 컴퓨터공학과의 평균 성적을 서브쿼리로 계산한 뒤, 그 평균 이상의 성적을 가진 같은 학과 학생들의 장학여부를 \"Y\"로 갱신하는 예시이다. 이처럼 UPDATE 문의 조건절(WHERE)에도 서브쿼리를 자유롭게 사용할 수 있다. 여러 테이블에 걸쳐 관련된 데이터를 변경해야 하는 경우(예: 주문 취소 시 주문 테이블과 재고 테이블을 함께 갱신), 각각의 UPDATE 문을 하나의 트랜잭션으로 묶어 처리해야 원자성이 보장된다. 즉 두 UPDATE 문이 모두 성공했을 때만 COMMIT을 수행하고, 하나라도 실패하면 ROLLBACK을 수행하여 데이터의 일관성을 유지해야 한다."]]},{"t":"② 요구사항 분석의 중요성","n":[["설명","요구사항 분석의 중요성"],["시험 포인트","실기 시험에서 SQL 문제를 풀 때는 먼저 문제에서 요구하는 결과 테이블의 형태(어떤 컬럼이 필요한지)를 정확히 파악하고, 그다음 그 컬럼들이 어느 테이블에 존재하는지, 여러 테이블에 걸쳐 있다면 어떤 컬럼을 기준으로 조인해야 하는지를 순서대로 분석하는 것이 중요하다."]]}]}]}]},{"t":"Ⅹ 질의 성능 최적화 기초","c":[{"t":"1. 실행 계획(Execution Plan)","c":[{"t":"(1) 실행 계획의 개념","c":[{"t":"① 실행 계획: 옵티마이저·EXPLA IN","n":[["설명","실행 계획이란 실행 계획은 DBMS의 옵티마이저가 특정 SQL문을 처리하기 위해 선택한 세부적인 처리 순서와 방법(어떤 인덱스를 사용할지, 어떤 조인 기법을 사용할지 등)을 보여주는 정보이다. 대부분의 DBMS는 EXPLAIN이나 이와 유사한 명령어를 통해 특정 질의의 실행 계획을 미리 확인할 수 있는 기능을 제공한다. 동일한 결과를 반환하는 SQL문이라도 작성 방식에 따라 실행 계획이 크게 달라질 수 있으며, 이는 처리 속도에 직접적인 영향을 미친다. 따라서 성능이 중요한 질의문을 작성할 때는 실행 계획을 확인하여, 불필요하게 전체 테이블을 검색(풀 스캔)하고 있지는 않은지 점검하는 것이 중요하다."]]},{"t":"② 인덱스 vs 풀 스캔","n":[["설명","인덱스와 조회 성능\nWHERE 절이나 JOIN 조건에 자주 사용되는 컬럼에 인덱스가 존재하면, DBMS는 테이블 전체를 검색하는\n대신 인덱스를 이용해 원하는 데이터의 위치를 빠르게 찾아갈 수 있다. 다만 인덱스가 있다고 해서 항상 사용되는 것은 아니며, 조회하려는 데이터의 비율이 테이블 전체의 상당 부분을 차지한다면 오히려 풀 스캔이 더효율적일 수도 있다. 인덱스는 조회(SELECT) 성능을 향상시키지만, 데이터가 삽입, 삭제, 갱신될 때마다 인덱스 자체도 함께 갱신해야 하므로 데이터 변경 작업의 성능은 오히려 저하될 수 있다. 따라서 조회가 빈번한 컬럼에는 인덱스를 생성하되, 지나치게 많은 인덱스를 생성하는 것은 오히려 전체적인 성능에 악영향을 줄 수 있다는 점을 유의해야 한다."]]}]},{"t":"(2) 인덱스를 무력화시키는 패턴","c":[{"t":"① 컬럼 함수 적용 시 인덱스 무력화","n":[["설명","컬럼에 함수를 적용하는 경우\nWHERE 절에서 인덱스가 걸린 컬럼에 함수를 적용하면(예: \"WHERE SUBSTR(학번, 1, 4) = '2024'\"), 인\n덱스가 정상적으로 활용되지 못하고 풀 스캔이 발생할 수 있다. 이러한 경우에는 함수를 적용하는 대신, 별도의 계산된 컬럼을 미리 만들어 두거나 조건식을 변형하여 인덱스가 활용될 수 있도록 개선하는 것이 바람직하다. LIKE 연산자를 사용할 때 검색어의 맨 앞에 % 와일드카드를 배치하면(예: \"WHERE 이름 LIKE '%수'\"), 인덱스를 효율적으로 활용하기 어려워진다. 반면 검색어의 뒤쪽에만 % 와일드카드를 배치하면(예: \"WHERE 이름 LIKE '김%'\") 인덱스를 활용한 검색이 가능한 경우가 많다."]]},{"t":"② 상황별 인덱스 활용 선택","n":[["설명","상황에 따른 선택"],["실제 사례","동일한 요구사항이라도 서브쿼리를 사용하는 방식과 조인을 사용하는 방식으로 각각 SQL문을 작성할 수 있는 경우가 많은데, 데이터의 양과 분포, 인덱스의 존재 여부에 따라 성능 차이가 크게 발생할 수 있다. 일반적으로 조인이 서브쿼리보다 옵티마이저가 최적화하기에 더 유리한 경우가 많지만, 항상 그런 것은 아니므로 실제 실행 계획을 확인하여 판단하는 것이 바람직하다."],["실제 사례","실무에서는 SELECT * 와 같이 모든 컬럼을 무분별하게 조회하는 대신, 실제로 필요한 컬럼만을 명시적으로 지정하여 조회하는 것이 네트워크 트래픽과 처리 부담을 줄이는 좋은 습관이다. 특히 대용량 테이블에서 일부 컬럼에만 인덱스가 걸려 있는 경우, 필요한 컬럼만 조회하면 인덱스만으로 결과를 반환하는 인덱스 온리 스캔이 가능해져 성능이 크게 향상되기도 한다."],["실제 사례","위 질의문은 날짜 문자열의 앞 7자리(연-월)를 추출하는 문자열 함수를 GROUP BY의 기준으로 활용하여, 월별 매출 통계를 산출하는 실무형 질의문이다. 이처럼 문자열 함수나 날짜 함수를 GROUP BY와 결합하여 원하는 단위로 데이터를 집계하는 패턴은 실무 리포트 작성에서 매우 빈번하게 사용된다.\nSELECT c.이름, COUNT(o.주문번호) AS 총주문수, SUM(o.총금액) AS 총구매액\nFROM 고객 c LEFT OUTER JOIN 주문 o\nON c.고객번호 = o.고객번호 GROUP BY c.이름\nORDER BY 총구매액 DESC NULLS LAST;"],["시험 포인트","위 질의문은 IN 연산자와 다중 행 서브쿼리를 활용하여, \"DB01\"과 \"NW01\" 두 과목을 모두 수강하고 있는 학생을 조회하는 질의문이다. 이처럼 여러 개의 서브쿼리를 AND로 결합하여 복수의 조건을 동시에 만족하는 대상을 찾는 패턴은 실기 시험에서 자주 다루어지는 유형이다.\nSELECT 학번 FROM 수강 WHERE 과목코드 = 'DB01'\nINTERSECT\nSELECT 학번 FROM 수강 WHERE 과목코드 = 'NW01';"],["시험 포인트","앞서 서브쿼리로 작성한 질의문은 집합 연산자인 INTERSECT를 이용해서도 동일한 결과를 얻을수 있다. 이처럼 하나의 요구사항을 서브쿼리, 조인, 집합 연산자 등 여러 방식으로 표현할 수 있다는 점을 이해해 두면, 실기 시험에서 특정 문법이 막히더라도 다른 접근 방식으로 문제를 해결할 수 있는 유연성을 기를 수있다."],["실제 사례","문법이 정확하더라도 문제에서 요구하는 조건과 실제 작성한 조건이 일치하는지, 조인 조건이 누락되어 의도치 않은 교차 조인이 발생하지는 않는지, GROUP BY와 HAVING의 사용이 적절한지 등 논리적인 측면까지 함께 검토하는 것이 실기 시험에서 고득점을 얻기 위한 핵심 요령이다."],["쉬운 예","CUBE는 ROLLUP과 달리 지정된 모든 컬럼 조합에 대한 소계를 빠짐없이 산출해 주는 기능이다. 예를 들어 \"GROUP BY CUBE(학과, 학년)\"는 학과별 소계, 학년별 소계, 학과와 학년의 조합별 소계, 전체 총계를 모두 포함한 결과를 반환하여, ROLLUP보다 더 다양한 차원의 집계를 한 번에 확인할 수 있다."],["실제 사례","ROLLUP이나 CUBE를 사용하면 소계나 총계를 나타내는 행에서는 해당 컬럼의 값이 널로 표시되 는데, 이 널 값이 실제 데이터의 널인지 아니면 소계를 나타내는 널인지 구분하기 어려운 경우가 있다. GROUPING 함수는 이러한 상황에서 특정 컬럼이 소계를 나타내는 행인지 여부를 1 또는 0으로 알려주는 역할을 한다."],["쉬운 예","실무에서 특정 DBMS 제품을 사용할 때는, 표준 SQL로 작성 가능한 부분과 그 제품에서만 지원하는 확장 문법을 구분하여 이해하는 것이 중요하다. 예를 들어 페이징 처리(특정 개수만큼만 조회) 구문은 제품마다 LIMIT, TOP, ROWNUM 등으로 상이하게 표현된다."],["시험 포인트","자격시험에서는 특정 제품에 종속되지 않는 표준적인 문법을 중심으로 다루는 경우가 많으므로, 이 교재에서 학습한 기본 SELECT 구조, WHERE 조건, GROUP BY와 HAVING, JOIN, 서브쿼리, 집합 연산자, DDL과 DCL의 기본 문법을 확실히 익혀 두는 것이 가장 효과적인 학습 전략이다."]]}]}]}]}]},{"t":"제4절 DCL·TCL과 SQL 활용 심화","c":[{"t":"Ⅰ DCL(Data Control Language)의 개념과 활용","c":[{"t":"1. DCL의 정의와 유형","c":[{"t":"(1) DCL이란","c":[{"t":"① DCL: 권한·트랜잭션 제어","n":[["설명","DCL의 정의 DCL은 데이터 제어어(Data Control Language)로서, 데이터베이스에서 데이터 이외의 오브젝트에 대해 조작할 필요가 있을 때 사용하는 SQL 명령어를 말한다. DCL의 조작 대상에는 사용자 권한(사용자를 등록하고 특정 데이터베이스를 사용할 수 있는 권리를 부여하는 접근 통제 목적)과 트랜잭션(동시에 다수의 작업을 독립적이고 안전하게 처리하기 위한 상호작용 단위)이 있다."],["시험 포인트","DCL은 크게 사용자 권한을 관리하는 GRANT(권한 부여), REVOKE(권한 회수)와, 트랜잭션을 제어하는 TCL(Transaction Control Language)인 COMMIT(트랜잭션 확정), ROLLBACK(트랜잭션 취소) , CHECKPOINT(복귀 지점 설정)로 구분할 수 있다. 시험에서는 GRANT와 REVOKE를 DCL로, COMMIT과 ROLLBACK을 TCL로 세분화하여 다루기도 한다."]]},{"t":"② 시스템 권한·객체 권한","n":[["설명","시스템 권한 시스템 권한은 데이터베이스 자체에 대한 권한으로, 사용자 계정을 생성하는 CREATE USER, 계정을 삭제하는 DROP USER, 데이터베이스에 접속하는 CREATE SESSION, 테이블을 생성하는 CREATE TABLE, 뷰를 생성하는 CREATE VIEW, 함수를 생성하는 CREATE PROCEDURE 등이 있다. 객체 권한은 특정 테이블이나 뷰와 같은 개별 객체에 대한 권한으로, 데이터를 추가하는 INSERT, 삭제하는 DELETE, 조회하는 SELECT, 변경하는 UPDATE, 프로시저를 실행하는 EXECUTE 등이 있다. 시스템 권한은 데이터베이스 차원의 권한이고, 객체 권한은 특정 객체 단위의 권한이라는 차이를 구분해서 이해해야 한다."]]}]},{"t":"(2) 권한 부여(GRANT)","c":[{"t":"① GRANT ~ ON ~ TO 구문","n":[["설명","시스템 권한과 객체 권한 부여\nGRANT 권한1, 권한2 TO 사용자계정;\nGRANT 권한1, 권한2 ON 객체명 TO 사용자계정;"],["쉬운 예","시스템 권한을 부여할 때는 \"GRANT 권한1, 권한2 TO 사용자계정;\"과 같이 대상 객체 없이 사용자계 정에 직접 권한을 부여한다. 객체 권한을 부여할 때는 \"ON 객체명\"을 추가하여 어떤 객체에 대한 권한인지를 명시해야 한다. 예를 들어 \"GRANT SELECT, INSERT ON 학생 TO 김철수;\"는 김철수라는 사용자에게 학생 테이블에 대한 조회 및 삽입 권한을 부여하는 명령문이다."]]},{"t":"② REVOKE ~ FROM 권한 회수","n":[["설명","권한 회수 구문\nREVOKE 권한1, 권한2 FROM 사용자계정;\nREVOKE 권한1, 권한2 ON 객체명 FROM 사용자계정;\n REVOKE는 GRANT에 대응하는 권한 회수 명령어로, 사용자에게 부여했던 권한을 다시 거두어들일 때 사용\n한다. 시스템 권한 회수는 \"FROM 사용자계정\" 형태로, 객체 권한 회수는 \"ON 객체명 FROM 사용자계정\" 형태로 작성한다. 만약 WITH GRANT OPTION을 통해 권한이 다른 사용자에게 재위임된 상태에서 원래 사용자의 권한을 회수하면, 대부분의 DBMS는 이렇게 연쇄적으로 위임된 권한까지 함께 회수하는 CASCADE 방식을 기본으로 채택하고 있다. 이는 권한 관리의 일관성을 유지하기 위한 조치이다."]]}]}]}]},{"t":"Ⅱ 접근 통제(Access Control)","c":[{"t":"1. 접근 통제의 개념과 유형","c":[{"t":"(1) 접근 통제란","c":[{"t":"① 접근 통제: 비인가 사용 방지","n":[["설명","접근 통제의 개념 접근 통제는 데이터베이스의 보안을 구현하는 방법으로, 보안 정책에 따라 접근 객체(시스템 자원, 통신 자원 등)에 대한 접근 주체(사용자, 프로세스 등)의 접근 권한을 확인하고, 이를 기반으로 접근을 제어하여 자원에 대한 비인가된 사용을 방지하는 정보 보호 기능이다. 데이터베이스에는 개인정보, 재무정보 등 민감한 데이터가 다수 포함되어 있으므로, 인가되지 않은 사용자가 함부로 데이터를 조회하거나 변경하지 못하도록 통제하는 것이 매우 중요하다. 앞서 학습한 DCL(GRANT,\nREVOKE)이 바로 데이터베이스에서 접근 통제를 구현하는 대표적인 수단이다."]]},{"t":"② DAC 임의 접근 통제","n":[["설명","임의 접근 통제(DAC) DAC(Discretionary Access Control, 임의 접근 통제)는 시스템 객체에 대한 접근을 사용자 개인 또는 그룹의 식별자를 기반으로 제한하는 방법이다. \"임의적\"이라는 말은 어떤 접근 권한을 갖는 사용자가 자신의 판단에 따라 다른 사용자에게 권한을 부여할 수 있다는 의미이며, 통제 권한이 주체(데이터 소유자)에게 있어 주체가 임의로 접근 통제 권한을 배분하고 제어할 수 있다. MAC(Mandatory Access Control, 강제 접근 통제)는 정보 시스템 내에서 어떤 주체가 특정 객체에 접근하려 할 때, 양쪽의 보안 레이블(Security Label)에 기초하여 높은 보안 수준을 요구하는 정보가 낮은 보안 수준의 주체에게 노출되지 않도록 접근을 제한하는 방법이다. 통제 권한이 제3자(중앙 관리자)에게 있으며, 주체는 접근 통제 권한과 무관하다는 특징이 있다."]]}]},{"t":"(2) DBMS와 DAC의 관계","c":[{"t":"① 상용 DBMS는 DAC 채택","n":[["설명","DBMS가 채택하는 접근 통제 방식 강제 접근 통제(MAC)의 경우 제3자(중앙 관리자)의 종류에 따라 보다 세분화된 정책이 존재할 수 있지만, 일반적으로 상용 데이터베이스 관리 시스템(DBMS)에서 채택하는 접근 통제 정책은 임의 접근 통제(DAC) 방식이다. 즉 데이터베이스 관리, 특히 접근 통제 용도로 SQL에서 사용하는 명령어가 바로 DCL(GRANT,\nREVOKE)이며, 이는 임의 접근 통제 방식에 해당한다."],["실제 사례","실무에서는 데이터베이스 관리자(DBA)가 각 테이블이나 뷰의 소유자로서, 자신이 관리하는 객체에 대한 접근 권한을 각 사용자나 역할(Role)에 부여하는 방식으로 접근 통제를 구현한다. 역할(Role) 개념을 활용하면 여러 사용자에게 공통으로 부여해야 하는 권한들을 하나의 역할로 묶어 관리할 수 있어, 개별 사용자마다 권한을 일일이 부여하는 것보다 관리가 훨씬 용이해진다."]]},{"t":"② DB 감사: 사후 탐지적 통제","n":[["설명","데이터베이스 감사의 개념 데이터베이스 감사는 누가, 언제, 어떤 데이터에 접근하여 어떤 작업을 수행했는지를 기록하고 추적하는 기능을 말한다. 이를 통해 비인가된 접근이나 의심스러운 활동을 사후에 확인하고 대응할 수 있다. 접근 통제가 사전에 비인가된 접근 자체를 차단하는 예방적 조치라면, 감사는 이미 발생한 접근 및 작업 내역을 사후에 검증하는 탐지적 조치라고 할 수 있다. 두 가지 기능이 상호 보완적으로 작동할 때 데이터베이스의 보안 수준을 한층 더 높일 수 있다."]]}]}]}]},{"t":"Ⅲ 트랜잭션(Transaction)과 TCL","c":[{"t":"1. 트랜잭션의 개념과 특성","c":[{"t":"(1) 트랜잭션이란","c":[{"t":"① 트랜잭션: 논리적 작업 단위","n":[["설명","트랜잭션의 정의 트랜잭션은 데이터베이스에서 하나의 논리적 기능을 수행하기 위한 작업의 단위를 말하며, 데이터베이스 관련 연산에서 가장 기본이 되는 처리 단위이다. 데이터베이스 시스템에서 복구나 병행 수행 시 처리되는 작업의 논리적 단위이며, 데이터베이스에 접근하고 갱신하는 하나 또는 여러 개의 SQL 질의문으로 구성된다. 트랜잭션을 설명하는 문제에서는 \"작업 단위\"라는 핵심 키워드를 기준으로 판단하면 된다. 대표적인 예로 은행에서 계좌 이체를 수행하는 경우를 들 수 있다. A 계좌에서 금액을 차감하는 연산과 B 계좌에 금액을 더하는 연산은 각각 별개의 SQL문이지만, 이 두 연산은 반드시 함께 성공하거나 함께 실패해야하는 하나의 논리적 작업 단위, 즉 하나의 트랜잭션으로 처리되어야 한다."]]},{"t":"② 원자성·일관성(ACID)","n":[["설명","원자성과 일관성 원자성(Atomicity)은 트랜잭션의 연산이 데이터베이스에 모두 반영되거나, 혹은 전혀 반영되지 않아야 한다는 성질이다. 트랜잭션 내의 모든 명령이 반드시 완벽하게 수행되어야 하며, 어느 하나라도 오류가 발생하면 트랜잭션 전부가 취소되어야 한다. 일관성(Consistency)은 트랜잭션이 성공적으로 완료된 이후에도 데이터베이스가 일관성 있는 상태를 유지해야 한다는 성질이다."],["시험 포인트","격리성(Isolation)은 하나의 트랜잭션이 실행되는 동안에는 다른 트랜잭션이 그 연산에 끼어들거나 접근할 수 없도록 격리되어야 한다는 성질이다. 지속성(Durability)은 트랜잭션이 성공적으로 완료(커밋)되면 그 결과는 영구적으로 데이터베이스에 반영되어야 하며, 이후 시스템에 장애가 발생하더라도 손실되지 않아야 한다는 성질이다. 트랜잭션의 네 가지 특성인 원자성, 일관성, 격리성, 지속성을 묻는 문제가 시험에 매우 자주 출제된다."]]}]},{"t":"(2) COMMIT과 ROLLBACK","c":[{"t":"① COMMIT 계좌 이체 확정","n":[["설명","COMMIT\nUPDATE 계좌 SET 잔액 = 잔액 - 10000 WHERE 계좌번호 = 'A001';\nUPDATE 계좌 SET 잔액 = 잔액 + 10000 WHERE 계좌번호 = 'B001';\nCOMMIT;\nCOMMIT은 트랜잭션의 실행 결과를 데이터베이스에 영구적으로 확정, 반영하는 명령어이다. 위 예시와 같이 계좌 이체와 관련된 두 개의 UPDATE 문이 모두 정상적으로 처리된 이후 COMMIT을 실행하면, 그 결과가 데이터베이스에 영구히 저장된다."],["쉬운 예","ROLLBACK은 트랜잭션 도중 오류가 발생했거나 작업을 취소하고자 할 때, 트랜잭션 내에서 수행된 변경 사항을 모두 취소하고 트랜잭션이 시작되기 이전의 상태로 되돌리는 명령어이다. 예를 들어 계좌 이체 도중 출금 연산은 성공했으나 입금 연산에서 오류가 발생했다면, ROLLBACK을 실행하여 출금 연산까지도 취소 함으로써 데이터의 일관성을 유지할 수 있다."]]},{"t":"② CHECKPOINT 저장점 부분 취소","n":[["설명","CHECKPOINT CHECKPOINT는 트랜잭션 내에서 ROLLBACK을 수행할 위치(저장점)를 지정하는 명령어이다. 이를 활용하면 트랜잭션 전체를 취소하는 대신, 특정 저장 지점까지만 되돌리는 부분적인 취소가 가능해진다."],["쉬운 예","많은 DBMS 제품에서는 CHECKPOINT와 유사한 개념으로 SAVEPOINT라는 명령어를 제공하며, \" ROLLBACK TO SAVEPOINT 저장점이름;\"과 같은 형태로 특정 저장점까지만 롤백할 수 있다. 예를 들어 여러 단계의 작업으로 구성된 긴 트랜잭션에서 마지막 단계에서만 오류가 발생했다면, 트랜잭션 전체를 취소하는 대신 마지막 저장점 이전까지의 작업은 유지하면서 마지막 단계만 다시 시도할 수 있어 효율적이다."]]}]}]}]},{"t":"Ⅳ SQL 활용 심화 - 프로시저와 트리거","c":[{"t":"1. 저장 프로시저와 사용자 정의 함수","c":[{"t":"(1) 저장 프로시저(Stored Procedure)","c":[{"t":"① CREATE PROCEDURE 저장 프로시저","n":[["설명","저장 프로시저의 개념\nCREATE PROCEDURE 프로시저이름(매개변수)\nAS BEGIN -- 실행할 SQL문들\nEND;\n저장 프로시저는 자주 사용되는 일련의 SQL문들을 하나의 단위로 묶어 데이터베이스 내부에 저장해 두고, 필요할 때마다 이름을 호출하여 실행할 수 있도록 하는 기능이다. 반복적으로 사용되는 복잡한 처리 로직을 매번 새로 작성할 필요 없이, 프로시저를 호출하는 것만으로 간편하게 실행할 수 있다는 장점이 있다. 저장 프로시저를 사용하면 네트워크를 통해 여러 개의 SQL문을 개별적으로 전송하는 대신 하나의 호출만으로 처리할 수 있어 네트워크 부하를 줄일 수 있으며, 동일한 로직을 여러 응용 프로그램에서 재사용할 수 있어 유지보수성이 향상된다. 또한 실행 권한을 프로시저 단위로 관리할 수 있어 보안 관리에도 유리하다."]]},{"t":"② 사용자 정의 함수: RETURN 필수","n":[["설명","사용자 정의 함수의 개념 사용자 정의 함수는 프로시저와 유사하게 일련의 SQL 처리 로직을 하나의 단위로 정의해 두는 기능이지만, 프로시저와 달리 반드시 하나의 값을 반환(RETURN)해야 한다는 차이가 있다. 이렇게 정의된 함수는\nSELECT 문의 컬럼 목록이나 WHERE 절 등 값이 필요한 위치에서 내장 함수처럼 자유롭게 사용할 수 있다.\n프로시저는 여러 개의 값을 매개변수를 통해 반환하거나 아무런 값도 반환하지 않을 수 있는 반면, 함수는 반드시 정확히 하나의 값을 반환해야 한다. 또한 프로시저는 별도의 실행 명령어(CALL 또는 EXECUTE)로 호출해야 하지만, 함수는 SQL문 내부에 직접 포함되어 사용될 수 있다는 차이가 있다."]]}]},{"t":"(2) 트리거의 개념","c":[{"t":"① CREATE TRIGGER 자동 실행","n":[["설명","트리거란\nCREATE TRIGGER 트리거이름\nAFTER INSERT ON 테이블이름 FOR EACH ROW BEGIN -- 자동으로 실행될 SQL문\nEND;\n트리거는 테이블에 삽입, 삭제, 갱신과 같은 특정 이벤트가 발생했을 때, 사용자의 명시적인 호출 없이도 데이터베이스가 자동으로 실행하는 프로시저의 일종이다. 위 예시는 테이블에 새로운 데이터가 삽입될 때마다 (AFTER INSERT) 자동으로 특정 작업을 수행하도록 정의한 트리거이다."],["쉬운 예","트리거는 데이터가 변경될 때마다 변경 이력을 별도의 로그 테이블에 자동으로 기록하거나, 특정 조건을 위반하는 데이터가 입력되지 않도록 검증하거나, 관련된 다른 테이블의 값을 자동으로 함께 갱신하는 등의 용도로 널리 활용된다. 예를 들어 주문 테이블에 새로운 주문이 삽입될 때, 트리거를 이용해 재고 테이블의 수량을 자동으로 차감하도록 구현할 수 있다."]]},{"t":"② 트리거 장점·남용 주의","n":[["설명","트리거의 장점 트리거를 활용하면 데이터 무결성 유지나 감사 로그 기록과 같은 부가적인 작업을, 응용 프로그램의 코드를 일일이 수정하지 않고도 데이터베이스 차원에서 일관되게 적용할 수 있다는 장점이 있다. 다만 트리거는 사용자가 명시적으로 호출하지 않아도 자동으로 실행되기 때문에, 트리거가 지나치게 많거나 복잡하게 얽혀 있으면 데이터 변경 시 어떤 트리거들이 연쇄적으로 실행되는지 추적하기 어려워져 시스템의 성능 저하나 예기치 않은 부작용의 원인이 될 수 있다. 따라서 트리거는 반드시 필요한 경우에 한해 신중하게 설계하여 사용해야 한다."]]}]}]}]},{"t":"Ⅴ 동시성 제어와 병행 제어","c":[{"t":"1. 병행 제어(Concurrency Control)의 개념","c":[{"t":"(1) 병행 제어란","c":[{"t":"① 병행 제어의 필요성","n":[["설명","병행 제어의 필요성"],["실제 사례","병행 제어는 여러 사용자(트랜잭션)가 동시에 데이터베이스에 접근할 때, 트랜잭션들의 연산이 서로 방해받지 않고 정확한 결과를 얻을 수 있도록 순서를 제어하는 기법을 말한다. 여러 트랜잭션을 병행 수행하지 않고 하나씩 순차적으로만 처리한다면 병행 제어가 필요 없겠지만, 이는 시스템의 처리량을 크게 떨어뜨리므로 실무에서는 병행 수행이 필수적이다."]]},{"t":"② 공유 락·배타 락","n":[["설명","공유 락과 배타 락로킹은 병행 제어를 구현하는 대표적인 기법으로, 트랜잭션이 특정 데이터에 접근하기 전에 그 데이터에 대한 잠금(Lock)을 설정하여 다른 트랜잭션의 접근을 제한하는 방식이다. 공유 락(Shared Lock)은 데이터를 읽기만 할 때 설정하는 잠금으로 여러 트랜잭션이 동시에 설정할 수 있으며, 배타 락(Exclusive Lock)은 데이터를 변경할 때 설정하는 잠금으로 다른 트랜잭션은 해당 데이터에 대해 어떠한 락도 추가로 설정할 수 없다. 2단계 로킹 프로토콜(Two-Phase Locking)은 트랜잭션이 필요한 락을 모두 획득하는 확장 단계와, 락을 하나씩 반환하는 축소 단계로 나뉘며, 한번 축소 단계에 들어가면 다시 새로운 락을 획득할 수 없다는 규칙을 갖는 병행 제어 기법이다. 이 프로토콜을 준수하면 트랜잭션의 직렬 가능성(Serializability)을 보장할 수 있다."]]}]},{"t":"(2) 교착상태(Deadlock)와 병행 제어","c":[{"t":"① DB 교착상태(Deadlock)","n":[["설명","데이터베이스에서의 교착상태 로킹 기법을 사용하는 과정에서, 두 개 이상의 트랜잭션이 서로 상대방이 점유한 락을 기다리며 무한정 대기하는 교착상태가 발생할 수 있다. 이는 운영체제에서 학습한 교착상태와 근본적으로 동일한 개념으로, 데이터 베이스에서도 이를 탐지하고 해소하기 위한 별도의 메커니즘이 필요하다. 대부분의 DBMS는 일정 시간 이상 대기 중인 트랜잭션을 탐지하면, 그중 하나(대체로 작업량이 적거나 나중에 시작된 트랜잭션)를 강제로 롤백시켜 나머지 트랜잭션이 계속 진행될 수 있도록 하는 방식으로 교착상태를 해소한다."]]},{"t":"② 격리 수준: 일관성 vs 성능","n":[["설명","격리 수준의 개념 트랜잭션 격리 수준은 여러 트랜잭션이 동시에 실행될 때, 한 트랜잭션이 다른 트랜잭션의 변경 사항을 어느 정도까지 볼 수 있도록 허용할 것인지를 결정하는 수준을 말한다. 격리 수준이 낮을수록 병행 처리 성능은 높아지지만 데이터 일관성이 저하될 위험이 커지며, 격리 수준이 높을수록 데이터 일관성은 보장되지만 병행 처리 성능이 저하될 수 있다. 격리 수준은 낮은 단계부터 READ UNCOMMITTED(커밋되지 않은 데이터까지 읽을 수 있음), READ COMMITTED(커밋된 데이터만 읽을 수 있음), REPEATABLE READ(트랜잭션 동안 동일한 조회 결과를 보장), SERIALIZABLE(가장 엄격한 수준으로 트랜잭션을 순차적으로 실행한 것과 동일한 결과를 보장)의 네단계로 구분된다. 격리 수준이 낮을 때는 더티 리드(Dirty Read), 반복 불가능한 읽기(Non-repeatable Read), 팬텀 리드(Phantom Read)와 같은 이상 현상이 발생할 수 있다."]]}]}]}]},{"t":"Ⅵ 데이터베이스 백업과 회복","c":[{"t":"1. 장애와 회복(Recovery)","c":[{"t":"(1) 장애의 유형","c":[{"t":"① 트랜잭션 장애·시스템 장애","n":[["설명","트랜잭션 장애와 시스템 장애 트랜잭션 장애는 잘못된 데이터 입력이나 트랜잭션 내부의 논리적 오류 등으로 인해 특정 트랜잭션이 정상적으로 완료되지 못하는 장애를 말한다. 시스템 장애는 하드웨어 고장이나 운영체제의 오류로 인해 데이터베이스 시스템 전체의 동작이 중단되는 장애를 말하며, 이 경우 주기억장치에 있던 정보는 손실되지만 디스크에 저장된 데이터베이스 자체는 일반적으로 손상되지 않는다. 미디어 장애는 디스크 헤드의 손상과 같이 데이터가 저장된 물리적 저장 장치 자체에 결함이 발생하는 가장 심각한 유형의 장애를 말한다. 이 경우에는 디스크에 저장된 데이터베이스 자체가 손상되므로, 별도로 보관해둔 백업 데이터를 이용한 복구 작업이 반드시 필요하다."]]},{"t":"② 로그 회복: UNDO·REDO","n":[["설명","로그를 이용한 회복 대부분의 DBMS는 트랜잭션이 수행하는 모든 변경 내역을 로그(Log)라는 별도의 파일에 순차적으로 기록해 둔다. 장애가 발생하면 이 로그를 이용하여, 완료되지 못한 트랜잭션의 변경 사항을 취소(UNDO)하거나, 이미 완료되었지만 디스크에는 아직 반영되지 못한 트랜잭션의 변경 사항을 다시 반영(REDO)하는 방식으로 데이터베이스를 장애 발생 이전의 일관된 상태로 복구한다. 체크포인트(Checkpoint)는 특정 시점까지의 트랜잭션 처리 결과를 데이터베이스에 안전하게 반영해 두고그 시점을 기록해 두는 기법이다. 장애가 발생했을 때 로그 전체를 처음부터 분석하는 대신, 가장 최근의 체크포인트 이후의 로그만을 분석하면 되므로 회복에 걸리는 시간을 크게 단축할 수 있다."]]}]},{"t":"(2) 백업의 유형","c":[{"t":"① 전체 백업·증분 백업","n":[["설명","전체 백업과 증분 백업 전체 백업(Full Backup)은 특정 시점의 데이터베이스 전체를 복사하여 보관하는 방식으로, 복구가 간단하지만 백업에 소요되는 시간과 저장 공간이 크다는 단점이 있다. 증분 백업(Incremental Backup)은 가장 최근의 백업 이후 변경된 데이터만을 백업하는 방식으로, 백업 시간과 저장 공간을 절약할 수 있지만 복구 시에는 전체 백업본과 그 이후의 모든 증분 백업본을 순서대로 적용해야 한다는 번거로움이 있다."],["쉬운 예","백업 주기는 데이터의 중요도, 변경 빈도, 허용 가능한 데이터 손실 범위(RPO, Recovery Point Objective) 등을 종합적으로 고려하여 결정해야 한다. 예를 들어 금융 거래와 같이 데이터 손실이 치명적인 시스템에서는 로그를 실시간으로 백업하여 장애 발생 직전까지의 데이터를 복구할 수 있도록 구성하는 경우가 많다."]]},{"t":"② 복제: 마스터·슬레이브","n":[["설명","복제의 개념 복제는 백업과는 별개로, 운영 중인 데이터베이스의 내용을 실시간 또는 준실시간으로 다른 서버에 동일하게 복사해 두는 기법이다. 원본 데이터베이스(마스터)에 장애가 발생하더라도 복제본(슬레이브)으로 신속하게 전환하여 서비스를 지속할 수 있다는 장점이 있다."],["실제 사례","백업은 특정 시점의 데이터를 별도로 저장해 두었다가 장애 발생 시 그 시점으로 되돌리는 개념인 반면, 복제는 여러 서버가 거의 동일한 최신 데이터를 유지하도록 하여 장애 발생 시에도 서비스 중단 없이 즉시 전환할 수 있도록 하는 개념이라는 점에서 차이가 있다. 실무에서는 두 가지를 함께 구성하여 데이터의 안전성과 서비스의 가용성을 모두 확보하는 것이 일반적이다."]]}]}]}]},{"t":"Ⅶ 데이터베이스 보안의 심화","c":[{"t":"1. 암호화와 감사 로그","c":[{"t":"(1) 데이터 암호화","c":[{"t":"① 저장 데이터 암호화","n":[["설명","저장 데이터 암호화"],["실제 사례","저장 데이터 암호화(Transparent Data Encryption 등)는 데이터베이스 파일 자체에 저장되는 데이터를 암호화하여, 만약 저장 장치나 백업 파일이 유출되더라도 암호화 키가 없이는 실제 내용을 확인할 수 없도록 보호하는 기법이다. 주민번호, 계좌번호와 같이 민감한 개인정보를 저장하는 컬럼에는 이러한 암호화 기법을 적용하는 것이 일반적이다."]]},{"t":"② 감사 로그: 누가·언제·무엇","n":[["설명","감사 로그 수집 대상 감사 로그에는 일반적으로 누가(사용자 계정), 언제(시각), 어떤 데이터에(대상 테이블 및 행), 어떤 작업을(조회, 삽입, 삭제, 변경) 수행했는지에 대한 정보가 기록된다. 특히 개인정보나 재무 정보와 같이 민감한 데이터에 대한 접근은 반드시 감사 로그로 남기도록 정책을 수립하는 것이 일반적이다. 감사 로그는 보안 사고가 발생했을 때 원인을 추적하는 사후 대응 목적뿐만 아니라, 평상시 비정상적인 접근 패턴(예: 심야 시간대의 대량 데이터 조회)을 모니터링하여 사고를 사전에 예방하는 목적으로도 활용된다. 다만 감사 로그 자체가 방대해질 수 있으므로, 로그의 보관 기간과 저장 방식에 대한 정책도 함께 수립해야 한다."]]}]},{"t":"(2) SQL 인젝션(SQL Injection)","c":[{"t":"① SQL 인젝션 개념","n":[["설명","SQL 인젝션의 개념"],["쉬운 예","SQL 인젝션은 응용 프로그램이 사용자로부터 입력받은 값을 제대로 검증하지 않고 SQL문에 그대로 결합하여 실행할 때, 공격자가 입력값에 악의적인 SQL 구문을 삽입하여 원래 의도하지 않은 데이터베이스 명령을 실행시키는 공격 기법이다. 예를 들어 로그인 화면에서 아이디 입력란에 특수한 SQL 구문을 입력하여 비밀번호 없이 인증을 우회하는 공격이 대표적이다."]]},{"t":"② Prepared Statement 방어","n":[["설명","준비된 명령문(Prepared Statement)의 사용"],["실제 사례","준비된 명령문은 SQL문의 구조(뼈대)와 사용자가 입력하는 실제 데이터값을 명확히 분리하여 처리하는 방식으로, 사용자가 입력한 값이 SQL 구문의 일부로 해석되지 않고 순수한 데이터값으로만 처리되도록 보장한다. 이는 SQL 인젝션을 방지하는 가장 근본적이고 효과적인 방법으로 알려져 있다."]]}]}]}]},{"t":"Ⅷ 역할(Role)과 사용자 관리","c":[{"t":"1. 역할(Role) 기반 권한 관리","c":[{"t":"(1) 역할의 개념","c":[{"t":"① CREATE ROLE 권한 묶음","n":[["설명","역할이란\nCREATE ROLE 역할이름;\nGRANT SELECT, INSERT ON 학생 TO 역할이름;\nGRANT 역할이름 TO 사용자계정;\n역할은 여러 개의 권한을 하나의 이름으로 묶어서 관리할 수 있도록 하는 오브젝트이다. 위 예시처럼 역할을 생성하고, 그 역할에 필요한 권한들을 부여한 뒤, 이 역할을 다시 개별 사용자에게 부여하면 여러 권한을 한번에 부여하고 회수할 수 있어 관리가 훨씬 간편해진다. 만약 역할을 사용하지 않고 개별 사용자마다 여러 권한을 하나씩 GRANT한다면, 조직 개편으로 다수의 사용자에게 권한을 변경해야 할 때 매우 번거로운 작업이 필요하다. 반면 역할을 사용하면 역할에 부여된 권한만한 번 수정하면, 그 역할을 부여받은 모든 사용자에게 자동으로 변경 사항이 반영되어 유지보수가 훨씬 용이해진다."]]},{"t":"② 업무별 역할 구성","n":[["설명","업무별 역할 구성"],["실제 사례","실무에서는 일반적으로 조회 전용 역할(SELECT 권한만 부여), 데이터 입력 담당자 역할(SELECT, INSERT, UPDATE 권한 부여), 관리자 역할(모든 권한 부여)과 같이 업무 성격에 따라 역할을 구분하여 구성하고, 각 사용자에게는 그 직무에 필요한 역할만을 부여하는 방식이 널리 사용된다."],["실제 사례","역할을 세분화하여 관리하면 최소 권한 원칙(각 사용자에게 꼭 필요한 최소한의 권한만 부여하는 보안 원칙)을 실무에서 훨씬 체계적으로 적용할 수 있다. 이는 특정 계정이 탈취되더라도 피해 범위를 해당 역할의 권한 범위 내로 최소화하는 데 도움이 된다."]]}]},{"t":"(2) 사용자 계정의 생성과 관리","c":[{"t":"① CREATE USER IDENTIFIED BY","n":[["설명","CREATE USER\nCREATE USER 사용자계정 IDENTIFIED BY 비밀번호;"],["실제 사례","CREATE USER 문은 데이터베이스에 접속할 수 있는 새로운 사용자 계정을 생성하는 명령문이다. 계정을 생성한 직후에는 아무런 권한도 부여되지 않은 상태이므로, 이후 GRANT 문이나 역할 부여를 통해 필요한 권한을 추가로 부여해야 실제 업무에 사용할 수 있다."]]},{"t":"② 비밀번호 정책·계정 잠금","n":[["설명","비밀번호 정책 대부분의 DBMS는 비밀번호의 최소 길이, 복잡도(영문·숫자·특수문자 조합), 유효 기간, 이전에 사용한 비밀번호의 재사용 제한 등을 설정할 수 있는 비밀번호 정책 기능을 제공한다. 이러한 정책을 적절히 설정하면 단순하거나 유출된 비밀번호로 인한 계정 탈취 위험을 줄일 수 있다. 짧은 시간 내에 특정 계정으로 비밀번호 로그인이 반복적으로 실패하는 경우, 이를 무작위 대입 공격 (Brute-force Attack)의 정황으로 간주하여 해당 계정을 일시적으로 잠그는 기능도 중요한 보안 요소이다. 이는 공격자가 비밀번호를 무작위로 계속 시도하여 계정을 탈취하는 것을 효과적으로 방지한다."]]}]}]}]},{"t":"Ⅸ DCL·TCL 실전 종합 예제","c":[{"t":"1. 권한 관리 시나리오","c":[{"t":"(1) 부서별 권한 부여 시나리오","c":[{"t":"① 조회 전용 계정 CREATE SESSION","n":[["설명","조회 전용 계정 구성\nCREATE USER 분석팀 IDENTIFIED BY '비밀번호';\nGRANT CREATE SESSION TO 분석팀;\nGRANT SELECT ON 주문 TO 분석팀;\nGRANT SELECT ON 고객 TO 분석팀;\n통계 분석 업무만을 담당하는 분석팀 계정에는 데이터베이스 접속 권한(CREATE SESSION)과 필요한 테이블에 대한 조회 권한(SELECT)만을 부여하고, 데이터를 변경할 수 있는 INSERT, UPDATE, DELETE 권한은 부여하지 않는 것이 최소 권한 원칙에 부합하는 설계이다.\nREVOKE SELECT ON 고객 FROM 분석팀;\n분석팀의 업무 범위가 변경되어 더 이상 고객 테이블에 접근할 필요가 없어졌다면, 위와 같이 REVOKE 문을 통해 해당 테이블에 대한 조회 권한만 선택적으로 회수할 수 있다. 이처럼 권한은 업무 변화에 맞추어 지속적으로 재검토되고 조정되어야 한다."]]},{"t":"② WITH GRANT OPTION 위험성","n":[["설명","WITH GRANT OPTION의 위험성\nGRANT SELECT ON 주문 TO 팀장 WITH GRANT OPTION;\n-- 팀장이 다시 팀원에게 권한을 위임\nGRANT SELECT ON 주문 TO 팀원;\n팀장에게 WITH GRANT OPTION과 함께 권한을 부여하면, 팀장은 이 권한을 다시 팀원에게 위임할 수 있다. 그러나 이후 관리자가 팀장의 권한을 REVOKE하면, 팀장이 위임했던 팀원의 권한까지 연쇄적으로 회수되는 것이 일반적인 동작 방식이므로, 권한 위임 구조를 설계할 때는 이러한 연쇄 효과를 미리 고려해야 한다. 권한 위임 기능이 남용되면 누가 어떤 권한을 가지고 있는지 파악하기 어려워질 수 있으므로, 데이터베이스 관리자는 정기적으로 전체 사용자와 역할에 부여된 권한 현황을 시스템 카탈로그를 통해 점검하고, 불필요하 거나 과도하게 부여된 권한을 정리하는 권한 감사 작업을 수행하는 것이 바람직하다."]]}]},{"t":"(2) 복합 트랜잭션 처리 시나리오","c":[{"t":"① 계좌 이체 트랜잭션 COMMIT","n":[["설명","계좌 이체 트랜잭션\nUPDATE 계좌 SET 잔액 = 잔액 - 50000 WHERE 계좌번호 = 'A001';\nUPDATE 계좌 SET 잔액 = 잔액 + 50000 WHERE 계좌번호 = 'B001';\n-- 두 UPDATE문이 모두 정상 처리되었는지 확인 후\nCOMMIT;\n계좌 이체와 같은 업무에서는 출금 연산과 입금 연산이 하나의 트랜잭션으로 묶여야 하며, 두 연산이 모두 성공적으로 처리된 것을 확인한 이후에 COMMIT을 실행해야 한다. 만약 출금 연산 이후 시스템 오류가 발생하여 입금 연산이 처리되지 못했다면 반드시 ROLLBACK을 통해 출금 연산까지 취소해야 계좌의 잔액이 부정 확해지는 문제를 막을 수 있다.\nUPDATE 재고 SET 수량 = 수량 - 3 WHERE 상품코드 = 'P001';\nSAVEPOINT 재고차감;\nUPDATE 포인트 SET 잔여포인트 = 잔여포인트 - 100 WHERE 회원번호 = 'M001';\n-- 포인트 차감 단계에서 문제 발생 시\nROLLBACK TO 재고차감;\nCOMMIT;\n위 예시에서는 재고 차감 이후 저장점(SAVEPOINT)을 설정해 두었으므로, 이후 포인트 차감 단계에서 문제가 발생하더라도 트랜잭션 전체를 취소하는 대신 저장점 이전까지의 재고 차감 결과는 그대로 유지하면서 포인트 차감 부분만 취소할 수 있다. 이는 여러 단계로 이루어진 복잡한 업무 처리에서 유용하게 활용되는 패턴이다."]]},{"t":"② 권한 부여 구문 완성 문제","n":[["설명","권한 부여 구문 완성 문제"],["시험 포인트","실기 시험에서는 특정 사용자에게 특정 테이블의 특정 권한을 부여하는 GRANT 문을 완성하는 문제가 출제될 수 있다. 이때 시스템 권한과 객체 권한의 문법 차이(ON 절의 유무)를 정확히 구분하여 작성하는 것이 중요하다."],["시험 포인트","여러 개의 UPDATE, DELETE 문과 COMMIT, ROLLBACK이 순서대로 나열된 상황을 제시하고, 최종적으로 데이터베이스에 어떤 상태가 반영되어 있을지를 묻는 문제도 자주 출제된다. 이러한 문제는 각 SQL문이 실행되는 순서를 차례로 따라가면서, ROLLBACK이 실행되는 시점을 기준으로 그 이전의 변경 사항이 취소되는지 여부를 정확히 판단하는 것이 핵심이다."]]}]}]}]}]}],"k":"필기 3과목"},{"n":4,"t":"정보시스템·테스트·화면","c":[{"t":"제1절 UI/UX 설계와 화면 구현 기초","c":[{"t":"Ⅰ UI의 개념과 종류","c":[{"t":"1. UI(User Interface)의 개념","c":[{"t":"(1) UI의 정의","c":[{"t":"① UI 사용자-시스템 상호작용 매개체","n":[["설명","UI란 UI(User Interface)는 사용자와 시스템 간의 상호작용이 원활하게 이루어지도록 하는 장치나 소프트웨어를 말한다. 인간과 기계, 디지털 기기, 소프트웨어 사이에서 의사소통할 수 있도록 만들어진 화면, 문자, 소리 등의 매개체를 의미하며, 초기에는 단순히 사용자와 컴퓨터 간 상호작용에만 국한되었으나 점차 사용자가 수행할 작업을 구체화하는 기능 위주로, 그리고 최근에는 정보 전달을 위한 표현 방법으로까지 그 개념이 확장되 었다. UI는 사용자의 만족도에 직접적인 영향을 주는 요소로, 소프트웨어 영역 중 변경이 가장 많이 발생하는 부분이다. 적절한 UI 구성으로 사용자의 편리성과 가독성을 높이고, 동선을 축약하여 작업 시간을 줄이며 업무에 대한 이해도를 높여줄 수 있다. UI는 사용자 중심으로 설계되어야 하며, 정보를 제공하는 사람과 공급받는 사람 간의 매개 역할을 수행하고, 사용자가 수행해야 할 기능을 구체적으로 제시해야 한다."]]},{"t":"② UI 분야: 정보 전달·콘텐츠 표현","n":[["설명","정보 제공·전달과 표현 UI는 물리적 제어를 통한 정보 제공과 전달을 위한 분야, 콘텐츠의 상세한 표현과 전체적인 구성에 대한 분야로 나눌 수 있다."],["쉬운 예","모든 사용자가 편리하고 쉽게 사용할 수 있도록 하는 기능에 대한 분야가 있다. 예를 들어 키오스크는 도입 초기에는 사용법이 낯설어 어려워하는 사용자가 많았으나, 지속적인 개선을 통해 점차 누구나 쉽게 사용할수 있는 방향으로 발전해 왔다."]]}]},{"t":"(2) GUI, CLI, NUI","c":[{"t":"① GUI 그래픽·CLI 텍스트 명령","n":[["설명","GUI(Graphical User Interface) GUI는 그래픽을 이용하여 아이콘, 버튼, 문자 등을 마우스로 선택해 작업을 수행하는 그래픽 사용자 환경을 말한다. CLI(Command Line Interface)는 명령과 출력이 텍스트 형태로 이루어지는 인터페이스로, 키보드를 통해 명령어를 입력하여 작업하는 환경이다. 과거에는 CLI 대신 CUI(Character User Interface)라는 용어가 사용되기도 하였다. NUI(Natural User Interface)는 멀티터치나 동작 인식 등 사용자의 말이나 자연스러운 행동을 인식하여 기기를 조작하는 인터페이스이다. MUI(Menu-based User Interface)는 메뉴를 기반으로 작업할 수 있는 환경을 말하며, VUI(Voice User Interface)는 사람의 음성으로 기계를 조작하는 인터페이스로, 최근 인공지능 스피커 등에서 널리 활용되고 있다."]]},{"t":"② OUI 사물-사용자 상호작용(IoT)","n":[["설명","OUI(Organic User Interface) OUI는 모든 사물과 사용자 간의 상호작용을 위한 인터페이스로, 사물인터넷(IoT, Internet of Things)과 같이 소프트웨어가 아닌 하드웨어 분야에서 네트워크에 연결된 가전제품 등을 조작하고 상태를 확인할 수 있도록 하는 인터페이스이다."],["쉬운 예","가상현실(VR, Virtual Reality)은 별도의 기기를 착용하여 가상의 환경을 체험하는 방식이며, 증강현실(AR, Augmented Reality)은 실제 화면과 그래픽 화면이 결합되어 나타나는 방식이다. 혼합현실(MR, Mixed Reality)은 가상과 실제가 공존하는 형태로, 예를 들어 실제 공간에 가상의 가구를 배치해 인테리어를 미리 확인해 보는 것과 같은 활용이 가능하다. 시험에서는 GUI와 CLI, IoT, 증강현실이 특히 자주 출제되는 경향이 있다."]]}]}]}]},{"t":"Ⅱ UI의 설계 원칙과 지침","c":[{"t":"1. UI의 기본 원칙","c":[{"t":"(1) 직관성과 유효성","c":[{"t":"① 직관성·유효성 원칙","n":[["설명","직관성 직관성은 누구나 쉽게 이해하고 사용할 수 있어야 한다는 원칙이다. 별도의 설명 없이도 사용자가 화면 구성만 보고 어떻게 조작해야 할지 짐작할 수 있도록 설계해야 한다. 유효성은 사용자의 목적을 정확하고 완벽하게 달성할 수 있도록 해야 한다는 원칙으로, 사용자가 의도한 동작이 정확하게 수행되어야 함을 의미한다."]]},{"t":"② 학습성·유연성 원칙","n":[["설명","학습성 학습성은 누구나 쉽게 배우고 익힐 수 있어야 한다는 원칙이다. 사용 방법이 지나치게 복잡하거나 어려우면 사용자의 만족도가 떨어질 수밖에 없다. 유연성은 사용자의 다양한 요구사항을 최대한 수용하고 실수를 최소화할 수 있도록 설계해야 한다는 원칙이다. 직관성, 유효성, 학습성, 유연성의 네 가지 기본 원칙을 정확히 구분하여 기억해 두어야 한다."]]}]},{"t":"(2) 사용자 중심과 일관성","c":[{"t":"① 사용자 중심·사용성","n":[["설명","사용자 중심 UI를 설계할 때는 개발자의 편의가 아니라 사용자가 쉽게 이해하고 편리하게 사용할 수 있는 환경을 제공하는 것을 최우선으로 해야 한다. 사용성이란 사용자가 얼마나 빠르고 쉽게 이해할 수 있는지, 얼마나 편리하고 효율적으로 사용할 수 있는지를 의미한다."],["쉬운 예","버튼이나 조작 방법 등을 일관성 있게 제공하여 사용자가 쉽게 기억하고 습득할 수 있도록 해야 한다. 예를 들어 소프트웨어가 업데이트될 때마다 조작 방법이 크게 달라진다면 사용자는 매번 새롭게 학습해야 하는 불편을 겪게 된다."]]},{"t":"② 단순성·결과 예측성·가시성","n":[["설명","단순성과 결과 예측성 단순성은 조작 방법을 단순화하여 사용자의 부담을 줄여야 한다는 지침이며, 결과 예측성은 작동시킬 기능만 보고도 그 결과를 미리 예측할 수 있도록 설계해야 한다는 지침이다. 가시성은 메인 화면에 주요 기능을 노출시켜 최대한 조작이 쉽도록 하는 것을 말하며, 표준화는 기능 구조와 디자인을 표준화하여 한 번 학습한 이후에는 쉽게 사용할 수 있도록 하는 것을 말한다. 접근성은 사용자의 연령, 성별, 인종 등 다양한 계층이 사용할 수 있도록 설계해야 한다는 지침이며, 이 밖에도 명확성과 오류 발생 해결(오류 발생을 사용자가 쉽게 인지할 수 있도록 하는 것) 등이 UI 설계 지침에 포함된다."]]}]}]}]},{"t":"Ⅲ UI 설계 도구와 UX","c":[{"t":"1. UI 설계 도구","c":[{"t":"(1) 와이어프레임과 목업","c":[{"t":"① 와이어프레임: 초기 개략 레이아웃","n":[["설명","와이어프레임(Wireframe) 와이어프레임은 기획 단계 초기에 제작하는 개략적인 레이아웃으로, 손으로 그린 그림도 해당될 수 있으며 UI 요소 등에 대한 뼈대를 설계하기 위한 도구이다. 개발자와 디자이너가 레이아웃을 협의하거나 진행 상태를 공유하기 위해 사용되며, 파워포인트, 키노트, 스케치, 일러스트, 포토샵 등의 도구로 제작할 수 있다."],["실제 사례","목업은 와이어프레임의 뼈대에 디자인 요소를 채워 넣어, 디자인이나 사용 방법, 설명, 평가 등을 위해 실제 화면과 좀 더 유사하게 만든 정적인 형태의 모형이다. 실제로 동작하지는 않으며 화면의 겉모습만을 보여주는 정적인 특징을 가지며, 파워목업, 발사믹목업과 같은 도구가 사용된다."]]},{"t":"② 스토리보드: 최종 작업 지침서","n":[["설명","스토리보드(Storyboard) 스토리보드는 와이어프레임의 콘텐츠에 대한 설명, 페이지 간 이동 흐름 등을 추가한 문서로, 디자이너와 개발자가 최종적으로 참고하는 작업 지침서 역할을 한다. 정책이나 프로세스, 콘텐츠 구성, 와이어프레임, 기능 정의 등 서비스 구축을 위한 모든 정보가 포함되며, 화면의 좌측에는 UI 화면을, 우측에는 설명(디스크립션)을 기입하는 형태로 작성한다."],["실제 사례","프로토타입은 와이어프레임이나 스토리보드에 실제 동작(인터랙션)을 적용하여, 실제 구현된 것처럼 테스트가 가능한 동적인 형태의 모형이다. 샘플 작성 방법에 따라 페이퍼 프로토타입과 디지털 프로토타입으로 나뉜다. 유스케이스는 사용자 측면의 요구사항으로, 사용자가 원하는 목표를 달성하기 위해 수행할 내용을 자연어로 기술하고 이를 구조적인 다이어그램으로 표현한 것이다. 설계 도구는 일반적으로 와이어프레임 → 목업 → 스토리보드 → 프로토타입의 순서로 점차 구체화된다."]]}]},{"t":"(2) UX의 개념","c":[{"t":"① UX 사용자 총체적 경험","n":[["설명","UX란 UX는 사용자 경험을 의미하며, 사용자가 시스템이나 서비스를 이용하면서 느끼고 생각하게 되는 총체적인 경험을 말한다. UI가 사용자와 시스템을 중계하는 인터페이스 자체를 가리킨다면, UX는 그 인터페이스를 통해 사용자가 느끼는 만족이나 감정을 가리킨다는 점에서 구분된다. UX는 단순히 기능이나 절차상의 만족뿐만 아니라, 사용자가 참여, 사용, 관찰하고 상호 교감하면서 얻게 되는 가치 있는 경험을 의미한다. 기술을 효용성 측면에서만 보는 것이 아니라 사용자 삶의 질을 향상시키는 방향으로 바라보는 개념이다."]]},{"t":"② UX 특성: 주관성·정황성·총체성","n":[["설명","주관성과 정황성 주관성은 사람마다 개인적, 신체적, 인지적 특성이 다르기 때문에 UX는 주관적일 수밖에 없다는 특성이다. 정황성은 경험이 일어나는 상황이나 주변 환경에 영향을 받는다는 특성이다. 총체성은 개인이 느끼는 총체적인 심리적, 감정적 결과를 말한다. UX의 세 가지 특성인 주관성, 정황성, 총체 성을 함께 기억해 두면 관련 문제에 효과적으로 대응할 수 있다."]]}]}]}]},{"t":"Ⅳ HTML의 기초","c":[{"t":"1. HTML의 개념과 구조","c":[{"t":"(1) HTML(HyperText Markup Language)이란","c":[{"t":"① HTML 하이퍼텍스트 마크업 언어","n":[["설명","HTML의 정의 HTML은 하이퍼텍스트 마크업 언어로, 인터넷 표준 문서인 하이퍼텍스트 문서를 만들 때 사용하는 언어이다. 하이퍼텍스트란 문서와 문서가 서로 연결되어 있는 형태를 의미하며, 마크업 언어는 문서의 구조를 표시(마 크)한다는 뜻을 담고 있다. 웹 브라우저에 표시되는 화면은 바로 HTML로 작성된 문서를 브라우저가 해석하여 보여주는 것이다. HTML은 태그(Tag)로 구성되며, 상위 태그 아래에 여러 개의 하위 태그가 존재하는 트리 구조 방식으로 이루어져 있다. 태그는 속성(Attribute)을 사용하여 기능을 구체화할 수 있으며, 대소문자를 구별하지 않는다. 속성의 값을 지정할 때는 일반적으로 큰따옴표로 감싸는 것이 관례이다."]]},{"t":"② HTML 기본 구조 head·body","n":[["설명","head와 body <!DOCTYPE html> <html> <head> <meta charset=\"UTF-8\"> <title>영진출판사</title> </head> <body> 안녕하세요<br> HTML을 연습하고 있습니다. </body> </html>"],["실제 사례","HTML 문서는 크게 머리글(head)과 본체(body)로 구성된다. head 영역에는 문서의 제목(title)이나 문자 인코딩 방식(meta charset)과 같이 화면에 직접 표시되지는 않지만 문서를 설명하는 정보가 담기며, title 태그의 내용은 웹 브라우저 상단의 탭 제목으로 표시된다. body 영역에는 실제로 화면에 표시되는 문서의 내용이 담긴다."]]}]},{"t":"(2) 구조 관련 태그","c":[{"t":"① h1~h6 제목·p 문단·div 구역","n":[["설명","제목과 문단 태그 h1부터 h6까지의 태그는 제목을 표시하는 태그로, 숫자가 작을수록 더 큰 제목을 의미한다. p 태그는 하나의 문단을 표시할 때 사용하며, div 태그는 화면을 구역별로 나누어 레이아웃을 구성할 때 널리 사용되는 대표적인 블록 요소이다. ul과 ol 태그는 각각 순서 없는 목록과 순서 있는 목록을 만들 때 사용하며, 그 안에 li 태그로 각 목록 항목을 표시한다. table 태그는 표를 만들 때 사용하며, tr(행), td(데이터 셀), th(제목 셀) 태그와 함께 사용된다."]]},{"t":"② a(href)·img(src)·f orm 태그","n":[["설명","a 태그와 img 태그 a 태그는 다른 문서나 페이지로 이동할 수 있는 하이퍼링크를 만들 때 사용하며, href 속성에 이동할 주소를 지정한다. img 태그는 이미지를 화면에 표시할 때 사용하며, src 속성에 이미지 파일의 경로를 지정한다. form 태그는 사용자로부터 데이터를 입력받아 서버로 전송하기 위한 영역을 정의하며, 그 안에 input 태그를 사용하여 텍스트 입력란, 버튼, 체크박스 등 다양한 입력 요소를 만들 수 있다. 이러한 입력 요소들은 회원가 입이나 로그인과 같은 화면을 구현하는 데 핵심적으로 사용된다."]]}]}]}]},{"t":"Ⅴ CSS와 JavaScript 기초","c":[{"t":"1. CSS(Cascading Style Sheets)","c":[{"t":"(1) CSS의 개념","c":[{"t":"① CSS 시각 스타일 지정 언어","n":[["설명","CSS란 CSS는 HTML로 작성된 문서의 색상, 글꼴, 배치, 크기와 같은 시각적인 스타일을 지정하는 언어이다. HTML이 문서의 구조와 내용을 담당한다면, CSS는 그 문서가 화면에 어떻게 보일지를 담당한다고 이해할수 있다."],["실제 사례","CSS는 HTML 태그의 style 속성에 직접 작성하는 인라인 방식, head 영역의 style 태그 안에 작성하는 내부 스타일시트 방식, 별도의 .css 파일로 작성하여 link 태그로 연결하는 외부 스타일시트 방식의 세가지 방법으로 적용할 수 있다. 실무에서는 유지보수가 용이한 외부 스타일시트 방식이 널리 사용된다."]]},{"t":"② CSS 선택자 태그·.class· #id","n":[["설명","선택자(Selector)\nh1 { color: blue; font-size: 24px; }\n.title { text-align: center; }\n#main { background-color: #f0f0f0; }\nCSS 선택자는 스타일을 적용할 HTML 요소를 지정하는 방법으로, 태그 이름을 그대로 사용하는 태그 선택자, 마침표(.)를 붙여 사용하는 클래스 선택자, 샵(#)을 붙여 사용하는 아이디 선택자 등이 있다. 클래스 선택자는 여러 요소에 중복하여 적용할 수 있는 반면, 아이디 선택자는 문서 내에서 유일하게 하나의 요소에만 적용하는 것이 원칙이다. color는 글자 색상을, background-color는 배경 색상을 지정하며, font-size는 글자 크기, text-align은 텍스트의 정렬 방식을 지정한다. width와 height는 요소의 너비와 높이를, margin과 padding은 각각 요소 바깥쪽과 안쪽의 여백을 지정하는 데 사용된다."]]}]},{"t":"(2) JavaScript의 개념","c":[{"t":"① JavaScript 웹 동적 기능","n":[["설명","JavaScript란 JavaScript는 웹 페이지에 동적인 기능을 부여하기 위해 사용되는 프로그래밍 언어이다. HTML이 문서의 뼈대, CSS가 문서의 외형을 담당한다면, JavaScript는 사용자의 클릭이나 입력에 반응하여 문서의 내용을 실시간으로 변경하는 등의 동작을 담당한다. JavaScript 코드는 HTML 문서 안에 script 태그를 사용하여 삽입하거나, 별도의 .js 파일로 작성하여 불러올 수 있다. 웹 브라우저는 이 코드를 해석하여 실행하며, 개발자 도구(F12)를 통해 콘솔에 출력된 결과나 오류 메시지를 직접 확인할 수 있다."]]},{"t":"② slice 추출·splice 원본 변경","n":[["설명","배열 요소의 추출과 변환 slice 메소드는 배열의 초기 위치부터 최종 위치 바로 앞까지의 요소를 추출하여 새로운 배열로 반환하며, 원본 배열은 변경하지 않는다. splice 메소드는 배열의 특정 위치에서 지정한 개수만큼 요소를 삭제하거나 다른 값으로 교체하며, 원본 배열 자체를 직접 변경한다는 점에서 slice와 근본적인 차이가 있다."],["쉬운 예","join 메소드는 배열의 각 요소를 지정한 구분자를 이용하여 하나의 문자열로 합칠 때 사용한다. 예를 들어 [\"가\", \"나\", \"다\"].join(\"-\")과 같이 작성하면 \"가-나-다\"라는 하나의 문자열이 만들어진다. slice(추출), splice(교체 및 삭제), join(문자열 변환)의 세 메소드는 기능이 서로 혼동되기 쉬우므로 명확히 구분하여 기억해 두어야 한다."]]}]}]}]},{"t":"Ⅵ UI 테스트 기법","c":[{"t":"1. UI 테스트의 개념과 종류","c":[{"t":"(1) UI 테스트란","c":[{"t":"① UI 테스트: 시나리오 기반 사용성 검증","n":[["설명","UI 테스트의 정의 UI 테스트는 구현된 UI의 사용성을 검증하기 위해 수행하는 테스트로, 사용자가 미리 작성된 시나리오에 따라 직접 제품을 사용하면서 진행하는 사용자 중심의 테스트이다. 현재 제품에 대한 사용자의 요구사항과 행동을 관찰할 수 있는 유용한 진단 방법이 되며, 테스트 결과물은 사용자 매뉴얼 작성 시 중요한 참고 자료로 활용된다."],["실제 사례","UI 테스트는 크게 소프트웨어 테스트와 사용성 테스트로 나눌 수 있다. 소프트웨어 테스트는 요구사항을 검증하고 확인하는 절차가 필요하며 결함을 발견하거나 품질 위험을 감소시키는 것이 목적으로, 대표적인 산출물은 테스트 케이스와 결과, 결함 리포트, 커버리지, 성능 지표 등이다. 사용성 테스트는 실제 사용자가 작업을 수행할 때 효과적이고 효율적이며 만족스러운지를 평가하는 테스트로, 대표적인 산출물은 이슈 목록, 심각도, 개선 정량 지표(SUS 등), 정성적 인사이트 등이다."]]},{"t":"② 휴리스틱 평가","n":[["설명","휴리스틱(Heuristic) 평가"],["실제 사례","휴리스틱 평가는 최소 세 명 이상의 디자인 전문가가 사전에 작성한 원칙에 따라 제품을 평가하는 기법으로, 사용성에 대한 문제를 찾아내기 위한 사용성 공학 방법이다. 전문가의 이론과 경험을 근거로 규칙들을 만들어 놓고, 평가 대상이 그 규칙을 얼마나 잘 지키는지 확인하는 방식이다. UI의 개발 정도와 관계없이 평가가 가능하고 적은 비용으로 짧은 시간 내에 중요한 문제점을 발견할 수 있다는 장점이 있지만, 구체적이고 계량적인 평가 자료를 만들기 어렵고 전문가와 실제 사용자의 시각 차이가 발생할 수 있다는 단점이 있다."],["실제 사례","페이퍼 프로토타입 테스트는 종이로 해당 서비스를 간단하게 만들어 실제 구현되는 것처럼 표현하고, 이를 이용해 테스트하는 평가 방법이다. 테스트 기법 중 가장 빠른 방법으로, 제품의 전반적인 콘셉트와 흐름을 보여줄 수 있으며, 테스트 참가자들이 최종 제품에 대한 기대를 갖지 않고 더 자유롭게 의견을 내는 경향이 있다."]]}]},{"t":"(2) 선호도 평가(Preferenc e Test)","c":[{"t":"① 선호도 평가: 2개 이상 UI 비교","n":[["설명","선호도 평가의 개념 선호도 평가는 두 개 이상의 UI를 두고 사용자가 어느 쪽을 더 선호하는지를 평가하는 기법으로, 선호도에 영향을 주는 속성들을 파악하고 예측하기 위해 사용된다. 사용자의 감성을 과학적이고 객관적인 시점에서 분석 해야 한다. 자료의 특성에 따라 점수, 순위, 태도 기반 선호도, 속성 기반 선호도 등 알맞은 추정법을 적용하여 분석하며, 이러한 결과를 바탕으로 서로 다른 안의 장점을 혼합하여 개선된 안을 도출할 수도 있다."]]},{"t":"② 성능 평가: 학습성·효율성·기억 용이성","n":[["설명","성능 평가의 개념 성능 평가는 개발의 마지막 단계에서 제품의 학습성(얼마나 쉽게 배울 수 있는지), 효율성(불필요한 노력이 필요하지 않은지), 기억 용이성(한번 익힌 방법을 다시 쉽게 기억할 수 있는지), 오류로부터의 회복(오류 발생시 빠르게 정상 상태로 전환될 수 있는지), 만족도 등을 종합적으로 평가하는 기법이다. 성능 평가는 제품이나 서비스의 개발 단계에 맞추어 진행되며, 각 태스크가 지닌 장단점을 파악하여 이후의 성능 개선 방향을 도출하는 데 활용된다. 휴리스틱 평가, 페이퍼 프로토타입, 선호도 평가, 성능 평가는 UI 테스트를 구성하는 대표적인 네 가지 기법으로 함께 기억해 두어야 한다."]]}]}]}]},{"t":"Ⅶ 웹 표준과 웹 접근성","c":[{"t":"1. 웹 표준(Web Standard)","c":[{"t":"(1) 웹 표준의 개념","c":[{"t":"① 웹 표준 W3C 규격","n":[["설명","웹 표준이란웹 표준은 W3C(World Wide Web Consortium)와 같은 국제 표준화 기구가 정한 규격으로, 어떤 브라우 저나 기기에서도 웹 페이지가 동일하게 표시되고 동작하도록 정의한 지침이다. HTML, CSS, JavaScript의 문법과 사용 방식을 규격화하여 웹 콘텐츠의 호환성을 보장하는 것이 목적이다. 웹 표준을 준수하지 않으면 특정 브라우저에서는 정상적으로 보이던 화면이 다른 브라우저에서는 깨지거나 동작하지 않는 문제가 발생할 수 있다. 이러한 크로스 브라우징 이슈를 방지하고, 유지보수 비용을 낮추기 위해 웹 표준 준수는 필수적이다."]]},{"t":"② 크로스 브라우징","n":[["설명","크로스 브라우징의 개념 크로스 브라우징은 웹 페이지가 다양한 브라우저(크롬, 파이어폭스, 사파리, 엣지 등)와 다양한 버전에서 동일한 방식으로 보이고 동작하도록 제작하는 기법이나 접근 방식을 의미한다."],["실제 사례","크로스 브라우징을 검증하기 위해서는 여러 브라우저에서 실제로 웹 페이지를 렌더링해 보며 레이아웃 붕괴, 스타일 불일치, 기능 오작동 여부를 하나씩 점검해야 한다. 최근에는 여러 브라우저 환경을 자동으로 캡처하여 비교해 주는 자동화 도구도 널리 활용된다."]]}]},{"t":"(2) 웹 접근성의 개념","c":[{"t":"① 웹 접근성: 모든 사용자 동등 접근","n":[["설명","웹 접근성이란웹 접근성은 신체적 장애나 나이, 환경 등에 관계없이 모든 사용자가 웹에서 제공하는 정보에 동등하게 접근하고 이용할 수 있도록 보장하는 것을 의미한다. 시각 장애인을 위한 스크린 리더 지원, 색약자를 위한 색상 대비 등이 대표적인 고려사항이다. 웹 접근성 지침(Web Content Accessibility Guidelines, WCAG)은 인식의 용이성, 운용의 용이성, 이해의 용이성, 견고성이라는 네 가지 원칙을 기반으로, 대체 텍스트 제공, 키보드만으로도 모든 기능 조작 가능, 명확한 오류 안내 등 구체적인 준수 기준을 제시한다."]]},{"t":"② alt 대체 텍스트·시맨틱 태그","n":[["설명","대체 텍스트와 시맨틱 마크업 이미지에는 대체 텍스트(alt 속성)를 반드시 제공하여 스크린 리더 사용자가 이미지의 내용을 이해할 수 있게 해야 한다. 또한 div 태그 대신 header, nav, main, article과 같은 시맨틱(semantic) 태그를 사용하면 문서의 구조를 명확히 전달할 수 있다. 마우스를 사용할 수 없는 사용자를 위해 Tab 키만으로 모든 인터랙티브 요소에 접근하고 조작할 수 있도록 설계해야 하며, 텍스트와 배경 사이의 색상 대비를 충분히 확보하여 저시력자도 내용을 쉽게 인식할 수 있도록 해야 한다."]]}]}]}]},{"t":"Ⅷ 반응형 웹과 모바일 UI","c":[{"t":"1. 반응형 웹 디자인(Respons ive Web Design)","c":[{"t":"(1) 반응형 웹의 개념","c":[{"t":"① 반응형 웹: 하나의 소스로 모든 기기","n":[["설명","반응형 웹 디자인이란 반응형 웹 디자인은 하나의 웹 페이지가 데스크탑, 태블릿, 스마트폰 등 다양한 화면 크기와 해상도에 자동으로 최적화되어 표시되도록 설계하는 기법이다. 별도의 모바일 전용 페이지를 만들지 않고도 하나의 소스로 모든 기기에 대응할 수 있다는 장점이 있다."],["쉬운 예","미디어 쿼리는 CSS에서 화면의 너비, 높이, 방향 등의 조건에 따라 다른 스타일을 적용할 수 있게 해주는 기능이다. 예를 들어 화면 너비가 768픽셀 이하인 경우에는 메뉴를 세로로 배치하고, 그 이상인 경우에는 가로로 배치하는 방식으로 활용된다."]]},{"t":"② 그리드 시스템 부트스트랩 12열","n":[["설명","그리드 시스템(Grid System) 그리드 시스템은 화면을 일정한 개수의 열(Column)로 나누고, 각 요소를 그 열에 맞추어 배치하는 레이아웃 방식이다. 부트스트랩(Bootstrap)과 같은 프레임워크는 12개의 열로 구성된 그리드 시스템을 기본으로 제공하여 반응형 레이아웃 구현을 용이하게 해준다. 유동형 레이아웃은 요소의 크기를 픽셀과 같은 고정 단위 대신 퍼센트(%)나 뷰포트 단위(vw, vh)와 같은 상대적인 단위로 지정하여, 화면 크기가 변하더라도 비율을 유지하며 자연스럽게 늘어나거나 줄어들도록 하는 기법이다."]]}]},{"t":"(2) 모바일 환경의 특성","c":[{"t":"① 터치 영역 최소 44x44픽셀","n":[["설명","터치 인터페이스 고려 모바일 기기는 마우스가 아닌 손가락 터치로 조작하므로, 버튼이나 링크와 같은 터치 대상의 크기를 충분히 크게 설계하여 오터치를 방지해야 한다. 일반적으로 최소 44x44픽셀 이상의 터치 영역을 권장한다. 모바일 기기는 데스크탑에 비해 화면이 작고, 네트워크 환경이 불안정할 수 있으므로 핵심 정보를 우선적으로 배치하고, 이미지 용량을 최적화하여 로딩 속도를 개선하는 것이 중요하다."]]},{"t":"② 햄버거 메뉴·하단 내비게이션","n":[["설명","햄버거 메뉴와 하단 내비게이션 햄버거 메뉴(3개의 가로줄 아이콘)는 좁은 화면에서 여러 메뉴 항목을 숨겨두었다가 탭하면 펼쳐지도록 하는 대표적인 모바일 UI 패턴이다. 하단 내비게이션 바는 자주 사용하는 핵심 메뉴를 화면 하단에 고정하여 엄지 손가락으로 쉽게 접근할 수 있도록 하는 패턴이다. 풀 투 리프레시(Pull to Refresh)는 화면을 아래로 당겨 콘텐츠를 최신 상태로 갱신하는 제스처 패턴이며, 무한 스크롤(Infinite Scroll)은 사용자가 화면 하단에 도달하면 다음 콘텐츠를 자동으로 이어서 불러오는 패턴으로, 모바일 애플리케이션에서 널리 사용된다."]]}]}]}]},{"t":"Ⅸ UI 화면 설계 표준화와 명세","c":[{"t":"1. UI 화면 설계서","c":[{"t":"(1) 화면 설계서의 개념","c":[{"t":"① 화면 설계서: 레이아웃·구성·이벤 트","n":[["설명","화면 설계서란 화면 설계서는 개발할 애플리케이션의 각 화면에 대한 레이아웃, 구성 요소, 이벤트 흐름 등을 상세하게 기술한 문서이다. 개발자와 디자이너, 기획자가 동일한 화면 구조를 이해할 수 있도록 하는 공통의 기준점 역할을한다. 화면 설계서에는 일반적으로 화면 번호, 화면명, 화면 설명, 관련 메뉴 경로, 입력 항목과 출력 항목, 버튼과 이벤트에 대한 처리 로직 등이 포함된다."]]},{"t":"② 네비게이션: 화면 간 이동 경로","n":[["설명","네비게이션(Navigation)의 개념 네비게이션은 사용자가 화면 간을 이동하는 경로와 그 구조를 의미한다. 사용자가 현재 어느 화면에 있는지, 어떻게 이전 화면으로 돌아갈 수 있는지를 명확히 인지할 수 있도록 설계하는 것이 중요하다. 네비게이션은 화면 간의 흐름을 트리 구조, 순차 구조, 허브 앤 스포크(Hub and Spoke) 구조 등으로 표현할수 있으며, 사이트맵이나 화면 정의서를 통해 전체 네비게이션 구조를 시각화하여 관리한다."]]}]},{"t":"(2) UI 컴포넌트(Componen t)","c":[{"t":"① UI 컴포넌트: 재사용 최소 단위","n":[["설명","UI 컴포넌트의 개념 UI 컴포넌트는 버튼, 입력 필드, 체크박스, 드롭다운 메뉴와 같이 화면을 구성하는 재사용 가능한 최소 단위 요소를 의미한다. 컴포넌트 단위로 설계하면 여러 화면에서 일관된 디자인을 유지하고 개발 생산성을 높일 수있다. 동일한 컴포넌트를 여러 화면에서 재사용하면 디자인 일관성을 유지할 수 있을 뿐만 아니라, 컴포넌트에 결함이 발견되었을 때 한 곳만 수정하면 이를 사용하는 모든 화면에 자동으로 반영되므로 유지보수성이 크게 향상된다."]]},{"t":"② 디자인 시스템: 디자인 규칙·가이드","n":[["설명","디자인 시스템의 개념 디자인 시스템은 색상, 타이포그래피, 아이콘, 컴포넌트 등 디자인 요소에 대한 규칙과 가이드를 체계적으로 정리한 것을 의미한다. 여러 명의 디자이너와 개발자가 협업하는 대규모 프로젝트에서 일관된 사용자 경험을 제공하기 위해 필수적으로 활용된다."],["실제 사례","디자인 시스템은 색상 팔레트, 그리드 시스템, 타이포그래피 규칙과 같은 기초 스타일 가이드와, 버튼이나 카드처럼 실제로 재사용되는 컴포넌트 라이브러리로 구성된다."]]}]}]}]},{"t":"Ⅹ 전통적 UI와 증강현실 인터페이스","c":[{"t":"1. 전통적 UI 환경의 발전 과정","c":[{"t":"(1) CLI에서 GUI로의 발전","c":[{"t":"① 초기 CLI 명령어 입력 방식","n":[["설명","초기 CLI 환경 초창기 컴퓨터 환경에서는 사용자가 명령어를 직접 입력하는 CLI(Command Line Interface) 방식이 주로 사용되었다. 이는 학습에 시간이 걸리지만, 숙련된 사용자에게는 빠르고 정확한 조작이 가능하다는 장점이 있었다. GUI(Graphical User Interface)의 등장으로 마우스를 이용한 아이콘 클릭과 창(Window) 조작이 가능해 지면서, 컴퓨터를 처음 접하는 사용자도 직관적으로 시스템을 사용할 수 있게 되었다. 이는 컴퓨터의 대중화에 크게 기여한 전환점이었다."]]},{"t":"② NUI 터치·VUI 음성 확산","n":[["설명","NUI와 음성 인터페이스의 확산 스마트폰과 태블릿의 보급으로 터치를 활용한 NUI(자연 사용자 인터페이스)가 주류로 자리잡았으며, 최근에는 인공지능 스피커와 같이 음성으로 명령을 내리는 VUI(음성 사용자 인터페이스)의 활용도 급속히 확산되고 있다. 제스처 인터페이스는 신체의 움직임(손짓, 몸짓)을 카메라나 센서로 인식하여 명령을 전달하는 방식으로, 게임 콘솔이나 스마트 TV 등에서 활용되며 물리적 접촉 없이도 기기를 조작할 수 있게 해준다."]]}]},{"t":"(2) VR과 AR의 활용 분야","c":[{"t":"① VR 가상환경 몰입·시뮬레이션","n":[["설명","VR(가상현실)의 활용 VR은 완전히 가상으로 구성된 환경에 사용자를 몰입시키는 기술로, 게임, 교육 시뮬레이션, 가상 훈련 등의 분야에서 실제와 유사한 체험을 제공하는 데 활용된다."],["실제 사례","AR은 실제 환경 위에 가상의 정보를 겹쳐서 보여주는 기술로, 스마트폰 카메라를 통해 실제 거리 위에 상점 정보를 표시하거나, 가구를 실제 공간에 미리 배치해 보는 서비스 등에 활용된다."]]},{"t":"② MR(혼합현실) 특징","n":[["설명","MR(혼합현실)의 특징"],["실제 사례","MR은 VR과 AR의 장점을 결합하여, 현실 공간을 인식한 가상의 객체가 실제 사물과 상호작용할 수있도록 하는 기술이다. 가상의 물체를 실제 책상 위에 놓인 것처럼 자연스럽게 조작할 수 있다는 점이 특징이다."],["실제 사례","UI 요구사항을 수집하기 위해서는 실제 사용자를 대상으로 한 인터뷰와 설문조사를 통해 사용자가 필요로 하는 기능과 불편함을 느끼는 지점을 구체적으로 파악해야 한다."],["실제 사례","사용자가 실제 업무 환경에서 어떻게 시스템을 사용하는지를 직접 관찰하는 현장 조사 (Contextual Inquiry)를 통해, 설문이나 인터뷰만으로는 파악하기 어려운 암묵적인 요구사항을 발견할 수 있다."],["실제 사례","페르소나는 실제 사용자 조사 데이터를 바탕으로 만든 가상의 대표 사용자 캐릭터이다. 나이, 직업, 목표, 불편함 등을 구체적으로 설정하여, 개발팀이 특정 사용자를 염두에 두고 UI를 설계할 수 있도록 돕는다."],["실제 사례","검토를 마친 UI 설계는 프로젝트 발주자나 주요 이해관계자의 최종 승인을 거친 후에야 실제 개발 단계로 넘어가며, 승인되지 않은 설계 변경은 별도의 변경 관리 절차를 따라야 한다."],["실제 사례","화면 개발이 완료되면 UI 표준 가이드를 기준으로 실제 구현된 화면이 이를 준수하고 있는지 점검하는 과정을 거쳐야 일관된 품질의 사용자 경험을 제공할 수 있다."],["실제 사례","화면에 사용되는 이미지의 용량을 최적화하고, 사용자가 실제로 스크롤하여 보게 되는 시점에 이미지를 불러오는 지연 로딩(Lazy Loading) 기법을 적용하면 초기 화면 로딩 속도를 크게 개선할 수 있다. 특히 모바일 환경에서는 데이터 사용량과 배터리 소모에도 직접적인 영향을 미치므로 더욱 중요하게 고려해야 한다."],["실제 사례","수천 건의 목록 데이터를 한 번에 화면에 모두 그리는 대신, 실제로 화면에 보이는 부분만 렌더링하고 스크롤에 따라 동적으로 요소를 교체하는 가상 스크롤 기법을 적용하면 대량의 데이터도 부드럽게 표시할 수있다."],["시험 포인트","마이크로 인터랙션은 사용자의 주의를 분산시키지 않을 정도로 절제되어야 하며, 지나치게 화려 하거나 긴 애니메이션은 오히려 사용성을 저해할 수 있으므로 적절한 균형을 유지하여 설계해야 한다."]]}]}]}]}]},{"t":"제2절 애플리케이션 테스트 기초와 테스트 기법","c":[{"t":"Ⅰ 테스트의 개념과 7가지 원칙","c":[{"t":"1. 테스트의 개념","c":[{"t":"(1) 테스트란","c":[{"t":"① 테스트: 요구 충족 확인·결함 발견","n":[["설명","테스트의 정의 테스트는 개발된 응용 애플리케이션이나 시스템이 사용자가 요구하는 기능과 성능, 사용성, 안전성 등을 충족하는지 확인하고, 노출되지 않은 결함을 찾아내는 활동을 말한다. 테스트 과정에는 소프트웨어 아키텍트와 테스트 매니저의 역할이 필요하며, 이 두 역할은 소프트웨어 생명주기(Life Cycle)의 V 모델에서 각각 좌측(개 발)과 우측(테스트)의 핵심 역할을 담당하면서 서로 보완하는 관계에 있다. 소프트웨어 생명주기는 요구사항 → 분석 → 디자인 → 구현(개발) 순으로 진행되며, 프로젝트의 특성과 방법론에 따라 반복적으로 수행되기도 한다. 이러한 개발 단계에 대응하여, 테스트는 단위 테스트, 통합 테스트, 시스템 테스트, 인수 테스트 순으로 진행된다."]]},{"t":"② 검증·확인(Verification ·Validation)","n":[["설명","검증(Verification)과 확인(Validation)"],["실제 사례","검증(Verification)은 소프트웨어가 개발 각 단계에서 명세된 요구사항을 올바르게 충족하는지를 확인하는 활동이며, 확인(Validation)은 사용자의 요구사항을 실제로 충족하는지를 사용자 입장에서 확인하는 활동이다. 이 둘을 합쳐 V&V라고 부르기도 한다."]]}]},{"t":"(2) 테스트 계획과 결함 발견","c":[{"t":"① 테스트는 계획 단계부터","n":[["설명","테스트는 계획 단계부터 한다 테스트 활동은 소프트웨어 개발 주기에서 가능한 초기부터 시작해야 한다. 요구사항이 정의되는 시점부터 테스트를 염두에 두고 계획을 수립해야, 개발이 진행된 이후에 발견되는 결함의 수정 비용을 줄일 수 있다. 테스트의 목적은 결함의 제거가 아니라 결함의 발견이다. 테스트는 결함이 있다는 것을 보여줄 수는 있지만, 결함이 없다는 것을 증명할 수는 없다는 점을 명확히 이해해야 한다."]]},{"t":"② 완전한 테스트 불가능","n":[["설명","완전한 테스트는 불가능하다 모든 것(입력값, 경로, 타이밍)에 대한 테스트는 자원의 한계로 인해 사실상 불가능하다. 가능한 입력의 수와 출력의 수가 지나치게 많고, 소프트웨어 명세서와 결함에 대한 판단 또한 주관적일 수 있다는 것이 그 근본적인 이유이다. 애플리케이션 테스트에서도 동일한 테스트에 대한 비정상적인 결함 검수가 이루어질 수 있으므로, 이를 방지하기 위해서는 다양한 방법으로 테스트하는 것이 필요하다. 시스템의 특성이나 도메인에 따라 적합한 테스트 방식은 달라질 수밖에 없다."]]},{"t":"③ 결함 집중 파레토 80/20·살충제 패러독스","n":[["설명","결함 집중을 고려한다 대부분의 결함은 소수의 특정 모듈에 집중되어 발생하는 경향을 보인다. 결함의 80%는 20%의 코드에 집중되어 있다는 파레토 법칙에 따라, 결함이 많이 발생하는 영역에 테스트 자원을 집중적으로 투입하는 것이 효율적이다. 살충제 패러독스는 동일한 테스트 케이스에 의한 반복적인 테스트로는 새로운 버그를 찾지 못하는 내성 현상을 의미한다. 마치 같은 살충제를 계속 사용하면 해충이 내성을 갖게 되는 것처럼, 테스트 케이스도 주기적으로 새롭게 검토하고 개정해야 새로운 결함을 발견할 수 있다."]]},{"t":"④ 오류 부재의 궤변","n":[["설명","오류 부재의 궤변이란 개발한 제품이 사용자의 필요와 기대에 부응하지 못하고 쓸모가 없다면, 결함을 찾는 활동 자체가 의미가 없어진다는 원칙이다. 아무리 결함이 없는 완벽한 소프트웨어라 하더라도, 사용자가 원하지 않는 기능이라면 그가치는 크게 떨어진다."],["실제 사례","개발한 제품은 요구사항과 일치하고 사용에 적합해야 한다. 결함이 전혀 없는 소프트웨어를 만드는 것보다, 사용자의 실제 요구를 충족하는 소프트웨어를 만드는 것이 테스트의 궁극적인 목적이라는 점을 일곱 가지 원칙을 통해 기억해 두어야 한다."]]}]}]}]},{"t":"Ⅱ 화이트박스 테스트","c":[{"t":"1. 화이트박스 테스트의 개념","c":[{"t":"(1) 화이트박스 테스트란","c":[{"t":"① 화이트박스: 내부 논리 경로 테스트","n":[["설명","화이트박스 테스트의 정의 화이트박스 테스트는 모듈 안의 내부 논리적 경로를 테스트하는 방식으로, 모듈의 원시 코드를 오픈시킨 상태에서 원시 코드의 논리적인 모든 경로를 테스트하고 테스트 케이스를 설계하는 방법이다. 모듈 내부의 작동을 직접 관찰하고 모든 문장을 한 번 이상 실행함으로써 수행하며, 설계된 절차에 초점을 둔 구조적 테스트로서 테스트 과정의 초기에 적용된다. 화이트박스 테스트는 설계자가 논리적인 복잡성을 측정할 수 있게 해주는 테스트 기법으로, 테스트 측정 결과는 실행 경로의 기초를 정의하는 데 지침으로 사용된다. 소스 코드를 직접 분석하여 모든 문장을 실행해 보는 방법이라는 점에서, 코드가 공개되지 않는 블랙박스 테스트와 근본적인 차이가 있다."]]},{"t":"② 기초 경로 검사(Basis Path)","n":[["설명","기초 경로 검사(Basis Path Testing) 기초 경로 검사는 프로그램 내의 모든 실행 가능한 경로를 파악하여 테스트 케이스를 설계하는 기법이다. 하나의 결과값에 도달하는 방법이 여러 가지가 있다면, 그 모든 경로를 하나씩 실행해 보고 각 경로가 올바르게 동작하는지를 검사한다. 제어 구조 검사는 조건 검사(조건문에 따른 논리적 조건이 참인 경우와 거짓인 경우를 모두 테스트), 루프 검사(반복문의 반복 구조에 초점을 맞추어 테스트), 데이터 흐름 검사(변수의 정의와 사용 위치가 올바른지를 초점에 두고 테스트)로 세분화된다. 이 세 가지 검사를 통해 프로그램 내부의 논리적 흐름이 설계된 대로 정확하게 동작하는지를 검증한다."]]}]},{"t":"(2) 문장 검증과 분기 검증","c":[{"t":"① 문장 검증·분기 검증 기준","n":[["설명","문장 검증 기준(Statement Coverage) 문장 검증 기준은 소스 코드의 모든 구문이 한 번 이상 수행되도록 테스트 케이스를 설계하는 검증 기준이다. 코드의 모든 라인이 최소 한 번씩은 실행되는지를 확인하는 가장 기본적인 커버리지 기준이다. 분기 검증 기준은 결정 검증 기준이라고도 하며, 소스 코드의 모든 조건문에 대해 조건이 참인 경우와 거짓인 경우가 한 번 이상 수행되도록 테스트 케이스를 설계하는 검증 기준이다. 문장 검증보다 더 엄격한 기준으로, 각 분기(조건문의 갈래)가 모두 실행되었는지를 확인한다."]]},{"t":"② 조건 검증: 개별 조건 참·거짓","n":[["설명","조건 검증 기준(Condition Coverage) 조건 검증 기준은 소스 코드의 조건문에 포함된 개별 조건(전체 조건문이 아니라 그 안에 포함된 하나하나의 개별 조건식)의 결과가 참인 경우와 거짓인 경우가 한 번 이상 수행되도록 테스트 케이스를 설계하는 검증 기준이다. 분기·조건 검증 기준은 분기 검증과 조건 검증 기준을 모두 만족하는 설계로, 조건문이 참인 경우와 거짓인 경우에 따라 조건 검증 기준의 입력 데이터를 구분하는 테스트 케이스를 설계하는 가장 엄격한 검증 기준 방식이다."]]}]}]}]},{"t":"Ⅲ 블랙박스 테스트","c":[{"t":"1. 블랙박스 테스트의 개념","c":[{"t":"(1) 블랙박스 테스트란","c":[{"t":"① 블랙박스: 내부 구조 없이 결과 검사","n":[["설명","블랙박스 테스트의 정의 블랙박스 테스트는 내부의 논리적 구조(소스 코드)를 볼 수 없는 상태에서, 입력된 데이터가 블랙박스를 통과할 때 그 결과물이 정확한지를 검사하는 테스트를 말한다. 소프트웨어가 수행할 특정 기능을 알기 위해 각 기능이 완전히 작동되는지를 입증하는 테스트로, 기능 테스트라고도 한다. 블랙박스 테스트는 사용자의 요구사항 명세를 보면서 테스트를 수행하며, 주로 구현된 기능을 테스트 대상으로 삼는다. 부정확하거나 누락된 기능, 인터페이스 오류, 자료구조나 외부 데이터 접근에 따른 오류, 초기화및 종료 오류 등을 발견하기 위해 사용되며, 테스트 과정의 후반부에 주로 적용된다."]]},{"t":"② 동치 분할(Equivalence)","n":[["설명","동치 분할(Equivalence Partitioning)"],["쉬운 예","동치 분할은 균등 분할이라고도 하며, 입력 자료에 초점을 맞추어 테스트 케이스를 만들고 검사하는 방법이다. 타당한 입력 자료와 타당하지 않은 입력 자료의 개수를 균등하게 만들어 테스트 케이스를 결정하고, 그 입력 자료에 맞는 결과가 제대로 출력되는지를 확인한다. 예를 들어 한 자리 정수를 더하는 프로그램에서 1+1부터 9+9까지 81가지 경우는 모두 동등한 특성을 가지므로, 이를 모두 모아 대표적인 몇 가지 케이스만 테스트하면 충분하다."],["쉬운 예","경계값 분석은 입력 자료에만 의존하는 동치 분할 기법을 보완하기 위한 기법으로, 입력 조건의 중간 값보다는 경계값(처음과 마지막 값)에서 오류가 발생할 확률이 높다는 점에 착안한 기법이다. 예를 들어 반복문의 조건을 설정할 때 마지막 값을 포함하는지 여부를 놓치는 실수가 자주 발생하므로, 경계가 되는 값을 중점적으로 테스트하는 것이 결함 발견에 효과적이다."]]}]},{"t":"(2) 원인-효과 그래프 검사와 오류 예측 검사","c":[{"t":"① 원인-효과 그래프 검사","n":[["설명","원인-효과 그래프 검사(Cause-Effect Graphing) 원인-효과 그래프 검사는 입력 데이터 간의 관계와 출력에 영향을 미치는 상황들을 체계적으로 분석하는 기법이다. 입력 데이터가 있을 때 어떻게 출력되는지 그 상황을 분석하여 이를 테스트 케이스로 선정하여 검사한다. 오류 예측 검사는 과거의 경험이나 테스터의 감각을 바탕으로 결함이 있을 만한 부분을 예측하여 테스트하는 기법이다. 다른 블랙박스 테스트 기법으로는 찾을 수 없는 오류를 찾아내는 일종의 보충 검사 역할을 한다."]]},{"t":"② 비교 검사: 여러 버전 동일 입력","n":[["설명","비교 검사(Comparison Testing) 비교 검사는 여러 버전의 프로그램에 동일한 자료를 입력하여 결과가 동일하게 나오는지를 비교하는 테스트 기법이다. 소프트웨어의 신뢰성이 특히 중요한 경우에 여러 개의 독립적인 버전을 개발하여 상호 비교하는 방식으로 활용되기도 한다. 화이트박스 테스트는 소스 코드의 내부 논리 구조를 검사 대상으로 삼아 테스트 초기에 적용되며, 기초 경로 검사와 제어 구조 검사(조건, 루프, 데이터 흐름)의 기법을 사용한다. 블랙박스 테스트는 명세서 기반으로 입력과 출력의 대응 관계를 검사 대상으로 삼아 테스트 후반부에 적용되며, 동치 분할, 경계값 분석, 원인-효과 그래프, 오류 예측, 비교 검사 등의 기법을 사용한다는 점에서 뚜렷하게 대비된다."]]}]}]}]},{"t":"Ⅳ 테스트 케이스와 테스트 오라클","c":[{"t":"1. 테스트 케이스(Test Case)","c":[{"t":"(1) 테스트 케이스의 개념","c":[{"t":"① 테스트 케이스: 입력값·실행조건·기대결과","n":[["설명","테스트 케이스란 테스트 케이스는 명세 기반 테스트의 설계 산출물로서, 특정한 프로그램의 일부분 또는 경로에 따라 수행하거나 특정한 요구사항을 준수하는지 확인하기 위해 설계된 입력값, 실행 조건, 기대 결과로 구성된 테스트 항목의 명세서를 의미한다. 테스트 케이스를 미리 설계해 두면 오류를 방지할 수 있고, 테스트 수행에 필요한 인력과 시간 등의 낭비를 축소할 수 있다. 테스트 케이스는 일반적으로 계획 검토 및 참조 문서 수집 → 내부 검토 및 우선순위 결정 → 요구사항 정의 → 테스트 설계와 방법 결정 → 테스트 케이스 정의 → 테스트 케이스 타당성 확인 및 유지보수 → 테스트 수행의 순서로 작성된다."]]},{"t":"② 테스트 설계·테스트 구현","n":[["설명","테스트 설계 테스트 설계는 개발된 소프트웨어나 시스템의 요구사항, 요구사항 명세서, 업무 구조, 시스템 구조 등을 기반으로, 소프트웨어의 어떤 부분을 어떻게 접근하여 테스트할지에 대한 상황과 방법을 파악하는 과정이다. 테스트 구현은 테스트 설계를 체계적으로 구체화시켜 테스트 케이스를 도출하고 작성하는 과정이며, 테스트 설계 방법은 이러한 상황과 방법을 구체화하기 위한 수단 및 도구를 의미한다."]]}]},{"t":"(2) 테스트 오라클의 개념","c":[{"t":"① 테스트 오라클 개념","n":[["설명","테스트 오라클이란"],["실제 사례","테스트 오라클은 테스트의 결과가 참인지 거짓인지를 판단하기 위해서 사전에 정의된 참 값을 입력하여 비교하는 기법 및 활동을 말한다. 실제 실행 결과와 기대하는 결과를 비교할 수 있는 기준이 없다면, 테스트를 수행하더라도 그 결과가 옳은지 판단할 수 없기 때문에 테스트 오라클이 반드시 필요하다."]]},{"t":"② 샘플링 오라클·휴리스틱 오라클","n":[["설명","샘플링 오라클과 휴리스틱 오라클 샘플링 오라클은 특정한 입력값들에 대해서만 기대하는 결과를 제공하는 오라클이다. 휴리스틱(추정) 오라클은 샘플링 오라클을 개선한 오라클로, 특정 입력값에 대해서는 올바른 결과를 제공하고 나머지 값들에 대해서는 휴리스틱(추정)으로 처리하는 방식이다. 일관성 검사 오라클은 애플리케이션에 변경이 있을 때, 수행 전과 후의 결과값이 동일한지를 확인하는 오라클이다. 프로그램을 수정한 이후 기존 기능이 의도치 않게 손상되지 않았는지를 확인하는 회귀 테스트에서 특히 유용하게 활용된다."]]}]}]}]},{"t":"Ⅴ 테스트 자동화","c":[{"t":"1. 테스트 자동화의 배경과 개념","c":[{"t":"(1) 테스트 자동화의 배경","c":[{"t":"① 테스트 자동화 필요성: 비용 절반 이상","n":[["설명","테스트 자동화의 필요성 소프트웨어 테스트는 소프트웨어 개발에 소요되는 총 시간과 비용의 절반 이상을 차지할 정도로 비중이 크다. 따라서 테스트의 정확성을 유지하면서 시간과 비용을 줄일 수 있는 자동화 도구의 활용이 매우 중요하게 다루어진다. 테스트 자동화는 사람이 하던 반복적인 테스트 절차를 자동화 도구를 활용하여 수행하는 것을 말한다. 준비, 구현, 수행, 분석 등을 스크립트 형태로 구현함으로써 테스트 시간과 인력 투입 부담을 최소화하고, 사람의 실수(Human Error)를 최소화할 수 있다."]]},{"t":"② 자동화 도구 장점: 인력·시간 최소화","n":[["설명","테스트 자동화 도구의 장점 반복 작업의 자동화를 통해 테스트 인력과 시간을 최소화할 수 있으며, 향상된 요구사항 정의와 성능 및 스트레스 테스트, 품질 측정을 최적화할 수 있다. 또한 빌드 확인, 회귀 테스트, 다중 플랫폼 호환성 확인, 소프트웨어 구성 확인 등 향상된 테스트 품질을 보장할 수 있다. 테스트 자동화 도구를 도입한 이후에는 도구 전문가의 양성 또는 고용이 필요하며, 초기에 프로세스 적용을 위한 시간, 비용, 노력에 대한 추가 투자가 필요하다. 특히 비공개 상용 소프트웨어의 경우 고가이며 인력과 교육에 대한 유지관리 비용이 높다는 단점이 있다."]]}]},{"t":"(2) 스크립트 설계와 도구 선정","c":[{"t":"① 스크립트 재사용성·도구 선정","n":[["설명","재사용성 고려 테스트 절차를 고려하여 재사용 및 측정이 불가능한 테스트 프로그램은 자동화 대상에서 제외해야 하며, 설계 기준을 고려하여 반복적인 빌드에서 스크립트의 재사용성이 있어야 한다. 모든 수동 테스트 과정을 자동화할 수 있는 도구는 존재하지 않으므로, 용도에 맞는 적절한 도구를 사용해야한다. 도구의 환경 설정과 습득 기간을 고려하여 프로젝트의 지연을 방지해야 한다."]]},{"t":"② 테스트 엔지니어 투입 시기","n":[["설명","적절한 투입 시기의 중요성 테스트 엔지니어의 늦은 투입은 프로젝트에 대한 이해 부족으로 불완전한 테스트를 초래할 수 있으므로, 프로젝트 초기에 적절한 투입 시기와 계획을 수립해야 한다. 테스트 활동은 테스트 계획(요구사항 관리), 테스트 분석·설계(테스트 케이스 생성, 커버리지 분석), 테스트 수행(테스트 자동화, 정적 분석, 동적 분석, 성능 테스트, 모니터링), 테스트 통제(형상 관리, 테스트 관리, 결함 추적·관리)와 같은 세부 단계로 나뉘며, 각 단계에 맞는 적절한 테스트 도구를 선정하여 활용해야 한다."]]}]}]}]},{"t":"Ⅵ 소프트웨어 품질 특성","c":[{"t":"1. ISO/IEC 25010 품질 특성","c":[{"t":"(1) 기능성과 신뢰성","c":[{"t":"① 기능성: 완전성·정확성·상호운용성 ·보안성","n":[["설명","기능성(Functionality) 기능성은 소프트웨어가 사용자의 요구를 만족시키는 기능을 제공하는 정도를 의미하며, 완전성(필요한 모든 기능의 구현), 정확성(정확한 결과 산출), 상호운용성(다른 시스템과의 연동 가능성), 보안성(데이터와 정보를 보호하는 능력)을 하위 특성으로 포함한다. 신뢰성은 소프트웨어가 정해진 조건에서 일정 시간 동안 요구되는 기능을 안정적으로 수행하는 능력을 의미하며, 성숙성(결함으로 인한 고장 발생 빈도), 결함 허용성(결함이 발생해도 정해진 성능을 유지하는 능력), 회복성(장애 발생 후 정상 복귀 능력)을 포함한다."]]},{"t":"② 사용성·효율성","n":[["설명","사용성(Usability) 사용성은 사용자가 소프트웨어를 얼마나 쉽게 이해하고 학습하며 사용할 수 있는지를 나타내는 특성으로, 이해성, 학습성, 운용성, 매력성을 하위 특성으로 포함한다. 효율성은 소프트웨어가 사용하는 자원의 양에 대해 요구되는 성능을 제공하는 능력을 의미하며, 시간 효율성( 응답 속도, 처리량)과 자원 효율성(메모리, CPU 등 자원 사용량)을 하위 특성으로 포함한다."]]}]},{"t":"(2) 유지보수성(Maintainab ility)","c":[{"t":"① 유지보수성 개념","n":[["설명","유지보수성의 개념"],["시험 포인트","유지보수성은 소프트웨어에 결함이 발견되거나 새로운 요구사항이 추가되었을 때, 이를 얼마나 쉽게 수정하고 개선할 수 있는지를 나타내는 특성이다. 모듈성, 재사용성, 분석성, 수정성, 시험성을 하위 특성으로 포함한다."]]},{"t":"② 이식성·호환성","n":[["설명","이식성 이식성은 소프트웨어가 다른 환경(운영체제, 하드웨어)으로 옮겨졌을 때 얼마나 쉽게 적응할 수 있는지를 나타내는 특성으로, 적응성, 설치성, 대체성을 하위 특성으로 포함한다. 호환성은 동일한 환경에서 다른 소프트웨어와 정보를 교환하거나 함께 사용될 수 있는 능력을 의미하며, 공존 성과 상호운용성을 하위 특성으로 포함한다."]]}]}]}]},{"t":"Ⅶ 소스 코드 품질 분석","c":[{"t":"1. 정적 분석과 동적 분석","c":[{"t":"(1) 정적 분석(Static Analysis)","c":[{"t":"① 정적 분석: 실행 없이 코드 분석","n":[["설명","정적 분석의 개념 정적 분석은 프로그램을 실행하지 않고 소스 코드 자체를 분석하여 코딩 스타일, 잠재적인 결함, 보안 취약점 등을 검출하는 기법이다. 코드 인스펙션이나 정적 분석 도구를 통해 컴파일 전 단계에서도 문제를 발견할 수있다는 장점이 있다. 대표적인 정적 분석 도구로는 자바 진영의 SonarQube, checkstyle, PMD, C/C++ 진영의 cppcheck 등이 있으며, 이러한 도구는 코드의 복잡도, 중복도, 규칙 위반 여부 등을 자동으로 검사하여 리포트를 제공한다."]]},{"t":"② 동적 분석 개념","n":[["설명","동적 분석의 개념"],["실제 사례","동적 분석은 프로그램을 실제로 실행한 상태에서 코드의 동작을 분석하는 기법으로, 메모리 누수, 예외 발생, 성능 저하와 같이 실행 중에만 나타나는 문제를 발견하는 데 효과적이다."]]}]},{"t":"(2) 코드 인스펙션(Code Inspection)","c":[{"t":"① 코드 인스펙션: 체크리스트 정형 검토","n":[["설명","코드 인스펙션의 개념 코드 인스펙션은 정형화된 절차에 따라 여러 명의 검토자가 모여 소스 코드를 검토하며 결함을 찾아내는 정적 테스트 기법이다. 사전에 정의된 체크리스트를 기반으로 진행하며, 결함이 발견되면 이를 공식적으로 기록하고 추적한다. 코드 인스펙션을 통해 코딩 표준 위반, 논리적 오류, 비효율적인 코드 등을 조기에 발견할 수 있으며, 검토 과정에서 팀원 간의 지식 공유 효과도 함께 얻을 수 있다."]]},{"t":"② 워크스루: 작성자 주도 비형식 검토","n":[["설명","워크스루의 개념 워크스루는 개발자가 작성한 코드나 설계 문서를 동료들에게 직접 설명하면서 함께 검토하는 비형식적인 검토 기법이다. 코드 인스펙션보다 절차가 덜 형식적이고 유연하게 진행된다는 특징이 있다. 워크스루는 작성자가 진행을 주도하며, 참석자들은 자유롭게 질문하고 의견을 제시한다. 격식에 얽매이지 않고 빠르게 피드백을 주고받을 수 있어 소규모 팀이나 프로젝트 초기 단계에서 유용하게 활용된다."]]}]}]}]},{"t":"Ⅷ 테스트 관리와 테스트 프로세스 개선","c":[{"t":"1. 테스트 관리의 개념","c":[{"t":"(1) 테스트 관리란","c":[{"t":"① 테스트 관리: 계획~종료 판정 통제","n":[["설명","테스트 관리의 정의 테스트 관리는 테스트 계획 수립부터 테스트 케이스 설계, 테스트 실행, 결과 분석, 종료 판정에 이르는 전체 테스트 활동을 체계적으로 통제하고 조율하는 활동을 의미한다. 테스트 관리자는 테스트 일정과 자원을 계획하고, 테스트 팀원에게 역할을 배분하며, 테스트 진행 상황과 품질 지표를 이해관계자에게 보고하는 역할을 담당한다."]]},{"t":"② 테스트 환경 개념","n":[["설명","테스트 환경의 개념"],["실제 사례","테스트 환경은 테스트를 수행하기 위해 필요한 하드웨어, 소프트웨어, 네트워크, 테스트 데이터 등을 갖춘 환경을 의미한다. 실제 운영 환경과 최대한 유사하게 구성해야 신뢰성 있는 테스트 결과를 얻을 수 있다."],["실제 사례","테스트 데이터는 실제 운영 데이터를 일부 가공하여 사용하거나, 테스트 목적에 맞게 별도로 생성하여 사용한다. 개인정보가 포함된 경우 마스킹 처리를 통해 보안을 유지하며 테스트를 진행해야 한다."]]}]},{"t":"(2) TMMi(테스트 성숙도 모델)","c":[{"t":"① TMMi 테스트 프로세스 성숙도 모델","n":[["설명","TMMi의 개념 TMMi는 조직의 테스트 프로세스 성숙도를 평가하고 개선하기 위한 국제적인 참조 모델이다. 테스트 프로세스가 얼마나 체계적이고 최적화되어 있는지를 단계별 수준으로 평가한다. TMMi는 초기(Initial), 관리(Managed), 정의(Defined), 관리 및 측정(Measured), 최적화 (Optimization)의 다섯 단계로 성숙도를 구분하며, 단계가 높아질수록 테스트 프로세스가 더욱 체계적이고 예측 가능하게 운영됨을 의미한다."]]},{"t":"② 테스트 회고(Retrospecti ve)","n":[["설명","테스트 회고(Retrospective) 테스트 회고는 하나의 테스트 사이클이 종료된 이후, 잘된 점과 개선이 필요한 점을 팀원들과 함께 논의하는 활동이다. 이를 통해 다음 테스트 주기에서 반복되는 문제를 줄이고 프로세스를 지속적으로 개선할 수 있다. 결함 발견율, 테스트 케이스 실행률, 결함 재발률과 같은 정량적인 지표를 지속적으로 수집하고 분석하면, 테스트 프로세스의 문제점을 객관적으로 파악하고 개선 방향을 설정하는 데 활용할 수 있다."]]}]}]}]},{"t":"Ⅸ 애자일 방법론에서의 테스트","c":[{"t":"1. 애자일 테스트의 특징","c":[{"t":"(1) 애자일 테스트란","c":[{"t":"① 애자일 테스트: 스프린트마다 테스트","n":[["설명","애자일 테스트의 개념 애자일 테스트는 짧은 반복 주기(스프린트)마다 개발과 테스트를 함께 진행하는 애자일 개발 방법론에 맞추어 수행되는 테스트 접근 방식이다. 폭포수 모델처럼 개발이 모두 끝난 뒤 테스트를 몰아서 하는 것이 아니라, 각 스프린트마다 지속적으로 테스트를 병행한다. 애자일 테스트는 변화하는 요구사항에 유연하게 대응하며, 개발자와 테스터가 밀접하게 협업하고, 자동화된 테스트를 적극적으로 활용하여 짧은 주기 안에 반복적으로 품질을 검증한다는 특징을 가진다."]]},{"t":"② 애자일 테스트 사분면","n":[["설명","사분면의 개념 애자일 테스트 사분면은 테스트를 비즈니스 지향/기술 지향, 팀 지원/제품 비판이라는 두 가지 축으로 나누어네 가지 유형으로 분류하는 프레임워크이다. 1사분면은 단위/컴포넌트 테스트와 같이 팀을 지원하는 기술 중심 테스트, 2사분면은 사용자 스토리 기반 인수 테스트와 같이 팀을 지원하는 비즈니스 중심 테스트, 3사분면은 탐색적 테스트와 사용성 테스트, 4사분면은 성능/보안 테스트와 같은 제품 비판적 기술 테스트로 구성된다."]]}]},{"t":"(2) 지속적 통합(CI)에서의 테스트","c":[{"t":"① CI 파이프라인 자동 빌드·단위 테스트","n":[["설명","CI 파이프라인과 자동화 테스트 지속적 통합(Continuous Integration) 환경에서는 개발자가 코드를 저장소에 반영할 때마다 자동으로 빌드와 단위 테스트가 수행되어, 결함을 즉시 발견할 수 있는 체계를 갖춘다. 지속적 배포(Continuous Deployment) 환경에서는 자동화된 회귀 테스트 스위트를 통과한 코드만 운영 환경에 배포되도록 하여, 배포 전 발생할 수 있는 결함을 사전에 차단한다."]]},{"t":"② 탐색적 테스트: 경험·직관 의존","n":[["설명","탐색적 테스트의 개념 탐색적 테스트는 사전에 정해진 테스트 케이스 없이, 테스터가 자유롭게 애플리케이션을 탐색하며 결함을 찾아내는 비정형 테스트 기법이다. 테스터의 경험과 직관에 크게 의존한다. 탐색적 테스트는 형식화된 테스트 케이스로는 발견하기 어려운 예상치 못한 결함을 찾아내는 데 효과적이며, 애자일 환경에서 짧은 시간 안에 폭넓게 품질을 점검할 때 자주 활용된다."]]}]}]}]},{"t":"Ⅹ 테스트 유형별 세부 기법","c":[{"t":"1. 성능 테스트의 세부 기법","c":[{"t":"(1) 부하 테스트와 스트레스 테스트","c":[{"t":"① 부하 테스트(Load Testing)","n":[["설명","부하 테스트(Load Testing)"],["실제 사례","부하 테스트는 시스템이 예상되는 최대 사용자 수나 트랜잭션 양을 처리할 때 정상적으로 동작하는지를 확인하는 테스트이다. 실제 운영 환경에서 예상되는 부하 수준을 시뮬레이션하여 응답 시간과 처리량을 측정한다."]]},{"t":"② 내구성(Soak) 테스트·급증 테스트","n":[["설명","내구성 테스트(Endurance/Soak Testing) 내구성 테스트는 시스템에 일정한 부하를 장시간 지속적으로 가하여, 시간이 지남에 따라 메모리 누수나 성능 저하와 같은 문제가 발생하는지를 확인하는 테스트이다. 급증 테스트는 짧은 시간 동안 사용자 요청이 급격히 증가하는 상황(예: 이벤트 오픈 직후)을 시뮬레이션하여, 시스템이 갑작스러운 트래픽 증가에도 안정적으로 대응하는지를 확인하는 테스트이다."]]}]},{"t":"(2) 취약점 스캐닝과 침투 테스트","c":[{"t":"① 취약점 스캐닝: SQL 인젝션·XSS","n":[["설명","취약점 스캐닝(Vulnerability Scanning) 취약점 스캐닝은 자동화된 도구를 이용하여 시스템에 알려진 보안 취약점이 존재하는지를 점검하는 기법이다. SQL 인젝션, 크로스 사이트 스크립팅(XSS)과 같은 대표적인 취약점 패턴을 자동으로 탐지한다."],["실제 사례","침투 테스트는 실제 공격자의 관점에서 시스템에 침투를 시도하여 보안 취약점을 찾아내는 테스트이다. 자동화 도구뿐만 아니라 전문가의 수동 분석을 함께 병행하여 보다 정교한 취약점을 발견할 수 있다."]]},{"t":"② 인증 테스트·권한 테스트","n":[["설명","인증(Authentication) 테스트 인증 테스트는 로그인, 비밀번호 재설정, 세션 관리와 같은 사용자 인증 관련 기능이 안전하게 구현되었는지를 확인하는 테스트이다. 무차별 대입 공격에 대한 방어 기능도 함께 점검한다. 권한 테스트는 사용자가 자신에게 허용되지 않은 기능이나 데이터에 접근할 수 없는지를 확인하는 테스트이다. 관리자 권한이 필요한 기능에 일반 사용자가 접근을 시도했을 때 정상적으로 차단되는지를 검증한다. Ⅺ. 테스트 조직과 역할"],["실제 사례","테스트 엔지니어는 실제 테스트 케이스를 설계하고 실행하는 역할을 담당하며, 테스트 리드는 테스트 팀을 총괄하며 일정과 자원을 관리하고 테스트 전략을 수립하는 역할을 담당한다."],["실제 사례","품질 관리는 실제 산출물(소프트웨어)이 요구되는 품질 기준을 충족하는지를 검사하고 결함을 찾아내는 활동을 의미한다. 테스트 활동은 대표적인 QC 활동에 해당한다."],["실제 사례","동적 테스트는 프로그램을 실제로 실행시켜 결과를 확인하는 방식으로, 화이트박스/블랙박스 테스트를 포함한 대부분의 전통적인 테스트 기법이 이에 해당한다."]]}]}]}]}]},{"t":"제3절 테스트 레벨과 V모델","c":[{"t":"Ⅰ V모델과 테스트 레벨의 개요","c":[{"t":"1. V모델(V-Model)의 개념","c":[{"t":"(1) V모델이란","c":[{"t":"① V모델: 개발-테스트 단계 대응","n":[["설명","V모델의 정의 V모델은 소프트웨어 개발 단계와 테스트 단계를 대응시켜 표현한 모델로, 폭포수 모델에 테스트 단계를 강조하여 결합한 형태이다. 개발 단계가 왼쪽 하향 곡선으로, 테스트 단계가 오른쪽 상향 곡선으로 표현되어 전체 적으로 V자 형태를 이루기 때문에 V모델이라는 이름이 붙었다. V모델에서는 요구사항 분석이 인수 테스트와, 시스템 설계가 시스템 테스트와, 아키텍처(상세) 설계가 통합 테스트와, 모듈(프로그램) 설계 및 구현이 단위 테스트와 서로 대응된다. 즉 왼쪽에서 정의된 각 개발 산출물은 오른쪽의 대응되는 테스트 단계에서 검증되는 구조를 가진다."]]},{"t":"② 요구분석 시 인수 테스트 계획","n":[["설명","조기 테스트 계획의 중요성 V모델은 테스트가 코딩이 완료된 이후에 수행되는 활동이 아니라, 요구사항 분석 단계부터 함께 계획되어야 함을 시각적으로 보여준다. 요구사항 분석 시점에 이미 인수 테스트 계획을 함께 수립함으로써, 테스트 준비 시간을 앞당기고 요구사항 자체의 모호함이나 결함을 조기에 발견할 수 있다. V모델을 적용하면 각 개발 단계의 산출물이 완성되는 즉시 대응되는 테스트 단계의 계획과 케이스 설계를 병행할 수 있어, 개발이 끝난 뒤 몰아서 테스트를 계획하는 방식보다 결함을 훨씬 더 이른 시점에 발견하고 수정 비용을 낮출 수 있다."]]}]},{"t":"(2) 테스트 레벨의 4단계","c":[{"t":"① 수행 단계별 테스트 레벨 분류","n":[["설명","프로젝트 수행 단계에 따른 분류"],["시험 포인트","테스트는 프로젝트 수행 단계에 따라 단위 테스트, 통합 테스트, 시스템 테스트, 인수 테스트의 네단계로 분류된다. 이를 앞글자를 따서 \"단통시인\"으로 암기하면 순서를 기억하기 쉽다."],["실제 사례","단위 테스트는 모듈이나 컴포넌트 단위의 내부 로직을, 통합 테스트는 모듈 간의 인터페이스와 상호작용을, 시스템 테스트는 전체 시스템이 요구사항을 충족하는지를, 인수 테스트는 사용자 관점에서 실제 사용 환경에서의 만족도를 각각 확인 대상으로 삼는다."]]},{"t":"② 단위→시스템 점진적 범위 확대","n":[["설명","점진적 확대 구조 테스트 레벨은 단위에서 시스템으로 갈수록 테스트의 범위가 점진적으로 확대되는 구조를 가진다. 작은 단위에서 결함이 없음을 확인한 후 점차 더 큰 단위로 통합하며 테스트를 진행함으로써, 결함의 원인을 좁은 범위 내에서 효율적으로 추적할 수 있다."],["실제 사례","일반적으로 단위 테스트와 통합 테스트는 개발자가 주로 수행하고, 시스템 테스트는 전문 테스트 조직이, 인수 테스트는 실제 사용자나 고객이 주체가 되어 수행하는 경우가 많다."]]}]}]}]},{"t":"Ⅱ 단위 테스트(Unit Test)","c":[{"t":"1. 단위 테스트의 개념과 대상","c":[{"t":"(1) 단위 테스트란","c":[{"t":"① 단위 테스트: 모듈 단독 기능 검증","n":[["설명","단위 테스트의 정의 단위 테스트는 개발자가 각 단위(모듈, 클래스, 함수 등) 자체에 대해 요구사항 명세에 따른 기능을 정확히 수행하는지 검증하는 테스트이다. 사용자의 요구사항에 대한 단위 모듈, 서브루틴 등을 다른 부분과 연계되지 않은 상태로 테스트하며, 화이트박스 테스트 기법을 주로 사용한다. 단위 테스트는 모듈 내부의 자료구조, 알고리즘의 정확성, 조건문과 반복문의 처리 등을 세부적으로 검증하여, 이후 단계인 통합 테스트에서 발생할 수 있는 결함을 사전에 최소화하는 것을 목적으로 한다."]]},{"t":"② 단위 테스트 기법","n":[["설명","단위 테스트 기법"],["실제 사례","단위 테스트는 코드 자체를 확인하는 정적 테스트(코드 검사, 워크스루, 인스펙션)와, 실제 코드를 실행하여 확인하는 동적 테스트(화이트박스/블랙박스 테스트 기법)로 나뉜다. 자동화된 단위 테스트 도구를 사용하면 스텁(Stub)이나 드라이버(Driver) 없이도 프레임워크 차원에서 개별 모듈을 실행하고 결과를 검증할수 있다."]]}]},{"t":"(2) 테스트 준비와 실행","c":[{"t":"① 단위 테스트 케이스 사전 설계","n":[["설명","테스트 케이스 설계 단위 테스트를 수행하기 전, 대상 모듈의 입력과 출력, 예외 상황을 고려한 테스트 케이스를 먼저 설계한다. 이때 경계값 분석이나 동치 분할과 같은 블랙박스 기법과, 문장/분기 커버리지와 같은 화이트박스 기법을 함께 활용하여 테스트 케이스의 완전성을 높인다."],["실제 사례","설계된 테스트 케이스를 실제로 실행하여 예상 결과와 실제 결과를 비교한다. 자동화 도구를 사용하는 경우 이 과정이 빌드 시마다 자동으로 반복 수행되도록 구성하여, 코드 변경으로 인한 회귀 결함을 즉시 탐지할 수 있다."]]},{"t":"② 결함 조기 발견·낮은 수정 비용","n":[["설명","결함의 조기 발견 단위 테스트는 전체 테스트 단계 중 가장 이른 시점에 수행되므로, 여기서 발견된 결함은 상대적으로 수정 비용이 매우 낮다. 결함이 늦게 발견될수록 수정 비용이 기하급수적으로 증가한다는 것이 소프트웨어 공학의 일반적인 원칙이다. 충분한 단위 테스트가 갖추어져 있으면, 이후 코드를 리팩토링(내부 구조 개선)하더라도 기존 기능이 손상되지 않았음을 신속하게 확인할 수 있어, 코드 품질을 지속적으로 개선해 나가는 데 중요한 안전망 역할을 한다."]]}]}]}]},{"t":"Ⅲ 통합 테스트(Integration Test)","c":[{"t":"1. 통합 테스트의 개념과 필요성","c":[{"t":"(1) 통합 테스트란","c":[{"t":"① 통합 테스트: 모듈 간 인터페이스 검증","n":[["설명","통합 테스트의 정의 통합 테스트는 단위 테스트를 통과한 모듈들을 결합하여, 하나의 시스템으로 정상적으로 동작하는지, 모듈 간인터페이스에 결함이 없는지를 검증하는 테스트이다. 개별 모듈은 정상적으로 동작하더라도, 모듈 간의 데이터 전달이나 호출 관계에서 예상치 못한 결함이 발생할 수 있기 때문에 반드시 필요하다. 통합 테스트에서는 주로 인터페이스 간 데이터 전달 오류, 모듈 간 호출 순서의 오류, 자원(메모리, 파일 등)의 공유로 인한 충돌, 전역 변수의 잘못된 사용 등이 발견된다."]]},{"t":"② 점증적 통합·비점증적(빅뱅) 통합","n":[["설명","점증적 통합과 비점증적 통합 점증적 통합 방식은 모듈을 하나씩 순차적으로 결합하며 테스트를 반복하는 방식이고, 비점증적 통합 방식(빅뱅 방식)은 전체 모듈을 한꺼번에 결합한 뒤 테스트하는 방식이다. 일반적으로 점증적 통합 방식이 결함의 위치를 좁혀 원인을 찾기 쉬우므로 더 선호된다. 통합 테스트 전략은 시스템의 구조와 개발 일정, 모듈의 완성도 등을 고려하여 빅뱅 방식, 상향식 방식, 하향식 방식, 혼합식(샌드위치) 방식 중에서 적절히 선택하여 적용한다."]]}]},{"t":"(2) 빅뱅 방식과 상향식 방식","c":[{"t":"① 빅뱅 방식: 단순하나 원인 추적 곤란","n":[["설명","빅뱅 방식(Big Bang Integration) 빅뱅 방식은 단위 테스트가 끝난 모든 모듈을 한꺼번에 결합하여 테스트하는 방식이다. 절차가 단순하고 시간이 적게 걸리는 장점이 있지만, 결함이 발생했을 때 어느 모듈에서 문제가 발생했는지 원인을 찾기가 매우 어렵다는 단점이 있다. 상향식 방식은 최하위 모듈부터 순차적으로 상위 모듈로 통합하며 테스트를 진행하는 방식이다. 상위 모듈이 아직 개발되지 않은 상태에서 하위 모듈을 호출하는 역할을 하는 테스트 드라이버(Driver)가 필요하며, 하위 모듈들을 하나의 클러스터(Cluster)로 결합하여 관리한다는 특징이 있다."]]},{"t":"② 하향식 통합(Top-Down)","n":[["설명","하향식 방식(Top-Down Integration)"],["시험 포인트","하향식 방식은 최상위 모듈부터 시작하여 하위 모듈을 순차적으로 결합해 나가는 방식이다. 아직 개발되지 않은 하위 모듈을 임시로 대체하는 스텁(Stub)이 필요하며, 깊이 우선(Depth-First) 또는 너비 우선 (Breadth-First) 방식으로 통합 순서를 결정한다. \"하스톱(하향식-스텁), 상클러(상향식-클러스터, 드라이버)\" 로 암기하면 혼동을 줄일 수 있다."]]}]}]}]},{"t":"Ⅳ 시스템 테스트와 인수 테스트","c":[{"t":"1. 시스템 테스트(System Test)","c":[{"t":"(1) 시스템 테스트란","c":[{"t":"① 시스템 테스트 정의","n":[["설명","시스템 테스트의 정의"],["실제 사례","시스템 테스트는 통합된 전체 시스템이 명시된 요구사항을 충족하는지를 검증하는 테스트이다. 개발된 소프트웨어가 실제 운영 환경과 유사한 조건에서 하드웨어, 네트워크, 운영체제 등 다른 시스템 구성요소와 함께 정상적으로 동작하는지를 확인한다."]]},{"t":"② 성능 테스트·보안 테스트","n":[["설명","성능 테스트와 보안 테스트 성능 테스트는 시스템이 특정 부하 상황에서도 응답 시간, 처리량 등의 성능 목표를 만족하는지를 확인하며, 부하 테스트와 스트레스 테스트를 포함한다. 보안 테스트는 시스템이 인가되지 않은 접근이나 공격으로부터 데이터와 자원을 안전하게 보호하는지를 확인한다. 회복 테스트는 시스템 장애 발생 후 정상 상태로 복구되는 능력을 확인하는 테스트이며, 호환성 테스트는 다양한 운영체제, 브라우저, 하드웨어 환경에서 시스템이 동일하게 동작하는지를 확인하는 테스트이다."]]}]},{"t":"(2) 인수 테스트란","c":[{"t":"① 인수 테스트: 사용자 최종 확인","n":[["설명","인수 테스트의 정의 인수 테스트는 개발된 소프트웨어가 사용자의 요구사항을 충족하는지를 사용자나 고객이 직접 확인하는 최종 단계의 테스트이다. 계약상 요구사항의 충족 여부를 판단하여 소프트웨어의 인수 여부를 결정하는 것이 목적이다."],["실제 사례","인수 테스트는 실제 사용 환경에서 실제 사용자에 의해 수행되며, 형식적인 절차보다는 사용자의 만족도와 실무 적합성에 더 중점을 둔다는 점에서 앞선 세 단계의 테스트와 성격이 다르다."]]},{"t":"② 알파 테스트: 개발자 입회·통제 환경","n":[["설명","알파 테스트(Alpha Test) 알파 테스트는 개발자의 장소에서 사용자가 개발자 입회 하에 수행하는 테스트로, 통제된 환경에서 실시된다. 문제가 발생하거나 사용상의 불편함이 나타나면 즉시 이를 기록하여 개발자에게 통보한다."],["실제 사례","베타 테스트는 사용자가 직접 실제 운영 환경에서 일정 기간 사용해보면서 문제점을 찾는 테스트로, 개발자 없이 사용자에 의해서만 진행된다. 다수의 사용자에게 배포하여 다양한 환경에서의 결함을 폭넓게 수집할 수 있다는 장점이 있다."]]}]}]}]},{"t":"Ⅴ 테스트 시나리오와 커버리지","c":[{"t":"1. 테스트 시나리오와 테스트 계획서","c":[{"t":"(1) 테스트 시나리오(Test Scenario)","c":[{"t":"① 테스트 시나리오: 케이스 묶음·순서","n":[["설명","테스트 시나리오의 개념 테스트 시나리오는 테스트 케이스를 여러 개 묶어서 정의한 것으로, 테스트를 어떤 절차와 순서로 진행할 것인지를 명세한 문서이다. 각 테스트 항목이 수행되어야 할 순서, 전후 관계, 테스트 데이터의 흐름 등을 종합적으로 정의한다. 테스트 시나리오는 여러 명의 테스터가 참여하는 대규모 테스트에서 일관된 절차로 테스트를 진행할 수 있게해 주며, 테스트의 누락을 방지하고 재현 가능한 테스트 환경을 보장하는 역할을 한다."]]},{"t":"② 테스트 계획서·결과보고서","n":[["설명","테스트 계획서 테스트 계획서는 테스트의 목적, 범위, 대상, 일정, 인력, 방법, 종료 조건 등을 문서화한 산출물이다. 테스트를 시작하기 전 전체적인 방향을 수립하는 기준이 되며, 프로젝트 착수 초기에 작성되어 지속적으로 갱신된다. 테스트 결과보고서는 테스트 수행 결과를 정리한 문서로, 발견된 결함의 목록과 심각도, 테스트 커버리지 달성률, 테스트 종료 여부에 대한 판단 근거 등을 포함하여 이해관계자에게 테스트 결과를 공유하는 데 활용된다."]]}]},{"t":"(2) 테스트 커버리지의 개념","c":[{"t":"① 커버리지 100%≠무결함","n":[["설명","테스트 커버리지란 테스트 커버리지는 테스트 케이스가 소프트웨어의 실행 가능한 부분을 얼마나 포괄하고 있는지를 측정하는 척도이다. 커버리지가 높을수록 더 많은 코드 경로가 테스트되었음을 의미하지만, 100%의 커버리지가 결함이 전혀 없음을 보장하지는 않는다. 커버리지 측정 도구를 사용하면 테스트되지 않은 코드 영역을 시각적으로 확인할 수 있어, 테스트 케이스 설계 시 놓친 부분을 보완하는 기준으로 활용할 수 있다."]]},{"t":"② 기능 기반·구조 기반 커버리지","n":[["설명","기능 기반 커버리지와 구조 기반 커버리지 기능 기반 커버리지는 요구사항 명세서에 정의된 기능이 얼마나 테스트되었는지를 기준으로 하며, 구조 기반 커버리지는 화이트박스 테스트의 문장/분기/조건 커버리지처럼 코드의 내부 구조를 기준으로 측정한다. 프로젝트의 중요도와 특성에 따라 목표로 하는 커버리지 수준을 사전에 설정해 두는 것이 바람직하다. 안전이 중요한 시스템일수록 더 높은 수준의 커버리지(예: 분기 커버리지 100%)를 목표로 설정하는 경우가 많다."]]}]}]}]},{"t":"Ⅵ 인터페이스 설계와 구현","c":[{"t":"1. 인터페이스의 개념","c":[{"t":"(1) 인터페이스란","c":[{"t":"① 인터페이스: 시스템 간 접점·규약","n":[["설명","인터페이스의 정의 인터페이스는 서로 다른 시스템이나 모듈, 컴포넌트 간에 정보를 교환하기 위해 정의된 접점 또는 규약을 의미한다. 하나의 시스템에서 다른 시스템으로 데이터를 주고받거나 기능을 호출할 때 인터페이스를 통해 상호작용이 이루어진다. 인터페이스는 송신 시스템, 수신 시스템, 그리고 그 사이에서 데이터를 전달하는 연계 방식(중계 서버, 데이터베이스 링크, 오픈 API 등)으로 구성된다. 인터페이스 설계 시에는 송수신 데이터의 형식, 주기, 오류 처리 방식을 명확히 정의해야 한다."]]},{"t":"② 인터페이스 설계서 구성","n":[["설명","인터페이스 설계서의 구성 인터페이스 설계서는 송신 시스템과 수신 시스템 간에 교환되는 데이터 항목, 데이터 타입, 길이, 필수 여부 등을 상세히 기술한 문서이다. 송신 시스템 정보, 수신 시스템 정보, 연계 방식, 데이터 명세를 표 형태로 정리하여 개발자와 테스터가 참조할 수 있도록 한다. 대규모 시스템에서는 다수의 인터페이스가 존재하므로, 인터페이스 목록을 별도로 관리하여 각 인터페이스의 송수신 시스템, 연계 데이터, 연계 주기, 담당자 등을 한눈에 파악할 수 있도록 해야 한다."]]}]},{"t":"(2) EAI와 ESB","c":[{"t":"① EAI 기업 내 시스템 통합","n":[["설명","EAI(Enterprise Application Integration) EAI는 기업 내에서 운영되는 다양한 정보 시스템들을 상호 연동될 수 있도록 통합하는 솔루션이다. 각 시스템 간의 데이터 형식과 통신 방식이 달라도 이를 중계하여 원활하게 연계될 수 있도록 지원한다. ESB는 서비스 지향 아키텍처(SOA)를 지원하기 위한 미들웨어로, 여러 애플리케이션과 서비스 간의 메시지 라우팅, 데이터 변환, 프로토콜 변환 등을 버스(Bus) 형태의 공통 통신 채널을 통해 처리한다. EAI보다 더 유연하고 확장 가능한 통합 방식으로 평가받는다."]]},{"t":"② API 기능 호출 인터페이스(JSON·XML)","n":[["설명","API(Application Programming Interface) API는 애플리케이션이 제공하는 기능을 다른 프로그램에서 호출하여 사용할 수 있도록 정의한 인터페이스이다. 함수나 프로토콜의 집합 형태로 제공되며, 요청과 응답의 형식(주로 JSON이나 XML)이 명세되어 있다. 오픈 API는 누구나 사용할 수 있도록 공개된 API를 의미하며, 최근에는 HTTP 프로토콜의 메서드(GET, POST, PUT, DELETE)를 활용하여 자원을 표현하는 REST(Representational State Transfer) 방식의 API가 널리 사용되고 있다."]]}]}]}]},{"t":"Ⅶ 제품 소프트웨어 패키징","c":[{"t":"1. 제품 소프트웨어 패키징의 개념","c":[{"t":"(1) 패키징이란","c":[{"t":"① 패키징: 설치 가능한 형태로 배포","n":[["설명","제품 소프트웨어 패키징의 정의 제품 소프트웨어 패키징은 개발이 완료된 소프트웨어를 사용자가 설치하고 사용할 수 있는 형태로 묶어서 배포하는 작업을 의미한다. 단순히 파일을 압축하는 것이 아니라, 사용자 편의성을 고려한 설치 환경 구성까지 포함하는 활동이다. 패키징 시에는 다양한 사용자의 실행 환경(운영체제, 하드웨어 사양)을 고려해야 하며, 다양한 배포 방식(설치 파일, 웹 배포 등)을 고려한 패키징 형태를 지원해야 한다. 또한 사용자 입장에서 설치와 삭제, 재설치가 용이하도록 설계해야 한다."]]},{"t":"② 패키징 도구 기능·DRM","n":[["설명","패키징 도구의 기능 패키징 도구는 소스 코드를 실행 가능한 형태로 컴파일하고, 라이선스 관리와 저작권 보호를 위한 DRM(디지털 저작권 관리) 기능을 적용하며, 다양한 운영체제에 대한 배포용 설치 파일을 자동으로 생성해 주는 기능을 제공한다. DRM은 디지털 콘텐츠나 소프트웨어의 불법 복제와 무단 사용을 방지하기 위한 저작권 보호 기술이다. 암호화, 인증 등을 통해 정당한 사용자만 콘텐츠를 이용할 수 있도록 제한하며, 패키징 단계에서 함께 적용되는 경우가 많다."]]}]},{"t":"(2) 릴리즈 노트란","c":[{"t":"① 릴리즈 노트: 버전별 변경사항 안내","n":[["설명","릴리즈 노트의 개념 릴리즈 노트는 소프트웨어 제품의 배포 시 해당 버전에서 변경된 사항, 추가된 기능, 수정된 결함 등을 사용자에게 안내하기 위해 작성하는 문서이다. 사용자가 새 버전에서 무엇이 달라졌는지 빠르게 파악할 수 있도록 돕는다. 릴리즈 노트에는 일반적으로 헤더(제품명, 버전 번호, 릴리즈 날짜), 개요, 목적, 문제 요약, 재현 항목, 수정/ 개선 내용, 사용자 영향도, 기타 참고사항이 포함된다."]]},{"t":"② 릴리즈 노트 작성: 명확·간결","n":[["설명","명확하고 간결한 서술 릴리즈 노트는 개발자가 아닌 일반 사용자도 이해할 수 있도록 전문 용어를 최소화하고, 변경 사항을 간결하고 명확한 문장으로 작성해야 한다. 릴리즈 노트는 형상관리 도구에서 관리하는 버전 태그와 연계하여 작성함으로써, 특정 버전에서 어떤 변경이 있었는지 추적 가능하도록 관리하는 것이 바람직하다."]]}]}]}]},{"t":"Ⅷ 화면 설계 도구 심화","c":[{"t":"1. 프로토타이핑 도구","c":[{"t":"(1) 저충실도와 고충실도 프로토타입","c":[{"t":"① 저충실도 프로토타입: 스케치","n":[["설명","저충실도(Low-Fidelity) 프로토타입 저충실도 프로토타입은 종이와 펜을 이용한 스케치나 간단한 와이어프레임처럼, 색상이나 세부 디자인 없이 화면의 대략적인 구조와 흐름만을 빠르게 표현한 프로토타입이다. 제작 비용이 낮아 초기 아이디어 검증에 적합하다."],["실제 사례","고충실도 프로토타입은 실제 색상, 폰트, 인터랙션까지 반영하여 최종 제품과 거의 동일하게 구현한 프로토타입이다. 실제 사용자 테스트에서 보다 정확한 피드백을 얻을 수 있지만 제작에 상대적으로 많은 시간과 비용이 소요된다."]]},{"t":"② 대표 프로토타이핑 도구","n":[["설명","대표적인 프로토타이핑 도구"],["실제 사례","대표적인 프로토타이핑 도구로는 피그마(Figma), 스케치(Sketch), 어도비 XD(Adobe XD) 등이 있으며, 이러한 도구들은 화면 간의 인터랙션을 시뮬레이션하여 실제 앱처럼 클릭해 볼 수 있는 기능을 제공한다."]]}]},{"t":"(2) 사용성 테스트의 수행 방법","c":[{"t":"① 실험실 기반 사용성 테스트","n":[["설명","실험실 기반 사용성 테스트 실험실 기반 사용성 테스트는 통제된 환경에서 사용자에게 특정 과업(Task)을 수행하도록 요청하고, 그 과정을 관찰하며 문제점을 기록하는 방식이다. 사용자의 표정, 시선, 발화 내용까지 상세히 관찰할 수 있다."],["실제 사례","원격 사용성 테스트는 사용자가 자신의 실제 환경에서 화면 녹화 도구를 이용해 과업을 수행하는 모습을 기록하여 분석하는 방식으로, 지리적 제약 없이 다양한 사용자의 피드백을 수집할 수 있다는 장점이 있다."]]},{"t":"② 아이트래킹(Eye Tracking)","n":[["설명","아이트래킹(Eye Tracking)"],["실제 사례","아이트래킹은 사용자의 시선이 화면의 어느 부분에 얼마나 오래 머무는지를 추적하는 기술로, 사용자가 실제로 화면의 어떤 요소에 주목하는지를 객관적인 데이터로 파악할 수 있게 해준다."]]}]}]}]},{"t":"Ⅸ 모바일 애플리케이션 플랫폼과 배포","c":[{"t":"1. 네이티브 앱과 하이브리드 앱","c":[{"t":"(1) 네이티브 앱(Native App)","c":[{"t":"① 네이티브 앱: 플랫폼 고유 언어","n":[["설명","네이티브 앱의 개념 네이티브 앱은 특정 운영체제(안드로이드, iOS)에 맞추어 해당 플랫폼의 고유 언어(자바/코틀린, 스위프트 등)로 개발된 애플리케이션이다. 기기의 하드웨어 기능을 최대한 활용할 수 있고 성능이 뛰어나다는 장점이 있다. 네이티브 앱은 플랫폼별로 별도의 코드를 작성해야 하므로, 여러 플랫폼을 모두 지원하려면 개발 비용과 유지보수 부담이 커진다는 단점이 있다."]]},{"t":"② 하이브리드 앱: 웹 기술 래핑","n":[["설명","하이브리드 앱(Hybrid App) 하이브리드 앱은 HTML, CSS, JavaScript와 같은 웹 기술로 개발한 후, 이를 네이티브 앱 형태로 감싸서 (Wrapping) 배포하는 방식이다. 하나의 코드로 여러 플랫폼에 배포할 수 있어 개발 비용을 절감할 수 있다. 크로스플랫폼 앱은 리액트 네이티브(React Native), 플러터(Flutter)와 같은 프레임워크를 이용하여 하나의 코드베이스로 안드로이드와 iOS 앱을 모두 개발하는 방식으로, 네이티브 앱에 가까운 성능을 제공하면서도 개발 효율성을 높일 수 있다."]]}]},{"t":"(2) 앱 스토어 배포 절차","c":[{"t":"① 배포 전 메타데이터·서명(Sign ing)","n":[["설명","배포 전 준비사항 앱을 스토어에 배포하기 전에는 아이콘, 스크린샷, 앱 설명, 개인정보처리방침 등의 메타데이터를 준비해야하며, 서명(Signing) 절차를 거쳐 앱의 무결성을 보장해야 한다. 구글 플레이 스토어나 애플 앱스토어에 앱을 등록하면, 각 플랫폼의 심사 정책(콘텐츠 적절성, 보안, 개인정보처리 등)에 따라 검토를 거친 후 사용자에게 배포된다. 심사에서 정책 위반 사항이 발견되면 반려될 수 있다."]]},{"t":"② 버전 체계 Major·Minor· Patch","n":[["설명","버전 관리 정책 모바일 애플리케이션은 주요 변경(Major), 기능 추가(Minor), 결함 수정(Patch)의 버전 번호 체계를 사용하여 배포 이력을 관리하는 것이 일반적이다. 중대한 보안 결함이 발견된 경우에는 사용자에게 강제로 최신 버전 업데이트를 요구할 수 있으며, 새로운 기능 배포 시에는 일부 사용자에게만 먼저 배포하는 점진적 배포(Staged Rollout) 방식을 활용하여 위험을 줄이기도 한다."]]}]}]}]},{"t":"Ⅹ 테스트 자동화 도구의 유형","c":[{"t":"1. UI 테스트 자동화 도구","c":[{"t":"(1) 웹 UI 테스트 자동화","c":[{"t":"① 셀레니움(Selenium) 웹 UI 자동화","n":[["설명","셀레니움(Selenium) 셀레니움은 웹 브라우저를 자동으로 제어하여 UI 테스트를 자동화하는 대표적인 오픈소스 도구이다. 다양한 브라우저와 프로그래밍 언어를 지원하여 여러 환경에서의 크로스 브라우징 테스트를 자동화할 수 있다. 웹 UI 테스트 자동화는 화면 요소의 위치나 이름이 자주 변경되는 경우 테스트 스크립트를 매번 수정해야 하는 유지보수 부담이 크다는 한계가 있다. 이를 완화하기 위해 페이지 객체 모델(Page Object Model)과 같은 설계 패턴이 활용된다."]]},{"t":"② 앱피움(Appium) 모바일 앱 자동화","n":[["설명","앱피움(Appium) 앱피움은 안드로이드와 iOS 앱의 UI를 자동으로 테스트할 수 있게 해주는 오픈소스 자동화 도구이다. 하나의 API로 여러 플랫폼의 모바일 앱을 테스트할 수 있어 크로스플랫폼 테스트 자동화에 널리 활용된다."],["실제 사례","모바일 테스트 자동화 시에는 다양한 기기의 화면 크기와 해상도, 운영체제 버전의 차이를 고려해야하며, 실제 기기와 에뮬레이터를 함께 활용하여 테스트의 신뢰성을 높이는 것이 바람직하다."]]}]},{"t":"(2) API 테스트의 개념","c":[{"t":"① API 테스트: 화면 없이 요청·응답 검증","n":[["설명","API 테스트란 API 테스트는 화면 없이 API 자체의 요청과 응답을 검증하는 테스트로, UI 테스트에 비해 실행 속도가 빠르고 안정적이라는 장점이 있다. 요청 파라미터, 응답 코드, 응답 데이터의 정확성을 검증한다. API 테스트는 UI가 아직 완성되지 않은 개발 초기 단계에서도 백엔드 로직을 미리 검증할 수 있으며, UI 변경에 영향을 받지 않으므로 테스트의 안정성이 높다."]]},{"t":"② 포스트맨(Postman)·Rest Assured","n":[["설명","포스트맨(Postman) 포스트맨은 API 요청을 손쉽게 구성하고 전송하여 응답을 확인할 수 있는 대표적인 API 테스트 도구이다. 테스트 스크립트를 작성하여 응답 값에 대한 자동 검증도 수행할 수 있다. RestAssured는 자바 기반의 API 테스트 자동화 라이브러리로, 코드 형태로 API 테스트 케이스를 작성하여 CI/CD 파이프라인에 손쉽게 통합할 수 있다. Ⅺ. 인터페이스 보안과 오류 처리"]]}]}]}]}]},{"t":"제4절 디버깅과 결함 관리","c":[{"t":"Ⅰ 디버깅(Debugging)의 개념과 기법","c":[{"t":"1. 디버깅의 개념","c":[{"t":"(1) 디버깅이란","c":[{"t":"① 디버깅: 결함 위치 찾아 수정","n":[["설명","디버깅의 정의 디버깅은 소프트웨어에서 발생하는 오류의 원인이 되는 코드상의 결함을 찾아내어 이를 수정하는 작업을 의미한다. 테스트를 통해 오류(실패)가 발견되었을 때, 그 실패를 일으킨 근본 원인인 결함의 정확한 위치를 찾아 제거하는 활동이 디버깅이다. 테스트가 결함의 존재 여부를 발견하는 활동이라면, 디버깅은 발견된 결함의 정확한 원인과 위치를 찾아 수정하는 활동이라는 점에서 서로 명확히 구분된다. 테스트는 \"무엇이 잘못되었는가\"를 밝히고, 디버깅은 \"왜, 어디에서 잘못되었는가\"를 밝혀 해결한다."]]},{"t":"② 오류 재현→원인 분석→수정","n":[["설명","오류 재현과 원인 분석 디버깅은 먼저 테스트에서 발견된 오류 현상을 동일한 조건에서 재현하는 것으로 시작한다. 오류가 재현되면 관련된 코드 영역을 추적하여 실패를 유발한 근본 원인을 분석한다. 원인이 파악되면 해당 코드를 수정하고, 수정된 코드가 원래의 오류를 해결했는지 뿐만 아니라 새로운 결함을 유발하지 않았는지 회귀 테스트를 통해 재검증하는 과정을 거친다."]]}]},{"t":"(2) 기초적인 디버깅 기법","c":[{"t":"① 출력문(Print)·중단점 디버깅","n":[["설명","출력문(Print) 디버깅 출력문 디버깅은 코드 중간중간에 변수의 값이나 실행 흐름을 출력하는 명령문을 삽입하여, 프로그램이 실행되는 동안 내부 상태를 확인하는 가장 기초적이고 직관적인 디버깅 기법이다. 중단점 디버깅은 통합 개발 환경(IDE)에 내장된 디버거를 이용하여 특정 코드 라인에 중단점을 설정하고, 프로그램 실행을 그 지점에서 멈춘 뒤 변수 값과 호출 스택을 직접 조사하는 기법이다."]]},{"t":"② 역추적(Backtracking)· 원인 제거법","n":[["설명","역추적(Backtracking)과 원인 제거법 역추적은 오류가 발견된 위치로부터 소스 코드를 거슬러 올라가면서 원인이 되는 부분을 찾는 기법이며, 원인 제거법은 오류의 원인이 될 만한 요소들을 하나씩 제거해 나가면서 원인을 좁혀가는 기법이다. 두 기법 모두 오류의 범위가 비교적 좁을 때 효과적으로 사용된다. 통합 개발 환경에서 제공하는 디버거는 단계별 실행(Step Over/Step Into), 변수 감시(Watch), 호출 스택 확인 등의 기능을 제공하여, 복잡한 로직에서도 문제의 원인을 체계적으로 추적할 수 있게 해 준다."]]}]}]}]},{"t":"Ⅱ 결함 관련 용어와 판단 기준","c":[{"t":"1. 오류·결함·실패의 구분","c":[{"t":"(1) Error, Fault, Defect","c":[{"t":"① 에러(Error): 사람의 실수","n":[["설명","에러(Error) 에러는 개발자나 사용자가 프로그램을 잘못 이해하거나 실수함으로써 발생하는 사람의 실수 그 자체를 의미한다. 즉, 결함이 발생하게 된 근본 원인이 되는 인간의 실수를 가리킨다."],["실제 사례","결함은 에러로 인해 소프트웨어 내부에 남게 된 잘못된 부분(코드, 명세, 문서 등)을 의미한다. Fault와 Defect는 실무에서 거의 같은 의미로 혼용되며, 프로그램이 의도한 대로 동작하지 않게 만드는 내부 적인 문제점을 지칭한다."]]},{"t":"② 실패(Failure)","n":[["설명","실패(Failure)"],["실제 사례","실패는 결함이 실제로 실행되어 사용자나 외부에서 관찰 가능한 형태로 잘못된 결과나 동작이 겉으로 드러난 상태를 의미한다. 결함이 존재하더라도 특정 조건에서 실행되지 않으면 실패로 이어지지 않을 수 있다."]]}]},{"t":"(2) 결함으로 판단하는 대표적 기준","c":[{"t":"① 명세서-실제 결과 불일치","n":[["설명","명세서와 실제 결과의 불일치 소프트웨어가 명세서에서 요구하는 기능을 수행하지 않거나, 명세서에 없더라도 소프트웨어가 당연히 수행해야 할 기능을 수행하지 않는 경우 결함으로 판단한다. 소프트웨어가 수행하지 않아야 할 기능을 수행하거나, 명세서에 명시되어 있지 않지만 소프트웨어 최종 사용자가 당연히 예상하는 목표를 만족시키지 못하는 경우에도 결함으로 판단한다."]]},{"t":"② 테스터 판단 기준: 사용 곤란·속도 저하","n":[["설명","테스터가 보기에 이해하기 어렵거나 기능 수행이 어려운 경우 소프트웨어 테스터가 보기에 문제가 있다고 판단되거나, 사용하기 어렵고 다루기 힘들며, 예측된 기능이 정확하게 수행되지 못하는 경우, 실행 속도가 느린 경우 등도 넓은 의미에서 결함 판단 기준에 포함된다."],["실제 사례","\"모든 테스트 케이스는 예상되는 출력 결과를 사전에 미리 정의해야 한다\", \"프로그래머는 자신이 작성한 프로그램에 대한 테스트를 수행하지 않는 것이 원칙이다\", \"발견된 오류에 대해서는 반드시 그 원인을 끝까지 추적해야 한다\"와 같은 테스트 격언은 오랜 실무 경험을 통해 축적된 테스트 수행의 원칙을 담고 있다."]]}]}]}]},{"t":"Ⅲ 결함 관리 프로세스","c":[{"t":"1. 결함 관리의 개념과 필요성","c":[{"t":"(1) 결함 관리란","c":[{"t":"① 결함 관리: 등록·추적·관리대장","n":[["설명","결함 관리의 정의 결함 관리는 소프트웨어 테스트 과정에서 발견된 결함을 체계적으로 등록, 추적, 관리하여 결함이 누락 없이 해결되고 재발하지 않도록 하는 활동이다. 결함 관리대장을 활용하여 결함 상태를 지속적으로 추적, 관리해야한다. 프로젝트 규모가 커질수록 발견되는 결함의 수도 방대해지므로, 체계적인 관리 없이는 어떤 결함이 수정되었고 어떤 결함이 아직 미해결 상태인지 파악하기가 매우 어렵다. 결함 관리를 통해 품질 지표를 정량적으로 측정하고 프로젝트의 위험도를 조기에 파악할 수 있다."]]},{"t":"② 결함 관리 계획·결함 기록","n":[["설명","결함 관리 계획과 결함 기록 결함 관리 계획 및 준비 단계에서는 결함 관리 정책과 기준을 수립하며, 이후 테스트를 수행하면서 발견된 결함을 결함 관리 대장에 상세히 기록한다. 결함 기록에는 발견 일자, 발견자, 재현 절차, 심각도 등이 포함되어야 한다."],["실제 사례","기록된 결함은 담당자 검토를 거쳐 실제 결함 여부와 우선순위가 결정되고, 개발자에게 할당되어 수정이 진행된다. 수정이 완료되면 테스터가 재테스트를 수행하여 결함이 실제로 해결되었는지 확인하고 결함을 종료 처리한다."]]}]},{"t":"(2) 결함 상태의 기본 흐름","c":[{"t":"① 접수(Open)·검토(Review ed)","n":[["설명","접수(Open)와 검토(Reviewed)"],["실제 사례","결함이 처음 발견되어 등록되면 접수(Open) 상태가 되며, 담당자가 해당 결함이 실제 결함인지, 중복 결함인지 등을 검토하는 검토(Reviewed) 상태로 전환된다."]]},{"t":"② 종료(Closed)·재오픈(Reo pened)","n":[["설명","종료(Closed)와 재오픈(Reopened) 조치가 완료된 결함을 테스터가 재테스트하여 정상적으로 해결되었음이 확인되면 종료(Closed) 상태가 된다. 만약 수정 후에도 동일한 문제가 재발하면 재오픈(Reopened) 상태로 되돌려 다시 수정 절차를 밟는다. 결함이지만 이번 릴리스에서는 수정하지 않기로 결정된 경우 보류(Deferred) 상태로 관리하며, 결함인지 여부가 불분명하여 추가 확인이 필요한 경우 확인 요청(Clarified) 상태를 거쳐 담당자 간 소통을 통해 처리 방향을 결정한다."]]}]}]}]},{"t":"Ⅳ 결함의 분류와 우선순위","c":[{"t":"1. 결함의 분류","c":[{"t":"(1) 발생 원인에 따른 분류","c":[{"t":"① 시스템·기능·GUI 결함","n":[["설명","시스템 결함과 기능 결함 시스템 결함은 시스템 자체의 구조나 아키텍처, 성능, 자원 관리와 관련된 결함을 의미하며, 기능 결함은 명세된 개별 기능이 요구사항대로 동작하지 않는 결함을 의미한다. GUI 결함은 사용자 인터페이스의 디자인, 배치, 반응성 등 화면과 관련된 결함이며, 문서 결함은 사용자 매뉴 얼이나 요구사항 명세서와 같은 문서상의 오류나 불일치를 의미한다."]]},{"t":"② 심각도 상·중·하 3등급","n":[["설명","심각도의 등급 구분 결함의 심각도는 일반적으로 상(High), 중(Medium), 하(Low)의 세 등급으로 구분한다. 상(High)은 시스템 전체가 마비되거나 핵심 기능이 완전히 동작하지 않는 치명적인 결함, 중(Medium)은 특정 기능에는 영향을 주지만 시스템 전체에는 영향이 적은 결함, 하(Low)는 화면 디자인의 사소한 오류처럼 기능에 큰 영향이 없는 결함을 의미한다. 심각도를 정확히 판단해야 제한된 개발 자원을 가장 시급한 결함부터 우선적으로 투입할 수 있다. 심각도가 잘못 평가되면 치명적인 결함이 방치되거나, 반대로 사소한 결함에 과도한 자원이 투입되는 비효율이 발생할수 있다."]]}]},{"t":"(2) 우선순위의 개념","c":[{"t":"① 우선순위: 처리 순서, 심각도와 별개","n":[["설명","우선순위란 우선순위는 발견된 결함을 어떤 순서로 처리할 것인지를 나타내는 척도로, 심각도와는 별개의 개념이다. 심각도가 낮더라도 사용자가 매우 자주 접하는 화면의 결함이라면 우선순위가 높게 설정될 수 있다."],["쉬운 예","예를 들어, 시스템 초기 화면의 로고 색상이 틀린 것은 심각도는 낮지만 모든 사용자가 즉시 확인하므로 우선순위가 높게 책정될 수 있는 반면, 사용 빈도가 매우 낮은 관리자 전용 기능의 치명적 오류는 심각도는 높지만 우선순위가 상대적으로 낮게 책정될 수 있다."]]},{"t":"② 비즈니스 영향도","n":[["설명","비즈니스 영향도"],["쉬운 예","결함이 비즈니스에 미치는 영향, 예를 들어 매출이나 고객 신뢰도에 미치는 영향이 큰 결함일수록 우선순위를 높게 책정해야 한다."]]}]}]}]},{"t":"Ⅴ 결함 관리 도구","c":[{"t":"1. 결함 관리 도구의 개념","c":[{"t":"(1) 결함 관리 도구란","c":[{"t":"① 결함 관리 도구: 생명주기 관리","n":[["설명","결함 관리 도구의 정의 결함 관리 도구는 소프트웨어 테스트 과정에서 발견된 결함을 체계적으로 기록, 추적, 관리할 수 있도록 지원하는 소프트웨어이다. 결함의 등록부터 종료까지 전체 생명주기를 온라인 상에서 관리할 수 있게 해 준다. 결함 관리 도구는 결함 등록, 담당자 할당, 상태 변경 이력 추적, 첨부파일(스크린샷, 로그) 관리, 통계 리포트 생성 등의 기능을 제공하여, 여러 이해관계자가 결함 처리 현황을 실시간으로 공유할 수 있게 한다."]]},{"t":"② Mantis 결함 특화·Trac 위키 결합","n":[["설명","Mantis와 Trac Mantis(멘티스)는 결함 관리에 특화된 오픈소스 도구로, 결함의 등록부터 처리 결과의 통계 확인까지 웹 기반으로 지원한다. Trac(트랙)은 결함 관리와 함께 프로젝트의 위키(Wiki) 기능과 형상관리 기능을 결합하여 제공하는 오픈소스 도구이다. Redmine(레드마인)은 결함 관리뿐 아니라 프로젝트 전반의 일정 관리, 게시판, 위키 기능을 함께 제공하는 오픈소스 프로젝트 관리 도구이다. Bugzilla(버그질라)는 대규모 오픈소스 프로젝트에서 널리 사용되는 결함 추적 시스템으로, 결함의 상태와 이력을 세밀하게 관리할 수 있는 기능을 제공한다."]]}]},{"t":"(2) 도구 선정 기준","c":[{"t":"① 도구 선정: 프로젝트 규모·협업","n":[["설명","프로젝트 규모와 협업 방식 프로젝트의 규모, 팀원 수, 분산 여부 등을 고려하여 적절한 도구를 선정해야 한다. 소규모 팀에서는 간단한 결함 관리 도구로도 충분하지만, 다수의 협력사가 참여하는 대규모 프로젝트에서는 권한 관리와 보고서 기능이 강력한 도구가 필요하다. 형상관리 도구(Git 등)나 프로젝트 관리 도구와의 연동이 용이한 결함 관리 도구를 선택하면, 결함 수정 커밋과 결함 티켓을 자동으로 연결하여 추적성을 높일 수 있다."]]},{"t":"② 품질 가시성 대시보드","n":[["설명","품질 가시성 확보 결함 관리 도구를 통해 프로젝트 전체의 결함 발생 추이와 처리 현황을 대시보드 형태로 파악할 수 있어, 프로젝트 관리자가 품질 상태를 객관적인 지표로 파악할 수 있다. 과거에 발생했던 결함의 이력을 데이터로 축적해 두면, 유사한 결함의 재발을 방지하기 위한 코드 리뷰 기준이나 테스트 케이스 보완에 활용할 수 있다."]]}]}]}]},{"t":"Ⅵ 애플리케이션 성능 개선과 모니터링","c":[{"t":"1. 애플리케이션 성능 분석","c":[{"t":"(1) 성능 분석의 개념","c":[{"t":"① 성능 분석 개념","n":[["설명","성능 분석이란"],["실제 사례","애플리케이션 성능 분석은 소프트웨어가 실제 운영 환경에서 요구되는 응답 시간, 처리량, 자원 사용률 등을 만족하는지 측정하고 개선점을 찾는 활동이다. 성능 결함은 사용자가 직접 체감하는 문제이므로 배포전 반드시 점검해야 한다."]]},{"t":"② 비효율 알고리즘·인덱스 미활용 쿼리","n":[["설명","비효율적인 알고리즘과 쿼리 불필요하게 복잡한 반복문이나 비효율적인 알고리즘, 인덱스를 활용하지 못하는 데이터베이스 쿼리는 대표적인 성능 저하 원인이다. 데이터 양이 적을 때는 문제가 드러나지 않다가 운영 데이터가 누적되면서 성능 문제가 뒤늦게 발견되는 경우가 많다. 메모리를 할당한 후 반환하지 않는 메모리 누수(Memory Leak)나, 특정 자원에 요청이 집중되어 병목(Bottleneck) 현상이 발생하면 시스템 전체의 성능이 급격히 저하될 수 있다."]]}]},{"t":"(2) 모니터링의 개념","c":[{"t":"① 모니터링: 실시간 장애 감지·APM","n":[["설명","애플리케이션 모니터링이란 애플리케이션 모니터링은 운영 중인 시스템의 상태를 실시간으로 관찰하여 장애나 성능 저하를 조기에 감지하는 활동이다. 로그 수집, 자원 사용률 추적, 알림 설정 등을 통해 문제 발생 시 신속하게 대응할 수 있도록 지원한다. APM은 애플리케이션의 성능을 실시간으로 모니터링하고 분석하는 도구 및 기법을 의미한다. 트랜잭션 단위로 응답 시간을 추적하고, 병목 구간을 시각적으로 표시하여 성능 문제의 원인을 신속하게 파악할 수 있도록 돕는다."]]},{"t":"② 로그 관리: 장애 원인 추적","n":[["설명","로그(Log) 관리 로그는 시스템에서 발생하는 이벤트와 오류를 기록한 데이터로, 장애 발생 시 원인을 추적하는 가장 중요한 단서가 된다. 로그를 체계적으로 수집, 저장, 검색할 수 있도록 로그 관리 시스템을 구축하는 것이 중요하다. 장애가 발생하면 장애 인지, 영향 범위 파악, 임시 조치(우회 방안 적용), 근본 원인 분석, 재발 방지 대책 수립의 순서로 대응하는 것이 일반적이다. 장애 대응 이력을 문서화해 두면 유사 장애 재발 시 신속한 대응이 가능하다."]]}]}]}]},{"t":"Ⅶ 단위 테스트 자동화 프레임워크 실습","c":[{"t":"1. JUnit을 활용한 단위 테스트","c":[{"t":"(1) JUnit의 기본 구조","c":[{"t":"① JUnit @Test 테스트 메소드 예제","n":[["설명","테스트 클래스와 테스트 메소드\nimport org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;\nclass CalculatorTest {\n      @Test\n      void additionTest() {\n           Calculator calc = new Calculator();\n           assertEquals(5, calc.add(2, 3));\n      }\n}\n    JUnit에서는 @Test 애노테이션이 붙은 메소드가 하나의 테스트 케이스로 인식된다. assertEquals와 같은\n    단언(Assertion) 메소드를 사용하여 기대값과 실제값을 비교하며, 값이 일치하지 않으면 테스트가 실패로 처\n    리된다.\n    JUnit은 assertEquals(같음 확인), assertTrue/assertFalse(참/거짓 확인),\n    assertNull/assertNotNull(널 여부 확인), assertThrows(예외 발생 확인) 등 다양한 단언 메소드를 제공\n    하여 여러 형태의 검증을 수행할 수 있게 한다."]]},{"t":"② @BeforeEach 초기화·@AfterEach 정리","n":[["설명","@BeforeEach와 @AfterEach @BeforeEach 애노테이션이 붙은 메소드는 각 테스트 메소드가 실행되기 전에 매번 호출되어 테스트 환경을 초기화하는 역할을 하며, @AfterEach는 각 테스트 메소드 실행 후에 자원을 정리하는 역할을 한다. @BeforeAll과 @AfterAll은 클래스 내의 모든 테스트가 시작되기 전과 모든 테스트가 종료된 후 단 한 번만 실행되는 정적(static) 메소드에 사용되며, 데이터베이스 연결과 같이 비용이 큰 자원의 준비와 해제에 활용된다."]]}]},{"t":"(2) TDD(Test Driven Development)의 개념","c":[{"t":"① TDD 테스트 주도 개발","n":[["설명","TDD란"],["실제 사례","TDD는 실제 코드를 작성하기에 앞서 테스트 코드를 먼저 작성하고, 이 테스트를 통과시키기 위한 최소한의 코드를 구현한 뒤, 이를 리팩토링하는 순서로 개발을 진행하는 개발 방법론이다."]]},{"t":"② TDD 장점: 회귀 테스트 용이","n":[["설명","TDD의 장점 TDD를 적용하면 모든 코드에 대응하는 테스트 코드가 자연스럽게 확보되어 회귀 테스트가 용이해지고, 테스트를 먼저 고민하는 과정에서 설계의 결함을 조기에 발견할 수 있다는 장점이 있다. TDD는 초기에는 개발 속도가 느려지는 것처럼 느껴질 수 있으나, 장기적으로는 결함 수정 비용을 크게 줄여 준다. 다만 테스트 작성 자체에 과도한 시간을 투입하지 않도록 테스트의 범위와 우선순위를 적절히 조절하는 것이 중요하다."]]}]}]}]},{"t":"Ⅷ 회귀 테스트와 형상관리 연계","c":[{"t":"1. 회귀 테스트(Regression Test)","c":[{"t":"(1) 회귀 테스트의 개념","c":[{"t":"① 회귀 테스트: 수정 후 기존 기능 확인","n":[["설명","회귀 테스트란 회귀 테스트는 소스 코드를 수정한 이후, 기존에 정상적으로 동작하던 기능이 새로운 변경으로 인해 손상되지 않았는지를 확인하는 테스트이다. 결함을 수정하거나 새로운 기능을 추가할 때마다 반복적으로 수행되어야한다. 소프트웨어는 지속적으로 수정되고 확장되므로, 회귀 테스트 없이 배포하면 이전에는 없던 새로운 결함(회귀 결함)이 발생할 위험이 매우 크다. 특히 여러 모듈이 서로 의존하는 대규모 시스템일수록 회귀 테스트의 중요성이 커진다."]]},{"t":"② 회귀 테스트 자동화·테스트 스위트","n":[["설명","회귀 테스트 자동화의 필요성 회귀 테스트는 동일한 테스트 케이스를 반복적으로 수행해야 하므로, 수작업으로 진행하면 시간과 비용이 크게 소요된다. 이 때문에 회귀 테스트는 테스트 자동화의 가장 대표적인 적용 대상으로 꼽힌다. 회귀 테스트 스위트(Suite)는 프로젝트가 진행됨에 따라 지속적으로 새로운 테스트 케이스가 추가되므로, 중복되거나 더 이상 의미 없는 테스트 케이스를 주기적으로 정리하여 실행 시간을 관리하는 것이 중요하다."]]}]},{"t":"(2) 결함과 커밋(Commit)의 연계","c":[{"t":"① 결함 ID 커밋 연계·핫픽스 브랜치","n":[["설명","결함 ID와 커밋 메시지 연계 결함을 수정한 커밋의 메시지에 결함 관리 도구의 결함 ID를 함께 기록하면, 어떤 코드 변경이 어떤 결함을 해결하기 위한 것인지 추적할 수 있어 이력 관리가 용이해진다. 결함 수정 작업은 별도의 핫픽스(Hotfix) 브랜치를 만들어 진행한 뒤, 검증이 완료되면 운영 브랜치에 병합하는 방식으로 관리하여, 진행 중인 다른 개발 작업에 영향을 주지 않도록 하는 것이 일반적이다."]]},{"t":"② 자동 결함 티켓·품질 게이트","n":[["설명","자동화된 결함 리포트 생성 CI/CD 파이프라인에서 자동화 테스트가 실패하면, 실패 로그와 함께 결함 관리 도구에 자동으로 티켓을 생성해 주는 연동 체계를 구축하면 결함 등록 누락을 방지할 수 있다. 품질 게이트는 코드 커버리지, 심각한 결함 수, 정적 분석 결과 등 사전에 정의된 품질 기준을 충족하지 못하면 다음 배포 단계로 진행되지 못하도록 자동으로 차단하는 장치이다."]]}]}]}]},{"t":"Ⅸ 테스트 결과 분석과 종료 판정","c":[{"t":"1. 테스트 결과 분석","c":[{"t":"(1) 테스트 결과의 정량적 분석","c":[{"t":"① 결함 밀도: 1,000라인당 결함 수","n":[["설명","결함 밀도(Defect Density) 결함 밀도는 코드의 특정 크기(예: 1,000라인)당 발견된 결함의 수를 의미하는 지표로, 모듈별 결함 밀도를 비교하면 품질이 취약한 영역을 파악하는 데 활용할 수 있다. 시간에 따른 결함 발견 건수와 해결 건수의 추세를 그래프로 나타내면, 테스트가 진행됨에 따라 결함이 안정적으로 감소하고 있는지, 아니면 새로운 결함이 계속 증가하고 있는지를 파악할 수 있다."]]},{"t":"② 테스트 종료 기준 사전 정의","n":[["설명","종료 기준의 설정 테스트 종료 기준은 계획된 테스트 케이스의 실행 완료율, 목표 커버리지 달성 여부, 심각도가 높은 결함의 해결 여부 등을 종합적으로 고려하여 사전에 정의해 두어야 한다. 모든 결함을 완벽히 제거하고 배포하는 것은 현실적으로 불가능하므로, 심각도가 낮은 잔존 결함에 대해서는 리스크를 감수하고 배포한 뒤 이후 버전에서 수정하는 것으로 결정하는 경우도 많다."]]}]},{"t":"(2) 테스트 산출물의 종류","c":[{"t":"① 사전 산출물·사후 산출물","n":[["설명","테스트 계획서와 테스트 케이스 테스트 활동의 대표적인 산출물로는 테스트 계획서, 테스트 케이스 명세서, 테스트 시나리오가 있으며, 이들은 테스트를 수행하기 전에 준비되어야 하는 사전 산출물이다. 테스트를 수행한 이후에는 테스트 결과보고서와 결함관리대장이 산출물로 작성되며, 이는 프로젝트의 품질 이력을 증명하는 근거 자료로 활용된다."]]},{"t":"② 산출물 형상관리 버전 관리","n":[["설명","산출물 버전 관리 테스트 산출물은 프로젝트가 진행됨에 따라 지속적으로 갱신되므로, 형상관리 도구를 통해 버전을 관리하여 특정 시점의 산출물을 언제든지 확인할 수 있도록 해야 한다. 테스트 산출물은 프로젝트 이해관계자들이 함께 열람해야 하는 경우가 많으므로, 공유 저장소에 체계적으로 보관하고 문서별 접근 권한을 적절히 설정하여 관리하는 것이 바람직하다."]]}]}]}]},{"t":"Ⅹ 디버깅 도구와 로깅 전략","c":[{"t":"1. 통합 개발 환경의 디버깅 도구","c":[{"t":"(1) 디버거의 핵심 기능","c":[{"t":"① Step Over·Step Into·조건부 중단점","n":[["설명","단계별 실행(Stepping) 단계별 실행은 프로그램을 한 줄씩(Step Over) 또는 함수 내부로 들어가며(Step Into) 실행하여, 각 시점의 변수 상태와 실행 흐름을 세밀하게 관찰할 수 있게 해주는 디버거의 핵심 기능이다. 조건부 중단점은 특정 조건(예: 변수 값이 100 이상일 때)이 만족될 때만 프로그램 실행을 멈추도록 설정하는 기능으로, 반복문 안에서 특정 상황에서만 발생하는 결함을 효율적으로 추적할 수 있게 해준다."]]},{"t":"② 호출 스택(Call Stack)·변수 감시","n":[["설명","호출 스택(Call Stack) 호출 스택은 현재 실행 중인 함수가 어떤 함수로부터 호출되었는지를 순서대로 보여주는 정보이다. 오류가 발생한 지점까지 어떤 경로로 함수가 호출되어 왔는지를 파악하는 데 필수적이다. 변수 감시 기능은 특정 변수의 값이 프로그램 실행 도중 어떻게 변화하는지를 실시간으로 추적하여 보여주는 기능으로, 예상치 못한 값의 변화가 발생하는 시점을 정확히 찾아낼 수 있다."]]}]},{"t":"(2) 로그 레벨(Log Level)","c":[{"t":"① 로그 레벨 종류","n":[["설명","로그 레벨의 종류"],["실제 사례","로그는 일반적으로 DEBUG(개발 시 상세 정보), INFO(일반적인 실행 정보), WARN(잠재적 문제) , ERROR(실제 오류), FATAL(치명적 오류)과 같은 레벨로 구분하여 기록한다."]]},{"t":"② 구조화된 로깅 JSON 형식","n":[["설명","구조화된 로깅(Structured Logging) 구조화된 로깅은 로그 메시지를 단순 텍스트가 아닌 JSON과 같은 정형화된 형식으로 기록하는 방식이다. 이를 통해 로그 분석 도구가 로그의 특정 필드(사용자 ID, 요청 시간 등)를 손쉽게 검색하고 집계할 수 있다. 여러 서버에서 발생하는 로그를 하나의 중앙 저장소로 모아 검색하고 시각화하는 로그 분석 시스템(ELK 스택 등)을 구축하면, 분산된 시스템에서 발생하는 문제를 신속하게 추적할 수 있다. Ⅺ. 결함 예방 활동과 코딩 표준"]]}]}]}]}]}],"k":"필기 4과목"},{"n":5,"t":"프로그래밍 언어 활용","c":[{"t":"제1절 알고리즘(Algorithm)의 이해","c":[{"t":"Ⅰ 알고리즘의 개념과 본질","c":[{"t":"1. 알고리즘의 정의","c":[{"t":"(1) 넓은 의미와 좁은 의미의 알고리즘","c":[{"t":"① 프로그램=자료구조+알고리즘","n":[["쉬운 예","예를 들어 학생 30명의 성적을 처리하는 프로그램을 만든다고 가정해 보겠습니다. 성적 데이터를 담아 두는 배열이 '자료 구조'라면, 그 배열을 처음부터 끝까지 순회하면서 합계를 구하고 평균을 계산하는 절차가 바로 '알고리즘'입니다. 두 가지가 모두 있어야 비로소 \"성적 처리 프로그램\"이라는 완성품이 나오게 됩니다."],["설명","넓은 의미의 알고리즘 넓은 의미에서 알고리즘은 자료 구조(Data Structure)와 함께 프로그램을 구성하는 핵심 요소를 말합니다. 프로그램이라는 것은 결국 \"무엇을(자료 구조) 어떻게(알고리즘) 처리할 것인가\"의 결합체이기 때문에, 스위 스의 컴퓨터 과학자 니클라우스 비르트(Niklaus Wirth)는 \"프로그램 = 자료 구조 + 알고리즘\"이라는 유명한 공식을 제시하기도 하였습니다. 즉, 아무리 좋은 자료가 준비되어 있어도 그것을 처리하는 절차(알고리즘)가 없다면 프로그램은 완성될 수 없습니다."]]},{"t":"② 문제 해결 절차·방법","n":[["시험 포인트","좁은 의미에서 알고리즘은 어떤 문제에 대한 답을 찾는 해법(            )을 의미합니다. 우리가 일상에서 \" 라면 끓이는 순서\", \"지하철 환승 경로 찾기\"처럼 어떤 목표에 도달하기 위해 밟아야 하는 단계들을 정리해 놓은 것이 모두 좁은 의미의 알고리즘에 해당합니다. 시험에서는 주로 이 좁은 의미, 즉 \"문제 해결을 위한 일련의 절차나 방법을 공식화한 형태\"라는 정의가 출제됩니다."],["설명","좁은 의미의 알고리즘"]]}]},{"t":"(2) 프로그램 개발 과정에서의 알고리즘의 위치","c":[{"t":"① 설계(계획) 단계 포함","n":[["쉬운 예","알고리즘은 프로그램 작성 과정 중 설계(계획) 단계에 포함됩니다. 프로그램 개발은 일반적으로 \"요구사항 분석 → 설계 → 구현(코딩) → 테스트 → 유지보수\"의 순서로 진행되는데, 알고리즘을 세우는 일은 코드를 입력하기 전, 즉 설계 단계에서 이루어집니다. 건축에 비유하면 실제로 벽돌을 쌓기(코딩) 전에 설계도(알고 리즘)를 그리는 것과 같습니다."],["설명","설계(계획) 단계에 포함"]]},{"t":"② 계산 실행의 단계적 절차","n":[["설명","계산을 실행하기 위한 단계적 절차 알고리즘은 문제 해결을 위한 일련의 절차나 방법이며, 계산을 실행하기 위한 단계적 절차이기도 합니다. \"단계적\"이라는 말이 중요한데, 각 단계는 명확하게 구분되어야 하고 순서가 있어야 한다는 뜻입니다. 정보처리기능사 실기에서는 이 알고리즘을 포괄적으로 \"공식화한 형태나 모형\"으로 표현한다고 이해하면 됩니다."]]}]}]},{"t":"2. 알고리즘의 5가지 특성(조건)","c":[{"t":"(1) 5가지 특성의 개요","c":[{"t":"① 5가지 특성 암기 필요성","n":[["시험 포인트","알고리즘이 알고리즘으로 인정받기 위해서는 반드시 다섯 가지 조건을 만족해야 합니다. 이 다섯 가지는 입력(Input), 출력(Output), 명확성(Definiteness), 유한성(Finiteness), 유효성(Effectiveness)입 니다. 아직까지 정보처리기능사 실기에서 알고리즘 이론을 직접 묻는 문제는 출제되지 않았지만, 필기와 마찬가지로 문제가 변형되어 출제될 가능성이 충분하므로 다섯 가지 특성은 반드시 모두 암기해 두어야 합니다."],["설명","특성 암기의 필요성"]]},{"t":"② 입·출·명·유·유 암기 요령","n":[["시험 포인트","\"입·출·명·유·유\"로 앞 글자를 따서 암기하면 편리합니다. 입력과 출력은 데이터의 흐름에 관한 조건이고, 명확성·유한성·유효성은 알고리즘 자체의 품질에 관한 조건이라고 구분해서 기억하면 헷갈리지 않습니다."],["설명","암기 요령"]]}]},{"t":"(2) 각 특성의 상세 내용","c":[{"t":"① 입력 0개 이상","n":[["쉬운 예","외부에서 제공되는 자료가 0개 이상 있어야 한다는 조건입니다. 여기서 주의할 점은 \"1개 이상\"이 아니라 \"0개 이상\"이라는 점입니다. 즉, 입력이 하나도 없는 알고리즘도 존재할 수 있습니다. 예를 들어 \"1부터 100까지의 합을 출력하라\"는 알고리즘은 외부 입력 없이도 동작하므로 입력이 0개인 경우에 해당합니다."],["설명","입력(Input)"]]},{"t":"② 출력 1개 이상","n":[["시험 포인트","적어도 1개 이상의 결과가 나와야 한다는 조건입니다. 입력과 달리 출력은 반드시 하나 이상 존재해야 합니다. 결과가 아무것도 나오지 않는 절차는 문제를 해결했다고 볼 수 없기 때문입니다. \"입력은 0개 이상, 출력은 1개 이상\"이라는 개수의 차이가 시험에서 자주 비교되는 포인트입니다."],["설명","출력(Output)"]]},{"t":"③ 명확성 명령어 의미 명확","n":[["쉬운 예","각 명령어의 의미가 명확하여야 한다는 조건입니다. 알고리즘의 각 단계는 누가 보더라도 같은 의미로 해석되어야 하며, 모호한 표현이 있어서는 안 됩니다. 예를 들어 \"적당히 소금을 넣는다\"는 요리법은 사람마다 다르게 해석되므로 명확성을 만족하지 못하지만, \"소금 5g을 넣는다\"는 명확성을 만족합니다."],["설명","명확성(명백성, Definiteness)"]]},{"t":"④ 유한성 반드시 종료","n":[["설명","유한성(Finiteness) 정해진 단계를 지나면 반드시 종료되어야 한다는 조건입니다. 무한히 반복되기만 하고 끝나지 않는 절차는 알고리즘이 아닙니다. 프로그래밍에서 종료 조건이 없는 무한 루프(Infinite Loop)를 작성하면 이 유한성을 위반하게 되는 것입니다."]]},{"t":"⑤ 유효성 실행 가능성","n":[["쉬운 예","모든 명령은 실행 가능한 연산들이어야 한다는 조건입니다. 아무리 절차가 명확해도 실제로 수행할 수없는 명령이라면 의미가 없습니다. 예를 들어 \"0으로 나눈 값을 구하라\"는 명령은 수학적으로 실행이 불가능하므로 유효성을 만족하지 못합니다."],["설명","유효성(Effectiveness)"]]}]},{"t":"(3) 특성 정리표","n":[["설명","(3) 특성 정리표\n특성                            핵심 키워드                       암기 포인트\n입력(Input)                     외부 제공 자료 0개 이상               0개도 가능(없어도 됨)\n출력(Output)                    결과 1개 이상                     반드시 1개 이상 존재\n명확성(Definiteness)             명령어의 의미가 명확                  모호함이 없어야 함\n유한성(Finiteness)               정해진 단계 후 반드시 종료              무한 반복 금지\n유효성(Effectiveness)            모든 명령은 실행 가능                 수행 불가능한 연산 금지"]]}]}]},{"t":"Ⅱ 알고리즘의 표현과 설계","c":[{"t":"1. 알고리즘의 표현 방법","c":[{"t":"(1) 대표적인 표현 방법의 종류","c":[{"t":"① 자연어 표현","n":[["쉬운 예","사람이 쓰는 일상 언어(한국어, 영어 등)로 알고리즘을 서술하는 방법입니다. 누구나 쉽게 읽을 수 있다는 장점이 있지만, 표현이 길어지고 사람마다 해석이 달라질 수 있어 명확성이 떨어진다는 단점이 있습니다. 예를 들어 \"두 수를 입력받아 큰 수를 출력한다. 만약 두 수가 같으면 '같음'을 출력한다.\"와 같이 서술하는 방식입니다."],["설명","자연어(Natural Language)에 의한 표현"]]},{"t":"② 순서도(Flowchart) 표현","n":[["시험 포인트","미리 약속된 기호와 도형을 이용하여 알고리즘의 논리적 절차, 흐름, 연산 등을 시각적으로 표현하는 방법입니다. 한눈에 흐름을 파악할 수 있어 교육용·문서화용으로 널리 쓰이며, 정보처리기능사 실기에서 알고리즘 문제가 출제될 때 가장 중요한 표현 수단입니다. 순서도는 제2절에서 상세히 다룹니다."],["설명","순서도(Flowchart)에 의한 표현"]]},{"t":"③ 의사코드(Pseudo Code)","n":[["쉬운 예","실제 프로그래밍 언어는 아니지만 프로그래밍 언어와 유사한 형식으로 알고리즘을 기술하는 방법입니다. 특정 언어의 문법에 얽매이지 않으면서도 자연어보다 훨씬 명확하게 절차를 표현할 수 있습니다. 예를 들어 \" IF score >= 60 THEN PRINT '합격' ELSE PRINT '불합격'\"과 같이 작성합니다."],["설명","의사코드(Pseudo Code)에 의한 표현"]]},{"t":"④ 프로그래밍 언어 표현","n":[["실제 사례","C, Java, Python 등 실제 프로그래밍 언어로 알고리즘을 직접 구현하는 방법입니다. 컴퓨터에서 바로 실행할 수 있다는 장점이 있으나, 해당 언어를 모르는 사람은 이해하기 어렵습니다. 정보처리기능사 실기의 프로그래밍 문제는 결국 이 단계까지 표현된 알고리즘을 읽고 결과를 예측하는 능력을 평가하는 것입니다."],["설명","프로그래밍 언어에 의한 표현"]]}]},{"t":"(2) 표현 방법 선택의 기준","c":[{"t":"① 대상 독자별 선택","n":[["실제 사례","알고리즘을 처음 배우는 사람이나 비전공자에게 설명할 때는 자연어나 순서도가 적합하고, 개발자 간의 의사소통에는 의사코드가, 실제 실행이 목적일 때는 프로그래밍 언어가 적합합니다. 상황에 따라 적절한 표현 방법을 선택하는 것이 중요합니다."],["설명","대상 독자에 따른 선택"]]},{"t":"② 시험 관점 순서도·코드","n":[["시험 포인트","정보처리기능사 실기에서는 순서도 기호의 의미를 묻거나, 순서도로 표현된 알고리즘의 실행 결과를 계산하는 유형이 출제된 바 있습니다. 자격증이 개편된 이후 첫 실기 시험에서 알고리즘 문제가 출제되었고, 최근 약 2년간 출제되지 않았지만 다시 출제될 가능성이 충분하므로 순서도의 도형과 연산 기호를 모두 파악해 두는 것이 좋습니다."],["설명","시험 관점에서의 선택"]]}]}]},{"t":"2. 알고리즘 설계의 기초","c":[{"t":"(1) 좋은 알고리즘의 조건","c":[{"t":"① 정확성·효율성(시간·공간)","n":[["설명","정확성과 효율성 좋은 알고리즘은 첫째로 정확해야 합니다. 어떤 입력이 들어와도 항상 올바른 결과를 내야 하며, 특수한 경우(예: 입력이 0이거나 음수인 경우)에도 오류 없이 동작해야 합니다. 둘째로 효율적이어야 합니다. 같은 문제를 해결하더라도 더 적은 시간(시간 복잡도)과 더 적은 메모리(공간 복잡도)를 사용하는 알고리즘이 좋은 알고리즘입니다."]]},{"t":"② 단순성·가독성","n":[["실제 사례","알고리즘은 가능한 한 단순하고 이해하기 쉬워야 합니다. 지나치게 복잡한 알고리즘은 구현 과정에서 오류가 발생하기 쉽고, 다른 사람이 유지보수하기도 어렵습니다. 실무에서는 \"약간 느리더라도 읽기 쉬운 코드\"가 선호되는 경우도 많습니다."],["설명","단순성과 가독성"]]}]},{"t":"(2) 알고리즘 설계의 실전 예시","c":[{"t":"① SWAP temp 3단계 교환","n":[["설명","예시 1: 두 변수의 값 교환(SWAP) 알고리즘 변수 a에 3, 변수 b에 5가 들어 있을 때 두 값을 서로 바꾸는 알고리즘을 생각해 보겠습니다. 단순히 \"a = b, b = a\"라고 하면 a에 5가 들어가는 순간 원래 a의 값 3이 사라져 버려 두 변수 모두 5가 되는 오류가 발생합 니다. 그래서 임시 변수 temp를 하나 두고 \"temp = a → a = b → b = temp\"의 세 단계로 처리해야 합니다. 이처럼 알고리즘 설계에서는 값이 덮어써져 사라지는 순서까지 고려해야 하며, 이 교환 알고리즘은 정렬 알고리즘의 기초가 되므로 실기에서도 매우 자주 등장합니다."]]},{"t":"② 1~N 합계 sum 누적","n":[["시험 포인트","【시험 포인트】 알고리즘의 5가지 특성(입력·출력·명확성·유한성·유효성)은 언제든 출제될 수 있는 기본 암기 사항입니다. 특히 \"입력은 0개 이상, 출력은 1개 이상\"의 차이를 정확히 구분해야 합니다."],["설명","예시 2: 1부터 N까지의 합 알고리즘 1부터 10까지의 합을 구하는 알고리즘은 \"합계 변수 sum을 0으로 초기화 → 카운터 변수 i를 1로 초기화 → sum에 i를 더함 → i를 1 증가 → i가 10 이하이면 다시 반복, 초과하면 종료 후 sum 출력\"의 절차로 설계할수 있습니다. 여기에는 알고리즘의 5가지 특성이 모두 들어 있습니다. 입력은 없고(0개 이상 허용), 출력은 sum 하나이며(1개 이상), 각 단계가 명확하고(명확성), i가 10을 넘으면 반드시 종료되며(유한성), 모든 연산이 실행 가능(유효성)합니다."]]}]}]}]}]},{"t":"제2절 순서도(Flowchart)","c":[{"t":"Ⅰ 순서도의 개념과 기호","c":[{"t":"1. 순서도의 개념","c":[{"t":"(1) 순서도의 정의","c":[{"t":"① 기호·도형 시각적 표현","n":[["설명","시각적 표현 도구로서의 순서도 순서도(Flowchart)는 알고리즘을 표현하는 여러 방식 중 하나로서, 미리 약속된 기호와 도형을 이용해 논리적 절차, 흐름, 연산 등을 시각적으로 표현한 것입니다. 글로 쓰인 절차보다 도형으로 그려진 절차가 훨씬 직관적으로 이해되기 때문에, 프로그램의 전체 흐름을 설명하거나 문서화할 때 널리 사용됩니다."]]},{"t":"② 위→아래·좌→우 흐름","n":[["설명","순서도의 흐름 방향 순서도는 기본적으로 위에서 아래로, 또는 왼쪽에서 오른쪽으로 흐릅니다. 이 흐름 방향은 순서도 문제를 풀때 매우 중요한데, 위에서 내려오는 값을 기준으로 아래쪽의 연산이 수행되기 때문입니다. 흐름의 방향은 흐름선(화살표)으로 표시하며, 화살표를 따라가면서 값의 변화를 추적하는 것이 순서도 문제 풀이의 기본입니다."]]}]},{"t":"(2) 순서도 사용의 장점과 단점","c":[{"t":"① 흐름 파악·언어 독립·디버깅","n":[["설명","장점 첫째, 프로그램의 논리적 흐름을 한눈에 파악할 수 있습니다. 둘째, 특정 프로그래밍 언어에 종속되지 않으므로 언어를 모르는 사람과도 의사소통이 가능합니다. 셋째, 오류 발견과 수정(디버깅)이 쉬워집니다. 코딩 전에 순서도로 논리를 검증하면 코딩 후에 발견될 오류를 미리 잡을 수 있습니다."]]},{"t":"② 복잡화·작성 시간 소요","n":[["설명","단점 첫째, 프로그램이 커지고 복잡해지면 순서도 역시 지나치게 복잡해져 오히려 이해하기 어려워집니다. 둘째, 순서도를 그리고 수정하는 데 시간이 많이 소요됩니다. 셋째, 반복이나 재귀와 같은 복잡한 구조는 도형만으로 표현하기 어려운 경우가 있습니다."]]}]}]},{"t":"2. 순서도의 주요 도형(기호)","c":[{"t":"(1) 기본 도형의 종류와 역할","c":[{"t":"① 단말 타원 시작·끝","n":[["설명","단말(Terminal) - 타원(둥근 모서리) 기호 프로그램의 시작(Start)과 끝(End)을 의미하는 도형입니다. 순서도의 맨 위와 맨 아래에 위치하며, 모든 순서도는 반드시 시작 단말에서 출발하여 종료 단말에서 끝나야 합니다. 알고리즘의 유한성(반드시 종료)을 도형으로 보장하는 역할이라고 이해할 수 있습니다."]]},{"t":"② 준비 육각형 초기값","n":[["쉬운 예","변수의 초기값 설정 등 준비 작업을 나타내는 도형입니다. 예를 들어 합계를 구하는 순서도에서 \"sum = 0, i = 1\"과 같이 초기값을 설정하는 부분에 육각형 기호를 사용합니다. 초기값 설정은 순서도 문제에서 가장 많이 묻는 부분이므로 이 도형이 나오면 특히 주의 깊게 봐야 합니다."],["설명","준비(Preparation) - 육각형 기호"]]},{"t":"③ 입출력 평행사변형","n":[["설명","입출력(Input/Output) - 평행사변형 기호 자료의 입력과 출력을 담당하는 도형입니다. 키보드로 값을 입력받거나 결과를 내보내는 동작을 평행사변형으로 표현합니다. 일반적인 입출력은 평행사변형을 사용하며, 특별히 서류(문서) 출력은 아래쪽이 물결 모양으로 된 별도의 도형을 사용합니다."]]},{"t":"④ 처리 직사각형 연산","n":[["설명","처리(Process) - 직사각형 기호 각종 연산과 데이터 처리를 나타내는 도형입니다. \"sum = sum + i\"와 같은 계산식, 값의 대입 등 실질적인 처리 작업이 모두 직사각형 안에 표현됩니다. 순서도에서 가장 많이 등장하는 기본 도형입니다."]]},{"t":"⑤ 판단 마름모 조건 분기","n":[["설명","판단(Decision) - 마름모 기호 조건을 판단하여 흐름을 분기시키는 도형입니다. 마름모 안에 조건식을 쓰고, 조건이 참(Yes)일 때와 거짓 (No)일 때 서로 다른 방향으로 흐름이 갈라집니다. 프로그래밍 언어의 if문에 해당하며, 반복문의 종료 조건 판단에도 사용됩니다."]]},{"t":"⑥ 반복(Loop) 기호","n":[["쉬운 예","일정 구간을 반복 실행함을 나타내는 도형입니다. 위쪽 공간에 \"어디부터 어디까지 몇씩 증가\"하는 형식, 즉 for문의 계산 형식(초기값, 조건, 증감)을 기재합니다. 예를 들어 \"i = 1, 10, 1\"이라고 쓰여 있다면 i가 1부터 10까지 1씩 증가하며 반복한다는 의미입니다."],["설명","반복(Loop) - 반복 기호"]]},{"t":"⑦ 흐름선 화살표·연결자 원","n":[["설명","흐름선(Flow Line)과 연결자(Connector) 흐름선(화살표)은 도형과 도형 사이의 처리 순서와 흐름 방향을 나타냅니다. 연결자(작은 원)는 순서도가 길어져 한 페이지에 다 그릴 수 없거나 흐름선이 교차할 때, 떨어져 있는 두 지점을 연결하기 위해 사용합니다."]]}]},{"t":"(2) 도형 정리표","n":[["설명","(2) 도형 정리표\n도형 이름                       모양           역할\n단말(Terminal)                타원           프로그램의 시작과 끝\n준비(Preparation)             육각형          변수 초기값 설정 등 준비 작업\n입출력(I/O)                    평행사변형        자료의 입력과 출력\n처리(Process)                 직사각형         연산, 대입 등 데이터 처리\n판단(Decision)                마름모          조건 판단과 분기\n반복(Loop)                    반복 기호        초기값·조건·증감에 의한 반복\n문서 출력                       물결 모양        서류(문서) 형태의 출력\n흐름선                         화살표          처리 순서와 흐름 방향"]]}]}]},{"t":"Ⅱ 순서도의 연산 기호","c":[{"t":"1. 산술 연산 기호","c":[{"t":"(1) 기본 산술 연산","c":[{"t":"① 사칙연산 ×와 * 차이","n":[["설명","사칙연산 기호 순서도의 산술 연산은 프로그래밍 연산과 비슷하면서도 조금 다릅니다. 더하기(+), 빼기(-), 곱하기(×), 나누 기(/)까지는 프로그래밍과 거의 동일하게 사용합니다. 곱하기의 경우 순서도에서는 수학 기호 ×를 쓰기도 하고, 프로그래밍에서는 별표(*)를 사용한다는 표기상의 차이가 있습니다."]]},{"t":"② 나머지 MOD(순서도 전용)","n":[["쉬운 예","나머지 연산에서 중요한 차이가 나타납니다. 프로그래밍에서는 %(퍼센트) 기호로 나머지를 표시하지만, 알고리즘 순서도에서는 MOD라는 기호를 함께 사용합니다. 예를 들어 7을 4로 나눈 나머지는 순서도에서 \" 7 MOD 4\"로도, \"7 % 4\"로도 표현할 수 있으며 둘 다 결과는 3입니다. 반드시 기억할 것은 MOD는 알고리즘( 순서도)에서만 쓰이고 실제 프로그래밍 언어에서는 쓰이지 않는다는 점입니다."],["설명","나머지 연산 - MOD"]]},{"t":"③ 거듭제곱 ^ 기호","n":[["시험 포인트","거듭제곱은 순서도에서 위 첨자 형태(예: 2³)나 ↑ 기호로 표현하지만, 프로그래밍에서는 언어에 따라 다르게 표현합니다. 이러한 표기의 차이점도 시험에서 비교 포인트가 될 수 있으므로 함께 알아 두어야 합니다."],["설명","거듭제곱 기호"]]}]},{"t":"(2) 산술 연산 비교표","n":[["설명","(2) 산술 연산 비교표\n연산             순서도(알고리즘)               프로그래밍\n더하기            +                       +\n빼기             -                       -\n곱하기            ×                       *\n나누기(몫)         /                       /(정수끼리는 몫)\n나머지            MOD 또는 %                %만 사용(MOD 사용 불가)"]]}]},{"t":"2. 관계(비교) 연산 기호","c":[{"t":"(1) 크기 비교 기호","c":[{"t":"① ≥·≤ vs >=·<=","n":[["설명","대소 비교 순서도의 관계 연산에는 크다(>), 크거나 같다·이상(≥), 작다·미만(<), 작거나 같다·이하(≤)가 있습니다. 순서도에서는 수학 기호인 ≥, ≤를 그대로 사용할 수 있지만, 프로그래밍에서는 >=, <=처럼 두 문자를 조합하여 표현한다는 차이가 있습니다."]]},{"t":"② 같다 = vs == 대입 구분","n":[["쉬운 예","순서도와 프로그래밍의 가장 중요한 차이 중 하나입니다. 순서도에서는 등호(=) 하나가 \"같다\"(비교)와 \"대입\"의 두 가지 의미로 함께 쓰입니다. 예를 들어 순서도에서 \"a = 4\"는 문맥에 따라 \"a에 4를 대입한다\" 는 의미가 됩니다. 반면 프로그래밍에서는 대입은 = 하나, 비교(같다)는 == 두 개로 명확히 구분합니다. 이 차이를 모르면 순서도 문제와 프로그래밍 문제를 오갈 때 혼동이 생기므로 반드시 구분해서 기억해야 합니다."],["설명","같다와 대입의 구분"]]},{"t":"③ ≠·<>·!= 표현","n":[["설명","같지 않다(다르다)의 표현 \"같지 않다\"는 순서도에서 세 가지 방식으로 표현될 수 있습니다. ≠ 기호, <>(작지도 크지도 않다) 기호, 그리고 프로그래밍식 표현인 != 입니다. 세 가지 모두 순서도에서 쓰일 수 있지만, 프로그래밍에서는 <> 기호를 쓰지 않고 !=만 사용한다는 점을 기억해야 합니다."]]}]},{"t":"(2) 관계 연산 비교표","n":[["설명","(2) 관계 연산 비교표\n의미                    순서도                            프로그래밍\n크다(초과)                >                              >\n크거나 같다(이상)            ≥                              >=\n작다(미만)                <                              <\n작거나 같다(이하)            ≤                              <=\n같다                    =                              ==\n같지 않다                 ≠, <>, !=                      !=(<>는 사용 안 함)\n대입                    = (같다와 겸용)                     ="]]}]}]},{"t":"Ⅲ 순서도의 기초 공식","c":[{"t":"1. 변수·상수와 수의 증감","c":[{"t":"(1) 변수와 상수","c":[{"t":"① 변수 변하는 값 저장","n":[["쉬운 예","변수는 고정되어 있지 않은 값, 또는 어떤 값을 주기억장치에 기억하기 위해 사용하는 공간입니다. \"고정되어 있지 않다\"는 말은 그 값이 언제든지 변경될 수 있다는 뜻입니다. 우리가 임의로 알파벳이나 숫자를 조합해서 만드는 모든 저장 공간(a, sum, cnt 등)이 변수입니다. 예를 들어 \"a = 10\"은 \"변수 a에 정수 10을 입력 (대입)하라\"는 의미입니다."],["설명","변수(Variable)의 개념"]]},{"t":"② 상수 고정·불변 값","n":[["설명","상수(Constant)의 개념 상수는 고정되어 있는 값, 또는 이미 지정되어 있어 변하지 않는 값입니다. 수식 안의 숫자 10, 3.14 같은 값들이 상수이며, 프로그램 실행 중에 그 값이 바뀌지 않습니다. NCS 기준에서는 순서도 안에서의 표현을 기준으로 \"고정된 값 또는 지정되어 변하지 않는 값\"으로 정의합니다."]]}]},{"t":"(2) 수의 증가와 감소","c":[{"t":"① i=i+1 증가·감소","n":[["쉬운 예","변수 i의 초기값이 설정되어 있는 경우에는 \"i = i + 1\"로 i를 연속적으로 증가시키거나 \"i = i - 1\"로 연속적으로 감소시킬 수 있습니다. 예를 들어 i = 0으로 초기화된 상태에서 i = i + 1을 실행하면 i는 1이 되고, 다시 실행하면 2가 됩니다. 이때 등호는 \"같다\"가 아니라 \"오른쪽 계산 결과를 왼쪽에 대입한다\"는 의미입니다."],["설명","초기값이 설정되어 있는 경우"]]},{"t":"② NULL 초기값 없음 누적 불가","n":[["설명","초기값이 설정되어 있지 않은 경우 - NULL의 개념 초기값이 설정되어 있지 않은 변수는 그 자체를 누적하여 증가시킬 수 없습니다. 값이 아무것도 없는 상태, 즉 0도 아니고 값을 알 수 없는 상태를 널(NULL) 또는 널 값(Null Value)이라고 합니다. NULL인 변수에 i = i+ 1을 수행하면 \"알 수 없는 값 + 1\"이 되어 정상적인 결과를 얻을 수 없습니다. 순서도 문제에서 가장 많이 묻는 부분이 바로 이 초기값의 유무이므로, 순서도를 볼 때는 항상 위쪽(먼저 실행되는 부분)에서 각 변수가 어떤 초기값을 갖는지부터 확인해야 합니다."]]},{"t":"③ 고정수-변수 감소 패턴","n":[["쉬운 예","초기값이 설정된 변수를 이용하면 고정된 숫자에서 연속적으로 빼는 것도 가능합니다. 예를 들어 i = 0인 상태에서 \"i = i + 1 → k = 10 - i\"를 반복하면, 첫 번째 반복에서 i는 1이 되고 k는 10 - 1 = 9가 됩니다. 두번째 반복에서 i는 2가 되고 k는 10 - 2 = 8이 됩니다. 이렇게 고정 숫자에서 증가하는 변수를 빼는 패턴은 프로그래밍에서도 자주 등장하므로 계산 과정을 손으로 직접 따라가며 연습해 두는 것이 좋습니다."],["설명","고정된 수에서 변수를 이용해 빼는 경우"]]}]}]},{"t":"2. 합계·평균·부호변경 공식","c":[{"t":"(1) 합의 공식(누적)","c":[{"t":"① sum=sum+i 누적","n":[["쉬운 예","합의 공식은 \"합계 = 합계 + 수\"의 형태입니다. 예를 들어 sum = sum + i는 합계 변수 sum에 i 값을"],["설명","기본 형태"]]},{"t":"② 합계 초기값 0 확인","n":[["설명","초기값에 대한 주의점 합계 변수의 초기값은 기본적으로 0으로 설정합니다. NULL 상태에서는 누적이 불가능하기 때문입니다. 다만 항상 0으로 고정되는 것은 아니며, 문제에 따라 0이 아닌 다른 기본값에서 시작하는 경우도 알고리즘 문제에서 자주 나오므로 초기값이 얼마로 주어졌는지를 반드시 확인해야 합니다."]]}]},{"t":"(2) 평균의 공식","c":[{"t":"① avg=sum÷cnt","n":[["설명","기본 형태 평균의 공식은 \"평균(avg) = 합계(sum) ÷ 개수(cnt)\"입니다. 엑셀의 AVERAGE 함수가 자동으로 해 주는 계산을 순서도에서는 합계와 개수를 각각 구한 뒤 나누는 방식으로 직접 표현합니다."]]},{"t":"② 점수 5개 평균 80","n":[["설명","실전 적용 예시 학생 5명의 점수 70, 80, 90, 60, 100의 평균을 구한다면, 먼저 sum = 0으로 초기화한 뒤 다섯 점수를 차례로 누적하여 sum = 400을 만들고, 개수 cnt = 5로 나누어 avg = 80을 얻습니다. 순서도에서는 입력 도형(평행사변형)으로 점수를 받고, 처리 도형(직사각형)에서 누적하며, 반복이 끝난 후 마지막에 나눗셈을 수행하는 구조가 됩니다."]]}]},{"t":"(3) 부호변경의 공식","c":[{"t":"① 부호×(-1) 교대 패턴","n":[["설명","-1 곱하기 패턴 4, -5, 6, -7처럼 부호가 플러스와 마이너스로 번갈아 나타나는 패턴을 표현할 때는 부호 변수에 -1을 곱하는 방법을 사용합니다. 양수에 -1을 곱하면 음수가 되고, 음수에 -1을 곱하면 다시 양수가 되므로, 반복할 때마다 \"부호 = 부호 × (-1)\"을 수행하면 부호가 계속 번갈아 바뀝니다."]]},{"t":"② 부호변경 교대합 예시","n":[["쉬운 예","예를 들어 \"1 - 2 + 3 - 4 + 5\"와 같은 교대 급수의 합을 구하는 순서도에서는 부호 변수 s = 1로 초기화한 후, 매 반복마다 \"sum = sum + (i × s) → s = s × (-1)\"을 수행합니다. 첫 반복에서 +1, 둘째 반복에서 -2, 셋째 반복에서 +3이 누적되는 방식입니다. 이 패턴은 순서도와 프로그래밍 양쪽에서 모두 자주 사용됩니다."],["설명","실전 적용 예시"]]}]}]},{"t":"3. 몫·나머지와 배열","c":[{"t":"(1) 몫과 나머지","c":[{"t":"① 몫 소수점 버림 5/2=2","n":[["설명","몫 연산 몫은 \"값 / 수\"로 표현하며 결과값을 정수형으로 표현합니다. 4 / 2 = 2이고, 5 / 2는 수학적으로 2.5이지만몫 연산에서는 소수점 이하를 버리고 2가 됩니다. 즉 5를 2로 나누면 몫이 2이고 나머지가 1인데, 몫 연산은 위의 2만 취한다는 의미입니다. \"소수점 이하를 버린다 = 정수로 표현한다\"로 기억해야 하며, C 언어에서 정수끼리의 / 연산이 이와 동일하게 동작합니다."]]},{"t":"② 나머지 %·MOD 짝홀 판별","n":[["설명","나머지 연산 나머지는 \"값 % 수\" 또는 \"값 MOD 수\"로 표현합니다. 7 % 3 = 1이고, 5 MOD 2 = 1입니다. 앞서 설명한 대로 MOD는 알고리즘 순서도에서만 쓰이고 프로그래밍에서는 %만 사용합니다. 나머지 연산은 짝수·홀수 판별(i % 2 == 0이면 짝수), 배수 판별(i % 3 == 0이면 3의 배수) 등에 매우 자주 활용되므로 실전 예시와 함께 기억해 두어야 합니다."]]}]},{"t":"(2) 배열(Array)","c":[{"t":"① 같은 자료형 연속 저장","n":[["쉬운 예","배열은 번호에 대응하는 데이터들로 이루어진 자료 구조로, 변수를 연속적으로 저장하기 위해 확보한 메모리 공간입니다. 즉 어떤 데이터 값을 넣기 위한 빈 공간들이 연속으로 이어져 있는 형태입니다. 서랍장에 비유하면, 변수 하나가 서랍 한 칸이라면 배열은 번호표가 붙은 서랍 여러 칸이 연달아 붙어 있는 서랍장 전체입니다."],["설명","배열의 개념"]]},{"t":"② 인덱스로 요소 접근","n":[["시험 포인트","배열 a[5]를 선언하면 a[0], a[1], a[2], a[3], a[4]의 다섯 개 주소로 이루어집니다. 여기서 주의할 점은 5칸을 선언했을 때 인덱스가 1부터 5까지가 아니라 0부터 4까지라는 것입니다. 프로그래밍에서 배열의 시작 인덱스는 항상 0입니다."],["설명","배열의 주소(인덱스)"]]},{"t":"③ 순서도 1부터 vs 코드 0부터","n":[["시험 포인트","프로그래밍에서는 배열의 주소값이 반드시 0부터 시작하지만, 순서도(알고리즘)에서는 0 또는 1부터 시작하는 문제가 간간이 출제됩니다. 즉 순서도 문제에서는 \"배열이 반드시 0부터 시작하지 않을 수도 있다\"는 점을 염두에 두고, 문제에 제시된 시작 번호를 확인한 후 풀이해야 합니다."],["시험 포인트","【시험 포인트】 순서도에서는 ① MOD 기호(프로그래밍에서는 % 만 사용) ② = 가 대입과 같다를 겸용(프로그래밍은 =와 == 구분) ③ 배열 인덱스가 0 또는 1에서 시작 가능(프로그래밍은 0 고정)이라는 세가지 차이가 핵심 출제 포인트입니다."],["설명","순서도와 프로그래밍의 차이"]]}]}]}]}]},{"t":"제3절 프로그래밍 언어와 컴퓨터 시스템의 기초","c":[{"t":"Ⅰ 프로그래밍 언어의 개념","c":[{"t":"1. 프로그래밍 언어와 프로그램","c":[{"t":"(1) 기본 정의","c":[{"t":"① 컴퓨터에 일 시키는 언어","n":[["설명","프로그래밍 언어의 정의 프로그래밍 언어는 컴퓨터 시스템을 동작시키기 위한 프로그램을 작성하는 언어입니다. 사람과 사람이 의사소통할 때 한국어나 영어를 사용하듯, 사람이 컴퓨터에게 일을 시킬 때 사용하는 약속된 언어가 프로그래밍 언어입니다. C, Java, Python 등이 대표적입니다."]]},{"t":"② 프로그램=명령어 조합","n":[["설명","프로그램의 정의 프로그램은 다소 단순해 보이는 명령어들의 조합으로 구성됩니다. 정보처리기능사 실기(NCS 기준)에서는 프로그램을 \"명령어들의 조합\"이라고 표현합니다. 개별 명령어 하나하나는 단순하지만, 이것들이 수천, 수만개 조합되어 워드프로세서나 게임 같은 복잡한 프로그램이 만들어집니다."]]}]},{"t":"(2) 비트와 바이트","c":[{"t":"① 비트 Binary Digit 최소단위","n":[["설명","비트(Bit)의 개념 프로그램을 이루는 명령어 조합은 비트(Bit)라고 불리는 0과 1의 값으로 작성·변환되어 컴퓨터가 이해할 수있게 됩니다. 비트는 Binary Digit의 약칭으로, 정보의 최소 단위입니다. 비트는 0과 1로만 구성되며 2진법을 이용합니다. 컴퓨터 내부의 모든 데이터(문자, 그림, 소리)는 결국 비트의 나열로 저장됩니다."]]},{"t":"② 1Byte=8bit","n":[["시험 포인트","비트 하나만으로는 표현할 수 있는 정보가 0과 1 두 가지뿐이므로, 사람이 알아볼 수 있는 문자 자료를 표현하기 위한 최소 단위로 바이트(Byte)가 필요합니다. 1바이트는 8비트입니다. 8개의 비트로는 2의 8 제곱, 즉 256가지 상태를 표현할 수 있어 영문자·숫자·기호 등을 나타내기에 충분합니다. \"1바이트 = 8비트\"는 이후 시프트 연산이나 자료형 크기 문제의 기초가 되므로 반드시 암기해야 합니다."],["설명","바이트(Byte)의 개념"]]},{"t":"③ KB→MB→GB→TB→PB→EB","n":[["설명","저장 용량의 단위 바이트가 모여 더 큰 저장 용량 단위를 이룹니다. 대략 1,000개(정확히는 1,024개)가 모일 때마다 단위가 올라가며, 바이트(B) → 킬로바이트(KB) → 메가바이트(MB) → 기가바이트(GB) → 테라바이트(TB) → 페타바이트(PB) → 엑사바이트(EB)의 순서입니다. 이 단위들은 자료 처리보다는 저장 용량을 표현할 때 사용됩니다."]]}]}]},{"t":"2. 컴퓨터 시스템의 구조","c":[{"t":"(1) 컴퓨터의 기본 동작","c":[{"t":"① CPU 처리·메모리 저장","n":[["설명","처리와 저장 컴퓨터는 전달받은 0과 1의 값들을 정해진 순서대로 실행하며, 그 과정에서 처리(Process)와 저장(Store) 등을 수행합니다. 프로그램 실행 및 데이터 처리는 중앙처리장치(CPU: Central Processing Unit)에서 수행하고, 저장은 기억장치(Memory)에서 수행합니다."]]},{"t":"② CPU=ALU+제어장치+레지스터","n":[["설명","중앙처리장치(CPU)의 구성 중앙처리장치는 사람의 두뇌에 해당하는 장치로, 연산장치(ALU), 제어장치(Control Unit), 레지스터 (Register) 등으로 구성됩니다. 연산장치는 산술·논리 연산을 수행하고, 제어장치는 명령어를 해석하여 각 장치에 동작을 지시하며, 레지스터는 CPU 내부의 초고속 임시 기억 공간입니다."]]}]},{"t":"(2) 버스와 명령 실행 사이클","c":[{"t":"① 버스 장치 간 데이터 통로","n":[["설명","버스(Bus)의 개념 중앙처리장치, 기억장치, 입출력장치 사이에서 데이터가 오고 갈 때, 데이터들이 움직이는 통로(공간)를 버스 (Bus)라고 합니다. 도시의 도로망처럼 컴퓨터 내부의 각 장치를 연결하여 데이터·주소·제어 신호를 실어 나르는 역할을 합니다."]]},{"t":"② 인출-해석-실행-기록","n":[["실제 사례","중앙처리장치는 목적에 따라 연산 등을 수행하며, 기본적으로 인출(Fetch) → 해석(Decode) → 실행(Execute) → 기록(Store)의 단계를 거칩니다. 인출은 기억장치에서 명령어를 가져오는 단계, 해석은 가져온 명령어가 무슨 일을 하라는 것인지 해독하는 단계, 실행은 실제 연산을 수행하는 단계, 기록은 그 결과를 저장하는 단계입니다. 이 네 단계가 초당 수십억 번 반복되면서 프로그램이 실행됩니다."],["설명","명령 실행 사이클(인출-해석-실행-기록)"]]},{"t":"③ 주방 비유 명령 사이클","n":[["설명","실생활 비유를 통한 이해 명령 실행 사이클은 음식점 주방에 비유할 수 있습니다. 주문서를 가져오는 것이 인출, 주문 내용을 읽고 무슨 요리인지 파악하는 것이 해석, 요리를 만드는 것이 실행, 완성된 요리를 내보내는(결과를 저장하는) 것이 기록에 해당합니다. 주문서(명령어)가 쌓여 있는 곳이 기억장치이고, 요리사가 CPU인 셈입니다."]]}]}]}]},{"t":"Ⅱ 프로그래밍의 기본 용어","c":[{"t":"1. 변수와 식별자","c":[{"t":"(1) 변수의 개념","c":[{"t":"① 값 저장 메모리 공간 이름","n":[["쉬운 예","변수(Variable)는 어떤 값을 주기억장치에 기억하기 위해서 사용하는 공간입니다. 앞서 순서도에서 배운 정의와 동일합니다. NCS 기준의 변수 개념도에서는 주기억장치 안의 한 칸(공간)을 변수명이 담당하고, 그 칸 안에 값이 들어가는 것으로 표현합니다. 예를 들어 \"a = 5\"라고 하면 주기억장치의 한 공간에 a라는 이름 표를 붙이고 그 안에 값 5를 대입한 것입니다."],["설명","변수의 정의"]]},{"t":"② 변수명=식별자(Identifier )","n":[["설명","식별자(Identifier)로서의 변수명 변수명은 프로그램을 구성하는 요소를 구별하기 위한 기준으로서 식별자(Identifier)에 속합니다. 식별자란 프로그램에서 데이터를 처리하기 위해 서로를 구별해서 나타내는 이름을 말하며, 변수명 외에도 함수명, 배열명 등이 모두 식별자입니다."]]}]},{"t":"(2) 바인딩과 선언","c":[{"t":"① 바인딩 변수-속성 연결","n":[["설명","바인딩(Binding)의 개념 바인딩은 변수와 변수에 관련된 속성(자료형, 값, 메모리 위치 등)을 연결하는 과정을 의미합니다. 바인딩은 연결 시점에 따라 정적 바인딩과 동적 바인딩 두 가지로 나뉩니다."]]},{"t":"② 정적 바인딩 컴파일 시점","n":[["설명","정적 바인딩(Static Binding) 프로그램을 실행하기 전(컴파일 시점)에 속성을 연결하는 방식입니다. 정적(Static)이라는 말은 \"움직임이 없다\"는 뜻으로, 프로그램이 움직이기(실행되기) 전에 미리 연결을 끝내 놓는 것입니다. C 언어에서 int a; 처럼 자료형을 미리 지정하는 것이 대표적인 예입니다."]]},{"t":"③ 동적 바인딩 런타임","n":[["설명","동적 바인딩(Dynamic Binding) 프로그램 실행 시간(Runtime)에 속성을 연결하는 방식입니다. 동적(Dynamic)이라는 말은 \"움직임이 있다\" 는 뜻으로, 프로그램이 실행되는 도중에 연결이 이루어집니다. Python에서 변수에 값을 넣는 순간 자료형이 결정되는 것이 대표적인 예입니다."]]},{"t":"④ 명시적·묵시적 선언","n":[["설명","선언(Declaration)의 두 가지 방식 선언은 변수에 속성을 부여하는 행위입니다. 선언에는 명시적(Explicit) 선언과 묵시적(Implicit) 선언이 있습니다. 명시적 선언은 프로그래머가 직접 이름을 지정하여 선언하는 것이고, 묵시적 선언은 미리 약속된 규칙에 의해 자동으로 속성이 부여되는 것입니다. NCS 상에서 중요하게 다뤄지는 용어이므로 두 방식을 구분해서 기억해야 합니다."]]}]}]},{"t":"2. 변수 선언의 규칙","c":[{"t":"(1) 변수명 작성 규칙","c":[{"t":"① 영문·숫자·언더바(_) 허용","n":[["시험 포인트","변수 이름에는 영문 대문자, 영문 소문자, 숫자, 밑줄(_, 언더바)을 사용할 수 있습니다. 반면 마이너스 기호(-)는 사용할 수 없습니다. 하이픈은 뺄셈 연산자와 혼동되기 때문입니다. 그래서 프로그래밍에서는 공백 대신 언더바를 사용하여 student_score처럼 이름을 짓는 경우가 많습니다."],["설명","사용 가능한 문자"]]},{"t":"② 숫자 시작·공백·예약어 금지","n":[["설명","금지 규칙 첫째, 변수명의 첫 번째 자리는 숫자로 시작할 수 없습니다. 1st_score는 불가능하지만 score1은 가능합니다. 둘째, 변수 이름 중간에 공백을 사용할 수 없습니다. my score는 불가능하고 my_score로 써야 합니다. 셋째, 이미 사용되고 있는 예약어(Reserved Word)는 변수명으로 사용할 수 없습니다."]]},{"t":"③ 예약어 print·while·in t 등","n":[["설명","예약어(Reserved Word)의 개념 예약어란 프로그래밍 언어가 미리 지정(묵시적으로 선언)해 둔 명령어들을 말합니다. 대표적으로 print,\nwhile, for, if, int 등이 있으며, 이런 단어들은 언어가 이미 용도를 정해 놓았기 때문에 변수명으로 쓸 수 없습\n니다."]]}]},{"t":"(2) 변수명 판별 연습","c":[{"t":"① score·_temp 가능, 대소문자 구별","n":[["설명","사용 가능한 변수명의 예 score, total_sum, a1, _temp, MAX_VALUE 등은 모두 규칙을 지킨 올바른 변수명입니다. 언더바로 시작하는 것은 허용되며, 대문자와 소문자를 섞어 쓰는 것도 가능합니다. 참고로 프로그래밍 언어는 대문자와 소문자를 구별하므로 Score와 score는 서로 다른 변수입니다."]]},{"t":"② 1st·my score·while 불가","n":[["시험 포인트","2nd(숫자로 시작), my score(중간 공백), for(예약어), total-sum(마이너스 기호 사용)은 모두 규칙을 위반한 변수명입니다. 시험에서 \"다음 중 변수명으로 사용할 수 없는 것\"을 고르는 유형이 필기에서 자주 출제되었으므로, 네 가지 금지 사항(숫자 시작, 공백, 예약어, 특수문자)을 체크리스트처럼 적용하는 연습이 필요합니다."],["시험 포인트","【시험 포인트】 ① 1바이트 = 8비트 ② CPU의 명령 실행 사이클: 인출 → 해석 → 실행 → 기록"],["설명","사용 불가능한 변수명의 예"]]},{"t":"③ 하이픈(-) 포함 규칙 요약","n":[["설명","변수명 규칙: 영문 대소문자·숫자·언더바 가능 / 숫자 시작·공백·예약어·하이픈 불가"]]}]}]}]}]},{"t":"제4절 데이터 타입과 서식 지정자","c":[{"t":"Ⅰ 데이터 타입(자료형)","c":[{"t":"1. 데이터 타입의 개념과 종류","c":[{"t":"(1) 데이터 타입의 정의","c":[{"t":"① 값 특성·길이 구분 속성","n":[["설명","기본 정의 데이터 타입(Data Type, 자료형)은 변수에 들어갈 값의 특성을 구분하여 그 특성에 맞게 저장할 수 있도록하는, 데이터 속성값의 길이 및 성질을 의미합니다. 쉽게 말해 \"이 변수에는 정수만 담겠다\", \"이 변수에는 문자만 담겠다\"처럼 담을 값의 종류와 크기를 미리 정하는 것입니다."]]},{"t":"② 메모리 효율·오류 방지","n":[["설명","데이터 타입이 필요한 이유 컴퓨터 메모리는 한정되어 있으므로 값의 종류에 따라 필요한 공간의 크기가 다릅니다. 문자 하나는 1바이트면 충분하지만 큰 정수나 실수는 4바이트 이상이 필요합니다. 데이터 타입을 지정하면 메모리를 효율적으로 사용할 수 있고, 잘못된 종류의 값이 저장되는 오류도 방지할 수 있습니다."]]}]},{"t":"(2) 주요 데이터 타입의 종류","c":[{"t":"① Boolean 참·거짓","n":[["설명","불린 타입(Boolean Type) 참(True)과 거짓(False)을 의미하는 데이터 타입입니다. 조건 판단의 결과를 저장할 때 사용합니다. C 언어( 표준 C의 기본형)에서는 불린 타입을 별도로 지원하지 않고 0(거짓)과 0이 아닌 값(참)으로 표현하며, Java에서는 boolean, Python에서는 bool 타입이 있습니다."]]},{"t":"② char 1바이트 'A'","n":[["설명","문자 타입(Character Type) 한 개의 문자를 저장하는 타입입니다. C와 Java에서는 char로 선언하며, 작은따옴표('A')를 사용하여 단일 문자를 표현합니다. C 언어의 char는 크기가 1바이트이며, 문자를 아스키(ASCII) 코드라는 정수값으로 변환하여 저장합니다."]]},{"t":"③ 문자열 C는 char 배열","n":[["설명","문자열 타입(String Type) 여러 문자의 나열(문자열)을 저장하는 타입입니다. 중요한 차이점으로, C 언어에서는 문자열 타입을 지원하지 않으며 문자열을 문자의 배열(char 배열)로 표현합니다. Java에서는 String 클래스를, Python에서는 str 타입을 사용합니다. 문자열은 큰따옴표(\"Hello\")로 표현합니다."]]},{"t":"④ int 정수 4바이트","n":[["실제 사례","소수점이 없는 수를 저장하는 타입입니다. C와 Java에서는 int로 선언합니다. NCS 교재에서 int가 2바이트 또는 4바이트로 표기되어 있는데, 실제 sizeof 연산 문제에서는 C 언어의 int를 4바이트로 계산합니다. 즉 \"C 언어에서 int는 4바이트, float도 4바이트, long도 4바이트, char는 1바이트\"라는 크기를 반드시 기억해야 연산 문제를 풀 수 있습니다."],["설명","정수 타입(Integer Type)"]]},{"t":"⑤ float 4B·double 8B","n":[["설명","부동 소수점 타입(Floating Point Type) 소수점이 있는 실수를 저장하는 타입입니다. C와 Java에서는 float(4바이트)와 double(8바이트)을 사용하"]]},{"t":"⑥ 배열 동일 자료형 묶음","n":[["시험 포인트","같은 타입의 데이터 여러 개를 연속으로 저장하는 타입입니다. C 언어에서는 배열 공간의 크기를 미리 선언합니다(예: int a[5];). Java에서도 미리 선언할 수 있지만, 데이터를 넣으면서 선언할 때는 크기 공간을 비워 두면 오른쪽 데이터의 개수에 맞게 크기가 자동으로 조정됩니다(예: int[] a = {1, 2, 3};). 이 선언 방식의 차이가 시험 비교 포인트입니다."],["설명","배열 타입(Array Type)"]]}]},{"t":"(3) 언어별 자료형과 크기 정리표","n":[["설명","(3) 언어별 자료형과 크기 정리표\n구분     C 언어                             Java                             Python\n불린     기본 지원 안 함(0/1)                   boolean                          bool\n문자     char (1바이트)                      char (2바이트)                      별도 없음(str로 처리)\n문자열    지원 안 함(char 배열 사용)               String                           str\n정수     int (4바이트)                       int (4바이트)                       int (크기 제한 없음)\n실수     float(4바이트), double(8바이트)        float(4바이트), double(8바이트)        float\n  C 언어에서 sizeof 함수(연산자)는 변수나 자료형이 차지하는 메모리 크기를 바이트 단위로 반환합니다.\n  sizeof(char)는 1, sizeof(int)는 4, sizeof(float)는 4, sizeof(double)은 8이 됩니다. \"char는 1바이트,\n  나머지 기본형(int, float, long)은 4바이트\"로 기억하면 sizeof 연산 문제를 빠르게 풀 수 있습니다."]]}]},{"t":"2. 아스키 코드(ASCII Code)","c":[{"t":"(1) 아스키 코드의 개념","c":[{"t":"① ASCII 문자↔정수 코드","n":[["쉬운 예","아스키(ASCII: American Standard Code for Information Interchange) 코드는 문자를 숫자(정 수)에 대응시킨 미국 표준 코드 체계입니다. C 언어에서 문자는 내부적으로 아스키 코드 정수값으로 저장됩니다. 예를 들어 문자 'A'는 65, 'B'는 66, 'a'는 97, '0'(문자 영)은 48에 대응됩니다."],["설명","정의"]]},{"t":"② 'A'=65·'a'=97·'0'= 48","n":[["시험 포인트","대문자 'A' = 65, 소문자 'a' = 97, 숫자 문자 '0' = 48의 세 가지 기준값을 암기하면 나머지는 순서대로 계산할 수 있습니다. 'C'는 65 + 2 = 67이고, 'e'는 97 + 4 = 101입니다. 또한 대문자와 소문자의 차이가 32라는 점('a' - 'A' = 97 - 65 = 32)도 대소문자 변환 문제에서 자주 활용됩니다."],["설명","핵심 암기 값"]]}]},{"t":"(2) 문자와 정수의 상호 변환","c":[{"t":"① char=65 %c→A %d→65","n":[["설명","문자 변수에 정수 대입 C 언어에서 char num1 = 65; 처럼 문자 변수에 65라는 정수를 대입해도 정상적으로 입력됩니다. char는 결국 1바이트 크기의 정수형처럼 동작하기 때문입니다. 이 변수를 %c로 출력하면 문자 'A'가, %d로 출력하면 정수 65가 나옵니다."]]},{"t":"② 문자 대입 %d 아스키 출력","n":[["시험 포인트","반대로 char path = 'A'; 처럼 작은따옴표로 문자를 대입한 후 %c로 출력하면 그대로 A가 나오고, %d로 출력하면 'A'의 아스키 코드인 65가 나옵니다. C 언어에서는 문자가 아스키 코드로 저장되기 때문에 서식 지정자에 따라 문자로도, 정수로도 출력할 수 있다는 것이 핵심입니다. 이 유형은 실기 기출에서 반복적으로 등장합니다."],["설명","문자 변수에 문자 대입 후 정수로 출력"]]}]}]}]},{"t":"Ⅱ 서식 지정자와 이스케이프 시퀀스","c":[{"t":"1. 서식 지정자(Format Specifier)","c":[{"t":"(1) 서식 지정자의 개념","c":[{"t":"① printf 출력 서식 기호","n":[["설명","정의 서식 지정자는 변수 혹은 값을 출력문을 통해 출력하기 위해 사용하는 기호입니다. 주로 C 언어의 printf문에서 사용하며, 출력할 값이 정수인지, 실수인지, 문자인지에 따라 서로 다른 서식 지정자를 사용합니다."]]},{"t":"② %d·%f·%c·%s·%lf","n":[["설명","주요 서식 지정자 %d는 부호 있는 10진수 정수, %f는 소수점 여섯째 자리까지의 실수, %c는 단일 문자, %s는 문자열을 출력합니다. 이 네 가지가 가장 많이 등장하며, 그 외에 %o(8진수), %x(16진수), %e(지수 표기), %u(부호 없는 10진수), %ld(long형 정수), %lf(double형 실수) 등이 있습니다."]]}]},{"t":"(2) 서식 지정자 실전 예제","c":[{"t":"① char 65 %d 출력 65","n":[["시험 포인트","char로 선언한 num1에 정수 65를 대입한 후 %d로 출력하면 저장된 정수 그대로 65가 출력됩니다. %d와 %d 사이에 공백이 한 칸 있으므로 65와 2000도 한 칸 띄어서 출력됩니다. num3은 1.23을 대입 했지만 %f는 소수점 여섯째 자리까지 표현하므로 1.230000으로 출력됩니다. 서식 지정자에 자릿수를 지정하지 않으면 여섯 자리가 기본이라는 점이 자주 출제됩니다."],["설명","예제 1: 문자 변수를 %d로 출력\n#include <stdio.h>\nint main(void) {\n      char num1 = 65;       // 문자형 변수에 정수 65 대입\n      int num2 = 2000;\n      float num3 = 1.23;\n      printf(\"%d %d\", num1, num2);      // 출력: 65 2000\n      printf(\"%f\", num3);               // 출력: 1.230000\n      return 0;\n}"]]},{"t":"② 'A' %c→A %d→65","n":[["설명","예제 2: 문자 변수를 %c와 %d로 각각 출력\n#include <stdio.h>\nint main(void) {\n      char PATH = 'A';     // 작은따옴표: 단일 문자\n      printf(\"%c\\n\", PATH);     // 출력: A\n      printf(\"%d\\n\", PATH);     // 출력: 65 (아스키 코드)\n      return 0;\n}\n    같은 변수라도 %c로 출력하면 문자 A가, %d로 출력하면 아스키 코드 65가 출력됩니다. C 언어에서 문자는\n    아스키 코드로 저장되기 때문입니다. 작은따옴표는 단일 문자를 선언할 때, 큰따옴표는 문자열을 선언할 때\n    사용한다는 따옴표 구분도 함께 기억해야 합니다."]]}]}]},{"t":"2. 따옴표와 출력의 관련 규칙","c":[{"t":"(1) 작은따옴표와 큰따옴표","c":[{"t":"① ' ' 단일 문자","n":[["설명","작은따옴표(' ') C와 Java에서 작은따옴표는 단일 문자 하나를 표현할 때 사용합니다. 'A', 'b', '3'처럼 반드시 한 글자만 들어가야 합니다. C 언어에서 'A'는 내부적으로 아스키 코드 65로 처리됩니다."]]},{"t":"② \" \" 문자열+'\\0' 2바이트","n":[["설명","큰따옴표(\" \") 큰따옴표는 문자열을 표현할 때 사용합니다. \"A\"는 한 글자처럼 보여도 문자열이며, 내부적으로는 문자 'A'와 문자열의 끝을 나타내는 널 문자('\\0')로 구성되어 2바이트를 차지합니다. Python에서는 작은따옴표와 큰따옴표를 구분 없이 문자열에 사용할 수 있다는 차이가 있습니다."]]}]},{"t":"(2) 이스케이프 시퀀스(Escape Sequence)","c":[{"t":"① 역슬래시(\\) 특수 동작","n":[["설명","개념 이스케이프 시퀀스는 역슬래시(\\)와 문자를 조합하여 특수한 동작을 표현하는 문자입니다. 화면에 그대로 출력할 수 없는 줄바꿈, 탭 등의 동작을 문자 형태로 표현하기 위해 사용합니다."]]},{"t":"② \\n 줄바꿈·\\t 탭·\\0","n":[["시험 포인트","【시험 포인트】 ① C의 char는 1바이트, int·float·long은 4바이트, double은 8바이트 ② '"],["설명","주요 이스케이프 시퀀스 \\n은 줄바꿈(New Line), \\t는 탭(Tab), \\0은 널 문자, \\\\는 역슬래시 자체, \\'는 작은따옴표, \\\"는 큰따옴표를 출력합니다. 출력 결과 문제에서 \\n의 위치에 따라 답의 줄 구성이 달라지므로, \\n이 나오면 반드시 줄을 바꿔서 답안을 작성해야 합니다."]]}]}]}]}]},{"t":"제5절 연산자(Operator)","c":[{"t":"Ⅰ 산술·시프트 연산자","c":[{"t":"1. 산술 연산자","c":[{"t":"(1) 산술 연산자의 종류","c":[{"t":"① + - * / % (MOD 미사용)","n":[["설명","기본 산술 연산자 연산자는 프로그램 실행을 위해 연산을 표현하는 기호입니다. 산술 연산자에는 더하기(+), 빼기(-), 곱하기(*), 나누기(/), 나머지(%)가 있습니다. 순서도와 달리 프로그래밍에서 나머지는 % 하나로 고정되어 있으며 MOD는 사용하지 않습니다."]]},{"t":"② C·Java 7/2=3, Python //","n":[["설명","정수 나눗셈의 특징 C 언어와 Java에서 정수끼리 / 연산을 하면 몫만 취하고 소수점 이하는 버립니다. 7 / 2는 3.5가 아니라 3입니다. 반면 Python에서 /는 실수 나눗셈(7 / 2 = 3.5)이고, 몫을 구하려면 //를 사용합니다(7 // 2 = 3). 이언어별 차이는 출력 결과 문제에서 자주 함정으로 등장합니다."]]}]},{"t":"(2) 산술 연산자의 우선순위","c":[{"t":"① 괄호→*/%→+- 왼쪽부터","n":[["설명","우선순위의 원칙 연산자 우선순위는 수학과 거의 동일합니다. 가장 먼저 실행되는 것은 괄호 ( )이고, 다음이 곱하기(*)·나누기 (/)·나머지(%), 그다음이 더하기(+)·빼기(-)입니다. 같은 우선순위의 연산자가 나란히 있을 때는 왼쪽부터 차례로 실행합니다."]]},{"t":"② 우선순위 계산 예시","n":[["시험 포인트","4 * 3 / 2를 계산하면 곱하기와 나누기는 같은 우선순위이므로 왼쪽부터 계산하여 (4 * 3) / 2 = 12 / 2 = 6이 됩니다. 2 + 3 * 4는 곱하기가 우선이므로 2 + 12 = 14가 됩니다. (2 + 3) * 4는 괄호가 우선이므로 5 * 4 = 20이 됩니다. 우선순위를 묻는 문제는 가장 기초적이면서도 가장 자주 출제되는 유형입니다."],["설명","계산 예시"]]}]}]},{"t":"2. 시프트 연산자(Shift Operator)","c":[{"t":"(1) 시프트 연산자의 개념","c":[{"t":"① <<·>> 비트 위치 이동","n":[["설명","정의 시프트 연산자는 10진수의 값을 2진수로 변환하여 비트의 위치를 이동시키는 연산자입니다. <<(왼쪽 시프트)는 비트를 왼쪽으로 이동시키고, >>(오른쪽 시프트)는 비트를 오른쪽으로 이동시킵니다. 컴퓨터는 데이터를 2진수로 기억하므로, 시프트 연산 문제를 풀 때는 먼저 10진수를 2진수로 바꾸는 것이 첫 단계입니다."]]},{"t":"② 1바이트 8자리 2진 표기","n":[["설명","8자리(1바이트) 표기의 이유 시프트 연산에서 2진수를 8자리로 쓰는 이유는 1바이트가 8비트로 구성되기 때문입니다. 5를 2진수로 표현하면 101이지만, 1바이트 기준의 기본 표현 양식에 맞춰 0000 0101로 8자리를 채워 씁니다. 2바이트라면 16자리가 됩니다."]]}]},{"t":"(2) 시프트 연산 예제","c":[{"t":"① 5<<2=20","n":[["설명","왼쪽 시프트 예제\nint num = 5;              // 2진수: 0000 0101\nint result = num << 2; // 왼쪽으로 2칸 이동\n// 0000 0101 → 0001 0100 = 16 + 4 = 20\n5(0000 0101)를 왼쪽으로 2칸 밀면 오른쪽 빈자리에 0이 채워지면서 0001 0100이 되고, 이를 10진수로 바꾸면 20입니다. 왼쪽으로 밀려 넘어간 비트는 사라지고, 오른쪽에서 새로 들어오는 자리는 0으로 채워진다는 것이 시프트 연산의 규칙입니다."]]},{"t":"② <<n=×2^n, >>n=÷2^n","n":[["설명","시프트 연산의 수학적 의미 왼쪽으로 n칸 시프트하면 2의 n제곱을 곱한 것과 같고, 오른쪽으로 n칸 시프트하면 2의 n제곱으로 나눈 몫과 같습니다. 5 << 2 = 5 × 4 = 20이고, 20 >> 2 = 20 ÷ 4 = 5입니다. 2진수 변환 없이 빠르게 검산할 수있는 요령이므로 함께 기억해 두면 좋습니다."]]}]}]}]},{"t":"Ⅱ 관계·논리·비트 연산자","c":[{"t":"1. 관계 연산자(Relational Operator)","c":[{"t":"(1) 관계 연산자의 개념","c":[{"t":"① > < >= <= == !=","n":[["설명","정의와 종류 관계 연산자는 두 피연산자 사이의 크기를 비교하는 연산자로, 비교 연산자 또는 조건 연산자라고도 부릅니다. 적어도 두 개의 데이터(왼쪽과 오른쪽)를 비교하며, 종류에는 >(초과), <(미만), >=(이상), <=(이하), ==(같다), !=(다르다)가 있습니다. 순서도와 달리 같다는 ==(등호 두 개), 다르다는 !=로 표기합니다."]]},{"t":"② 비교 결과 참1·거짓0","n":[["쉬운 예","관계 연산의 결과는 조건이 맞으면 참(True), 맞지 않으면 거짓(False)입니다. 중요한 것은 C 언어에서는 참과 거짓이 True/False라는 단어가 아니라 숫자로 표현된다는 점입니다. 참일 경우 1, 거짓일 경우 0이 결과값이 됩니다. 예를 들어 printf(\"%d\", 5 > 3); 은 1을 출력합니다. 관계 연산의 결과(1 또는 0)를 이후 산술 연산에 사용하는 문제도 출제되므로 이 규칙을 확실히 기억해야 합니다."],["설명","결과값의 표현"]]}]}]},{"t":"2. 논리 연산자(Logical Operator)","c":[{"t":"(1) 논리 연산자의 종류","c":[{"t":"① && 모두 참일 때 참","n":[["설명","AND 연산자(&&) 두 피연산자 사이의 논리적인 관계를 정의하는 연산자 중 &&(AND)는 두 가지 논리값이 모두 참일 때만 참 (True)을 반환하고, 그렇지 않으면 거짓(False)을 반환합니다. \"5 > 3 && 2 > 1\"은 양쪽 모두 참이므로 참이 되고, \"5 > 3 && 1 > 2\"는 오른쪽이 거짓이므로 전체가 거짓이 됩니다."]]},{"t":"② || 하나라도 참이면 참","n":[["설명","OR 연산자(||)"]]},{"t":"③ ! 단항 논리 반전","n":[["설명","NOT 연산자(!) !(NOT)는 논리값을 반대로 뒤집는 연산자입니다. !(5 > 3)은 참을 뒤집어 거짓이 됩니다. 피연산자가 하나뿐인 단항 연산자라는 점에서 &&, ||와 구별됩니다."]]}]},{"t":"(2) 단축 평가 - 최근 출제 경향","c":[{"t":"① && 앞 거짓 시 뒤 생략","n":[["쉬운 예","&& 연산은 모든 조건을 만족해야 참이 되므로, 왼쪽에서 오른쪽으로 연산하다가 앞쪽에서 하나라도 거짓이 나오면 뒤쪽의 연산은 아예 진행하지 않습니다. 이미 전체 결과가 거짓으로 확정되었기 때문입니다. 예를 들어 \"a > 10 && ++b > 5\"에서 a > 10이 거짓이면 ++b는 실행되지 않아 b의 값이 증가하지 않습니다."],["설명","AND의 단축 평가"]]},{"t":"② || 앞 참 시 뒤 생략","n":[["설명","OR의 단축 평가 반대로 || 연산은 하나라도 참이면 참이므로, 앞쪽에서 참이라는 결과가 나오는 순간 뒤쪽의 연산은 진행하지 않습니다. \"a > 1 || ++b > 5\"에서 a > 1이 참이면 ++b는 실행되지 않습니다. 이 단축 평가를 증감 연산자( 전위·후위)와 결합하여 변수의 최종 값을 묻는 문제가 최근 많이 등장하는 유형이므로 반드시 이해해야 합니다."]]}]}]},{"t":"3. 비트 연산자(Bitwise Operator)","c":[{"t":"(1) 비트 연산자의 개념","c":[{"t":"① & | ^ ~ 비트 단위","n":[["설명","정의 비트 연산자는 2진수에 대한 논리식, 즉 필기에서 배운 불 대수 진리표를 비트 단위로 적용하는 연산자입니다. &(비트 AND), |(비트 OR), ^(비트 XOR), ~(비트 NOT)가 있습니다. 논리 연산자와 기호가 비슷하지만 개수가 다릅니다. 논리 연산은 &&, ||처럼 두 개를 쓰고, 비트 연산은 &, |처럼 하나만 씁니다."]]},{"t":"② 비트 진리표 계산","n":[["쉬운 예","비트 AND(&)는 두 비트가 모두 1일 때만 1, 비트 OR(|)는 하나라도 1이면 1, 비트 XOR(^)는 두 비트가 서로 다를 때만 1입니다. 예를 들어 1010 & 1100 = 1000, 1010 | 1100 = 1110, 1010 ^ 1100 = 0110입니다. 필기에서 연습했던 논리 게이트 계산식을 프로그래밍 기호로 표시한 것이 비트 연산자라고 이해하면 됩니다."],["설명","진리표에 의한 계산"]]}]}]}]},{"t":"Ⅲ 증감·복합대입·삼항·진법 연산자","c":[{"t":"1. 증감 연산자(Increment/ Decrement Operator)","c":[{"t":"(1) 전위 연산과 후위 연산","c":[{"t":"① ++a 증감 후 연산, a++","n":[["설명","개념 증감 연산자는 피연산자를 1씩 증가(++)시키거나 감소(--)시킬 때 사용하는 연산자입니다. 부호의 위치에 따라 전위 연산자와 후위 연산자로 구분합니다. 전위 연산자(++a, --a)는 피연산자를 증감한 후 해당 라인의 연산을 수행하고, 후위 연산자(a++, a--)는 해당 라인의 연산을 수행한 후 증감합니다."]]},{"t":"② 선 긋기 좌→우 구분","n":[["설명","구분 요령 - 선 긋기 방법 부호와 변수 사이에 선을 긋고 왼쪽에서 오른쪽으로 읽으면 쉽게 구분됩니다. ++a는 \"증가(++)가 먼저, 사용(a)이 나중\"이고, a++는 \"사용(a)이 먼저, 증가(++)가 나중\"입니다. 순서는 항상 왼쪽에서 오른쪽이므로, 기호가 앞에 있으면 증감 먼저, 변수가 앞에 있으면 사용 먼저라고 기억하면 됩니다."]]}]},{"t":"(2) 증감 연산자 실전 예제","c":[{"t":"① ++a·--b 출력 6 4","n":[["설명","전위 연산 예제\nint a = 5, b = 5;\nprintf(\"%d %d\\n\", ++a, --b);   // 출력: 6 4\nprintf(\"%d %d\\n\", a, b);       // 출력: 6 4\n++a는 먼저 a를 6으로 증가시킨 후 출력하므로 6이 나오고, --b는 먼저 b를 4로 감소시킨 후 출력하므로 4가 나옵니다. 연산 후에도 a는 6, b는 4로 유지됩니다."]]},{"t":"② a++·b-- 출력 5 5→6 4","n":[["설명","후위 연산 예제\nint a = 5, b = 5;\nprintf(\"%d %d\\n\", a++, b--);   // 출력: 5 5\nprintf(\"%d %d\\n\", a, b);       // 출력: 6 4\na++는 현재 값 5를 먼저 출력한 후 a를 6으로 증가시키고, b--도 5를 먼저 출력한 후 4로 감소시킵니다. 그래서 첫 줄은 5 5가 출력되지만, 두 번째 줄에서는 이미 증감이 완료된 6과 4가 출력됩니다. 전위와 후위의 출력 차이를 비교하는 이 유형은 실기 단골 문제입니다."]]}]}]},{"t":"2. 복합 대입 연산자","c":[{"t":"(1) 개념과 종류","c":[{"t":"① a+=2 ⇔ a=a+2","n":[["설명","정의 복합 대입 연산자는 반복적인 연산을 간결하게 줄여 쓰기 위한 연산자입니다. a += 2는 a = a + 2를 줄인 것이고, a -= 2는 a = a - 2, a *= 2는 a = a * 2, a /= 2는 a = a / 2, a %= 2는 a = a % 2를 줄인 것입니다."]]},{"t":"② a+=5, a%=4 → 3","n":[["설명","계산 예시 a = 10일 때 a += 5를 실행하면 a = 10 + 5 = 15가 됩니다. 이어서 a %= 4를 실행하면 a = 15 % 4 = 3이 됩니다. 복합 대입 연산자가 연속으로 나오는 문제는 한 줄씩 풀어 쓰면서 계산하면 실수를 줄일 수 있습니다."]]}]}]},{"t":"3. 삼항 연산자(Ternary Operator)","c":[{"t":"(1) 개념과 형식","c":[{"t":"① 조건 ? 참값 : 거짓값","n":[["설명","정의 삼항 연산자는 조건에 부합할 경우 참(True) 값을, 부합하지 않을 경우 거짓(False) 값을 반환하는 연산자입니다. 형식은 \"조건식 ? 참일 때 값 : 거짓일 때 값\"입니다. 피연산자가 세 개(조건식, 참 값, 거짓 값)라서 삼항 연산자라고 부릅니다."]]},{"t":"② max=(a>b)?a:b","n":[["설명","사용 예시\nint a = 10;\nchar* result = (a > 5) ? \"크다\" : \"작다\";\n// a가 5보다 크므로 \"크다\"가 선택됨\n10 > 5가 참이므로 물음표 뒤의 첫 번째 값이 선택됩니다. 삼항 연산자는 if문을 쓰지 않고 한 라인 안에 조건 분기를 표현하기 위해 사용합니다. \"max = (a > b) ? a : b;\"처럼 두 수 중 큰 값을 구하는 코드가 대표적인 활용 예입니다."]]}]}]},{"t":"4. 진법 입력 및 출력 연산자","c":[{"t":"(1) 진법 표현의 개념","c":[{"t":"① 0b 2진·0 8진·0x 16진","n":[["쉬운 예","사람은 10진법을 사용하지만 컴퓨터에서는 2진법, 8진법, 16진법도 자주 사용하므로, 프로그래밍 언"],["설명","접두어에 의한 진법 표현"]]},{"t":"② 언어별 진법 접두어 차이","n":[["실제 사례","C와 Python의 진법 접두어 표현은 거의 비슷하며(0b, 0, 0x), Java도 동일한 방식의 선언을 지원"],["시험 포인트","【시험 포인트】 ① 관계 연산 결과는 C에서 1(참)/0(거짓) ② &&·"],["설명","언어별 진법 표현"]]}]}]}]}]},{"t":"제6절 명령문(제어문)","c":[{"t":"Ⅰ 조건문","c":[{"t":"1. if문","c":[{"t":"(1) if문의 개념과 구조","c":[{"t":"① 단일 if·if~else·다중 if","n":[["설명","정의 명령문은 프로그램을 구성하는 문장으로, 지시 사항을 처리하는 단위입니다. 그중 조건문은 조건의 참·거짓 여부에 따라 실행 경로를 달리하는 문장이며, 대표적으로 if문과 switch~case문이 있습니다. if문은 단일 if 문(if만 사용), if~else문(참·거짓 두 갈래), 다중 if문(if~else if~else)으로 구성됩니다."]]},{"t":"② 실행문 1줄 시 { } 생략","n":[["시험 포인트","C와 Java에서 if문의 조건 뒤에 중괄호 { }가 없을 때는 바로 아래 한 줄까지만 if문에 포함되는 것으로 인식합니다. 이 규칙은 반복문에서도 동일하게 적용됩니다. 중괄호가 생략된 코드에서 어디까지가 조건문의 범위인지를 판별하는 것이 출력 결과 문제의 함정 포인트가 되므로 주의해야 합니다."],["설명","중괄호 생략 규칙"]]}]},{"t":"(2) if문의 형태별 상세","c":[{"t":"① if 단독·참/거짓 두 갈래","n":[["설명","단일 if문과 if~else문"]]},{"t":"② if~else if~else 다중","n":[["설명","다중 if문(if ~ else if ~ else)"]]},{"t":"③ Python elif·콜론·들여쓰 기","n":[["설명","Python의 if문 - elif Python에서는 else if 대신 elif를 사용한다는 차이점 외에는 C·Java와 형태가 비슷합니다. 또한 Python은 중괄호 대신 콜론(:)과 들여쓰기로 실행 범위를 구분한다는 문법적 차이가 있습니다. \"C·Java는 else if, Python은 elif\"로 구분해서 기억해야 합니다."]]}]}]},{"t":"2. switch~case문","c":[{"t":"(1) switch~case문의 개념","c":[{"t":"① 값 일치 분기 vs if 범위","n":[["설명","정의와 if문과의 차이 switch~case문은 변수의 값이 어떤 상태(case)인지에 따라 분기하는 조건문입니다. if문은 산술 또는 관계 비교식(범위 비교)이 가능하지만, switch~case문은 조건이 특정 값과 일치하는지 여부만 확인합니다. 즉 \" 점수가 80 이상인가\"는 if문으로, \"등급이 1인가 2인가 3인가\"는 switch문으로 표현하기에 적합합니다."]]},{"t":"② default = else 역할","n":[["설명","default의 역할 switch문에서 default는 해당하는 조건(case)이 모두 맞지 않았을 경우 실행되는 부분으로, if문의 else에 해당합니다."]]}]},{"t":"(2) switch~case문의 주의점","c":[{"t":"① break 없으면 폴스루","n":[["시험 포인트","case 안에 break가 없으면 일치한 case부터 아래의 모든 case가 연달아 실행됩니다. 이를 폴"],["설명","break의 유무와 폴스루(Fall-through)\nint n = 2;\nswitch (n) {\n       case 1: printf(\"one \");\n       case 2: printf(\"two \");\n       case 3: printf(\"three \");\n       default: printf(\"etc\");\n}\n// break가 없으므로 출력: two three etc"]]},{"t":"② Python switch 없음","n":[["시험 포인트","C와 Java는 switch~case문을 지원하지만 Python에는 switch~case문이 없습니다. 이 사실"],["설명","Python에는 switch~case문이 없음"]]}]}]}]},{"t":"Ⅱ 반복문","c":[{"t":"1. for문","c":[{"t":"(1) for문의 구조","c":[{"t":"① 초기식·조건식·증감식","n":[["설명","세 가지 구성 요소 반복문은 특정 부분을 조건이 만족하는 동안 반복 실행하는 문장이며, for문, while문, do~while문의 세 가지가 있습니다. for문은 기준값(초기식: 어디부터), 조건식(어디까지), 증감식(얼마큼씩 증가)의 세 요소를 괄호 안에 모두 포함합니다."]]},{"t":"② for(i=1;i<=10;i++)","n":[["설명","대표적인 형태"]]}]},{"t":"(2) for문의 실행 순서","c":[{"t":"① 초기→조건→본문→증감","n":[["설명","실행 순서의 이해 for문은 \"① 초기식(최초 1회만) → ② 조건식 검사 → ③ (참이면) 본문 실행 → ④ 증감식 → 다시 ② 조건식 검사\"의 순서로 동작합니다. 조건식이 거짓이 되는 순간 반복이 종료됩니다. 초기식은 처음 한 번만 실행된다는 점, 그리고 본문 실행 후에 증감식이 실행된다는 순서가 중요합니다."]]},{"t":"② for문 1~10 합계 55","n":[["설명","누적 합계 예제\nint sum = 0;\nfor (int i = 1; i <= 10; i++) {\n      sum = sum + i;\n}\nprintf(\"%d\", sum);     // 출력: 55\n    1부터 10까지의 합을 구하는 전형적인 코드입니다. sum은 0에서 시작하여 1, 3, 6, 10, 15, 21, 28, 36,\n    45, 55로 누적됩니다. 순서도의 합의 공식(sum = sum + i)이 for문으로 그대로 구현된 형태입니다."]]}]}]},{"t":"2. while문과 do~while문","c":[{"t":"(1) while문","c":[{"t":"① while 조건식만, 출력 0~4","n":[["설명","while문의 구조와 특징\nint i = 0;                // 기준값(초기값): while문 위쪽에 위치\nwhile (i < 5) {           // 조건식만 포함\n      printf(\"%d \", i);\n      i++;                // 증감식: while문 안쪽에 위치\n}\n// 출력: 0 1 2 3 4\n    while문의 괄호에는 조건식만 들어갑니다. for문은 기준값과 증감식이 명령문 안에 모두 포함되어 실수가 적\n    지만, while문은 조건식만 들어가므로 기준값(초기값)은 항상 while문 위쪽에 있어야 하고, 증감식은 while\n    문 안쪽에 반드시 들어가 있어야 합니다. 증감식을 빠뜨리면 조건이 영원히 참이 되어 무한 루프에 빠집니다."]]},{"t":"② for vs while 구성 위치","n":[["시험 포인트","for문과 while문은 형식만 다를 뿐 서로 변환이 가능합니다. for문의 초기식은 while문 앞으로, 조건식은 while의 괄호 안으로, 증감식은 while 본문의 마지막으로 옮기면 동일한 동작을 합니다. 시험에서 같은 로직을 for문과 while문으로 각각 제시하고 결과를 묻기도 하므로 두 형태를 자유롭게 오갈 수 있어야 합니다."],["설명","for문과 while문의 비교"]]}]},{"t":"(2) do~while문","c":[{"t":"① do~while 최소 1회 실행","n":[["시험 포인트","do~while문은 조건을 비교하기 전에 do 블록의 명령문을 먼저 실행하므로, 조건이 만족하지 않아도 최소 한 번은 실행됩니다. for문과 while문은 조건이 처음부터 거짓이면 본문을 한 번도 실행하지 않지만, do~while문은 \"적어도 한 번은 실행\"이 보장된다는 점이 결정적 차이입니다. 자주 출제되지는 않지만 이 특징 자체가 출제 포인트입니다."],["설명","구조와 특징\nint i = 10;\ndo {\n    printf(\"%d \", i);   // 조건과 무관하게 최소 1회 실행\n    i++;\n} while (i < 5);\n// 출력: 10 (조건이 거짓이지만 1회는 실행됨)"]]},{"t":"② for·while·do~while 비교","n":[["설명","반복문 3형제 비교"]]}]}]}]},{"t":"Ⅲ 제어문과 중첩 구조","c":[{"t":"1. break문과 continue문","c":[{"t":"(1) break문","c":[{"t":"① break 반복 즉시 탈출","n":[["설명","정의와 동작 break문은 특정 조건에서 반복문이나 조건문(switch)을 아예 탈출하기 위해 사용합니다. 반복문 내에서 break를 만나면 남은 반복 횟수와 관계없이 즉시 반복문 아래쪽(바깥)으로 빠져나갑니다. 단어 뜻 그대로 \" 멈추다\"로 기억하면 됩니다."]]},{"t":"② i=5부터 짝수 break→5","n":[["설명","예제\nfor (int i = 5; i >= 0; i--) {\n         if (i % 2 == 0) break;   // i를 2로 나눈 나머지가 0이면 탈출\n         printf(\"%d \", i);\n}\n// i=5: 홀수라 출력 → i=4: 짝수이므로 break → 출력: 5\n    i가 5부터 감소하면서 반복하는데, i % 2 == 0(짝수) 조건이 처음으로 참이 되는 i = 4에서 break가 실행되\n    어 반복문 전체를 탈출합니다. 따라서 출력은 5 하나뿐입니다."]]}]},{"t":"(2) continue문","c":[{"t":"① continue 아래 건너뛰기","n":[["설명","정의와 동작 continue문은 아래 구문을 실행하지 않고 반복문을 계속(지속)하는 제어문입니다. continue를 만나면 그아래의 코드를 건너뛰고 반복문의 처음(증감식)으로 돌아갑니다. 단어 뜻 그대로 \"계속하다\"로 기억하면 됩니다."]]},{"t":"② 짝수 continue→1 3 5","n":[["설명","예제\nfor (int i = 1; i <= 5; i++) {\n         if (i % 2 == 0) continue;   // 짝수면 아래를 건너뜀\n         printf(\"%d \", i);\n}\n// 출력: 1 3 5\n    i가 짝수(2, 4)일 때는 continue에 의해 printf가 건너뛰어지고, 홀수(1, 3, 5)일 때만 출력됩니다. break는\n    반복 자체를 끝내지만 continue는 이번 회차만 건너뛰고 반복은 계속한다는 차이를 명확히 구분해야 합니다."]]}]}]},{"t":"2. 중첩 반복문","c":[{"t":"(1) 이중 for문의 구조","c":[{"t":"① 바깥×안쪽 횟수 실행","n":[["설명","개념 반복문 안에 또 반복문이 들어 있는 구조를 중첩 반복문(이중 for문)이라고 합니다. 바깥 반복문이 1회 돌 때마다 안쪽 반복문은 처음부터 끝까지 전부 실행됩니다. 바깥이 3회, 안쪽이 4회라면 안쪽 본문은 총 3 × 4 = 12회 실행됩니다."]]},{"t":"② 이중 for 구구단 2~3단","n":[["설명","구구단 예제\nfor (int i = 2; i <= 3; i++) {\n      for (int j = 1; j <= 3; j++) {\n          printf(\"%d*%d=%d \", i, j, i*j);\n      }\n      printf(\"\\n\");\n}\n// 출력: 2*1=2 2*2=4 2*3=6\n//         3*1=3 3*2=6 3*3=9\n    바깥 변수 i가 2일 때 안쪽 변수 j가 1부터 3까지 돌면서 2단이 출력되고, i가 3이 되면 다시 j가 1부터 3까지\n    돌면서 3단이 출력됩니다. 중첩 반복문 문제는 바깥과 안쪽 변수의 값 변화를 표로 그려 가며 추적하는 것이\n    가장 정확한 풀이 방법입니다."]]}]},{"t":"(2) 중첩 구조 문제 풀이 요령","c":[{"t":"① 중첩 실행 횟수 곱셈","n":[["시험 포인트","중첩 반복문의 총 실행 횟수는 각 반복문의 반복 횟수를 곱하여 구합니다. 다만 안쪽 반복문의 조건이 바깥 변수에 의존하는 경우(예: j <= i)에는 단순 곱셈이 아니라 각 회차별로 세어 더해야 합니다. i가 1부터 4까지일 때 j가 1부터 i까지 돈다면 1 + 2 + 3 + 4 = 10회가 됩니다. 이런 삼각형 형태의 반복은 별 찍기 문제 등으로 자주 출제됩니다."],["설명","실행 횟수 계산"]]},{"t":"② i·j·sum 변수 추적표","n":[["시험 포인트","【시험 포인트】 ① 중괄호 없는 if·반복문은 아래 한 줄만 포함 ② switch문에서 break가 없으면 아래 case까지 연달아 실행(폴스루) ③ Python에는 switch~case문이 없고 elif를 사용 ④ do~while은 최소 1회 실행 보장 ⑤ break는 탈출, continue는 이번 회차만 건너뜀"],["설명","변수 추적표 작성 출력 결과 문제를 풀 때는 i, j, sum 등 관련 변수를 열로 하는 추적표를 그리고, 반복이 한 번 돌 때마다 값을 기록하는 습관을 들여야 합니다. 암산으로 풀다가 증감 시점(전위·후위)이나 조건 경계(미만·이하)에서 실수하는 경우가 압도적으로 많기 때문입니다."]]}]}]}]}]},{"t":"제7절 함수와 사용자 정의 자료형","c":[{"t":"Ⅰ 함수(Function)와 메소드(Method)","c":[{"t":"1. 함수의 개념","c":[{"t":"(1) 함수의 정의와 필요성","c":[{"t":"① 반복 코드 방지 호출 묶음","n":[["설명","정의 함수(C 언어)와 메소드(Java)는 반복적인 코드의 사용을 방지하기 위하여, 필요할 때마다 해당 코드를 호출하여 값을 반환받도록 만든 하나의 항(코드 묶음)입니다. 같은 계산을 프로그램 곳곳에서 열 번 해야 한다면, 열 번 복사해 붙이는 대신 함수 하나를 만들어 열 번 호출하는 것이 효율적이고 유지보수도 쉽습니다."]]},{"t":"② 자료형 함수명(매개변수)·void","n":[["설명","함수의 기본 형식 C 언어에서 함수는 \"자료형 함수명(매개변수) { 실행문; return 반환값; }\"의 형식으로 작성합니다. 자료형은 함수가 돌려주는 값의 타입이고, 매개변수는 함수가 전달받는 값이며, return은 결과를 호출한 곳으로 돌려주는 명령입니다. 반환값이 없는 함수는 자료형을 void로 선언합니다."]]}]},{"t":"(2) 함수의 호출과 반환","c":[{"t":"① main 먼저, 호출→복귀","n":[["설명","main 함수와 실행 순서 C 언어 프로그램은 항상 main 함수가 제일 먼저 실행됩니다. main 함수 안에서 다른 함수를 호출하면 프로그램의 흐름이 해당 함수로 이동하고, 함수 실행이 끝나면(return을 만나면) 호출했던 자리로 다시 돌아옵니다. 코드가 위에서 아래로만 흐르는 것이 아니라 호출과 복귀로 점프한다는 것이 함수 문제 풀이의 핵심입니다."]]},{"t":"② func(1,2) 반환 3","n":[["설명","호출 예제\n#include <stdio.h>\nint func(int num1, int num2) {\n      printf(\"%d %d\\n\", num1, num2);\n      return num1 + num2;\n}\nint main(void) {\n      int s = func(1, 2);    // 1이 num1에, 2가 num2에 대입\n      printf(\"%d\", s);       // 반환값 3 출력\n      return 0;\n}\n    main에서 func(1, 2)를 호출하면 1이 매개변수 num1에, 2가 num2에 대입되어 함수 본문이 실행됩니다.\n    함수 안에서 1 2가 출력되고, return에 의해 3이 호출한 자리로 돌아와 변수 s에 저장된 후 출력됩니다."]]}]}]},{"t":"2. 반환값의 저장 - 실기 최중요 포인트","c":[{"t":"(1) 반환값을 저장하는 경우와 저장하지 않는 경우","c":[{"t":"① n=plus(n) 저장 시 11","n":[["설명","반환값을 변수에 저장하는 경우(예제 1)\nint plus(int num) {\n      return num + 1;\n}\nint main(void) {\n      int n = 10;\n      n = plus(n);          // 반환값 11을 n에 다시 저장\n      printf(\"%d\", n);      // 출력: 11\n}\n    n = plus(n); 처럼 함수의 반환값을 변수 n에 다시 대입하면, 함수 안에서 1 증가한 11이 n에 저장되어 11이\n    출력됩니다."]]},{"t":"② plus(n) 미저장 시 10","n":[["설명","반환값을 저장하지 않는 경우(예제 2)\nint plus(int num) {\n      return num + 1;\n}\nint main(void) {\n      int n = 10;\n      plus(n);              // 호출만 하고 반환값을 저장하지 않음\n      printf(\"%d\", n);      // 출력: 10\n}\nplus(n); 처럼 호출만 하고 반환값을 어디에도 저장하지 않으면, 함수가 실행되어 11을 돌려주더라도 그 값을 받는 공간이 없으므로 n은 변하지 않고 그대로 10이 출력됩니다. 두 예제의 차이는 \"n = \" 한 줄, 즉 저장 공간의 유무뿐입니다. 함수가 호출되는 과정은 동일하지만 반환값을 저장했느냐 안 했느냐로 결과가 달라지는이 유형은 기능사 실기에서 자주 등장하는 최중요 포인트입니다."]]}]},{"t":"(2) 값에 의한 호출(Call by Value)의 이해","c":[{"t":"① Call by Value 복사본","n":[["설명","매개변수는 복사본 C 언어에서 함수에 변수를 전달하면 변수 자체가 아니라 값의 복사본이 전달됩니다. 함수 안에서 매개변수를 아무리 변경해도 호출한 쪽의 원본 변수는 영향을 받지 않습니다. 이것이 위 예제 2에서 n이 변하지 않은 근본적인 이유입니다."]]},{"t":"② 반환값 대입·Call by Reference","n":[["설명","원본을 변경하려면 원본 변수를 변경하려면 예제 1처럼 반환값을 다시 대입받거나, 포인터(주소)를 전달하는 참조에 의한 호출(Call by Reference)을 사용해야 합니다. 기능사 수준에서는 \"반환값을 저장해야 원본이 바뀐다\"는 원칙만 확실히 잡아도 관련 문제를 풀 수 있습니다."]]}]}]}]},{"t":"Ⅱ 사용자 정의 자료형","c":[{"t":"1. 열거체(Enumeration)","c":[{"t":"(1) 열거체의 개념","c":[{"t":"① enum 관련 상수 나열","n":[["설명","정의 C, C++, Java 같은 프로그래밍 언어에서는 사용자가 직접 자료형을 만드는 것이 가능하며, 이를 사용자 정의 자료형이라고 합니다. C·C++의 경우 열거체, 구조체, 공용체로 구분합니다. 그중 열거체(enum)는 서로 관련 있는 상수들을 나열하여 이름을 붙여 두는 자료형입니다."]]},{"t":"② 0부터, 지정값 후 +1","n":[["시험 포인트","열거체에서 아무 값도 지정하지 않으면 첫 멤버의 초기값은 0이고, 이후 멤버는 앞 멤버에서 1씩 증가합니다. 값을 지정한 멤버가 있으면 그다음 멤버부터는 지정된 값에서 다시 1씩 증가합니다. 위 예제에서 BLACK은 0, RED는 1이 되고, YELLOW는 10으로 지정되었으므로 GREEN은 2가 아니라 11이 됩니다. 이 규칙이 열거체 문제의 핵심 출제 포인트입니다."],["설명","열거체의 값 부여 규칙\nenum color { BLACK, RED, YELLOW = 10, GREEN };\n// BLACK = 0, RED = 1, YELLOW = 10, GREEN = 11"]]}]},{"t":"(2) 열거체의 활용","c":[{"t":"① 숫자에 이름, 가독성 향상","n":[["설명","사용 목적 숫자에 의미 있는 이름을 붙여 코드의 가독성을 높이는 것이 열거체의 목적입니다. 요일을 0~6의 숫자로 관리하는 것보다 SUN, MON, TUE라는 이름으로 관리하면 코드를 읽기가 훨씬 쉽습니다."]]},{"t":"② Java enum 키워드","n":[["설명","Java에서의 열거체 Java에서도 enum 키워드로 열거체를 정의할 수 있으며, 열거체 규칙(0부터 시작, 1씩 증가)의 개념은 자바등 다른 언어에서도 등장할 수 있으므로 enum이라는 키워드 자체를 기억해 두어야 합니다."]]}]}]},{"t":"2. 구조체(Structure)와 공용체(Union)","c":[{"t":"(1) 구조체","c":[{"t":"① struct 서로 다른 자료형 묶음","n":[["쉬운 예","구조체(struct)는 서로 다른 자료형의 멤버 변수들을 하나로 묶어 사용하는 사용자 정의 자료형입니다. 멤버 변수의 자료형을 마음대로 선언할 수 있으며 멤버 함수의 작성도 가능합니다. 예를 들어 학생 한 명의 정보(이름은 문자열, 점수는 정수, 평균은 실수)처럼 타입이 다른 데이터를 하나의 단위로 관리할 때 사용합니다."],["설명","정의"]]},{"t":"② struct 선언·점(.) 멤버 접근","n":[["설명","구조체의 선언과 사용\nstruct test {           // 구조체 정의\n     int kor;\n     int eng;\n     int math;\n};\nint main(void) {\n     struct test t1;    // 구조체 변수 선언\n     t1.kor = 90;       // 점(.) 연산자로 멤버 접근\n     printf(\"%d\", t1.kor);     // 출력: 90\n}\n구조체는 struct 키워드로 정의한 후 구조체 변수를 선언하여 사용합니다. 멤버에 접근할 때는 점(.) 연산자를 사용하여 \"변수명.멤버명\" 형식으로 값을 할당하거나 출력합니다. t1.kor = 90은 t1이라는 구조체 변수의 kor 멤버에 90을 대입한다는 의미입니다."]]}]},{"t":"(2) 공용체","c":[{"t":"① union 메모리 공간 공유","n":[["설명","정의와 구조체와의 차이 공용체(union)는 구조체와 형식이 거의 유사하지만, 모든 멤버가 하나의 메모리 공간을 공유한다는 점이 다릅니다. 구조체는 멤버마다 각각의 공간을 갖지만, 공용체는 가장 큰 멤버 하나 크기의 공간을 모든 멤버가 함께 사용하므로 메모리 크기를 작게 사용합니다. 이런 특성 때문에 임베디드나 통신 분야처럼 메모리가 제한된 환경에서 많이 쓰입니다."]]},{"t":"② union 키워드 선언","n":[["시험 포인트","공용체는 struct 대신 union 키워드로 선언하며, 나머지 사용 방법(점 연산자로 멤버 접근)은 구조체와 동일합니다. \"공용체 = union\"이라는 키워드를 몰라서 틀리는 경우가 많았으므로(산업기사·기사 기출) 키워드 자체를 확실히 암기해야 합니다."],["설명","선언 키워드\nunion test {             // struct 대신 union 사용\n      int a;\n      char b;\n};"]]},{"t":"③ enum·struct·union 비교","n":[["설명","사용자 정의 자료형 비교표"]]}]}]}]},{"t":"Ⅲ 추상화·상속·구체화","c":[{"t":"1. 추상화(Abstraction)","c":[{"t":"(1) 추상화의 개념","c":[{"t":"① 불필요 세부 제거·간략화","n":[["실제 사례","추상화는 문제의 본질을 이해하기 위해 세부 사항은 배제하고 중요한 부분을 중심으로 간략화하는 기법입니다. \"추상화 = 간략화\"로 기억하면 됩니다. 지하철 노선도가 실제 지형을 생략하고 역의 연결 관계만 남긴 것처럼, 복잡한 대상에서 핵심만 남기는 것이 추상화입니다."],["설명","정의"]]},{"t":"② 기능·자료·제어 추상화","n":[["시험 포인트","추상화는 기능 추상화, 자료 추상화, 제어 추상화의 세 가지로 나뉩니다. 기능 추상화는 입력 데이터를 출력 데이터로 변환하는 과정(기능)을 추상화하는 것이고, 자료 추상화는 데이터와 그 데이터에 대한 연산을 묶어 추상화하는 것이며, 제어 추상화는 프로그램의 제어 흐름(반복·분기 등)을 추상화하는 것입니다. 세 가지 유형의 이름은 이론 문제로 출제될 수 있으므로 \"기능·자료·제어\"로 암기합니다."],["설명","추상화의 세 가지 유형"]]}]}]},{"t":"2. 상속과 구체화","c":[{"t":"(1) 상속(Inheritance)","c":[{"t":"① 상위 특성 하위가 물려받음","n":[["설명","정의 상속은 상위 수준 그룹의 모든 특성을 하위 수준의 그룹이 이어받아 재사용 또는 확장하는 것입니다. 부모의 재산을 자식이 물려받듯, 상위 클래스(부모)의 변수와 메소드를 하위 클래스(자식)가 물려받는 개념으로, 모자(   ) 관계·모자 상속이라는 표현도 사용합니다. 특히 Java 문제에서 자주 등장하는 개념입니다."]]},{"t":"② 단일·다중 상속, Java 단일","n":[["설명","단일 상속과 다중 상속 상속에는 단일 상속과 다중 상속이 있으며, 상위 수준의 그룹이 하나만 존재할 때 이를 단일 상속이라고 부릅니다. 부모가 둘 이상이면 다중 상속입니다. Java는 클래스의 다중 상속을 지원하지 않고 단일 상속만 지원한다는 특징도 함께 기억해 두면 좋습니다."]]}]},{"t":"(2) 구체화(Refinement)","c":[{"t":"① 추상 부분 상세 나열","n":[["설명","정의 구체화는 하위 수준 그룹이 상위 수준 그룹의 추상화된 부분을 구체화(상세하게 나열)시키는 것입니다. 추상 화가 간략화라면 구체화는 그 반대 방향, 즉 간략화되어 있던 부분을 상세히 풀어서 나열하는 것입니다."]]},{"t":"② 추상화↔구체화 반대 방향","n":[["시험 포인트","\"동물\"이라는 추상적 개념을 \"개, 고양이, 말\"로 상세화하는 것이 구체화이고, 반대로 \"개, 고양이, 말\"의 공통점만 남겨 \"동물\"로 만드는 것이 추상화입니다. 두 개념은 서로 반대 방향의 작업이라는 쌍으로 기억하면 혼동을 막을 수 있습니다."],["시험 포인트","【시험 포인트】 ① 함수 반환값은 변수에 저장해야 원본이 바뀜(n = func(n)과 func(n)의 차이) 상화의 3유형: 기능·자료·제어"],["설명","추상화와 구체화의 관계"]]}]}]}]}]},{"t":"제8절 프로그래밍 언어의 특성과 분류","c":[{"t":"Ⅰ 프로그래밍 언어의 역사와 언어별 특징","c":[{"t":"1. 프로그래밍 언어의 발전 과정","c":[{"t":"(1) 연대별 발전 흐름","c":[{"t":"① 연대별 정리 필요성","n":[["시험 포인트","프로그래밍 언어의 개발 연도는 기본서나 자료마다 조금씩 차이가 있을 수 있습니다. 정보처리기능사 실기는 NCS 기준을 따르므로, 정확한 연도를 하나하나 암기하기보다 연대별로 구분 지어 어떤 언어가 어느 시대에 등장했는지를 파악하는 것이 효율적입니다."],["설명","연대별 구분의 필요성"]]},{"t":"② FORTRAN 1954~Go 2009","n":[["설명","연대별 주요 언어 1950년대에는 FORTRAN(1954년 초기 버전)과 COBOL(1959년)이 등장했고, 1970년대에는 Pascal(1971년)과 C(1972년)가 등장했습니다. 1980년대에는 C++, 1990년대에는 Java(1995년)와 JavaScript, Python(1991년)이, 2000년대에는 C#(2000년)과 Go(2009년, Google) 등이 등장했습니다."]]}]}]},{"t":"2. 주요 언어별 특징","c":[{"t":"(1) 초창기 언어","c":[{"t":"① FORTRAN 1954 과학계산","n":[["설명","FORTRAN(포트란) 1954년 초기 버전이 개발된, NCS 기준으로 가장 초기에 개발된 언어입니다. 과학 기술 계산용으로 만들어졌으며, 시스템 의존적이고 프로그램 작성을 위해서는 컴퓨터 시스템 관련 지식이 많이 필요했다는 특징이 있습니다."]]},{"t":"② COBOL 1959 사무처리","n":[["시험 포인트","1959년 미국 국방성에 의해 개발된 사무 처리용 언어입니다. 단순한 입출력 구현 시에도 프로그램의 크기가 크고 구문이 복잡하다는 특징이 있으며, 원래는 순차적(절차적) 방식의 언어였습니다. 중요한 최신 경향으로, 코볼은 현재 객체지향 언어로 업데이트되었습니다. 절차지향에서 객체지향으로 바뀐 대표적인 언어라는 점이 새로운 출제 포인트가 될 수 있습니다. 대문자로만 작성한다는 특징도 있습니다."],["설명","COBOL(코볼)"]]},{"t":"③ Pascal 1971 교육용","n":[["설명","Pascal(파스칼) 1971년 개발된 언어로, 간결한 문법 덕분에 교육용 언어로 성공을 거두었습니다. 다만 간결함을 추구한 만큼 처리 능력은 상대적으로 떨어졌습니다. FORTRAN·COBOL·Pascal 세 언어를 초창기 언어 그룹으로 묶어 기억하면 좋습니다."]]}]},{"t":"(2) C 계열 언어","c":[{"t":"① C 1972 UNIX·포인터","n":[["시험 포인트","1972년에 개발된 언어로, UNIX 운영체제 구현에 사용된 언어입니다. 범용 언어로 개발되었으나 문법의 간결성, 효율적 실행, 효과적인 포인터 타입 제공이라는 세 가지 특징으로 인해 가장 많이 사용되는 시스템 프로그래밍 언어가 되었습니다. \"간결·효율·포인터·UNIX\"의 네 키워드로 암기합니다."],["설명","C 언어"]]},{"t":"② C++ C의 객체지향 확장","n":[["설명","C++ C 언어를 객체지향 언어로 발전시킨 언어입니다. C의 문법과 효율성을 유지하면서 클래스, 상속 등 객체지향 개념을 추가했습니다."]]},{"t":"③ C# 2000 닷넷 프레임워크","n":[["시험 포인트","2000년에 마이크로소프트가 닷넷(.NET) 프레임워크를 이용하기 위해 만든 언어입니다. Visual Basic과 같이 사용자 인터페이스를 쉽게 만들 수 있는 도구를 제공하며, 시스템 소프트웨어나 운영체제 기반 응용 개발에 많이 쓰입니다. 닷넷 환경에 고정(의존)된다는 특징이 시험 포인트입니다."],["설명","C#"]]}]},{"t":"(3) Java와 스크립트 계열 언어","c":[{"t":"① Java 1995 JVM 이식성","n":[["설명","Java(자바) 1995년 개발된 언어로, C보다 단순하고 보안성이 뛰어나며 분산 환경(네트워크 환경)을 지원하기 위해 만들어진 객체지향 언어입니다. 한 번 작성한 프로그램이 JVM(자바 가상 머신) 위에서 운영체제에 관계없이 실행되는 높은 이식성이 특징입니다."]]},{"t":"② JavaScript 웹 스크립트","n":[["시험 포인트","웹 페이지의 동작을 구현하는 스크립트 언어입니다. 이름 때문에 Java와 혼동하기 쉽지만 자바스"],["설명","JavaScript(자바스크립트)"]]},{"t":"③ Perl 텍스트 처리·CGI","n":[["설명","Perl(펄) 텍스트 처리에 주안점을 두고 개발된 인터프리터 언어로, CGI(웹 게이트웨이) 용도로도 많이 사용되었습니다. 변수의 자료형을 명시적으로 선언할 필요가 없다는 특징이 있습니다."]]},{"t":"④ Python 1991 인터프리터·AI","n":[["설명","Python(파이썬) 1991년 개발된 언어로, 원래 교육용 언어로 만들어져 배우기 쉽고 이식성이 좋으며 다양한 함수(라이브러리)를 많이 제공합니다. 스타트업과 기업에서도 많이 사용되며, 최근에는 AI·데이터 처리 분야의 표준 언어로 자리 잡았습니다. 대표적인 인터프리터 언어이자 객체지향 언어이며 스크립트 언어라는 세 가지 성격을 모두 갖습니다."]]}]},{"t":"(4) 2000년대 이후의 언어","c":[{"t":"① Go 2009 Google","n":[["설명","Go(고) 2009년 Google에서 만든 언어로, 짧게 GO라고도 부릅니다. C와 직접적인 연관을 가지며 내장 라이브러리를 많이 지원합니다. C 언어의 문법과 유사하며 if, for, switch를 포함한 제어 구조를 가지고 있고, 코드 사용이 낮은(간결한) 것이 특징입니다."]]},{"t":"② Dart(Google)·Scala (JVM)","n":[["설명","Dart와 Scala Dart는 JavaScript와 Java의 영향을 받아 Google이 만든 언어이고, Scala는 Java(JVM)에 기반을 두어 모듈성이 장점인 언어입니다. 두 언어는 상대적으로 중요도가 낮지만 이름과 기반 정도는 알아 두는 것이 좋습니다."]]}]}]}]},{"t":"Ⅱ 프로그래밍 언어의 유형 분류","c":[{"t":"1. 개발 편의성에 따른 분류","c":[{"t":"(1) 저급 언어(Low-Level Language)","c":[{"t":"① 기계어·어셈블리어","n":[["설명","정의와 종류 저급 언어는 기계가 이해하기 쉬운 언어입니다. 0과 1로 이루어진 기계어(Machine Language)와, 기계어를 기호화한 어셈블리어(Assembly Language)가 저급 언어에 속합니다. \"저급\"은 품질이 낮다는 뜻이 아니라 기계에 가깝다(수준이 낮은 계층)는 의미입니다."]]},{"t":"② 빠름·하드웨어 제어·호환X","n":[["설명","특징 실행 속도가 빠르고 하드웨어를 직접 제어할 수 있지만, 사람이 이해하고 작성하기가 매우 어렵고 기계(CPU 종류)마다 언어가 달라 호환성이 없습니다."]]}]},{"t":"(2) 고급 언어(High-Level Language)","c":[{"t":"① C·Java·Python 사람 친화","n":[["설명","정의와 종류 고급 언어는 사람이 쉽게 이해할 수 있도록 만든 언어입니다. if, for처럼 사람이 읽을 수 있는 문자열로 표현되며, C, Java, Python 등 우리가 일반적으로 배우는 프로그래밍 언어가 모두 고급 언어입니다."]]},{"t":"② 기계 독립·번역 필요","n":[["설명","특징 사람이 이해하기 쉽고 기계에 독립적이어서 호환성이 좋지만, 컴퓨터가 실행하려면 번역(컴파일 또는 인터프리트) 과정이 필요합니다."]]}]}]},{"t":"2. 실행 방식에 따른 분류","c":[{"t":"(1) 절차형·함수형 언어","c":[{"t":"① 명령형 순차 실행 C·FORTRAN","n":[["설명","명령형(절차형) 언어 명령형 언어는 컴퓨터에 저장된 명령어들이 순차적으로 실행되는 방식의 언어로, 절차형 언어라고도 합니다. C, COBOL(과거), FORTRAN 등이 해당합니다. \"무엇을 어떤 순서로 할 것인가\"를 중심으로 프로그램을 작성합니다."]]},{"t":"② 함수형 LISP 부작용 최소","n":[["설명","함수형 언어 함수형 언어는 수학적 함수의 계산(적용)을 중심으로 프로그램을 구성하는 언어입니다. LISP 등이 대표적이며, 부작용(Side Effect)을 최소화하는 것이 특징입니다."]]}]},{"t":"(2) 논리형·객체지향형 언어","c":[{"t":"① 논리형 PROLOG 추론","n":[["설명","논리형 언어 논리형 언어는 사실과 규칙을 선언해 놓고 논리적 추론을 통해 문제를 해결하는 언어입니다. PROLOG가 대표적입니다."]]},{"t":"② 객체지향 Java·C++·Pyth on","n":[["설명","객체지향형 언어 객체지향형 언어는 데이터(속성)와 그 데이터를 처리하는 메소드(동작)를 객체라는 단위로 묶어 프로그램을 구성하는 언어입니다. Java, C++, Python 등이 해당하며, 현재 가장 널리 쓰이는 방식입니다. 상속·캡슐화· 다형성 등의 개념을 기반으로 합니다."]]}]}]},{"t":"3. 구현 기법에 따른 분류","c":[{"t":"(1) 컴파일 방식과 인터프리터 방식","c":[{"t":"① 컴파일 전체 번역·목적 프로그램","n":[["설명","컴파일(Compile) 방식 컴파일 방식은 고급 언어로 작성된 원시 프로그램(Source Program) 전체를 한꺼번에 기계어로 번역한 후실행하는 방식입니다. 이 번역 과정에서 목적 프로그램(Object Program)이 생성됩니다. C, C++, C# 등이 컴파일 언어이며, 번역에 시간이 걸리지만 한 번 번역된 후에는 실행 속도가 빠릅니다."]]},{"t":"② 인터프리터 행 단위 번역","n":[["설명","인터프리터(Interpreter) 방식 인터프리터 방식은 원시 프로그램을 한 줄씩(행 단위로) 번역하면서 즉시 실행하는 방식입니다. Python, JavaScript, Perl, BASIC 등이 해당합니다. 목적 프로그램을 생성하지 않으며, 실행 속도는 컴파일 방식보다 느리지만 수정 후 바로 실행할 수 있어 개발이 편리합니다."]]},{"t":"③ 목적 프로그램 유무로 구분","n":[["설명","컴파일러와 인터프리터의 구분 기준 필기에서 자주 등장했던 구분 기준은 목적 프로그램(Object Program)의 유무입니다. 컴파일러는 목적 프로그램을 생성하고, 인터프리터는 목적 프로그램을 생성하지 않습니다. 이 한 가지 기준만 기억해도 두 방식을 확실히 구분할 수 있습니다."]]}]},{"t":"(2) 혼합형 방식","c":[{"t":"① Java 바이트코드+JVM","n":[["설명","개념 혼합형 방식은 컴파일과 인터프리트를 결합한 방식입니다. 대표적으로 Java는 소스 코드를 바이트코드(Bytecode)로 컴파일한 후, JVM이 이 바이트코드를 해석(인터프리트)하며 실행합니다. 하나의 언어가 두단계를 모두 거치는 것입니다."]]},{"t":"② 컴파일·인터프리터·혼합 비교","n":[["시험 포인트","【시험 포인트】 ① C 언어: UNIX 구현, 간결·효율·포인터 ② Java: 보안성·분산환경, C#: 닷넷 의존 ③ Python: 교육용 출발의 인터프리터·객체지향·스크립트 언어 ④ 컴파일러는 목적 프로그램 생성, 인터프리터는 생성 안 함 ⑤ COBOL은 절차지향에서 객체지향으로 변경됨"],["설명","방식별 비교표"]]}]}]}]}]},{"t":"제9절 라이브러리(Library)","c":[{"t":"Ⅰ 라이브러리의 개념","c":[{"t":"1. 라이브러리의 정의와 분류","c":[{"t":"(1) 라이브러리의 정의","c":[{"t":"① 모듈화된 프로그램 집합체","n":[["설명","기본 정의 라이브러리는 효율적인 프로그램 개발을 위해 필요한 프로그램들을 모아 놓은 집합체입니다. 필요할 때 찾아서 쓸 수 있도록 모듈화되어 제공되는 프로그램이며, 프로그래밍 언어에 일반적으로 도움말, 설치 파일, 코드 등과 함께 제공됩니다. 도서관(Library)에서 필요한 책을 빌려 쓰듯, 미리 만들어진 코드를 가져다 쓴다는 의미로 이해하면 됩니다."]]},{"t":"② sqrt 재사용·시간 단축","n":[["설명","라이브러리를 사용하는 이유 제곱근을 구하는 코드를 개발자가 매번 직접 작성하는 것은 비효율적입니다. 이미 검증된 sqrt 함수를 호출하면 한 줄로 해결됩니다. 이처럼 라이브러리는 개발 시간을 단축시키고, 검증된 코드를 재사용함으로써 프로그램의 신뢰성을 높여 줍니다."]]}]},{"t":"(2) 표준 라이브러리와 외부 라이브러리","c":[{"t":"① stdio.h·java.lang 기본 제공","n":[["설명","표준 라이브러리(Standard Library) 프로그래밍 언어가 기본적으로 가지고 있는 라이브러리를 표준 라이브러리라고 합니다. C 언어의 stdio.h, math.h나 Java의 java.lang 패키지처럼 언어를 설치하면 함께 제공되어 별도 설치 없이 사용할 수 있습니다."]]},{"t":"② 별도 설치·프레임워크","n":[["설명","외부 라이브러리(External Library) 별도의 파일을 설치하여 사용하는 라이브러리를 외부 라이브러리라고 합니다. 개발자가 필요에 따라 내려받아 설치해야 하며, 이 외부 라이브러리를 프레임워크(Framework)라고 표현하기도 합니다."]]}]}]},{"t":"2. 모듈과 패키지","c":[{"t":"(1) 모듈(Module)","c":[{"t":"① 모듈=개별 파일(.py)","n":[["설명","정의 라이브러리는 모듈과 패키지로 구성됩니다. 모듈은 개별 파일 하나, 즉 특정 기능을 수행하는 하나의 프로그램 단위를 말합니다. Python에서 .py 파일 하나가 모듈 하나에 해당합니다."]]},{"t":"② 기능별 분리·유지보수 용이","n":[["설명","모듈화의 장점 기능별로 파일을 나누어 두면 필요한 기능만 가져다 쓸 수 있고, 수정할 때도 해당 모듈만 고치면 되므로 유지보수가 쉬워집니다."]]}]},{"t":"(2) 패키지(Package)","c":[{"t":"① 패키지=모듈 묶음 폴더","n":[["쉬운 예","패키지는 모듈들을 모아 놓은 더 큰 묶음입니다. 즉 \"모듈 < 패키지 < 라이브러리\"의 포함 관계로 이해할 수 있습니다. 폴더에 비유하면 모듈이 파일 하나, 패키지가 관련 파일들을 모아 놓은 폴더입니다."],["설명","정의"]]},{"t":"② 라이브러리>패키지>모듈","n":[["시험 포인트","\"개별 파일은 모듈, 모아 놓은 더미는 패키지\"라는 한 문장으로 기억하면 됩니다. 시험에서 모듈과 패키지의 정의를 바꿔 놓고 틀린 것을 고르게 하는 유형이 나올 수 있습니다."],["설명","정리"]]}]}]}]},{"t":"Ⅱ C 언어 표준 라이브러리","c":[{"t":"1. 주요 헤더 파일","c":[{"t":"(1) 헤더 파일의 개념","c":[{"t":"① #include <헤더.h> 선언","n":[["쉬운 예","C 언어에서 표준 라이브러리의 함수를 사용하려면 해당 함수가 정의된 헤더 파일(Header File)을\n#include 문으로 반드시 선언해야 합니다. 예를 들어 printf를 쓰려면 #include <stdio.h>를, sqrt를 쓰려면\n#include <math.h>를 코드 맨 위에 써야 합니다. 어떤 함수가 어떤 헤더 파일에 속하는지가 출제 포인트입니\n다."],["설명","정의와 선언 방법"]]},{"t":"② stdio·math·stdlib· string.h","n":[["설명","주요 헤더 파일 정리"]]}]},{"t":"(2) 주요 함수의 상세","c":[{"t":"① sqrt·pow·abs·ceil· floor","n":[["시험 포인트","sqrt(x)는 x의 제곱근, pow(x, y)는 x의 y제곱, abs(x)는 절댓값, tan(x)는 탄젠트 값을 반환합니다. log 함수는 특히 주의해야 하는데, 컴퓨터의 log(x)는 상용로그(밑 10)가 아니라 자연로그(밑 e)입니다. 상용로그를 구하려면 log10(x)을 사용해야 합니다. log 문제가 자주 출제되었으므로 \"log = 자연로그, log10 = 상용로그\"를 확실히 구분해야 합니다."],["설명","수학 함수(math.h)"]]},{"t":"② atoi·malloc·rand","n":[["설명","변환·메모리·난수 함수(stdlib.h) atoi(문자열)는 문자열을 정수로 변환합니다(\"123\" → 123). malloc(크기)은 실행 중에 메모리를 동적으로 할당하고, rand( )는 난수(임의의 수)를 생성합니다. atoi는 \"ASCII to Integer\"의 약자로 기억하면 쉽습니다."]]},{"t":"③ strlen·strcpy·strc mp·strcat","n":[["설명","문자열 함수(string.h) strlen(s)은 문자열의 길이를 반환하고, strcpy(a, b)는 문자열 b를 a에 복사하며, strcmp(a, b)는 두 문자열을 비교하고(같으면 0 반환), strcat(a, b)는 문자열 a 뒤에 b를 이어 붙입니다. C 언어에는 문자열 타입이 없으므로 이런 문자열 전용 함수들이 반드시 필요하다는 맥락도 함께 이해해 두면 좋습니다."]]}]}]},{"t":"2. 입출력 함수의 활용","c":[{"t":"(1) printf와 scanf","c":[{"t":"① printf 표준 출력 함수","n":[["시험 포인트","printf는 서식 지정자를 이용해 값을 출력하는 표준 출력 함수입니다. printf(\"%d점입니다\", 90); 은 \"90점입니다\"를 출력합니다. 서식 지정자와 이스케이프 시퀀스(제4절 참조)가 조합되어 출제됩니다."],["설명","printf 함수"]]},{"t":"② scanf(\"%d\", &a) 주소 연산자","n":[["설명","scanf 함수 scanf는 키보드로부터 값을 입력받는 표준 입력 함수입니다. scanf(\"%d\", &a); 처럼 변수 앞에 주소 연산자 &를 붙여야 한다는 것이 특징입니다. 입력받은 값이 변수의 메모리 주소에 저장되기 때문입니다."]]}]}]}]},{"t":"Ⅲ Java·Python의 주요 라이브러리","c":[{"t":"1. Java 표준 라이브러리","c":[{"t":"(1) Math 클래스의 주요 메소드","c":[{"t":"① Math.ceil·floor·ro und","n":[["쉬운 예","Java의 Math 클래스에서 소수 자릿수 처리 메소드 세 가지가 가장 중요합니다. Math.ceil( )은 올림, Math.floor( )는 버림(내림), Math.round( )는 반올림입니다. 예를 들어 Math.ceil(3.2) = 4.0, Math.floor(3.8) = 3.0, Math.round(3.5) = 4가 됩니다. ceil(천장)은 위로, floor(바닥)는 아래로 간다고 연상하면 헷갈리지 않습니다. C 언어와의 차이점으로 강조되는 부분이므로 세 메소드의 구분은 반드시 암기해야 합니다."],["설명","올림·버림·반올림 - 최중요"]]},{"t":"② Math.abs·pow·sqrt· max·min","n":[["설명","기타 주요 메소드 Math.abs( )는 절댓값, Math.pow( )는 거듭제곱, Math.sqrt( )는 제곱근, Math.max(a, b)와 Math.min(a, b)는 두 값 중 큰 값과 작은 값을 반환합니다. C의 math.h 함수들과 이름이 거의 같으므로 묶어서 기억하면 효율적입니다."]]}]},{"t":"(2) String 클래스의 주요 메소드","c":[{"t":"① length()·charAt(i) 0부터","n":[["설명","문자열 정보 관련 length( )는 문자열의 길이를, charAt(i)는 i번째 문자를 반환합니다. 인덱스는 0부터 시작하므로 \" HELLO\".charAt(1)은 H가 아니라 E입니다."]]},{"t":"② substring·equals() 내용 비교","n":[["설명","문자열 가공 관련 substring(a, b)는 a번째부터 b번째 직전까지의 부분 문자열을, toUpperCase( )와 toLowerCase( )는대문자·소문자 변환 결과를, equals( )는 두 문자열의 내용이 같은지를 반환합니다. Java에서 문자열 내용 비교는 ==가 아니라 equals( )를 사용해야 한다는 점도 중요합니다."]]}]}]},{"t":"2. Python의 주요 내장 함수와 모듈","c":[{"t":"(1) 주요 내장 함수","c":[{"t":"① print·input·len·ra nge","n":[["설명","기본 내장 함수\nprint( )는 출력, input( )은 입력, len( )은 길이, range( )는 정수 범위 생성, int( )·float( )·str( )은 자료형\n변환 함수입니다. Python은 별도의 헤더 파일 선언 없이 내장 함수를 바로 사용할 수 있다는 점이 C와의 차\n이입니다."]]},{"t":"② abs·max·min·sum·ro und","n":[["설명","수치 관련 내장 함수 abs( )는 절댓값, max( )·min( )은 최댓값·최솟값, sum( )은 합계, round( )는 반올림을 수행합니다. 리스트 [1, 2, 3]에 대해 sum( )을 적용하면 6이 되는 것처럼, Python은 리스트 단위 연산이 간편하다는 특징이 있습니다."]]}]},{"t":"(2) 주요 모듈","c":[{"t":"① import math·random","n":[["설명","math 모듈과 random 모듈\nimport math로 불러오면 math.sqrt( ), math.pow( ), math.ceil( ), math.floor( ) 등을 사용할 수 있고,\nimport random으로 불러오면 random.random( ), random.randint(a, b) 등 난수 관련 함수를 사용할\n수 있습니다. C의 #include, Java의 import처럼 Python도 import 문으로 모듈을 선언한 후 사용한다는\n공통 구조를 기억해야 합니다."]]},{"t":"② #include·import 선언 비교","n":[["시험 포인트","【시험 포인트】 ① 컴퓨터의 log는 자연로그(상용로그는 log10) ② C 함수와 헤더 파일의 짝 (printf-stdio.h, sqrt-math.h, atoi-stdlib.h, strlen-string.h) ③ Java의 ceil(올림)·floor(버림)·round(반 올림) 구분 ④ 모듈(개별 파일) < 패키지(모듈 묶음), 외부 라이브러리 = 프레임워크"],["설명","언어별 라이브러리 선언 비교"]]}]}]}]}]},{"t":"제10절 언어별 핵심 문법 비교와 기출 유형 분석","c":[{"t":"Ⅰ C·Java·Python 핵심 문법 비교","c":[{"t":"1. 기본 구조와 출력문 비교","c":[{"t":"(1) 프로그램 기본 구조","c":[{"t":"① C 헤더+main, 세미콜론","n":[["설명","C 언어의 기본 구조\n#include <stdio.h>\nint main(void) {\n      printf(\"Hello\");\n      return 0;\n}\n    C는 헤더 파일 선언부와 main 함수로 구성되며, 모든 실행은 main 함수에서 시작합니다. 각 문장의 끝에는\n    세미콜론(;)을 반드시 붙입니다."]]},{"t":"② Java 클래스+main 메소드","n":[["설명","Java의 기본 구조\npublic class Main {\n      public static void main(String[] args) {\n          System.out.println(\"Hello\");\n      }\n}\n    Java는 모든 코드가 클래스 안에 있어야 하며, main 메소드에서 실행이 시작됩니다. 출력은\n    System.out.println(줄바꿈 있음) 또는 System.out.print(줄바꿈 없음)를 사용합니다. println과 print의\n    줄바꿈 차이는 출력 결과 문제에서 반드시 확인해야 하는 포인트입니다."]]},{"t":"③ Python 콜론·들여쓰기","n":[["설명","Python의 기본 구조\nprint(\"Hello\")\n    Python은 클래스나 main 함수 없이 코드를 바로 작성할 수 있으며, 문장 끝에 세미콜론을 붙이지 않습니다.\n    블록 구분은 중괄호가 아니라 콜론(:)과 들여쓰기로 합니다. print( )는 기본적으로 출력 후 줄바꿈을 합니다."]]}]},{"t":"(2) 언어별 문법 비교표","n":[["설명","(2) 언어별 문법 비교표\n구분            C                      Java                          Python\n출력문           printf( )              System.out.println( )         print( )\n블록 구분         중괄호 { }                중괄호 { }                       들여쓰기와 콜론(:)\n문장 끝          세미콜론 필수                세미콜론 필수                       세미콜론 없음\n변수 선언         자료형 필수(int a;)         자료형 필수(int a;)                자료형 불필요(a = 1)\n다중 조건         else if                else if                       elif\nswitch문       있음                     있음                            없음\n증감 연산자(++)    있음                     있음                            없음(a += 1 사용)\n정수 나눗셈        / (몫)                  / (몫)                         // (몫), / (실수)"]]}]},{"t":"2. 언어별 함정 포인트","c":[{"t":"(1) Python의 특이점","c":[{"t":"① ++·-- 없음, a+=1","n":[["설명","증감 연산자 부재 Python에는 ++, -- 증감 연산자가 없습니다. a++ 대신 a += 1을 사용해야 합니다. C·Java 문제에 익숙한 상태에서 Python 코드에 ++가 나오면 오류라는 것을 알아채야 합니다."]]},{"t":"② / 실수 나눗셈, // 몫","n":[["설명","나눗셈 연산자의 구분 Python의 /는 항상 실수 나눗셈(7 / 2 = 3.5)이고, //가 몫 연산(7 // 2 = 3)입니다. C·Java의 정수 / 연산(몫)과 결과가 다르므로, 같은 식이라도 언어에 따라 답이 달라질 수 있음을 유의해야 합니다."]]}]},{"t":"(2) Java의 특이점","c":[{"t":"① 1+2+\"A\"=3A, \"A\"+1+2=A12","n":[["설명","문자열 연결과 덧셈 Java에서 + 연산자는 숫자끼리는 덧셈, 문자열이 섞이면 연결로 동작합니다. System.out.println(1 + 2 + \" A\")는 왼쪽부터 계산하여 3 + \"A\" = \"3A\"가 되지만, System.out.println(\"A\" + 1 + 2)는 \"A1\" + 2 = \" A12\"가 됩니다. 계산 순서(왼쪽부터)와 문자열 만남 시점에 따라 결과가 달라지는 대표적 함정 유형입니다."]]},{"t":"② print 줄 유지·println 줄바꿈","n":[["설명","print와 println의 차이\nSystem.out.print는 출력 후 줄을 바꾸지 않고, System.out.println은 출력 후 줄을 바꿉니다. 반복문 안에\n서 어느 쪽을 쓰느냐에 따라 출력이 한 줄로 이어지는지 여러 줄로 나뉘는지가 결정됩니다."]]}]}]}]},{"t":"Ⅱ 기출 유형 분석과 실전 연습","c":[{"t":"1. 대표 기출 유형","c":[{"t":"(1) 출력 결과 예측 유형","c":[{"t":"① 코드 실행 결과 쓰기","n":[["시험 포인트","제시된 코드를 읽고 화면에 출력되는 결과를 정확히 답안으로 작성하는 유형으로, 프로그래밍 문제의 대부분을 차지합니다. 채점은 출력 결과가 정확히 일치하는지를 보므로, 대소문자·공백·줄바꿈까지 정확하게 써야 합니다. 최근 시험에서는 C 언어보다 Python·Java의 실행 결과를 묻는 문제의 비중이 늘어나는 경향이 있으므로 세 언어를 고르게 연습해야 합니다."],["설명","유형 설명"]]},{"t":"② 3의 배수 합 1~10 = 18","n":[["시험 포인트","1부터 10까지 중 3의 배수(3, 6, 9)만 누적하므로 출력은 18입니다. 반복문으로 범위를 만들고 조건문(나머지 연산)으로 걸러내는 이 구조가 가장 전형적인 출제 형태입니다. i가 1일 때부터 10일 때까지 표를 그려 sum의 변화(0 → 3 → 9 → 18)를 추적하는 습관을 들이면 정확도가 크게 올라갑니다."],["설명","실전 예제 - 반복문과 조건문 결합\nint sum = 0;\nfor (int i = 1; i <= 10; i++) {\n     if (i % 3 == 0) {\n         sum += i;\n     }\n}\nprintf(\"%d\", sum);"]]}]},{"t":"(2) 빈칸 채우기 유형","c":[{"t":"① 목적 파악 후 빈칸 추론","n":[["설명","유형 설명 코드의 일부를 빈칸으로 제시하고 프로그램이 의도한 대로 동작하도록 빈칸에 들어갈 코드(연산자, 조건식, 함수명 등)를 작성하는 유형입니다. 프로그램의 목적(예: 1부터 N까지의 합)을 먼저 파악한 후, 빈칸 주변의 문맥으로 답을 추론합니다."]]},{"t":"② 최댓값 a[i]>max → 9","n":[["시험 포인트","배열에서 최댓값을 찾는 전형적인 알고리즘입니다. 첫 요소를 max로 두고, 나머지 요소를 차례로 비교하여 더 크면 교체합니다. 빈칸 문제로 조건식(a[i] > max)이나 교체문(max = a[i])이 출제되며, 최솟값 찾기는 부등호 방향만 반대(a[i] < min)입니다."],["설명","실전 예제 - 최댓값 찾기\nint a[5] = {3, 7, 1, 9, 5};\nint max = a[0];\nfor (int i = 1; i < 5; i++) {\n      if (a[i] > max) {    // 빈칸: a[i] > max\n          max = a[i];\n      }\n}\nprintf(\"%d\", max);         // 출력: 9"]]}]}]},{"t":"2. 학습 전략과 마무리 정리","c":[{"t":"(1) 효과적인 학습 전략","c":[{"t":"① 변수 추적표 손 풀이","n":[["설명","손으로 추적하는 훈련 프로그래밍 문제는 눈으로만 읽으면 반드시 실수가 나옵니다. 변수 추적표를 그려 반복문이 한 번 돌 때마다각 변수의 값을 손으로 기록하는 훈련을 해야 합니다. 특히 증감 연산자의 전위·후위, 반복 조건의 미만·이하, break·continue의 동작은 표를 그려야 정확히 잡아낼 수 있습니다."]]},{"t":"② C·Java·Python 차이 정리","n":[["시험 포인트","C·Java·Python의 공통 문법을 먼저 익힌 후, 차이점(switch 유무, 증감 연산자 유무, 나눗셈 동작, 출력 함수)을 별도로 정리하는 것이 효율적입니다. 시험 문제의 함정은 대부분 언어 간 차이점에서 나오기 때문입니다."],["설명","언어 간 차이점 중심의 정리"]]}]},{"t":"(2) Part 01 총정리 암기 리스트","c":[{"t":"① 필수 암기 개념 목록","n":[["시험 포인트","알고리즘의 5가지 특성(입력·출력·명확성·유한성·유효성), 순서도 도형의 역할(단말·준비·입출력· 처리·판단), 1바이트 = 8비트, 변수명 규칙, C 자료형 크기(char 1, int·float 4, double 8바이트), 아스키 코드 ('A'=65, 'a'=97, '0'=48), 연산자 우선순위(괄호 → 곱·나눗·나머지 → 덧·뺄셈)를 암기해야 합니다."],["설명","반드시 암기할 개념"]]},{"t":"② 필수 암기 규칙 목록","n":[["시험 포인트","관계 연산 결과는 1(참)/0(거짓), 논리 연산자의 단축 평가, 전위·후위 증감의 차이, switch문의 break 유무(폴스루), do~while의 최소 1회 실행, 함수 반환값의 저장 유무, 열거체의 값 증가 규칙, 컴파일러와 인터프리터의 구분(목적 프로그램 유무), log는 자연로그, Java의 ceil·floor·round 구분을 암기해야 합니다."],["설명","반드시 암기할 규칙"]]},{"t":"③ Part 01 마무리 당부","n":[["시험 포인트","Part 01 프로그래밍 언어 활용은 실기 시험에서 가장 배점이 크고 문항 수도 많은 영역입니다. 이정리서의 각 절을 순서대로 학습한 뒤, 제5절(연산자)과 제6절(명령문)의 예제들은 코드를 가리고 결과를 직접써 보는 방식으로 반복 연습하기 바랍니다. 이론 암기(제1~4절, 제8~9절)와 코드 추적 연습(제5~7절, 제10절)을 병행하는 것이 합격의 지름길입니다."],["시험 포인트","【최종 점검】 ① 세 언어의 차이점 표(제10절 Ⅰ-1-(2)) ② 출력 결과는 대소문자·공백·줄바꿈까지 정확히 ③ 변수 추적표 그리기 습관 ④ 최근 경향: Python·Java 출제 비중 증가"],["설명","마무리 당부"]]}]}]}]}]}],"k":"실기 Part01"},{"n":6,"t":"애플리케이션 테스트 수행","c":[{"t":"제1절 애플리케이션 테스트의 개념과 원칙","c":[{"t":"Ⅰ 애플리케이션 테스트의 정의와 V모델","c":[{"t":"1. 애플리케이션 테스트란","c":[{"t":"(1) 테스트의 정의","c":[{"t":"① 애플리케이션 테스트 개념","n":[["실제 사례","애플리케이션 테스트는 개발된 응용 애플리케이션이나 시스템이 사용자가 요구하는 기능과 성능, 사용성, 안정성 등을 만족하는지 확인하고, 겉으로 드러나지 않은 결함을 찾아내는 활동을 의미한다. 단순히 프로그램이 실행되는지 확인하는 것을 넘어, 요구사항과 실제 동작 사이의 차이를 체계적으로 검증하는 과정이다."],["설명","애플리케이션 테스트의 개념"]]},{"t":"② V모델 개발-테스트 대응","n":[["시험 포인트","V모델을 정확히 이해하면, \"가장 먼저 작성되는 요구사항 명세서가 가장 마지막에 검증하는 인수 테스트의 기준이 된다\"는 흐름을 파악할 수 있다. 실기 시험에서는 각 개발 단계와 테스트 단계를 짝짓는 문제, 또는 특정 테스트가 어느 개발 단계에서 유래한 결함을 검증하는지 묻는 문제가 출제될 수 있다."],["설명","V모델의 좌우 대응 관계 V모델은 왼쪽에 개발 단계(요구사항 분석 → 시스템 설계 → 모듈 설계 → 구현)를, 오른쪽에 이에 대응하는 테스트 단계(인수 테스트 ← 시스템 테스트 ← 통합 테스트 ← 단위 테스트)를 배치하여 V자 형태로 표현한 모델이다. 요구사항 분석은 인수 테스트와, 시스템 설계는 시스템 테스트와, 모듈 설계는 통합 테스트와, 구현(코딩)은 단위 테스트와 각각 대응한다."]]}]},{"t":"(2) 테스트 원칙 1~4","c":[{"t":"① 원칙: 계획부터·결함 발견","n":[["설명","계획 단계부터 시작, 결함 발견 활동첫 번째 원칙은 \"테스트는 계획 단계부터 한다\"는 것으로, 테스트는 코드가 완성된 이후가 아니라 요구사항 분석·설계 단계부터 함께 계획되어야 한다는 의미이다. 두 번째 원칙은 \"테스트는 결함을 밝히는 활동이다\"로, 테스트의 목적이 \"결함이 없다는 것을 증명\"하는 것이 아니라 \"존재하는 결함을 찾아내는 것\"에 있음을 강조한다. 세 번째 원칙은 \"완전한 테스트는 불가능하다\"로, 모든 입력값과 모든 실행 경로를 테스트하는 것은 현실적으로 불가능하다는 의미이다. 네 번째 원칙은 \"테스트는 상황(정황)에 따라 다르다\"로, 의료기기 소프트웨어와 게임 소프트웨어처럼 도메인의 특성에 따라 테스트 접근 방식이 달라져야 한다는 의미이다."]]},{"t":"② 결함 집중·살충제 패러독스","n":[["설명","결함 집중과 살충제 패러독스 다섯 번째 원칙은 \"결함 집중을 고려한다\"로, 파레토 법칙(80:20 법칙)에 따라 소수(약 20%)의 모듈에서 대다수(약 80%)의 결함이 발견되는 경향을 의미한다. 여섯 번째 원칙은 \"살충제 패러독스를 고려한다\"로, 동일한 테스트 케이스를 반복해서 사용하면 벌레(결함)가 그 살충제(테스트)에 내성이 생기듯 더 이상 새로운 결함을 찾아내지 못하게 되므로, 테스트 케이스를 주기적으로 검토하고 보완해야 한다는 의미이다. 일곱 번째 원칙은 \"오류-부재의 궤변(Absence of Errors Fallacy)을 고려한다\"로, 발견된 결함을 모두 제거하여 결함이 하나도 없는 소프트웨어를 만들었다고 하더라도, 사용자의 요구사항을 충족하지 못하거나 사용하기 불편하다면 여전히 실패한 시스템이라는 의미이다. 즉 결함 제거만으로는 좋은 소프트웨어가 완성되지 않는다는 점을 일깨워 주는 원칙이다."]]}]}]}]},{"t":"Ⅱ 테스트에 관한 격언과 소프트웨어 테스터","c":[{"t":"1. 테스트에 관한 격언","c":[{"t":"(1) 테스트 격언 1~2","c":[{"t":"① 완벽한 테스트 불가능","n":[["설명","완벽한 테스트의 불가능성 테스트에 관한 격언 중 첫 번째는 \"소프트웨어를 완벽하게 테스트하는 것은 불가능하다\"는 것이다. 무한에 가까운 입력값의 조합과 실행 경로를 모두 검증할 수 없기 때문에, 테스트는 항상 위험 관리의 관점에서 우선순위를 정해 수행해야 한다. 두 번째 격언은 \"소프트웨어 테스트는 위험을 수반하는 훈련이다\"는 것이다. 테스트를 아무리 철저히 수행해도 놓치는 부분이 있을 수 있다는 것을 인정하고, 위험이 큰 영역(핵심 기능, 자주 변경되는 모듈 등)에 테스트 자원을 우선 배분하는 전략적 사고가 필요하다는 의미이다."]]},{"t":"② 결함 부재 입증 불가","n":[["실제 사례","네 번째 격언은 \"발견한 결함이 많을수록 남아 있는 결함의 수도 많다\"는 것이다. 이는 통계적 경험에 기반한 것으로, 결함이 유난히 많이 발견되는 모듈은 추가적인 숨은 결함이 존재할 가능성이 높으므로 더 집중적인 테스트가 필요하다는 실무적 시사점을 담고 있다. 참고로 작업 일정이나 외부 요인(자연재해 등)으로 인해 발견한 모든 결함을 수정할 수 없는 경우도 있다는 점 역시 함께 언급된다."],["설명","결함 부재를 입증할 수 없음세 번째 격언은 \"테스트 작업으로 결함이 존재하지 않는다는 사실을 입증할 수 없다\"는 것이다. 테스트를 통과했다는 것은 \"발견된 결함이 없다\"는 의미일 뿐, \"결함이 전혀 존재하지 않는다\"는 것을 증명하지는 못한다는 냉정한 사실을 나타낸다."]]}]},{"t":"(2) 테스터의 역할","c":[{"t":"① 테스터: 결함 조기 발견·확인","n":[["설명","결함의 조기 발견과 확인 소프트웨어 테스터의 기본적인 역할은 결함을 발견하고, 가능한 한 빨리 발견하며, 발견된 결함이 올바르게 수정되었는지 확인하는 작업이다. 개발자가 놓치기 쉬운 관점에서 시스템을 검증하는 독립적인 시각이 테스터에게 요구된다. 테스터에게 요구되는 대표적인 능력은 탐구심과 문제 해결력이다. 단순히 주어진 테스트 케이스를 실행하는 것을 넘어, 시스템의 취약한 부분을 능동적으로 탐색하고 발견된 문제의 원인을 논리적으로 분석하는 역량이 중요하다."]]},{"t":"② 테스트 비용 절반 이상·자동화","n":[["설명","테스트 자동화가 중요해진 배경 소프트웨어 테스트는 소프트웨어 개발에 사용되는 총 시간과 비용의 절반 이상을 차지할 정도로 비중이 크다. 테스트의 정확성을 유지하면서 시간과 비용을 줄일 수 있는 자동화 도구의 중요성이 점점 커지고 있다. 테스트 자동화의 장점은 휴먼 에러(사람이 일으키는 실수)를 최소화하고, 인력과 시간을 절감하며, 향상된 테스트 품질을 보장한다는 것이다. 단점은 자동화 도구를 다루는 전문가의 양성이 필요하고, 이에 따른 고용 비용이 추가로 발생한다는 점이다."]]}]}]}]}]},{"t":"제2절 테스트 레벨(단위·통합·시스템 ·인수)","c":[{"t":"Ⅰ 단위 테스트와 통합 테스트","c":[{"t":"1. 단위 테스트(Unit Test)","c":[{"t":"(1) 단위 테스트의 개념","c":[{"t":"① 단위 테스트: 개발자·최초 수행","n":[["설명","단위 테스트란 단위 테스트는 작은 소프트웨어 단위(모듈, 컴포넌트, 함수 등)를 테스트하는 것으로, 개발자 자신에 의해 진행된다. V모델에서 가장 아래쪽(구현·코딩 단계에 대응)에 위치하는 테스트이며, 가장 먼저 수행되는 테스트 라는 점이 단위 테스트를 설명하는 핵심적인 특징이다. 단위 테스트는 구조적 테스트, 기능성 테스트, 리소스 관련 테스트, 강건성 테스트 등 특정 비기능성 테스트까지 포함하는, 개발자 자신에 의한 개발 단계의 테스트라고 이해할 수 있다."]]},{"t":"② 구조 기반 vs 명세 기반","n":[["시험 포인트","명세 기반 테스트 안에 블랙박스 테스트가 포함되는 관계이며, \"명세 기반 테스트가 곧 블랙박스 테스트다\"라고 동일시하는 것은 정확하지 않다. 블랙박스 테스트는 명세 기반 테스트에 속하는 여러 기법 중 하나라는 포함 관계를 정확히 구분하여 기억해야 하며, 이는 실기 시험에서 반복적으로 다루어지는 핵심 포인트이다."],["설명","구조 기반 테스트와 명세 기반 테스트 단위 테스트의 방법은 구조 기반과 명세 기반 두 가지로 나뉜다. 구조 기반 테스트는 제어의 흐름과 조건의 결정을 검증하는 것을 목적으로 하며(화이트박스 테스트에 해당), 명세 기반 테스트는 동등 분할과 경계값 분석을 통해 검증하는 것을 목적으로 한다."]]}]},{"t":"(2) 통합 테스트의 개념과 유형","c":[{"t":"① 통합 테스트: 모듈 간 상호작용","n":[["설명","통합 테스트란 통합 테스트는 모듈 사이의 인터페이스, 즉 통합된 컴포넌트 간의 상호작용을 테스트하기 위해 수행한다. \"상호작용\"이라는 단어가 통합 테스트를 정의하는 데 있어 가장 핵심적인 키워드이다. 대표적인 통합 테스트 방식에는 빅뱅, 상향식, 하향식, 샌드위치(혼합)식이 있다. 빅뱅 방식은 모든 모듈을 동시에 통합한 후 한꺼번에 테스트하는 방식이며, 상향식은 최하위 모듈에서 상위 모듈로 통합해 나가는 방식이고, 하향식은 반대로 최상위 모듈에서 하위 모듈로 내려가면서 통합하는 방식이다."]]},{"t":"② 상향식 통합·드라이버","n":[["시험 포인트","상향식 통합 테스트에서는 아직 개발되지 않은 상위 모듈을 대신하여 하위 모듈을 호출하고 결과를 확인하는 역할을 하는 임시 모듈인 드라이버(Driver)가 필요하다. \"상향식은 드라이버\"라는 짝을 정확히 암기해야 한다."],["시험 포인트","하향식 통합 테스트에서는 아직 개발되지 않은 하위 모듈을 대신하여 임시로 값을 반환하는 역할을 하는 스텁(Stub)이 필요하다. \"하향식은 스텁\"이라는 짝을 드라이버와 혼동하지 않도록 반드시 구분하여 암기해야 하며, 이는 실기 시험에서 매우 자주 출제되는 핵심 포인트이다."],["설명","상향식 통합과 드라이버(Driver)"]]}]}]}]},{"t":"Ⅱ 시스템 테스트와 인수 테스트","c":[{"t":"1. 시스템 테스트(System Test)","c":[{"t":"(1) 시스템 테스트의 개념","c":[{"t":"① 시스템 테스트: 성능·장애 포함","n":[["설명","시스템 테스트란 시스템 테스트는 통합된 단위 시스템의 기능이 전체 시스템 안에서 정상적으로 수행되는지를 테스트하는 것이다. 이 테스트에는 성능 및 장애 테스트가 포함되어 있다는 것이 가장 대표적인 특징이다. 시스템 테스트는 기능적 요구사항 테스트와 비기능적 요구사항 테스트로 나뉜다. 기능적 요구사항 테스트는 요구사항 명세서, 비즈니스 절차, 유스케이스 등에 대한 명세서 기반의 블랙박스 테스트로 수행되며, 비기능적 요구사항 테스트는 성능 테스트, 회복 테스트, 보안 테스트 등을 포함한다."]]},{"t":"② 성능·장애(회복)·보안 테스트","n":[["설명","성능 테스트와 장애(회복) 테스트 성능 테스트는 시스템이 요구되는 응답 시간, 처리량 등의 성능 기준을 만족하는지 검증하는 테스트이다. 장애(회복) 테스트는 시스템에 장애가 발생했을 때 정상적으로 복구될 수 있는지를 검증하는 테스트로, 시스템의 안정성을 확인하는 데 핵심적인 역할을 한다. 보안 테스트는 시스템이 비인가 접근이나 데이터 유출과 같은 보안 위협으로부터 안전한지를 검증하는 테스트이다. 시스템 테스트 단계에서 성능·회복·보안과 같은 비기능적 요구사항을 종합적으로 검증한다는 것이 단위·통합 테스트와 구분되는 특징이다."]]}]},{"t":"(2) 인수 테스트의 개념","c":[{"t":"① 인수 테스트: 최종 사용자·마지막","n":[["실제 사례","인수 테스트에는 사용자 인수 테스트, 운영상 인수 테스트, 계약 인수 테스트, 규정 인수 테스트, 그리고 널리 알려진 알파 테스트와 베타 테스트가 포함된다. 알파 테스트는 개발자의 통제된 환경(회사 내부)에서 실제 사용자가 참여하여 수행하고, 베타 테스트는 통제되지 않은 실제 사용 환경에서 다수의 사용자가 참여하여 수행한다는 차이가 있다."],["설명","인수 테스트란 인수 테스트는 최종 사용자와 업무에 따른 이해관계자 등이 수행하는, 개발 프로세스에서 가장 마지막에 실시되는 테스트이다. 개발된 제품의 운영 여부를 최종적으로 결정한다는 점에서 마지막 관문의 역할을 한다."]]},{"t":"② 고객 주도 최종 검증","n":[["실제 사례","인수 테스트는 고객(사용자)이 주도하여 최종적으로 자신들의 요구사항을 만족하는지 확인하는 테스트라는 점에서 다른 테스트 레벨과 구분된다. 개발자나 테스터가 아닌 실제 사용자의 관점에서 시스템을 평가 한다는 것이 핵심이다."],["시험 포인트","단위 테스트(개발자, 구조/명세 기반), 통합 테스트(모듈 간 상호작용, 빅뱅/상향식/하향식), 시스템 테스트(전체 시스템, 기능적/비기능적), 인수 테스트(사용자, 최종 승인)로 이어지는 V모델의 흐름을 각 테스트의 주체와 목적 중심으로 정리하여 암기하는 것이 실기 시험 대비에 효과적이다."],["설명","고객 주도의 최종 검증"]]}]}]}]}]},{"t":"제3절 테스트 케이스와 테스트 오라클","c":[{"t":"Ⅰ 테스트 케이스(Test Case)","c":[{"t":"1. 테스트 케이스의 개념과 작성 절차","c":[{"t":"(1) 테스트 케이스란","c":[{"t":"① 명세 기반 테스트의 산출물","n":[["시험 포인트","테스트 케이스는 실기 시험에서 작성 절차·순서를 빈칸으로 비워 놓거나 순서를 나열하는 문제로 자주 등장한다. 따라서 각 절차 단계의 명칭과 순서를 정확히 암기하는 것이 중요하다."],["설명","테스트 케이스의 정의 테스트 케이스는 명세 기반 테스트의 산출물을 의미한다. 특정한 목적을 달성하거나 요구사항을 위반하는지 확인하기 위해 개발된, 입력값·실행 조건·기대 결과 등으로 구성된 테스트 항목의 집합이라고 이해할 수 있다."]]},{"t":"② 작성 절차: 계획 검토·위험 평가","n":[["설명","테스트 계획 검토와 위험 평가 테스트 케이스 작성은 먼저 테스트 계획서를 검토하고 프로젝트의 위험을 평가하는 것에서 시작한다. 이 단계에서 테스트할 대상 기능의 우선순위와 위험도를 파악하여, 어느 부분에 더 많은 테스트 자원을 투입할지 결정한다. 이후 테스트 요구사항을 정의하고, 이를 기반으로 구체적인 테스트 케이스(입력값, 실행 절차, 기대 결과)를 작성한다. 마지막으로 작성된 테스트 케이스를 검토하고 필요에 따라 승인받는 절차를 거쳐 테스트 케이스 작성이 마무리된다."]]}]},{"t":"(2) 테스트 케이스의 필수 항목","c":[{"t":"① 식별자·사전조건·입력·기대결과","n":[["설명","식별자와 테스트 조건 테스트 케이스에는 각 케이스를 구분하는 식별자(ID), 테스트 대상이 되는 항목이나 기능, 그리고 테스트를 수행하기 위한 사전 조건(Precondition)이 포함되어야 한다. 사전 조건은 테스트를 시작하기 전에 시스템이 갖추어야 할 상태를 의미한다. 테스트 케이스에는 테스트를 실행할 때 사용할 구체적인 입력값과, 그 입력값에 대해 시스템이 반환해야 할기대 결과(Expected Result)가 반드시 포함되어야 한다. 기대 결과가 명확하지 않으면 테스트 실행 결과가 성공인지 실패인지 판단할 수 없기 때문에 이는 테스트 케이스의 핵심 요소이다."]]},{"t":"② 독립적·명확한 케이스·경계값","n":[["설명","명확하고 독립적인 케이스 작성각 테스트 케이스는 다른 케이스의 실행 결과에 의존하지 않고 독립적으로 실행 가능하도록 작성하는 것이 바람직하다. 또한 테스트 케이스의 목적과 절차가 다른 담당자가 보아도 명확하게 이해될 수 있도록 구체적으로 작성해야 한다. 정상적인 입력값에 대한 케이스뿐만 아니라, 경계값(최댓값, 최솟값 등)과 예외적인 상황(잘못된 입력, 빈 값등)에 대한 케이스도 함께 포함하여 작성해야 결함을 더 효과적으로 찾아낼 수 있다."]]}]}]}]},{"t":"Ⅱ 테스트 오라클(Test Oracle)","c":[{"t":"1. 테스트 오라클의 개념과 종류","c":[{"t":"(1) 테스트 오라클이란","c":[{"t":"① 결과 참/거짓 판단 기준값","n":[["시험 포인트","테스트 오라클은 참 오라클(True Oracle), 샘플링 오라클(Sampling Oracle), 휴리스틱 오라클(Heuristic Oracle), 일관성 검사 오라클(Consistent Oracle)의 네 가지로 구성된다. 실기 시험에서는 오라클의 세부 정의보다, 특정 설명이 이 네 가지 오라클 중 어느 것에 해당하는지(또는 해당하지 않는지) 구분하는 문제가 더 자주 출제된다."],["설명","테스트 오라클의 정의 테스트 오라클은 테스트의 결과가 참인지 거짓인지 판단하기 위해 사전에 정의된 값을 입력하여 비교하는 기법이다. 테스트를 실행한 결과가 옳은지 그른지 판정할 기준이 있어야 하는데, 그 기준을 제공하는 것이 오라클의 역할이다."]]},{"t":"② 참·샘플링·휴리스틱 오라클","n":[["설명","참 오라클과 샘플링 오라클참 오라클(True Oracle)은 모든 입력값에 대해 기대하는 결과를 제공하여 발생된 모든 오류를 검출할 수 있는 오라클이다. 샘플링 오라클(Sampling Oracle)은 전체 입력값 중 일부(샘플)에 대해서만 기대 결과를 제공하는 오라클로, 참 오라클보다 제한적이지만 현실적으로 자주 활용된다. 휴리스틱 오라클(Heuristic Oracle)은 샘플링 오라클을 개선한 방식으로, 샘플에 대한 기대 결과를 제공하고 나머지 입력값에 대해서는 추정(휴리스틱)을 통해 처리하는 오라클이다. 일관성 검사 오라클(Consistent Oracle)은 애플리케이션의 변경 전과 변경 후 결과값이 동일한지를 검증하여, 프로그램에 변화가 있었을 때 이전과 일관된 결과를 내는지 확인하는 오라클이다."]]}]},{"t":"(2) 테스트 도구의 평가 방법","c":[{"t":"① 테스트 도구 도입 고려사항","n":[["실제 사례","테스트 도구는 수행하는 활동에 따라 정적 분석 도구(코드를 실행하지 않고 분석), 동적 분석 도구(코드를 실행하며 분석), 테스트 케이스 생성 도구, 테스트 실행 도구, 성능 테스트 도구 등으로 분류할 수 있다. 각 도구가 어떤 테스트 레벨과 활동에 사용되는지 연결지어 이해하는 것이 실무 활용에 도움이 된다."],["설명","테스트 도구 도입 시 고려사항 테스트 도구를 도입할 때는 도구가 지원하는 테스트 활동의 범위, 기존 개발 환경과의 통합 가능성, 사용의 편의성과 학습 곡선, 도구의 유지보수 및 지원 정책 등을 종합적으로 고려해야 한다."]]},{"t":"② 테스트 케이스 내 오라클 위치","n":[["실제 사례","테스트 케이스를 구성하는 \"기대 결과\" 항목이 바로 테스트 오라클의 개념이 실제로 적용되는 지점이다. 즉 테스트 케이스를 작성할 때 기대 결과를 어떤 오라클 방식(참/샘플링/휴리스틱/일관성 검사)으로 정의할 것인지가 케이스 설계의 중요한 의사결정 사항이 된다."],["실제 사례","테스트 대상 기능의 중요도가 매우 높고 모든 경우의 수를 검증해야 한다면 참 오라클에 가까운 접근이 필요하지만, 현실적으로 시간과 비용의 제약이 있다면 샘플링이나 휴리스틱 오라클을 활용하는 것이 실무에서는 더 일반적이다. 회귀 테스트(변경 후 재검증)에서는 일관성 검사 오라클이 특히 유용하게 활용된다."],["설명","테스트 케이스에서 오라클의 위치"]]}]}]}]}]},{"t":"제4절 결함(Defect)의 이해와 분류","c":[{"t":"Ⅰ 결함 관련 용어의 구분","c":[{"t":"1. 에러·오류(폴트)·실패·결함의 정의","c":[{"t":"(1) 에러(Error)와 오류/폴트(Fault)","c":[{"t":"① 에러(사람)·오류/폴트(코드)","n":[["설명","에러(Error)의 정의 에러는 소프트웨어 개발 또는 유지보수 수행 중에 발생한 부정확한 결과를 의미한다. 개발자의 실수로 발생하거나, 명세서를 잘못 이해했거나, 서브루틴의 기능을 오해하는 등의 원인으로 발생하는, 사람(휴먼 에러)에 의한 원인에 초점을 맞춘 용어이다. 오류(Fault)는 프로그램 코드상에 존재하는 것으로, 비정상적인 프로그램과 정상적인 프로그램 간의 버전 차이 또는 코드의 누락된 부분을 의미한다. 에러가 사람의 실수라는 원인에 초점을 둔다면, 폴트는 그 결과로 코드에 남게 되는 구체적인 흔적(잘못된 코드, 누락된 코드)에 초점을 둔다는 차이가 있다."]]},{"t":"② 실패(실행 결과 차이)·결함","n":[["설명","실패(Failure)의 정의 실패는 정상적인 프로그램과 비정상적인 프로그램의 실행 결과의 차이를 의미한다. 에러가 개발·유지보수 \" 수행 중\"에 발생하는 부정확한 결과라면, 실패는 프로그램을 \"실행\"했을 때 드러나는 기대값과 실제값의 차이 라는 점에서 시점의 차이가 있다. 결함은 버그, 에러, 오류, 실패, 프로그램 실행에 대한 문제점 등을 모두 포함하는 가장 포괄적인 개념이다. 즉에러·폴트·실패는 각각 결함이 발생하는 과정의 서로 다른 단계나 관점을 나타내는 용어이며, 결함은 이 모든 것을 아우르는 상위 개념이라는 점을 정확히 이해해야 한다."]]}]},{"t":"(2) 결함으로 판단하는 세 가지 기준","c":[{"t":"① 명시 동작 미수행·비명시 수행","n":[["설명","명시된 동작의 미수행·비명시 동작의 수행 결함으로 판단하는 첫 번째 기준은 \"기능 명세에 가능하다고 명시된 동작을 수행하지 않은 경우\"이다. 두 번째 기준은 \"불가능하다고 명시된 동작을 수행하는 경우\"이며, 세 번째 기준은 \"명시되어 있지 않은 동작을 수행하거나, 명시되어 있지 않지만 수행해야 할 동작을 수행하지 않은 경우\"이다. 네 번째 기준은 \"테스터가 볼 때 문제가 있다고 판단되는 경우\"로, 명세서에 명시적으로 기술되지 않았더라도 사용자 관점에서 불편하거나 비정상적으로 보이는 동작도 결함으로 분류될 수 있다는 것을 의미한다. 결함은이 네 가지 기준을 모두 포함하는 개념이라는 점을 기억해야 한다."]]},{"t":"② 에러→폴트→실패 흐름","n":[["시험 포인트","개발자의 실수(에러) → 코드에 남는 흔적(폴트/오류) → 실행 시 드러나는 차이(실패) → 이 모든 것을 포괄하는 개념(결함)이라는 흐름으로 네 가지 용어를 순서대로 정리하여 암기하면 혼동을 줄일 수 있다."],["시험 포인트","실기 시험에서 결함 관련 용어를 주관식으로 작성할 때 영어로 작성해야 하는 경우가 있으므로, Error, Fault, Failure, Defect(Bug)의 정확한 스펠링까지 함께 암기해 두어야 한다."],["설명","네 가지 용어의 흐름 정리"]]}]}]}]},{"t":"Ⅱ 결함의 분류와 심각도","c":[{"t":"1. 결함의 4가지 분류","c":[{"t":"(1) 시스템 결함과 기능 결함","c":[{"t":"① 시스템 결함(DB 에러)·기능 결함","n":[["설명","시스템 결함(System Defect) 시스템 결함은 비정상적인 시스템 종료, 응답 시간 초과, 데이터베이스 에러 등을 포함하는 결함 유형이다. 데이터베이스와 관련된 오류가 시스템 결함에 포함된다는 것을 기억해야 한다. 기능 결함은 사용자의 요구사항이 반영되지 않거나 일치하지 않는, 즉 기능 자체에 대한 결함을 의미한다. 요구사항 오류, 부정확한 비즈니스 로직, 스크립트 오류, 다른 시스템과의 연동 시 발생하는 호환성 결여 등이 여기에 포함된다."]]},{"t":"② GUI 결함: 화면 시각적 오류","n":[["실제 사례","문서 결함은 기획자·사용자·개발자 간의 커뮤니케이션(의사소통)에 대한 기록이 원활하지 않을 때발생하는 결함을 의미한다. 요구사항 명세서나 설계 문서의 내용이 실제 구현과 다르거나 모호하게 작성된 경우가 대표적인 예이다."],["설명","GUI 결함(사용자 인터페이스 결함) GUI 결함은 사용자 인터페이스에서 눈에 보이는 오류를 의미한다. 화면에 표시되는 텍스트, 버튼, 레이아웃 등에서 발견되는 시각적인 문제들이 여기에 해당한다."]]}]},{"t":"(2) 심각도 레벨의 구분","c":[{"t":"① 심각도 High·Medium·Lo w","n":[["실제 사례","심각도(Severity)는 결함이 시스템에 미치는 기술적 영향의 크기를 의미하며, 우선순위(Priority)는 그 결함을 얼마나 빨리 수정해야 하는지에 대한 순위를 의미한다는 점에서 개념적으로 구분된다. 실무에서는 심각도가 높지만 우선순위가 낮은 경우(예: 매우 드물게 발생하는 심각한 오류)와, 심각도는 낮지만 우선순위가 높은 경우(예: 첫 화면에 노출되는 사소한 오타)가 모두 존재할 수 있다."],["설명","심각도의 세 가지 레벨 결함의 심각도는 하이(High), 미디움(Medium), 로우(Low)의 세 단계로 표시된다. 심각도는 결함이 시스템에 미치는 영향의 크기를 나타내는 지표로, 결함 관리 프로세스에서 어떤 결함을 우선적으로 수정해야 하는지 결정하는 기준이 된다."]]},{"t":"② 결함 분류로 담당 팀 판단","n":[["쉬운 예","예를 들어 결제 시스템에서 결제가 완전히 실패하는 결함은 하이(High) 심각도로 분류되어 즉시 수정이 필요하지만, 화면 하단의 문구가 미세하게 정렬이 어긋난 결함은 로우(Low) 심각도로 분류되어 다음 배포 주기에 수정하는 방식으로 처리하는 것이 일반적인 실무 관행이다."],["설명","결함 분류의 실무적 의의 결함을 시스템·기능·GUI·문서 결함으로 분류하는 것은, 어느 팀(개발팀, 기획팀, 디자인팀, 문서 관리팀)이 해당 결함을 담당해야 하는지 신속하게 판단하는 데 도움을 준다."]]}]}]}]}]},{"t":"제5절 결함 관리 프로세스와 코드 검토 기법","c":[{"t":"Ⅰ 결함 관리 프로세스와 상태 추적","c":[{"t":"1. 결함 관리 프로세스의 7단계","c":[{"t":"(1) 결함 관리 계획과 기록","c":[{"t":"① 관리 계획 수립·DB 기록","n":[["설명","결함 관리 계획 수립 결함 관리 프로세스의 첫 단계는 결함 관리 계획을 수립하는 것이다. 이 단계에서 결함을 어떤 기준으로 분류하고, 누가 검토·수정을 담당하며, 어떤 도구로 추적할 것인지에 대한 전체적인 방침을 정한다. 두 번째 단계는 발견된 결함을 데이터베이스에 기록하는 것이다. 결함의 내용, 발견 위치, 재현 절차, 심각도 등의 정보를 체계적으로 기록하여 이후 담당자가 참고할 수 있도록 한다."]]},{"t":"② 결함 검토와 수정","n":[["실제 사례","세 번째 단계는 기록된 결함 내용을 개발자에게 전달하기 위해 검토하는 것이고, 네 번째 단계는 개발자가 실제로 결함을 수정하는 것이다. 다섯 번째 단계는 수정된 내용을 다시 확인(재확인)하는 것으로, 결함이 실제로 해결되었는지 테스트를 통해 검증한다."],["설명","검토와 수정"]]}]},{"t":"(2) 결함 상태의 흐름","c":[{"t":"① 결함 등록과 할당","n":[["시험 포인트","결함의 상태 추적은 결함이 등록(Open)된 뒤 담당자에게 할당(Assigned)되는 것으로 시작한다. 결함의 등록과 할당에 대한 부분이 실기 시험에서 자주 출제되는 대표적인 내용이므로, 각 상태의 정확한 영문 명칭과 순서를 기억해야 한다."],["설명","등록과 할당"]]},{"t":"② 종료(Closed)·재오픈(Reo pened)","n":[["설명","종료(Closed) 수정 확인 테스트를 통과하면 해당 결함은 종료(Closed) 상태가 된다. 종료된 결함은 해당 결함 관리 사이클이 완결되었음을 의미한다. 종료된 결함이라도 이후 동일한 문제가 다시 발생하는 것이 확인되면 재오픈(Reopened) 상태로 되돌아갈수 있다. 이처럼 결함 상태는 등록 → 할당 → 수정 → 확인 → 종료(필요시 재오픈)의 순환 구조를 가진다는 것을 이해해야 한다."]]}]}]}]},{"t":"Ⅱ 코드 검토 기법(인스펙션·워크스루 )","c":[{"t":"1. 소프트웨어 인스펙션과 코드 인스펙션","c":[{"t":"(1) 소프트웨어 인스펙션의 개념","c":[{"t":"① 소프트웨어 ⊃ 코드 인스펙션","n":[["설명","소프트웨어 인스펙션이란 소프트웨어 인스펙션은 코드 인스펙션뿐만 아니라 설계 및 설계 산출물까지 포괄하는, 프로그램 코드 검토 기법의 상위 개념이다. 코드 인스펙션은 소프트웨어 인스펙션에 포함되는 하위 개념이라는 포함 관계를 정확히 이해해야 한다. 코드 인스펙션은 매우 효과적인 테스트 방법으로, 다른 테스트 방법으로 대처할 수 없을 정도로 중요한 기법중 하나이다. 상당한 시간이 필요하지만, 적절히 수행하면 결함의 90%까지 차단할 수 있는 것으로 알려져 있어 통계적으로 결함 검출 용도가 매우 높은 검토 기법이다."]]},{"t":"② 조기 결함 발견 비용 절감","n":[["설명","조기 결함 발견의 비용 절감 효과 인스펙션을 수행해야 하는 비즈니스적 이유 중 하나는, 결함을 빨리 찾을수록 수정 비용이 절감되는 효과가 있기 때문이다. 개발 초기 단계에서 발견된 결함은 배포 이후 발견된 결함보다 수정 비용이 훨씬 저렴하다는 것이 소프트웨어 공학의 일반적인 원리이다. 인스펙션은 업무의 집중도를 높이고, 다른 팀원에 대한 교육 효과를 제공하며, 제품의 재설계(리엔지니어링)를 통해 품질을 향상시키는 효과도 있다. 이러한 여러 효과 때문에 인스펙션은 단순히 결함을 찾는 것을 넘어 조직 전체의 개발 역량 향상에도 기여한다."]]}]},{"t":"(2) 참여자와 산출물의 차이","c":[{"t":"① 인스펙션 동료 vs 워크스루 전문가","n":[["설명","참여자의 차이 인스펙션(Inspection)의 참여자는 동료(Peer)들이며, 워크스루(Walkthrough)의 참여자는 기술 전문가 및동료들이다. 이 차이는 워크스루가 좀 더 폭넓은 전문성을 가진 참여자를 포함할 수 있음을 시사한다. 워크스루는 작성자(저자)가 검토 회의를 주도하며, 워크스루의 결과로 보고서와 결함 리스트가 산출된다. 워크스루는 다른 말로 \"검토 회의\"라고도 부른다는 점을 함께 기억해 두면 좋다."]]},{"t":"② 체크리스트 사용 여부 차이","n":[["시험 포인트","인스펙션은 체크리스트를 사용하는 반면, 워크스루는 체크리스트를 사용하지 않는다는 것이 두기법을 구분하는 핵심적인 차이점이다. 실기 시험에서는 이 차이를 묻는 문제가 자주 출제되므로 반드시 기억해야 한다."],["설명","체크리스트 사용 여부의 차이"]]}]}]}]}]},{"t":"제6절 소프트웨어 형상 관리(SCM)","c":[{"t":"Ⅰ 형상 관리의 개념과 구성요소","c":[{"t":"1. 형상 관리(SCM)란","c":[{"t":"(1) 형상 관리의 정의","c":[{"t":"① SCM: 모든 산출물 변경 관리","n":[["설명","소프트웨어 형상 관리의 개념 소프트웨어 형상 관리(SCM, Software Configuration Management)는 모든 출력물, 즉 컴퓨터 프로그램과 이에 대한 문서 등 소프트웨어 형상의 변경에 대한 모든 형상을 보호하는 활동을 의미한다. 소스 코드뿐만 아니라 설계 문서, 계획서 등 프로젝트의 모든 산출물이 형상 관리의 대상이 된다. 형상 관리는 눈에 보이게 만들어 주는 모든 과정, 즉 소프트웨어 개발 과정에서 생성되는 모든 산출물을 체계적으로 식별하고 통제하는 활동이다. SCI(Software Configuration Item, 소프트웨어 형상 항목)는 형상관리의 대상이 되는 개별 항목들을 의미하며, 명세서, 계획서, 흐름도(플로차트), 원시 코드 등이 대표적인 형상 항목이다."]]},{"t":"② 기준선(Baseline) 변경 통제","n":[["설명","기준선의 개념 기준선(Baseline)은 정식으로 검토되고 승인된 특정 시점의 형상 항목으로, 이후의 개발 및 변경에 대한 근거로 사용된다. 기준선이 설정되면 이후의 모든 변경은 정해진 절차를 통해서만 가능하도록 통제된다. 기준선은 변경을 통제하거나 도와주는 역할을 하며, 정해진 절차를 통해서만 변경이 가능하다는 원칙을 나타낸다. 형상 항목이 세부적인 산출물 하나하나를 의미한다면, 기준선은 그 시점의 산출물 전체를 간결하게 대표하는 승인된 버전이라고 이해할 수 있다."]]}]},{"t":"(2) 형상 식별과 버전 관리","c":[{"t":"① 형상 식별·버전 관리","n":[["설명","형상 식별(Configuration Identification) 형상 식별은 형상 관리 대상이 되는 항목을 정의하고 식별하는 활동이다. 어떤 산출물이 형상 관리의 대상이 되는지 명확히 정의하는 것이 형상 관리의 첫걸음이다. 버전 관리는 형상 항목이 변경될 때마다 그 이력을 체계적으로 관리하는 활동이다. 이를 통해 특정 시점의 버전으로 되돌리거나, 여러 버전 간의 차이를 비교하는 것이 가능해진다."]]},{"t":"② 변경 통제·형상 감사·상태 보고","n":[["설명","변경 통제(Change Control) 변경 통제는 형상 항목에 대한 변경 요청을 검토하고 승인하는 절차를 관리하는 활동이다. 임의로 산출물을 변경하는 것을 방지하고, 정해진 절차를 거친 변경만 반영되도록 통제한다. 형상 감사는 형상 항목이 요구사항에 맞게 제대로 구현되었는지 검토하는 활동이며, 상태 보고는 형상 항목의 현재 상태와 변경 이력에 대한 정보를 관계자에게 보고하는 활동이다. 형상 식별, 버전 관리, 변경 통제, 형상 감사, 상태 보고의 다섯 가지가 형상 관리의 주요 활동으로 정리된다."]]}]}]}]},{"t":"Ⅱ 형상 관리 도구","c":[{"t":"1. 대표적인 형상 관리 도구","c":[{"t":"(1) CVS와 SVN","c":[{"t":"① CVS 초창기·SVN 중앙 저장소","n":[["설명","CVS(Concurrent Versions System) CVS는 초창기부터 널리 사용되어 온 형상 관리 도구로, 여러 개발자가 동시에 소스 코드를 수정할 수 있도록 지원한다. 다만 최신 도구들에 비해 브랜치나 파일 이름 변경과 같은 기능이 상대적으로 제한적이라는 한계가 있다. SVN은 CVS의 여러 단점을 개선한 형상 관리 도구로, 중앙 저장소(Repository) 방식을 사용하여 모든 버전 이력을 중앙 서버에서 관리한다. 파일과 디렉터리의 이름 변경, 이동 등의 작업을 CVS보다 안정적으로 지원한다."]]},{"t":"② Git 분산 버전 관리(DVCS)","n":[["시험 포인트","CVS, SVN, Git이라는 세 가지 대표적인 형상 관리 도구는 시대 순으로 등장하며 발전해 온 도구 들로, 각 도구의 특징과 차이를 이해하는 것이 중요하다. 특히 Git의 분산 저장소 개념은 실기 시험뿐만 아니라 산업기사·기사 시험에도 자주 등장하는 핵심 개념이므로 확실히 기억해 두어야 한다."],["설명","Git Git은 분산 버전 관리 시스템(DVCS)으로, 중앙 저장소뿐만 아니라 각 개발자의 로컬 저장소에도 전체 버전 이력이 복제되어 저장된다는 점이 CVS·SVN과 근본적으로 다르다. 브랜치 생성과 병합이 매우 가볍고 빠르게 수행되어, 현재 가장 널리 사용되는 형상 관리 도구이다."]]}]},{"t":"(2) 형상 관리가 테스트에 미치는 영향","c":[{"t":"① 버전 비교로 회귀 테스트","n":[["실제 사례","결함이 발견되었을 때, 형상 관리 이력을 통해 어느 버전(커밋)에서 해당 결함이 처음 발생했는지 추적할 수 있다면 원인 분석이 훨씬 수월해진다. 이 때문에 실무에서는 결함 관리 도구와 형상 관리 도구를 연동하여 사용하는 경우가 많다."],["설명","회귀 테스트와 버전 관리 형상 관리 도구를 통해 이전 버전과 현재 버전을 비교할 수 있으므로, 코드 변경 이후 기존 기능이 정상적으로 동작하는지 확인하는 회귀 테스트(Regression Test)를 효율적으로 수행할 수 있다. 어떤 부분이 변경되었는지 명확히 파악할 수 있어야 회귀 테스트의 범위를 효과적으로 좁힐 수 있다."]]},{"t":"② 형상 관리 구성요소 요약","n":[["시험 포인트","형상 항목(SCI)은 세부 산출물, 기준선(Baseline)은 승인된 특정 시점의 버전, 형상 관리 도구 (CVS/SVN/Git)는 이 모든 것을 관리하는 수단이라는 세 가지 개념의 관계를 정리하여 암기해야 한다."],["시험 포인트","형상 식별 → 버전 관리 → 변경 통제 → 형상 감사 → 상태 보고로 이어지는 다섯 가지 주요 활동의 순서와 각각의 역할을 정확히 구분하여 기억하는 것이 실기 시험 대비에 효과적이다."],["설명","형상 관리 구성요소 요약"]]}]}]}]}]},{"t":"제7절 블랙박스 테스트 기법 심화","c":[{"t":"Ⅰ 동등 분할과 경계값 분석","c":[{"t":"1. 동등 분할 기법(Equivale nce Partitioning)","c":[{"t":"(1) 동등 분할의 개념","c":[{"t":"① 클래스별 대표값 하나 테스트","n":[["쉬운 예","동등 분할의 목적은 모든 입력값을 하나하나 테스트하는 비효율을 없애고, 적은 수의 테스트 케이스로도 넓은 범위의 결함을 발견할 수 있도록 하는 것이다. 예를 들어 나이 입력값이 1세부터 120세까지 유효하다고할 때, 유효 클래스(1~120)와 무효 클래스(0 이하, 121 이상)로 나누어 각각 대표값을 선정해 테스트한다."],["설명","동등 분할이란 동등 분할 기법은 입력 조건을 유효한 값과 유효하지 않은 값으로 나누어, 각 부분 집합(클래스)에서 대표값을 하나씩만 선정하여 테스트하는 명세 기반 테스트 기법이다. 같은 클래스 안의 모든 값은 동일한 결과를 낼 것이라고 가정하기 때문에, 클래스마다 대표값 하나만 테스트해도 충분하다는 논리에 근거한다."]]},{"t":"② 성적 등급 4클래스 예시","n":[["실제 사례","유효 클래스뿐만 아니라 음수 점수, 100점을 초과하는 점수와 같은 무효 클래스에 대한 테스트도 반드시 포함해야 한다. 실제 실기 시험에서는 \"동등 분할 기법을 적용하여 테스트 케이스를 작성하시오\"와 같은 문제가 출제될 때, 유효 클래스와 무효 클래스를 모두 고려했는지가 채점의 핵심 포인트가 된다."],["설명","성적 등급 판정 시스템의 동등 분할 점수가 90점 이상이면 A, 80점 이상 90점 미만이면 B, 70점 이상 80점 미만이면 C, 70점 미만이면 F로 판정하는 시스템이 있다고 하자. 이 경우 동등 분할 클래스는 [90~100], [80~89], [70~79], [0~69]의 네 가지로 나뉘며, 각 클래스에서 95점, 85점, 75점, 50점과 같은 대표값을 하나씩 선정하여 네 개의 테스트 케이 스만으로 전체 판정 로직을 검증할 수 있다."]]}]},{"t":"(2) 경계값 분석의 개념","c":[{"t":"① 경계 부근 값 집중 테스트","n":[["쉬운 예","일반적으로 경계값을 선정할 때는 경계값 자체, 경계값보다 1 작은 값, 경계값보다 1 큰 값의 세 가지를 함께 테스트한다. 예를 들어 나이 입력 범위가 1~120세라면, 0, 1, 2(하한 경계 주변)와 119, 120, 121(상한 경계 주변)을 테스트 케이스로 선정한다."],["설명","경계값 분석이란 경계값 분석은 입력 조건의 경계(최솟값, 최댓값 부근)에서 결함이 자주 발생한다는 경험적 사실에 근거하여, 경계 부근의 값들을 집중적으로 테스트하는 기법이다. 동등 분할이 클래스 내부의 대표값 하나를 선택하는 것과 달리, 경계값 분석은 클래스의 경계선 자체에 초점을 맞춘다는 차이가 있다."]]},{"t":"② 할인율 10만·30만원 경계 예시","n":[["실제 사례","실무에서는 동등 분할로 테스트 케이스의 전체 구조를 설계한 뒤, 각 클래스의 경계에 대해서만 경계값 분석을 추가로 적용하는 방식으로 두 기법을 함께 사용하는 경우가 많다. 실기 시험에서도 두 기법의 정의를 명확히 구분하면서도, 실제 문제 풀이에서는 함께 적용하는 유형의 문제가 자주 출제된다."],["설명","할인율 적용 시스템의 경계값 분석 구매 금액이 10만원 이상이면 5% 할인, 30만원 이상이면 10% 할인을 적용하는 시스템이라면, 99,999원, 100,000원, 100,001원(첫 번째 경계)과 299,999원, 300,000원, 300,001원(두 번째 경계)을 테스트 케이스로 선정하여 경계 부근에서 할인율이 정확히 전환되는지 검증해야 한다."]]}]}]}]},{"t":"Ⅱ 결정 테이블과 상태 전이 테스트","c":[{"t":"1. 결정 테이블 테스트(Decisi on Table Testing)","c":[{"t":"(1) 결정 테이블의 개념과 구성","c":[{"t":"① 조건 조합별 액션 표 정리","n":[["설명","결정 테이블이란 결정 테이블 테스트는 여러 개의 조건과 그 조건들의 조합에 따라 달라지는 액션(결과)을 표 형태로 정리하여 테스트 케이스를 도출하는 기법이다. 조건이 여러 개 얽혀 있는 복잡한 비즈니스 로직을 검증할 때 특히 유용하다. 결정 테이블은 조건 항목(Condition Stub), 조건 항목의 참/거짓 조합(Condition Entry), 액션 항목 (Action Stub), 액션의 수행 여부(Action Entry)의 네 부분으로 구성된다. 조건이 n개 있으면 이론적으로 2의 n제곱 가지의 조합이 발생할 수 있다."]]},{"t":"② 회원 등급별 배송비 예시","n":[["쉬운 예","예를 들어 \"회원 등급이 VIP인가\"와 \"구매 금액이 5만원 이상인가\"라는 두 가지 조건이 있다면, 조건의 조합은 (VIP, 5만원 이상), (VIP, 5만원 미만), (일반, 5만원 이상), (일반, 5만원 미만)의 네 가지가 되고, 각조합에 대해 \"무료배송\" 또는 \"배송비 부과\"라는 액션이 결정된다. 이 네 가지 조합 각각이 하나의 테스트 케이스가 된다."],["실제 사례","결정 테이블은 조건이 누락되거나 중복되는 것을 표 형태로 한눈에 확인할 수 있게 해주므로, 복잡한 조건 분기 로직을 가진 시스템(예: 보험료 산정, 세금 계산, 포인트 적립 규칙)을 검증할 때 실무에서 널리 활용된다."],["설명","회원 등급별 배송비 결정 테이블"]]}]},{"t":"(2) 상태 전이 테스트(State Transition Testing)","c":[{"t":"① 상태 전이 테스트: 이벤트별 전환","n":[["설명","상태 전이 테스트란 상태 전이 테스트는 시스템이 여러 상태(State)를 가지고 있고, 특정 이벤트(입력)에 의해 한 상태에서 다른 상태로 전환(Transition)되는 시스템을 테스트하는 기법이다. 로그인 상태, 주문 처리 상태(주문접수-결제완 료-배송중-배송완료) 등이 대표적인 예이다. 상태 전이 테스트는 상태 전이 다이어그램(또는 상태 전이표)을 기반으로, 각 상태에서 가능한 모든 전이와 불가능한 전이(잘못된 이벤트가 발생했을 때 시스템이 올바르게 거부하는지)를 모두 테스트 케이스로 도출해야한다."]]},{"t":"② 유스케이스 테스트: 액터 시나리오","n":[["시험 포인트","동등 분할·경계값 분석(입력값 중심), 결정 테이블(조건 조합 중심), 상태 전이(상태 변화 중심), 유스케이스(사용자 시나리오 중심)의 네 가지 블랙박스 기법은 각각 초점을 두는 대상이 다르므로, 실기 시험에서 주어진 문제 상황(시나리오)을 읽고 어떤 기법이 가장 적합한지 판단하는 연습이 필요하다."],["설명","유스케이스 테스트란 유스케이스 테스트는 시스템과 사용자(액터) 간의 상호작용 시나리오인 유스케이스를 기반으로 테스트 케이스를 도출하는 기법이다. 유스케이스에 명시된 기본 흐름(정상 시나리오)뿐만 아니라 대안 흐름과 예외 흐름까지 모두 테스트 대상으로 포함시킨다."]]}]}]}]}]},{"t":"제8절 화이트박스 테스트 기법과 커버리지","c":[{"t":"Ⅰ 화이트박스 테스트의 개념과 기초 경로 검사","c":[{"t":"1. 화이트박스 테스트란","c":[{"t":"(1) 화이트박스 테스트의 개념","c":[{"t":"① 소스 코드 보는 구조 기반 기법","n":[["설명","화이트박스 테스트의 정의 화이트박스 테스트는 프로그램 내부의 소스 코드, 제어 흐름, 자료 구조 등을 직접 보면서 테스트 케이스를 설계하는 구조 기반 테스트 기법이다. 블랙박스 테스트가 내부 구조를 몰라도 되는 것과 달리, 화이트박스 테스트는 반드시 소스 코드를 이해하고 있어야 수행할 수 있다. 화이트박스 테스트의 목적은 프로그램 내부의 모든 논리적 경로(코드의 분기, 반복문, 조건문)가 최소 한 번이상 실행되도록 테스트하여, 코드 내부에 존재하는 논리적 오류를 찾아내는 것이다. 단위 테스트 단계에서 주로 사용되는 기법이다."]]},{"t":"② 기초 경로 검사·McCabe 순환 복잡도","n":[["설명","기초 경로 검사의 개념 기초 경로 검사는 흐름 그래프(Flow Graph)의 논리적 복잡도를 계산하고, 이 복잡도를 실행 경로의 기초 집합을 정의하는 데 사용하는 화이트박스 테스트 기법이다. 맥케이브(McCabe)가 제안한 순환 복잡도(Cyclomatic Complexity) 개념에 기반한다. 순환 복잡도는 흐름 그래프의 에지(Edge) 수에서 노드(Node) 수를 빼고 2를 더하는 방식(V(G) = E - N + 2)으로 계산하며, 이 값은 해당 프로그램을 완전히 테스트하기 위해 필요한 최소한의 독립적인 테스트 경로 수를 의미한다. 순환 복잡도가 높을수록 코드가 복잡하고 결함이 발생할 가능성이 높다고 해석된다."]]}]},{"t":"(2) 화이트박스 테스트 기법의 분류","c":[{"t":"① 구조 기반 테스트 기법 종류","n":[["시험 포인트","화이트박스 테스트는 크게 기초 경로 검사(순환 복잡도 기반), 제어 구조 테스트(조건/루프/데이터 흐름 검증), 커버리지 기반 테스트(구문/결정/조건 커버리지)의 세 갈래로 분류할 수 있다. 실기 시험에서는이 중 커버리지 기반 테스트가 계산 문제 형태로 가장 자주 출제된다."],["설명","구조 기반 테스트 기법의 종류"]]},{"t":"② 루프 테스트: 반복 횟수 경계","n":[["쉬운 예","예를 들어 게시판의 페이지네이션 기능에서 게시물이 0건, 1건, 페이지 크기와 정확히 일치하는 건수, 페이지 크기보다 하나 많은 건수일 때 각각 화면이 올바르게 표시되는지를 검증하는 것이 루프 테스트의 대표적인 적용 사례이다."],["설명","루프 테스트의 개념 루프 테스트는 반복문(for, while 등)의 실행 횟수에 따른 오류를 검증하는 화이트박스 테스트 기법이다. 반복 횟수가 0회, 1회, 2회, 그리고 최댓값보다 하나 적은 횟수, 최댓값, 최댓값을 초과하는 횟수 등 다양한 경우를 테스트하여 반복 구조의 경계 조건에서 발생하는 오류를 찾아낸다."]]}]}]}]},{"t":"Ⅱ 화이트박스 커버리지 기법","c":[{"t":"1. 구문 커버리지와 결정 커버리지","c":[{"t":"(1) 구문 커버리지(Statemen t Coverage)","c":[{"t":"① 구문 커버리지: 가장 약한 기준","n":[["쉬운 예","구문 커버리지는 모든 코드 라인이 실행되었는지만 확인할 뿐, 조건문의 참/거짓 분기를 모두 확인하 지는 못한다는 한계가 있다. 예를 들어 if문의 조건이 항상 참으로만 평가되어도 해당 구문이 실행되기만 하면 구문 커버리지는 만족되므로, 더 강한 커버리지 기준이 추가로 필요하다."],["설명","구문 커버리지의 개념 구문 커버리지는 프로그램 내의 모든 실행 가능한 구문(코드 라인)을 최소 한 번 이상 실행하는 테스트 케이스를 설계하는 기법이다. 화이트박스 커버리지 기법 중 가장 기본적이고 약한(느슨한) 수준의 커버리지 기준이다."]]},{"t":"② 결정(분기)·조건 커버리지","n":[["설명","결정 커버리지(Decision/Branch Coverage) 결정 커버리지(분기 커버리지)는 프로그램 내의 모든 조건문에서 참(True)과 거짓(False) 분기가 각각 최소한 번씩 실행되도록 테스트 케이스를 설계하는 기법이다. 구문 커버리지보다 강한 기준으로, if문·while문 등의 모든 분기 방향을 검증한다. 조건 커버리지는 조건문 내부에 여러 개의 개별 조건이 있을 때, 각 개별 조건이 참과 거짓을 각각 한 번씩 갖도록 테스트 케이스를 설계하는 기법이다. 조건 커버리지를 만족한다고 해서 반드시 결정 커버리지까지 만족하는 것은 아니라는 점에 유의해야 한다."]]}]},{"t":"(2) 조건/결정 커버리지","c":[{"t":"① 조건/결정 커버리지: 둘 다 만족","n":[["쉬운 예","예를 들어 \"if (A && B)\"라는 조건문이 있을 때, 결정 커버리지는 전체 식(A && B)의 결과가 참/거짓 각각 한 번씩 나오면 되지만, 조건 커버리지는 A와 B 각각이 참/거짓을 모두 가져야 하고, 조건/결정 커버리지는 이 두 조건을 모두 동시에 만족시켜야 한다."],["설명","조건/결정 커버리지의 개념 조건/결정 커버리지는 결정 커버리지와 조건 커버리지를 모두 만족시키는, 즉 각 개별 조건의 참/거짓과 전체 결정문의 참/거짓을 모두 최소 한 번씩 실행하도록 테스트 케이스를 설계하는 기법이다. 두 기법을 합쳐 놓은더 강력한 커버리지 기준이라고 이해할 수 있다."]]},{"t":"② 구문→결정→조건→조건/결정→다중","n":[["시험 포인트","실기 시험에서는 주어진 순서도나 코드에 대해 특정 커버리지 기준(예: 구문 커버리지 100%)을 만족하는 최소 테스트 케이스의 개수나 입력값을 구하는 문제가 자주 출제되므로, 각 커버리지 기법의 정의를 명확히 구분하고 직접 순서도를 그려가며 연습하는 것이 중요하다."],["설명","커버리지 강도 순서 화이트박스 커버리지 기법은 일반적으로 구문 커버리지(가장 약함) → 결정(분기) 커버리지 → 조건 커버리지 → 조건/결정 커버리지 → 다중 조건 커버리지(가장 강함) 순으로 검증 강도가 강해진다고 정리할 수 있다. 커버리지가 강할수록 더 많은 테스트 케이스가 필요하지만 더 많은 결함을 발견할 가능성이 높아진다."]]}]}]}]}]},{"t":"제9절 테스트 자동화와 테스트 도구","c":[{"t":"Ⅰ 테스트 자동화의 개념과 장단점","c":[{"t":"1. 테스트 자동화란","c":[{"t":"(1) 테스트 자동화의 개념","c":[{"t":"① 수동 테스트를 도구로 자동 수행","n":[["설명","테스트 자동화의 정의 테스트 자동화는 사람이 수동으로 반복 수행하던 테스트 작업을 도구를 이용하여 자동으로 수행하도록 만드는 것을 의미한다. 소프트웨어 개발에 사용되는 총 시간과 비용의 상당 부분을 테스트가 차지하기 때문에, 테스트의 정확성을 유지하면서 시간과 비용을 줄일 수 있는 자동화 도구의 중요성이 매우 크다. 테스트 자동화는 회귀 테스트와 같이 동일한 테스트를 반복적으로 수행해야 하는 경우, 그리고 대량의 데이터를 이용한 반복 테스트가 필요한 경우에 특히 효과적이다. 단순 반복적인 수작업 테스트를 자동화함으로써 테스터가 더 창의적이고 탐색적인 테스트에 집중할 수 있게 된다."]]},{"t":"② 휴먼 에러 최소화·품질 향상","n":[["설명","휴먼 에러 최소화와 자원 절감 테스트를 자동화하면 사람이 반복 작업을 수행하는 과정에서 발생하는 휴먼 에러(사람의 실수로 인한 오류)를 최소화할 수 있다. 또한 자동화를 통해 테스트에 투입되는 인력과 시간을 최소화할 수 있다는 것이 대표적인 장점이다. 테스트 자동화는 동일한 테스트를 언제든 동일한 조건으로 재현할 수 있게 해주므로, 향상된 테스트 품질을 보장한다는 장점이 있다. 특히 회귀 테스트처럼 반복 실행이 필수적인 테스트에서 자동화의 효과가 극대화된다."]]}]},{"t":"(2) 테스트 자동화의 단점","c":[{"t":"① 전문가 양성·초기 비용 부담","n":[["설명","전문가 양성의 필요성 테스트 자동화 도구는 일반 사용자가 다루기 쉽지 않은 경우가 많아, 도구를 능숙하게 다룰 수 있는 전문 인력의 양성이 필요하다는 단점이 있다. 이는 추가적인 고용과 비용 부담으로 이어진다. 테스트 자동화 도구를 도입하고 자동화 스크립트를 구축하는 데에는 상당한 초기 비용과 시간이 소요되며, 애플리케이션이 변경될 때마다 자동화 스크립트도 함께 유지보수해야 하는 부담이 발생한다는 것이 단점으로 지적된다."]]},{"t":"② 반복 빈도 높고 안정적 기능 우선","n":[["설명","자동화 대상 선정 기준 모든 테스트를 자동화하는 것이 항상 효율적인 것은 아니므로, 반복 빈도가 높고 안정적인(자주 바뀌지 않는) 기능부터 자동화 대상으로 선정하는 것이 바람직하다. 반대로 UI가 자주 바뀌는 화면이나 일회성 테스트는 자동화의 효과가 낮을 수 있다. 테스트 도구를 평가할 때는 도구가 지원하는 테스트 범위, 기존 개발 환경 및 형상 관리 도구와의 연동 가능성, 스크립트 작성 및 유지보수의 용이성 등을 종합적으로 고려하여 선정해야 한다."]]}]}]}]},{"t":"Ⅱ 정적 분석 도구와 동적 분석 도구","c":[{"t":"1. 정적 분석 도구(Static Analysis Tool)","c":[{"t":"(1) 정적 분석 도구의 개념","c":[{"t":"① 정적 분석: 실행 없이 코드 분석","n":[["설명","정적 분석 도구란 정적 분석 도구는 프로그램을 실행하지 않고 소스 코드 자체를 분석하여 코딩 스타일 위반, 잠재적인 결함, 보안 취약점 등을 찾아내는 도구이다. 코드 인스펙션이나 워크스루와 같은 사람이 직접 수행하는 코드 검토를 도구를 통해 자동화한 것이라고 이해할 수 있다. 대표적인 정적 분석 도구로는 소스 코드의 복잡도(순환 복잡도)를 측정하거나, 사용하지 않는 변수·잠재적인널 포인터 참조·메모리 누수 가능성 등을 탐지하는 도구들이 있다. 개발 초기 단계에서 정적 분석 도구를 활용하면 코드 리뷰에 소요되는 시간을 크게 줄일 수 있다."]]},{"t":"② 동적 분석 도구: 실행 중 분석","n":[["실제 사례","동적 분석 도구는 프로그램을 실제로 실행시키면서 코드의 동작을 분석하는 도구로, 메모리 누수, 성능 병목 구간, 실행 시점의 예외 발생 등을 탐지하는 데 사용된다. 정적 분석이 코드를 실행하지 않고 분석하는 것과 대비되는 개념이다."],["실제 사례","정적 분석은 코드를 실행하지 않으므로 빠르게 넓은 범위를 검사할 수 있지만 실행 시점에만 나타나는 문제(예: 특정 조건에서만 발생하는 메모리 누수)는 찾아내기 어렵다. 반대로 동적 분석은 실제 실행 환경에서만 나타나는 문제를 찾아낼 수 있지만 프로그램을 실행해야 하므로 상대적으로 시간이 오래 걸린다. 따라서 실무에서는 두 가지 분석 도구를 함께 사용하는 것이 일반적이다."],["설명","동적 분석 도구란"]]}]},{"t":"(2) 테스트 레벨별 지원 도구","c":[{"t":"① 단위 테스트 xUnit·JUnit","n":[["설명","단위 테스트 지원 도구 단위 테스트 단계에서는 개별 함수나 모듈을 독립적으로 실행하고 결과를 검증할 수 있는 단위 테스트 프레임워크(예: JUnit과 같은 xUnit 계열 도구)가 널리 사용된다. 이러한 도구는 테스트 케이스 작성, 실행, 결과 리포팅을 자동화해 준다. 통합 테스트와 시스템 테스트 단계에서는 여러 모듈 또는 전체 시스템을 대상으로 시나리오 기반 테스트를 자동으로 반복 수행하는 테스트 자동화 도구, 그리고 대량의 가상 사용자를 시뮬레이션하여 성능을 측정하는 성능 테스트 도구가 주로 활용된다."]]},{"t":"② 도구 관련 용어 구분","n":[["시험 포인트","실기 시험에서는 정적 분석 도구와 동적 분석 도구의 차이, 테스트 자동화의 장단점을 서술하는 문제가 자주 출제되므로, \"실행 여부\"라는 기준으로 두 도구를 명확히 구분하여 암기해야 한다."],["실제 사례","테스트 자동화 스크립트 역시 하나의 소스 코드이므로 형상 관리 도구(CVS/SVN/Git)를 통해 버전 관리되어야 하며, 애플리케이션 코드가 변경되면 관련된 자동화 스크립트도 함께 형상 관리 대상으로 갱신해야 한다는 점을 실무 관점에서 기억해 두어야 한다."],["설명","도구 관련 용어 구분"]]}]}]}]}]},{"t":"제10절 애플리케이션 성능 개선과 소스 코드 최적화","c":[{"t":"Ⅰ 애플리케이션 성능 저하 원인 분석","c":[{"t":"1. 성능 저하의 주요 원인","c":[{"t":"(1) 데이터베이스 관련 성능 저하 원인","c":[{"t":"① 비효율 쿼리·인덱스 부재 풀 스캔","n":[["쉬운 예","N+1 문제는 하나의 목록을 조회한 후, 목록의 각 항목에 대해 추가 정보를 얻기 위해 N번의 개별 쿼리를 반복 실행하는 비효율적인 패턴을 의미한다. 예를 들어 게시글 100개를 조회한 뒤 각 게시글의 작성자 정보를 얻기 위해 100번의 추가 쿼리를 실행한다면, 총 101번의 쿼리가 발생하여 성능이 크게 저하된다."],["설명","비효율적인 쿼리와 인덱스 부재 애플리케이션 성능 저하의 대표적인 원인 중 하나는 데이터베이스 조회 시 불필요하게 많은 데이터를 가져오 거나, 인덱스가 적절히 설정되지 않아 풀 스캔(Full Scan)이 발생하는 경우이다. WHERE 절의 조건 컬럼에 인덱스가 없으면 테이블 전체를 순차적으로 검색하게 되어 데이터가 많을수록 응답 시간이 급격히 늘어난다."]]},{"t":"② 반복 연산·메모리 누수","n":[["설명","불필요한 반복 연산과 메모리 누수 반복문 내부에서 동일한 계산을 매번 다시 수행하거나, 사용이 끝난 객체나 리소스(파일 핸들, 데이터베이스 연결 등)를 적절히 해제하지 않아 메모리 누수가 발생하는 경우도 성능 저하의 주요 원인이다. 특히 장시간 운영되는 서버 애플리케이션에서는 작은 메모리 누수가 누적되어 결국 시스템 전체의 성능 저하나 장애로 이어질 수 있다. 외부 API 호출이나 파일 입출력과 같이 시간이 오래 걸리는 작업을 동기(순차) 방식으로 처리하면, 해당 작업이 끝날 때까지 다른 작업이 대기해야 하는 병목 현상이 발생한다. 이러한 경우 비동기 처리나 병렬 처리를 도입하여 성능을 개선할 수 있다."]]}]},{"t":"(2) 성능 테스트 도구를 활용한 진단","c":[{"t":"① 프로파일링으로 병목 진단","n":[["실제 사례","프로파일링은 프로그램 실행 중 각 함수나 구간이 얼마나 많은 시간과 자원(CPU, 메모리)을 소비하 는지 측정하는 기법이다. 프로파일링 도구를 통해 병목이 되는 구간을 정확히 특정하지 않고 무작정 코드를 최적화하면 실제 성능 개선 효과를 얻기 어렵다."],["설명","프로파일링(Profiling)"]]},{"t":"② 인덱스 추가 3초→0.01초","n":[["설명","인덱스 추가를 통한 조회 성능 개선 사례 회원 100만 건이 저장된 테이블에서 이메일로 회원을 조회하는 쿼리가 평균 3초 걸리던 것을, 이메일 컬럼에 인덱스를 추가한 후 0.01초로 단축한 사례를 예로 들 수 있다. 이처럼 인덱스 추가는 비용 대비 효과가 가장큰 성능 개선 방법 중 하나로 꼽힌다. 자주 조회되지만 변경 빈도가 낮은 데이터(예: 공지사항, 카테고리 목록)를 매번 데이터베이스에서 조회하는 대신 캐시(메모리)에 저장해 두고 재사용하면, 데이터베이스 부하를 줄이고 응답 시간을 대폭 단축할 수 있다."]]}]}]}]},{"t":"Ⅱ 소스 코드 최적화와 클린 코드","c":[{"t":"1. 소스 코드 최적화 기법","c":[{"t":"(1) 알고리즘 및 자료구조 최적화","c":[{"t":"① 시간 복잡도 고려 알고리즘","n":[["쉬운 예","동일한 문제를 해결하더라도 사용하는 알고리즘에 따라 시간 복잡도가 크게 달라질 수 있다. 예를 들어 정렬되지 않은 배열에서 특정 값을 찾을 때 선형 탐색은 O(n)이 걸리지만, 정렬된 배열에서 이진 탐색을 사용하면 O(log n)으로 단축할 수 있어 데이터가 많을수록 성능 차이가 커진다."],["설명","시간 복잡도를 고려한 알고리즘 선택"]]},{"t":"② 리팩토링: 기능 유지·구조 개선","n":[["설명","리팩토링의 개념 리팩토링은 소프트웨어의 겉으로 드러나는 동작(기능)은 변경하지 않으면서, 내부 구조를 개선하여 코드를더 이해하기 쉽고 유지보수하기 쉽게 만드는 작업을 의미한다. 기능 추가가 아니라 코드 품질 개선이 목적이라는 점이 핵심이다. 리팩토링을 수행하기 전과 후에 동일한 테스트 케이스(특히 회귀 테스트)를 실행하여 기능이 변경되지 않았음을 반드시 검증해야 한다. 테스트 코드가 충분히 갖추어져 있지 않은 상태에서의 리팩토링은 의도치 않은 PART B. 실기 대비 · Part02 애플리케이션 테스트 수행 · 제10절 애플리케이션 성능 개선과 소스 코드 최적화 결함을 유발할 위험이 크다."]]}]},{"t":"(2) 클린 코드(Clean Code) 작성 원칙","c":[{"t":"① 명확한 네이밍·단일 책임·중복 제거","n":[["설명","가독성과 명확한 네이밍 클린 코드는 변수명·함수명이 그 역할을 명확하게 드러내도록 작성하고, 하나의 함수가 하나의 책임만 갖도록 (단일 책임 원칙) 설계하는 것을 지향한다. 코드는 작성하는 시간보다 읽히는 시간이 훨씬 길기 때문에, 가독성이 곧 유지보수 비용과 직결된다. 동일하거나 유사한 코드가 여러 곳에 중복되어 있으면 하나를 수정할 때 나머지도 함께 수정해야 하므로 결함이 발생하기 쉽다. 이를 방지하기 위해 공통 로직은 함수나 모듈로 추출하여 재사용하고, 코드만으로 의도가 충분히 드러나지 않는 부분에 한해 주석을 작성하는 것이 바람직하다."]]},{"t":"② 순환 복잡도·응집도↑ 결합도↓","n":[["실제 사례","성능 개선과 소스 코드 최적화 영역은 실기 시험에서 순서도나 코드를 제시하고 비효율적인 부분을 찾아 개선 방안을 서술하도록 요구하는 형태로 자주 출제되므로, 인덱스·캐싱·알고리즘 개선·리팩토링이라는네 가지 대표적인 개선 방향을 실제 사례와 함께 기억해 두는 것이 효과적이다."],["설명","코드 품질을 측정하는 지표 코드의 품질을 정량적으로 측정하는 지표로는 순환 복잡도(코드의 논리적 복잡성), 코드 중복도(중복 코드의 비율), 결합도와 응집도(모듈 간의 의존 관계와 모듈 내부의 관련성) 등이 있다. 응집도는 높을수록, 결합도는 낮을수록 좋은 설계로 평가된다."]]}]}]}]}]},{"t":"제17절 실기 시험 대비 최종 요약과 용어 사전","c":[{"t":"Ⅰ 과목 전체 핵심 요약","c":[{"t":"1. 테스트 개념·레벨 핵심 요약","c":[{"t":"(1) 테스트 기본 개념 요약","c":[{"t":"① V모델 대응·테스트 7원칙","n":[["시험 포인트","단위 테스트는 개발자·구조 기반/명세 기반, 통합 테스트는 상호작용·드라이버(상향식)/스텁(하향식), 시스템 테스트는 전체 시스템·기능적/비기능적(성능·회복·보안), 인수 테스트는 사용자·알파/베타 테스트라는 키워드로 각 레벨을 구분하여 암기해야 한다."],["설명","V모델과 테스트 7원칙 요약 V모델은 요구사항 분석-인수 테스트, 시스템 설계-시스템 테스트, 모듈 설계-통합 테스트, 구현-단위 테스트가 서로 대응되는 구조이다. 테스트 7원칙은 계획 단계부터 시작, 결함 발견 활동, 완전한 테스트 불가능, 상황 의존적, 결함 집중(파레토 법칙), 살충제 패러독스, 오류-부재의 궤변으로 정리된다."]]},{"t":"② 테스트 케이스 5요소·오라클 4종","n":[["설명","테스트 케이스 구성요소 요약 테스트 케이스는 명세 기반 테스트의 산출물이며, 식별자·테스트 대상·사전 조건·입력값·기대 결과의 다섯 가지 요소로 구성된다. 작성 절차는 테스트 계획 검토·위험 평가 → 테스트 요구사항 정의 → 케이스 작성 → 검토·승인의 순서를 따른다. 참 오라클(모든 입력값), 샘플링 오라클(일부 입력값), 휴리스틱 오라클(샘플링 개선, 나머지는 추정), 일관성 검사 오라클(변경 전후 비교)의 네 가지를 각각의 핵심 키워드로 구분하여 기억해야 한다."]]}]},{"t":"(2) 결함 용어·분류·관리 프로세스 요약","c":[{"t":"① 결함 용어 4종 요약","n":[["시험 포인트","에러(사람의 실수) → 오류/폴트(코드에 남는 흔적) → 실패(실행 결과의 차이) → 결함(이 모든 것을 포괄)의 흐름으로 암기한다. 결함 분류는 시스템/기능/GUI/문서 결함의 네 가지, 심각도는 High/Medium/Low의 세 단계로 구분된다."],["설명","결함 용어 4종 요약"]]},{"t":"② 형상 관리 핵심 요약","n":[["시험 포인트","형상 항목(SCI, 세부 산출물)과 기준선(Baseline, 승인된 특정 시점 버전)의 관계를 이해하고, 형상 관리의 5대 활동(형상 식별-버전 관리-변경 통제-형상 감사-상태 보고)과 3대 도구(CVS-SVN-Git, 시대순 발전)를 함께 암기해야 한다."],["설명","형상 관리 핵심 요약"]]}]}]}]},{"t":"Ⅱ 실기 시험 대비 핵심 용어 사전","c":[{"t":"1. 테스트 레벨·기법 관련 용어","c":[{"t":"(1) 테스트 레벨 관련 용어 정리","c":[{"t":"① 드라이버·스텁·빅뱅·샌드위치","n":[["설명","단위·통합 테스트 용어 단위 테스트(Unit Test), 통합 테스트(Integration Test), 드라이버(Driver, 상향식에서 상위 모듈 대체), 스텁(Stub, 하향식에서 하위 모듈 대체), 빅뱅(Big-Bang), 샌드위치(Sandwich, 혼합식)와 같은 용어의 정확한 영문 스펠링과 의미를 함께 정리해야 한다. 시스템 테스트(System Test), 인수 테스트(Acceptance Test), 알파 테스트(Alpha Test, 통제된 내부 환경), 베타 테스트(Beta Test, 통제되지 않은 실사용 환경), 성능 테스트(Performance Test), 회복 테스트(Recovery Test), 보안 테스트(Security Test)의 용어를 정리해야 한다."]]},{"t":"② 블랙박스 기법 용어","n":[["시험 포인트","동등 분할(Equivalence Partitioning), 경계값 분석(Boundary Value Analysis), 결정 테이블 테스트(Decision Table Testing), 상태 전이 테스트(State Transition Testing), 유스케이스 테스트(Use Case Testing)의 다섯 가지 기법명을 정확히 암기해야 한다."],["설명","블랙박스 기법 용어"]]}]},{"t":"(2) 결함·형상 관리 용어","c":[{"t":"① 결함 관련 영문 용어","n":[["시험 포인트","에러(Error), 오류/폴트(Fault), 실패(Failure), 결함(Defect/Bug), 심각도(Severity), 우선순위(Priority), 형상 항목(SCI, Software Configuration Item), 기준선(Baseline)의 정확한 스펠링을 암기해야한다."],["설명","결함 관련 영문 용어"]]},{"t":"② 성능 개선 관련 용어","n":[["시험 포인트","프로파일링(Profiling), N+1 문제, 캐싱(Caching), 인덱스(Index), 리팩토링(Refactoring), 순환 복잡도, 결합도(Coupling)와 응집도(Cohesion)의 개념과 \"결합도는 낮게, 응집도는 높게\"라는 원칙을 함께 암기해야 한다."],["시험 포인트","테스트 자동화(Test Automation), 정적 분석 도구(Static Analysis Tool), 동적 분석 도구(Dynamic Analysis Tool), 회귀 테스트(Regression Test)의 용어와 각 도구의 실행 여부에 따른 차이를 정리하여 실기 시험 직전까지 반복 확인해야 한다."],["설명","성능 개선 관련 용어"]]}]}]}]}]},{"t":"제18절 실기 시험 D-Day 최종 점검","c":[{"t":"Ⅰ 시험 직전 최종 점검 체크리스트","c":[{"t":"1. 개념·용어 최종 점검","c":[{"t":"(1) 혼동하기 쉬운 용어 짝 점검","c":[{"t":"① 드라이버 vs 스텁 점검","n":[["시험 포인트","상향식 통합 테스트에는 드라이버(Driver, 상위 모듈 대체), 하향식 통합 테스트에는 스텁(Stub, 하위 모듈 대체)이 필요하다는 것을 마지막으로 한 번 더 확인한다. \"상향식-드라이버\", \"하향식-스텁\"이라는 짝을 입으로 소리 내어 읽어보는 것도 효과적인 암기 방법이다."],["설명","드라이버 vs 스텁 최종 점검"]]},{"t":"② 명세 기반 = 블랙박스 관계","n":[["시험 포인트","명세 기반 테스트가 블랙박스 테스트를 포함하는 상위 개념이라는 포함 관계를 다시 한번 확인한다. \"명세 기반 테스트 = 블랙박스 테스트\"라고 단순 동일시하지 않도록 주의해야 한다."],["설명","명세 기반 테스트와 블랙박스 테스트의 관계 점검"]]}]},{"t":"(2) 순환 복잡도 계산 공식 점검","c":[{"t":"① V(G)=E-N+2 계산 연습","n":[["설명","공식 재확인 순환 복잡도 V(G) = E(에지 수) - N(노드 수) + 2 공식을 다시 한번 확인하고, 간단한 흐름 그래프 예제(노드 5개, 에지 6개 등)를 직접 손으로 계산해 보는 연습을 마지막으로 수행한다. 구문 커버리지, 결정 커버리지, 조건 커버리지, 조건/결정 커버리지의 강도 순서와 각각의 정의를 다시 한번 확인하고, 간단한 if문 예제를 통해 각 커버리지를 만족하는 최소 테스트 케이스 개수를 직접 세어보는 연습을한다."]]},{"t":"② 서술형 핵심 키워드·영문 병기","n":[["설명","키워드 중심 답안 작성 서술형 문제에 답할 때는 장황한 설명보다, 핵심 키워드(예: \"동료\", \"체크리스트 사용\", \"모든 결함 제거\")를 명확히 포함시켜 채점자가 정답 요소를 쉽게 확인할 수 있도록 작성하는 것이 중요하다. 가능하다면 국문 용어와 함께 영문 용어(예: \"결정 테이블 테스트(Decision Table Testing)\")를 병기하여 답안을 작성하면, 정확한 개념 이해를 보여줄 수 있어 채점에 유리하다."]]}]}]}]},{"t":"Ⅱ 과목 간 연계와 실전 대비 마무리","c":[{"t":"1. 다른 과목과의 연계 포인트","c":[{"t":"(1) SQL·데이터베이스 과목과의 연계","c":[{"t":"① 테스트 데이터 SQL INSERT 연계","n":[["설명","테스트 데이터 준비와 SQL의 연계 테스트 케이스를 실행하기 위한 테스트 데이터를 준비할 때 SQL의 INSERT문이 활용되며, 결함 재현을 위해 특정 데이터 상태를 만들 때도 SQL 조작 능력이 필요하다. 다른 과목에서 학습한 SQL 지식이 애플리케이션 테스트 과목과 직접적으로 연결된다는 것을 인지하고 있어야 한다. 애플리케이션 성능 저하의 상당 부분이 데이터베이스 조회 비효율에서 비롯되므로, SQL 활용 과목에서 학습한 인덱스와 조인 최적화 지식이 성능 개선 문제 풀이에 직접 활용될 수 있다."]]},{"t":"② Git과 네트워크·OS 연계","n":[["설명","형상 관리와 운영체제·네트워크의 연계 형상 관리 도구(Git 등)는 서버에 설치되어 운영되며, 분산 버전 관리 시스템의 동작 원리를 이해하려면 네트워크의 클라이언트-서버 통신 개념에 대한 기초 지식이 도움이 된다. 테스트 환경을 구성할 때 운영체제의 프로세스 관리 개념(메모리 사용량, 프로세스 상태)을 이해하고 있으면, 성능 테스트 결과를 해석하고 병목 원인을 진단하는 데 도움이 된다."]]}]},{"t":"(2) 시험 당일 시간 배분 전략","c":[{"t":"① 단답형 빠르게·계산형 시간 배분","n":[["시험 포인트","답안 작성을 마친 뒤에는 남은 시간 동안 영문 스펠링 오타, 용어 혼동(드라이버/스텁, 심각도/우선순위 등)이 없는지 반드시 재검토하는 습관을 들여야 한다."],["설명","문제 유형별 시간 배분 단답형·용어 정의 문제는 빠르게 풀고, 계산이 필요한 커버리지·순환 복잡도 문제와 서술형 문제에 상대적으로 더 많은 시간을 배분하는 것이 효율적이다. 확실히 아는 문제부터 먼저 풀어 시간을 절약하는 전략이 필요하다."]]},{"t":"② 전체 절 복습 순서","n":[["시험 포인트","시험 직전에는 절1(개념·V모델) → 절2(테스트 레벨) → 절4·5(결함) → 절6(형상관리) → 절17(용어사전) 순으로 핵심 절만 빠르게 복습하는 것이 효율적이다. 시간이 부족하다면 용어 사전과 모의고사의 오답만 집중적으로 재확인한다."],["시험 포인트","본 정리서에 수록된 세 회차의 실전 모의고사를 시험 전날 시간을 재며 다시 풀어보는 것이 실전 감각을 유지하는 데 가장 효과적이다. 이상으로 애플리케이션 테스트 수행 과목의 실기 시험 대비 정리를 마친다."],["설명","전체 절 복습 순서 제안"]]}]}]}]}]},{"t":"제19절 테스트 문서화와 커뮤니케이션 실무","c":[{"t":"Ⅰ 테스트 산출물 문서화 표준","c":[{"t":"1. 테스트 문서의 종류와 표준","c":[{"t":"(1) IEEE 829 테스트 문서 표준","c":[{"t":"① IEEE 829 테스트 문서 표준","n":[["실제 사례","IEEE 829는 소프트웨어 테스트 문서화에 관한 국제 표준으로, 테스트 계획서, 테스트 설계 명세서, 테스트 케이스 명세서, 테스트 절차 명세서, 테스트 결과 보고서 등 테스트 전 과정에서 작성되어야 할 문서의 종류와 형식을 규정한다. 실무에서 표준화된 테스트 문서를 작성할 때 참고하는 대표적인 기준이다."],["설명","IEEE 829 표준의 개념"]]},{"t":"② 테스트 진척 현황표·결함 추이","n":[["설명","테스트 진척 현황표 테스트 진척 현황표는 전체 테스트 케이스 중 실행 완료된 비율, 통과율, 남은 일정 등을 시각적으로 보여주는 관리 문서이다. 프로젝트 관리자는 이 문서를 통해 테스트 일정이 계획대로 진행되고 있는지, 추가 자원 투입이 필요한지를 판단한다. 결함 추이 그래프는 시간 경과에 따라 새로 발견된 결함 수와 해결된 결함 수를 그래프로 시각화한 것으로, 결함 발견 속도가 둔화되는 시점을 파악하여 테스트 종료 시점을 판단하는 근거로 활용된다. 결함 발견 곡선이 완만해지는 시점이 출시 준비가 임박했다는 신호로 해석될 수 있다."]]}]},{"t":"(2) 개발자와의 협업","c":[{"t":"① 사실 중심 결함 보고","n":[["설명","결함 보고 시 커뮤니케이션 원칙 테스터가 개발자에게 결함을 전달할 때는 사실에 근거하여 객관적으로 기술해야 하며, 개발자의 능력이나 태도를 비난하는 표현은 피해야 한다. \"이 코드는 왜 이렇게 짰나요\"와 같은 표현 대신 \"이러한 입력값에서 이러한 결과가 나왔습니다\"와 같이 사실 중심으로 전달하는 것이 협업 관계를 원활하게 유지하는 데 중요하다. 결함의 심각도는 테스터가 기술적으로 판단하지만, 우선순위는 종종 프로젝트 관리자나 기획자와 협의하여 결정된다. 일정이 촉박한 경우 심각도가 낮은 결함은 다음 배포 주기로 미루는 것에 대해 관련 이해관계자와 사전에 합의하는 절차가 필요하다."]]},{"t":"② 비즈니스 영향 중심 품질 보고","n":[["설명","품질 상태 보고 테스트 관리자는 경영진이나 고객에게 현재 제품의 품질 상태(테스트 진행률, 잔존 결함 수, 위험 평가)를 정기적으로 보고하여, 출시 일정에 대한 의사결정을 지원해야 한다. 이때 기술적인 세부사항보다는 비즈니스에 미치는 영향(예: \"결제 기능에 영향을 줄 수 있는 결함 2건이 남아있습니다\") 중심으로 전달하는 것이 효과적이다. 인수 테스트는 고객이 직접 참여하므로, 테스트 과정에서 발견된 문제와 그에 대한 대응 계획을 투명하게 공유하여 고객의 신뢰를 확보하는 것이 중요하다. 인수 테스트 결과 보고서에는 합격/불합격 여부와 그 근거가 명확하게 기술되어야 한다."]]}]}]}]},{"t":"Ⅱ 테스트 계획 수립과 위험 관리","c":[{"t":"1. 테스트 계획 수립 실무","c":[{"t":"(1) 테스트 범위와 일정 계획","c":[{"t":"① 테스트 범위·Out of Scope 정의","n":[["설명","테스트 범위(Test Scope) 정의 테스트 계획을 수립할 때는 먼저 테스트 대상이 되는 기능과 테스트하지 않을 범위(Out of Scope)를 명확히 정의해야 한다. 범위가 불명확하면 테스트 자원이 비효율적으로 분산되거나, 중요한 기능이 테스트에서 누락될 위험이 있다. 테스트 일정은 개발 일정과 연계하여 수립하되, 단위 테스트-통합 테스트-시스템 테스트-인수 테스트 각 단계에 필요한 시간을 현실적으로 산정해야 한다. 일정이 지나치게 촉박하면 충분한 테스트 없이 출시되어 품질 위험이 커질 수 있다."]]},{"t":"② 위험 기반 테스트: 고위험 집중","n":[["설명","위험 기반 테스트(Risk-Based Testing) 위험 기반 테스트는 시스템의 각 기능이 실패했을 때 미치는 비즈니스 영향과 발생 가능성을 평가하여, 위험도가 높은 기능에 더 많은 테스트 자원을 집중하는 전략이다. 결제, 로그인과 같은 핵심 기능은 위험도가 높으므로 우선적으로 충분한 테스트 케이스를 확보해야 한다. 테스트 자원(시간, 인력)이 부족할 경우, 위험도가 낮은 기능의 테스트를 축소하거나 회귀 테스트 범위를 자동화된 핵심 시나리오로 한정하는 등의 우선순위 조정 전략을 적용해야 한다. 이러한 의사결정은 반드시 이해관계자와 사전에 협의되어야 한다."]]}]},{"t":"(2) 테스트 완료 기준(Exit Criteria)","c":[{"t":"① 완료 기준: 실행률·High 결함 0건","n":[["설명","완료 기준의 개념 테스트 완료 기준은 테스트 활동을 종료해도 되는지 판단하는 사전에 합의된 기준으로, 일반적으로 계획된 테스트 케이스의 실행률(예: 100%), 커버리지 목표 달성 여부, 미해결 심각도 High 결함의 개수(예: 0건) 등으로 정의된다. 완료 기준을 충족하지 못한 상태에서 출시 압박이 있는 경우, 잔존 위험을 명시적으로 문서화하고 이해관계자의 승인을 받아 조건부로 출시를 진행하는 경우도 있다. 이때 어떤 위험을 감수하고 출시하는지 명확히 기록해 두는 것이 이후 문제 발생 시 책임 소재를 명확히 하는 데 중요하다."]]},{"t":"② 핵심 문서 종류 요약","n":[["시험 포인트","테스트 계획서, 테스트 케이스 명세서, 결함 보고서, 테스트 요약 보고서라는 네 가지 핵심 문서의 목적과 작성 시점을 구분하여 암기해야 한다."],["설명","핵심 문서 종류 요약"]]}]}]}]}]}],"k":"실기 Part02"},{"n":7,"t":"응용SW 기초 기술 활용","c":[{"t":"제1절 운영체제의 개념과 발달 과정","c":[{"t":"Ⅰ 운영체제의 개념과 목적","c":[{"t":"1. 운영체제(OS)란 무엇인가","c":[{"t":"(1) 운영체제의 정의와 역할","c":[{"t":"① OS 정의·하드웨어 인터페이스","n":[["설명","운영체제의 정의 운영체제(Operating System)는 사용자로 하여금 컴퓨터의 하드웨어를 보다 쉽게 사용할 수 있도록 인터페이스를 제공해주는 소프트웨어이다. 여기서 하드웨어란 데이터를 처리하는 중앙처리장치(CPU), 데이터를 저장하는 기억장치, 외부와 통신을 담당하는 통신장치, 데이터 입출력을 담당하는 입출력장치 등을 의미한다. 운영체제는 사용자 편의성을 위한 인터페이스인 동시에, 컴퓨터의 자원(CPU, 메모리, 디스크, 입출력장치 등)을 효율적으로 관리하는 자원 관리자로서의 역할도 함께 수행한다. 즉 사용자와 하드웨어 사이에서 인터페이스를 제공하는 기능과, 한정된 시스템 자원을 여러 프로그램에 배분하는 관리 기능을 동시에 담당하는 소프트웨어이다."]]},{"t":"② 처리능력↑·반환시간↓ 우수","n":[["설명","처리 능력과 반환 시간 처리 능력(Throughput)은 일정한 단위 시간 내에 처리할 수 있는 일의 양을 의미하며, 값이 클수록 우수한 성능을 나타낸다. 반환 시간(Turnaround Time)은 하나의 작업을 시작한 시간부터 결과를 얻을 때까지 걸린 시간을 의미하며, 값이 작을수록 우수한 성능을 나타낸다. 사용 가능도(Availability)는 시스템을 이용하려 할 때 얼마나 빨리 사용할 수 있는지의 정도를 의미하고, 신뢰도(Reliability)는 시스템이 주어진 문제를 정확하게 해결할 수 있는지의 정도를 의미한다. 이 네 가지(처리 능력, 반환 시간, 사용 가능도, 신뢰도)가 운영체제의 대표적인 성능 평가 항목이다."]]}]},{"t":"(2) 초창기 운영체제(1950~19 60년대)","c":[{"t":"① 일괄처리·버퍼링·스풀링","n":[["설명","일괄 처리·버퍼링·스풀링(1950년대) 일괄 처리 시스템은 데이터를 모아두었다가 묶어서 처리하는 방식이다. 버퍼링은 입출력장치와 프로세서의 속도 차이를 보완하기 위해 다음 레코드를 주기억장치(버퍼)에 미리 보관함으로써 CPU가 레코드를 기다림 없이 전달받을 수 있게 하는 기법이다. 스풀링은 버퍼링과 달리 주기억장치 대신 디스크를 매우 큰 버퍼처럼 사용하는 기법으로, 여러 작업의 입출력과 계산을 함께 진행할 수 있다는 장점이 있다. 다중 프로그래밍은 여러 프로그램을 메모리에 나눠 적재한 후 번갈아 할당하며 동시에 실행하는 방식이다. 시분할 시스템은 다중 프로그래밍을 확장하여 프로세서 스케줄링 개념을 더한 시스템으로, 여러 사용자에게 짧은 간격으로 프로세서를 번갈아 할당해 마치 혼자 독점하는 것처럼 사용하게 한다. 다중 처리 시스템은 하나의 시스템에서 여러 개의 프로세서를 사용하는 시스템이며, 실시간 시스템은 데이터가 발생하는 즉시 응답하는 시스템이다."]]},{"t":"② 1970년대 다중모드·분산처리","n":[["설명","다중 모드·범용 시스템, 분산·병렬 처리(1970년대) 1970년대 초반에는 일괄, 시분할, 실시간, 다중 처리 등을 모두 제공하는 다중 모드 시스템과, 여러 가지 용도로 사용할 수 있는 범용 시스템이 등장했다. 1970년대 중반 이후에는 독립적인 처리 능력을 가진 컴퓨터 시스템을 통신망으로 연결하여 서로 통신하며 협력 처리하는 분산 처리 시스템과, 하나 이상의 연산을 동시에 수행하여 연산 속도를 높이는 병렬 처리 시스템이 발전했다. 2000년대에는 모바일 및 임베디드 시스템, 가상화 및 클라우드 컴퓨팅이 발전했다. 임베디드 시스템은 기계나 제어가 필요한 장치 내부에 존재하며 특정 기능을 수행하는 시스템이다. 가상화는 물리적 하드웨어를 사용자로부터 은폐하여 논리적인 리소스를 제공하거나, 하나의 물리적 리소스를 여러 개로 보이게 하는 기술이다."]]}]}]}]},{"t":"Ⅱ 가상화와 클라우드 컴퓨팅의 유형","c":[{"t":"1. 가상화의 유형","c":[{"t":"(1) 가상화 방식에 따른 분류","c":[{"t":"① 호스트OS형·하이퍼바이저형","n":[["설명","호스트 OS형과 하이퍼바이저형 호스트 OS형은 물리적 하드웨어 위에 OS를 설치하고, 그 위에 가상화 소프트웨어와 가상머신을 이용하는 방식으로, 기존 OS 위에 가상화 OS를 설치하는 형태이다. 하이퍼바이저형은 호스트 OS를 필요로 하지 않고 직접 물리 하드웨어를 움직여 독립적인 호스트처럼 동작하는 방식으로, 가상화를 위한 독립적 OS를 직접 설치한다. 컨테이너형은 컨테이너라는 가상화 소프트웨어를 이용하는 방식으로, 미리 구축해 놓은 가상화 OS(컨테이너)를 설치하여 사용한다. 하이퍼바이저형에 비해 자원 오버헤드가 적어 가볍고 빠르게 실행할 수 있다는 특징이 있다."]]},{"t":"② 가상화 개념과 효과","n":[["실제 사례","가상화는 물리적인 리소스들을 사용자에게 하나로 보이게 하거나, 반대로 하나의 물리적인 리소스를 여러 개로 보이게 하는 것을 의미한다. 대부분의 서버는 용량의 20% 정도만을 사용하는데, 가상화를 적용하면 서버의 가동률을 70% 이상으로 끌어올릴 수 있다는 실무적 효과가 있다."],["실제 사례","플랫폼 가상화는 하드웨어 플랫폼 위에서 실행되는 호스트 프로그램이 게스트 프로그램을 만들어 마치 독립된 환경처럼 보여주는 방식이다. 리소스 가상화는 메모리, 저장 장치, 네트워크 등을 결합하거나 나누는 방식으로, 사용자는 가상화된 물리적 장치의 실제 위치를 알 수 없는 경우가 많다."],["설명","가상화의 개념과 효과"]]}]},{"t":"(2) IaaS와 PaaS","c":[{"t":"① IaaS 관리범위 최대","n":[["설명","IaaS(Infrastructure as a Service, 인프라형) IaaS는 사용자가 관리할 수 있는 범위가 가장 넓은 클라우드 서비스로, 웹상에서 구글·마이크로소프트·아마존 등이 제공하는 네트워크, 보안, 데이터 저장소, 콘텐츠 딜리버리 서비스 등 다양한 인프라를 임대하여 이용할 수 있는 서비스이다. 서버 OS, 미들웨어, 런타임, 데이터 등을 사용자가 직접 구성하고 관리할 수 있다. PaaS는 운영체제가 이미 구성되어 있는 상태에서 사용자가 데이터와 애플리케이션만 직접 관리할 수 있는 서비스이다. 미리 구축된 플랫폼을 이용하므로 관리상의 자유도는 낮지만, 개발 자체에 집중할 수 있다는 장점이 있다."]]},{"t":"② SaaS 관리범위 최소","n":[["실제 사례","개발 자유도가 높은 인프라 구성이 필요하다면 IaaS를, 개발에만 집중하고 인프라 관리 부담을 줄이고 싶다면 PaaS를, 소프트웨어 자체를 그대로 사용하고 싶다면 SaaS를 선택하는 것이 일반적인 실무 기준이다. 실기 시험에서는 각 서비스의 사용자 관리 범위 차이를 묻는 문제가 출제될 수 있다."],["설명","SaaS(Software as a Service, 서비스형) SaaS는 인프라와 운영체제뿐만 아니라 사용할 수 있는 소프트웨어까지 모두 갖추어져, 웹상 로그인만으로 다양한 소프트웨어를 사용한 만큼 비용을 지불해가며 사용할 수 있는 서비스이다. 사용자가 직접 관리해야 하는 범위가 IaaS, PaaS, SaaS 순으로 점점 줄어든다는 흐름을 함께 기억해 두면 세 서비스의 관계를 이해하기 쉽다."]]}]}]}]}]},{"t":"제2절 운영체제 계열별 특징과 명령어 활용","c":[{"t":"Ⅰ 운영체제 계열별 특징","c":[{"t":"1. 윈도우 계열과 유닉스 계열","c":[{"t":"(1) 윈도우(Windows) 계열","c":[{"t":"① 윈도우 GUI·MS 독점 배포","n":[["설명","윈도우의 발전과 특징 마이크로소프트사에서 1995년 윈도우 95(Windows 95)를 발표한 이후 98, ME, XP, 7, 8, 10 등의 버전으로 지속적으로 출시되어 왔다. 사용자가 마우스로 아이콘을 클릭하여 소프트웨어를 실행하는 편리한 GUI 인터페이스가 특징이며, 마이크로소프트사만이 수정 및 배포할 수 있어 고객 지원이 체계적이라는 장점이 있다. 다만 문제(버그 등) 발견 시 수정에 시간이 걸리며, 이 시간차를 노리는 악성 해커들로 인해 유닉스 계열보다 보안에 취약하다는 문제점이 제기된다. 선점형 멀티태스킹은 운영체제가 수행 중인 각 프로그램의 실행 시간을 할당하고, 실행 중 문제가 발생하면 해당 프로그램을 강제 종료시킨 후 모든 시스템 자원을 반환하는 방식이다. PnP(Plug & Play)는 장치를 연결할 때 별도의 사용자 조작 없이 자동으로 장치를 인식하여 사용 가능하게 하는 기능이다. 핫플러그는 전원이 켜진 상태에서 장치 추가는 가능하나 제거는 불가능한 반면, 핫스왑은 전원이 켜진 상태에서 장치의 교체까지 가능한 기능이다."]]},{"t":"② 유닉스 Multics·C언어 기반","n":[["설명","유닉스의 역사와 특징 유닉스는 1960년대 AT&T Bell 연구소, MIT, General Electric의 공동 연구로 개발이 착수되었으며, 멀티 태스크 기능에 초점을 맞춘 초기 운영체제 Multics를 바탕으로 발전했다. C언어로 재이식되어 대중화의 기반을 마련했고, 이후 SYSTEM V 계열과 BSD(Berkeley Software Distribution) 계열로 발전해 왔으나 현재는 두 계열의 장점을 통합한 버전이 배포되고 있다. 대표적으로 IBM의 AIX, 오라클의 솔라리스(Solaris), HP의 UX 등이 있다. 유닉스는 커널(Kernel), 쉘(Shell), 유틸리티(Utility)로 구성된다. 커널은 운영체제의 핵심 구성요소로 프로세스 수행에 필요한 하드웨어의 동작을 조정하는 서비스를 제공한다. 쉘은 실행한 프로세스 등을 커널에게 전달할 수 있도록 번역해 주는 명령 번역기이며, 유틸리티는 운영체제에서 기본으로 제공하는 것 외의 실행 가능한 프로그램을 의미한다."]]}]},{"t":"(2) 리눅스(Linux) 계열","c":[{"t":"① 리눅스 1991 토발즈 오픈소스","n":[["설명","리눅스의 탄생과 특징 리눅스는 유닉스의 호환 커널로, 1991년 리누스 토발즈(Linus Torvalds)가 자유 소프트웨어(Free Software) 정책 하에 완전히 자유롭고 재배포가 가능한 운영체제로 개발했다. 수천 명 이상의 개발자들이 코드를 검토하고 업데이트하므로 버그 발생 시 다수의 개발자가 수정에 참여하여 빠른 업데이트가 가능하다. 윈도우와 같은 체계적인 지원은 상대적으로 부족하여 일반인보다는 전문가들이 주로 사용하며, 데비안, 레드햇, Fedora, Ubuntu, CentOS 등 여러 회사가 배포하여 배포 정책·주기가 각기 다르다. 리눅스는 대부분 무료이며 개발자·일반 사용자가 주 사용자이고 커뮤니티에 의해 오픈소스로 개발·배포되는 반면, 유닉스는 대부분 유료이며 메인프레임·워크스테이션 등 대형 시스템 관리자가 주 사용자이고 IBM, HP 등 대부분 사업자에 의해 배포된다. 두 계열 모두 커맨드 기반이 주였으나 최근에는 GUI도 제공하는 추세이며, 기본은 Bourne Shell이나 현재는 다양한 Shell과 호환된다."]]},{"t":"② 맥OS 유닉스 기반·OS X","n":[["설명","매킨토시 OS의 특징 매킨토시 운영체제는 유닉스 기반으로 만들어져 애플사 제품군에서만 사용 가능한 그래픽 기반 운영체제이다. 애플사는 OS라는 운영체제를 오랜 기간 유지해 왔으나 1999년 OS X로 업데이트했으며, 이후 클라이언트· 서버 버전 등으로 제품군을 확대하고 지속적으로 새로운 버전을 발표하고 있다. 매킨토시 OS는 프로그램을 폴더에 복사하고 삭제함으로써 install과 uninstall 과정을 단순화한 것이 특징이다. 드라이버 설치 또한 확장 폴더에 넣고 재부팅하면 자동으로 인식되어 매우 간단하다는 장점이 있다."]]}]}]}]},{"t":"Ⅱ CLI 기본 명령어와 파일 시스템","c":[{"t":"1. 운영체제 제어 방식과 리눅스 디렉터리 구조","c":[{"t":"(1) CLI와 GUI","c":[{"t":"① CLI 명령입력 vs GUI 마우스","n":[["설명","CLI(Command Line Interface)와 GUI(Graphic User Interface) CLI는 사용자가 직접 명령어를 입력하여 컴퓨터에게 명령을 내리는 방식이고, GUI는 마우스로 화면을 클릭하여 컴퓨터를 제어하는 방식이다. 초기 운영체제는 CLI 기반을 많이 사용하였으나 GUI가 개발되며 CLI의 사용 빈도가 낮아졌다가, 최근 오픈소스 기반 개발 환경이 급격히 늘어나며 CLI의 기본 개념과 명령어의 중요성이 다시 부상하고 있다. 윈도우에서 CLI 명령어를 입력하려면 Command 창(cmd)이 필요하며, 프로그램 및 파일 검색에서 \"CMD\" 를 입력하거나 명령 프롬프트를 실행하여 사용한다. 리눅스와 유닉스 명령어는 쉘(Shell)에서 입력 가능하며, 쉘은 컴퓨터 내부를 관리하는 커널과 사용자 간을 연결하는 창의 역할을 한다. 쉘은 세션별 변수 설정, 사용자 요청 기반 명령 실행, 백그라운드 처리, 서브 쉘 설정, 스크립트 기능 등을 지원한다."]]},{"t":"② 리눅스 / 루트·/etc·/tmp","n":[["설명","리눅스 디렉터리 표기와 최상위 디렉터리 리눅스 디렉터리는 윈도우의 폴더와 같은 개념이다. 윈도우에서는 드라이브명이나 역슬래시(\\)를 사용하는 반면, 리눅스에서는 슬래시(/)를 사용한다. 최상위 디렉터리는 /(루트)이며, root는 최상위 디렉터리 아래에 있는 root 계정의 홈 디렉터리를 의미한다. /etc는 시스템 환경 및 주요 설정 파일을 보관하고, /tmp는 임시 파일을 보관하며, /lib는 프로그램 모듈을 보관한다. /usr는 사용자 활용 파일을 보관하고, /dev는 물리적 장치 제어를 위한 파일을 보관하며, /home은각 사용자의 작업 디렉터리이다. /boot는 커널을 위한 프로그램 파일을 보관하고, /root는 슈퍼유저(관리자)의 홈 디렉터리이며, /sbin은 슈퍼유저가 사용하는 명령어를 저장하는 디렉터리이고, /var는 시스템 동작 중변화하는 파일을 저장하는 디렉터리이다."]]}]},{"t":"(2) 파일·디렉터리 조작 명령어","c":[{"t":"① cd·dir/ls·copy/cp 대응","n":[["설명","경로 변경·목록 출력·파일 복사 명령어 경로 변경은 윈도우/MS-DOS와 리눅스 모두 cd 명령어를 사용한다. 목록 출력은 윈도우/MS-DOS에서 dir, 리눅스에서 ls를 사용한다. 파일 복사는 윈도우/MS-DOS에서 copy, 리눅스에서 cp를 사용하며, 구조 복사(디렉터리 전체 복사)는 윈도우에서 xcopy, 리눅스에서도 동일하게 cp(옵션 -r 등 활용)를 사용한다. 디렉터리 생성은 윈도우와 리눅스 모두 mkdir 명령어를 사용한다. 하위 파일 삭제는 윈도우에서 del, 리눅스에서 rm을 사용하며, 권한 설정은 윈도우에서 attrib, 리눅스에서 chmod를 사용한다. 화면 표시(파일 내용 출력)는 윈도우에서 type, 리눅스에서 cat 명령어를 사용한다."]]},{"t":"② tracert/traceroute ·kill·ps","n":[["시험 포인트","네트워크 상태를 점검하는 명령어는 ping이며 윈도우·리눅스 모두 공통으로 사용한다. 접속해 있는 사용자를 표시하는 명령어는 리눅스에서 who이다. 이 표(cd, ls·dir, cp·copy, mkdir, rm·del, chmod·attrib, cat·type, traceroute·tracert, kill, ps, pwd, ping, who)는 실기 시험의 리눅스/유닉스 명령어 활용 문제에서 가장 핵심적으로 다루어지는 부분이므로 반드시 암기해야 한다."],["설명","경로 추적과 프로세스 관련 명령어 목적지까지의 경로를 표시하는 명령어는 윈도우에서 tracert, 리눅스에서 traceroute이다. 프로세스 종료는 리눅스에서 kill 명령어를 사용하고, 실행 중 프로세스 표시는 리눅스에서 ps 명령어를, 디렉터리 경로 표시는 리눅스에서 pwd 명령어를 사용한다."]]}]}]}]}]},{"t":"제3절 프로세스와 메모리 관리","c":[{"t":"Ⅰ 프로세스의 상태와 전이","c":[{"t":"1. 프로세스 관리의 개념","c":[{"t":"(1) 프로세스란","c":[{"t":"① 프로세스=실행 중 프로그램","n":[["시험 포인트","윈도우에서는 작업 관리자의 프로세스 탭에서 다양한 프로세스를 조회할 수 있고, 프로그램이 정상 동작하지 않을 때 \"작업 끝내기\"를 통해 해당 프로세스를 강제로 중단시킬 수 있다. 실기 시험에서는 이러한 실습 환경에서의 프로세스 확인 방법도 함께 다루어질 수 있다."],["설명","프로세스의 정의 프로그램은 파일 형태로 저장되어 있다가 실행을 시키면 동작한다. 이렇게 실행 중인 프로그램을 프로세스(Process), 작업(Job) 또는 태스크(Task)라고 한다. 프로세스 관리 기법에는 일시 중지 및 재실행, 동기화, 통신, 교착상태 처리, 프로세스 생성·삭제 등이 있다."]]},{"t":"② 생성·준비·실행 상태","n":[["실제 사례","생성(Create) 상태는 사용자에 의해 프로세스가 생성된 상태이다. 준비(Ready) 상태는 프로세스가 준비 큐에서 실행을 준비하고 있는 상태이며, 실행(Running) 상태는 준비 큐에 있던 프로세스가 CPU를 할당받아 실제로 실행되는 상태이다."],["설명","생성·준비·실행 상태"]]}]},{"t":"(2) 디스패치와 보류","c":[{"t":"① 디스패치 준비→실행","n":[["설명","디스패치(Dispatch) 디스패치는 준비(ready) 상태에서 실행(running) 상태로 바뀌는 것을 의미한다. 프로세스 스케줄러가 준비 큐에서 다음에 실행할 프로세스를 선택하여 CPU를 할당하는 과정이 바로 디스패치이다. 보류는 실행(running) 상태에서 대기(blocked) 상태로 전이되는 것으로, 프로세스가 실행 중 할당 시간이다 되기 전에 입출력 동작을 해야 할 경우 프로세스가 CPU를 반납하고 보류 상태로 들어가는 것을 의미한다."]]},{"t":"② 깨움 대기→준비","n":[["설명","깨움(Wakeup) 깨움은 대기(blocked) 상태에서 준비(ready) 상태로 넘어가는 것으로, 프로세스가 기다리던 입출력 작업이 완료되어 다시 준비 상태로 돌아가는 것을 의미한다. 시간 제한은 실행(running) 상태에서 준비(ready) 상태로 전이되는 것으로, 클럭 인터럽트를 통해 프로세스가 일정 시간만 CPU를 점유할 수 있게 하는 것을 의미한다. 시분할 시스템에서 특정 프로세스가 CPU를 독점하지 못하도록 하는 핵심 메커니즘이다."]]}]}]}]},{"t":"Ⅱ 프로세스 스케줄링 기법","c":[{"t":"1. 선점형 스케줄링","c":[{"t":"(1) RR과 SRT","c":[{"t":"① RR 시간할당·SRT 잔여최소","n":[["설명","RR(Round Robin, 라운드 로빈) RR은 순서대로 시간 단위로 CPU를 할당하는 방식으로, 자원 사용에 제한된 시간이 있고 할당된 시간이 지나면 자원을 반납하도록 강제한다. 시분할 시스템에서 가장 널리 사용되는 대표적인 선점형 스케줄링 기법이다. SRT는 SJF(Shortest Job First) 기법의 장점을 최대화하여, 남은 실행 시간이 가장 짧은 프로세스를 우선적으로 처리하는 방식이다. 새로운 프로세스가 도착할 때마다 현재 실행 중인 프로세스와 남은 시간을 비교하여 더 짧은 쪽으로 선점이 일어날 수 있다."]]},{"t":"② 다단계 큐","n":[["쉬운 예","다단계 큐는 프로세스를 그룹으로 분류할 수 있을 경우, 그룹에 따라 각기 다른 준비 상태의 큐를 사용하는 기법이다. 예를 들어 시스템 프로세스, 대화형 프로세스, 배치 프로세스 등으로 그룹을 나누어 각각 별도의 큐에서 스케줄링을 수행할 수 있다."],["설명","다단계 큐(Multilevel Queue)"]]}]},{"t":"(2) FIFO와 SJF","c":[{"t":"① FIFO 선입선출·호위효과","n":[["설명","FIFO·FCFS(First In First Out, First Come First Served) FIFO(FCFS)는 선입선출 방식으로, 우선순위에 상관없이 먼저 도착한 프로세스부터 처리하는 가장 단순한 스케줄링 기법이다. 구현이 간단하지만 처리 시간이 긴 프로세스가 먼저 도착하면 뒤의 짧은 프로세스들이 오래 기다려야 하는 호위 효과(Convoy Effect)가 발생할 수 있다. SJF는 CPU 점유 시간이 가장 짧은 프로세스를 먼저 할당하는 처리 방식이다. 평균 대기 시간을 최소화하는데 이론적으로 가장 효율적이지만, 실행 시간이 긴 프로세스는 계속 뒤로 밀려 실행 기회를 얻지 못하는 기아(Starvation) 현상이 발생할 수 있다."]]},{"t":"② HRN (대기+실행)/실행","n":[["설명","HRN(Highest Response-ratio Next) HRN은 SJF 기법을 보완하여 대기 시간과 실행 시간을 함께 고려하는 방식으로, 우선순위 계산식은 (대기시간 + 실행시간) / 실행시간이다. 대기 시간이 길어질수록 우선순위 값이 커지므로, SJF에서 발생할 수 있는 기아 현상을 완화할 수 있다는 장점이 있다. 우선순위 스케줄링은 준비 상태의 프로세스마다 우선순위를 부여하여, 가장 높은 우선순위를 가진 프로세스부터 할당하는 기법이다. 우선순위가 낮은 프로세스가 계속 실행 기회를 얻지 못하는 기아 현상을 방지하기 위해, 대기 시간이 길어질수록 우선순위를 점진적으로 높여주는 에이징(Aging) 기법이 함께 사용되기도 한다."]]}]}]}]}]},{"t":"제4절 네트워크 기초와 OSI 7계층","c":[{"t":"Ⅰ 네트워크의 기본 개념과 분류","c":[{"t":"1. 네트워크와 데이터 교환 방식","c":[{"t":"(1) 네트워크의 개념과 거리별 분류","c":[{"t":"① 프로토콜·LAN/WAN 분류","n":[["설명","네트워크와 프로토콜 네트워크는 원하는 정보를 원하는 수신자 또는 기기에 정확하게 전송하기 위한 기반 인프라이다. 네트워크를 사용하여 정보를 전달할 때는 약속한 규칙에 따라야 하는데, 이를 프로토콜(Protocol)이라고 한다. LAN(근거리 네트워크)은 한 건물 또는 작은 지역을 커버하는 네트워크이다. WAN(광대역 네트워크)은 국가, 대륙과 같이 광범위한 지역을 연결하는 네트워크로, LAN에 비해 전송 거리가 넓어 라우팅 알고리즘이 필요하며, 거리 제약은 없으나 다양한 경로를 지나 정보가 전달되므로 LAN보다 속도가 느리고 에러율이 높다."]]},{"t":"② 회선교환 고정대역폭","n":[["설명","회선 교환 방식 회선 교환 방식은 물리적 전용선을 활용하여 데이터 전달 경로가 정해진 후 동일 경로로만 데이터를 전달하는 방식이다. 대역폭(데이터를 동시에 전송할 수 있는 양)이 고정되어 있어 안정적인 전송률을 확보할 수 있다는 장점이 있다. 패킷 교환 방식은 패킷이라는 단위를 사용하여 데이터를 송수신하는 방식으로, 현재 컴퓨터 네트워크에서 주로 사용하는 방식이다. 정보를 일정한 크기로 분할한 뒤 각각의 패킷에 송수신 주소 및 부가 정보를 입력하여 전송하며, 각 패킷은 서로 다른 경로로 전달될 수 있다."]]}]},{"t":"(2) OSI 7계층의 개념과 하위 계층","c":[{"t":"① OSI 7계층 ISO 표준","n":[["실제 사례","1계층 물리 계층(Physical)은 실제 장비들을 연결하기 위한 연결 장치를 다루며 허브·리피터가 대표 장비이다. 2계층 데이터 링크 계층(Data Link)은 오류와 흐름을 제거하여 신뢰성 있는 데이터 전송을 담당하며 브리지·스위치가 대표 장비이다. 3계층 네트워크 계층(Network)은 다수의 중개 시스템 중 올바른 경로를 선택하도록 지원하며 라우터가 대표 장비이다. 4계층 전송 계층(Transport)은 송신·수신 프로세스 간의 연결을 담당하며 TCP/IP, UDP가 대표 기술이다."],["설명","OSI 모델의 개념 OSI(Open System Interconnection)는 국제 표준화 기구인 ISO(International Standardization Organization)에서 개발한 네트워크 계층 표현 모델이다. 각 계층은 서로 독립적으로 구성되고, 하위 계층의 기능을 이용하여 상위 계층에 기능을 제공하는 구조로 되어 있으며, 1계층인 물리 계층부터 7계층인 응용 계층까지로 정의된다."]]},{"t":"② 5계층 세션·6계층 표현","n":[["시험 포인트","7계층 응용 계층(Application)은 사용자 친화적인 환경을 제공하며 이메일, 웹 등의 서비스가 이계층에서 동작한다. 실기 시험에서는 각 계층의 번호와 이름, 대표 장비를 정확히 매칭하는 문제가 자주 출제되므로 1~7계층을 순서대로 암기해 두어야 한다."],["설명","세션·표현 계층 5계층 세션 계층(Session)은 송신·수신 간의 논리적 연결을 담당한다. 6계층 표현 계층(Presentation)은 코드·문자 등을 번역하여 일관되게 전송하고, 압축·해제·보안 기능을 담당한다."]]}]}]}]},{"t":"Ⅱ 네트워크 주요 장비","c":[{"t":"1. 허브와 리피터","c":[{"t":"(1) 허브(Hub)","c":[{"t":"① 허브 수신포트 외 전송","n":[["설명","허브의 개념과 동작 방식 허브는 여러 대의 컴퓨터를 연결하여 네트워크로 보내거나, 하나의 네트워크로 수신된 정보를 여러 대의 컴퓨터로 송신하기 위한 장비이다. 수신한 프레임을 수신 포트를 제외한 모든 포트로 전송하는 방식으로 동작한다. 더미 허브는 데이터를 단순히 연결한 성형 구조로 구성된 허브이며, 스위치 허브는 스위치 기능을 가진 허브로 데이터의 유무 및 흐름을 제어하는 지능형 허브이다. 요즘 사용되는 대부분의 허브는 스위치 허브 방식이다."]]},{"t":"② 리피터 감쇠신호 재생","n":[["설명","리피터의 역할 리피터는 감쇠된 전송 신호를 새롭게 재생하여 다시 전달하는 재생 중계 장치이다. 신호가 전선을 따라 이동하면서 점점 약해지는 감쇠 현상을 해결하기 위해 사용된다. 허브 등으로 연결하여 통신할 경우, 감쇠된 디지털 신호를 증폭시켜 주는 역할을 하여 신호가 약해지지 않고 목적지 컴퓨터로 수신되도록 한다. 장거리 케이블 배선이 필요한 네트워크 환경에서 특히 중요한 역할을 한다."]]}]},{"t":"(2) 브리지(Bridge)와 스위치(Switch)의 공통점","c":[{"t":"① 브리지 SW·저속·Store&Fo rward","n":[["설명","브리지·스위치의 기본 기능 브리지와 스위치는 두 시스템을 연결하는 네트워킹 장치로, 두 개의 LAN을 연결하여 더 큰 LAN을 만들어 주는 역할을 공통적으로 수행한다. 브리지는 소프트웨어 방식으로 동작하며 저속이고, 포트들이 동일한 속도로 전송하며 2~3개의 포트를 가진다. 데이터를 전부 받은 후 처리하는 Store and Forwarding 방식만을 사용한다."]]},{"t":"② 스위치 HW·고속·Cut Through","n":[["설명","스위치의 전송 방식과 포트 스위치는 하드웨어 방식으로 동작하며 고속이고, 포트마다 다른 속도로 전송할 수 있으며 여러 개(4개 이상)의 포트를 가진다. 목적지 주소만 확인한 후 바로 전송하는 Cut Through 방식과, 브리지의 Store and Forwarding 방식의 장점을 결합한 Fragment Free 방식을 함께 사용한다. 브리지는 목적지 주소를 기준으로 1:1 연결을 지원하는 반면, 스위치는 목적지 주소 기준으로 1:N 연결을 지원한다. 이러한 차이로 인해 스위치가 브리지보다 훨씬 많은 포트와 높은 처리 속도를 제공할 수 있다."]]}]}]}]}]},{"t":"제5절 TCP/IP와 네트워크 프로토콜","c":[{"t":"Ⅰ 주요 네트워크 프로토콜","c":[{"t":"1. 원격 통신과 파일 전송 프로토콜","c":[{"t":"(1) HTTP와 FTP","c":[{"t":"① HTTP 하이퍼텍스트 전송","n":[["시험 포인트","HTTP는 웹(인터넷) 상에서 데이터를 주고받을 수 있는 프로토콜이다. 웹 브라우저와 웹 서버 사이의 통신에 사용되는 가장 기본적인 프로토콜로, 실기 시험에서는 웹 서비스와 관련된 문제의 기본 배경 지식으로 다루어질 수 있다."],["설명","HTTP(HyperText Transfer Protocol)"]]},{"t":"② Telnet과 SSH 원격접속","n":[["시험 포인트","Telnet은 원격 통신에 이용되는 프로토콜로, 데이터 전송 시 암호화 작업이 없어 보안성이 낮으며 포트 번호는 23번을 사용한다. SSH(Secure Shell)는 마찬가지로 원격 통신에 이용되는 프로토콜이지만, 데이터 전송 시 암호화 작업이 존재하여 보안성이 높으며 포트 번호는 22번을 사용한다. 실기 시험에서는 Telnet과 SSH의 보안성 차이와 포트 번호(23번, 22번)를 짝지어 암기하는 것이 중요하다."],["설명","Telnet과 SSH"]]}]},{"t":"(2) TCP와 UDP","c":[{"t":"① TCP 신뢰성 vs UDP 고속","n":[["설명","TCP(Transmission Control Protocol) TCP는 데이터를 주고받는 과정에서 데이터를 접수하는 작업을 통해 서로 확인하는 과정을 거쳐, 정상적으로 데이터 누락 등을 확인할 수 있는 신뢰성 있는 데이터 전송 프로토콜이다. UDP는 데이터를 주고받는 과정에서 확인 과정을 거치지 않아 신뢰성이 떨어지는 프로토콜이다. 다만 확인 과정을 거치지 않기 때문에 TCP보다 데이터 전송 속도가 빠르다는 특징이 있다."]]},{"t":"② DHCP 유동IP·ARP IP→MAC","n":[["설명","DHCP와 ARP·RARP DHCP(Dynamic Host Configuration Protocol)는 각종 TCP/IP 프로토콜 및 IP 주소 등을 자동으로 클라이언트에게 제공 및 사용할 수 있도록 해주는 프로토콜(유동 IP 설정)이다. ARP(Address Resolution Protocol)는 IP(논리적 주소)에 대응하는 이더넷 카드의 MAC(물리적 주소)을 검색하여 변환해 주는 프로토콜이며, RARP는 ARP와 반대로 MAC(물리적 주소)을 IP(논리적 주소)로 변환해 주는 프로토콜이다. SMTP(Simple Mail Transfer Protocol)는 전자우편 송신 프로토콜이며, POP3(Post Office Protocol 3)는 전자우편 수신 프로토콜이다. 이메일을 보내는 과정과 받는 과정에 서로 다른 프로토콜이 사용된다는 점을 구분하여 기억해야 한다."]]}]}]}]},{"t":"Ⅱ IP 주소 체계와 TCP/IP 4계층","c":[{"t":"1. IPv4와 IPv6","c":[{"t":"(1) IP 주소의 개념과 IPv4","c":[{"t":"① IPv4 32비트·KISA 관리","n":[["설명","IP 주소의 개념 IP(Internet Protocol) 주소는 전 세계 컴퓨터에 부여되는 유일한 식별자이다. 각 나라의 공인 기관에서 할당하고 관리하는데, 우리나라의 경우 한국인터넷진흥원(KISA)이 관리를 담당한다. IPv4는 인터넷 초기부터 현재까지 쓰이고 있는 주소 체계이며, 000.000.000.000과 같이 4자리씩(8비트씩) 4묶음(10진수)으로 표시하고 총 32비트로 약 43억 개를 부여할 수 있다. 최근 디바이스의 증가로 IPv4가 가진 주소의 양이 부족해질 수 있어 IPv6가 공표되었으며, NAT(Network Address Translator)가 IPv4와 IPv6 두 주소 체계를 변환하는 역할을 담당한다."]]},{"t":"② IPv6 128비트·IPsec 기본","n":[["설명","IPv6의 특징과 IPv4·IPv6 비교 IPv6는 128비트 주소 길이를 가지며 16비트씩 8묶음(16진수)으로 표시하고, 약 43억×43억×43억×43억 개의 주소를 부여할 수 있다. IPv4는 A, B, C 등 클래스 단위의 비순차적 할당 방식을 사용하는 반면, IPv6는 네트워크 규모 및 단말기 수에 따른 순차적 할당 방식을 사용한다. 또한 IPv6는 IPsec 보안 기능을 기본으로 제공하고 헤더 크기가 고정적이라는 점에서 IPv4보다 개선되었다. 클래스 A(첫 옥텟 0xxxxxxx, 범위 0~127)는 대형 기관(대륙 간)에서 사용하고, 클래스 B(10xxxxxx, 128~191)는 중형 기관(국가 간)에서 사용하며, 클래스 C(110xxxxx, 192~223)는 소형 기관(기업 간)에서 사용한다. 클래스 D(1110xxxx, 224~239)는 그룹 통신·멀티캐스트용, 클래스 E(1111xxxx, 240~254)는 연구·실험용으로 사용된다."]]}]},{"t":"(2) TCP/IP 4계층 모델","c":[{"t":"① TCP/IP 4계층 통칭","n":[["설명","TCP/IP의 개념 TCP/IP란 TCP와 IP 프로토콜만을 지칭하는 것이 아니라, UDP(User Datagram Protocol), ICMP(Internet Control Message Protocol), ARP(Address Resolution Protocol), RARP(Reverse ARP) 등 관련된 프로토콜을 통칭하는 개념이다. TCP/IP 4계층은 응용(Application) 계층, 전송(Transport) 계층, 인터넷(Internet) 계층, 네트워크 액세스(Network Access) 계층으로 구성된다. OSI 7계층의 응용·표현·세션 계층은 TCP/IP의 응용 계층에 대응하고, 전송 계층은 그대로 전송 계층에 대응하며, 네트워크 계층은 인터넷 계층에, 데이터링크·물리 계층은 네트워크 액세스 계층에 대응한다."]]},{"t":"② TCP CRC·흐름제어·1:1","n":[["설명","TCP의 특징 TCP는 CRC 체크와 재전송 기능을 통해 신뢰성 있는 전송을 확보하고, Flow Control(흐름 제어) 기능을 수행하여 단계별 데이터 전송 상황을 체크한다. 논리적인 1:1 가상 회선을 지원하여 정해진 경로로만 데이터가 전달되며, 대표 서비스로는 FTP, Telnet, HTTP, SMTP, POP, IMAP 등이 있다. UDP는 연결되어 있으면 데이터를 송신할 수 있으나 수신 여부는 확인하기 어려우며, Flow Control과 Error Control을 하지 않아 신뢰성 있는 데이터 전송에는 부적합하다. 대신 하나의 송신 정보를 다수의 인원이 수신해야 할 경우에 사용하기 적합하며, 대표 서비스로는 SNMP, DNS, TFTP, NFS, NETBIOS, 인터넷 게임·방송·증권 시세 등이 있다. TCP는 수신 측의 수신 가능 상태를 단계별로 체크하며 데이터를 전송하는 반면, UDP는 확인 작업 없이 데이터를 송신하기만 한다는 것이 가장 큰 차이점이다."]]}]}]}]}]},{"t":"제6절 네트워크 핵심 알고리즘","c":[{"t":"Ⅰ 패킷 스위칭과 회선 교환","c":[{"t":"1. 패킷 스위칭 관련 기술","c":[{"t":"(1) 패킷 스위칭의 개념","c":[{"t":"① 패킷 스위칭·X.25","n":[["설명","패킷 스위칭(패킷 교환)이란 패킷 스위칭은 컴퓨터 네트워크 통신 방식 중 하나로, 작은 블록의 패킷으로 데이터를 전송하며 데이터를 전송하는 동안만 네트워크 자원을 사용하도록 하는 방법이다. 현재 가장 많은 사람들이 사용하는 통신 방식이며, 정보 전달의 단위인 패킷은 여러 통신 지점(Node)을 연결하는 데이터 연결 상의 모든 노드들 사이에서 개별적으로 경로가 제어된다. X.25는 패킷이라고 불리는 데이터 블록을 사용하여 대용량의 데이터를 다수의 패킷으로 분리하여 송신하며, 수신 측에서는 다수의 패킷을 결합하여 원래의 데이터로 복원한다. 전기 통신 국제기구인 ITU-T에서 관리 감독하는 프로토콜로, OSI 7계층 중 1~3계층(물리·데이터링크·네트워크 계층)까지를 담당한다. 초기에는 에러 제어나 흐름 제어를 위한 복잡한 기능으로 인해 성능상의 오버헤드가 발생했기 때문에, 현재는 프레임 릴레이나 ISDN, ATM 등 고속망으로 대체되었다."]]},{"t":"② 프레임 릴레이 1~2계층","n":[["설명","프레임 릴레이(Frame Relay) 프레임 릴레이는 ISDN을 사용하기 위한 프로토콜로 ITU-T에 의해 표준으로 작성되었다. X.25가 고정된 대역폭을 갖는 반면, 프레임 릴레이는 사용자의 요청에 따라 유연한 대역폭을 할당하며, 망의 성능 향상을 위해 에러 제어와 흐름 제어 기능을 단순화했다. X.25가 OSI 7계층 중 1~3계층을 담당하는 것과 달리 프레임 릴레이는 1~2계층만을 담당하며, 전용선을 사용하는 것보다 가격이 저렴하고 기술적으로 X.25보다 우위에 있다. ATM(비동기 전송 모드)은 광대역 전송에 쓰이는 스위칭 기법이다. 동기화를 맞추지 않아 보낼 데이터가 없는 사용자의 슬롯을 다른 사람이 사용할 수 있도록 하여 네트워크상의 효율성을 높인다. ATM망은 연결형 회선이기 때문에 하나의 패킷을 보내 연결을 설정하고 이후 실데이터 전송이 이루어지며, OSI 7계층과는 다른 고유한 참조 모델(물리 계층, ATM 계층, AAL 계층)을 가지고 있다."]]}]},{"t":"(2) 서킷 스위칭의 개념","c":[{"t":"① 서킷 스위칭 자원 독점","n":[["설명","서킷 스위칭(회선 교환)이란 서킷 스위칭은 패킷 스위칭과 달리, 네트워크 리소스를 특정 사용층이 독점하도록 하는 것을 의미한다. 네트워크를 독점적으로 사용하기 때문에 전송이 보장(Guaranteed)된다는 것이 가장 큰 특징이다. 서킷 스위칭은 서킷을 확보하기 위한 작업을 진행하고, 실데이터를 전송하며, 서킷을 닫는 프로세스로 진행된다. 이러한 작업이 진행되는 동안 다른 기기들은 해당 경로를 사용할 수 없다는 점이 패킷 스위칭과의 근본적인 차이이다."]]},{"t":"② 패킷 공유 vs 서킷 독점","n":[["설명","자원 사용 방식의 차이 패킷 스위칭은 데이터를 전송하는 동안만 네트워크 자원을 사용하므로 여러 통신이 자원을 공유하며 효율적으로 사용할 수 있는 반면, 서킷 스위칭은 통신이 이루어지는 전체 시간 동안 자원을 독점하므로 자원 활용의 유연성은 떨어지지만 전송 품질과 순서가 보장된다는 장점이 있다. 패킷 스위칭은 짧은 데이터 트래픽이 간헐적으로 발생하는 인터넷 통신에 적합하고, 서킷 스위칭은 통화 품질이 일정하게 유지되어야 하는 전통적인 전화망 통신에 적합하다. 현재 컴퓨터 네트워크에서는 패킷 스위칭 방식이 주로 사용된다."]]}]}]}]},{"t":"Ⅱ 라우팅 알고리즘","c":[{"t":"1. 거리 벡터 알고리즘과 링크 상태 알고리즘","c":[{"t":"(1) 거리 벡터 알고리즘(DV)","c":[{"t":"① 거리 벡터 전체 테이블 교환","n":[["설명","거리 벡터 알고리즘의 개념 거리 벡터 알고리즘은 라우터와 라우터 간의 최단 경로 스패닝 트리를 찾고, 그 최적 경로를 이용할 수 없을 경우 다른 경로를 찾는 방식이다. 라우팅 알고리즘은 데이터가 송신 측으로부터 수신 측까지 전달되는 과정에서 다양한 물리적 장치들을 거치는 가운데, 목적지까지의 최적 경로를 산출하기 위한 방법이다. 각 라우터가 업데이트될 때마다 전체 라우팅 테이블을 이웃 라우터에게 보내지만, 수신된 경로 비용 정보는 인접한 이웃 라우터에게만 전달되며, 링크 상태 라우팅 알고리즘보다 계산 면에서 단순하다는 특징이 있다."]]},{"t":"② 링크 상태 전체 토폴로지","n":[["설명","링크 상태 알고리즘의 개념 링크 상태 알고리즘은 라우터와 라우터 간의 모든 경로를 파악하여 대체 경로를 사전에 마련해 두는 방식이다. 네트워크 전체의 위상(토폴로지) 정보를 각 라우터가 동일하게 유지한다는 특징이 있다. 링크 상태 알고리즘을 사용하면 네트워크를 일관성 있게 파악할 수 있으나, 거리 벡터 알고리즘에 비해 계산이 더 복잡하고 트래픽 정보를 광범위한 범위까지 전달해야 한다는 부담이 있다."]]}]},{"t":"(2) RIP와 IGRP","c":[{"t":"① RIP 30초 갱신·IGRP 시스코","n":[["설명","RIP(Routing Information Protocol) RIP는 최초의 라우팅 프로토콜로 거리 벡터 알고리즘을 활용하며, 30초 주기로 전체 라우팅 정보를 갱신한다. 변화가 생겼을 때 업데이트에 상당한 시간이 소요되며, 라우팅 루프가 발생할 가능성이 있다는 단점이 있다. IGRP는 RIP의 문제점을 개선하기 위해 시스코(Cisco)에서 개발한 프로토콜로, 네트워크 상태(대역폭, 속도 등)를 종합적으로 고려하여 라우팅한다는 특징이 있다."]]},{"t":"② OSPF 링크상태·BGP ISP간","n":[["설명","OSPF(Open Shortest Path First) OSPF는 링크 상태 알고리즘을 사용하는 라우팅 프로토콜로, 발생한 변경 정보에 대해 RIP보다 빠르게 업데이트되며, 네트워크 토폴로지에 대한 정보가 전체 라우터에 동일하게 유지된다는 특징이 있다. BGP는 규모가 큰 네트워크의 상호 연결과, 대형 사업자(ISP) 간의 상호 라우팅에 사용되는 프로토콜이다. 인터넷 전체를 구성하는 여러 자율 시스템(AS) 간의 경로 교환에 사용되는 대표적인 외부 게이트웨이 프로토콜이다."]]}]}]}]}]},{"t":"제7절 데이터베이스 기초와 DBMS 종류","c":[{"t":"Ⅰ 데이터베이스의 개념과 용어","c":[{"t":"1. 데이터베이스의 개념과 특징","c":[{"t":"(1) 데이터베이스란","c":[{"t":"① DB 정의·중복제거·무결성","n":[["설명","데이터베이스의 정의 데이터베이스는 다수의 인원, 시스템 또는 프로그램이 사용할 목적으로 통합하여 관리되는 데이터의 집합이다. IT 시스템의 발달로 급증하는 데이터에 대한 효과적인 관리가 중요해졌으며, 데이터베이스 관리의 핵심은 자료의 중복성 제거, 무결성 확보, 일관성 유지, 유용성 보장에 있다. 데이터베이스는 실시간 접근성(Real-time Accessibility, 요청 즉시 처리·응답), 계속적인 변화 (Continuous Evolution, 삽입·삭제·갱신을 통해 지속적으로 최신 상태 유지), 동시 공유(Concurrent Sharing, 여러 사용자가 동시에 서로 다른 목적으로 데이터에 접근), 내용에 의한 참조(Content Reference, 저장 위치가 아닌 데이터의 내용으로 참조)라는 특징을 가진다."]]},{"t":"② 데이터베이스 설계 순서","n":[["실제 사례","데이터베이스는 요구조건 분석 → 개념적 설계 → 논리적 설계 → 물리적 설계 → 구현의 다섯 단계 순서로 설계된다. 요구조건 분석 단계에서 업무 요건을 파악하고, 개념적 설계에서 ERD와 같은 개념적 모델을 도출하며, 논리적 설계에서 특정 DBMS에 맞는 논리 스키마로 변환하고, 물리적 설계에서 저장 구조를 결정한뒤 구현 단계에서 실제 데이터베이스를 만든다."],["설명","데이터베이스 설계 순서"]]}]},{"t":"(2) 속성·튜플·차수·기수","c":[{"t":"① 속성=열·튜플=행·차수·기수","n":[["설명","속성(Attribute)과 튜플(Tuple) 속성(Attribute)은 릴레이션 내의 하나의 열을 의미하며, 어떤 개체(Entity)를 표현하고 저장한 것으로 흔히 컬럼(Column) 또는 필드(Field)로 표현된다. 튜플(Tuple)은 릴레이션 내의 하나의 행을 의미하며, 레코드 (Record) 또는 로우(Row)로 표현된다. 차수(Degree)는 하나의 릴레이션 내에 들어 있는 속성의 수를 의미하며, 기수(Cardinality)는 하나의 릴레이션 내에 들어 있는 튜플의 수를 의미한다. 도메인(Domain)은 릴레이션 내 각각의 속성들이 가질 수 있는 값들의 집합을 의미한다."]]},{"t":"② 후보키·기본키·슈퍼키","n":[["설명","후보키·기본키·슈퍼키 후보키(Candidate Key)는 유일성과 최소성을 만족하는 속성들의 집합이다. 기본키(Primary Key)는 후보키 중 선정된 키로, 중복 값 입력이 불가능하고 Null 값을 가질 수 없다. 슈퍼키(Super Key)는 유일성은 만족하지만 최소성은 만족하지 않는 속성들의 집합이다. 대체키(Alternate Key)는 후보키 중 기본키로 선택되지 못한 나머지 후보키를 의미한다. 외래키(Foreign Key)는 다른 테이블의 행을 식별하는 키로, 참조되는 테이블의 기본키를 가리키며 두 테이블 간의 관계를 표현하는 데 사용된다."]]}]}]}]},{"t":"Ⅱ DBMS의 종류와 특징","c":[{"t":"1. DBMS의 개념과 장단점","c":[{"t":"(1) DBMS의 개념","c":[{"t":"① DBMS 정의·데이터 관리 SW","n":[["설명","DBMS(Database Management System)의 정의 DBMS는 데이터 관리의 복잡성을 해결하는 동시에, 데이터 추가·변경·검색·삭제 및 백업·복구·보안 등의 기능을 지원하는 소프트웨어이다. 저장되는 정보는 텍스트, 이미지, 음악 파일, 지도 데이터 등으로 매우 다양하며, SNS의 발달과 빅데이터의 폭넓은 활용으로 인해 데이터의 종류와 양이 급격히 증가하는 추세이다. 데이터 무결성은 부적절한 자료가 입력되어 동일한 내용에 대해 서로 다른 데이터가 저장되는 것을 허용하지 않는 성질이다. 데이터 일관성은 삽입·삭제·갱신·생성 후에도 저장된 데이터가 변함없이 일정해야 하는 성질이며, 데이터 회복성은 장애가 발생했을 때 특정 상태로 복구되어야 하는 성질이다. 데이터 보안성은 불법적인 노출·변경·손실로부터 보호되어야 하는 성질이고, 데이터 효율성은 응답 시간·저장 공간 활용 등이 최적화되어 사용자·소프트웨어·시스템의 요구 조건을 만족시켜야 하는 성질이다."]]},{"t":"② DBMS 장점·DBA 필요 단점","n":[["설명","DBMS의 장점 DBMS를 사용하면 데이터 중복을 최소화하고, 데이터 공유(일관성 유지)가 가능하며, 정합성·무결성·보안성을 유지할 수 있다. 또한 사용자 중심의 데이터 처리, 데이터 표준화 적용, 데이터 접근 용이성, 저장 공간 공유로 인한 절약 효과를 얻을 수 있다. DBMS는 전문적인 데이터베이스 전문가(DBA)가 필요하고, 구축을 위한 서버가 필요하며 유지 비용이 발생한다. 데이터 백업과 복구가 어려울 수 있고, 시스템이 복잡하며, 대용량 디스크로 접근이 집중될 때 병목 현상으로 과부하가 발생할 수 있다는 단점이 있다."]]}]},{"t":"(2) DBMS 구조에 따른 분류","c":[{"t":"① 계층형 IMS·망형 DBMS","n":[["설명","계층형 DBMS와 망형 DBMS 계층형 DBMS(Hierarchical DBMS)는 데이터를 상하 종속적인 관계로 계층화하여 관리하는 데이터베이스로, 데이터 접근 속도는 빠르지만 종속적인 구조로 인해 변화하는 데이터 구조에 유연하게 대응하기 어렵다는 단점이 있으며 IMS, System 2000 등이 대표적이다. 망형 DBMS(Network DBMS)는 데이터의 구조를 네트워크 상의 망상 형태로 논리적으로 표현한 모델로, 트리 구조나 계층형 데이터베이스보다는 유연하지만 설계가 복잡하다는 단점이 있으며 IDS, TOTAL, IDMS 등이 대표적이다. 관계형 DBMS(Relational DBMS)는 가장 보편화된 데이터베이스 관리 시스템으로, 데이터를 저장하는 테이블의 일부를 다른 테이블과 상하 관계로 표시하며 상관 관계를 정리한다. 변화하는 업무나 데이터 구조에 대한 유연성이 좋아 유지 관리가 용이하다는 장점이 있으며, Oracle, SQL Server, MySQL, MariaDB 등이 대표적이다."]]},{"t":"② 문서형 MongoDB·그래프형","n":[["설명","문서 저장 DBMS와 그래프 DBMS, Key-Value DBMS 문서 저장 DBMS(Document Store DBMS)는 관계형 DBMS와 달리 스키마 구조가 필요 없고 일관된 구조가 필요 없으며, MongoDB·Amazon DynamoDB·Couchbase 등이 대표적이다. 그래프 DBMS(Graph DBMS)는 노드와 에지로 특징되는 요소에 특화되어 노드 간 관계를 구조화하여 저장하며 Neo4j 등이 대표적이다. Key-Value DBMS는 가장 간단한 형태의 DBMS로 임베디드 시스템과 같은 간단한 시스템에 적합하며 Redis, Memcached 등이 대표적이다. 상용화 DBMS는 상업적 목적으로 판매되는 소프트웨어로 Oracle, MS SQL Server, DB2, Microsoft Access, Teradata 등이 있다. 오픈소스 기반 DBMS는 누구에게나 공개되어 제한 없이 사용할 수 있는 소프트웨어로 MySQL, PostgreSQL, MongoDB, Redis, Elasticsearch 등이 있다. 관계형 DBMS를 넘어 비관계형(NoSQL, Not Only SQL) 데이터까지 다루는 시스템도 점차 늘어나는 추세이며, NoSQL은 전통적인 관계형 데이터베이스보다 덜 제한적인 일관성 모델을 이용하여 빅데이터와 실시간 웹 애플리케이션에활 용된다."]]}]}]}]}]},{"t":"제8절 개체-관계 다이어그램(ERD) 작성 실무","c":[{"t":"Ⅰ ERD의 구성요소","c":[{"t":"1. 엔티티와 속성","c":[{"t":"(1) ERD의 개념과 E-R 모델","c":[{"t":"① ERD 엔티티 관계 도식화","n":[["설명","ERD(E-R Diagram)의 개념 ERD는 업무 분석 결과로 도출된 실체(엔티티)와 엔티티 간의 관계를 도식화한 것이다. 요소들 간의 연관성을 도식화하기 때문에 데이터베이스 관리자, 개발자, 사용자 모두가 데이터의 흐름과 연관성을 공통적으로 쉽게 확인할 수 있다는 장점이 있다. ERD의 구성요소인 개체, 관계, 속성을 추출하기 위해서는 업무나 시스템에 대한 명확한 정의가 필요하다. E-R 모델은 ERD로 도식화하기 전에 각 개체를 사각형, 화살표, 마름모로 표기한 형태를 의미하며, 업무 설명에서 개체·관계·속성을 추출하는 것이 ERD 작성의 첫 단계이다."]]},{"t":"② 엔티티 □·속성 ○","n":[["설명","엔티티(Entity) 엔티티는 사물 또는 사건을 의미하며 개체라고도 한다. ERD에서 엔티티는 사각형(□)으로 나타내고 사각형 안에는 엔티티의 이름을 입력하는데, 엔티티 이름은 가능한 한 대문자로 쓰고 단수형으로 명명하며 유일한 단어로 정해야 한다는 규칙이 있다. 속성은 엔티티가 가지고 있는 요소 또는 성질을 의미한다. 속성은 선으로 연결된 동그라미(○)로 표기하는 Chen Model 방식과, 표 형식으로 표기하는 Crow's Foot Model 방식이 있다. 관계형 데이터베이스 활용을 위해서는 Crow's Foot Model이 더 편리하며, 이때 속성명은 단수형으로 명명하고 엔티티명은 사용하지 않으며, 속성이 필수 사항(NOT NULL)인지 아닌지(NULL 허용)를 고려하여 작성해야 한다."]]}]},{"t":"(2) 관계의 개념과 카디널리티","c":[{"t":"① 관계 마름모·1:1·1:N·M:N","n":[["설명","관계(Relationship)의 표기 관계는 두 엔티티 간의 관계를 정의하는 것으로, 개체는 사각형(□), 속성은 타원형(○)을 이용하여 표시하고, 관계는 마름모 또는 Crow's Foot 표기법의 선 끝 기호로 표시한다. ERD의 관계 표식에는 1:1 관계(하나의 개체가 다른 하나의 개체와만 대응), 1:N 관계(하나의 개체가 여러 개체와 대응), M:N 관계(여러 개체가 여러 개체와 대응)가 있다. 필수 관계와 선택(필수가 아닌) 관계를 구분하여 표시하는 것도 중요하며, 1:1은 1:1을 포함하고, 1:N은 1:1과 1:N을 포함하며, M:N은 1:1, 1:N, N:1, M:N을 모두 포함하는 포괄적 관계로 이해할 수 있다."]]},{"t":"② 기본키 밑줄·Crow's Foot","n":[["설명","개체·관계 표기 기호 E-R 모델에서 개체는 사각형으로, 관계는 마름모(다이아몬드)로 표기하며 각 도형 안에는 개체명 또는 관계 명을 기입한다. 기본키 속성은 밑줄로 구분하여 표시하는 것이 일반적인 관례이다. 개체와 속성, 개체와 관계는 실선으로 연결하여 연관성을 표시한다. Crow's Foot Model에서는 이 연결선의 끝에 표시되는 기호(일( ), 까마귀 발(<) 등)의 조합으로 1:1, 1:N, M:N 및 필수·선택 관계를 모두 표현할수 있다는 특징이 있다."]]}]}]}]},{"t":"Ⅱ ERD 작성 절차와 테이블 생성","c":[{"t":"1. 요소 추출과 E-R 모델 작성","c":[{"t":"(1) 업무 시나리오로부터 요소 추출","c":[{"t":"① 시나리오 분석 예시","n":[["쉬운 예","예를 들어 \"보험사에서 사용하는 데이터베이스를 설계한다. 고객이 있고 고객이 사용하는 계좌가 있다. 고객에 대한 정보로는 이름, 주소, 휴대전화번호, 주민등록번호가 있다. 고객 계좌에 대한 정보로는 계좌번호, 계좌종류, 잔고, 개설일자, 인출한도가 있다. 주소 정보에 대한 정보로는 시군구, 동, 상세주소, 우편번호가 있다. \"는 업무 시나리오가 주어졌다고 가정한다."],["설명","시나리오 분석 예시"]]},{"t":"② 고객·계좌·주소 E-R 모델","n":[["쉬운 예","관계형 스키마 작성을 위한 테이블 형태를 표시할 때, 테이블의 가장 윗칸은 유일하게 필드를 구분할수 있는 구분자(유일키)가 되어야 한다(유일키를 만드는 방법에는 일련번호를 부여하는 방법 등이 있다). 유일키 아래 칸에는 나머지 속성들을 기입한다. 예를 들어 \"고객은 다수의 계좌를 보유할 수 있다\"와 같은 제약조건은 고객:계좌가 1:N 관계임을 의미하므로 이를 스키마에 반영해야 한다."],["설명","E-R 모델 작성 추출된 개체(고객, 계좌, 주소)와 속성, 관계를 가지고 E-R 모델을 작성한다. 고객 개체와 계좌 개체, 고객 개체와 주소 개체 사이에 각각 관계선을 연결하고, 각 개체 아래에 속성을 나열하는 형태로 작성한다."]]}]},{"t":"(2) 테이블 간 관계 설정","c":[{"t":"① 기본키-외래키 테이블 연결","n":[["쉬운 예","각 테이블의 기본키에는 (PK) 표시를, 다른 테이블을 참조하는 외래키에는 별도 표시를 하여 관계를 명확히 드러낸다. 예를 들어 고객 테이블의 고객번호(PK)를 계좌 테이블에서 외래키로 참조하도록 설계하면, 계좌가 어느 고객의 것인지 식별할 수 있는 관계형 스키마가 완성된다."],["설명","테이블 간 관계 표시 테이블 간 관계를 표시할 때는 1:1, 1:N, N:1, N:M의 관계를 고려해야 한다. 테이블 간에 연결할 수 있는 속성( 주로 기본키-외래키 쌍)을 부여하여, 하나의 테이블에서 다른 테이블의 값을 찾아갈 수 있도록 구성해야 한다."]]},{"t":"② 논리→물리 스키마 영문 변환","n":[["시험 포인트","테이블 생성을 위한 SQL 명령어를 작성할 때는 정수형, 문자형(가변 길이는 VARCHAR), 날짜형 등 컬럼의 성격에 맞는 데이터 타입을 SQL 표준을 참조하여 정확히 지정해야 한다. 이렇게 논리적 설계(ERD)에서 물리적 설계(CREATE TABLE)로 이어지는 전체 흐름이 실기 시험의 데이터베이스 설계 문제에서 다루어질 수 있다."],["설명","논리 스키마와 물리 스키마 매칭 관계형 테이블 생성을 위해서는 논리 스키마와 매칭되는 물리 스키마를 작성해야 한다. SQL 표준 언어는 한글 컬럼명·테이블명 입력이 원칙적으로 허용되지 않으므로, 논리적으로 \"고객번호\"였던 속성명을 물리적으로는 Client_ID와 같은 영문 식별자로 변환하는 과정이 필요하다.\nCREATE TABLE Address (\n     SEQ_ID INT PRIMARY KEY,\n     Address1 VARCHAR(255),\n     Address2 VARCHAR(255),\n     Address3 VARCHAR(255),\n     Postal_Code VARCHAR(255),\n     Client_ID VARCHAR(255)\n);"]]}]}]}]}]},{"t":"제12절 리눅스·유닉스 명령어 심화 실습","c":[{"t":"Ⅰ 파일·디렉터리 명령어 심화 활용","c":[{"t":"1. 경로 이동과 목록 조회 실습","c":[{"t":"(1) cd·pwd 명령어 실습","c":[{"t":"① cd ..·~·- 경로 이동","n":[["시험 포인트","cd 명령어는 절대 경로(/로 시작)와 상대 경로(현재 위치 기준) 모두를 인식한다. ..은 상위 디렉터리, ~는 홈 디렉터리, -는 바로 직전에 있던 디렉터리를 의미하는 특수 기호로, 실기 시험에서 이 기호들의 의미를 묻는 문제가 출제될 수 있다. $ pwd /home/user/project"],["설명","cd 명령어의 다양한 활용"]]},{"t":"② ls -l 상세목록 d/-","n":[["설명","ls -l(상세 목록 출력) $ ls -l"]]}]},{"t":"(2) cp·mkdir 명령어 실습","c":[{"t":"① cp -r 디렉터리 재귀복사","n":[["설명","cp 명령어의 단일 파일과 디렉터리 복사"]]},{"t":"② rm -r·rm -rf 강제삭제","n":[["설명","rm 명령어의 기본 사용법"]]}]}]}]},{"t":"Ⅱ 권한·프로세스·네트워크 명령어 심화 활용","c":[{"t":"1. 권한 설정과 프로세스 관리 실습","c":[{"t":"(1) chmod 명령어 실습","c":[{"t":"① chmod 755·644 숫자표기","n":[["설명","chmod의 숫자 표기법 $ chmod 755 script.sh $ chmod 644 report.txt chmod의 숫자 표기법은 소유자·그룹·기타 사용자 각각에 대해 읽기(4)+쓰기(2)+실행(1)의 합으로 권한을 표현한다. 755는 소유자에게 rwx(7=4+2+1), 그룹과 기타 사용자에게 r-x(5=4+1)를 부여하는 것이고, 644는 소유자에게 rw-(6=4+2), 그룹과 기타 사용자에게 r--(4)만 부여하는 것이다."]]},{"t":"② ps -ef PID 확인","n":[["설명","ps 명령어로 프로세스 확인 $ ps -ef"]]}]},{"t":"(2) ping과 traceroute 실습","c":[{"t":"① ping ICMP 응답시간","n":[["설명","ping 명령어로 연결 상태 확인 $ ping www.example.com 64 bytes from 93.184.216.34: icmp_seq=1 ttl=56 time=15.2 ms ping은 지정한 호스트로 ICMP 패킷을 보내 응답 시간을 측정하는 명령어로, 네트워크 연결 상태를 점검하는 가장 기본적인 도구이다. 응답이 오지 않는다면 대상 호스트가 다운되었거나, 네트워크 경로에 문제가 있거나, 방화벽에서 ICMP를 차단하고 있을 가능성을 의심해야 한다. $ traceroute www.example.com"]]},{"t":"② who 접속 사용자 확인","n":[["실제 사례","실무에서는 여러 명령어를 파이프(|)로 연결하여 조합해서 사용하는 경우가 많다. 위 예시는 로그 디렉터리로 이동해 error가 포함된 파일을 찾고(ls -l | grep error), myapp이라는 이름의 프로세스를 찾아(ps -ef | grep myapp) 해당 프로세스의 PID를 추출하여 강제 종료하는 흐름을 보여준다. 실기 시험에서는 이런 개별 명령어의 의미를 정확히 이해하고 있는지를 묻는 문제가 출제될 수 있다."],["설명","who 명령어로 접속 사용자 확인 $ who"]]}]}]}]}]},{"t":"제14절 실기 시험 대비 최종 요약과 용어 사전","c":[{"t":"Ⅰ 운영체제·네트워크 핵심 요약","c":[{"t":"1. 운영체제 핵심 요약","c":[{"t":"(1) 운영체제 목적과 계열 요약","c":[{"t":"① OS 4대 성능 평가 항목","n":[["시험 포인트","운영체제의 4대 성능 평가 항목은 처리 능력(Throughput, 클수록 좋음), 반환 시간(Turnaround Time, 작을수록 좋음), 사용 가능도(Availability, 클수록 좋음), 신뢰도(Reliability, 클수록 좋음)이다. 각 항목이 크면 좋은지 작으면 좋은지를 정확히 구분하여 암기해야 한다."],["설명","운영체제 4대 성능 평가 항목"]]},{"t":"② 프로세스 5대 상태·전이","n":[["시험 포인트","프로세스의 5대 상태는 생성-준비-실행-대기-종료이다. 상태 전이 용어는 디스패치(준비→실행) , 보류(실행→대기), 깨움(대기→준비), 시간 제한(실행→준비)의 네 가지로, 각각 어느 상태에서 어느 상태로 이동하는지를 화살표로 정리하여 암기하면 헷갈리지 않는다."],["설명","프로세스 5대 상태와 전이 용어"]]}]},{"t":"(2) OSI 7계층 핵심 요약","c":[{"t":"① OSI 계층별 대표 장비","n":[["시험 포인트","1계층 물리(허브·리피터), 2계층 데이터링크(브리지·스위치), 3계층 네트워크(라우터), 4계층 전송(TCP/UDP), 5계층 세션, 6계층 표현(압축·암호화), 7계층 응용(사용자 서비스)으로 요약된다. \"물-데-네- 전-세-표-응\"과 같은 두문자를 활용한 암기법도 실기 시험 직전 빠른 복습에 도움이 된다."],["설명","계층별 이름과 대표 장비 요약"]]},{"t":"② IP 클래스 첫 옥텟 범위","n":[["시험 포인트","클래스 A(0~127, 대형기관), 클래스 B(128~191, 중형기관), 클래스 C(192~223, 소형기관), 클래스 D(224~239, 멀티캐스트), 클래스 E(240~254, 연구용)로 요약된다. 첫 옥텟의 숫자 범위와 클래스, 사용 목적을 하나의 표로 정리해 암기하는 것이 효율적이다."],["설명","IP 클래스 첫 옥텟 범위 요약"]]}]}]}]},{"t":"Ⅱ 데이터베이스·리눅스 명령어 최종 점검","c":[{"t":"1. 데이터베이스 핵심 요약","c":[{"t":"(1) 키(Key)와 스키마 핵심 요약","c":[{"t":"① 키 종류 핵심 요약","n":[["시험 포인트","슈퍼키(유일성O, 최소성X) → 후보키(유일성O, 최소성O) → 기본키(후보키 중 선택, NULL 불가) → 대체키(후보키 중 기본키가 아닌 것) → 외래키(다른 테이블 참조)의 관계를 하나의 계층 구조로 정리하여 암기하면 좋다."],["설명","키의 종류 핵심 요약"]]},{"t":"② 계층형→망형→관계형","n":[["실제 사례","관계형(스키마 필요, 가장 광범위), 문서 저장(스키마 불필요, MongoDB), 그래프(노드·에지 특화, Neo4j), Key-Value(가장 단순, Redis)로 요약된다. 데이터 구조가 단순할수록, 스키마 제약이 적을수록 처리 속도가 빨라지는 경향이 있다는 특성도 함께 기억해 두면 실무형 문제에 대응하기 좋다."],["설명","구조별 DBMS 요약 계층형(트리 구조, 접근 빠름·유연성 낮음), 망형(그래프 구조, 계층형보다 유연·설계 복잡), 관계형(테이블 구조, 가장 보편적이고 유연성 우수)으로 발전해 왔다는 흐름을 이해하면 각 구조의 장단점을 자연스럽게 연결지어 기억할 수 있다."]]}]},{"t":"(2) 파일·디렉터리 명령어 최종 점검","c":[{"t":"① 기본 명령어 7종 점검","n":[["시험 포인트","dir↔ls, copy↔cp, del↔rm, attrib↔chmod, type↔cat, tracert↔traceroute의 여섯 가지 대응 관계를 빠짐없이 암기하고 있는지 스스로 점검한다. 시험장에서 리눅스 명령어가 갑자기 기억나지 않을 때, 평소 익숙한 윈도우 명령어와의 대응 관계를 떠올리면 빠르게 복기할 수 있다."],["설명","기본 파일 조작 명령어 점검 cd(경로 변경), ls(목록 출력), cp(파일 복사), mkdir(디렉터리 생성), rm(삭제), chmod(권한 설정), cat(파일 내용 출력) 일곱 가지 명령어의 정확한 철자와 기능을 스스로 확인해 본다. 이 중 하나라도 막힌다면 해당 명령어의 실습을 다시 반복해야 한다."]]},{"t":"② 네트워크·사용자 명령어","n":[["시험 포인트","ping(네트워크 상태 점검), traceroute(경로 추적), who(접속 사용자 확인) 세 가지 명령어의 용도를 정확히 구분할 수 있는지 점검한다. 실기 시험에서는 이 명령어들이 각각 \"무엇을 확인하기 위한\" 명령 어인지를 상황과 함께 제시하고 올바른 명령어를 선택하도록 요구하는 문제가 출제될 수 있다."],["시험 포인트","ps(프로세스 목록 확인), kill(프로세스 종료), pwd(현재 경로 확인) 세 가지 명령어의 기능을 명확히 구분하고, 특히 kill 명령어 사용 시 대상 PID를 정확히 확인해야 한다는 점을 마지막으로 되새기며 실기 시험에 임하는 것이 중요하다. 이 모든 최종 점검 항목에 자신 있게 답할 수 있다면, 응용SW 기초 기술 활용 영역의 실기 시험에 충분히 대비된 상태라고 볼 수 있다."],["설명","네트워크·사용자 확인 명령어 점검"]]}]}]}]}]},{"t":"제15절 시스템·네트워크 보안 기초","c":[{"t":"Ⅰ 접근 통제와 인증 기초","c":[{"t":"1. 파일 권한과 접근 통제","c":[{"t":"(1) 리눅스 파일 권한 체계","c":[{"t":"① 소유자·그룹·기타 rwx","n":[["설명","권한의 세 가지 주체와 세 가지 유형 리눅스의 파일 권한은 소유자(User), 그룹(Group), 기타 사용자(Other) 세 주체에 대해 각각 읽기(Read), 쓰기(Write), 실행(Execute) 세 가지 권한을 부여하는 구조이다. ls -l 명령으로 확인되는 -rwxr-xr--와 같은 문자열은 앞의 rwx(소유자), r-x(그룹), r--(기타)로 해석된다. 파일에 대한 실행(x) 권한은 그 파일을 프로그램으로 실행할 수 있는지를 결정하며, 디렉터리에 대한 실행(x) 권한은 그 디렉터리 내부로 접근(cd)할 수 있는지를 결정한다는 점에서 파일과 디렉터리의 실행 권한 의미가 다르다는 것을 유의해야 한다."]]},{"t":"② DAC 임의 접근 통제","n":[["설명","임의 접근 통제(DAC) 임의 접근 통제(DAC, Discretionary Access Control)는 시스템 객체에 대한 접근을 사용자 개인 또는 그룹의 식별자를 기반으로 제한하는 방법이다. 어떤 접근 권한을 가진 사용자가 자신의 판단으로 다른 사용자에게 권한을 부여할 수 있다는 것이 \"임의적\"이라는 말의 의미이며, 통제 권한이 주체(사용자)에게 있다는 특징이 있다. 대부분의 운영체제와 DBMS가 이 방식을 채택한다. 강제 접근 통제(MAC, Mandatory Access Control)는 주체와 객체 양쪽의 보안 레이블(Security Label)에 기초하여, 높은 보안 수준의 정보가 낮은 보안 수준의 주체에게 노출되지 않도록 접근을 제한하는 방법이다. DAC와 달리 통제 권한이 제3자(보안 관리자)에게 있으며, 군사·정부 시스템처럼 매우 높은 보안이 요구되는 환경에서 주로 사용된다."]]}]},{"t":"(2) 방화벽과 암호화","c":[{"t":"① 방화벽 트래픽 차단·암호화","n":[["설명","방화벽(Firewall)의 개념 방화벽은 내부 네트워크와 외부 네트워크(인터넷) 사이에 위치하여, 미리 정의된 보안 규칙에 따라 들어오고 나가는 트래픽을 허용하거나 차단하는 시스템이다. 특정 포트(예: Telnet의 23번)를 차단하여 취약한 프로토콜의 사용을 원천적으로 막는 등의 방식으로 활용된다. 암호화는 데이터를 제3자가 알아볼 수 없는 형태로 변환하여 전송하고, 수신자만 이를 원래 형태로 복호화할수 있게 하는 기술이다. 앞서 다룬 SSH가 Telnet과 달리 데이터를 암호화하여 전송함으로써 통신 내용이 가로채이더라도 내용을 알아볼 수 없게 하는 것이 암호화 적용의 대표적인 사례이다."]]},{"t":"② 바이러스·웜·트로이 목마","n":[["설명","대표적인 악성코드 유형 바이러스(Virus)는 다른 프로그램에 기생하여 실행 시 함께 동작하며 자신을 복제하는 악성코드이고, 웜 (Worm)은 독립적으로 실행되며 네트워크를 통해 스스로 전파되는 악성코드이다. 트로이 목마(Trojan Horse)는 정상 프로그램으로 위장하여 사용자를 속인 뒤 악성 행위를 수행하는 악성코드로, 스스로 복제·전 파되지 않는다는 점에서 바이러스·웜과 구분된다. DoS(Denial of Service, 서비스 거부) 공격은 시스템에 과도한 요청을 보내 정상적인 서비스를 제공하지 못하게 만드는 공격이다. DDoS(Distributed DoS, 분산 서비스 거부) 공격은 여러 대의 컴퓨터(좀비 PC)를 동원하여 동시에 DoS 공격을 수행하는 방식으로, 단일 IP 차단만으로는 방어하기 어렵다는 특징이 있다."]]}]}]}]},{"t":"Ⅱ 백업과 시스템 관리 기초","c":[{"t":"1. 백업과 복구 전략","c":[{"t":"(1) 백업의 유형","c":[{"t":"① 전체·증분·차등 백업","n":[["설명","전체 백업과 증분 백업 전체 백업(Full Backup)은 시스템의 모든 데이터를 매번 백업하는 방식으로, 복구가 간단하지만 백업 시간과 저장 공간이 많이 필요하다. 증분 백업(Incremental Backup)은 마지막 백업 이후 변경된 데이터만 백업하는 방식으로, 백업 시간은 짧지만 복구 시에는 전체 백업본과 그 이후의 모든 증분 백업본을 순서대로 적용해야 한다. 차등 백업(Differential Backup)은 마지막 전체 백업 이후 변경된 모든 데이터를 매번 백업하는 방식으로, 증분 백업보다 백업 용량은 크지만 복구 시에는 전체 백업본과 가장 최근의 차등 백업본만 있으면 되어 복구 과정이 증분 백업보다 간단하다는 특징이 있다."]]},{"t":"② 전체→증분→로그 복구 순서","n":[["실제 사례","시스템 로그는 언제 어떤 작업이 수행되었는지에 대한 기록으로, 장애 원인 분석과 복구 시점 결정에 핵심적인 역할을 한다. 리눅스에서는 /var/log 디렉터리에 시스템 동작 중 변화하는 다양한 로그 파일이 저장되며, 실무에서는 이 로그를 주기적으로 점검하여 이상 징후를 조기에 발견하는 것이 중요하다."],["설명","장애 발생 시 복구 절차 시스템 장애가 발생하면 먼저 가장 최근의 전체 백업본을 복원한 뒤, 그 이후의 증분(또는 차등) 백업을 순서대로 적용하고, 마지막으로 트랜잭션 로그를 재적용하여 장애 직전 시점까지의 데이터를 최대한 복구하는 절차를 따른다."]]}]},{"t":"(2) 성능 모니터링","c":[{"t":"① top·ps CPU·메모리 점검","n":[["설명","CPU·메모리 사용률 모니터링 윈도우에서는 작업 관리자(성능 탭)를 통해, 리눅스에서는 top이나 ps 명령어를 통해 현재 CPU와 메모리 사용률을 확인할 수 있다. 특정 프로세스가 비정상적으로 높은 CPU나 메모리를 점유하고 있다면, 해당 프로세스의 정상 동작 여부를 우선적으로 점검해야 한다. 대용량 디스크에 접근이 집중될 경우 병목 현상으로 시스템 전체 성능이 저하될 수 있다. 이런 경우 자주 사용되는 데이터에 인덱스를 적용하거나, 디스크 입출력을 분산시키는 방식으로 병목을 완화할 수 있다."]]},{"t":"② 정기 점검의 중요성","n":[["실제 사례","시스템 관리자는 정기적으로 디스크 용량, 로그 파일 크기, 백업 성공 여부 등을 점검해야 한다. 디스크 용량이 가득 차면 시스템이 정상적으로 데이터를 기록하지 못해 서비스 장애로 이어질 수 있으므로, 사전 모니터링과 알림 설정이 실무에서 매우 중요하다."],["설명","정기 점검의 중요성"]]}]}]}]}]},{"t":"제16절 실기 시험 실습 환경 적응 전략","c":[{"t":"Ⅰ 컴퓨터 실습형 시험 대비 전략","c":[{"t":"1. 실습 환경에서의 명령어 입력 유의사항","c":[{"t":"(1) 터미널 환경 적응","c":[{"t":"① 실습·개인 환경 차이","n":[["쉬운 예","실기 시험 고사장의 리눅스 환경은 개인 PC에서 사용하던 배포판(Ubuntu, CentOS 등)과 명령어 세부 동작이 미세하게 다를 수 있다. 예를 들어 일부 배포판은 기본 쉘이 bash가 아닌 다른 쉘일 수 있으므로, 시험 시작 전 안내되는 환경 설명을 주의 깊게 확인하고 필요하다면 간단한 명령어(pwd, ls 등)로 환경을 먼저 점검하는 것이 안전하다."],["시험 포인트","실습형 시험에서는 명령어의 정확한 철자가 채점에 직결된다. 특히 rm과 rn, 1(숫자 일)과 l(소문자 엘)처럼 시각적으로 혼동되기 쉬운 문자를 입력할 때는 한 글자씩 확인하며 타이핑하는 습관을 들여야 한다."],["설명","실습 환경과 개인 환경의 차이"]]},{"t":"② 실행 후 ls 결과 확인","n":[["실제 사례","chmod를 사용해 권한을 변경한 뒤에는 ls -l로 실제 권한 문자열(rwxr-xr-x 등)이 의도한 대로 바뀌었는지 반드시 재확인해야 한다. 권한 설정 실수는 이후 실행이나 접근 시도에서 \"Permission denied\"와 같은 오류로 이어져 뒤늦게 발견되면 시간을 낭비하게 된다."],["설명","명령어 실행 후 즉시 결과 확인 mkdir이나 cp와 같이 화면에 별다른 출력이 없는 명령어를 실행한 뒤에는, 반드시 ls 명령으로 의도한 대로 파일·디렉터리가 생성·복사되었는지 확인하는 습관을 들여야 한다. 명령어가 오류 없이 실행되었다고 해서 항상 의도한 결과가 나온 것은 아니기 때문이다."]]}]},{"t":"(2) 네트워크 명령어 실습 대비","c":[{"t":"① ping·traceroute 결과 해석","n":[["시험 포인트","ping이나 traceroute 명령을 실행했을 때 나타나는 응답 시간, 손실률(packet loss), 홉(hop) 수 등의 출력 결과를 해석하는 연습을 미리 해 두어야 한다. 실기 시험에서는 단순히 명령어를 입력하는 것을 넘어, 출력 결과가 의미하는 바를 설명하는 문제가 함께 출제될 수 있다."],["설명","ping·traceroute 결과 해석 연습"]]},{"t":"② SQL 클라이언트 도구 숙지","n":[["시험 포인트","실기 시험장에서 사용하는 SQL 클라이언트 도구(예: MySQL Workbench, DBeaver, 또는 CLI 기반 mysql 클라이언트)의 기본 사용법을 미리 숙지해 두어야 한다. 쿼리 실행 단축키, 결과 확인 방법, 오류 메시지 확인 위치 등을 알고 있으면 실습 시간을 절약할 수 있다."],["실제 사례","ERD를 손으로 그리거나 도구로 작성한 뒤, 이를 실제 CREATE TABLE 문으로 변환하는 연습을 반복해 두어야 한다. 논리적 설계(ERD)에서 물리적 설계(SQL 문)로 이어지는 전체 흐름을 막힘없이 수행할 수있어야 응용SW 기초 기술 활용 영역의 통합적인 문제에 대응할 수 있다."],["설명","SQL 클라이언트 도구 사용법 숙지"]]}]}]}]},{"t":"Ⅱ 과목 통합 마무리 점검","c":[{"t":"1. 응용SW 기초 기술 자가 점검표","c":[{"t":"(1) 운영체제·네트워크 자가 점검","c":[{"t":"① OS 자가점검·명령어 13종","n":[["설명","운영체제 관련 자가 점검 항목 운영체제의 4대 성능 평가 항목을 설명할 수 있는가? 프로세스의 5대 상태와 전이 용어(디스패치, 보류, 깨움, 시간 제한)를 구분할 수 있는가? 선점형과 비선점형 스케줄링 기법을 각각 두 가지 이상 나열할 수 있는가? 리눅스 기본 명령어 13종(cd, ls, cp, mkdir, rm, chmod, cat, traceroute, kill, ps, pwd, ping, who)의 기능과 윈도우 대응 명령어를 모두 설명할 수 있는가? 이 항목들을 스스로 점검해 본다. OSI 7계층의 이름과 대표 장비를 순서대로 나열할 수 있는가? TCP와 UDP의 차이와 각각의 대표 서비스를 설명할 수 있는가? IP 주소 클래스(A~E)의 첫 옥텟 범위와 사용 목적을 설명할 수 있는가? 라우팅 프로토콜 (RIP, OSPF, BGP)의 차이를 설명할 수 있는가? 이 항목들에 자신 있게 답할 수 있어야 한다."]]},{"t":"② 스키마 3단계·키 자가점검","n":[["시험 포인트","업무 시나리오에서 개체·속성·관계를 정확히 추출할 수 있는가? 1:1, 1:N, M:N 관계를 구분하고 M:N 관계를 관계형 테이블로 어떻게 변환하는지 설명할 수 있는가? 논리 스키마를 물리 스키마(CREATE TABLE 문)로 정확히 변환할 수 있는가? 이 모든 자가 점검 항목에 자신 있게 답할 수 있다면, 응용SW 기초 기술 활용 영역의 실기 시험에 충분히 대비된 상태라고 볼 수 있다."],["설명","데이터베이스 개념 자가 점검 항목 스키마의 3단계(내부·개념·외부)를 설명할 수 있는가? 키의 종류(슈퍼키, 후보키, 기본키, 대체키, 외래키)를 구분하고 각각의 조건을 설명할 수 있는가? DBMS의 장단점을 각각 세 가지 이상 나열할 수 있는가? 관계형· 문서저장형·그래프형·Key-Value형 DBMS의 차이와 대표 제품을 설명할 수 있는가?"]]}]},{"t":"(2) Part01~04 연계 복습 전략","c":[{"t":"① 프로그래밍 언어 연계 복습","n":[["쉬운 예","Part01(프로그래밍 언어 활용)에서 다룬 C/Java/Python의 파일 입출력, 예외 처리 개념은 본 Part03에서 다룬 운영체제의 프로세스·파일 시스템 개념과 밀접하게 연결된다. 예를 들어 프로그램이 파일을 여는 과정은 운영체제의 파일 디스크립터 관리와 직결되므로, 두 Part를 함께 복습하면 개념 간의 연결고리를더 깊이 이해할 수 있다."],["실제 사례","Part04(SQL 활용)에서 다룬 CREATE TABLE, 인덱스, 뷰의 실전 문법은 본 Part03에서 다룬 ERD 설계, 키(Key) 개념, DBMS 종류에 대한 이해가 뒷받침되어야 온전히 체화된다. ERD로 설계한 논리적 구조를 SQL 문법으로 실제 구현하는 전체 흐름을 하나로 연결하여 복습하는 것이 실기 시험 대비에 가장 효과적이다."],["설명","프로그래밍 언어와 응용SW 기술의 연계"]]},{"t":"② 과목 통합적 사고","n":[["시험 포인트","실기 시험은 각 Part를 독립적으로 암기하는 것을 넘어, 프로그래밍·SQL·운영체제·네트워크 지식을 종합적으로 활용해야 하는 실무형 문제로 구성될 가능성이 높다. 평소 학습할 때도 각 주제를 개별적으로 암기하기보다, 실제 개발 업무의 흐름(요구사항 분석 → 설계 → 구현 → 디버깅) 속에서 각 지식이 어떻게 연결 되는지를 의식하며 학습하는 것이 중요하다."],["실제 사례","이 정리서에 수록된 모든 예제와 모의 문제는 단순히 읽고 넘어가는 것이 아니라, 실제 컴퓨터 환경에서 직접 타이핑하고 실행하며 결과를 확인하는 과정을 반복할 때 비로소 실기 시험에서 요구하는 실전 역량으로 이어진다. 마지막까지 손으로 직접 연습하는 태도를 유지하는 것이 합격의 핵심이다."],["설명","통합적 사고의 중요성"]]}]}]}]}]}],"k":"실기 Part03"},{"n":8,"t":"SQL 활용","c":[{"t":"제1절 DDL과 데이터 정의 실무","c":[{"t":"Ⅰ DDL(데이터 정의어)의 개념과 대상","c":[{"t":"1. DDL의 정의와 오브젝트","c":[{"t":"(1) DDL이란","c":[{"t":"① DDL 정의·오브젝트 대상","n":[["실제 사례","DDL(Data Definition Language)은 데이터를 정의하는 언어이며, 더 정확히 표현하면 데이터를 담는 그릇 자체를 정의하는 언어이다. 이 그릇을 DBMS에서는 오브젝트(Object)라고 부르며, 실기 시험에서는 이 오브젝트의 종류와 각 DDL 명령어의 정확한 문법을 실제로 작성할 수 있는지를 확인한다."],["설명","DDL의 정의"]]},{"t":"② CREATE·ALTER·DROP· TRUNCATE","n":[["설명","생성과 변경(CREATE, ALTER) DDL 명령어는 구분에 따라 생성(CREATE : 데이터베이스 오브젝트 생성), 변경(ALTER : 데이터베이스 오브젝트 변경)으로 나뉜다. CREATE는 새로운 오브젝트를 만들 때, ALTER는 이미 존재하는 오브젝트의 구조를 수정할 때 사용한다. 삭제에 해당하는 명령어에는 DROP(데이터베이스 오브젝트 삭제)과 TRUNCATE(데이터베이스 오브젝트 내용 삭제, 테이블 구조는 유지)가 있다. DROP은 테이블 자체를 완전히 없애지만, TRUNCATE는 테이블의 데이터만 모두 삭제하고 테이블의 구조(컬럼 정의 등)는 그대로 남긴다는 차이를 명확히 구분해야 한다."]]}]},{"t":"(2) 데이터 사전의 개념","c":[{"t":"① 데이터 사전=메타데이터 시스템 테이블","n":[["설명","데이터 사전이란 데이터 사전은 데이터베이스에 저장된 데이터에 대한 정보, 즉 메타데이터(Metadata)를 저장하고 있는 시스템 테이블이다. 사용자가 DDL 명령어로 테이블, 뷰, 인덱스 등을 생성하거나 변경하면 그 정의 정보가 자동으로 데이터 사전에 기록되고 관리된다. 사용자에게 데이터 사전은 단순한 조회의 대상이지만, 데이터베이스 엔진을 이루는 컴파일러나 옵티마이저와 같은 구성요소에게 데이터 사전은 작업을 수행하는 데 필요한 참조 정보일 뿐만 아니라 작업의 대상이기도 하다. 즉 DBMS 내부적으로도 끊임없이 참조되고 갱신되는 핵심 시스템 자원이다."]]},{"t":"② 오브젝트·컬럼·제약·권한 정보 자동 갱신","n":[["시험 포인트","실기 시험이나 실무에서 특정 테이블의 구조를 확인하고 싶을 때는 DESC 테이블이름과 같은 명령이나 데이터 사전을 조회하는 SELECT 문을 통해, 직접 문서를 찾아보지 않고도 컬럼명과 자료형, 제약조건을 즉시 확인할 수 있다."],["설명","데이터 사전에 저장되는 정보 데이터 사전에는 데이터베이스 오브젝트 정보(테이블, 뷰, 인덱스 등), 각 오브젝트를 구성하는 컬럼의 이름과 데이터 타입, 제약조건 정보, 사용자 권한 정보 등이 저장된다. 이러한 정보는 사용자가 직접 수정하는 것이 아니라 DDL 명령어의 실행 결과로 자동 갱신된다."]]}]}]}]},{"t":"Ⅱ 테이블 생성과 변경","c":[{"t":"1. 테이블 생성(CREATE TABLE)","c":[{"t":"(1) 신규 테이블 생성 문법","c":[{"t":"① CREATE TABLE 기본 문법","n":[["설명","CREATE TABLE의 기본 문법\nCREATE TABLE 테이블이름 (\n     열이름 데이터타입 [DEFAULT 값] [NOT NULL]\n     [PRIMARY KEY (열 리스트)]\n     {[FOREIGN KEY (열 리스트) REFERENCES 테이블이름 [(열이름)]\n        [ON DELETE 옵션]\n        [ON UPDATE 옵션]]}\n     [CHECK (조건식) | UNIQUE(열이름)]\n);\n CREATE TABLE 문에서 각 열은 열이름과 데이터타입을 필수로 지정하고, 필요에 따라 DEFAULT(기본값)\n, NOT NULL(널 값 허용 안 함)과 같은 제약조건을 추가로 지정할 수 있다. PRIMARY KEY와 FOREIGN KEY는 각각 기본 키와 외래 키 제약조건을 지정하는 절이다.\nCREATE TABLE 테이블이름 AS SELECT 문;\nAS SELECT 구문을 사용하면 기존 테이블에서 조회한 결과를 바탕으로 새로운 테이블을 생성할 수 있다. 이방식으로 생성된 테이블은 SELECT 문의 결과에 포함된 컬럼과 데이터를 그대로 가지지만, 원본 테이블의 제약조건(기본 키, 외래 키 등)은 함께 복사되지 않는다는 점에 유의해야 한다."]]},{"t":"② ALTER TABLE ADD·MODIFY","n":[["시험 포인트","ADD는 테이블에 새로운 열을 추가하는 명령이고, MODIFY는 이미 존재하는 열의 데이터 타입이나 기본값을 변경하는 명령이다. 실기 시험에서 ADD와 MODIFY를 혼동하여 사용하는 경우가 많으므로, \" 새로 추가\"인지 \"기존 것을 변경\"인지 문제의 요구사항을 정확히 구분해야 한다.\nALTER TABLE 테이블이름 DROP 열이름;\nALTER TABLE 테이블이름 ADD CONSTRAINT 제약조건이름 CHECK (조건식);"],["설명","열 추가와 데이터 타입 변경\nALTER TABLE 테이블이름 ADD 열이름 데이터타입 [DEFAULT 값];\nALTER TABLE 테이블이름 MODIFY 열이름 데이터타입 [DEFAULT 값];"]]}]},{"t":"(2) 이름 변경 명령어","c":[{"t":"① RENAME TO 테이블·컬럼 이름 변경","n":[["설명","테이블 이름 변경(RENAME)\nALTER TABLE 기존테이블이름 RENAME TO 새테이블이름;\nRENAME은 테이블 자체의 이름을 변경하는 명령어로, 제품에 따라 ALTER TABLE ... RENAME TO 형태 또는 별도의 RENAME 문으로 제공되기도 한다. 이름만 바뀔 뿐 테이블 안의 데이터와 구조는 그대로 유지된다.\nALTER TABLE 테이블이름 RENAME COLUMN 기존열이름 TO 새열이름;\n컬럼의 이름만 변경하고 싶을 때는 RENAME COLUMN 절을 사용한다. 자료형까지 함께 변경해야 한다면 앞서 다룬 MODIFY 명령을 별도로 사용해야 하며, 이름 변경과 자료형 변경은 서로 다른 명령이라는 점을 구분해야 한다."]]},{"t":"② NOT NULL 열 추가 시 DEFAULT 필수","n":[["실제 사례","실무에서 이미 서비스 중인 테이블의 구조를 변경할 때는 해당 테이블을 사용하는 다른 프로그램이나 뷰에 영향을 주지 않는지 사전에 검토해야 한다. 실기 시험에서는 이러한 실무적 맥락보다 문법 자체의 정확 성에 집중하되, 왜 이러한 절차가 필요한지 개념적으로 이해해 두면 응용문제에도 대응할 수 있다."],["설명","기존 데이터와의 호환성 확인 이미 데이터가 저장된 테이블에 NOT NULL 제약조건이 있는 열을 추가하려면, 기존 행에 대해 어떤 기본값을 채울지 DEFAULT 옵션과 함께 지정해야 오류 없이 반영된다. 열의 자료형을 변경할 때도 기존에 저장된 데이터가 새로운 자료형과 호환되는지 미리 확인해야 한다."]]}]}]}]},{"t":"Ⅲ 제약조건(Constraint)의 종류와 적용","c":[{"t":"1. 제약조건의 유형","c":[{"t":"(1) 개체 무결성 관련 제약조건","c":[{"t":"① PK 중복·NULL 불가, UNIQUE NULL 허용","n":[["설명","PRIMARY KEY(기본 키) 기본 키는 테이블에서 각 행을 유일하게 식별할 수 있는 열(또는 열의 조합)에 지정하는 제약조건으로, 중복된 값과 NULL 값을 모두 허용하지 않는다. 하나의 테이블에는 오직 하나의 기본 키만 지정할 수 있다. UNIQUE 제약조건은 지정한 열에 중복된 값이 저장되는 것을 허용하지 않지만, 기본 키와 달리 NULL 값은 허용한다는 차이가 있다. 하나의 테이블에 여러 개의 UNIQUE 제약조건을 지정할 수 있다."]]},{"t":"② FK 참조·ON DELETE/UPDATE 옵션","n":[["쉬운 예","NOT NULL은 해당 열에 반드시 값이 입력되어야 함을 의미하는 제약조건이며, CHECK는 열에 저장될 수 있는 값의 범위나 조건을 지정하는 제약조건이다. 예를 들어 CHECK (score >= 0 AND score <= 100)은 점수 열에 0에서 100 사이의 값만 저장되도록 제한한다."],["설명","FOREIGN KEY(외래 키) 외래 키는 다른 테이블의 기본 키를 참조하는 열에 지정하는 제약조건으로, 참조하는 테이블에 존재하지 않는 값을 입력하려고 하면 오류가 발생한다. ON DELETE, ON UPDATE 옵션을 통해 참조하는 데이터가 삭제되거나 변경될 때 함께 어떻게 처리할지(CASCADE, SET NULL 등)를 지정할 수 있다."]]}]},{"t":"(2) 제약조건 명명(Naming)과 관리","c":[{"t":"① CONSTRAINT 키워드로 제약 이름 지정","n":[["설명","제약조건에 이름 지정하기\nCREATE TABLE student (\n      student_id INT,\n      score INT,\n      CONSTRAINT pk_student PRIMARY KEY (student_id),\n      CONSTRAINT chk_score CHECK (score BETWEEN 0 AND 100)\n);\nCONSTRAINT 키워드로 제약조건에 이름을 직접 지정하면, 이후 해당 제약조건을 삭제하거나 변경할 때 이름으로 명확하게 식별할 수 있다. 이름을 지정하지 않으면 DBMS가 자동으로 임의의 이름을 부여하므로 관리가 어려워질 수 있다.\nINSERT나 UPDATE 실행 시 제약조건 위반 오류가 발생하면, 오류 메시지에 표시된 제약조건 이름을 확인\n하여 어떤 제약조건을 위반했는지 파악한 뒤, 입력하려는 데이터가 해당 제약조건을 만족하는지 재검토해야한다."]]},{"t":"② DROP 구조+데이터 vs TRUNCATE 데이터만","n":[["시험 포인트","다른 테이블에서 외래 키로 참조하고 있는 테이블은 참조하는 테이블을 먼저 삭제하거나 외래 키제약을 해제하지 않는 한 DROP이 거부될 수 있다. 실기 시험에서 테이블 삭제 문제가 출제되면, 삭제 순서(자식 테이블 먼저, 부모 테이블 나중)를 고려해야 한다."],["설명","DROP TABLE과 TRUNCATE TABLE\nDROP TABLE student;       -- 테이블 구조와 데이터 모두 삭제\nTRUNCATE TABLE student;   -- 데이터만 삭제, 구조는 유지\nDROP TABLE은 테이블 자체를 데이터베이스에서 완전히 제거하므로 이후 해당 테이블명으로는 어떤 작업\n도 할 수 없다. TRUNCATE TABLE은 테이블 안의 모든 데이터를 삭제하지만 테이블의 구조(열 정의, 제약조건)는 그대로 남아있어, 이후 다시 데이터를 입력할 수 있다는 차이가 있다."]]}]}]}]},{"t":"Ⅳ 데이터 타입과 제약조건 관리 실무","c":[{"t":"1. 주요 데이터 타입","c":[{"t":"(1) 문자형과 숫자형 데이터 타입","c":[{"t":"① CHAR 고정길이·VARCHAR 가변길이","n":[["실제 사례","CHAR는 고정 길이 문자열 데이터 타입으로, 지정한 길이보다 짧은 문자열을 저장하면 나머지 공간을 공백으로 채운다. VARCHAR는 가변 길이 문자열 데이터 타입으로, 실제 입력된 문자열의 길이만큼만 저장 공간을 사용한다. 길이가 일정한 데이터(예: 학번, 코드값)에는 CHAR를, 길이가 들쭉날쭉한 데이터(예: 이름, 주소)에는 VARCHAR를 사용하는 것이 일반적이다."],["설명","문자형 데이터 타입(CHAR, VARCHAR)"]]},{"t":"② DATE 타입 테이블 생성 예시","n":[["시험 포인트","DATE는 날짜에 사용되는 데이터 타입으로, 생년월일이나 등록일과 같은 날짜 정보를 저장할 때사용한다. 실기 시험의 CREATE TABLE 문제에서는 각 열의 성격(문자/숫자/날짜)에 맞는 데이터 타입을 정확히 선택하여 작성할 수 있는지가 중요한 평가 요소가 된다."],["쉬운 예","열에 저장될 데이터의 성격을 먼저 파악한 뒤, 산술 연산이 필요하면 숫자형, 문자 그대로 취급해야 하면(전화번호, 우편번호 등) 문자형을 선택하는 것이 원칙이다. 예를 들어 전화번호는 숫자로만 구성되어 있어도 앞자리의 0이 보존되어야 하고 산술 연산 대상이 아니므로 VARCHAR로 정의하는 것이 일반적이다."],["설명","날짜형 데이터 타입(DATE)\nCREATE TABLE student (\n     student_id INT,\n     name VARCHAR(20),\n     birth_date DATE,\n     score FLOAT\n);"]]}]},{"t":"(2) 제약조건의 관리(추가·삭제·활 성화)","c":[{"t":"① ALTER TABLE ADD/DROP 제약조건","n":[["실제 사례","대량의 데이터를 일괄로 적재(bulk insert)해야 할 때, 매 행마다 제약조건을 검사하면 처리 속도가 크게 저하될 수 있다. 이런 경우 일시적으로 DISABLE CONSTRAINT로 제약조건 검사를 비활성화한 뒤 데이터를 적재하고, 적재가 끝나면 ENABLE CONSTRAINT로 다시 활성화하여 데이터 무결성을 확인하는 실무 기법이 활용된다."],["설명","제약조건 추가와 삭제 -- 제약조건 추가\nALTER TABLE 테이블이름 ADD [CONSTRAINT 제약조건이름] 제약조건 (열이름);\n-- 제약조건 삭제\nALTER TABLE 테이블이름 DROP FOREIGN KEY [제약조건이름];\n테이블 생성 이후에도 ALTER TABLE 문에 ADD 절을 사용하여 제약조건을 추가할 수 있으며, 이때 CONSTRAINT 키워드로 이름을 지정하면 이후 관리가 쉬워진다. 제약조건을 삭제할 때는 DROP 절 뒤에 제약조건의 종류와 이름을 지정한다. -- 제약조건 활성화\nALTER TABLE 테이블이름 ENABLE CONSTRAINT 제약조건이름;\n-- 제약조건 비활성화\nALTER TABLE 테이블이름 DISABLE CONSTRAINT 제약조건이름;"]]},{"t":"② NO ACTION·SET NULL 등 FK 옵션","n":[["설명","FOREIGN KEY의 참조 무결성 옵션 FOREIGN KEY 제약조건은 참조 대상을 테이블 이름(열 이름)으로 명시해야 하며, 참조 무결성이 위배되는 상황(참조되는 부모 행이 삭제되거나 변경되는 경우)이 발생했을 때의 처리 방법을 옵션으로 지정할 수 있다. 대표적인 옵션에는 NO ACTION(아무 조치 없이 오류 발생), SET DEFAULT(기본값으로 설정), SET NULL(NULL로 설정), CASCADE(연쇄적으로 함께 삭제·변경), RESTRICT(참조하는 데이터가 있으면 삭제·변경을 제한)가 있다.\nCREATE TABLE enrollment (\n     student_id INT,\n     course_id INT,\n     FOREIGN KEY (student_id) REFERENCES student(student_id) ON DELETE CASCADE\n);\n위 예시는 student 테이블에서 특정 학생이 삭제될 때, 그 학생을 참조하는 enrollment 테이블의 관련 행도 함께(CASCADE) 삭제되도록 지정한 것이다. 만약 ON DELETE RESTRICT였다면, enrollment에 해당 학생의 수강 기록이 남아있는 한 student 테이블에서 그 학생을 삭제하는 것 자체가 거부된다."]]}]}]}]}]},{"t":"제2절 DCL과 TCL 실무","c":[{"t":"Ⅰ DCL(데이터 제어어)의 개념과 활용","c":[{"t":"1. DCL의 개념과 대상","c":[{"t":"(1) DCL이란","c":[{"t":"① DCL 대상=사용자 권한·트랜잭션","n":[["시험 포인트","넓은 의미에서 DCL은 사용자 권한을 다루는 GRANT/REVOKE와, 트랜잭션을 다루는 COMMIT/ROLLBACK/CHECKPOINT(TCL)를 모두 포함하는 개념으로 다루어지기도 한다. 실기 시험에서는 이 둘을 별도로 구분하여 각각의 명령어 문법을 정확히 작성할 수 있는지를 확인한다."],["설명","DCL(Data Control Language)의 정의 DCL은 데이터베이스에서 데이터 이외의 오브젝트에 대해 조작할 필요가 있을 때 사용하는 SQL 명령어이다. DCL의 조작 대상은 사용자 권한(접근 통제를 위해 사용자를 등록하고 특정 데이터베이스를 사용할 수 있는 권리를 부여하는 작업)과 트랜잭션(동시에 다수의 작업을 독립적으로 안전하게 처리하기 위한 상호작용 단위)이다."]]},{"t":"② GRANT 권한 ON 객체 TO 사용자","n":[["설명","시스템 권한과 객체 권한 부여 문법 -- 시스템 권한 부여\nGRANT 권한1, 권한2 TO 사용자계정;\n-- 객체 권한 부여\nGRANT 권한1, 권한2 ON 객체명 TO 사용자계정;\n-- 실전 예시\nGRANT CREATE TABLE, CREATE VIEW TO kim;\nGRANT SELECT, INSERT ON student TO lee;\n시스템 권한 부여는 GRANT 뒤에 권한 목록과 TO 사용자계정을 지정하며, 객체 권한 부여는 ON 객체명을 추가로 명시하여 특정 테이블이나 뷰에 대한 권한임을 지정한다는 차이가 있다. 대표적인 시스템 권한에는\nCREATE USER(계정 생성), DROP USER(계정 삭제), DROP ANY TABLE(테이블 삭제), CREATE\nSESSION(데이터베이스 접속), CREATE TABLE(테이블 생성), CREATE VIEW(뷰 생성) 등이 있다. 객체 권한에는 ALTER(테이블 변경 권한), INSERT/DELETE/SELECT/UPDATE(데이터 조작 권한), EXECUTE ON PROCEDURE(실행 권한)가 있다. 시스템 권한이 데이터베이스 전반에 대한 권한이라면, 객체 권한은 특정 테이블이나 뷰, 프로시저 등 개별 객체에 대한 세부적인 권한이라는 점에서 구분된다."]]}]},{"t":"(2) 권한 회수(REVOKE)","c":[{"t":"① REVOKE 권한 ON 객체 FROM 사용자","n":[["시험 포인트","실기 시험에서는 GRANT로 부여한 권한을 REVOKE로 정확히 회수하는 짝을 맞추는 문제가 출제될 수 있으므로, TO와 FROM의 위치를 혼동하지 않는 것이 중요하다. \"권한을 준다(TO)\"와 \"권한을 회수한 다(FROM)\"는 방향성으로 기억하면 헷갈리지 않는다."],["설명","REVOKE의 문법 -- 시스템 권한 회수\nREVOKE 권한1, 권한2 FROM 사용자계정;\n-- 객체 권한 회수\nREVOKE 권한1, 권한2 ON 객체명 FROM 사용자계정;\n-- 실전 예시\nREVOKE INSERT ON student FROM lee;\n REVOKE는 GRANT에 대응하는 권한 회수 명령으로, GRANT의 TO가 REVOKE에서는 FROM으로 바뀐다\n는 점을 정확히 기억해야 한다. 시스템 권한 회수와 객체 권한 회수의 문법 구조는 GRANT와 동일하게 ON 객체명의 유무로 구분된다."]]},{"t":"② DAC 임의 접근 통제·주체 기반","n":[["설명","임의 접근 통제(DAC) 임의 접근 통제(DAC, Discretionary Access Control)는 시스템 객체에 대한 접근을 사용자 개인 또는 그룹의 식별자를 기반으로 제한하는 방법이다. 어떤 종류의 접근 권한을 갖는 사용자는 다른 사용자에게 자신의 판단에 의해서 권한을 줄 수 있다는 것이 임의적이라는 말의 의미이며, 통제 권한이 주체(사용자)에게 있다는 특징이 있다. 데이터베이스 관리 시스템(DBMS)에서 채택한 접근 통제 정책은 일반적으로 이 임의 접근 통제(DAC) 방식이다. 강제 접근 통제(MAC, Mandatory Access Control)는 어떤 주체가 특정 객체에 접근하려 할 때 양쪽의 보안 레이블(Security Label)에 기초하여, 높은 보안 수준을 요구하는 정보(객체)가 낮은 보안 수준의 주체에게 노출되지 않도록 접근을 제한하는 통제 방법이다. DAC와 달리 통제 권한이 제3자에게 있으며, 주체는 접근 통제 권한과 무관하다는 특징이 있다. 데이터베이스 관리, 특히 접근 통제 용도로 SQL에서 사용하는 명령어가 바로 DCL이다."]]}]}]}]},{"t":"Ⅱ TCL(트랜잭션 제어어)의 개념과 활용","c":[{"t":"1. 트랜잭션의 개념","c":[{"t":"(1) 트랜잭션이란","c":[{"t":"① 트랜잭션=분할 불가 논리 연산 단위","n":[["설명","트랜잭션의 다양한 정의 트랜잭션은 일 처리 단위를 의미하며, 다양한 관점에서 다음과 같이 정의된다. 트랜잭션은 논리적 연산 단위이며, 한 개 이상의 데이터베이스 조작(즉, 하나 이상의 SQL 문장)을 포함하며, 트랜잭션은 거래이다. 이때 거래 결과가 모두 반영되거나 또는 모두 취소되어야 한다는 점에서, 데이터베이스에서의 트랜잭션은 특별하고 엄격한 거래를 의미하며, 더 이상 분할할 수 없는 최소 단위이다. 트랜잭션을 제어한다는 것은 흐름의 구조를 바꾼다는 것이 아니라, 트랜잭션의 결과를 수용(COMMIT)하거나 취소(ROLLBACK)하는 것을 의미한다. 이러한 작업을 수행하는 명령어가 바로 TCL(Transaction Control Language)이다."]]},{"t":"② COMMIT 확정·ROLLBACK 취소","n":[["설명","COMMIT과 ROLLBACK COMMIT은 트랜잭션을 확정하는 명령어로, 트랜잭션 내에서 수행한 모든 변경 사항을 데이터베이스에 영구적으로 반영한다. ROLLBACK은 트랜잭션을 취소하는 명령어로, 아직 COMMIT되지 않은 변경 사항을 모두 되돌려 트랜잭션 시작 이전 상태로 복원한다. CHECKPOINT는 저장점을 설정하는 명령어로, ROLLBACK할 위치를 지정하는 역할을 한다. 트랜잭션 전체를 되돌리는 대신 특정 저장점까지만 부분적으로 되돌리고 싶을 때 활용하며, Oracle 등 일부 제품에서는 이와 유사한 기능을 SAVEPOINT라는 명령어로 제공하기도 한다."]]}]},{"t":"(2) COMMIT과 ROLLBACK의 실전 사용","c":[{"t":"① 결과 확인 후 COMMIT/ROL LBACK","n":[["시험 포인트","하나의 트랜잭션 안에서 여러 SQL 문장을 실행한 뒤, 그 결과가 올바른지 확인하고 COMMIT 또는 ROLLBACK을 결정하는 흐름이 일반적이다. 실기 시험에서 UPDATE나 DELETE 실행 후 결과가 잘못되었 다면, COMMIT을 하기 전이라면 ROLLBACK으로 되돌릴 수 있다는 점을 기억해야 한다."],["시험 포인트","일부 DBMS 클라이언트 도구는 기본적으로 자동 커밋(Auto Commit) 모드로 동작하여, 각 SQL 문이 실행될 때마다 자동으로 COMMIT이 수행된다. 이 경우 ROLLBACK으로 되돌릴 수 없으므로, 실기시험 환경에서 사용하는 도구의 커밋 모드 설정을 사전에 확인해 두는 것이 안전하다."],["설명","트랜잭션 처리 예시\nUPDATE student SET score = score + 10 WHERE student_id = 1001;\nDELETE FROM student WHERE score < 0;\n-- 결과를 확인한 후 문제가 없다면\nCOMMIT;\n-- 만약 의도치 않은 결과라면\nROLLBACK;"]]},{"t":"② 권한 부여와 트랜잭션 연계","n":[["실제 사례","실무에서는 특정 사용자에게 데이터 조작 권한(GRANT INSERT, UPDATE 등)을 부여한 뒤, 그 사용자가 수행하는 작업이 하나의 트랜잭션으로 처리되고 COMMIT 또는 ROLLBACK으로 마무리되는 일련의 과정이 반복된다."],["시험 포인트","GRANT는 TO(권한을 준다), REVOKE는 FROM(권한을 회수한다), COMMIT은 확정, ROLLBACK은 취소, CHECKPOINT는 저장점 설정이라는 핵심 키워드를 명확히 구분하여 암기해 두면 DCL/TCL 관련 문제를 빠르고 정확하게 해결할 수 있다."],["설명","권한 부여와 트랜잭션의 연계"]]}]}]}]}]},{"t":"제3절 인덱스와 뷰 활용","c":[{"t":"Ⅰ 인덱스(INDEX)의 개념과 활용","c":[{"t":"1. 인덱스의 개념","c":[{"t":"(1) 인덱스란","c":[{"t":"① 인덱스=검색 속도 향상, PK 자동 생성","n":[["설명","인덱스의 정의 인덱스는 데이터베이스 오브젝트 중 하나로, 테이블에서 데이터의 검색 속도를 향상시키기 위해 만드는 데이터 구조이다. 책의 찾아보기(색인)와 같은 역할을 하며, 인덱스가 없으면 원하는 데이터를 찾기 위해 테이블 전체를 처음부터 끝까지 조회해야 하므로 대용량 테이블일수록 인덱스의 유무가 성능에 큰 영향을 미친다. 테이블에서 기본키(PRIMARY KEY)로 지정할 경우 자동으로 인덱스가 생성된다. 이는 기본키가 각 행을 유일하게 식별해야 하므로, 이 유일성을 빠르게 검사하고 검색하기 위해 DBMS가 자동으로 인덱스 구조를 만들어 관리하기 때문이다."]]},{"t":"② CREATE [UNIQUE] INDEX 문법","n":[["시험 포인트","인덱스 관련 명령어에 대한 SQL 표준이 없기에 제품별로 DROP 명령문의 사용법이 약간씩 다르며, 보통 인덱스를 테이블의 종속 구조로 생각하여 인덱스를 삭제하기 위해 테이블을 기준으로 명령을 작성한다. 즉, ALTER TABLE 명령문에 DROP INDEX 명령이 추가되는 형태로 사용된다는 점이 실기 시험에서 중요하게 다루어진다."],["설명","인덱스 생성과 변경 -- 인덱스 생성\nCREATE [UNIQUE] INDEX <index_name> ON <table_name> (<column(s)>);\n-- 인덱스 변경\nALTER [UNIQUE] INDEX <index_name> ON <table_name> (<column(s)>);\nUNIQUE 옵션은 생략 가능하며, 지정하면 인덱스가 걸린 컬럼에 중복값을 허용하지 않는다. table_name은 인덱스 대상 테이블 이름, column(s)는 인덱스 대상 테이블의 특정 컬럼 이름(들)을 의미한다. 한 번 생성된 인덱스에 대해 변경이 필요한 경우는 드물며, 일부 제품은 인덱스에 대한 변경 SQL문이 없어 기존 인덱스를 삭제하고 신규 인덱스를 생성하는 방식이 권고된다.\nALTER TABLE <table_name> DROP INDEX <index_name>;"]]}]},{"t":"(2) 인덱스 대상 컬럼 선정","c":[{"t":"① WHERE·JOIN·FK 컬럼 인덱스 효과적","n":[["설명","인덱스 생성이 효과적인 경우\nWHERE 절의 검색 조건이나 JOIN 조건으로 자주 사용되는 컬럼, 외래 키로 사용되는 컬럼에 인덱스를 생성\n하면 실질적인 조회 성능 향상 효과를 얻을 수 있다. 값의 종류가 몇 개 되지 않는 컬럼(성별과 같이 두 가지 값만 있는 경우)은 인덱스의 효과가 크지 않다는 점도 함께 기억해야 한다. 인덱스는 조회(SELECT) 성능을 향상시키지만, 데이터가 추가/수정/삭제될 때마다 인덱스 자체도 함께 갱신해야 하므로 오히려 쓰기 작업의 성능은 저하시킬 수 있다. 따라서 자주 조회되지만 변경은 상대적으로 적은 컬럼에 인덱스를 생성하는 것이 일반적인 전략이다."]]},{"t":"② 일반 INDEX vs UNIQUE INDEX 실습","n":[["설명","단일 컬럼과 고유 인덱스 실습\nCREATE INDEX idx_student_name ON student (name);\nCREATE UNIQUE INDEX idx_student_email ON student (email);\n이름(name) 컬럼은 중복이 있을 수 있으므로 일반 인덱스를, 이메일(email)과 같이 반드시 유일해야 하는 컬럼에는 UNIQUE INDEX를 생성하여 검색 속도 향상과 데이터 무결성 보장을 동시에 얻을 수 있다.\nALTER TABLE student DROP INDEX idx_student_name;\n생성된 인덱스가 더 이상 필요하지 않거나, 인덱스 정의를 변경해야 할 때는 위와 같이 ALTER TABLE 문으로 기존 인덱스를 삭제한 뒤 새로운 인덱스를 다시 생성하는 절차를 따른다."]]}]}]}]},{"t":"Ⅱ 뷰(VIEW)의 개념과 활용","c":[{"t":"1. 뷰의 개념과 특징","c":[{"t":"(1) 뷰란","c":[{"t":"① 뷰=논리 테이블, 다수 테이블로 생성","n":[["설명","뷰의 정의 뷰는 논리 테이블로서, 사용자에게는(생성 관점이 아닌 사용 관점에서) 테이블과 동일하게 취급된다. 뷰는 하나의 논리 테이블로부터 생성 가능하며, 다수의 테이블 또는 다른 뷰를 이용하여 생성할 수도 있다. 뷰와 같은 결과를 만들기 위해 조인(JOIN) 기능을 매번 활용할 수도 있으나, 뷰가 만들어져 있다면 훨씬 간단한 질의로 동일한 결과를 얻을 수 있다. 뷰를 사용하는 주된 이유는 단순한 질의어를 사용할 수 있기 때문이다. FROM 절에 있는 하나의 뷰를 통해, 뷰를 구성하는 복수의 테이블을 대체하는 효과를 얻을 수 있어 반복적으로 사용되는 복잡한 조인 쿼리를 간결하게 만들 수 있다."]]},{"t":"② 논리적 독립성·보안, 뷰 인덱스 불가","n":[["설명","논리적 데이터 독립성과 보안 뷰는 논리 테이블이므로 테이블의 구조가 변경되어도 뷰를 사용하는 애플리케이션 코드는 영향을 받지 않을수 있다는 논리적 데이터 독립성을 제공한다. 또한 테이블의 일부 정보만을 보여주는 뷰에는 접근을 허용하는 방식으로 데이터 보안을 용이하게 확보할 수 있다는 장점도 있다. 인덱스는 물리적으로 저장된 데이터를 대상으로 하기 때문에, 논리적 구성인 뷰 자체는 인덱스를 가지지 못한다. 또한 뷰의 정의를 변경하려면 뷰를 삭제하고 재생성해야 하며(뷰 정의 변경 불가), 뷰의 내용에 대한 삽입/ 삭제/변경에는 여러 제약이 존재한다."]]}]},{"t":"(2) 뷰 생성","c":[{"t":"① CREATE VIEW 뷰이름 AS SELECT","n":[["시험 포인트","뷰는 하나의 테이블을 그대로 옮긴 형태(뷰A), 일부 컬럼만 선택한 형태(뷰X), 여러 테이블을 조인한 결과(뷰Y)로 다양하게 생성할 수 있다. 실기 시험에서는 주어진 요구사항에 맞추어 이 세 가지 형태 중 적절한 CREATE VIEW 문을 정확히 작성할 수 있는지를 확인한다."],["설명","뷰 생성 문법\nCREATE VIEW <뷰이름>(컬럼목록) AS <뷰를 통해 보여줄 데이터 조회용 쿼리문>;\n뷰 생성 명령의 일반 형태는 CREATE VIEW 뒤에 뷰 이름과 컬럼 목록을 지정하고, AS 뒤에 뷰가 보여줄 데이터를 조회하는 SELECT 쿼리문을 작성하는 구조이다. -- 테이블A 그대로 뷰A\nCREATE VIEW 뷰A AS SELECT * FROM 테이블A;\n-- 테이블A의 일부 컬럼으로 뷰X\nCREATE VIEW 뷰X AS SELECT 컬럼1, 컬럼2, 컬럼3 FROM 테이블A;\n-- 테이블A와 테이블B의 조인 결과를 뷰Y\nCREATE VIEW 뷰Y AS SELECT * FROM 테이블A, 테이블B\nWHERE 테이블A.컬럼1 = 테이블B.컬럼1;"]]},{"t":"② DROP VIEW, 정의 변경 불가→재생성","n":[["설명","뷰 삭제 문법\nDROP VIEW <View_Name>;\n뷰 정의 자체를 변경하는 것은 불가능하다. 일단 뷰를 정의하면 뷰의 물리적 실체는 뷰의 이름과 데이터를 조회하기 위한 쿼리문뿐이며, 이 쿼리문을 직접 변경하는 수단은 제공되지 않으므로 뷰의 삭제와 재생성을 통해서만 정의 변경이 가능하다. 뷰를 통해 접근 가능한 데이터에 대한 변경(INSERT, UPDATE, DELETE)이 가능하지만, 모든 경우에 데이터 변경이 허용되는 것은 아니다. 대표적으로 기본키에 해당하는 컬럼이 뷰에 정의되어 있지 않은 경우에는\nINSERT가 불가능하며, 이러한 제약은 뷰 자체가 논리적 개념이기에 물리적 상황(원본 테이블의 제약조건)에\n 의존적임을 의미한다."]]}]}]}]},{"t":"Ⅲ 조인의 세부 유형과 서브쿼리 동작 방식 분류","c":[{"t":"1. 논리적 조인의 세부 유형","c":[{"t":"(1) 내부 조인(Inner Join)의 세부 유형","c":[{"t":"① Equi Join(=) vs Natural Join","n":[["시험 포인트","교차 조인(Cross Join)은 조인 조건이 없는 모든 데이터의 조합을 추출하는 조인으로, 학생 수 x 학과 수만큼의 결과가 반환되는 카티션 곱(Cartesian Product)과 동일한 결과를 만들어낸다. 실기 시험에서\nFROM 절에 여러 테이블을 콤마로 나열하고 조인 조건을 빠뜨리는 실수가 이 교차 조인 결과를 그대로 만들어\n낸다는 점을 연결지어 이해해야 한다."],["설명","동등 조인(Equi Join)과 자연 조인(Natural Join) -- 동등 조인: 조건에 =를 사용\nSELECT s.name, d.dept_name FROM student s\nJOIN department d ON s.dept_id = d.dept_id;\n-- 자연 조인: 같은 이름의 컬럼을 자동으로 매칭\nSELECT * FROM student NATURAL JOIN department;\n동등 조인(Equi Join)은 공통으로 존재하는 컬럼의 값이 같은 경우를 추출하는 조인으로, 조인 조건에 등호 (=)를 사용한다. 자연 조인(Natural Join)은 두 테이블의 모든 컬럼을 비교하여, 같은 컬럼명을 가진 모든 컬럼의 값이 같은 경우를 추출하는 조인으로, 조인 조건을 명시적으로 작성하지 않아도 동일한 이름의 컬럼을 자동으로 매칭한다는 특징이 있다.\nSELECT * FROM student CROSS JOIN department;"]]},{"t":"② LEFT·RIGHT OUTER JOIN 기준 테이블","n":[["시험 포인트","왼쪽 외부 조인(Left Outer Join)은 왼쪽 테이블의 모든 데이터와 오른쪽 테이블의 동일 데이터를 추출하며, 오른쪽 테이블에 대응하는 값이 없으면 NULL로 채운다. 오른쪽 외부 조인(Right Outer Join)은 반대로 오른쪽 테이블의 모든 데이터와 왼쪽 테이블의 동일 데이터를 추출한다. 실기 시험에서는 어느 테이블이 \"기준\"이 되는지를 LEFT·RIGHT 키워드로 정확히 판단해야 한다.\nSELECT s.name, d.dept_name FROM student s\nFULL OUTER JOIN department d ON s.dept_id = d.dept_id;"],["설명","왼쪽 외부 조인과 오른쪽 외부 조인 -- 왼쪽 외부 조인: 왼쪽 테이블 기준 모든 데이터 + 대응하는 오른쪽 데이터\nSELECT s.name, d.dept_name FROM student s\nLEFT OUTER JOIN department d ON s.dept_id = d.dept_id;\n-- 오른쪽 외부 조인: 오른쪽 테이블 기준 모든 데이터 + 대응하는 왼쪽 데이터\nSELECT s.name, d.dept_name FROM student s\nRIGHT OUTER JOIN department d ON s.dept_id = d.dept_id;"]]}]},{"t":"(2) 비연관 서브쿼리와 연관 서브쿼리","c":[{"t":"① 비연관 서브쿼리 독립 선실행","n":[["설명","비연관(Un-Correlated) 서브쿼리\nSELECT name FROM student\nWHERE dept_id = (SELECT dept_id FROM department WHERE dept_name = '컴퓨터공학과'\n);\n비연관 서브쿼리는 서브쿼리가 메인쿼리의 컬럼을 가지고 있지 않은 형태로, 서브쿼리가 메인쿼리와 관계없이 독립적으로 먼저 실행되어 하나의 결괏값을 메인쿼리에 제공하는 용도로 사용된다. 위 예시에서 서브쿼리는 메인쿼리의 컬럼을 참조하지 않고 독립적으로 실행되어 dept_id 값을 반환한다.\nSELECT name FROM student s\nWHERE EXISTS (\n     SELECT 1 FROM enrollment e\n     WHERE e.student_id = s.student_id\n);\n연관 서브쿼리는 서브쿼리가 메인쿼리의 컬럼을 가지고 있는 형태로, 메인쿼리가 먼저 수행되어 얻은 각 행의 데이터를 서브쿼리의 조건에 맞는지 하나씩 확인하고자 할 때 사용한다. 위 예시에서 서브쿼리 내부의 s.student_id는 메인쿼리의 현재 행을 참조하므로, 메인쿼리의 행 수만큼 서브쿼리가 반복 실행되는 구조를 가진다."]]},{"t":"② 동작 방식·데이터 형태 분류 기준","n":[["시험 포인트","서브쿼리는 동작 방식에 따라 비연관 서브쿼리와 연관 서브쿼리로 분류되고, 반환되는 데이터의 형태에 따라 Single Row, Multiple Row, Multiple Column 서브쿼리로 분류된다. 이 두 가지 분류 기준은 서로 배타적이지 않고 동시에 적용될 수 있는 별개의 관점이라는 점을 실기 시험에서 혼동하지 않아야 한다."],["시험 포인트","실기 시험에서 서브쿼리 문제를 만나면, 먼저 서브쿼리가 메인쿼리의 컬럼을 참조하는지(연관 여부)를 확인하고, 그 다음 서브쿼리의 실행 결과가 몇 건·몇 컬럼으로 반환되는지(데이터 형태)를 파악하여 알맞은 비교 연산자(=, IN, EXISTS 등)를 선택하는 순서로 접근하면 실수를 줄일 수 있다."],["설명","동작 방식과 데이터 형태, 두 가지 분류 기준"]]}]}]}]}]},{"t":"제4절 조인·서브쿼리와 집합 연산","c":[{"t":"Ⅰ 조인(JOIN)의 개념과 유형","c":[{"t":"1. 조인의 개념","c":[{"t":"(1) 조인이란","c":[{"t":"① 조인=공통값 이용 교집합 결합","n":[["시험 포인트","조인은 관계형 데이터베이스의 가장 큰 장점이자 대표적인 핵심 기능이다. 여러 테이블에 나누어 저장된 정규화된 데이터를 필요에 따라 다시 결합하여 조회할 수 있게 해주므로, 실기 시험에서 두 개 이상의 테이블을 다루는 문제의 핵심 해결 도구가 된다."],["설명","조인의 정의 조인은 결합을 의미하며, 관계형 데이터베이스에서의 조인은 교집합 결과를 가지는 결합 방법을 의미한다. 두테이블의 공통값을 이용하여 컬럼을 조합하는 수단으로, 보통 기본키와 후보키값을 결합하여 사용하는 것이 일반적이지만, 보다 엄밀하게 말하면 기본키나 후보키와 관계없이 논리적인 값들의 연관을 사용하는 것도 가능하다."]]},{"t":"② 논리적 조인 유형","n":[["실제 사례","논리적 조인은 사용자의 SQL문에 표현되는 테이블 결합 방식으로, 두 테이블에 공통으로 존재하는 컬럼을 이용하는 방식(공통 컬럼 기반)이다. 그 종류로 내부 조인(Inner Join)과 외부 조인(Outer Join)이 있으며, 실기 시험에서 실제로 작성하는 조인 쿼리는 대부분 이 논리적 조인에 해당한다."],["설명","논리적 조인"]]}]},{"t":"(2) 내부 조인(INNER JOIN)","c":[{"t":"① INNER JOIN 조건 만족 행만 반환","n":[["설명","내부 조인 문법\nSELECT s.name, d.dept_name\nFROM student s\nINNER JOIN department d ON s.dept_id = d.dept_id;\nINNER JOIN은 두 테이블에서 조인 조건을 만족하는 행만을 결과로 반환한다. 즉, 학생 테이블에는 있지만 학과 테이블에 대응하는 정보가 없는 학생은 결과에서 제외되며, 두 테이블의 교집합에 해당하는 데이터만 조회된다.\nSELECT s.name, d.dept_name\nFROM student s\nLEFT OUTER JOIN department d ON s.dept_id = d.dept_id;\nLEFT OUTER JOIN은 왼쪽 테이블(student)의 모든 행을 결과에 포함시키고, 오른쪽 테이블(department)에 대응하는 데이터가 없으면 해당 컬럼을 NULL로 채워 반환한다. 이는 물리적 조인 설명에서 언급된 \"특정 테이블의 모든 데이터를 기준으로 다른 테이블의 정보를 추출(다른 테이블에 값이 없어도 출력됨)\"하는 특성과 연결된다."]]},{"t":"② 조인 조건 누락→카티션 곱","n":[["설명","조인 조건 누락(카티션 곱) -- 오류: 조인 조건(ON) 누락\nSELECT s.name, d.dept_name\nFROM student s, department d;\n-- 학생 수 x 학과 수 만큼의 결과가 반환됨\nFROM 절에 여러 테이블을 콤마로 나열하면서 조인 조건을 명시하지 않으면, 두 테이블의 모든 행이 각각 조\n합되는 카티션 곱(Cartesian Product)이 발생한다. 조인 문제에서는 반드시 ON 절(또는 WHERE 절)에 조인 조건이 명시되어 있는지 확인해야 한다.\nSELECT a.name AS 직원, b.name AS 상사\nFROM employee a\nJOIN employee b ON a.manager_id = b.emp_id;\n셀프 조인은 동일한 테이블을 마치 서로 다른 두 개의 테이블처럼 취급하여 조인하는 기법으로, 직원과 그 직원의 상사가 같은 테이블에 저장되어 있는 경우처럼 계층 구조를 표현할 때 활용된다. 반드시 서로 다른 별칭 (alias)을 부여하여 두 테이블을 구분해야 한다."]]}]}]}]},{"t":"Ⅱ 서브쿼리와 집합 연산","c":[{"t":"1. 서브쿼리(Sub Query)의 유형","c":[{"t":"(1) 데이터 형태에 따른 서브쿼리 분류","c":[{"t":"① 단일 행(=,<) vs 다중 행(IN,ANY)","n":[["시험 포인트","다중 컬럼 서브쿼리는 서브쿼리의 결과가 여러 컬럼으로 반환되는 서브쿼리이다. 메인쿼리의 조건절에서 여러 컬럼을 동시에 비교할 때, 서브쿼리와 메인쿼리에서 비교하는 컬럼의 개수와 위치가 정확히 동일해야 한다는 점을 실기 시험에서 유의해야 한다."],["설명","단일 행(Single Row)과 다중 행(Multiple Row) 서브쿼리 단일 행(Single Row) 서브쿼리는 서브쿼리의 결과가 항상 1건 이하로 반환되는 서브쿼리로, =, <, <=, >, >=, <>와 같은 단일 행 비교 연산자가 사용된다. 다중 행(Multiple Row) 서브쿼리는 서브쿼리 실행 결과가 여러 건인 서브쿼리로, IN, ALL, ANY, SOME, EXISTS와 같은 다중 행 비교 연산자가 사용된다는 차이가 있다."]]},{"t":"② AVG 비교 단일 행 서브쿼리 실습","n":[["실제 사례","서브쿼리가 여러 값을 반환할 가능성이 있다면 = 대신 IN을 사용해야 하며, 이를 혼동하여 =를 사용하면 \"subquery returns more than 1 row\"와 같은 오류가 발생한다. EXISTS는 서브쿼리 결과의 존재 여부만 확인하므로 실제 값보다 존재 여부 확인이 중요한 문제에 효율적으로 활용된다."],["설명","단일 행 서브쿼리 실습\nSELECT name, score FROM student\nWHERE score > (SELECT AVG(score) FROM student);\n전체 학생의 평균 점수보다 높은 점수를 가진 학생을 조회하는 이 쿼리는, 서브쿼리(SELECT AVG(score)...)의 결과가 항상 하나의 값(평균)만 반환하므로 > 연산자를 그대로 사용할 수 있는 단일 행 서브쿼리의 대표적인 예이다.\nSELECT name FROM student\nWHERE dept_id IN (SELECT dept_id FROM department WHERE region = '서울');\nSELECT name FROM student s\nWHERE EXISTS (SELECT 1 FROM enrollment e WHERE e.student_id = s.student_id);"]]}]},{"t":"(2) 집합 연산의 개념과 유형","c":[{"t":"① 집합 연산 UNION·INTERS ECT·MINUS","n":[["설명","집합 연산의 개념 집합 연산은 테이블을 집합 개념으로 보고, 두 테이블(또는 두 질의)의 연산에 집합 연산자를 사용하는 방식이다. 집합 연산자는 2개 이상의 질의 결과를 하나의 결과로 만들어 주며, 서로 다른 테이블에서 유사한 형태의 결과를 반환하는 것을 하나로 합치고자 할 때, 또는 동일 테이블에서 서로 다른 질의를 수행하여 결과를 합치고자 할 때 사용한다. 집합 연산자에는 UNION(여러 SQL문 결과의 합집합, 중복 행 제거함), UNION ALL(여러 SQL문 결과의 합집합, 중복 행 제거하지 않음), INTERSECTION(여러 SQL문 결과의 교집합, 중복 행 제거함), MINUS(앞의 SQL문 결과와 뒤의 SQL문 결과 사이의 차집합, 중복 행 제거함, 일부 제품의 경우 EXCEPT 사용)가 있다."]]},{"t":"② UNION 중복 제거 vs UNION ALL","n":[["설명","UNION과 UNION ALL 실습\nSELECT name FROM student WHERE department = '컴퓨터공학과'\nUNION\nSELECT name FROM student WHERE score >= 90;\n-- 두 조건을 만족하는 이름을 중복 없이 합쳐서 반환 -- UNION ALL을 사용하면 중복된 이름도 그대로 모두 표시됨 UNION은 두 쿼리 결과를 합치되 중복된 행을 자동으로 제거하며, UNION ALL은 중복 제거 과정을 생략하 므로 UNION보다 처리 속도가 빠르다. 중복 제거가 필요하지 않은 상황이라면 UNION ALL을 사용하는 것이 성능상 유리하다.\nSELECT student_id FROM student\nMINUS\nSELECT student_id FROM enrollment;\n-- 수강 신청을 하지 않은 학생의 student_id만 반환 MINUS는 앞의 쿼리 결과에서 뒤의 쿼리 결과에 존재하는 값을 제외한 나머지만 반환하는 차집합 연산이다. 전체 학생 중 수강 신청 테이블(enrollment)에 존재하지 않는 학생, 즉 아직 수강 신청을 하지 않은 학생을 찾는 문제와 같이 \"A에는 있지만 B에는 없는 데이터\"를 조회할 때 매우 유용하게 활용된다."]]}]}]}]}]},{"t":"제5절 DML과 데이터 조작 실무","c":[{"t":"Ⅰ DML(데이터 조작어)의 개념과 데이터 조회","c":[{"t":"1. DML의 개념과 유형","c":[{"t":"(1) DML이란","c":[{"t":"① DML 데이터 조작어 정의","n":[["실제 사례","DML은 데이터를 조작하는 명령어로, 여기서 조작이란 데이터 관점에서 데이터의 생명 주기(생성, 조회, 변경, 삭제)를 제어하는 것을 의미한다. DDL이 데이터를 담는 그릇(오브젝트) 자체를 다룬다면, DML은그 그릇 안에 담긴 실제 데이터를 다룬다는 점에서 근본적으로 구분된다."],["시험 포인트","DML 명령어에는 데이터 조회를 담당하는 SELECT(테이블의 내용을 조회), 데이터 삭제를 담당하는 DELETE(테이블의 내용을 삭제), 데이터 변경을 담당하는 UPDATE(테이블의 내용을 변경), 데이터 추가를 담당하는 INSERT(테이블의 내용을 추가)의 네 가지가 있다. 실기 시험에서는 이 네 명령어의 정확한 문법과 실행 결과를 예측하는 문제가 핵심적으로 출제된다."],["설명","DML(Data Manipulation Language)의 정의"]]},{"t":"② SELECT [DISTINCT] 기본 형식","n":[["시험 포인트","ALL 옵션은 중복을 포함한 조회 결과를 그대로 출력하며 SELECT 문의 기본값이기도 하다. DISTINCT 옵션은 중복된 행을 제외하고 서로 다른 값만 한 번씩 출력한다. 실기 시험에서 \"중복을 제거하여 출력하라\"는 요구사항이 있으면 DISTINCT를 사용해야 한다는 점을 기억해야 한다."],["설명","SELECT의 기본 형식\nSELECT [OPTION] columns FROM table [WHERE 절];\n SELECT는 테이블의 내용을 조회할 때 사용하는 명령어로, 가장 많이 사용되는 SQL 명령어이며 다른 DML\n명령어와 함께 사용되어 SQL 활용을 풍부하게 만든다. OPTION 자리에는 ALL 또는 DISTINCT가 올 수 있고, columns 자리에는 조회할 컬럼명 목록 또는 전체를 의미하는 와일드카드(*)가 올 수 있다.\nSELECT ALL dept_name FROM student;         -- 중복 포함 조회\nSELECT DISTINCT dept_name FROM student; -- 중복 제거 조회"]]}]},{"t":"(2) 조건 검색과 정렬","c":[{"t":"① WHERE 논리·비교·특수 연산자","n":[["설명","WHERE 절을 이용한 조건 검색\nSELECT name, score FROM student\nWHERE score >= 80 AND dept_id = 101;\n WHERE 절은 조회할 행의 조건을 지정하는 절로, AND/OR/NOT과 같은 논리 연산자와 =, <>, >, <, >=,\n<=와 같은 비교 연산자, BETWEEN, IN, LIKE, IS NULL과 같은 특수 연산자를 조합하여 정교한 조건을 표현할 수 있다.\nSELECT name, score FROM student\nORDER BY score DESC, name ASC;\nORDER BY는 조회 결과를 특정 컬럼 기준으로 정렬하는 절로, ASC(오름차순, 기본값)와 DESC(내림차순)를 지정할 수 있다. 여러 컬럼을 나열하면 앞쪽 컬럼을 우선 기준으로 정렬하고, 값이 같을 경우 다음 컬럼을 기준으로 추가 정렬한다."]]},{"t":"② COUNT·AVG·MAX·MIN· SUM 집계","n":[["시험 포인트","집계 함수는 여러 행의 값을 하나의 결과로 요약하는 함수로, COUNT(개수), AVG(평균), MAX( 최댓값), MIN(최솟값), SUM(합계)이 대표적이다. 실기 시험에서는 특정 조건을 만족하는 행의 개수나 평균을 구하는 문제에 이러한 함수들을 정확히 조합하여 사용할 수 있어야 한다.\nSELECT dept_id, AVG(score) FROM student\nGROUP BY dept_id\nHAVING AVG(score) >= 80;"],["설명","집계 함수(Aggregate Function)\nSELECT COUNT(*), AVG(score), MAX(score), MIN(score), SUM(score)\nFROM student;"]]}]}]}]},{"t":"Ⅱ 데이터 변경(INSERT·UPDA TE·DELETE) 실무","c":[{"t":"1. 데이터 추가와 변경","c":[{"t":"(1) INSERT 문","c":[{"t":"① INSERT 컬럼 명시형·생략형","n":[["설명","INSERT의 두 가지 형식\nINSERT INTO table_name (column1, column2, ...) VALUES (value1, value2, ...);\nINSERT INTO table_name VALUES (value1, value2, ...);\n INSERT는 데이터를 삽입하는 명령어로, 컬럼명을 명시하는 형식과 생략하는 형식 두 가지를 제공한다. 컬럼\n명을 생략할 경우 VALUES에 나열하는 값의 개수와 순서가 테이블에 정의된 모든 컬럼의 개수와 순서에 정확히 일치해야 하며, 데이터 삽입 결과로 하나의 레코드가 추가되므로 삽입에 사용되는 정보는 하나의 레코드를 충분히 묘사해야 한다.\nINSERT INTO student (student_id, name) VALUES (1005, '홍길동');\n컬럼명을 명시하여 일부 컬럼에만 값을 지정하는 경우, 지정하지 않은 나머지 컬럼은 DEFAULT로 지정된 값이 채워지거나, DEFAULT가 없고 NOT NULL 제약조건도 없다면 NULL로 채워진다. 만약 NOT NULL 제약조건이 있는 컬럼을 값 없이 비워두면 오류가 발생한다."]]},{"t":"② UPDATE SET [WHERE] 문법","n":[["시험 포인트","UPDATE는 데이터를 변경, 수정할 때 사용하는 명령어로, SET 절에 변경할 컬럼과 새로운 값을 나열한다. WHERE 절을 통해 어떤 조건을 만족하는 행에 대해서만 특정 컬럼의 값을 수정하는 용도로 많이 사용되며, WHERE 절을 생략하면 테이블의 모든 행이 한꺼번에 변경되므로 각별히 주의해야 한다.\nDELETE FROM table [WHERE 절];"],["시험 포인트","DELETE는 레코드를 삭제할 때 사용하는 명령어이다. 조건절 없이 DELETE를 사용하는 경우 테이블 전체의 데이터가 한 번에 삭제되므로, 실기 시험에서 WHERE 절의 유무에 따른 실행 결과 차이를 정확히 예측할 수 있어야 한다. DELETE는 데이터만 삭제하고 테이블 구조는 남기며, 롤백이 가능한 트랜잭션의 일부로 처리된다는 점에서 DROP·TRUNCATE와 구분된다."],["설명","UPDATE 문의 문법과 주의사항\nUPDATE table SET column1 = value1, column2 = value2, ... [WHERE 절];"]]}]},{"t":"(2) DML 명령어 실행 순서와 결과 예측","c":[{"t":"① INSERT→UPDATE→DELE TE→SELECT 흐름","n":[["시험 포인트","실기 시험에서는 위와 같이 여러 DML 문장을 순서대로 실행했을 때 최종적으로 어떤 데이터가 남는지를 묻는 문제가 자주 출제된다. 각 문장을 순서대로 하나씩 적용해 가며 테이블의 상태 변화를 단계별로 추적하는 연습이 필요하다."],["설명","복합 DML 실행 흐름\nINSERT INTO student VALUES (2001, '김철수', 101, 85);\nUPDATE student SET score = score + 5 WHERE student_id = 2001;\nDELETE FROM student WHERE score < 60;\nSELECT * FROM student WHERE student_id = 2001;"]]},{"t":"② WHERE 누락 시 전체 행 변경 사고","n":[["실제 사례","실무에서 가장 빈번하게 발생하는 사고 유형은 UPDATE나 DELETE 문에서 WHERE 절을 빠뜨려 의도하지 않은 전체 데이터가 변경되거나 삭제되는 경우이다. 이러한 사고를 예방하기 위해 실무에서는 먼저 동일한 조건으로 SELECT를 실행하여 영향을 받을 행을 확인한 뒤 UPDATE·DELETE를 실행하는 습관이 권장된다. -- 오류: 문자열 컬럼에 따옴표 없이 값 입력\nINSERT INTO student (name) VALUES (홍길동);\n-- 올바른 예\nINSERT INTO student (name) VALUES ('홍길동');"],["시험 포인트","문자형(CHAR, VARCHAR)이나 날짜형(DATE) 컬럼에 값을 입력할 때는 반드시 작은따옴표로 값을 감싸야 하며, 이를 누락하면 문법 오류가 발생한다. 숫자형(INT, FLOAT) 컬럼은 따옴표 없이 값을 그대로 입력한다는 차이를 실기 시험에서 정확히 구분해야 한다."],["설명","WHERE 절 누락으로 인한 전체 변경 사고 -- 위험한 예: WHERE 절 누락\nUPDATE student SET score = 0;\n-- 의도: 특정 학생만 초기화하려 했으나 전체 학생의 점수가 0이 됨"]]}]}]}]}]},{"t":"제9절 SQL 실기 시험 대비 마무리 점검","c":[{"t":"Ⅰ 핵심 문법 최종 요약","c":[{"t":"1. DDL·DML 핵심 요약","c":[{"t":"(1) DDL 명령어 총정리","c":[{"t":"① DDL 4대 명령어와 오브젝트","n":[["시험 포인트","DDL의 4대 명령어는 CREATE(생성), ALTER(변경), DROP(삭제), TRUNCATE(내용만 삭제, 구조 유지)이며, 이들이 다루는 오브젝트 대상은 스키마, 도메인, 테이블, 뷰, 인덱스이다. 실기 시험 직전에는이 네 명령어와 각각의 정확한 문법을 다시 한 번 손으로 써 보며 확인하는 것이 효과적이다."],["시험 포인트","제약조건에는 PRIMARY KEY(기본 키, NOT NULL+UNIQUE 포함), FOREIGN KEY(외래 키, 참조 무결성), UNIQUE(고유 키, NULL 허용), NOT NULL(널 값 불허), CHECK(조건식 지정), 그리고 이름을 지정하는 CONSTRAINT 키워드가 있다. 각 제약조건이 \"중복 허용 여부\"와 \"NULL 허용 여부\"에서 어떻게 다른지 표로 정리하여 암기해 두면 실기 시험에서 빠르게 답할 수 있다."],["설명","DDL 4대 명령어와 오브젝트 대상"]]},{"t":"② DML 4대 명령어 핵심 문법","n":[["설명","SELECT·INSERT·UPDATE·DELETE 핵심 문법 DML의 4대 명령어는 SELECT(조회), INSERT(추가), UPDATE(변경), DELETE(삭제)이다. SELECT\n[OPTION] columns FROM table [WHERE 절]; INSERT INTO table (columns) VALUES (values);\nUPDATE table SET column=value [WHERE 절]; DELETE FROM table [WHERE 절]; 이 네 가지 기본\n골격을 정확히 기억하고, WHERE 절 생략 시의 위험성(UPDATE·DELETE 전체 적용)을 항상 함께 떠올려야 한다. SQL 문의 절 순서는 SELECT - FROM - WHERE - GROUP BY - HAVING - ORDER BY로 고정되어 있다. WHERE는 그룹화 이전 개별 행 필터링, HAVING은 그룹화 이후 집계 결과 필터링이라는 차이를 다시 한번 명확히 구분해 두어야 한다."]]}]},{"t":"(2) DCL 핵심 요약","c":[{"t":"① GRANT는 TO·REVOKE는 FROM","n":[["시험 포인트","GRANT 권한 TO 사용자(권한을 준다, TO), REVOKE 권한 FROM 사용자(권한을 회수한다,\nFROM)의 대응 관계를 정확히 암기해야 한다. 시스템 권한(CREATE TABLE, CREATE VIEW, CREATE\nUSER 등)과 객체 권한(SELECT, INSERT, UPDATE, DELETE, ALTER, EXECUTE ON PROCEDURE)의 차이는 ON 객체명의 유무로 구분된다는 점도 함께 기억한다."],["설명","GRANT·REVOKE와 TO·FROM"]]},{"t":"② COMMIT 후 ROLLBACK 불가·자동 커밋","n":[["시험 포인트","트랜잭션은 하나 이상의 SQL 문장을 포함하는 논리적 연산 단위이자 더 이상 분할할 수 없는 최소 단위의 거래이며, 그 결과는 모두 반영되거나 모두 취소되어야 한다는 원칙을 다시 한 번 되새기며 시험장에 들어가는 것이 좋다."],["설명","COMMIT·ROLLBACK·CHECKPOINT COMMIT은 트랜잭션 확정(변경 사항을 영구 반영), ROLLBACK은 트랜잭션 취소(변경 사항을 되돌림), CHECKPOINT는 저장점 설정(ROLLBACK할 위치 지정)이다. COMMIT 이후에는 ROLLBACK으로 되돌릴 수 없다는 점, 자동 커밋 모드에서는 매 SQL 문마다 자동으로 COMMIT이 수행되어 ROLLBACK이 무의 미해진다는 점을 마지막으로 한 번 더 점검한다."]]}]}]}]},{"t":"Ⅱ 실전 대비 자주 나오는 함정과 모의 점검","c":[{"t":"1. 실기 시험에서 자주 나오는 함정","c":[{"t":"(1) 문법 관련 함정","c":[{"t":"① 단수·복수·철자 함정","n":[["시험 포인트","REFERENCES(끝에 S 있음), CONSTRAINT(끝에 T), TRUNCATE(중간에 N 없음, TRUNCATE로 정확히 표기) 등 철자를 혼동하기 쉬운 키워드는 실기 시험에서 반복적으로 출제되는 함정이다. 실전에서는 이러한 키워드를 손으로 여러 번 직접 타이핑하며 정확한 철자를 몸에 익히는 연습이 가장 효과적이다."],["시험 포인트","WHERE 절과 GROUP BY, HAVING, ORDER BY의 순서를 바꾸어 배치하는 문제나, 서브쿼리의 괄호를 누락시키는 문제가 자주 출제된다. 채점 시스템(컴퓨터 실습 환경)에서는 이러한 순서 오류가 있으면 실행 자체가 되지 않으므로, 답안을 제출하기 전 반드시 직접 실행해 문법 오류 여부를 확인하는 습관이 중요하다."],["설명","단수·복수, 철자 함정"]]},{"t":"② IS NULL·집계 NULL 제외 함정","n":[["시험 포인트","UPDATE·DELETE 문에서 WHERE 절을 생략하면 테이블 전체에 영향을 미친다는 사실은 실기 시험의 결과 예측 문제에서 반복적으로 다루어진다. 문제에서 \"테이블 전체가 어떻게 변경되는가\" 또는 \"특정 조건의 행만 어떻게 되는가\"를 구분하여 묻는 경우, WHERE 절의 존재 여부를 가장 먼저 확인하는 습관을 들여야 한다."],["설명","NULL 처리 함정 = NULL 대신 IS NULL을 사용해야 하는 점, 집계 함수가 NULL을 계산에서 제외한다는 점, UNIQUE 제약조건이 NULL은 중복으로 취급하지 않는다는 점은 모두 NULL과 관련된 대표적인 함정이다. 문제에 NULL이 언급되면 항상 \"이 값이 계산·비교·제약조건에서 예외적으로 처리되지 않는가\"를 먼저 점검해야 한다."]]}]},{"t":"(2) 모의 문제 1: 테이블 설계와 제약조건","c":[{"t":"① PK·NOT NULL·CHECK· FK 테이블 작성","n":[["설명","문제: 아래 요구사항에 맞는 CREATE TABLE 문 작성 요구사항: 학과(department) 테이블을 참조하는 학생(student) 테이블을 생성하라. student_id는 기본 키, name은 필수 입력, score는 0~100 사이의 값만 허용, dept_id는 department 테이블의 dept_id를 참조하는 외래 키로 지정하라.\nCREATE TABLE student (\n     student_id INT PRIMARY KEY,\n     name VARCHAR(20) NOT NULL,\n     score INT CHECK (score BETWEEN 0 AND 100),\n     dept_id INT,\n     FOREIGN KEY (dept_id) REFERENCES department(dept_id)\n);"]]},{"t":"② 학과별 AVG≥80 HAVING·ORDER BY","n":[["설명","문제: 아래 요구사항에 맞는 SELECT 문 작성 요구사항: 학과별 평균 점수를 구하되, 평균 점수가 80점 이상인 학과만, 평균 점수가 높은 순서로 정렬하여 학과 이름과 평균 점수를 조회하라. (student와 department는 dept_id로 조인)\nSELECT d.dept_name, AVG(s.score) AS avg_score\nFROM student s JOIN department d ON s.dept_id = d.dept_id\nGROUP BY d.dept_name HAVING AVG(s.score) >= 80\nORDER BY avg_score DESC;"]]}]}]}]}]},{"t":"제13절 SQL 내장 함수 실무 활용","c":[{"t":"Ⅰ 문자 함수와 숫자 함수","c":[{"t":"1. 문자 함수(String Function)","c":[{"t":"(1) 문자열 결합과 길이 함수","c":[{"t":"① CONCAT 문자열 결합","n":[["설명","CONCAT과 문자열 결합\nSELECT CONCAT(name, '(', dept_name, ')') AS 표시이름\nFROM student s JOIN department d ON s.dept_id = d.dept_id;\nCONCAT 함수는 두 개 이상의 문자열을 하나로 결합하는 함수로, 이름과 학과명을 \"홍길동(컴퓨터공학과)\" 와 같은 형태로 합쳐서 보여주고 싶을 때 활용한다. 일부 DBMS에서는 CONCAT 대신 || 연산자로도 문자열을 결합할 수 있다.\nSELECT name, LENGTH(name) AS 이름길이\nFROM student WHERE LENGTH(name) > 3;\nLENGTH 함수는 문자열의 길이(문자 개수)를 반환하는 함수로, 이름이 3자를 초과하는 학생을 조회하는 등문자열 길이 조건이 필요한 문제에 활용된다."]]},{"t":"② SUBSTRING(phone,1, 3) 부분 추출","n":[["설명","SUBSTRING(문자열 일부 추출)\nSELECT SUBSTRING(phone, 1, 3) AS 국번\nFROM customer;\nSUBSTRING(또는 SUBSTR) 함수는 문자열의 특정 위치에서 지정한 길이만큼 부분 문자열을 추출하는 함수이다. 위 예시는 전화번호(phone) 문자열의 첫 번째 위치부터 3글자를 추출하여 국번만 뽑아내는 활용이다.\nSELECT * FROM student WHERE UPPER(email) LIKE '%@GMAIL.COM';\nUPPER는 문자열을 모두 대문자로, LOWER는 모두 소문자로 변환하는 함수이다. 이메일 주소처럼 대소문자가 섞여 입력될 수 있는 데이터를 검색할 때, UPPER나 LOWER로 대소문자를 통일한 뒤 비교하면 대소문자 표기 차이로 인한 조회 누락을 방지할 수 있다."]]}]},{"t":"(2) 반올림·절삭 함수","c":[{"t":"① ROUND 반올림·TRUNC 절삭","n":[["시험 포인트","TRUNC 함수는 반올림 없이 지정한 자릿수 이하를 그대로 잘라내는(절삭) 함수이다. ROUND(85.7)이 86으로 반올림되는 것과 달리, TRUNC(85.7)은 85로 소수점 이하를 버린다는 차이를 실기 시험에서 정확히 구분해야 한다."],["설명","ROUND(반올림)\nSELECT name, ROUND(score, 1) AS 반올림점수\nFROM student;\nROUND 함수는 숫자를 지정한 소수 자릿수로 반올림하는 함수이다. ROUND(score, 1)은 score 값을 소수 첫째 자리까지 반올림하여 표시하며, 두 번째 인자를 생략하면 정수로 반올림한다.\nSELECT TRUNC(85.7) AS 절삭값 FROM DUAL;      -- 결과: 85"]]},{"t":"② ABS 절댓값·MOD 나머지","n":[["설명","ABS(절댓값)\nSELECT ABS(score - target_score) AS 점수차이\nFROM student;\nABS 함수는 숫자의 절댓값을 반환하는 함수로, 두 값의 차이가 양수인지 음수인지 관계없이 순수한 차이 크기만 비교하고 싶을 때 활용된다.\nSELECT student_id FROM student WHERE MOD(student_id, 2) = 0;\nMOD 함수는 첫 번째 인자를 두 번째 인자로 나눈 나머지를 반환하는 함수이다. MOD(student_id, 2) = 0은 student_id가 짝수인 행만 조회하는 조건으로, 홀짝 구분이 필요한 문제에 자주 활용된다."]]}]}]}]},{"t":"Ⅱ 날짜 함수와 NULL 처리 함수","c":[{"t":"1. 날짜 함수(Date Function)","c":[{"t":"(1) 현재 날짜와 날짜 연산","c":[{"t":"① SYSDATE-365=1년 전 날짜","n":[["설명","SYSDATE·NOW(현재 날짜·시간)\nSELECT name, hire_date FROM employee\nWHERE hire_date <= SYSDATE - 365;\nSYSDATE(또는 제품에 따라 NOW())는 현재 날짜와 시간을 반환하는 함수이다. 날짜형 데이터에 정수를 더하거나 빼면 그만큼의 일수가 가감되므로, SYSDATE - 365는 1년 전 날짜를 의미하며 입사한 지 1년이 지난 직원을 조회하는 조건으로 활용된다.\nSELECT name, SYSDATE - hire_date AS 근속일수\nFROM employee;\n두 날짜형 값을 빼면 그 사이의 일수 차이가 계산된다. SYSDATE - hire_date는 현재 날짜에서 입사일을 뺀값으로, 근속 일수를 계산하는 데 활용되는 대표적인 날짜 연산 방식이다."]]},{"t":"② TO_CHAR 'YYYY-MM-D D' 변환","n":[["설명","TO_CHAR(날짜를 문자열로 변환)\nSELECT name, TO_CHAR(hire_date, 'YYYY-MM-DD') AS 입사일\nFROM employee;\nTO_CHAR 함수는 날짜형 데이터를 지정한 형식의 문자열로 변환하는 함수이다. 'YYYY-MM-DD'와 같은 형식 문자열을 지정하면 원하는 표기 방식(연-월-일)으로 날짜를 출력할 수 있다.\nSELECT * FROM employee\nWHERE hire_date >= TO_DATE('2025-01-01', 'YYYY-MM-DD');\nTO_DATE 함수는 문자열을 지정한 형식에 맞추어 날짜형 데이터로 변환하는 함수이다. WHERE 절에서 날짜형 컬럼과 문자열을 직접 비교하려면, 이처럼 TO_DATE로 문자열을 날짜형으로 먼저 변환해야 정확한 비교가 이루어진다."]]}]},{"t":"(2) NULL 치환 함수","c":[{"t":"① NVL·COALESCE NULL 치환","n":[["실제 사례","NULLIF 함수는 두 인자의 값이 같으면 NULL을 반환하고, 다르면 첫 번째 인자의 값을 그대로 반환하는 함수이다. score가 0인 경우(아직 시험을 보지 않아 편의상 0으로 저장한 경우 등)를 실제로는 \"값이 없는 것\"으로 취급하고 싶을 때 NULLIF(score, 0)을 사용하면 0을 NULL로 변환하여 집계 함수 계산에서 제외시킬 수 있다."],["설명","NVL·COALESCE(NULL을 다른 값으로 치환)\nSELECT name, NVL(score, 0) AS 점수\nFROM student;\nNVL(또는 여러 값 중 NULL이 아닌 첫 값을 찾는 COALESCE) 함수는 값이 NULL이면 지정한 대체 값을 반환하고, NULL이 아니면 원래 값을 그대로 반환하는 함수이다. score가 NULL인 학생을 0점으로 간주하여 계산하고 싶을 때 NVL(score, 0)과 같이 활용한다.\nSELECT NULLIF(score, 0) AS 점수\nFROM student;"]]},{"t":"② CASE WHEN 점수별 학점 분기","n":[["설명","CASE WHEN(조건별 값 분기)\nSELECT name, score,\nCASE WHEN score >= 90 THEN 'A' WHEN score >= 80 THEN 'B' WHEN score >= 70 THEN 'C' ELSE 'D' END AS 학점\nFROM student;\nCASE WHEN 구문은 조건에 따라 서로 다른 값을 반환하는 조건 분기 표현식이다. 점수 구간에 따라 A, B, C, D와 같은 학점을 부여하는 것처럼, 여러 조건을 순차적으로 검사하여 처음 만족하는 조건의 결과값을 반환하고, 어떤 조건도 만족하지 않으면 ELSE 절의 값을 반환한다.\nSELECT name, gender,\nDECODE(gender, 'M', '남성', 'F', '여성', '미상') AS 성별표시\nFROM student;\nDECODE 함수는 일부 DBMS 제품에서 제공하는 함수로, 특정 값과 일치하는 경우에 대응하는 값을 반환하고 어느 것과도 일치하지 않으면 마지막 인자(기본값)를 반환한다. CASE WHEN이 범위나 복잡한 조건 비교에 유리하다면, DECODE는 특정 값 하나하나를 나열하여 치환하는 단순 매핑에 간결하게 사용된다."]]}]}]}]}]},{"t":"제14절 실기 시험 SQL 실습 환경 대비","c":[{"t":"Ⅰ 실습형 채점 환경의 특징","c":[{"t":"1. 컴퓨터 실습 환경에서의 SQL 작성 유의점","c":[{"t":"(1) 실습 환경과 필답형의 차이","c":[{"t":"① 실제 실행 결과가 채점 기준","n":[["시험 포인트","필답형 시험에서는 문법을 정확히 알고 있으면 손으로 쓴 답이 다소 형식적으로 부정확해도 채점자가 의도를 파악해 부분 점수를 줄 수 있었지만, 컴퓨터 실습 환경에서는 작성한 SQL 문이 실제로 실행되어 요구된 결과를 만들어내는지가 그대로 채점 기준이 된다. 따라서 문법 오류 없이 실행되는 것 자체가 1차적으로 매우 중요하다."],["쉬운 예","일부 DBMS는 테이블명·컬럼명의 대소문자를 구분하지 않지만, 문자열 값(작은따옴표로 감싼 값)은 대소문자를 구분하여 비교하는 경우가 많다. 예를 들어 WHERE dept_name = '컴퓨터공학과'와 WHERE dept_name = '컴퓨터공학과 '(끝에 공백 포함)는 서로 다른 값으로 취급되어 조회 결과가 달라질 수 있으므로, 실습 환경에서는 오타나 불필요한 공백에 특히 주의해야 한다."],["설명","실제 실행 결과가 채점 기준"]]},{"t":"② 세미콜론(;) 누락 실행 실패","n":[["시험 포인트","문제에서 제시된 테이블명(student)과 컬럼명(student_id)을 정확히 그대로 사용하지 않고 임의로 줄이거나(stu, sid 등) 변형하여 작성하면, 해당 테이블이나 컬럼이 존재하지 않는다는 오류가 발생한다. 문제에 제시된 이름을 복사하듯 정확히 옮겨 적는 습관이 실습형 시험에서는 특히 중요하다."],["설명","세미콜론 누락으로 인한 실행 실패 여러 SQL 문을 한 번에 작성하여 실행하는 환경에서는 각 문장 끝에 세미콜론(;)이 없으면 다음 문장과 하나로 합쳐져 문법 오류가 발생하거나, 의도한 문장이 실행되지 않을 수 있다. 각 SQL 문을 작성할 때마다 세미콜론으로 마무리하는 습관을 들여야 한다."]]}]},{"t":"(2) 문제 분석 순서","c":[{"t":"① DISTINCT·GROUP BY 등 키워드 추출","n":[["설명","요구사항에서 핵심 키워드 추출 문제 지문에서 \"중복 없이\"(DISTINCT), \"~이상/~이하\"(비교 연산자와 BETWEEN), \"그룹별로\"(GROUP BY), \"~순으로 정렬\"(ORDER BY)과 같은 핵심 키워드를 먼저 표시해 두면, 어떤 SQL 절과 함수를 사용해야 하는지 빠르게 판단할 수 있다. SQL 문을 작성하기 전에 DESC 테이블이름 명령이나 제시된 테이블 정의서를 통해 각 테이블의 컬럼명, 데이터 타입, 제약조건(특히 기본 키와 외래 키)을 먼저 파악해야, 조인 조건이나 WHERE 조건을 정확하게 작성할 수 있다."]]},{"t":"② SELECT*부터 단계적 확장","n":[["설명","단순한 SELECT부터 점진적으로 확장 복잡한 조인과 서브쿼리가 포함된 문제라도, 먼저 가장 기본적인 SELECT * FROM 테이블;로 데이터의 형태를 확인한 뒤, WHERE 조건을 추가하고, 필요하면 JOIN을 추가하고, 마지막으로 GROUP BY·ORDER BY를 붙여나가는 단계적 접근이 실수를 줄이는 데 효과적이다. 전체 SQL 문을 한 번에 완성하려 하지 말고, 조인까지만 작성한 상태에서 한 번 실행해 결과를 확인하고, 이어서 GROUP BY를 추가해 다시 실행하는 식으로 단계마다 실행 결과를 눈으로 검증하면서 진행하면 어느 단계에서 오류가 발생했는지 빠르게 찾아낼 수 있다."]]}]}]}]},{"t":"Ⅱ 실기 시험 대비 최종 자가 점검표","c":[{"t":"1. DDL·DML 자가 점검","c":[{"t":"(1) DDL 관련 자가 점검 항목","c":[{"t":"① CREATE/ALTER·DROP/ TRUNCATE 구분","n":[["쉬운 예","FOREIGN KEY의 ON DELETE 옵션 다섯 가지(NO ACTION, SET DEFAULT, SET NULL, CASCADE, RESTRICT)를 각각 설명할 수 있는가? CHECK 제약조건 위반 시 어떤 일이 벌어지는지 예를 들어 설명할 수 있는가? 이 항목들이 막힌다면 DDL 절을 한 번 더 복습해야 한다."],["설명","CREATE·ALTER·DROP·TRUNCATE 구분 점검 스스로에게 다음을 질문해 본다. CREATE와 ALTER의 차이를 한 문장으로 설명할 수 있는가? DROP과 TRUNCATE 중 테이블 구조까지 삭제하는 것은 무엇인가? PRIMARY KEY와 UNIQUE의 NULL 허용 여부 차이를 알고 있는가? 이 세 가지 질문에 막힘없이 답할 수 있다면 DDL의 핵심은 충분히 숙지된 상태이다."]]},{"t":"② 절 순서·WHERE vs HAVING·COUNT","n":[["시험 포인트","WHERE 절 없는 UPDATE·DELETE가 어떤 결과를 초래하는지 설명할 수 있는가? 실습 중\nUPDATE나 DELETE를 작성할 때마다 먼저 동일한 조건의 SELECT로 영향받을 행을 확인하는 습관이 있는\n가? 이 습관이 몸에 배어 있어야 실기 시험에서 치명적인 실수를 예방할 수 있다."],["설명","SELECT 절 순서와 함수 점검\nSELECT-FROM-WHERE-GROUP BY-HAVING-ORDER BY의 순서를 정확히 기억하는가? WHERE와\nHAVING의 차이를 설명할 수 있는가? COUNT(*)와 COUNT(컬럼명)의 차이를 NULL과 연결지어 설명할수 있는가? 이 항목들을 스스로 점검해 본다."]]}]},{"t":"(2) 조인·서브쿼리 자가 점검 항목","c":[{"t":"① 조인 유형·카티션 곱·UNION 점검","n":[["설명","조인 유형 구분 점검 INNER JOIN과 LEFT/RIGHT/FULL OUTER JOIN의 결과 차이를 그림으로 그려 설명할 수 있는가? 카티션 곱이 발생하는 상황과 그 원인(조인 조건 누락)을 설명할 수 있는가? 단일 행과 다중 행 서브쿼리에 사용할수 있는 연산자를 각각 나열할 수 있는가? UNION과 UNION ALL의 차이(중복 제거 여부)를 설명할 수 있는가? MINUS(또는 EXCEPT) 연산의 결과가 어느 쪽 기준인지(앞 쿼리 기준) 정확히 알고 있는가? 이 항목들까지 자신 있게 답할 수 있다면 SQL 실기 준비가 충분히 되어 있는 상태이다."]]},{"t":"② GRANT·REVOKE 권한 점검","n":[["시험 포인트","GRANT의 TO와 REVOKE의 FROM을 혼동하지 않고 사용할 수 있는가? 시스템 권한과 객체 권한의 차이(ON 객체명의 유무)를 설명할 수 있는가? DAC와 MAC의 통제 권한 소재 차이를 설명할 수 있는가?"],["실제 사례","COMMIT 이후에는 ROLLBACK이 불가능하다는 점을 알고 있는가? 자동 커밋 모드의 위험성을 이해하고 있는가? 이 모든 자가 점검 항목에 자신 있게 답할 수 있다면, SQL 실무 능력을 평가하는 실기 시험의 작업형 문제에 충분히 대비된 상태라고 볼 수 있다."],["설명","권한 부여·회수 점검"]]}]}]}]},{"t":"Ⅲ 실기 시험 D-Day 최종 요약","c":[{"t":"1. 시험 당일 준비물과 마음가짐","c":[{"t":"(1) 시험 당일 확인 사항","c":[{"t":"① 준비물·도착 시간 확인","n":[["시험 포인트","신분증, 수험표 등 필수 준비물을 전날 미리 챙겨두고, 고사장의 컴퓨터 환경(운영체제, SQL 클라이언트 도구, 편집기)이 평소 연습하던 환경과 다를 수 있으므로 시험 시작 전 안내되는 사용법을 주의 깊게 확인해야 한다."],["시험 포인트","시험 시작 직후 전체 문제를 먼저 훑어보며 난이도를 파악하고, 확실히 풀 수 있는 문제부터 시작하여 초반에 긴장을 풀고 자신감을 확보하는 것이 좋다. 남은 시간을 문제 수로 나누어 문제당 대략적인 목표 시간을 정해두면 특정 문제에 매몰되는 것을 방지할 수 있다."],["설명","준비물과 도착 시간 확인"]]},{"t":"② 제출 전 전체 SQL 재실행 확인","n":[["시험 포인트","각 문제의 지문을 다시 한 번 읽으며 \"오름차순인지 내림차순인지\", \"이상인지 초과인지\", \"몇 개컬럼을 조회하라고 했는지\"와 같은 세부 요구사항을 놓치지 않았는지 최종적으로 대조하는 습관이 실기 시험에서 사소한 감점을 막는 마지막 안전장치가 된다."],["설명","모든 문제의 실행 여부 확인 제출 직전, 작성한 모든 SQL 문을 처음부터 다시 한 번 순서대로 실행해 보아 이전 단계의 테이블 변경 (DROP, ALTER 등)이 이후 문제의 실행에 영향을 주지 않았는지 확인해야 한다. 특히 이전 문제에서 테이블을 삭제했다면 이후 문제에서 그 테이블을 사용하는 SQL이 오류를 일으킬 수 있다."]]}]},{"t":"(2) 반복 타이핑과 실습 습관","c":[{"t":"① 손 타이핑 반복 연습","n":[["시험 포인트","눈으로 SQL 문법을 읽고 이해하는 것과, 직접 키보드로 타이핑하여 오류 없이 실행시키는 것은 전혀 다른 능력이다. 매일 일정 시간을 정해 CREATE TABLE부터 조인, 서브쿼리까지 손으로 직접 작성하고 실행해 보는 반복 연습이 실기 시험 합격의 가장 확실한 지름길이다."],["시험 포인트","연습 중 자주 틀리는 문법(REFERENCES 철자, HAVING과 WHERE 혼동 등)을 별도로 기록해 두고 주기적으로 다시 살펴보는 오답 노트 방식이 효과적이다. 취약한 유형을 파악해 그 부분만 집중적으로 반복 연습하면 학습 효율을 높일 수 있다."],["설명","손으로 직접 타이핑하는 연습의 중요성"]]},{"t":"② MySQL·MariaDB·Post greSQL 실습","n":[["시험 포인트","실제 시험과 유사한 제한 시간을 정해두고 이 정리서의 모의고사 문제집(Ⅰ, Ⅱ, Ⅲ) 문제들을 시간 안에 풀어보는 연습을 반복하면, 실제 시험장에서의 시간 압박감에 대한 적응력을 기를 수 있다."],["설명","무료 DBMS를 이용한 실습 환경 마련 MySQL, MariaDB, PostgreSQL 등 무료로 설치할 수 있는 DBMS를 개인 컴퓨터에 설치하고, 학생·부서· 주문과 같은 예제 테이블을 직접 만들어 이 정리서에 수록된 예제와 모의 문제를 하나씩 직접 실행해 보는 것이 가장 실전에 가까운 연습 방법이다."]]}]}]}]},{"t":"Ⅳ SQL 실기 대비 용어 사전","c":[{"t":"1. 자주 혼동되는 용어 비교","c":[{"t":"(1) 구조 관련 용어 비교","c":[{"t":"① 스키마 vs 인스턴스","n":[["실제 사례","스키마(Schema)는 데이터베이스의 구조와 제약조건에 관한 명세로 시간에 따라 잘 변하지 않는 데이터베이스의 정적인 특성을 나타내는 반면, 인스턴스(Instance)는 특정 시점에 데이터베이스에 실제로 저장된 데이터의 값으로 계속 변화하는 데이터베이스의 상태를 의미한다. 실기 시험에서 CREATE TABLE로 만드는 것은 스키마이고, 그 안에 INSERT로 채워지는 것은 인스턴스라고 구분하여 이해하면 혼동이 줄어든다."],["쉬운 예","후보키(Candidate Key)는 유일성과 최소성을 만족하여 기본 키가 될 수 있는 자격을 갖춘 모든 키를 의미하며, 이 중 기본 키로 선택되지 않은 나머지 후보키를 대체키(Alternate Key)라고 한다. 예를 들어 student 테이블에 student_id와 email이 모두 유일성을 가진다면 둘 다 후보키이며, student_id를 기본 키로 선택했다면 email은 대체키가 된다."],["설명","스키마 vs 인스턴스"]]},{"t":"② 프로시저 vs 함수","n":[["시험 포인트","프로시저(Procedure)는 특정 작업을 수행하는 일련의 SQL 문 묶음으로 반환값이 없거나 여러 개의 출력 매개변수를 가질 수 있는 반면, 함수(Function)는 반드시 하나의 반환값을 가지며 주로 SELECT 문내부에서 값처럼 호출되어 사용된다는 차이가 있다. 실기 시험에서는 이 둘의 상세한 구현보다 개념적 차이를 묻는 문제가 나올 수 있다."],["실제 사례","정적 SQL은 프로그램 작성 시점에 SQL 문의 구조가 이미 확정되어 있는 형태이고, 동적 SQL은 프로그램 실행 중에 조건에 따라 SQL 문의 내용(테이블명, 조건절 등)이 그때그때 조합되어 만들어지는 형태이다. 실무에서는 사용자의 검색 조건에 따라 WHERE 절이 유동적으로 구성되는 경우 동적 SQL을 활용한다."],["설명","프로시저 vs 함수(개념 구분)"]]}]},{"t":"(2) 언어 계열 약어 정리","c":[{"t":"① DDL·DML·DCL·TCL 정식 명칭","n":[["설명","DDL·DML·DCL·TCL의 정식 명칭 DDL은 Data Definition Language(데이터 정의어), DML은 Data Manipulation Language(데이터 조작어), DCL은 Data Control Language(데이터 제어어), TCL은 Transaction Control Language(트랜 잭션 제어어)의 약어이다. 각 약어가 무엇의 줄임말인지 정확히 알고 있으면, 처음 보는 낯선 문제도 이름의 의미로부터 어떤 종류의 명령인지 유추할 수 있다. DAC는 Discretionary Access Control(임의 접근 통제), MAC은 Mandatory Access Control(강제 접근 통제)의 약어이다. Discretionary(임의적인)와 Mandatory(의무적인, 강제적인)라는 원어의 의미를 함께 기억하면, 통제 권한이 주체에게 있는지(임의적) 제3자에게 있는지(강제적)를 헷갈리지 않고 구분할 수 있다."]]},{"t":"② 제약조건 영어 키워드","n":[["시험 포인트","PRIMARY KEY(기본 키), FOREIGN KEY(외래 키), UNIQUE(고유, 유일), NOT NULL(널 값아님), CHECK(검사, 조건 확인), CONSTRAINT(제약, 제약조건), REFERENCES(참조하다) 등 제약조건과 관련된 영어 단어의 원래 의미를 함께 알아두면 철자를 암기하기가 한결 수월해진다."],["설명","제약조건 관련 영어 키워드"]]}]}]}]}]}],"k":"실기 Part04"},{"n":9,"t":"실전 디버깅 연습문제집","c":[{"t":"제1절 C언어 코드 구현과 디버깅 실무","c":[{"t":"Ⅰ C언어 기본 구조와 입출력","c":[{"t":"1. C언어 프로그램의 기본 구조","c":[{"t":"(1) 기본 골격과 컴파일 과정","c":[{"t":"① C 기본 골격 main·retur n 0","n":[["시험 포인트","모든 C 프로그램은 반드시 main 함수를 하나 포함해야 하며, 프로그램 실행은 이 main 함수에서 시작된다. #include 지시문은 printf와 같은 표준 라이브러리 함수를 사용하기 위해 필요한 헤더 파일을 포함시키는 역할을 한다. 실기 시험에서는 이 기본 골격을 그대로 사용하되, main 함수 내부에 요구사항에 맞는 로직을 채워 넣는 형태의 문제가 자주 출제된다."],["시험 포인트","작업형 시험장의 IDE에서는 소스 코드를 작성한 뒤 컴파일(Build) 버튼을 눌러 오류가 없는지 확인하고, 실행(Run) 버튼을 눌러 실제 출력 결과가 문제에서 요구하는 값과 일치하는지 검증하는 순서로 작업을 진행한다. 컴파일 단계에서 오류가 발생하면 오류 메시지에 표시된 줄 번호를 먼저 확인하는 습관을 들여야 한다."],["설명","C 프로그램의 기본 골격\n#include <stdio.h>\nint main(void) {\n     printf(\"Hello, World!\\n\");\n     return 0;\n}"]]},{"t":"② C 기본 자료형 int, float, double, char","n":[["시험 포인트","int는 정수형, float와 double은 실수형, char는 문자 하나를 저장하는 자료형이다. 실기 시험에서는 정수 나눗셈과 실수 나눗셈의 결과가 다르게 나오는 문제(예: 정수형 변수끼리 나눗셈을 하면 소수점 이하가 버려짐)가 자주 함정으로 출제되므로 자료형에 따른 연산 결과의 차이를 정확히 이해하고 있어야 한다.\nint x = 7, y = 2;\ndouble result = (double)x / y;"],["설명","기본 자료형\nint a = 10;\nfloat b = 3.14f;\ndouble c = 3.141592;\nchar d = 'A';"]]}]},{"t":"(2) printf와 서식 지정자","c":[{"t":"① 서식 지정자 %d·%f·%c·%s ·%lf","n":[["시험 포인트","서식 지정자와 변수의 자료형이 일치하지 않으면 컴파일 오류는 발생하지 않지만 실행 시 엉뚱한 값이 출력되는 대표적인 실전 버그이다. 실기 시험에서 출력 결과가 이상하게 나온다면 가장 먼저 printf의 서식 지정자와 변수 자료형의 일치 여부를 점검해야 한다."],["설명","주요 서식 지정자 %d(정수), %f(실수), %c(문자), %s(문자열), %lf(double 실수)와 같은 서식 지정자를 정확히 구분하여 사용해야 한다. double 자료형을 scanf로 입력받을 때는 %lf를 사용해야 하지만, printf로 출력할 때는 %f와 %lf 모두 사용 가능하다는 점도 함께 기억해야 한다.\ndouble price = 1500.5;\nprintf(\"%d\\n\", price);   // 오류: %d와 double 불일치\nprintf(\"%.1f\\n\", price); // 정상: 1500.5"]]},{"t":"② scanf 입력 시 & 주소 연산자","n":[["시험 포인트","scanf 함수는 변수의 값을 직접 변경해야 하므로 반드시 변수 앞에 주소 연산자 &를 붙여야 한다. 실기 시험에서 &를 빠뜨려 입력값이 제대로 반영되지 않는 실수가 매우 빈번하게 발생하므로, scanf 코드를 작성할 때마다 &의 유무를 습관적으로 확인해야 한다.\nchar name[20];\nscanf(\"%s\", name);   // 배열명은 그 자체로 주소이므로 &를 붙이지 않음"],["시험 포인트","문자 배열은 배열명 자체가 첫 번째 원소의 주소를 의미하므로, scanf로 문자열을 입력받을 때는 &를 붙이지 않는다. 정수형 변수에는 &를 붙이고 문자 배열에는 붙이지 않는 이 차이를 혼동하는 실수가 실기시험에서 자주 발생하는 디버깅 포인트이다."],["설명","scanf의 기본 사용법\nint num;\nscanf(\"%d\", &num);"]]}]}]}]},{"t":"Ⅱ 제어문(조건문과 반복문) 구현과 디버깅","c":[{"t":"1. 조건문의 구현","c":[{"t":"(1) if-else 문","c":[{"t":"① if-else if-else 학점 분기","n":[["쉬운 예","if-else if-else 구조에서는 조건이 순서대로 평가되므로, 조건의 순서를 잘못 배치하면 의도하지 않은 결과가 나올 수 있다. 예를 들어 score >= 80을 먼저 검사하면 90점 이상인 경우도 모두 B로 분류되는 오류가 발생하므로, 조건은 반드시 더 좁은 범위(또는 더 큰 값)부터 검사하도록 순서를 설계해야 한다.\nint x = 5;"],["시험 포인트","조건문에서 비교 연산자 ==을 써야 할 자리에 대입 연산자 =를 실수로 사용하는 것은 C언어에서 가장 대표적인 버그 유형 중 하나이다. 대입 연산자를 사용하면 컴파일 오류 없이 조건이 항상 참으로 처리되어, 의도한 로직과 다른 결과가 출력되므로 실기 시험에서 반드시 점검해야 하는 항목이다."],["설명","기본 조건문 구조\nint score = 85;\nif (score >= 90) {\n    printf(\"A\\n\");\n} else if (score >= 80) {\n    printf(\"B\\n\");\n} else {\n    printf(\"C\\n\");\n}"]]},{"t":"② switch문 case별 break","n":[["시험 포인트","switch 문의 각 case 뒤에는 break 문을 반드시 작성해야 하며, break가 없으면 조건에 맞는 case 이후의 모든 case가 연속으로 실행되는 폴스루(Fall-through) 현상이 발생한다. 실기 문제에서 switch 문의 일부 case에 break가 누락된 코드를 제시하고 이를 찾아 수정하도록 요구하는 유형이 자주 출제된다.\nint grade = 2;\nswitch (grade) {"],["실제 사례","위 코드는 grade가 2일 때 case 2의 break가 없어 case 3까지 실행되어 \"보통미흡\"이 함께 출력된다. 이러한 결함은 실행은 되지만 결과가 잘못 나오는 논리적 오류(Logic Error)에 해당하며, 컴파일 오류로는 잡히지 않으므로 실제 실행 결과를 눈으로 반드시 확인하는 습관이 중요하다."],["설명","switch 문의 구조와 break\nint day = 3;\nswitch (day) {\n    case 1: printf(\"월요일\\n\"); break;\n    case 2: printf(\"화요일\\n\"); break;\n    case 3: printf(\"수요일\\n\"); break;\n    default: printf(\"범위 밖\\n\");\n}"]]}]},{"t":"(2) for문과 while문","c":[{"t":"① for문 1~10 합계 55","n":[["시험 포인트","반복문 내부에서 조건에 사용된 변수를 변화시키는 증감식을 빠뜨리면 무한 루프에 빠지게 된다. 실기 시험 도중 프로그램이 멈추지 않고 계속 실행된다면 반복문 내부에 조건 변수의 증감 코드가 누락되지 않았는지 가장 먼저 확인해야 한다."],["설명","for문의 기본 구조\nint sum = 0;\nfor (int i = 1; i <= 10; i++) {\n      sum += i;\n}\nprintf(\"%d\\n\", sum);       // 55\n    for문은 초기식, 조건식, 증감식을 한 줄에 명시하여 반복 횟수가 명확한 경우에 주로 사용된다. 조건식을 <=\n    가 아닌 <로 잘못 작성하면 마지막 값이 누락되는 경계값 오류가 발생하므로, 반복 범위의 시작과 끝을 정확\n    히 검토해야 한다.\nint i = 0;\nwhile (i < 5) {\n      printf(\"%d\\n\", i);\n      // i++; 증감식 누락 -> 무한 루프 발생\n}"]]},{"t":"② 중첩 for문 별 찍기","n":[["시험 포인트","중첩 반복문은 바깥쪽 반복문의 변수(i)와 안쪽 반복문의 변수(j)를 혼동하기 쉬우므로, 각 반복문이 담당하는 역할(행의 반복, 열의 반복)을 명확히 구분하여 코드를 작성해야 한다. 실기 시험에서 도형 출력 문제는 중첩 반복문의 이해도를 확인하는 대표적인 유형이다."],["시험 포인트","break는 반복문을 즉시 종료시키는 반면, continue는 현재 반복만 건너뛰고 다음 반복으로 넘어 간다. 두 키워드를 혼동하여 사용하면 의도한 것과 전혀 다른 반복 횟수와 결과가 나오므로, 문제에서 요구하는 것이 \"반복을 완전히 멈추는 것\"인지 \"특정 조건만 건너뛰는 것\"인지를 정확히 구분해서 적용해야 한다."],["설명","중첩 반복문(별 찍기 예제)\nfor (int i = 1; i <= 5; i++) {\n      for (int j = 1; j <= i; j++) {\n          printf(\"*\");\n      }\n      printf(\"\\n\");\n}"]]}]}]}]},{"t":"Ⅲ 배열과 문자열 처리","c":[{"t":"1. 1차원 배열과 2차원 배열","c":[{"t":"(1) 1차원 배열의 선언과 활용","c":[{"t":"① 1차원 배열 선언·초기화","n":[["시험 포인트","C언어 배열의 인덱스는 0부터 시작하므로, arr[5]로 선언한 배열의 유효한 인덱스는 0부터 4까 지이다. 반복문의 조건을 i <= 5로 잘못 작성하면 배열의 범위를 벗어난 메모리에 접근하는 배열 범위 초과 (Out of Bounds) 오류가 발생하므로 반복 조건의 경계값을 항상 주의 깊게 확인해야 한다.\nint arr[5] = {1, 2, 3, 4, 5};"],["설명","배열의 선언과 초기화\nint arr[5] = {10, 20, 30, 40, 50};\nfor (int i = 0; i < 5; i++) {\n      printf(\"%d \", arr[i]);\n}"]]},{"t":"② 2차원 배열 matrix[2][3 ] 접근","n":[["시험 포인트","2차원 배열은 행(row)과 열(column) 두 개의 인덱스로 원소에 접근하며, 중첩 반복문을 이용해 순회하는 것이 일반적이다. 행과 열의 반복 범위를 서로 바꿔서 사용하는 실수(matrix[j][i]를 matrix[i][j] 대신 사용하는 등)가 실기 시험에서 흔한 오류로 출제된다.\nint sum = 0;\nfor (int i = 0; i < 2; i++)"],["시험 포인트","2차원 배열의 모든 원소 합을 구하는 문제는 실기 시험에서 자주 출제되는 유형으로, 중첩 반복문의 각 인덱스 범위(행의 개수, 열의 개수)를 배열 선언 크기와 정확히 일치시키는 것이 핵심이다."],["설명","2차원 배열의 선언과 접근\nint matrix[2][3] = {{1, 2, 3}, {4, 5, 6}};\nfor (int i = 0; i < 2; i++) {\n     for (int j = 0; j < 3; j++) {\n         printf(\"%d \", matrix[i][j]);\n     }\n     printf(\"\\n\");\n}"]]}]},{"t":"(2) 문자열의 선언과 표준 함수","c":[{"t":"① 문자열 끝 널 문자 \\0","n":[["시험 포인트","strlen(길이 계산), strcpy(복사), strcat(연결), strcmp(비교)는 실기 시험에서 가장 자주 사용되는 문자열 표준 함수이다. strcmp는 두 문자열이 같으면 0을, 다르면 0이 아닌 값을 반환한다는 점을 정확히 기억해야 하며, 이를 if(strcmp(a,b))와 같이 잘못 사용하면 조건의 참/거짓이 반대로 해석되는 오류가 발생한다."],["설명","문자열의 선언 방식\nchar str1[20] = \"Hello\";\nchar str2[] = \"World\";\n    C언어에서 문자열은 문자 배열의 끝에 널 문자(\\0)가 자동으로 추가되는 형태로 저장된다. 배열 크기를 지정\n    할 때는 저장할 문자열의 길이보다 최소 1자 이상 크게 잡아 널 문자가 들어갈 공간을 확보해야 한다.\n#include <string.h>\nchar a[20] = \"Hello\";\nchar b[20] = \"World\";\nstrcat(a, b);            // a = \"HelloWorld\"\nprintf(\"%d\\n\", strlen(a));    // 10\nprintf(\"%d\\n\", strcmp(a, b)); // 0이 아닌 값(다름)"]]},{"t":"② strcmp 일치 시 0 반환","n":[["설명","strcmp 조건문 오용 사례\nchar pw[20] = \"1234\";\nif (strcmp(pw, \"1234\")) {    // 오류: 값이 같아도 0이 반환되어 거짓 처리\n      printf(\"비밀번호 일치\\n\");\n}\n// 올바른 코드\nif (strcmp(pw, \"1234\") == 0) {\n      printf(\"비밀번호 일치\\n\");\n}\n    strcmp는 문자열이 일치할 때 0(거짓으로 해석됨)을 반환하므로, if(strcmp(...))처럼 그대로 조건에 사용하\n    면 \"일치하지 않을 때\" 참이 되는 정반대의 로직이 되어버린다. 반드시 strcmp의 반환값을 0과 명시적으로\n    비교하는 코드로 작성해야 한다.\nchar small[5];\nstrcpy(small, \"Hello World\"); // 오류: 배열 크기(5)보다 긴 문자열 복사\n    문자 배열의 크기보다 긴 문자열을 strcpy로 복사하면 버퍼 오버플로우(Buffer Overflow)가 발생하여 프로\n    그램이 비정상 종료되거나 예측할 수 없는 동작을 일으킬 수 있다. 문자열을 다루는 배열을 선언할 때는 항상\n    저장할 최대 문자열의 길이를 여유 있게 고려해야 한다."]]}]}]}]},{"t":"Ⅳ 함수와 포인터","c":[{"t":"1. 함수의 정의와 호출","c":[{"t":"(1) 함수의 기본 구조","c":[{"t":"① 함수 add(3,5) 결과 8","n":[["시험 포인트","함수는 반환형, 함수명, 매개변수 목록으로 구성되며, main 함수보다 뒤에 정의된 함수를 사용하려면 미리 함수 원형(프로토타입)을 선언해 두거나 함수를 main보다 앞에 정의해야 한다. 실기 시험에서 함수 원형 선언 누락으로 인한 컴파일 오류가 자주 발생하므로, 여러 함수를 사용하는 문제에서는 이 순서를 반드시 점검해야 한다.\nvoid increase(int x) {"],["실제 사례","C언어의 함수는 기본적으로 값에 의한 호출 방식을 사용하므로, 함수 내부에서 매개변수의 값을 변경해도 호출한 쪽의 원본 변수에는 영향을 주지 않는다. 함수를 통해 원본 값을 실제로 변경하고 싶다면 포인터를 활용한 참조에 의한 호출 방식을 사용해야 한다."],["설명","함수 선언과 정의\nint add(int a, int b) {\n     return a + b;\n}\nint main(void) {\n     int result = add(3, 5);\n     printf(\"%d\\n\", result);    // 8\n     return 0;\n}"]]},{"t":"② 재귀 팩토리얼 종료 조건","n":[["실제 사례","위 코드는 종료 조건이 없어 n이 계속 감소하면서 함수 호출이 끝없이 반복되어 결국 스택 오버플로 우가 발생한다. 실기 시험에서 재귀 함수 문제가 출제되면 가장 먼저 if문으로 구성된 종료 조건이 존재하는지, 그리고 그 조건이 실제로 도달 가능한 값인지를 확인해야 한다."],["설명","재귀 함수의 개념(팩토리얼 예제)\nint factorial(int n) {\n     if (n <= 1) return 1;     // 종료 조건\n     return n * factorial(n - 1);\n}\n    재귀 함수는 자기 자신을 다시 호출하는 함수로, 반드시 재귀 호출을 멈추는 종료 조건(Base Case)이 있어\n    야 한다. 종료 조건을 빠뜨리면 함수 호출이 무한히 반복되어 스택 오버플로우(Stack Overflow)로 프로그램\n    이 비정상 종료되므로, 재귀 함수를 작성할 때는 종료 조건을 가장 먼저 확인해야 한다.\nint factorial(int n) {\n     return n * factorial(n - 1);      // 오류: 종료 조건 없음\n}"]]}]},{"t":"(2) 포인터의 기본 개념","c":[{"t":"① 포인터 &주소·*역참조","n":[["시험 포인트","함수의 매개변수를 포인터로 선언하면 호출 시 변수의 주소를 전달하여, 함수 내부에서 원본 변수의 값을 직접 변경할 수 있게 된다. 실기 시험에서 두 변수의 값을 교환(swap)하는 함수를 작성하는 문제는 참조에 의한 호출의 이해도를 확인하는 대표적인 유형이다."],["설명","포인터 선언과 역참조\nint num = 10;\nint *ptr = &num;\nprintf(\"%d\\n\", *ptr);     // 10 (num의 값)\nprintf(\"%p\\n\", ptr);      // num의 주소\n*ptr = 20;\nprintf(\"%d\\n\", num);      // 20으로 변경됨\n    포인터는 변수의 주소를 저장하는 변수이며, *ptr과 같이 역참조 연산자를 사용하면 그 주소에 저장된 값에\n    접근하거나 값을 변경할 수 있다. 포인터를 통해 값을 변경하면 원본 변수의 값도 함께 변경된다는 점이 값에\n    의한 호출과 근본적으로 다른 부분이다.\nvoid increase(int *x) {\n     *x = *x + 1;\n}\nint main(void) {\n     int num = 5;\n     increase(&num);\n     printf(\"%d\\n\", num);   // 6 (변경됨)\n     return 0;\n}"]]},{"t":"② 널 포인터 역참조 오류","n":[["설명","널 포인터 역참조 오류\nint *ptr = NULL;\nprintf(\"%d\\n\", *ptr);     // 오류: 널 포인터 역참조, 프로그램 비정상 종료\n    포인터가 유효한 주소를 가리키지 않은 상태(NULL이거나 초기화되지 않은 상태)에서 역참조를 시도하면 프\n    로그램이 강제 종료된다. 포인터를 사용하기 전에는 반드시 유효한 변수의 주소로 초기화되어 있는지를 확인\n    하는 습관이 중요하다.\nvoid increase(int *x) { *x += 1; }\nint main(void) {\n     int num = 5;\n     increase(num);   // 오류: &을 붙이지 않아 주소가 아닌 값 전달\n     return 0;\n}\n    포인터를 매개변수로 받는 함수를 호출할 때 인자에 &를 붙이지 않으면, 정수값이 주소로 잘못 해석되어 컴파\n    일 오류 또는 프로그램 비정상 종료로 이어진다. 함수 원형에 포인터 매개변수(int *)가 있다면 호출부에서도\n    반드시 & 연산자를 사용해 주소를 전달해야 한다."]]}]}]}]},{"t":"Ⅴ 구조체와 동적 메모리 할당","c":[{"t":"1. 구조체(Structure)의 활용","c":[{"t":"(1) 구조체의 정의와 사용","c":[{"t":"① struct 선언·점(.) 멤버 접근","n":[["설명","구조체 선언과 멤버 접근\nstruct Student {\n     char name[20];\n     int score;\n};\nint main(void) {\n     struct Student s1 = {\"Kim\", 90};\n     printf(\"%s %d\\n\", s1.name, s1.score);\n     return 0;\n}\n    구조체는 서로 다른 자료형의 데이터를 하나로 묶어 관리할 수 있게 해주는 사용자 정의 자료형이다. 구조체\n    변수의 멤버에 접근할 때는 점(.) 연산자를 사용하며, 학생 정보나 직원 정보와 같이 여러 속성을 함께 다루는\n    실기 문제에서 자주 활용된다.\nstruct Student list[3] = {\n     {\"Kim\", 90}, {\"Lee\", 85}, {\"Park\", 95}\n};\nfor (int i = 0; i < 3; i++) {\n     printf(\"%s: %d\\n\", list[i].name, list[i].score);\n}\n    구조체 배열을 사용하면 여러 명의 학생 정보와 같이 동일한 형태의 데이터를 여러 건 다룰 수 있다. 배열 원\n    소의 멤버에 접근할 때는 list[i].score와 같이 인덱스와 점 연산자를 함께 사용한다는 점을 정확히 기억해야\n    한다."]]},{"t":"② 구조체 포인터 -> 연산자","n":[["실제 사례","구조체를 가리키는 포인터를 통해 멤버에 접근할 때는 점 연산자 대신 화살표 연산자(->)를 사용한다. (*p).name과 p->name은 완전히 동일한 의미이지만, 화살표 연산자가 가독성이 더 좋아 실무에서 널리 사용된다.\nvoid changeScore(struct Student s) {"],["실제 사례","구조체를 함수의 매개변수로 값 자체를 전달하면 원본 변수의 복사본이 함수에 전달되므로 함수 내부에서 값을 변경해도 원본에는 영향을 주지 않는다. 원본 구조체의 값을 실제로 변경하고 싶다면 반드시 구조체 포인터를 매개변수로 사용해야 한다."],["설명","구조체 포인터와 화살표 연산자\nstruct Student s1 = {\"Kim\", 90};\nstruct Student *p = &s1;\nprintf(\"%s\\n\", p->name);   // 화살표 연산자 사용\nprintf(\"%s\\n\", (*p).name); // 위와 동일한 의미"]]}]},{"t":"(2) malloc과 free","c":[{"t":"① malloc 할당·NULL 검사·free","n":[["시험 포인트","malloc으로 할당한 메모리는 사용이 끝난 후 반드시 free 함수로 해제해야 하며, 이를 누락하면 프로그램이 실행되는 동안 사용하지 않는 메모리가 계속 쌓이는 메모리 누수가 발생한다. 실기 시험에서 동적 할당 문제가 출제되면 free 호출 여부를 마지막에 반드시 점검해야 한다."],["설명","동적 메모리 할당의 기본\n#include <stdlib.h>\nint *arr = (int *)malloc(5 * sizeof(int));\nif (arr == NULL) {\n     printf(\"메모리 할당 실패\\n\");\n     return 1;\n}\nfor (int i = 0; i < 5; i++) arr[i] = i * 10;\nfree(arr);\n    malloc 함수는 힙(Heap) 영역에 지정된 크기만큼의 메모리를 동적으로 할당하고 그 시작 주소를 반환한다.\n    메모리 할당에 실패하면 NULL을 반환하므로, malloc 사용 직후에는 반드시 NULL 여부를 확인하는 방어적\n    코드를 작성하는 것이 안전하다.\nint *arr = (int *)malloc(5 * sizeof(int));\n// arr 사용 후 free(arr)를 호출하지 않음 -> 메모리 누수"]]},{"t":"② Dangling Pointer 해제 후 접근","n":[["설명","해제된 메모리 재사용(Dangling Pointer)\nint *p = (int *)malloc(sizeof(int));\n*p = 10;\nfree(p);\nprintf(\"%d\\n\", *p);        // 오류: 이미 해제된 메모리 접근\n    free로 해제한 메모리를 다시 사용하려고 하면 예측할 수 없는 값이 출력되거나 프로그램이 비정상적으로 종\n    료될 수 있다. 이러한 포인터를 댕글링 포인터(Dangling Pointer)라고 하며, free 호출 이후에는 해당 포인\n    터를 다시 사용하지 않거나 NULL로 초기화해 두는 것이 안전한 습관이다.\nint *arr = (int *)malloc(5 * sizeof(arr));      // 오류: sizeof(arr)는 포인터 크기\n// 올바른 코드\nint *arr2 = (int *)malloc(5 * sizeof(int));     // sizeof(int)로 정확한 크기 계산\n    malloc의 크기를 계산할 때 sizeof(arr)처럼 포인터 변수 자체의 크기를 사용하면 의도한 만큼의 메모리가\n    할당되지 않는다. 반드시 sizeof(int)와 같이 저장하려는 자료형의 크기를 기준으로 계산해야 하며, 배열 원\n    소 개수와 자료형 크기를 정확히 곱하는 습관을 들여야 한다."]]}]}]}]},{"t":"Ⅵ 자주 발생하는 디버깅 유형 종합","c":[{"t":"1. 컴파일 오류(Syntax Error) 유형","c":[{"t":"(1) 기호 누락 오류","c":[{"t":"① 세미콜론·중괄호 누락","n":[["실제 사례","세미콜론이나 중괄호와 같은 기본 문법 요소를 누락하는 것은 초보자가 가장 흔히 저지르는 실수이다. 컴파일러가 오류 메시지에서 지적하는 줄 번호는 실제 오류가 발생한 줄보다 한두 줄 아래에 표시되는 경우가 많으므로, 오류가 보고된 줄의 바로 윗줄도 함께 확인하는 습관이 필요하다."],["설명","세미콜론과 중괄호 누락\nint main(void) {\n      int a = 10   // 오류: 세미콜론 누락\n      printf(\"%d\\n\", a);\n      return 0;\n}"]]},{"t":"② 변수 미선언·중복 선언","n":[["설명","변수 선언 누락과 중복 선언\nint main(void) {\n      total = 0;   // 오류: 변수 선언 없이 사용\n      int total;   // 중복 선언 위치도 잘못됨\n      return 0;\n}\n    C언어에서는 변수를 사용하기 전에 반드시 자료형과 함께 선언해야 하며, 동일한 이름의 변수를 같은 범위 내\n    에서 중복 선언할 수 없다. \"undeclared\" 또는 \"redefinition\"과 같은 오류 메시지가 나타나면 변수 선언의\n    위치와 중복 여부를 점검해야 한다.\n    C언어는 대소문자를 구분하는 언어이므로 Total과 total은 서로 다른 변수로 인식된다. 변수명이나 함수명\n    을 다른 곳에서 참조할 때 대소문자를 실수로 다르게 입력하면 \"undeclared identifier\"와 같은 오류가 발생\n    하므로, 이름을 정확히 일치시켜 사용해야 한다."]]}]},{"t":"(2) 런타임 오류(Runtime Error)","c":[{"t":"① 0으로 나누기 런타임 오류","n":[["설명","0으로 나누기 오류\nint a = 10, b = 0;\nprintf(\"%d\\n\", a / b);    // 오류: 0으로 나눔, 프로그램 비정상 종료\n    정수를 0으로 나누는 연산은 정의되지 않은 동작으로, 실행 중 프로그램이 강제 종료되는 대표적인 런타임 오\n    류이다. 사용자로부터 나누는 값을 입력받는 프로그램에서는 나누기 전에 그 값이 0인지 확인하는 방어 코드\n    를 추가하는 것이 안전하다.\n    앞서 다룬 배열 범위 초과 오류 역시 대표적인 런타임 오류이다. 컴파일은 정상적으로 되지만 실행 시점에 예\n    측할 수 없는 값이 출력되거나 프로그램이 비정상 종료되므로, 배열을 다루는 모든 반복문에서는 인덱스의 유\n    효 범위를 재차 확인하는 습관이 필수적이다."]]},{"t":"② C 논리 오류 특징","n":[["시험 포인트","논리 오류는 컴파일도 정상적으로 되고 프로그램도 오류 없이 실행되지만, 출력되는 결과가 요구사항과 다른 경우를 의미한다. 앞서 다룬 switch문의 break 누락, 조건문의 순서 오류, 반복 범위의 경계값 오류 등이 모두 논리 오류에 해당하며, 실기 시험에서 가장 많은 배점을 차지하는 디버깅 유형이다."],["실제 사례","논리 오류를 찾기 위해서는 코드를 눈으로만 읽기보다, 문제에서 요구하는 예상 출력값과 실제 출력 값을 직접 비교하고, 중간중간 printf 문을 추가하여 변수의 값이 예상대로 변화하는지 단계별로 추적하는 것이 효과적이다. 시험 환경에서는 디버거의 중단점(Breakpoint) 기능을 활용하여 변수 값의 변화를 직접 관찰하는 것도 좋은 전략이다."],["설명","논리 오류의 특징"]]}]}]}]},{"t":"Ⅶ C언어 실전 예제 모음","c":[{"t":"1. 배열 활용 실전 예제","c":[{"t":"(1) 배열 정렬과 탐색","c":[{"t":"① 버블 정렬 인접 원소 교환","n":[["시험 포인트","버블 정렬은 인접한 두 원소를 비교하여 순서가 잘못되어 있으면 교환하는 과정을 배열 전체에 반복하는 정렬 알고리즘이다. 실기 시험에서는 정렬 알고리즘을 완성된 형태로 암기하기보다, 이중 반복문의 비교 조건과 교환(swap) 로직의 순서를 정확히 이해하고 있는지를 확인하는 문제가 주로 출제된다.\nint binarySearch(int arr[], int n, int target) {"],["시험 포인트","이진 탐색은 정렬된 배열에서 중간값과 목표값을 비교하여 탐색 범위를 절반씩 줄여나가는 효율적인 탐색 알고리즘이다. 이진 탐색은 반드시 정렬된 배열을 전제로 하므로, 정렬되지 않은 배열에 그대로 적용하면 올바른 결과를 얻을 수 없다는 점을 실기 시험에서 반드시 기억해야 한다."],["설명","버블 정렬(Bubble Sort) 구현\nvoid bubbleSort(int arr[], int n) {\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - i - 1; j++) {\n            if (arr[j] > arr[j + 1]) {\n                int temp = arr[j];\n                arr[j] = arr[j + 1];\n                arr[j + 1] = temp;\n            }\n        }\n    }\n}"]]},{"t":"② 포인터 swap 함수 값 교환","n":[["시험 포인트","두 변수의 값을 교환하는 함수는 반드시 포인터(주소)를 매개변수로 받아야 하며, 값 자체를 전달 받으면 함수 내부에서만 교환이 일어날 뿐 호출한 곳의 원본 변수는 그대로 유지된다는 점이 실기 시험의 대표적인 함정이다.\nint arr[5] = {23, 7, 45, 12, 8};\nint max = arr[0], min = arr[0];\nfor (int i = 1; i < 5; i++) {"],["설명","두 변수의 값 교환(swap) 함수\nvoid swap(int *a, int *b) {\n     int temp = *a;\n     *a = *b;\n     *b = temp;\n}\n// 사용\nint x = 10, y = 20;\nswap(&x, &y);\nprintf(\"%d %d\\n\", x, y);    // 20 10"]]}]},{"t":"(2) 문자열 반전과 회문 검사","c":[{"t":"① 문자열 반전 len/2 교환","n":[["시험 포인트","회문 검사는 문자열의 앞뒤 대칭 위치의 문자가 서로 같은지를 확인하는 로직으로, 하나라도 일치하지 않으면 즉시 0(거짓)을 반환하고 함수를 종료해야 불필요한 반복을 줄일 수 있다. 실기 시험에서 이러한 조기 반환(Early Return) 패턴을 적절히 활용하는 것이 효율적인 코드 작성의 핵심이다."],["설명","문자열 반전(직접 구현)\nvoid reverse(char str[]) {\n     int len = strlen(str);\n     for (int i = 0; i < len / 2; i++) {\n         char temp = str[i];\n         str[i] = str[len - 1 - i];\n         str[len - 1 - i] = temp;\n     }\n}\n    문자열을 반전시키는 문제는 문자열의 앞과 뒤에서 각각 인덱스를 이동시키며 서로 교환하는 방식으로 구현\n    하며, 반복 횟수는 문자열 길이의 절반(len/2)까지만 진행하면 충분하다는 점이 핵심이다.\nint isPalindrome(char str[]) {\n     int len = strlen(str);\n     for (int i = 0; i < len / 2; i++) {\n         if (str[i] != str[len - 1 - i]) return 0;     // 회문이 아님\n     }\n     return 1;   // 회문임\n}"]]},{"t":"② 특정 문자 개수 세기 \\0까지","n":[["시험 포인트","문자열의 끝을 판단할 때는 str[i] != '\\0'과 같이 널 문자를 기준으로 반복을 종료해야 하며, strlen()을 미리 계산해서 반복 조건에 사용하는 방식도 동일한 결과를 낸다. 이 두 방식 모두 실기 시험에서 자주 사용되는 문자열 순회 패턴이다.\n#include <ctype.h>\nchar str[] = \"Hello\";\nfor (int i = 0; str[i] != '\\0'; i++) {"],["설명","특정 문자의 개수 세기\nchar str[] = \"programming\";\nint count = 0;\nfor (int i = 0; str[i] != '\\0'; i++) {\n     if (str[i] == 'g') count++;\n}\nprintf(\"g의 개수: %d\\n\", count);       // 2"]]}]}]}]},{"t":"Ⅷ C언어 실전 디버깅 문제 모음","c":[{"t":"1. 문제 유형 1: 코드 빈칸 채우기","c":[{"t":"(1) 반복문 빈칸 채우기 문제","c":[{"t":"① 짝수 합 30 빈칸 i%2==0","n":[["설명","문제: 1~10까지 짝수의 합 구하기\n#include <stdio.h>\nint main(void) {\n      int sum = 0;\n      for (int i = 1; i <= 10; i++) {\n          if (___빈칸___) {\n              sum += i;\n          }\n      }\n      printf(\"%d\\n\", sum);    // 30이 출력되어야 함\n      return 0;\n}\n    문제에서 요구하는 출력값 30은 2+4+6+8+10의 합이다. 빈칸에는 i가 짝수인지를 판별하는 조건인 i % 2\n    == 0이 들어가야 한다. 이러한 빈칸 채우기 문제는 요구되는 출력 결과를 먼저 역산하여 어떤 조건이나 로직\n    이 필요한지 추론하는 접근이 효과적이다.\nfor (int i = 1; i <= 10; i++) {\n      if (i % 2 == 0) {     // 정답\n          sum += i;\n      }\n}\n    나머지 연산자 %를 사용하여 i를 2로 나눈 나머지가 0이면 짝수임을 판별한다. 만약 홀수의 합을 구해야 하\n    는 문제였다면 i % 2 != 0 또는 i % 2 == 1로 조건이 달라진다는 점도 함께 기억해 두어야 한다."]]},{"t":"② GCD 유클리드 gcd(b, a%b)","n":[["설명","문제: 최대공약수(GCD) 구하기\nint gcd(int a, int b) {\n      if (b == 0) return a;\n      return gcd(___빈칸1___, ___빈칸2___);\n}\n// gcd(24, 18)의 결과는 6이어야 함\n    유클리드 호제법을 이용한 최대공약수 계산은 gcd(a, b) = gcd(b, a % b)라는 재귀 관계를 활용한다. 빈칸\n    1에는 b, 빈칸2에는 a % b가 들어가야 하며, b가 0이 되는 순간의 a값이 바로 최대공약수가 된다.\nint gcd(int a, int b) {\n      if (b == 0) return a;\n      return gcd(b, a % b);      // 정답\n}\n// gcd(24, 18) -> gcd(18, 6) -> gcd(6, 0) -> 6 반환\n    재귀 함수의 실행 과정을 손으로 직접 따라가며 단계별 결과를 적어보는 연습이 이런 유형의 문제에 특히 효\n    과적이다. gcd(24,18)은 gcd(18, 24%18=6)로, 다시 gcd(6, 18%6=0)으로 이어져 최종적으로 6을 반\n    환한다."]]}]},{"t":"(2) 컴파일 오류 찾기 문제","c":[{"t":"① studio.h 오타·세미콜론 누락","n":[["시험 포인트","이 코드에는 두 가지 오류가 있다. 첫째, #include <studio.h>는 stdio.h의 오타이다. 둘째, int arr[5] = {1,2,3,4,5} 뒤에 세미콜론이 누락되어 있다. 실기 시험에서는 이처럼 여러 개의 작은 오류가 한 코드에 함께 숨어 있는 경우가 많으므로, 하나를 발견했다고 안심하지 말고 코드 전체를 끝까지 검토해야 한다.\n#include <stdio.h>\nint main(void) {"],["설명","문제: 다음 코드의 오류를 찾아 수정하시오\n#include <studio.h>\nint main(void) {\n      int arr[5] = {1, 2, 3, 4, 5}\n      int sum = 0;\n      for (int i = 0; i < 5; i++)\n           sum = sum + arr[i];\n      printf(\"합계: %d\\n\", sum);\n      return 0;\n}"]]},{"t":"② = 대입 vs == 비교 오류","n":[["실제 사례","조건문에 == 대신 =(대입 연산자)가 사용되어, num % 2의 결과(1)가 0에 대입되면서 조건식 전체의 값이 0(거짓)이 아니라 대입 결과인 0 자체가 조건으로 평가된다. 실제로 이 코드는 컴파일러에 따라 경고가 발생하거나, 결과가 항상 예상과 다르게 나오는 대표적인 대입-비교 혼동 오류이다.\nint num = 7;"],["설명","문제: 다음 코드가 항상 \"짝수\"만 출력하는 이유를 찾아 수정하시오\nint num = 7;\nif (num % 2 = 0) {\n     printf(\"짝수\\n\");\n} else {\n     printf(\"홀수\\n\");\n}"]]}]}]}]},{"t":"Ⅸ C언어 실전 디버깅 문제 심화","c":[{"t":"1. 포인터와 구조체 디버깅 문제","c":[{"t":"(1) 포인터 관련 오류 찾기","c":[{"t":"① Call by Value 값 미변경","n":[["시험 포인트","함수의 매개변수를 int *x로 변경하고, 호출 시 &num으로 주소를 전달하면 함수 내부에서 *x를 통해 원본 변수의 값을 직접 변경할 수 있다. 이 유형은 실기 시험에서 \"함수를 이용해 원본 값을 변경하시오\"라는 요구사항으로 매우 자주 출제된다."],["설명","문제: 다음 코드의 오류를 찾아 수정하시오\nvoid addOne(int x) {\n      x = x + 1;\n}\nint main(void) {\n      int num = 10;\n      addOne(num);\n      printf(\"%d\\n\", num);   // 11이 출력되기를 기대했지만 10이 출력됨\n      return 0;\n}\n    addOne 함수가 값에 의한 호출(Call by Value)로 매개변수를 전달받기 때문에, 함수 내부에서 x의 값을 변\n    경해도 main의 num에는 영향을 주지 못한다. 원본 변수를 변경하려면 반드시 포인터를 사용한 참조에 의한\n    호출로 바꾸어야 한다.\nvoid addOne(int *x) {\n      *x = *x + 1;\n}\nint main(void) {\n      int num = 10;\n      addOne(&num);    // 주소 전달\n      printf(\"%d\\n\", num);   // 11\n      return 0;\n}"]]},{"t":"② i<=3 배열 범위 초과 평균 오류","n":[["설명","문제: 학생 평균 점수가 잘못 계산되는 이유를 찾아 수정하시오\nstruct Student { char name[20]; int score; };\nint main(void) {\n      struct Student list[3] = {\n            {\"Kim\", 90}, {\"Lee\", 80}, {\"Park\", 70}\n      };\n      int total = 0;\n      for (int i = 0; i <= 3; i++) {\n            total += list[i].score;\n      }\n      printf(\"평균: %d\\n\", total / 3);\n      return 0;\n}\n    반복문의 조건이 i <= 3으로 되어 있어 배열의 유효 범위(인덱스 0~2)를 벗어난 list[3]에 접근하는 오류가\n    발생한다. 이로 인해 정의되지 않은 값이 total에 더해져 평균이 잘못 계산되거나 프로그램이 비정상 종료될\n    수 있다.\nfor (int i = 0; i < 3; i++) {         // <=를 <로 수정\n      total += list[i].score;\n}\nprintf(\"평균: %d\\n\", total / 3);         // 80\n    조건을 i < 3으로 수정하면 인덱스 0, 1, 2까지만 정확히 순회하여 90+80+70=240의 합계가 계산되고, 이\n    를 3으로 나눈 80이 올바르게 출력된다."]]}]},{"t":"(2) 문자열 배열과 반복문 오류","c":[{"t":"① 문자열 == 비교 오류 strcmp","n":[["설명","문제: 이름 목록 중 \"Kim\"을 찾지 못하는 이유를 설명하시오\nchar names[3][10] = {\"Kim\", \"Lee\", \"Park\"};\nint found = 0;\nfor (int i = 0; i < 3; i++) {\n      if (names[i] == \"Kim\") {     // 오류: 문자열을 ==으로 비교\n            found = 1;\n      }\n}\nprintf(\"%d\\n\", found);       // 0이 출력됨(찾지 못함)\n    C언어에서 문자 배열끼리 ==으로 비교하면 문자열의 내용이 아니라 각 배열의 주소(메모리 위치)를 비교하\n    게 되므로, 내용이 같아도 항상 다른 결과(거짓)가 나온다. 문자열의 내용을 비교하려면 반드시 strcmp() 함\n    수를 사용해야 한다.\n#include <string.h>\nfor (int i = 0; i < 3; i++) {\n      if (strcmp(names[i], \"Kim\") == 0) {    // 정답\n          found = 1;\n      }\n}\nprintf(\"%d\\n\", found);      // 1\n    strcmp(names[i], \"Kim\")의 반환값이 0이면 두 문자열의 내용이 완전히 일치함을 의미하므로, 이를 ==0\n    과 비교하는 방식으로 수정하면 정상적으로 \"Kim\"을 찾아 found가 1로 설정된다."]]},{"t":"② malloc 미초기화 쓰레기 값","n":[["시험 포인트","malloc() 대신 calloc()을 사용하면 할당과 동시에 모든 원소가 0으로 자동 초기화되므로, 이러한 초기화 누락 오류를 원천적으로 방지할 수 있다. malloc과 calloc의 이러한 차이는 실기 시험에서 매우 자주 출제되는 개념이다."],["설명","문제: 다음 코드가 예상과 다른 값을 출력하는 이유를 설명하시오\nint *arr = (int *)malloc(5 * sizeof(int));\nint sum = 0;\nfor (int i = 0; i < 5; i++) {\n      sum += arr[i];     // 오류: 초기화하지 않은 값 사용\n}\nprintf(\"%d\\n\", sum);      // 예측 불가능한 값 출력\n    malloc()으로 할당된 메모리는 이전에 다른 용도로 사용되었던 값이 그대로 남아있는 쓰레기 값(Garbage\n    Value)으로 채워져 있으며, 자동으로 0으로 초기화되지 않는다. 배열의 값을 사용하기 전에 반드시 명시적으\n    로 초기화해야 한다.\nint *arr = (int *)malloc(5 * sizeof(int));\nfor (int i = 0; i < 5; i++) {\n      arr[i] = 0;      // 명시적 초기화 추가\n}\n// 또는 calloc()을 사용하면 자동으로 0으로 초기화됨\nint *arr2 = (int *)calloc(5, sizeof(int));"]]}]}]}]}]},{"t":"제2절 Java 코드 구현과 디버깅 실무","c":[{"t":"Ⅰ Java 기본 구조와 클래스","c":[{"t":"1. Java 프로그램의 기본 구조","c":[{"t":"(1) 클래스와 main 메소드","c":[{"t":"① Java 기본 골격 main 메소드","n":[["시험 포인트","Java 프로그램은 반드시 하나 이상의 클래스로 구성되며, 프로그램 실행의 시작점은 public static void main(String[] args) 메소드이다. 파일명은 반드시 public class로 선언한 클래스 이름과 정확히 일치해야 하며, 이 규칙을 어기면 컴파일 오류가 발생하므로 작업형 시험에서 파일을 저장할 때 항상 클래스명과 일치하는지 확인해야 한다.\nimport java.util.Scanner;\nScanner sc = new Scanner(System.in);\nint num = sc.nextInt();\nSystem.out.println(\"입력값: \" + num);"],["시험 포인트","Scanner 클래스는 사용자로부터 값을 입력받을 때 사용되며, java.util 패키지에서 import 해야 사용할 수 있다. nextInt(), nextDouble(), next(), nextLine()과 같이 입력받을 자료형에 맞는 메소드를 정확히 구분하여 사용해야 하며, 특히 nextInt() 이후 nextLine()을 호출할 때 개행 문자가 남아 있어 원하지 않는 빈 문자열이 입력되는 문제가 실기 시험에서 자주 발생한다."],["설명","Java 프로그램의 기본 골격\npublic class Main {\n      public static void main(String[] args) {\n          System.out.println(\"Hello, World!\");\n      }\n}"]]},{"t":"② 기본 자료형 vs 참조 자료형","n":[["실제 사례","==연산자는 두 참조변수가 동일한 객체를 가리키는지(주소값)를 비교하는 반면, equals() 메소드는 문자열의 실제 내용이 같은지를 비교한다. 실기 시험에서 문자열의 내용이 같은지를 판단해야 할 때 ==을 사용하는 것은 매우 흔한 오류이므로, 문자열 비교는 반드시 equals()를 사용해야 한다."],["설명","기본 자료형과 참조 자료형\nint a = 10;\ndouble b = 3.14;\nboolean c = true;\nString d = \"Hello\";     // 참조 자료형\n    int, double, boolean, char와 같은 기본 자료형은 값 자체를 저장하지만, String과 같은 참조 자료형은 객\n    체의 주소를 저장한다는 근본적인 차이가 있다. 이 차이는 이후 문자열 비교 시 ==과 equals()의 결과가 다\n    르게 나오는 원인이 되므로 반드시 이해하고 있어야 한다.\nString s1 = new String(\"Hello\");\nString s2 = new String(\"Hello\");\nSystem.out.println(s1 == s2);            // false (객체 주소 비교)\nSystem.out.println(s1.equals(s2));       // true (내용 비교)"]]}]},{"t":"(2) 클래스 정의와 객체 생성","c":[{"t":"① 클래스 구성 필드·메소드","n":[["실제 사례","클래스는 속성(필드)과 동작(메소드)으로 구성되며, 객체는 이 클래스를 바탕으로 실제로 생성된 인스턴스를 의미한다. 실기 시험에서는 클래스를 설계하고 필요한 필드와 메소드를 채워 넣는 문제가 자주 출제되므로, 필드명과 메소드 내부에서 사용하는 이름이 정확히 일치하는지 항상 확인해야 한다.\nclass Student {"],["설명","클래스의 구성 요소\nclass Student {\n     String name;\n     int score;\n     void printInfo() {\n         System.out.println(name + \": \" + score);\n     }\n}"]]},{"t":"② 접근 제어자 4종 private 등","n":[["실제 사례","setter 메소드에서 this.score = score 대신 score = score로 작성하면 매개변수가 자기 자신에게 대입될 뿐 실제 필드 값은 변경되지 않는 논리 오류가 발생한다. private 필드에 접근하는 setter/getter를 작성할 때는 this 키워드로 필드와 매개변수를 명확히 구분해야 한다."],["설명","접근 제어자의 종류 Java의 접근 제어자에는 public(어디서든 접근 가능), protected(같은 패키지 및 상속 관계에서 접근 가능) , default(같은 패키지에서만 접근 가능), private(같은 클래스 내에서만 접근 가능)가 있다. 필드를 private으로 선언하고 getter/setter 메소드를 통해서만 접근하도록 하는 것이 캡슐화의 기본 원칙이다.\nclass Student {\n      private int score;\n      public int getScore() { return score; }\n      public void setScore(int score) {\n          this.score = score;    // this 누락 시 자기 자신에게 대입(무한 재귀 위험 없음, 단\n순 오류)\n      }\n}"]]}]}]}]},{"t":"Ⅱ 제어문과 배열/컬렉션","c":[{"t":"1. 조건문과 반복문","c":[{"t":"(1) 조건문 구현","c":[{"t":"① 삼항 조건 연산자 ?: 학점","n":[["시험 포인트","삼항 조건 연산자(? :)를 중첩해서 사용하면 간결한 코드를 작성할 수 있지만, 괄호를 명확히 사용하지 않으면 연산 우선순위를 혼동하기 쉬우므로 실기 시험에서는 if-else if-else 구조로 명확하게 작성하는 것이 안전하다.\nint x = 10;"],["시험 포인트","C언어와 달리 Java는 조건식이 반드시 boolean 타입이어야 하므로, 대입 연산자 =를 조건문에 사용하면 컴파일 오류가 즉시 발생하여 오히려 실수를 미리 방지해준다는 차이가 있다. 다만 boolean 변수에 대해서는 if(flag = true)와 같이 여전히 대입 오류가 컴파일되어 통과되므로 boolean 조건에서는 특히 주의해야 한다."],["설명","if-else와 조건 연산자\nint score = 85;\nString grade = (score >= 90) ? \"A\" : (score >= 80) ? \"B\" : \"C\";\nSystem.out.println(grade);      // B"]]},{"t":"② 향상된 for문 for-each 합 15","n":[["설명","향상된 for문(for-each)\nint[] arr = {1, 2, 3, 4, 5};\nint sum = 0;\nfor (int num : arr) {\n     sum += num;\n}\nSystem.out.println(sum);      // 15\n    향상된 for문은 배열이나 컬렉션의 모든 원소를 순회할 때 인덱스 없이 간결하게 코드를 작성할 수 있게 해준\n    다. 다만 for-each문 내부에서는 인덱스에 직접 접근할 수 없고, 순회 중인 원소의 값을 변경해도 원본 배열\n    에는 반영되지 않는다는 점(기본 자료형의 경우)을 유의해야 한다.\nint i = 0;\ndo {\n     System.out.println(i);\n     i++;\n} while (i < 5);\n    do-while문은 조건을 검사하기 전에 반복 블록을 최소 한 번은 반드시 실행한다는 특징이 있다. while문과\n    마찬가지로 반복 조건에 사용되는 변수의 증감식을 빠뜨리면 무한 루프에 빠지므로, 반복문 내부에 조건 변수\n    를 변화시키는 코드가 존재하는지 항상 점검해야 한다."]]}]},{"t":"(2) 배열의 활용","c":[{"t":"① 배열 length 괄호 없이 사용","n":[["시험 포인트","Java 배열의 길이는 length라는 필드로 접근하며, 문자열의 길이를 구하는 length() 메소드와 혼동하지 않도록 주의해야 한다. 배열은 arr.length, 문자열은 str.length()로 괄호의 유무가 다르다는 점이 실기 시험에서 흔히 혼동되는 부분이다.\nint[] arr = {1, 2, 3};\nSystem.out.println(arr[3]);\n// ArrayIndexOutOfBoundsException 예외 발생"],["설명","배열의 선언과 길이\nint[] arr = new int[5];\nint[] arr2 = {1, 2, 3, 4, 5};\nSystem.out.println(arr2.length);      // 5 (괄호 없이 사용)"]]},{"t":"② ArrayList add·remove·get","n":[["시험 포인트","HashMap은 키(key)와 값(value)의 쌍으로 데이터를 저장하는 자료구조로, 키를 통해 값을 빠르게 조회할 수 있다는 장점이 있다. keySet()을 이용해 모든 키를 순회하며 값을 조회하는 패턴은 실기 시험에서 자주 활용되는 대표적인 사용법이다."],["설명","ArrayList의 기본 사용법\nimport java.util.ArrayList;\nArrayList<Integer> list = new ArrayList<>();\nlist.add(10);\nlist.add(20);\nlist.remove(0);     // 인덱스 0 삭제\nSystem.out.println(list.get(0));     // 20\n    ArrayList는 크기가 고정된 배열과 달리 원소를 자유롭게 추가/삭제할 수 있는 동적 크기의 리스트이다.\n    remove(int index)는 인덱스를 삭제하고, remove(Object o)는 값을 삭제한다는 차이가 있어,\n    list.remove(1)과 같은 코드가 인덱스 1을 삭제하는 것인지 값 1을 삭제하는 것인지 자료형에 따라 다르게 동\n    작하므로 이 차이를 명확히 이해해야 한다.\nimport java.util.HashMap;\nHashMap<String, Integer> map = new HashMap<>();\nmap.put(\"Kim\", 90);\nmap.put(\"Lee\", 85);\nSystem.out.println(map.get(\"Kim\"));     // 90\nfor (String key : map.keySet()) {\n      System.out.println(key + \": \" + map.get(key));\n}"]]}]}]}]},{"t":"Ⅲ 상속과 다형성","c":[{"t":"1. 상속(Inheritance)","c":[{"t":"(1) 상속의 기본 개념","c":[{"t":"① extends 클래스 상속","n":[["설명","클래스 상속과 extends\nclass Animal {\n     void sound() {\n         System.out.println(\"동물이 소리를 냅니다\");\n     }\n}\nclass Dog extends Animal {\n     void bark() {\n         System.out.println(\"멍멍\");\n     }\n}\n// 사용\nDog d = new Dog();\nd.sound();     // 부모 클래스의 메소드 호출 가능\nd.bark();\n    상속은 extends 키워드를 사용하여 부모 클래스(Animal)의 필드와 메소드를 자식 클래스(Dog)가 그대로\n    물려받는 기능이다. 자식 클래스는 부모 클래스에 정의된 기능을 재사용하면서, 자신만의 고유한 필드와 메소\n    드를 추가로 정의할 수 있다.\nclass Animal {\n     Animal() {\n         System.out.println(\"Animal 생성자\");\n     }\n}\nclass Dog extends Animal {\n     Dog() {\n         super();     // 부모 생성자 명시적 호출(생략 시 자동 호출됨)\n         System.out.println(\"Dog 생성자\");\n     }\n}\n    자식 클래스의 생성자에서는 부모 클래스의 생성자를 호출하는 super()가 (명시하지 않아도) 가장 먼저 자동\n    으로 실행된다. 부모 클래스가 매개변수를 필요로 하는 생성자만 가지고 있는 경우, 자식 생성자에서 super(\n    매개변수)를 명시적으로 호출하지 않으면 컴파일 오류가 발생하므로 이 부분을 유의해야 한다."]]},{"t":"② @Override 오버라이딩","n":[["실제 사례","오버라이딩은 부모 클래스에 정의된 메소드를 자식 클래스에서 동일한 이름과 매개변수로 재정의하는 것을 의미한다. @Override 애노테이션을 붙이면 컴파일러가 실제로 부모 클래스에 오버라이딩 대상 메소드가 존재하는지 검사해주므로, 메소드 이름의 오타로 인한 오버로딩(새로운 메소드 생성) 실수를 사전에 방지할 수 있다.\nclass Animal {"],["설명","오버라이딩의 개념\nclass Animal {\n     void sound() {\n          System.out.println(\"동물 소리\");\n     }\n}\nclass Dog extends Animal {\n     @Override\n     void sound() {\n          System.out.println(\"멍멍\");\n     }\n}"]]}]},{"t":"(2) 다형성의 활용","c":[{"t":"① 업캐스팅 다형성 자식 메소드 호출","n":[["실제 사례","부모 타입의 참조변수로 자식 객체를 가리키는 것을 업캐스팅이라고 하며, 이때 메소드를 호출하면 참조변수의 타입이 아니라 실제 객체의 타입에 정의된 오버라이딩 메소드가 호출된다. 이러한 동작 방식을 동적 바인딩이라고 하며, 다형성의 핵심 원리이다.\ninterface Movable {"],["실제 사례","인터페이스는 메소드의 이름과 매개변수만을 정의하고 실제 구현은 이를 구현하는 클래스에 맡기는 역할을 한다. implements 키워드로 인터페이스를 구현하는 클래스는 인터페이스에 선언된 모든 추상 메소드를 반드시 재정의해야 하며, 하나라도 누락하면 컴파일 오류가 발생한다."],["설명","업캐스팅과 다형성\nAnimal a = new Dog();    // 업캐스팅\na.sound();    // Dog의 오버라이딩된 메소드가 호출됨(멍멍)"]]},{"t":"② abstract 추상 클래스·메소드","n":[["시험 포인트","추상 클래스를 new 키워드로 직접 인스턴스화하려고 하면 컴파일 오류가 발생한다. 반드시 추상 클래스를 상속받은 구체적인 자식 클래스를 통해서만 객체를 생성할 수 있다는 점을 실기 시험에서 정확히 기억하고 있어야 한다."],["설명","추상 클래스의 개념\nabstract class Shape {\n     abstract double area();     // 추상 메소드, 구현부 없음\n     void printArea() {\n         System.out.println(\"넓이: \" + area());\n     }\n}\nclass Circle extends Shape {\n     double radius;\n     Circle(double radius) { this.radius = radius; }\n     double area() {\n         return 3.14 * radius * radius;\n     }\n}\n    추상 클래스는 하나 이상의 추상 메소드(구현부가 없는 메소드)를 포함할 수 있는 클래스로, 자체적으로는 객\n    체를 생성할 수 없고 반드시 상속을 통해 자식 클래스에서 추상 메소드를 구현해야 한다.\nShape s = new Shape();      // 오류: 추상 클래스는 직접 인스턴스화 불가\nShape s2 = new Circle(5); // 정상: 자식 클래스로 인스턴스화"]]}]}]}]},{"t":"Ⅳ 예외 처리(Exception Handling)","c":[{"t":"1. 예외 처리의 기본 구조","c":[{"t":"(1) try-catch 구문","c":[{"t":"① try-catch ArithmeticException","n":[["설명","기본 예외 처리\ntry {\n      int result = 10 / 0;\n} catch (ArithmeticException e) {\n      System.out.println(\"0으로 나눌 수 없습니다: \" + e.getMessage());\n}\n    try 블록 안에서 예외가 발생하면 프로그램이 즉시 종료되는 대신, 해당 예외 타입과 일치하는 catch 블록으\n    로 제어가 이동하여 예외 상황에 대한 처리를 수행할 수 있다. e.getMessage()를 통해 예외에 대한 구체적\n    인 메시지를 확인할 수 있다는 점도 함께 기억해 두어야 한다.\ntry {\n      int[] arr = new int[3];\n      arr[5] = 10;\n} catch (ArrayIndexOutOfBoundsException e) {\n      System.out.println(\"배열 범위 초과\");\n} finally {\n      System.out.println(\"항상 실행되는 블록\");\n}\n    finally 블록은 예외 발생 여부와 관계없이 항상 실행되는 블록으로, 파일이나 네트워크 연결을 닫는 자원 정\n    리 코드를 작성할 때 주로 활용된다. try 블록에서 return문이 실행되더라도 finally 블록은 return 되기 전에\n    반드시 실행된다는 점을 정확히 이해하고 있어야 한다."]]},{"t":"② 다중 catch 구체→상위 순서","n":[["설명","다중 catch 블록\ntry {\n      int[] arr = new int[3];\n      System.out.println(arr[5]);\n} catch (ArrayIndexOutOfBoundsException e) {\n      System.out.println(\"배열 범위 오류\");\n} catch (Exception e) {\n      System.out.println(\"기타 오류\");\n}\n    여러 종류의 예외를 서로 다르게 처리하고 싶을 때는 catch 블록을 여러 개 작성할 수 있다. 이때 반드시 더\n    구체적인(하위) 예외 클래스를 먼저 catch하고, 더 포괄적인(상위) 예외 클래스인 Exception을 나중에\n    catch해야 하며, 순서가 반대로 되면 컴파일 오류가 발생한다.\ntry {\n      // ...\n} catch (Exception e) {              // 상위 클래스를 먼저 배치\n      System.out.println(\"일반 오류\");\n} catch (ArithmeticException e) { // 오류: 도달 불가능한 코드로 컴파일 오류\n      System.out.println(\"산술 오류\");\n}\n    상위 예외 클래스(Exception)를 먼저 catch하면 그 이후에 작성된 하위 예외 클래스\n    (ArithmeticException)의 catch 블록은 절대 실행될 수 없는 코드가 되어 컴파일 오류가 발생한다. 항상 구\n    체적인 예외를 먼저, 포괄적인 예외를 나중에 배치하는 순서를 지켜야 한다."]]}]},{"t":"(2) throw와 throws","c":[{"t":"① throw 예외 직접 발생","n":[["설명","throw를 이용한 예외 발생\nvoid checkAge(int age) {\n      if (age < 0) {\n          throw new IllegalArgumentException(\"나이는 음수일 수 없습니다\");\n      }\n      System.out.println(\"나이: \" + age);\n}\n    throw 키워드는 개발자가 특정 조건에서 의도적으로 예외를 발생시킬 때 사용한다. 유효하지 않은 값이 입력\n    되었을 때 이를 무시하고 넘어가는 대신 명시적으로 예외를 발생시키면, 문제의 원인을 더 명확하게 파악하고\n    호출한 곳에서 적절히 대응할 수 있게 된다.\nvoid readFile() throws java.io.IOException {\n      // 파일 입출력 코드\n}\n    throws는 메소드 선언부에 사용하여, 해당 메소드가 특정 예외를 발생시킬 수 있음을 호출하는 쪽에 알리고\n    예외 처리의 책임을 위임하는 키워드이다. 체크 예외(Checked Exception)를 발생시키는 메소드는 반드시\n    throws로 선언하거나 메소드 내부에서 try-catch로 처리해야 하며, 이를 누락하면 컴파일 오류가 발생한다."]]},{"t":"② 사용자 정의 예외 extends Exception","n":[["시험 포인트","Exception 클래스를 상속받아 사용자 정의 예외 클래스를 만들면, 프로그램의 특정 도메인에 맞는 의미 있는 예외 이름을 정의하여 오류 상황을 더 명확하게 표현할 수 있다. 실기 시험에서 특정 조건을 위반 했을 때 사용자 정의 예외를 발생시키도록 요구하는 문제가 출제될 수 있다.\nvoid process() throws InvalidScoreException {"],["설명","사용자 정의 예외 만들기\nclass InvalidScoreException extends Exception {\n      InvalidScoreException(String message) {\n           super(message);\n      }\n}\nvoid setScore(int score) throws InvalidScoreException {\n      if (score < 0 || score > 100) {\n           throw new InvalidScoreException(\"점수는 0~100 사이여야 합니다\");\n      }\n}"]]}]}]}]},{"t":"Ⅴ Java 자주 발생하는 디버깅 유형 종합","c":[{"t":"1. 컴파일 오류(Compile Error) 유형","c":[{"t":"(1) 클래스와 파일명 불일치","c":[{"t":"① public 클래스명 = 파일명","n":[["설명","public 클래스명과 파일명 오류 public으로 선언된 클래스의 이름은 반드시 소스 파일의 이름과 정확히 일치해야 한다(대소문자 포함). 이 규칙을 어기면 \"class ... is public, should be declared in a file named ...\"라는 명확한 오류 메시지가 출력되므로, 이 메시지가 보이면 파일명과 클래스명을 다시 확인해야 한다. C언어와 마찬가지로 Java에서도 세미콜론이나 중괄호의 누락은 가장 흔한 컴파일 오류의 원인이다. 특히 Java는 클래스, 메소드, 제어문의 중괄호가 중첩되는 구조가 많으므로, 코드 편집기의 괄호 자동 강조 기능을 적극 활용하여 짝이 맞는지 확인하는 것이 효율적이다."]]},{"t":"② 자료형 불일치 Integer.pa rseInt","n":[["실제 사례","메소드의 선언부에 지정된 반환형과 실제 return 문에서 반환하는 값의 자료형이 일치하지 않으면 컴파일 오류가 발생한다. void로 선언된 메소드에서 값을 반환하려고 하거나, int로 선언된 메소드에서 return문이 아예 없는 경우도 흔한 오류이므로 메소드 선언부와 내부 로직을 함께 점검해야 한다."],["설명","자료형 불일치\nint num = \"10\";      // 오류: String을 int에 대입할 수 없음\nint num2 = Integer.parseInt(\"10\");    // 정상: 문자열을 정수로 변환\nJava는 자료형에 매우 엄격한 언어이므로, 문자열을 정수형 변수에 그대로 대입하면 컴파일 오류가 발생한다. 문자열로 입력받은 값을 숫자로 사용해야 한다면 Integer.parseInt(), Double.parseDouble()과 같은 변환 메소드를 반드시 사용해야 한다."]]}]},{"t":"(2) 자주 발생하는 런타임 예외","c":[{"t":"① NullPointerExcepti on null 참조","n":[["실제 사례","서로 호환되지 않는 타입으로 강제 형 변환을 시도하면 ClassCastException이 발생한다. 다형성을 활용해 여러 자식 객체를 부모 타입으로 다루다가 다시 원래의 자식 타입으로 캐스팅할 때는, instanceof 연산자로 실제 객체의 타입을 먼저 확인하는 것이 안전하다."],["설명","NullPointerException\nString str = null;\nSystem.out.println(str.length());    // 오류: NullPointerException\n객체가 생성되지 않아 null 상태인 참조변수의 메소드를 호출하려고 하면 NullPointerException이 발생한다. 이는 Java에서 가장 빈번하게 발생하는 런타임 예외로, 객체를 사용하기 전에 new 키워드로 정상적으로 생성되었는지, 혹은 이전 로직에서 null이 대입되지는 않았는지를 확인해야 한다.\nObject obj = \"Hello\";\nInteger num = (Integer) obj;    // 오류: String을 Integer로 캐스팅 불가"]]},{"t":"② Java 논리 오류 특징·사례","n":[["시험 포인트","Java의 논리 오류 역시 C언어와 마찬가지로 컴파일과 실행은 정상적으로 되지만 결과가 요구사항과 다르게 나오는 경우를 의미한다. 반복문의 경계값 오류, 조건문의 순서 오류, 오버라이딩 대신 새로운 메소드가 정의되는 오류 등이 대표적인 사례이며, 실기 시험에서 이러한 유형의 결함을 코드에서 찾아 수정하는 문제가 많은 배점을 차지한다."],["시험 포인트","System.out.println을 활용해 각 단계별 변수의 값을 출력하며 예상값과 실제값을 비교하는 것이 가장 기본적인 디버깅 방법이다. 통합 개발 환경(이클립스 등)의 디버거 기능을 활용하면 중단점을 설정하고 변수 값의 변화를 한 줄씩 추적할 수 있으므로, 작업형 시험 환경에서 디버거 사용법을 미리 익혀두는 것이 실전에서 큰 도움이 된다."],["설명","논리 오류의 특징과 사례"]]}]}]}]},{"t":"Ⅵ Java 실전 예제 모음","c":[{"t":"1. 배열과 컬렉션 실전 예제","c":[{"t":"(1) 배열 정렬과 검색","c":[{"t":"① Arrays.sort 오름차순 정렬","n":[["설명","Arrays.sort()를 이용한 정렬\nimport java.util.Arrays;\nint[] arr = {5, 2, 8, 1, 9};\nArrays.sort(arr);\nSystem.out.println(Arrays.toString(arr));    // [1, 2, 5, 8, 9]\nArrays.sort()는 배열을 오름차순으로 직접 정렬해주는 표준 라이브러리 메소드로, 직접 정렬 알고리즘을 구현하지 않고도 간단히 사용할 수 있다. Arrays.toString()을 함께 사용하면 배열의 내용을 사람이 읽기 쉬운 형태로 출력할 수 있어 디버깅 시에도 유용하다.\nimport java.util.*;\nList<Integer> list = new ArrayList<>(Arrays.asList(5, 2, 8, 1));\nCollections.sort(list);                           // 오름차순\nCollections.sort(list, Collections.reverseOrder()); // 내림차순\nSystem.out.println(list);\nArrayList와 같은 컬렉션을 정렬할 때는 Collections.sort()를 사용하며, 기본은 오름차순이지만 Collections.reverseOrder()를 두 번째 인자로 전달하면 내림차순으로 정렬할 수 있다. 배열은 Arrays.sort(), 컬렉션은 Collections.sort()를 사용한다는 이름의 차이를 정확히 구분해야 한다."]]},{"t":"② 2차원 배열 합계 matrix.length","n":[["설명","2차원 배열의 합계 구하기\nint[][] matrix = {{1, 2, 3}, {4, 5, 6}};\nint sum = 0;\nfor (int i = 0; i < matrix.length; i++) {\n      for (int j = 0; j < matrix[i].length; j++) {\n          sum += matrix[i][j];\n      }\n}\nSystem.out.println(sum);       // 21\n    Java의 2차원 배열은 matrix.length로 행의 개수를, matrix[i].length로 i번째 행의 열 개수를 각각 구할 수\n    있다. C언어와 달리 각 행의 길이가 서로 다른 가변 배열(Jagged Array)도 만들 수 있으므로, 반복문의 열\n    범위는 반드시 matrix[i].length를 사용해야 안전하다.\nString[] names = {\"Park\", \"Kim\", \"Lee\"};\nArrays.sort(names);      // 사전 순으로 정렬\nfor (String name : names) {\n      System.out.println(name);\n}\n// 출력: Kim, Lee, Park\n    문자열 배열도 Arrays.sort()로 정렬할 수 있으며, 이때는 숫자 크기가 아닌 사전 순(알파벳/가나다 순)으로\n    정렬된다는 점을 기억해야 한다. 향상된 for문(for-each)을 이용하면 정렬된 배열을 간결하게 순회하며 출력\n    할 수 있다."]]}]},{"t":"(2) 문자열 메소드 활용","c":[{"t":"① substring·indexOf· replace","n":[["시험 포인트","split() 메소드는 지정한 구분자를 기준으로 문자열을 분리하여 문자열 배열로 반환하며, CSV 형식의 데이터를 파싱하는 실기 문제에서 매우 자주 활용된다. 구분자로 특수문자(마침표 등)를 사용할 때는 정규 표현식으로 해석되어 예상과 다르게 동작할 수 있으므로 주의가 필요하다."],["설명","substring, indexOf, replace\nString str = \"Hello, World!\";\nSystem.out.println(str.substring(7));           // World!\nSystem.out.println(str.substring(0, 5));        // Hello\nSystem.out.println(str.indexOf(\"World\"));       // 7\nSystem.out.println(str.replace(\"World\", \"Java\"));      // Hello, Java!\n    substring(시작인덱스)는 시작 인덱스부터 끝까지, substring(시작, 끝)은 시작부터 끝-1까지의 부분 문자\n    열을 반환한다. indexOf()는 특정 문자열이 처음 등장하는 위치를 반환하며 찾지 못하면 -1을 반환한다는 점\n    도 함께 기억해야 한다.\nString csv = \"Kim,90,컴퓨터공학과\";\nString[] parts = csv.split(\",\");\nSystem.out.println(parts[0]);      // Kim\nSystem.out.println(parts[1]);      // 90\nSystem.out.println(parts[2]);      // 컴퓨터공학과"]]},{"t":"② StringBuilder append 효율","n":[["설명","StringBuilder를 사용하는 이유\nStringBuilder sb = new StringBuilder();\nfor (int i = 1; i <= 5; i++) {\n      sb.append(i).append(\" \");\n}\nSystem.out.println(sb.toString());         // 1 2 3 4 5\n    String은 불변(immutable) 객체이므로 문자열을 반복적으로 연결(+연산)하면 매번 새로운 String 객체가\n    생성되어 메모리와 성능 측면에서 비효율적이다. StringBuilder는 내부적으로 문자열을 변경 가능한 형태로\n    관리하여, 반복문 안에서 문자열을 계속 이어붙여야 하는 경우 훨씬 효율적으로 동작한다.\nStringBuilder sb = new StringBuilder(\"Hello\");\nsb.append(\" World\");           // Hello World\nsb.insert(5, \",\");              // Hello, World\nsb.reverse();                     // dlroW ,olleH\nSystem.out.println(sb.toString());\n    StringBuilder는 append(추가), insert(특정 위치 삽입), reverse(반전), delete(삭제)와 같은 다양한 메\n    소드를 제공한다. 문자열 반전 문제와 같이 String 클래스 자체에는 존재하지 않는 기능이 필요할 때\n    StringBuilder의 reverse() 메소드를 활용하면 매우 간결하게 해결할 수 있다."]]}]}]}]},{"t":"Ⅶ Java 실전 디버깅 문제 모음","c":[{"t":"1. 문제 유형 1: 코드 빈칸 채우기","c":[{"t":"(1) 조건문과 반복문 빈칸 채우기","c":[{"t":"① 3의 배수 합 1683 i%3==0","n":[["시험 포인트","빈칸에는 i가 3의 배수인지를 판별하는 조건 i % 3 == 0이 들어가야 한다. 실기 시험에서는 이러한 배수 판별 조건을 요구하는 문제가 매우 자주 출제되므로, 나머지 연산자를 이용한 배수 판별 공식을 확실히 암기해 두어야 한다.\nfor (int i = 1; i <= 100; i++) {"],["설명","문제: 1~100 사이의 3의 배수의 합 구하기\npublic class Main {\n      public static void main(String[] args) {\n          int sum = 0;\n          for (int i = 1; i <= 100; i++) {\n              if (___빈칸___) {\n                     sum += i;\n              }\n          }\n          System.out.println(sum);       // 1683이 출력되어야 함\n      }\n}"]]},{"t":"② getMax 빈칸 a > b","n":[["설명","문제: 두 수의 최대값을 반환하는 메소드\npublic class Main {\n      static int getMax(int a, int b) {\n          if (___빈칸___) {\n              return a;\n          } else {\n              return b;\n          }\n      }\n      public static void main(String[] args) {\n          System.out.println(getMax(5, 8));       // 8이 출력되어야 함\n      }\n}\n    빈칸에는 a가 b보다 큰지 확인하는 조건 a > b가 들어가야 한다. a > b가 참이면 a를 반환하고, 그렇지 않으\n    면(a가 b보다 작거나 같으면) b를 반환하는 구조이다.\nstatic int getMax(int a, int b) {\n      if (a > b) {     // 정답\n          return a;\n      } else {\n          return b;\n      }\n}\n    a와 b가 같은 경우도 else 블록으로 처리되어 b가 반환되지만, 두 값이 같으므로 결과에는 차이가 없다는 점\n    도 함께 이해해 두면 조건의 등호 포함 여부를 판단하는 데 도움이 된다."]]}]},{"t":"(2) 컴파일 오류 찾기 문제","c":[{"t":"① 클래스명 main 불일치·세미콜론","n":[["설명","문제: 다음 코드의 오류를 찾아 수정하시오\npublic class main {\n      public static void main(String[] args) {\n          int[] arr = {1, 2, 3, 4, 5}\n          int sum = 0\n          for (int i = 0; i < arr.length; i++) {\n                 sum += arr[i];\n          }\n          System.out.println(\"합계: \" + sum);\n      }\n}\n    파일명이 Main.java라고 가정할 때, public class main은 클래스명(main)과 파일명(Main)의 대소문자가\n    일치하지 않아 컴파일 오류가 발생한다. 또한 배열 선언과 sum 선언 뒤에 세미콜론이 각각 누락되어 있다. 이\n    처럼 대소문자 불일치는 눈으로 보기에는 비슷해 보이지만 Java 컴파일러는 이를 엄격하게 구분한다는 점을\n    기억해야 한다.\npublic class Main {\n      public static void main(String[] args) {\n          int[] arr = {1, 2, 3, 4, 5};\n          int sum = 0;\n          for (int i = 0; i < arr.length; i++) {\n                 sum += arr[i];\n          }\n          System.out.println(\"합계: \" + sum);\n      }\n}\n    클래스명을 Main으로 대문자로 수정하고 누락된 세미콜론을 모두 추가하면 정상적으로 컴파일되어 \"합계:\n    15\"가 출력된다."]]},{"t":"② i<=length 배열 범위 예외","n":[["시험 포인트","조건을 i < scores.length로 수정하면 인덱스 0, 1, 2까지만 접근하여 정상적으로 270이 출력된다. 배열의 length와 반복 조건에 <= 또는 <를 사용하는 것 사이의 경계값 오류는 Java 실기 시험에서 매우 자주 출제되는 대표적인 유형이다."],["설명","문제: 다음 코드 실행 시 발생하는 예외와 원인을 설명하시오\npublic class Main {\n      public static void main(String[] args) {\n          int[] scores = {90, 85, 95};\n          int total = 0;\n          for (int i = 0; i <= scores.length; i++) {\n              total += scores[i];\n          }\n          System.out.println(total);\n      }\n}\n    반복문의 조건이 i <= scores.length로 작성되어 있어, i가 scores.length(3)와 같아지는 마지막 반복에서\n    scores[3]에 접근하게 된다. 배열의 유효 인덱스는 0~2이므로 이는\n    ArrayIndexOutOfBoundsException을 발생시키는 대표적인 경계값 오류이다.\nfor (int i = 0; i < scores.length; i++) {     // <=를 <로 수정\n      total += scores[i];\n}"]]}]}]}]},{"t":"Ⅷ Java 실전 디버깅 문제 심화","c":[{"t":"1. 객체지향 디버깅 문제","c":[{"t":"(1) 오버라이딩 오류 찾기","c":[{"t":"① Sound 대소문자 오버라이딩 실패","n":[["설명","문제: 자식 클래스의 메소드가 호출되지 않는 이유를 설명하시오\nclass Animal {\n      void sound() { System.out.println(\"동물 소리\"); }\n}\nclass Dog extends Animal {\n      void Sound() { System.out.println(\"멍멍\"); }    // 오류\n}\npublic class Main {\n      public static void main(String[] args) {\n          Animal a = new Dog();\n          a.sound();   // \"동물 소리\"가 출력됨(의도와 다름)\n      }\n}\n    Dog 클래스의 Sound() 메소드는 첫 글자가 대문자로 되어 있어, 부모 클래스의 sound()와 이름이 일치하\n    지 않으므로 오버라이딩이 아닌 완전히 별개의 새로운 메소드로 취급된다. 따라서 a.sound() 호출 시 부모\n    클래스인 Animal의 sound()가 그대로 실행된다.\nclass Dog extends Animal {\n      @Override\n      void sound() { System.out.println(\"멍멍\"); }    // 정답\n}\n    메소드명을 소문자 sound로 정확히 일치시키고 @Override 애노테이션을 붙이면, a.sound() 호출 시 Dog\n    의 오버라이딩된 메소드가 호출되어 \"멍멍\"이 출력된다. @Override를 습관적으로 붙이면 이러한 이름 불일\n    치 오류를 컴파일 시점에 미리 발견할 수 있다."]]},{"t":"② super(name) 호출 누락","n":[["설명","문제: 다음 코드가 컴파일되지 않는 이유를 설명하시오\nclass Animal {\n      String name;\n      Animal(String name) { this.name = name; }\n}\nclass Dog extends Animal {\n      Dog() {\n          System.out.println(\"Dog 생성\");    // 오류: super() 호출 누락\n      }\n}\n    Animal 클래스는 매개변수를 필요로 하는 생성자만 정의되어 있어 기본 생성자가 자동으로 생성되지 않는다.\n    Dog의 생성자에서 super()를 명시적으로 호출하지 않으면 컴파일러가 자동으로 매개변수 없는 super()를\n    호출하려 시도하는데, Animal에는 그러한 생성자가 없으므로 컴파일 오류가 발생한다.\nclass Dog extends Animal {\n      Dog(String name) {\n          super(name);     // 부모 생성자 명시적 호출\n          System.out.println(\"Dog 생성\");\n      }\n}\n    Dog의 생성자에서 super(name)을 명시적으로 호출하여 부모 클래스의 생성자에 필요한 인자를 전달하면\n    정상적으로 컴파일된다. 부모 클래스에 매개변수 없는 생성자가 없다면, 자식 클래스는 반드시 super(인자)\n    를 명시적으로 호출해야 한다는 규칙을 기억해야 한다."]]}]},{"t":"(2) 컬렉션 관련 오류 찾기","c":[{"t":"① list.get(3) IndexOutOfBounds","n":[["설명","문제: 다음 코드 실행 시 발생하는 예외를 설명하시오\nimport java.util.*;\nArrayList<Integer> list = new ArrayList<>();\nlist.add(10);\nlist.add(20);\nlist.add(30);\nSystem.out.println(list.get(3));     // 오류 발생\n    ArrayList의 인덱스는 0부터 시작하며 현재 리스트에는 인덱스 0, 1, 2까지만 존재(총 3개 원소)한다.\n    get(3)은 존재하지 않는 인덱스에 접근하는 것이므로 IndexOutOfBoundsException이 발생한다. 배열과\n    마찬가지로 ArrayList도 인덱스의 유효 범위를 벗어나면 예외가 발생한다는 점을 기억해야 한다.\nSystem.out.println(list.get(2));     // 30 (마지막 원소)\nSystem.out.println(list.size());       // 3 (전체 원소 개수)\n    ArrayList의 마지막 원소에 접근하려면 list.get(list.size() - 1)과 같이 size()에서 1을 뺀 인덱스를 사용해\n    야 한다. 이는 배열의 length - 1로 마지막 인덱스를 구하는 것과 동일한 원리이다."]]},{"t":"② parseInt 실패 → NumberFormat 예외","n":[["시험 포인트","try-catch로 NumberFormatException을 처리하면, 사용자가 잘못된 값을 입력하더라도 프로그램이 비정상 종료되지 않고 적절한 안내 메시지를 출력한 뒤 계속 실행될 수 있다. 실기 시험에서 사용자 입력을 다루는 문제는 이러한 예외 상황까지 고려하여 구현하는 것이 안전하다."],["설명","문제: 다음 코드에서 예외가 발생하는 원인을 설명하고 수정하시오\nimport java.util.Scanner;\nScanner sc = new Scanner(System.in);\nSystem.out.print(\"숫자 입력: \");\nString input = sc.nextLine();\nint num = Integer.parseInt(input);      // 숫자가 아닌 값 입력 시 오류\nSystem.out.println(num * 2);\n    사용자가 숫자가 아닌 문자열(예: \"abc\")을 입력하면 Integer.parseInt()가 이를 정수로 변환할 수 없어\n    NumberFormatException이 발생한다. 사용자 입력값은 항상 예상과 다를 수 있으므로 방어적인 예외 처\n    리가 필요하다.\ntry {\n      int num = Integer.parseInt(input);\n      System.out.println(num * 2);\n} catch (NumberFormatException e) {\n      System.out.println(\"숫자만 입력해야 합니다\");\n}"]]}]}]}]}]},{"t":"제3절 Python 코드 구현과 디버깅 실무","c":[{"t":"Ⅰ Python 기본 문법과 자료형","c":[{"t":"1. Python 프로그램의 기본 구조","c":[{"t":"(1) 들여쓰기와 기본 출력","c":[{"t":"① Python 들여쓰기 블록 구분","n":[["시험 포인트","Python은 중괄호 대신 들여쓰기(Indentation)로 코드 블록을 구분하는 독특한 문법을 가진다. 같은 블록 안의 코드는 반드시 동일한 개수의 공백으로 들여쓰기가 맞춰져야 하며, 들여쓰기가 한 칸이라도 어긋나면 IndentationError가 발생하므로 실기 시험에서 가장 먼저 주의해야 할 부분이다. a = 10"],["실제 사례","Python은 변수의 자료형을 미리 선언하지 않는 동적 타이핑 언어로, 하나의 변수에 이후 다른 자료형의 값을 자유롭게 재할당할 수 있다. type() 함수를 사용하면 현재 변수에 저장된 값의 실제 자료형을 확인할수 있어 디버깅 시 유용하게 활용된다."],["설명","Python의 들여쓰기 규칙 if True:\nprint(\"Hello, World!\")\nprint(\"Python\")"]]},{"t":"② Python 자료형 int·float·str·bool","n":[["시험 포인트","Python의 기본 자료형에는 정수(int), 실수(float), 문자열(str), 불(bool), 그리고 여러 값을 담는 리스트(list), 튜플(tuple), 딕셔너리(dict), 집합(set)과 같은 컬렉션 자료형이 있다. 실기 시험에서는 리스트와 딕셔너리를 활용한 문제가 특히 자주 출제된다. num_str = \"10\""],["시험 포인트","Python은 문자열과 숫자를 자동으로 변환하여 연산해주지 않으므로, 문자열로 입력받은 값을 숫자 연산에 사용하려면 반드시 int() 또는 float()로 명시적으로 형 변환해야 한다. input() 함수로 입력받은 값은 항상 문자열(str) 타입이라는 점을 실기 시험에서 특히 기억해야 한다."],["설명","기본 자료형"]]}]},{"t":"(2) 주요 연산자","c":[{"t":"① / 실수 나눗셈·// 몫·** 거듭제곱","n":[["시험 포인트","input() 함수는 사용자의 입력을 항상 문자열 형태로 반환하므로, 숫자 계산이 필요한 경우 int() 또는 float()로 반드시 형 변환을 해주어야 한다. 이 변환을 누락하면 문자열과 숫자를 함께 연산하려다 TypeError가 발생하는 것이 Python 실기 시험에서 매우 흔한 오류이다."],["설명","산술 연산자와 나눗셈\nprint(7 / 2)       # 3.5 (실수 나눗셈)\nprint(7 // 2)      # 3    (몫, 정수 나눗셈)\nprint(7 % 2)       # 1    (나머지)\nprint(2 ** 3)      # 8    (거듭제곱)\nPython에서 / 연산자는 항상 실수(float) 결과를 반환하며, 정수 몫만 필요할 때는 // 연산자를 사용해야 한다. C언어나 Java의 정수 나눗셈 방식(자동으로 소수점 버림)에 익숙하다면 Python의 /가 실수를 반환한다는 차이를 반드시 구분해서 기억해야 한다. num = input(\"숫자를 입력하세요: \")\nprint(type(num))     # <class 'str'>"]]},{"t":"② f-string 포맷팅","n":[["시험 포인트","f-string은 문자열 앞에 f를 붙이고 중괄호 안에 변수를 직접 넣어 값을 삽입할 수 있는 최신 포맷팅 방식으로, 가독성이 좋고 실기 시험에서도 자주 활용된다. 중괄호 안에 변수명을 정확히 기입하지 않으면 NameError가 발생하므로 변수명의 오타에 주의해야 한다.\nprint(\"{}의 점수는 {}점\".format(name, score))\nprint(\"%s의 점수는 %d점\" % (name, score))"],["시험 포인트","format() 메소드는 중괄호 자리에 순서대로 값을 채워 넣는 방식이며, %d와 %s를 사용하는 방식은 C언어의 printf 방식과 유사하다. 세 가지 포맷팅 방식 모두 실기 시험에서 등장할 수 있으므로 최소한 f-string 방식은 능숙하게 다룰 수 있도록 연습해야 한다."],["설명","f-string을 이용한 포맷팅 name = \"Kim\" score = 90\nprint(f\"{name}의 점수는 {score}점입니다\")"]]}]}]}]},{"t":"Ⅱ 제어문과 함수","c":[{"t":"1. 조건문과 반복문","c":[{"t":"(1) 조건문 구현","c":[{"t":"① if-elif-else 콜론(:) 필수","n":[["설명","if-elif-else 구문 score = 85 if score >= 90:\nprint(\"A\")\nelif score >= 80:\nprint(\"B\")\nelse:\nprint(\"C\")\nPython의 조건문은 else if 대신 elif라는 키워드를 사용하며, 조건식 뒤에는 반드시 콜론(:)을 붙여야 한다. 콜론을 빠뜨리면 SyntaxError가 발생하므로, 조건문과 반복문을 작성할 때마다 콜론의 존재 여부를 습관적으로 확인해야 한다. score = 85 if score >= 90:\n  print(\"A\")\nprint(\"우수\")      # 오류: 들여쓰기 칸 수 불일치\n같은 블록 내부의 코드는 들여쓰기 칸 수가 정확히 일치해야 하는데, 위 코드는 print(\"A\")와 print(\"우수\")의 들여쓰기 칸 수가 달라 IndentationError가 발생한다. 에디터의 탭과 스페이스가 혼용되는 경우에도 이러한 오류가 발생할 수 있으므로, 하나의 파일 내에서는 들여쓰기 방식을 통일해야 한다."]]},{"t":"② range(1, 11) 합계 55","n":[["시험 포인트","range(1, 11)은 1부터 10까지의 숫자를 생성하며, 11은 포함되지 않는다는 점이 실기 시험에서 자주 혼동되는 부분이다. range(n)은 0부터 n-1까지, range(a, b)는 a부터 b-1까지를 의미한다는 규칙을 정확히 기억해야 한다. i = 0\nwhile i < 5:"],["시험 포인트","while문 내부에서 조건에 사용된 변수를 변화시키는 코드(i += 1)를 빠뜨리면 무한 루프에 빠지게 되며, 이는 C언어나 Java와 동일하게 나타나는 문제이다. 실기 시험 도중 프로그램이 멈추지 않는다면 반복문 내부에 조건 변수의 변화 코드가 있는지부터 확인해야 한다."],["설명","for문과 range() 함수 total = 0 for i in range(1, 11):   # 1부터 10까지 total += i\nprint(total)     # 55"]]}]},{"t":"(2) 함수의 기본 구조","c":[{"t":"① def 함수 정의·return","n":[["설명","함수 정의와 반환값\ndef add(a, b):\n    return a + b\nresult = add(3, 5)\nprint(result)      # 8\nPython에서 함수는 def 키워드로 정의하며, 매개변수의 자료형을 명시하지 않아도 된다는 점이 C언어나 Java와의 큰 차이이다. return 문이 없는 함수는 자동으로 None을 반환하므로, 반환값을 사용하는 코드에서 함수에 return 문이 빠져있지 않은지 확인해야 한다.\ndef greet(name, greeting=\"안녕하세요\"):\n    print(f\"{greeting}, {name}님\")"]]},{"t":"② *args 가변 인자 합 10","n":[["실제 사례","Python의 재귀 함수 역시 C언어와 마찬가지로 반드시 종료 조건이 있어야 하며, 종료 조건이 없거나 잘못된 경우 RecursionError(재귀 깊이 초과 오류)가 발생한다. 재귀 함수 문제에서는 종료 조건이 실제로 도달 가능한지, 그리고 매개변수가 종료 조건 방향으로 올바르게 변화하는지를 반드시 확인해야 한다."],["설명","가변 인자(*args)\ndef sum_all(*args):\n   total = 0\n   for num in args:\n       total += num\n   return total\nprint(sum_all(1, 2, 3, 4))       # 10\n*args를 매개변수로 사용하면 함수 호출 시 전달하는 인자의 개수에 상관없이 모두 튜플 형태로 받아 처리할수 있다. 정해지지 않은 개수의 값을 더하거나 처리해야 하는 문제에서 자주 활용되는 패턴이다.\ndef factorial(n):\n   if n <= 1:\n       return 1      # 종료 조건\n   return n * factorial(n - 1)\nprint(factorial(5))      # 120"]]}]}]}]},{"t":"Ⅲ 리스트와 딕셔너리","c":[{"t":"1. 리스트(List)의 활용","c":[{"t":"(1) 리스트의 기본 조작","c":[{"t":"① 리스트 인덱싱 -1·append","n":[["시험 포인트","Python 리스트는 음수 인덱스를 지원하여 -1은 마지막 원소, -2는 뒤에서 두 번째 원소를 의미한다. append()는 리스트의 끝에 원소를 추가하는 메소드로, 실기 시험에서 리스트에 값을 누적하여 추가하는 문제에 자주 활용된다. nums = [1, 2, 3, 4, 5]"],["시험 포인트","슬라이싱은 리스트의 일부분을 잘라내는 기능으로, nums[a:b]는 인덱스 a부터 b-1까지를 의미하며 b번째 인덱스는 포함되지 않는다. 이는 range() 함수와 동일한 규칙이므로, \"끝 인덱스는 포함되지 않는다\"는 Python의 일관된 규칙으로 기억해 두면 실기 시험에서 실수를 줄일 수 있다."],["설명","리스트 생성과 인덱싱 fruits = [\"apple\", \"banana\", \"cherry\"]\nprint(fruits[0])       # apple\nprint(fruits[-1])      # cherry (음수 인덱스: 마지막 원소)\nfruits.append(\"grape\")\nprint(fruits)      # ['apple', 'banana', 'cherry', 'grape']"]]},{"t":"② 리스트 컴프리헨션 제곱·짝수","n":[["시험 포인트","리스트 컴프리헨션은 반복문과 조건문을 한 줄로 축약하여 새로운 리스트를 생성하는 Python 고유의 간결한 문법이다. 대괄호 안에 [표현식 for 변수 in 반복대상 if 조건]의 순서를 정확히 기억하면 실기 시험에서 짧고 효율적인 코드를 작성할 수 있다. nums = [3, 1, 4, 1, 5]"],["시험 포인트","sort()는 리스트 자체를 직접 정렬하며 반환값이 None이므로 result = nums.sort()와 같이 사용하면 result에 None이 저장되는 오류가 발생한다. 원본을 유지하면서 정렬된 새 리스트가 필요하다면 sorted() 함수를 사용해야 하며, 이 차이를 혼동하는 것이 실기 시험의 흔한 함정이다."],["설명","리스트 컴프리헨션 squares = [x**2 for x in range(1, 6)]\nprint(squares)     # [1, 4, 9, 16, 25]\nevens = [x for x in range(1, 11) if x % 2 == 0]\nprint(evens)     # [2, 4, 6, 8, 10]"]]}]},{"t":"(2) 딕셔너리의 기본 조작","c":[{"t":"① 딕셔너리 키·값 접근·추가","n":[["설명","딕셔너리 생성과 값 접근\nstudent = {\"name\": \"Kim\", \"score\": 90}\nprint(student[\"name\"])     # Kim"]]},{"t":"② items() 키·값 튜플 순회","n":[["시험 포인트","딕셔너리를 이용해 단어나 원소의 등장 빈도수를 계산하는 문제는 실기 시험에서 매우 자주 출제되는 유형이다. count.get(word, 0) + 1과 같이 get()의 기본값 매개변수를 활용하면, 해당 단어가 처음 등장 했을 때 KeyError 없이 0에서부터 1을 더하는 코드를 간결하게 작성할 수 있다."],["설명","items()를 이용한 순회\nscores = {\"Kim\": 90, \"Lee\": 85, \"Park\": 95}\nfor name, score in scores.items():\nprint(f\"{name}: {score}점\")\nitems() 메소드는 딕셔너리의 키와 값을 튜플 형태로 반환하여, for문에서 두 개의 변수(name, score)로 동시에 받아 순회할 수 있게 해준다. 키만 필요할 때는 keys(), 값만 필요할 때는 values()를 사용한다는 것도 함께 기억해야 한다. text = \"apple banana apple cherry banana apple\" words = text.split()\ncount = {}\nfor word in words: count[word] = count.get(word, 0) + 1\nprint(count)   # {'apple': 3, 'banana': 2, 'cherry': 1}"]]}]}]}]},{"t":"Ⅳ 예외 처리와 파일 입출력","c":[{"t":"1. 예외 처리(Exception Handling)","c":[{"t":"(1) try-except 구문","c":[{"t":"① try-except ValueError 등","n":[["설명","기본 예외 처리 try: num = int(input(\"숫자 입력: \")) result = 10 / num\nprint(result)\nexcept ValueError:\nprint(\"숫자만 입력해야 합니다\")\nexcept ZeroDivisionError:\nprint(\"0으로 나눌 수 없습니다\")\nPython의 예외 처리는 try-except 구문을 사용하며, 여러 종류의 예외를 각각 다르게 처리하고 싶을 때는 except 블록을 여러 개 작성할 수 있다. 정수로 변환할 수 없는 문자열을 int()에 전달하면 ValueError가, 0으로 나누면 ZeroDivisionError가 발생한다는 점을 정확히 구분해서 기억해야 한다. try: num = int(\"10\") except ValueError:\nprint(\"변환 오류\")\nelse:\nprint(\"예외가 발생하지 않음\")           # try가 성공했을 때만 실행\nfinally:\nprint(\"항상 실행됨\")\nelse 블록은 try 블록에서 예외가 전혀 발생하지 않았을 때만 실행되며, finally 블록은 예외 발생 여부와 관계없이 항상 실행된다. 이 두 블록의 차이를 명확히 이해하면 자원 정리나 후처리 로직을 더욱 정교하게 작성할수 있다."]]},{"t":"② except as e 예외 객체","n":[["시험 포인트","except 절에서 as 키워드를 사용하면 발생한 예외 객체를 변수에 담아 구체적인 오류 메시지를 확인할 수 있다. 디버깅 시 이 오류 메시지를 출력해보면 문제의 원인을 훨씬 빠르게 파악할 수 있으므로 실기시험에서도 적극적으로 활용하는 것이 좋다.\ndef check_age(age):"],["설명","예외 객체 활용 try: result = 10 / 0 except ZeroDivisionError as e:\nprint(f\"오류 발생: {e}\")"]]}]},{"t":"(2) 파일 읽기와 쓰기","c":[{"t":"① with open 파일 자동 닫기","n":[["시험 포인트","with 문을 사용하지 않고 open()으로 직접 파일을 열었다면 반드시 작업이 끝난 뒤 close()를 호출하여 파일을 닫아야 한다. 이를 누락하면 파일이 계속 사용 중인 상태로 남아 다른 프로그램에서 해당 파일에 접근하지 못하는 문제가 발생할 수 있으므로, 실기 시험에서는 with문을 사용하는 것이 실수를 줄이는 안전한 방법이다."],["설명","with문을 이용한 파일 처리 with open(\"data.txt\", \"w\") as f: f.write(\"Hello, Python!\\n\") with open(\"data.txt\", \"r\") as f: content = f.read()\nprint(content)\nwith 문을 사용하면 파일을 열고 작업이 끝난 후 자동으로 파일을 닫아주므로, close()를 깜빡 잊어 파일이 계속 열려 있는 문제를 방지할 수 있다. \"w\"는 쓰기 모드(기존 내용 삭제 후 새로 씀), \"r\"은 읽기 모드, \"a\"는 추가 모드를 의미한다는 점을 정확히 구분해야 한다. f = open(\"data.txt\", \"r\") content = f.read()\nprint(content)\n# f.close()   누락 시 파일이 계속 열린 상태로 남음(자원 누수)"]]},{"t":"② FileNotFoundError 없는 파일","n":[["시험 포인트","존재하지 않는 파일을 읽기 모드로 열려고 하면 FileNotFoundError가 발생한다. 실기 시험에서는 문제에서 제공한 파일의 경로와 이름을 정확히 확인하고, 상대 경로와 절대 경로 중 어떤 방식으로 접근해야 하는지도 함께 점검해야 한다. with open(\"data.txt\", \"r\") as f:"],["설명","FileNotFoundError"]]}]}]}]},{"t":"Ⅴ Python 실전 예제 모음","c":[{"t":"1. 문자열과 리스트 실전 예제","c":[{"t":"(1) 문자열 처리 실전 예제","c":[{"t":"① [::-1] 반전·회문 검사","n":[["시험 포인트","split()은 문자열을 리스트로 분리하고, join()은 반대로 리스트를 특정 구분자로 연결하여 하나의 문자열로 만든다. join()은 \"구분자\".join(리스트) 형태로 구분자 문자열 뒤에 점(.)을 찍고 호출한다는 점이 다른 언어와 형태가 달라 실기 시험에서 자주 혼동되는 부분이다."],["설명","문자열 반전과 회문 검사 str1 = \"hello\"\nprint(str1[::-1])    # olleh (슬라이싱으로 반전)\ndef is_palindrome(s):\n    return s == s[::-1]\nprint(is_palindrome(\"level\"))      # True\nPython은 슬라이싱 문법 [::-1]을 이용하면 별도의 반복문 없이 문자열이나 리스트를 손쉽게 반전시킬 수 있다. 회문 검사는 원본 문자열과 반전시킨 문자열이 동일한지 비교하는 것만으로 간단히 구현할 수 있다는 점이 Python의 큰 장점이다."]]},{"t":"② max·min·sorted 리스트 처리","n":[["시험 포인트","Python은 max(), min(), sorted()와 같은 내장 함수를 통해 최대값, 최소값, 정렬을 매우 간단하게 처리할 수 있다. sorted() 함수에 reverse=True 옵션을 추가하면 내림차순으로 정렬할 수 있다는 점을 기억해 두면 실기 시험에서 정렬 관련 문제를 빠르게 해결할 수 있다. nums = [1, 2, 2, 3, 3, 3, 4] unique = list(set(nums))"],["설명","리스트에서 최대값/최소값과 정렬 nums = [23, 7, 45, 12, 8]\nprint(max(nums))     # 45\nprint(min(nums))     # 7\nprint(sorted(nums))                 # [7, 8, 12, 23, 45]\nprint(sorted(nums, reverse=True))       # [45, 23, 12, 8, 7]"]]}]},{"t":"(2) 딕셔너리를 활용한 데이터 처리","c":[{"t":"① items() 값 기준 내림차순 정렬","n":[["시험 포인트","딕셔너리를 값(value) 기준으로 정렬하려면 items()로 (키, 값) 쌍을 튜플로 변환한 뒤, sorted()의 key 매개변수에 lambda x: x[1]과 같이 정렬 기준을 지정해야 한다. 이 패턴은 실기 시험에서 학생들의 점수를 순위별로 출력하는 문제에 매우 자주 활용된다. nums = [1, 3, 2, 3, 3, 1]\ncount = {}\nfor n in nums:"],["설명","딕셔너리 값 기준 정렬\nscores = {\"Kim\": 90, \"Lee\": 85, \"Park\": 95}\nsorted_scores = sorted(scores.items(), key=lambda x: x[1], reverse=True) for name, score in sorted_scores:\nprint(f\"{name}: {score}\")\n# Park: 95, Kim: 90, Lee: 85"]]},{"t":"② lambda·map 익명 함수","n":[["시험 포인트","filter() 함수는 리스트의 각 원소에 조건 함수를 적용하여, 그 결과가 참(True)인 원소만 걸러내어 새로운 리스트로 만들어준다. 리스트 컴프리헨션(evens = [x for x in nums if x % 2 == 0])으로도 동일한 결과를 얻을 수 있으므로, 두 가지 방식을 모두 알아두면 실기 시험에서 상황에 맞게 선택하여 활용할 수 있다."],["설명","lambda(람다) 함수 add = lambda a, b: a + b\nprint(add(3, 5))     # 8\nnums = [1, 2, 3, 4, 5] squared = list(map(lambda x: x ** 2, nums))\nprint(squared)     # [1, 4, 9, 16, 25]\n람다식은 이름이 없는 익명 함수를 한 줄로 간결하게 정의하는 문법으로, def를 사용한 일반 함수 정의를 짧게 축약한 형태이다. map() 함수와 결합하여 리스트의 모든 원소에 동일한 연산을 적용할 때 매우 자주 활용된다. nums = [1, 2, 3, 4, 5, 6, 7, 8] evens = list(filter(lambda x: x % 2 == 0, nums))\nprint(evens)     # [2, 4, 6, 8]"]]}]}]}]},{"t":"Ⅵ Python 실전 디버깅 문제 모음","c":[{"t":"1. 문제 유형 1: 코드 빈칸 채우기","c":[{"t":"(1) 반복문과 조건문 빈칸 채우기","c":[{"t":"① 소수 판별 is_prime = False","n":[["설명","문제: 1~20 사이의 소수(prime) 출력하기 for num in range(2, 21): is_prime = True for i in range(2, num): if num % i == 0: ___빈칸___ if is_prime:\nprint(num, end=\" \")\n# 출력: 2 3 5 7 11 13 17 19 빈칸에는 num이 i로 나누어 떨어질 때 소수가 아님을 표시하는 is_prime = False가 들어가야 한다. 소수 판별 문제는 어떤 수를 2부터 자기 자신 이전까지의 수로 나누어 떨어지는 경우가 하나라도 있으면 소수가 아니라는 원리를 코드로 정확히 구현할 수 있는지를 확인하는 대표적인 유형이다. for num in range(2, 21): is_prime = True for i in range(2, num): if num % i == 0:"]]},{"t":"② 짝수 필터 n % 2 == 0","n":[["시험 포인트","빈칸에는 n이 짝수인지 판별하는 조건 n % 2 == 0이 들어가야 한다. 이 문제는 리스트 컴프리헨 션([n for n in numbers if n % 2 == 0])으로도 동일하게 구현할 수 있으므로, 두 가지 방식을 모두 알아두면 실기 시험에서 유연하게 대응할 수 있다.\ndef filter_even(numbers):"],["설명","문제: 리스트에서 짝수만 걸러내는 함수\ndef filter_even(numbers):\n   result = []\n   for n in numbers:\n       if ___빈칸___:\n           result.append(n)\n   return result\nprint(filter_even([1, 2, 3, 4, 5, 6]))      # [2, 4, 6]"]]}]},{"t":"(2) 문법 오류 찾기 문제","c":[{"t":"① def 콜론(:) 누락 오류","n":[["시험 포인트","함수 정의 def calculate_average(scores) 뒤에 콜론(:)이 누락되어 SyntaxError가 발생한다. Python은 함수, 조건문, 반복문, 클래스 정의 등 블록을 시작하는 모든 구문 뒤에 반드시 콜론을 붙여야 한다는 규칙을 놓치기 쉬우므로 주의해야 한다."],["설명","문제: 다음 코드의 오류를 찾아 수정하시오\ndef calculate_average(scores)\n   total = sum(scores)\n   average = total / len(scores)\n   return average\nscores = [90, 85, 95, 80]\nprint(calculate_average(scores))"]]},{"t":"② 0 나눗셈 ZeroDivision Error","n":[["시험 포인트","divisors 리스트의 두 번째 값이 0이므로, 두 번째 반복에서 divide(20, 0)이 호출되어 ZeroDivisionError가 발생한다. 실기 시험에서 리스트의 값을 미리 확인하지 않고 코드만 보면 이러한 오류를 놓치기 쉬우므로, 반복문에 사용되는 데이터 값 자체도 함께 검토하는 습관이 중요하다.\ndef divide(a, b):"],["시험 포인트","try-except 구문으로 0으로 나누는 예외 상황을 처리하면 프로그램이 중단되지 않고 계속 실행될 수 있다. 실기 시험에서 예외 처리 문제는 단순히 오류를 방지하는 것을 넘어, 문제에서 요구하는 정확한 대체 값이나 메시지를 출력하도록 구현하는 것까지 요구하므로 문제 요구사항을 꼼꼼히 확인해야 한다."],["설명","문제: 다음 코드가 실행되지 않고 오류가 발생하는 이유를 설명하시오\ndef divide(a, b):\n   return a / b\nnumbers = [10, 20, 30] divisors = [2, 0, 5] for i in range(len(numbers)):\nprint(divide(numbers[i], divisors[i]))"]]}]}]}]},{"t":"Ⅶ Python 실전 디버깅 문제 심화","c":[{"t":"1. 딕셔너리와 함수 디버깅 문제","c":[{"t":"(1) 딕셔너리 접근 오류 찾기","c":[{"t":"① 없는 키 KeyError·get( )","n":[["시험 포인트","get() 메소드에 기본값을 지정하거나, in 연산자로 키의 존재 여부를 먼저 확인한 후 접근하는 두가지 방법 모두 KeyError를 방지하는 안전한 코드 작성법이다. 실기 시험에서 문제의 요구사항에 따라 어떤 방식이 더 적합한지 판단하여 사용해야 한다."],["설명","문제: 다음 코드에서 예외가 발생하는 이유를 설명하시오\nscores = {\"Kim\": 90, \"Lee\": 85}\nprint(scores[\"Park\"])    # 오류 발생\n딕셔너리에 존재하지 않는 키(\"Park\")를 대괄호로 직접 조회하면 KeyError가 발생한다. 딕셔너리에 특정 키가 반드시 존재한다는 확신이 없다면, 안전하게 조회할 수 있는 get() 메소드를 사용하는 것이 바람직하다.\nscores = {\"Kim\": 90, \"Lee\": 85}\nprint(scores.get(\"Park\"))            # None\nprint(scores.get(\"Park\", 0))         # 0 (기본값 지정)"]]},{"t":"② 가변 기본값 인자 [] 누적","n":[["시험 포인트","가변 자료형(리스트, 딕셔너리 등)을 함수의 기본값으로 사용할 때는 None을 기본값으로 지정한후, 함수 내부에서 None인지 확인하여 새로운 객체를 생성하는 패턴을 사용해야 한다. 이는 Python의 잘 알려진 함정이므로 실기 시험에서 함수 관련 문제를 풀 때 특히 주의해야 한다."],["설명","문제: 다음 코드가 예상과 다르게 동작하는 이유를 설명하시오\ndef add_item(item, item_list=[]):\n   item_list.append(item)\n   return item_list\nprint(add_item(\"a\"))    # ['a']\nprint(add_item(\"b\"))    # ['a', 'b'] (예상: ['b'])\nPython에서 함수의 기본값 매개변수(item_list=[])는 함수가 처음 정의될 때 단 한 번만 생성되며, 이후 호출마다 재사용된다. 따라서 이전 호출에서 추가된 값이 계속 누적되는, 초보자가 자주 놓치는 대표적인 함정이다.\ndef add_item(item, item_list=None):\n   if item_list is None:"]]}]},{"t":"(2) 리스트 인덱스 오류 찾기","c":[{"t":"① range(len+1) IndexError","n":[["설명","문제: 다음 코드에서 예외가 발생하는 이유를 설명하시오 scores = [90, 85, 95] for i in range(len(scores) + 1):\nprint(scores[i])     # 오류 발생\nrange(len(scores) + 1)은 0부터 3까지의 범위를 생성하는데, scores 리스트의 유효 인덱스는 0~2까지이므로 i가 3이 되는 마지막 반복에서 scores[3]에 접근하여 IndexError가 발생한다. range()에 +1을 실수로 추가하는 것은 매우 흔한 경계값 오류이다. scores = [90, 85, 95]"]]},{"t":"② range(1, 9) 끝값 9 누락","n":[["시험 포인트","range(1, 10)으로 수정하면 1부터 9까지 정확히 순회하여 2단과 3단의 구구단 결과가 모두 올바르게 출력된다. 실기 시험에서 range()의 끝 값 설정은 가장 자주 실수하는 부분이므로, 코드 작성 후 반드시 첫값과 마지막 값이 요구사항과 일치하는지 검산해야 한다."],["설명","문제: 다음 구구단 출력 코드의 오류를 찾아 수정하시오 for i in range(2, 4):"]]}]}]}]},{"t":"Ⅷ 실전 디버깅 종합 점검표","c":[{"t":"1. 언어 공통 디버깅 체크리스트","c":[{"t":"(1) 제출 전 최종 점검 항목","c":[{"t":"① 문법·자료형 최종 점검","n":[["실제 사례","코드를 제출하기 전에는 세미콜론(C, Java)과 콜론(Python)의 누락 여부, 괄호와 중괄호의 짝, 변수 선언과 자료형의 일치 여부, 함수의 반환형과 실제 반환값의 일치 여부를 순서대로 점검해야 한다. 이 네 가지는 세 언어 모두에서 공통적으로 발생하는 가장 기초적인 오류 유형이다."],["시험 포인트","조건문에서 대입 연산자(=)와 비교 연산자(==, C/Java 기준)를 혼동하지 않았는지, 반복문의 시작과 끝 경계값이 요구사항과 정확히 일치하는지, 반복문 내부에 조건 변수를 변화시키는 코드가 누락되어 무한 루프에 빠지지 않는지를 점검해야 한다."],["설명","문법과 자료형 점검"]]},{"t":"② 인덱스 범위 최종 점검","n":[["시험 포인트","배열이나 리스트의 인덱스가 유효 범위(0부터 길이-1까지)를 벗어나지 않는지 반드시 확인해야한다. C언어는 이러한 오류를 컴파일 시점에 잡아주지 않으므로 특히 더 주의해야 하며, Java와 Python은 실행 시 명확한 예외(ArrayIndexOutOfBoundsException, IndexError)를 발생시켜 알려준다는 언어별 차이도 함께 기억해야 한다."],["설명","배열/리스트 인덱스 점검"]]}]},{"t":"(2) 문제 접근 순서","c":[{"t":"① 요구사항 입출력 형식 파악","n":[["설명","요구사항 정확히 파악하기 코드를 작성하기 전에 문제에서 요구하는 입력값, 처리 과정, 출력 형식을 먼저 정확히 읽고 이해해야 한다. 출력 형식이 조금이라도 다르면(예: 공백 하나, 소수점 자릿수) 오답으로 처리될 수 있으므로 예시 입출력을 꼼꼼히 대조해야 한다. 복잡한 문제일수록 전체 로직을 한 번에 작성하기보다, 작은 단위로 나누어 구현하고 각 단계마다 출력문 (printf, System.out.println, print)으로 중간 결과를 확인하며 진행하는 것이 오류를 줄이는 효과적인 전략이다."]]},{"t":"② 막히면 표시 후 다음 문제","n":[["시험 포인트","특정 문제에서 막혔을 때 너무 오랜 시간을 소비하지 말고, 일단 현재까지의 진행 상황을 저장해둔 뒤 다른 문제로 넘어가고 나중에 다시 돌아오는 시간 관리 전략이 실기 시험에서 매우 중요하다."],["설명","막히는 문제는 표시 후 다음으로"]]}]}]}]},{"t":"Ⅸ 세 언어 비교와 전환 시 주의사항","c":[{"t":"1. 문법 요소별 비교","c":[{"t":"(1) 변수 선언과 조건문 비교","c":[{"t":"① 정적 타입 vs 동적 타이핑","n":[["시험 포인트","C언어와 Java는 중괄호({})로 코드 블록을 구분하고 세미콜론으로 각 문장을 끝내지만, Python은 콜론(:)과 들여쓰기로 블록을 구분하며 세미콜론이 필요 없다. 세 언어를 번갈아 가며 학습할 때 이러한 블록 구분 방식의 차이로 인한 문법 오류가 가장 빈번하게 발생하므로 특히 주의해야 한다."],["설명","변수 선언 방식의 차이 C언어는 int, double과 같이 자료형을 반드시 명시하여 변수를 선언해야 하며, Java도 마찬가지로 정적 타입을 사용하지만 String과 같은 참조 자료형이 추가로 존재한다. 반면 Python은 변수 선언 시 자료형을 명시하지 않는 동적 타이핑 언어로, 하나의 변수에 다른 자료형의 값을 자유롭게 재할당할 수 있다는 근본적인 차이가 있다."]]},{"t":"② 배열 고정 크기 vs 리스트 가변","n":[["설명","배열과 리스트의 차이 C언어의 배열은 크기가 고정되어 있고 선언 시 지정한 자료형의 값만 저장할 수 있는 반면, Java의 배열도 크기가 고정되지만 ArrayList와 같은 컬렉션을 사용하면 크기를 유동적으로 조절할 수 있다. Python의 리스트는 처음부터 크기가 자유롭고 서로 다른 자료형의 값을 함께 담을 수 있어 가장 유연하다는 차이가 있다. C언어와 Java는 함수(메소드)의 반환형과 매개변수의 자료형을 반드시 명시해야 하지만, Python은 def 키워드만으로 자료형 명시 없이 함수를 정의할 수 있다는 차이가 있다. 이 차이로 인해 Python 함수는 더 간결하게 작성할 수 있지만, 매개변수에 어떤 자료형이 전달될지 코드만으로는 파악하기 어려울 수 있다는 점도 함께 알아두어야 한다."]]}]},{"t":"(2) C/Java에서 Python으로 전환 시 실수","c":[{"t":"① Python에 세미콜론·중괄호 습관","n":[["시험 포인트","C나 Java에 익숙한 학습자가 Python 코드를 작성할 때, 습관적으로 문장 끝에 세미콜론을 붙이 거나 블록을 중괄호로 감싸려는 실수를 하는 경우가 많다. Python에서는 세미콜론이 있어도 문법 오류는 아니지만 불필요하며, 중괄호는 아예 다른 의미(딕셔너리, 집합)로 사용되므로 혼동해서는 안 된다."],["설명","세미콜론과 중괄호를 습관적으로 사용"]]},{"t":"② 중괄호 누락 시 한 줄만 적용","n":[["설명","들여쓰기만으로 블록이 구분된다고 착각 Python에 익숙한 학습자가 C나 Java 코드를 작성할 때 들여쓰기만 맞추고 중괄호를 빠뜨리는 실수를 하는 경우가 있다. C와 Java에서는 들여쓰기가 보기 좋게 되어 있어도 중괄호가 없다면 반복문이나 조건문이 단한 줄의 문장에만 적용된다는 점을 명확히 이해해야 한다. Python 스타일에 익숙해지면 C나 Java에서도 변수의 자료형을 선언하지 않고 사용하려는 실수를 할 수 있는데, 이는 두 언어에서 반드시 컴파일 오류로 이어진다. 세 언어를 함께 학습할 때는 지금 작성하는 코드가 어떤 언어인지 항상 의식하면서 그 언어의 문법 규칙을 정확히 따르는 습관이 중요하다."]]}]}]}]},{"t":"Ⅹ 실전 대비 마무리 점검","c":[{"t":"1. 자주 틀리는 문제 유형 재정리","c":[{"t":"(1) 경계값과 자료형 관련 실수","c":[{"t":"① 경계값 등호 <= vs < 구분","n":[["설명","경계값 오류의 재확인 반복문의 시작과 끝 조건에서 등호(<=, <, >=, >)를 정확히 구분하지 않으면 배열의 마지막 원소가 누락되거나 범위를 초과하는 오류로 이어진다. 문제에서 요구하는 반복 횟수를 직접 계산해 보고, 작성한 코드의 반복 조건이 그 횟수와 정확히 일치하는지 항상 검산하는 습관을 들여야 한다. 문자열과 숫자 간의 형 변환이 필요한 상황(Python의 input(), Java의 Scanner로 받은 값 계산 등)에서 변환을 누락하면 오류가 발생하거나 예상과 다른 결과가 나온다. 입력을 받는 코드를 작성할 때마다 그 값을 어떤 용도로 사용할 것인지 미리 생각하고 필요한 형 변환을 빠뜨리지 않아야 한다."]]},{"t":"② 제출 전 컴파일·예시 출력 대조","n":[["시험 포인트","작업형 시험은 실제 개발 환경에서 코드를 작성하므로 익숙하지 않은 IDE 사용법 때문에 당황할수 있다. 시험 전에 미리 사용할 IDE(VS Code, 이클립스 등)의 실행, 저장, 디버깅 단축키를 충분히 연습해 두면 실제 시험에서 도구 사용 미숙으로 인한 시간 낭비를 줄이고 문제 해결 자체에 더 집중할 수 있다."],["설명","코드 제출 전 최종 확인 코드를 제출하기 전에는 반드시 컴파일(빌드)을 한 번 더 실행하여 오류가 없는지 확인하고, 문제에서 제시한 예시 입력값을 직접 넣어 실행 결과가 예시 출력값과 정확히 일치하는지 재확인해야 한다. 공백이나 줄바꿈과 같은 사소한 형식 차이도 채점에 영향을 줄 수 있으므로 세심하게 비교해야 한다."]]}]}]}]}]}],"k":"실기 디버깅"}];
